def administration(payload, refused=None):
    """One local administration exchange. It must succeed, or, when refused
    names an error code, it must refuse with exactly that code."""
    completed = subprocess.run([str(runner), "--manager", "admin", "--config", str(config)],
                               input=json.dumps(payload).encode(), stdout=subprocess.PIPE,
                               stderr=subprocess.PIPE, timeout=20)
    value = frozen.parse_json(completed.stdout)
    validate("LocalAdminResponse", value)
    if refused is not None:
        assert not completed.stderr and completed.returncode == 1 and not value["ok"] and value["error"]["code"] == refused, (
            "local administration did not refuse as expected", completed.returncode, value.get("error", {}).get("code"))
        return value
    assert not completed.stderr and completed.returncode == 0 and value["ok"], (
        "local administration refused", completed.returncode, value.get("error", {}).get("code"))
    return value


class DelayForwarder:
    """A TCP forwarder from its listening socket to the manager port. It
    passes the bytes of each connection through unchanged in both
    directions, so TLS runs end to end. While the delay window is open, each
    chunk from the manager is sent to the client the given delay after it
    arrived, and the chunks of one connection keep their order. A connection
    that the client closes is closed at the manager too, and its chunks that
    are not yet sent are dropped. chunks records the connection number,
    arrival time, due time and size of each chunk from the manager."""

    def __init__(self, listener, upstream_port, delay):
        self.listener, self.upstream_port, self.delay = listener, upstream_port, delay
        self.lock = threading.Lock()
        self.window_end = 0.0
        self.chunks = []
        self.dropped = 0
        self.connections = 0
        threading.Thread(target=self.accept, daemon=True).start()

    def open_window(self, seconds):
        """Delay each chunk from the manager that arrives in the next seconds."""
        with self.lock:
            self.window_end = time.monotonic() + seconds

    def pending_at(self, moment):
        """The chunks that arrived before the moment and were due after it."""
        with self.lock:
            return [chunk for chunk in self.chunks if chunk[1] <= moment < chunk[2]]

    def accept(self):
        while True:
            try:
                client, _ = self.listener.accept()
            except OSError:
                return
            with self.lock:
                self.connections += 1
                number = self.connections
            try:
                upstream = socket.create_connection(("127.0.0.1", self.upstream_port), timeout=10)
            except OSError:
                client.close()
                continue
            upstream.settimeout(None)
            closed = threading.Event()
            queued = []
            ready = threading.Condition()
            threading.Thread(target=self.client_to_manager, args=(client, upstream, closed, ready), daemon=True).start()
            threading.Thread(target=self.manager_to_queue, args=(number, upstream, queued, ready, closed), daemon=True).start()
            threading.Thread(target=self.queue_to_client, args=(client, queued, ready, closed), daemon=True).start()

    def client_to_manager(self, client, upstream, closed, ready):
        try:
            while data := client.recv(65536):
                upstream.sendall(data)
        except OSError:
            pass
        closed.set()
        for end in (upstream, client):
            with contextlib.suppress(OSError):
                end.shutdown(socket.SHUT_RDWR)
        with ready:
            ready.notify_all()

    def manager_to_queue(self, number, upstream, queued, ready, closed):
        while True:
            try:
                data = upstream.recv(65536)
            except OSError:
                data = b""
            now = time.monotonic()
            with self.lock:
                due = now + self.delay if now < self.window_end else now
                if data:
                    self.chunks.append((number, now, due, len(data)))
            with ready:
                queued.append((due, data))
                ready.notify_all()
            if not data:
                return

    def queue_to_client(self, client, queued, ready, closed):
        while True:
            with ready:
                while not queued and not closed.is_set():
                    ready.wait()
                if closed.is_set():
                    with self.lock:
                        self.dropped += sum(1 for _, data in queued if data)
                    queued.clear()
                    client.close()
                    return
                due, data = queued.pop(0)
            delay = due - time.monotonic()
            if delay > 0:
                closed.wait(delay)
            if closed.is_set():
                with self.lock:
                    self.dropped += 1 if data else 0
                continue
            if not data:
                with contextlib.suppress(OSError):
                    client.shutdown(socket.SHUT_WR)
                return
            try:
                client.sendall(data)
            except OSError:
                closed.set()


class TuiModeFixture:
    """The shared fixture of the TUI modes. It writes the manager
    configuration with the profiles that the mode names. It issues one
    credential for the client profile of the TUI and a separate credential
    for the harness through local administration, so that the requests of the
    harness spend nothing of the per-client bounds of the TUI credential
    (sseReadersPerClient 2 and ordinaryMutationsPerMinute 30). The pi-client
    mode names its client credential pi instead of tui, and the emacs-client
    mode names it emacs. session()
    starts the TUI through TuiSession, at 80x24 by default. credential_ids
    holds the credential identifier of each issued credential, client_ids
    holds its client identifier, and renew() issues a new TUI credential
    with its own client profile."""

    def __init__(self, profiles, scopes, client="tui"):
        configuration["profiles"] = [profile for profile in configuration["profiles"] if profile["id"] in profiles]
        assert [profile["id"] for profile in configuration["profiles"]] == profiles, ("unknown TUI mode profile", profiles)
        config.write_text(json.dumps(configuration))
        self.profiles, self.scopes = profiles, scopes
        harness_scopes = ["observe", "submit", "control"] + (["export"] if "export" in scopes else [])
        self.credential_ids, self.client_ids = {}, {}
        for name, granted in ((client, scopes), ("harness", harness_scopes)):
            self.issue(name, granted)
        self.harness = {"Authorization": "Bearer " + (work / "credential-harness").read_bytes().decode("ascii")}
        self.client_profile = self.write_profile(client)
        self.client_state = work / "unused-client-state"

    def issue(self, name, granted):
        """Issue one credential through local administration into
        credential-NAME and record its credential and client identifiers."""
        issued = administration({"version": 1, "operation": "issue-credential", "label": "TUI mode " + name,
                                 "scopes": granted, "profileIds": self.profiles,
                                 "expiresAt": "2999-01-01T00:00:00Z", "outputFile": str(work / ("credential-" + name))})
        self.credential_ids[name] = issued["result"]["credential"]["credentialId"]
        self.client_ids[name] = issued["result"]["credential"]["clientId"]

    def write_profile(self, name):
        """The client profile of the credential credential-NAME."""
        profile = work / ("client-profile-" + name + ".json")
        profile.write_text(json.dumps({"version": 1, "endpoint": f"https://127.0.0.1:{port}/v1",
                                       "credentialFile": str(work / ("credential-" + name)), "caFile": str(cert)}))
        profile.chmod(0o600)
        return profile

    def renew(self, name):
        """Issue a new TUI credential with the scopes of the mode as
        credential-NAME, and return its client profile."""
        self.issue(name, self.scopes)
        return self.write_profile(name)

    def session(self, rows=24, columns=80, client_profile=None, client_profiles=None):
        """The service TUI of the TUI credential, or of the given client
        profile, or of the given client profiles in that order, in a new
        pseudo-terminal."""
        from tui_probe import TuiSession
        profiles = client_profiles or [client_profile or self.client_profile]
        command = [os.environ["TUI_CHECK"], "--tui", "--service"] + [str(path) for path in profiles] + ["+RTS", "-N" + native, "-RTS"]
        return TuiSession(runner, self.client_state, rows=rows, columns=columns, command=command, explicit_state=False)


def client_controls_fixture(client):
    """The credentials of a client-controls mode. The module configures the
    profiles of CLIENT_CONTROLS_PROFILES for the mode, each with its own
    resource key, and two execution reservations. This issues the client
    credential credential-CLIENT with observe, submit and control for those
    profiles, and the credential of the harness, through TuiModeFixture,
    whose client_profile names the client credential."""
    return TuiModeFixture(CLIENT_CONTROLS_PROFILES[sys.argv[5]], CLIENT_CONTROLS_SCOPES, client=client)


class CrossClientFixture(TuiModeFixture):
    """The fixture of the cross-client witness modes. Through
    TuiModeFixture.issue it issues the client credentials tui, emacs and
    pi, each with observe, submit, control and export on profile_1 and
    profile_2, and the credential of the harness. Each client credential
    has its own client profile in client_profiles, so the three clients
    have distinct client identifiers. client_profile and session() are
    those of the tui credential."""

    CLIENTS = ("tui", "emacs", "pi")

    def __init__(self):
        super().__init__(["profile_1", "profile_2"], ["observe", "submit", "control", "export"], client="tui")
        for name in self.CLIENTS[1:]:
            self.issue(name, self.scopes)
        self.client_profiles = {name: self.client_profile if name == "tui" else self.write_profile(name) for name in self.CLIENTS}
        assert len({self.client_ids[name] for name in self.CLIENTS + ("harness",)}) == 4, (
            "the witness credentials share a client identifier", self.client_ids)


class CapacityFixture(TuiModeFixture):
    """The fixture of the capacity-admission mode. Before the manager starts,
    TuiModeFixture issues the credential r1-1 and the credential harness
    with observe, submit and control on CAPACITY_PROFILES into the manager
    root of the module, which the first lifetime uses. begin() writes the
    configuration of one lifetime with the given manager root, profiles and
    limits, and issue_all() then issues the other credentials of that
    lifetime through the live administration channel with
    TuiModeFixture.issue. installed keeps every capacity and cohort profile,
    because TuiModeFixture keeps only CAPACITY_PROFILES in the first
    configuration."""

    def __init__(self):
        self.installed = list(configuration["profiles"])
        super().__init__(CAPACITY_PROFILES, ["observe", "submit", "control"], client="r1-1")
        self.base_limits = dict(configuration["limits"])

    def begin(self, root, profiles, limits):
        """Write the configuration of one lifetime. A root other than the
        manager root of the module is created empty."""
        if root != work / "manager":
            root.mkdir(mode=0o700)
        self.profiles = profiles
        configuration.update(managerRoot=str(root), profiles=[profile for profile in self.installed if profile["id"] in profiles],
                             limits=dict(self.base_limits, **limits))
        config.write_text(json.dumps(configuration))

    def issue_all(self, names):
        """Issue each named credential that does not exist yet."""
        for name in names:
            if name not in self.credential_ids:
                self.issue(name, self.scopes)


