# True while a TUI session is open. During the session every mutation belongs
# to the TUI, and the harness only reads. The journey sets it for the whole
# run after fixture setup and credential issuance.
posts_forbidden = journey
if journey:
    print("JOURNEY POST GUARD active: any harness POST through exchange after fixture setup and credential issuance fails", flush=True)


@contextlib.contextmanager
def harness_reads_only():
    """Forbid harness POSTs until the TUI session inside this block has ended."""
    global posts_forbidden
    previous, posts_forbidden = posts_forbidden, True
    try:
        yield
    finally:
        posts_forbidden = previous


@contextlib.contextmanager
def harness_acts():
    """Allow harness POSTs inside this block, for an action of the harness
    that a client check asks for during the check."""
    global posts_forbidden
    previous, posts_forbidden = posts_forbidden, False
    try:
        yield
    finally:
        posts_forbidden = previous


class PersistentConnection:
    """One TLS connection that a credential keeps for its requests. exchange
    sends a request on it and leaves it open. Before a request, ready()
    opens a new connection when the connection has been idle for IDLE
    seconds, before the 15-second connection timeout of the server closes
    it, or when the server has sent bytes or closed it while it was idle.
    elapsed holds the milliseconds of the last exchange, from the write of
    the request to the read of the complete response body. A failed
    exchange closes the connection, and nothing sends its request again."""

    IDLE = 10.0

    def __init__(self):
        self.connection, self.used, self.elapsed, self.opened = None, 0.0, None, 0

    def ready(self):
        if self.connection is not None and (time.monotonic() - self.used > self.IDLE
                                            or select.select([self.connection.sock], [], [], 0)[0]):
            self.close()
        if self.connection is None:
            self.connection = http.client.HTTPSConnection("127.0.0.1", port, context=context, timeout=7)
            self.connection.connect()
            self.opened += 1
        return self.connection

    def done(self, started):
        self.used = time.monotonic()
        self.elapsed = (self.used - started) * 1000

    def close(self):
        if self.connection is not None:
            self.connection.close()
            self.connection = None


def exchange(path, headers=None, method="GET", payload=None, persistent=None):
    """One request and its complete response. With persistent, the request
    uses that PersistentConnection and leaves it open. Otherwise it uses a
    new connection and closes it."""
    assert not (posts_forbidden and method == "POST"), "harness POST while the POST guard is active"
    connection = persistent.ready() if persistent else http.client.HTTPSConnection("127.0.0.1", port, context=context, timeout=7)
    try:
        started = time.monotonic()
        connection.request(method, path, body=payload, headers=headers or {})
        response = connection.getresponse()
        body = response.read(1048577)
        if persistent:
            persistent.done(started)
        assert len(body) <= 1048576
        assert response.getheader("Cache-Control") == "no-store"
        assert response.getheader("X-Content-Type-Options") == "nosniff"
        value = frozen.parse_json(body)
        if response.status >= 400:
            validate("Problem", value)
        elif method == "POST":
            assert response.getheader("Location") == value["links"]["self"]
        return response.status, value, body, dict((name.lower(), value) for name, value in response.getheaders())
    except BaseException:
        if persistent:
            persistent.close()
        raise
    finally:
        if not persistent:
            connection.close()


def request(path, headers=None, method="GET", payload=None):
    return fetch(path, headers, method, payload)[:3]


def fetch(path, headers=None, method="GET", payload=None):
    deadline = time.monotonic() + 5
    # A JSON read may meet the declared page-set refusal while the TUI holds
    # the page-set capacity. A stream registration keeps its own 429 handling.
    page_set_read = (headers or {}).get("Accept") != "text/event-stream"
    while True:
        status, value, raw, received = exchange(path, headers, method, payload)
        if (method != "GET" or time.monotonic() >= deadline
                or not (status == 503 or (status == 429 and page_set_read and value["code"] == "storage-quota"))):
            return status, value, raw, received
        assert status == 429 or value["code"] == "storage-unavailable"
        # Fresh read observations may contend with original coordinator work
        # or with the page sets of the TUI. Each retry is a new bounded read.
        # No POST enters this loop.
        time.sleep(0.05)


# The TUI answers every Enter or y on the exact review with one notice line,
# "Approval key N: <fixed text>", where N counts the approval-key presses of
# the session. Only the handling of that press renders its number, so the
# first appearance of a number above every earlier one is the boundary at
# which the TUI has finished processing the press. The not-sent notice keeps
# the number of the approving press, so it never counts as a new press.
#
# The notices are read from the PTY output written after the key, not from
# the final screen. An approval-start notice lasts only until the TUI observes
# the association, and several frames can arrive in one read. Vty rewrites a
# changed row as a whole and the notice text is one span, so a complete row
# ends at the next escape sequence or at the dialog border.
NOTICE = re.compile(r"Approval key (\d+): ([^\x1b\u2502\r\n]*)(?=[\x1b\u2502\r\n])")
ENTER_REFUSED = "Enter does not approve; y approves the exact review"
DETAIL_REFUSED = "y does not approve in the detail view"
APPROVAL_STARTED = "Approval started for the exact displayed review."
NOT_SENT = "Approval was not sent: the preflight check refused it before any send."
# These refusals report a transient lane or observation state that a later
# observation clears, so the positive approval may press y again after one.
APPROVAL_DEFERRED = ("Approval did not start: a manager command is in progress or unresolved.",
                     "Approval did not start: the displayed review is stale.")
OUTPUT_LIMIT = 16 * 1024 * 1024
# The live monitor shows the published runtime status on its own line. Each
# label names exactly one published status. The rank orders the statuses along
# the run lifecycle, so a later observation may only move forward from a
# non-terminal status.
RUNTIME_LINE = re.compile(r"Runtime: (Starting|Running|Cancelling|Succeeded|Failed|Cancelled|Owner unavailable)(?![A-Za-z])")
LABEL_STATUS = {"Starting": "starting", "Running": "running", "Cancelling": "cancelling", "Succeeded": "succeeded",
                "Failed": "failed", "Cancelled": "cancelled", "Owner unavailable": "orphaned"}
STATUS_RANK = {"starting": 0, "running": 1, "cancelling": 2, "succeeded": 3, "failed": 3, "cancelled": 3, "orphaned": 3}
# Rows that only the request screen shows. A live-monitor frame contains none.
REQUEST_SCREEN_ROWS = ("Manager request", "Admission:", "Position:", "Blocking reasons:", "Retained operator literals:")


def agrees(shown, published):
    """Whether a displayed runtime label agrees with a later published status."""
    displayed = LABEL_STATUS[shown]
    return published == displayed or STATUS_RANK[displayed] < min(3, STATUS_RANK[published])


def notice_is(line, number, text):
    """Whether the first displayed row of a notice starts the given notice.

    The TUI wraps a long notice at 80 columns. Every first row is long enough
    to tell the fixed texts apart, and no fixed text is a prefix of another.
    """
    full = f"Approval key {number}: {text}"
    return full.startswith(line) and len(line) >= min(len(full), len(f"Approval key {number}: ") + 30)


def squeeze(text):
    """The text without white space and box drawing, so wrapped rows join."""
    return "".join(char for char in text if not char.isspace() and not "─" <= char <= "╿")


def details(screen):
    """The text of the details pane of a TUI overview screen, joined."""
    return "".join(line.split("\u2502", 1)[1].strip() for line in screen.splitlines() if "\u2502" in line)


def history_focus(session, index, expected):
    """Home and then Down index times select the row at this position of
    the History view of the TUI. The focused details must name the
    expected run. Returns the details without spaces, so that a long
    identifier that wraps across rows stays one string."""
    session.send(b"\x1b[H")
    session.settle()
    if index:
        session.send(b"\x1b[B" * index)
    deadline = time.monotonic() + 20
    while "Run:" + expected not in details(session.screen.text()).replace(" ", ""):
        assert time.monotonic() < deadline, ("the History row at this position is not the run", index, expected, session.screen.text())
        session.pump(0.1)
    return details(session.screen.text()).replace(" ", "")


def focus_row(session, label, value, timeout):
    """Move the overview focus to the row whose list label starts with
    label and whose details contain value, until the overview lists it.
    The value is compared without spaces."""
    deadline = time.monotonic() + timeout
    while True:
        session.send(b"\x1b[A" * 16)
        session.settle()
        for _ in range(16):
            screen = session.screen.text()
            if "> " + label in screen and value in details(screen).replace(" ", ""):
                return screen
            session.send(b"\x1b[B")
            session.settle()
        assert time.monotonic() < deadline, ("no overview row has the label and the value", label, value, session.screen.text())
        session.pump(0.5)


def mutation_key(session, key, expected, timeout):
    """Send a mutation key until the screen shows the expected text. A
    key that a page-set read deferred shows a numbered outcome and sends
    nothing, so the key is sent again, as an operator does."""
    deferred = re.compile(r"(Key|Approval key) (\d+): (\S+ deferred during a page-set read|Approval did not start: "
                          r"(a manager command is in progress|the displayed review is stale))")
    seen = {match.group(2) for match in deferred.finditer(session.screen.text())}
    deadline = time.monotonic() + timeout
    session.send(key)
    while squeeze(expected) not in squeeze(session.screen.text()):
        assert time.monotonic() < deadline, ("the TUI did not show", expected, session.screen.text())
        fresh = {match.group(2) for match in deferred.finditer(session.screen.text())} - seen
        if fresh:
            seen |= fresh
            session.send(key)
        session.pump(0.1)
    return session.screen.text()


def notices(session, start):
    """The notice rows in the PTY output after the byte offset start, in order."""
    # TuiSession keeps the whole output until it reaches this limit.
    assert len(session.output) < OUTPUT_LIMIT, "PTY output reached the retention limit"
    text = bytes(session.output[start:]).decode("utf-8", "replace")
    return [(int(match.group(1)), ("Approval key " + match.group(1) + ": " + match.group(2)).rstrip())
            for match in NOTICE.finditer(text)]


def key_notice(session, key, after, failure):
    """Send one approval key and return the byte offset before it, and the
    number and first row of its notice.

    The wait ends at the first notice numbered above after in the output
    written after the key, or fails with the given message at the deadline.
    No fixed delay takes part.
    """
    start = len(session.output)
    session.send(key)
    deadline = time.monotonic() + 15
    while True:
        newer = [item for item in notices(session, start) if item[0] > after]
        if newer:
            return start, newer[0]
        if time.monotonic() >= deadline or session.process.poll() is not None:
            break
        session.pump()
    (work / "tui-missing-notice.screen.txt").write_text(session.screen.text())
    print("KEY OUTCOME: no approval-key notice above", after, "before the deadline", flush=True)
    raise AssertionError(failure)


MIXED_TEXT = "Café λ — explicit false.\nSecond line."
# The exact literal and the exact captured text of
# ext-pi/test/manager-ui-live.test.ts, as LITERAL and CAPTURED state them.
PI_UI_LITERAL = "  Café λ — exact literal.\n\tSecond line ✓"
PI_UI_CAPTURED = "  Captured Ünïcode λ\r\nsecond line\n"
# The literals of the two mixed-controls runs of the monitor and answer steps
# of ext-pi/test/manager-ui-live.test.ts, as ANSWERED and STALE state them.
PI_UI_ANSWERED = "Pi answer λ: explicit false."
PI_UI_STALE = "Pi stale λ: the harness answers first."
PI_UI_CANCELLED = "Pi cancel λ: the run ends cancelled."
PI_UI_TOOL_DECLINED = "Pi tool λ: the human declines the review."
PI_UI_TOOL_ANSWERED = "Pi tool λ: the model answers false."
# The replacement answer of the fork step, as FORKED states it.
PI_UI_FORKED = "Pi fork λ: the replaced answer."


def mixed_client(capabilities, authorized, attempts=None):
    """The read and mutation steps of the mixed workflow, bound to one
    credential. When attempts is a list, each mutation appends its operation,
    URI, exact headers, exact payload, receipt URI and original receipt, so a
    later step can repeat the exact attempt."""

    def observed(path, schema):
        deadline = time.monotonic() + 5
        while True:
            status, value, raw, headers = exchange(path, authorized)
            if status != 503:
                break
            assert value["code"] == "storage-unavailable" and time.monotonic() < deadline, ("read unavailable", path)
            # A 503 here means that a Store action waited out its whole allowance.
            # Each retry is a new read observation, never a repeated mutation or
            # an inferred successful effect.
            time.sleep(0.05)
        assert status == 200, (path, status, value.get("code"))
        validate(schema, value, raw)
        return value, headers.get("etag"), raw

    def wait_for(path, schema, ready):
        deadline = time.monotonic() + 40
        while True:
            value, tag, raw = observed(path, schema)
            if ready(value):
                return value, tag, raw
            if schema == "Request" and value["phase"] in ("draft", "withdrawn", "refused"):
                (work / "wait-last.json").write_bytes(raw)
                raise AssertionError(("request preparation did not remain active", path, value["phase"]))
            if time.monotonic() >= deadline:
                (work / "wait-last.json").write_bytes(raw)
                raise AssertionError(("observation deadline", path))
            time.sleep(0.05)

    def mutate(path, body, tag):
        assert tag is not None and tag.startswith('"') and tag.endswith('"')
        key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
        payload = json.dumps(body, ensure_ascii=False, separators=(",", ":")).encode()
        headers = authorized | {"Content-Type": "application/json", "Idempotency-Key": key, "If-Match": tag}
        status, receipt, _, _ = exchange(path, headers, method="POST", payload=payload)
        if status == 503 and confirm_uncertain:
            # This optional test scenario explicitly chooses one reconciliation
            # resend, just as it explicitly chooses approval. Production Client
            # must not make this choice. URI/key/body/precondition stay unchanged.
            print("OPERATOR CONFIRM exact retained attempt:", body["operation"], flush=True)
            current, _, _ = observed("/v1/capabilities", "Capabilities")
            assert current["authorityEpoch"] == capabilities["authorityEpoch"]
            status, receipt, _, _ = exchange(path, headers, method="POST", payload=payload)
        assert status == 202, ("mutation refused or uncertain", body["operation"], status, receipt.get("code"))
        validate("CommandReceipt", receipt)
        if attempts is not None:
            attempts.append((body["operation"], path, headers, payload, receipt["links"]["self"], receipt))
        if body["operation"] == "approve":
            # Runtime association is independent evidence. The approval receipt
            # remains dispatch-attempted and is not reclassified as delivered.
            return receipt["links"]["self"]
        value, _, _ = wait_for(receipt["links"]["self"], "CommandReceipt",
            lambda value: value["state"] in ("effect-observed", "refused", "unresolved"))
        assert value["state"] == "effect-observed", ("mutation not effected", body["operation"], value["state"])
        return receipt["links"]["self"]

    return observed, wait_for, mutate, authorized


def approve_mixed(created, workflow, client):
    """Supply the literal input, enqueue, check the exact review and approve
    it. Returns the approval receipt URI and the associated run."""
    enqueue_mixed(created, workflow, client)
    return approve_review(created, workflow, client)


def enqueue_mixed(created, workflow, client):
    """Supply the literal input of each declaration and enqueue the request."""
    observed, _, mutate, _ = client
    text = MIXED_TEXT
    request_uri = created["links"]["self"]
    for declaration in workflow["inputs"]:
        current, tag, _ = observed(request_uri, "Request")
        mutate(request_uri, {"operation": "set-input", "input": {"name": declaration["name"],
            "source": "literal", "value": text}}, tag)
    current, tag, _ = observed(request_uri, "Request")
    assert not current["readiness"]["missing"] and not current["readiness"]["errors"]
    assert all(item["value"] == text for item in current["readiness"]["supplied"])
    mutate(request_uri, {"operation": "enqueue"}, tag)


def approve_review(created, workflow, client):
    """Wait until the enqueued request is in review, check the exact review
    and approve it. Returns the approval receipt URI and the associated run."""
    observed, wait_for, mutate, _ = client
    text = MIXED_TEXT
    request_uri = created["links"]["self"]
    current, _, _ = wait_for(request_uri, "Request", lambda value: value["preparationId"] is not None)
    preparation, tag, raw = observed("/v1/preparations/" + current["preparationId"], "Preparation")
    (work / "exact-review.json").write_bytes(raw)
    assert preparation["requestId"] == created["id"] and preparation["state"] == "live"
    for item in preparation["review"]["inputs"]:
        declaration = next(value for value in workflow["inputs"] if value["name"] == item["name"])
        # The logical literal stays unchanged. Native prompt transport adds its
        # declared LF, and the exact approval hashes those native input bytes.
        expected = text.encode() + (b"\n" if declaration["source"] == "prompt" else b"")
        assert item["source"] == "literal" and item["bytes"] == str(len(expected))
        assert item["sha256"] == hashlib.sha256(expected).hexdigest()
    overview, _, raw = observed("/v1/snapshot", "OverviewSnapshot")
    # The overview of a credential can span pages, as in the emacs-client
    # mode, so the harness reads every page of the set.
    items, page = list(overview["items"]), overview
    while page["page"]["next"] is not None:
        page, _, _ = observed(page["page"]["next"], "OverviewSnapshot")
        items += page["items"]
    assert any(item["kind"] == "preparation" and item["preparation"]["id"] == preparation["id"] for item in items)
    (work / "review-overview.json").write_bytes(raw)
    selectors = ("reviewDigest", "requestRevision", "profileRevision", "descriptorRevision", "processGeneration")
    approval = mutate("/v1/preparations/" + preparation["id"],
           {"operation": "approve", **{key: preparation[key] for key in selectors}}, tag)
    current, _, _ = wait_for(request_uri, "Request", lambda value: value["runId"] is not None)
    return approval, current["runId"]


def drive_mixed(run, client, stop_at_question=False, overview=True):
    """Act on each decision head of the run through one credential. The
    question receives typed false and the recovery receives retry. With
    stop_at_question, return the pending question head without answering it,
    so that the worker stays live. Otherwise return at terminal success.
    With overview, each head is also found in the overview snapshot, which
    must then fit one page. Returns the question head, or None, and the
    counts of answers and retries that this call sent."""
    observed, _, mutate, client_authorized = client
    base = "/v1/runs/" + run
    answered = recovered = 0
    deadline = time.monotonic() + 50
    while True:
        snapshot, _, raw = observed(base + "/snapshot", "RunSnapshot")
        assert snapshot["page"]["next"] is None
        runtime = snapshot["runtime"]
        if runtime is not None and runtime["status"] in ("succeeded", "failed", "cancelled"):
            assert runtime["status"] == "succeeded" and not stop_at_question, ("mixed workflow terminal status", runtime["status"])
            (work / "terminal-snapshot.json").write_bytes(raw)
            return None, answered, recovered
        assert time.monotonic() < deadline, "mixed workflow terminal deadline"
        control, control_tag, _ = observed(base + "/control", "RunControl")
        head = control["decisionHeadId"]
        if head is None:
            time.sleep(0.05)
            continue
        decision, decision_tag, _ = observed("/v1/decisions/" + head, "Decision")
        assert decision["position"] == 0 and decision["state"] == "pending" and decision["runId"] == run
        if collections:
            check_collections("head-" + decision["kind"], client_authorized, "profile_1", runs=[run], decisions=[head], queue=run)
            status, problem, _ = request("/v1/decisions?runId=" + run, other_authorized)
            assert status == 403 and problem["code"] == "insufficient-scope", ("other profile run queue", status, problem.get("code"))
            print("PASS decision collection lists the pending", decision["kind"], "head of the mixed run in both the head and the run queue views", flush=True)
        if overview:
            overview_value, _, raw = observed("/v1/snapshot", "OverviewSnapshot")
            assert any(item["kind"] == "run" and item["run"]["id"] == run for item in overview_value["items"])
            assert any(item["kind"] == "decision" and item["decision"]["id"] == head for item in overview_value["items"])
            (work / ("decision-" + decision["kind"] + ".json")).write_bytes(raw)
        body = {"occurrenceId": decision["address"]["occurrenceId"], "generation": decision["generation"]}
        if decision["kind"] == "question":
            assert decision["question"]["code"] == "flag"
            if stop_at_question:
                return head, answered, recovered
            body.update(operation="answer", value=False)
            mutate("/v1/decisions/" + head, body, decision_tag)
            answered += 1
        else:
            assert any(offer["operation"] == "retry" and offer["generation"] == decision["generation"]
                       and offer["address"] == decision["address"] for offer in control["offers"])
            body.update(operation="retry")
            mutate(base + "/control", body, control_tag)
            recovered += 1


def verified_download(run, client, authorized):
    """Read the verified result of a terminal run and download its exact bytes.
    Returns the artifact metadata."""
    observed = client[0]
    base = "/v1/runs/" + run
    value, _, raw = observed(base, "Run")
    (work / "terminal-run.json").write_bytes(raw)
    outputs, _, _ = observed(base + "/outputs", "OutputPage")
    result = next(item for item in outputs["items"] if item["kind"] == "result")
    assert result["verification"]["state"] == "verified" and result["artifact"]["runId"] == run
    artifact = result["artifact"]
    assert artifact["id"] == result["verification"]["artifactId"] and artifact["kind"] == "source-result"
    connection = http.client.HTTPSConnection("127.0.0.1", port, context=context, timeout=7)
    try:
        connection.request("GET", artifact["download"], headers=authorized | {"Accept": "application/octet-stream"})
        response = connection.getresponse()
        actual = response.read(int(artifact["bytes"]) + 1)
        assert response.status == 200 and response.getheader("Content-Type") == "application/octet-stream"
        assert response.getheader("Content-Disposition") == "attachment"
        assert response.getheader("Cache-Control") == "no-store" and response.getheader("X-Content-Type-Options") == "nosniff"
        assert len(actual) == int(artifact["bytes"]) and hashlib.sha256(actual).hexdigest() == artifact["sha256"]
        (work / "verified-result.json").write_bytes(actual)
    finally:
        connection.close()
    return artifact


def run_mixed(created, workflow, capabilities, authorized):
    client = mixed_client(capabilities, authorized)
    observed, wait_for, _, _ = client
    request_uri = created["links"]["self"]
    approval, run = approve_mixed(created, workflow, client)
    _, answered, recovered = drive_mixed(run, client)
    assert answered and recovered, ("mixed workflow decisions", answered, recovered)
    verified_download(run, client, authorized)
    pending, _, raw = observed(approval, "CommandReceipt")
    assert pending["state"] == "dispatch-attempted" and pending["effect"] is None
    (work / "approval-still-pending.json").write_bytes(raw)
    released, _, raw = wait_for(request_uri, "Request",
        lambda value: value["runId"] == run and value["admission"]["state"] == "released")
    assert released["phase"] == "associated"
    (work / "released-request.json").write_bytes(raw)
    print("PASS actual HTTP mixed workflow: Unicode, exact approval, typed false, retry, terminal observation and verified bytes; approval delivery remains distinct", flush=True)
    return run


def other_profile_request():
    """Create one draft in the second profile with the second credential."""
    status, current, _ = request("/v1/capabilities", other_authorized)
    assert status == 200 and current["profileIds"] == ["profile_2"], ("other capabilities", status)
    status, catalogue, _ = request("/v1/workflows?profileId=profile_2", other_authorized)
    assert status == 200 and catalogue["items"], ("other catalogue", status)
    chosen = catalogue["items"][0]
    body = {"workflowId": chosen["id"], "descriptorRevision": chosen["revision"],
            "profileId": chosen["profileId"], "profileRevision": chosen["profileRevision"]}
    key = current["authorityEpoch"] + "." + secrets.token_urlsafe(16)
    status, value, raw = request("/v1/requests", other_authorized | {"Content-Type": "application/json", "Idempotency-Key": key},
                                 method="POST", payload=json.dumps(body, separators=(",", ":")).encode())
    assert status == 201, ("other request", status, value.get("code"))
    validate("Request", value, raw)
    assert value["profileId"] == "profile_2"
    return value


def private_markers():
    """Bytes that no collection body may contain: the fixture root, which holds
    the manager root, every run store and every root identity, the native run
    identifiers, and raw invocation fields."""
    markers = [str(work).encode(), json.dumps(str(work))[1:-1].encode(), b"mixed-adapter", b"--scripted",
               b"targetArguments", b"--engine"]
    stores = work / "manager" / "runs" / "runs"
    if stores.is_dir():
        markers += [entry.name.encode() for entry in stores.iterdir()]
    return markers


def check_collections(name, authorized, profile, requests=(), runs=(), decisions=(), queue=None, absent=()):
    """Read the request, run and decision collections, and the FIFO queue of
    the queue run when one is named. Each body must be one schema-valid page
    of the given profile, must contain the expected identifiers and none of
    the absent ones, and must contain no private marker. The queue must start
    with its expected head."""
    reads = [("requests", "/v1/requests", "RequestPage"), ("runs", "/v1/runs", "RunPage"),
             ("decisions", "/v1/decisions", "DecisionPage")]
    if queue is not None:
        reads.append(("queue", "/v1/decisions?runId=" + queue, "DecisionPage"))
    found = {}
    markers = private_markers()
    for label, path, schema in reads:
        status, value, raw, received = fetch(path, authorized)
        assert status == 200, ("collection read", path, status, value.get("code"))
        validate(schema, value, raw)
        assert received.get("etag", "").startswith('"'), ("collection ETag", path)
        # The run collection of the pages mode also lists the legacy entries
        # of its bound root, which span more than one window. The check
        # follows every page of that set. Every other collection is one page.
        pages, bodies = [value], [raw]
        while pages_mode and label == "runs" and pages[-1]["page"]["next"] is not None:
            status, following, following_raw, _ = fetch(pages[-1]["page"]["next"], authorized)
            assert status == 200, ("collection continuation", path, status, following.get("code"))
            validate(schema, following, following_raw)
            pages.append(following)
            bodies.append(following_raw)
        items = [item for page in pages for item in page["items"]]
        assert pages[-1]["page"]["next"] is None and value["page"]["totalItems"] == len(items), ("collection page", path)
        assert len({item["id"] for item in items}) == len(items), ("collection duplicate", path)
        assert all(item["profileId"] == profile for item in items), ("collection profile", path)
        leaked = [marker for marker in markers for body in bodies if marker in body]
        assert not leaked, ("collection body holds private bytes", path, leaked)
        (work / f"collection-{name}-{label}.json").write_bytes(raw)
        found[label] = [item["id"] for item in items]
    for label, expected in (("requests", requests), ("runs", runs), ("decisions", decisions)):
        assert set(expected) <= set(found[label]), ("collection member missing", label, expected, found[label])
    if queue is not None:
        assert found["queue"][:len(decisions)] == list(decisions), ("run queue head", found["queue"])
    hidden = [ident for values in found.values() for ident in values if ident in absent]
    assert not hidden, ("collection shows another profile", hidden)
    return found


def check_run_resources(run, authorized):
    """Read the export and lineage-request collections of the terminal mixed
    run, and an unknown export receipt. Each collection must be one
    schema-valid page of the run with no private marker. The run has no
    export and no child request. Its released reservation leaves every
    lineage operation eligible. The second credential is refused, and an
    unknown export is absent for both credentials."""
    markers = private_markers()
    found = {}
    for label, path, schema in (("exports", f"/v1/runs/{run}/exports", "ExportPage"),
                                ("lineage", f"/v1/runs/{run}/lineage-requests", "LineagePage")):
        status, value, raw, received = fetch(path, authorized)
        assert status == 200, ("run resource read", path, status, value.get("code"))
        validate(schema, value, raw)
        assert value["runId"] == run and value["items"] == [], ("run resource members", path)
        assert value["page"]["next"] is None and value["page"]["totalItems"] == 0, ("run resource page", path)
        assert received.get("etag", "").startswith('"'), ("run resource ETag", path)
        leaked = [marker for marker in markers if marker in raw]
        assert not leaked, ("run resource body holds private bytes", path, leaked)
        (work / f"run-{label}.json").write_bytes(raw)
        found[label] = value
        status, problem, _ = request(path, other_authorized)
        assert status == 403 and problem["code"] == "insufficient-scope", ("other profile run resource", path, status)
        status, problem, _ = request(path + "?runId=" + run, authorized)
        assert status == 400 and problem["code"] == "malformed-request", ("run resource query refusal", path, status)
    lineage = found["lineage"]
    assert lineage["eligible"] == ["restart", "resume", "fork"] and lineage["refusal"] is None, ("lineage eligibility", lineage["eligible"], lineage["refusal"])
    for credential in (authorized, other_authorized):
        status, problem, _ = request("/v1/exports/export_absent", credential)
        assert status == 404 and problem["code"] == "unavailable-resource", ("unknown export", status, problem.get("code"))


def read_coordination(statement, parameters=()):
    """The rows of one query of the coordination database, read through a
    read-only connection."""
    import sqlite3
    found = sorted((work / "manager").rglob("coordination.sqlite3"))
    assert len(found) == 1, ("coordination database", found)
    connection = sqlite3.connect(found[0].as_uri() + "?mode=ro", uri=True)
    try:
        return [tuple(row) for row in connection.execute(statement, parameters)]
    finally:
        connection.close()


def command_ids():
    """The identifiers of every command row of the coordination database."""
    return {ident for (ident,) in read_coordination("SELECT id FROM commands")}


def command_receipts(cursor, authorized):
    """The resource and receipt of each command that a command.changed event
    after the cursor names, in event order, from read-only reads."""
    resources = []
    for _ in range(256):
        status, batch, raw, _ = fetch("/v1/events?after=" + cursor, authorized | {"Accept": "application/json"})
        assert status == 200, ("event read", status, batch.get("code"))
        validate("EventBatch", batch, raw)
        for event in batch["events"]:
            if event["event"] == "command.changed" and event["data"]["resource"] not in resources:
                resources.append(event["data"]["resource"])
        cursor = batch["cursor"]
        if not batch["hasMore"]:
            break
    else:
        raise AssertionError("JOURNEY-DEADLINE event pages")
    receipts = []
    for resource in resources:
        status, receipt, raw, _ = fetch(resource, authorized)
        assert status == 200, (resource, status, receipt.get("code"))
        validate("CommandReceipt", receipt, raw)
        receipts.append((resource, receipt))
    return receipts


def run_history(authorized):
    """Every page of /v1/runs in order. Returns the run identifiers in the
    order of the collection, the number of legacy observer entries and the
    number of pages."""
    history, observers, pages, target = [], 0, 0, "/v1/runs"
    while target is not None:
        status, value, raw = request(target, authorized)
        assert status == 200, ("history page", target, status, value.get("code"))
        validate("RunPage", value, raw)
        assert value["page"]["index"] == pages, ("history page index", value["page"]["index"], pages)
        pages += 1
        history.extend(item["id"] for item in value["items"])
        observers += sum(1 for item in value["items"] if item["supervision"] == "observer")
        target = value["page"]["next"]
    return history, observers, pages


def read_flow(name, paths, binary=None):
    """Run the flow verb of the given binary, or else of the TUI_CHECK binary,
    on the paths and return its exit status, its records and its summary. The
    output is kept in work."""
    completed = subprocess.run([str(binary or os.environ["TUI_CHECK"]), "flow"] + [str(path) for path in paths],
                               stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=60)
    (work / (name + ".ndjson")).write_bytes(completed.stdout)
    (work / (name + ".stderr")).write_bytes(completed.stderr)
    lines = [json.loads(line) for line in completed.stdout.splitlines()]
    assert lines and "summary" in lines[-1], ("the flow verb printed no summary", completed.returncode, completed.stderr[-2000:])
    return completed.returncode, lines[:-1], lines[-1]["summary"]


def journey_flow_assertions(credential, submitted, preparation, approve_command, answer_command, answer_resource,
                            retry_command, run, question_occurrence):
    """Read the journey manager log and run store with the flow verb, after the
    manager process has exited, and assert each fact of section 6.1 gate 1 of
    the actor-flow design with its own FLOW-ASSERT message."""
    flow_dir = work / "manager" / "flow"
    logs = sorted(flow_dir.glob("*.ndjson"))
    stores = sorted(work.glob("manager/runs/runs/*/runtime"))
    assert len(logs) == 1 and len(stores) == 1, ("FLOW-ASSERT the journey has other than one manager log and one run store", logs, stores)
    manager_path, store = str(logs[0]), stores[0]
    status, records, summary = read_flow("journey-flow", [flow_dir, store])
    assert status == 0 and summary["verified"] and not summary["problems"], (
        "FLOW-ASSERT the flow verb did not verify the journey logs", status, summary["problems"])
    manager = [record for record in records if record["log"] == manager_path]
    runlog = [record for record in records if record["log"] == str(store)]
    assert len(manager) + len(runlog) == len(records), "FLOW-ASSERT the flow verb printed a record of another log"
    at = lambda log, position: {"log": log, "position": position}
    run_log = next(item for item in summary["logs"] if item["kind"] == "run")
    report = run_log["report"]
    native = store.parent.name

    # The senders are the journey credential and client.
    principal = {"principal": "credential", "credentialId": credential["credentialId"], "client": credential["clientId"]}
    commands = [record for record in manager if record["schema"] == "command"]
    receipts = [record for record in manager if record["schema"] == "receipt"]
    assert commands and all(record["from"] == principal for record in commands), (
        "FLOW-ASSERT a manager-log command sender is not the journey credential and client", [record["from"] for record in commands])
    assert all(record["to"] == {"to": principal} for record in receipts), (
        "FLOW-ASSERT a manager-log receipt is not addressed to the journey credential and client")

    def command(operation, failure):
        found = [record for record in commands if record["body"]["operation"] == operation]
        assert len(found) == 1, (failure, operation, len(found))
        found = found[0]
        replies = [record for record in receipts if record["replyTo"] == found["position"]]
        assert len(replies) == 1, (failure, "receipt", len(replies))
        reply = replies[0]
        assert reply["body"]["operation"] == operation and reply["body"]["state"] != "refused", (failure, "receipt", reply["body"]["state"])
        assert reply["body"]["id"] == found["about"]["command"] == reply["about"]["command"], (failure, "receipt identity")
        return found, reply

    enqueue, enqueue_receipt = command("enqueue", "FLOW-ASSERT the manager log has no enqueue command with its receipt")
    assert enqueue["body"]["resource"] == submitted["links"]["self"] and enqueue["about"]["request"] == submitted["id"], (
        "FLOW-ASSERT the manager log has no enqueue command with its receipt", enqueue["body"]["resource"])
    print("FLOW enqueue command", enqueue["about"]["command"], "at position", enqueue["position"], "with its", enqueue_receipt["body"]["state"],
          "receipt at position", enqueue_receipt["position"], flush=True)

    reviews = [record for record in manager if record["schema"] == "review"]
    assert len(reviews) == 1, ("FLOW-ASSERT the manager log has other than one review", len(reviews))
    review = reviews[0]
    assert review["from"] == "manager" and review["to"] == {"approvers": configuration["profiles"][0]["id"]}, (
        "FLOW-ASSERT the review is not from the manager to the approvers of the profile", review["from"], review["to"])
    assert review["about"].get("request") == submitted["id"], ("FLOW-ASSERT the review names another request", review["about"])
    joined = [item for item in summary["joins"]["reviews"] if item["review"] == at(manager_path, review["position"])]
    assert len(joined) == 1 and joined[0]["preparation"] == preparation["id"], ("FLOW-ASSERT the review is not joined to the preparation", joined)
    print("FLOW review at position", review["position"], "for preparation", preparation["id"], flush=True)

    approve, approve_receipt = command("approve", "FLOW-ASSERT the manager log has no approve command with its receipt")
    selectors = ("reviewDigest", "requestRevision", "profileRevision", "descriptorRevision", "processGeneration")
    body = approve["body"]["body"]["json"]
    assert approve["about"]["command"] == approve_command and approve["body"]["resource"] == "/v1/preparations/" + preparation["id"], (
        "FLOW-ASSERT the approve command is not the journey approval", approve["about"], approve["body"]["resource"])
    assert all(body.get(selector) == preparation[selector] for selector in selectors), (
        "FLOW-ASSERT the approve command does not carry the five review selectors", body)
    assert joined[0]["commands"] == [approve["position"]], ("FLOW-ASSERT the review is not joined to the approve command", joined[0]["commands"])
    print("FLOW approve command", approve_command, "at position", approve["position"], "carries", ", ".join(selectors), flush=True)

    relays = [record for record in manager if record["schema"] == "relay"]
    starts = [record for record in relays if record["body"]["kind"] == "start"]
    assert len(starts) == 1 and starts[0]["about"]["command"] == approve_command and starts[0]["body"]["nativeRun"] == native, (
        "FLOW-ASSERT the manager log has no start relay of the approval", [record["about"] for record in starts])
    start = starts[0]
    delivered = [item["delivered"] for item in summary["joins"]["relays"] if item["relay"] == at(manager_path, start["position"])]
    first = next(record for record in runlog if record["position"] == 0)
    assert delivered == [at(str(store), 0)] and first["schema"] == "start" and first["from"] == "manager", (
        "FLOW-ASSERT the start relay is not joined to the run-log start", delivered, first["schema"])
    print("FLOW start relay at position", start["position"], "delivered as run-log start 0 of", native, flush=True)

    questions = [record for record in runlog if record["schema"] == "question" and record["to"] == {"to": "manager"}]
    assert len(questions) == 1 and str(questions[0]["about"]["occurrence"]) == str(question_occurrence), (
        "FLOW-ASSERT the run log has no person question of the answered occurrence", [record["about"] for record in questions])
    question = questions[0]
    assert question["body"]["code"] == "flag", ("FLOW-ASSERT the run log has no person question of the answered occurrence", question["body"]["code"])
    print("FLOW person question at run-log position", question["position"], "for occurrence", question_occurrence, flush=True)

    answer, _ = command("answer", "FLOW-ASSERT the manager log has no answer command carrying JSON false")
    value = answer["body"]["body"]["json"].get("value", None)
    assert answer["about"]["command"] == answer_command and answer["body"]["resource"] == answer_resource and value is False, (
        "FLOW-ASSERT the manager log has no answer command carrying JSON false", answer["about"], value)
    print("FLOW answer command", answer_command, "at position", answer["position"], "carries JSON false", flush=True)

    retry, _ = command("retry", "FLOW-ASSERT the manager log has no retry command with its receipt")
    assert retry["about"]["command"] == retry_command and retry["body"]["resource"] == "/v1/runs/" + run + "/control", (
        "FLOW-ASSERT the manager log has no retry command with its receipt", retry["about"], retry["body"]["resource"])

    # Each command reaches the run as one relayed control, received as a
    # run-log control from the manager, with its acknowledgement event.
    controls = {}
    for identity, failure in ((answer_command, "FLOW-ASSERT the answer control is not relayed and acknowledged"),
                              (retry_command, "FLOW-ASSERT the retry command has no relayed and acknowledged control")):
        relayed = [record for record in relays if record["body"]["kind"] == "control" and record["about"]["command"] == identity]
        assert len(relayed) == 1 and relayed[0]["body"]["nativeRun"] == native, (failure, "relay", len(relayed))
        delivered = [item["delivered"] for item in summary["joins"]["relays"] if item["relay"] == at(manager_path, relayed[0]["position"])]
        assert len(delivered) == 1 and delivered[0] is not None and delivered[0]["log"] == str(store), (failure, "delivery", delivered)
        control = next(record for record in runlog if record["position"] == delivered[0]["position"])
        assert control["schema"] == "control" and control["from"] == "manager" and control["about"]["command"] == identity, (
            failure, "run-log control", control["schema"], control["from"], control["about"])
        acknowledged = [item["acknowledgement"] for item in summary["joins"]["controls"] if item["control"] == at(str(store), control["position"])]
        assert len(acknowledged) == 1 and acknowledged[0] is not None, (failure, "acknowledgement", acknowledged)
        controls[identity] = control
        print("FLOW relay at position", relayed[0]["position"], "delivered as run-log control", control["position"],
              "from the manager with command", identity, "and acknowledgement event", acknowledged[0], flush=True)

    # The run-log control and answer records name the manager and the command,
    # and the reader joins them to the commands of the principal.
    run_controls = [record for record in runlog if record["schema"] == "control"]
    assert sorted(record["about"].get("command") for record in run_controls) == sorted([answer_command, retry_command]) and all(
        record["from"] == "manager" for record in run_controls), (
        "FLOW-ASSERT a run-log control does not name the manager and a journey command", [(record["from"], record["about"]) for record in run_controls])
    answers = [record for record in runlog if record["schema"] == "answer" and record["replyTo"] == question["position"]]
    assert len(answers) == 1 and answers[0]["from"] == "manager" and answers[0]["about"].get("command") == answer_command and answers[0]["body"] is False, (
        "FLOW-ASSERT the run-log answer does not name the manager and the answer command", [(record["from"], record["about"], record["body"]) for record in answers])
    joined_answers = [item for item in summary["joins"]["answers"] if item["answer"] == at(str(store), answers[0]["position"])]
    assert joined_answers == [{"answer": at(str(store), answers[0]["position"]), "command": at(manager_path, answer["position"]), "commandId": answer_command}], (
        "FLOW-ASSERT the run-log answer is not joined to the answer command of the principal", joined_answers)
    for identity, control in controls.items():
        relay = next(record for record in relays if record["body"]["kind"] == "control" and record["about"]["command"] == identity)
        issued_command = next(record for record in commands if record["about"]["command"] == identity)
        assert issued_command["from"] == principal and relay["about"]["command"] == control["about"]["command"], (
            "FLOW-ASSERT a run-log control is not joined to a command of the principal", identity)
    print("FLOW run-log answer at position", answers[0]["position"], "names the manager and", answer_command,
          "and joins to manager position", answer["position"], flush=True)

    # The terminal record, and no ask after it.
    stop = report["stop"]
    assert stop is not None and not report["live"] and any(record["position"] == stop for record in runlog), (
        "FLOW-ASSERT the run log has no terminal record", stop, report["live"])
    asks = ("question", "engine-start", "turn", "steer", "command")
    late = [record["position"] for record in runlog if record["position"] > stop and record["schema"] in asks]
    assert not late and not report["states"]["askAfterStop"], ("FLOW-ASSERT an ask follows the terminal record", late, report["states"]["askAfterStop"])
    print("FLOW terminal record at run-log position", stop, "of", report["records"], "records, and no ask follows it", flush=True)

    # Consent verification of the start relay.
    consent = summary["consent"]
    assert len(consent) == 1 and consent[0]["verified"] and not consent[0]["problems"], ("FLOW-ASSERT consent verification failed", consent)
    assert (consent[0]["review"], consent[0]["command"], consent[0]["relay"], consent[0]["runStart"]) == (
        review["position"], approve["position"], at(manager_path, start["position"]), at(str(store), 0)), (
        "FLOW-ASSERT consent verification failed", consent[0])
    print("FLOW consent verified: review", review["position"], "approve", approve["position"], "receipt", consent[0]["receipt"],
          "start relay", start["position"], "run start 0", flush=True)

    # The manager log ends its lifetime with the shutdown notice.
    lifetimes = summary["joins"]["lifetimes"]
    assert lifetimes and all(item["shutdown"] is not None for item in lifetimes), ("FLOW-ASSERT the manager log has no shutdown notice", lifetimes)

    # Gate 9 report: the manager log size and the run-log storage ratio.
    manager_bytes = sum(path.stat().st_size for path in flow_dir.rglob("*") if path.is_file())
    claims = store / "flow-claims"
    logged = (store / "flow.ndjson").stat().st_size + sum(
        path.stat().st_size for path in (claims.rglob("*") if claims.is_dir() else ()) if path.is_file())
    public = sum((store / name).stat().st_size for name in ("events.ndjson", "answers.json", "effects.ndjson") if (store / name).exists())
    ratio = logged / public
    print(f"FLOW manager log size: {len(manager)} records, {manager_bytes} bytes", flush=True)
    print(f"FLOW run-log storage ratio: run log {logged} bytes, public files {public} bytes, ratio {ratio:.3f}", flush=True)
    assert ratio <= 2.5, ("FLOW-ASSERT the run log takes more than 2.5 times the public files", ratio)
    print("PASS flow: the verb verifies the journey manager log and run store, every FLOW-ASSERT holds and consent is verified", flush=True)


def approve_fault_in_session(session, submitted, preparation, preparation_uri, preparation_tag, renamed_log, cursor, authorized):
    """Check, with read-only observations, that the manager refused the
    approval after the manager log was renamed away."""
    assert renamed_log is not None, "the approve-fault control did not rename the manager log"
    refusal = squeeze('Refused 503 "storage-unavailable"')
    deadline = time.monotonic() + 45
    while refusal not in squeeze(session.screen.text()):
        assert "Phase: associated" not in session.screen.text(), "FLOW-FAULT-ASSERT the approval associated a run although the approve append failed"
        if time.monotonic() >= deadline or session.process.poll() is not None:
            (work / "tui-approve-fault-missing.screen.txt").write_text(session.screen.text())
            raise AssertionError("FLOW-FAULT-DEADLINE the TUI showed no storage-unavailable refusal of the approval")
        session.pump()
    session.settle()
    (work / "tui-approve-fault.screen.txt").write_text(session.screen.text())
    print("PASS actual TUI shows the approval send refused with 503 storage-unavailable", flush=True)
    status, current, raw, _ = fetch(submitted["links"]["self"], authorized)
    assert status == 200, ("request read", status, current.get("code"))
    validate("Request", current, raw)
    assert current["runId"] is None and current["phase"] == "review" and current["preparationId"] == preparation["id"], (
        "FLOW-FAULT-ASSERT the refused approval changed the request", current["phase"], current["runId"])
    status, still, raw, received = fetch(preparation_uri, authorized)
    assert status == 200, ("preparation read", status, still.get("code"))
    validate("Preparation", still, raw)
    assert still["state"] == "live" and still["revision"] == preparation["revision"] and received.get("etag") == preparation_tag, (
        "FLOW-FAULT-ASSERT the refused approval changed the preparation", still["state"])
    approvals = [receipt for _, receipt in command_receipts(cursor, authorized) if receipt["operation"] == "approve"]
    assert all(receipt["state"] == "refused" for receipt in approvals), (
        "FLOW-FAULT-ASSERT the ledger holds an accepted approval", [receipt["state"] for receipt in approvals])
    print("PASS the request stays in review, the preparation stays live and unchanged, and the ledger holds no accepted approval",
          "(approve receipts:", len(approvals), ")", flush=True)


def approve_fault_after_shutdown(renamed_log, preparation_uri):
    """After the manager process has exited, check that the manager recorded
    its storage-unavailable response to the approval, that no manager log
    holds an approve command or a start relay, and that no run store exists."""
    faults = (work / "server-0.stderr").read_text(errors="replace").splitlines()
    assert any("response POST " + preparation_uri + " " in line and "public=503 storage-unavailable" in line for line in faults), (
        "FLOW-FAULT-ASSERT the manager recorded no storage-unavailable response to the approval")
    flow_dir = work / "manager" / "flow"
    left = sorted(flow_dir.glob("*.ndjson"))
    assert not left, ("FLOW-FAULT-ASSERT the manager wrote a new log at the renamed path", left)
    stores = sorted(work.glob("manager/runs/runs/*"))
    assert not stores, ("FLOW-FAULT-ASSERT a run store exists after the refused approval", stores)
    _, records, _ = read_flow("approve-fault-flow", [renamed_log])
    schemas = [record["schema"] for record in records]
    assert "review" in schemas, ("FLOW-FAULT-ASSERT the renamed manager log holds no review", schemas)
    approvals = [record["position"] for record in records if record["schema"] == "command" and record["body"]["operation"] == "approve"]
    relays = [record["position"] for record in records if record["schema"] == "relay"]
    assert not approvals and not relays, ("FLOW-FAULT-ASSERT a manager log holds an approve command or a relay", approvals, relays)
    print("PASS the manager recorded its 503 storage-unavailable response to the approval; the renamed manager log holds the review and",
          len(records), "records, and no approve command and no relay; no run store exists and the manager wrote no new log", flush=True)


def wait_ready(process):
    """Wait for HTTPS readiness of the original foreground manager process."""
    deadline = time.monotonic() + 40
    while True:
        assert process.poll() is None, "foreground manager exited before HTTPS readiness"
        try:
            status, _, _ = request("/v1/profiles")
            break
        except ConnectionRefusedError:
            assert time.monotonic() < deadline, "HTTPS readiness deadline"
            time.sleep(0.05)
    assert status == 401


def descendants(root):
    """The current descendant process IDs of root, from one process listing."""
    listing = subprocess.run(["ps", "-Ao", "pid=,ppid="], stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                             text=True, timeout=10, check=True).stdout
    children = {}
    for line in listing.splitlines():
        pid, parent = map(int, line.split())
        children.setdefault(parent, []).append(pid)
    found, frontier = [], [root]
    while frontier:
        for child in children.get(frontier.pop(), []):
            found.append(child)
            frontier.append(child)
    return found


def process_environment(pid):
    """The command and environment that ps shows for one same-user process,
    or None when the process has exited."""
    completed = subprocess.run(["ps", "eww", "-o", "command=", "-p", str(pid)], stdout=subprocess.PIPE,
                               stderr=subprocess.PIPE, timeout=10)
    return completed.stdout if completed.returncode == 0 and completed.stdout.strip() else None


def open_stream(path, authorized):
    """Open one SSE response and read its first complete block, which the
    manager writes at once as an event batch or a heartbeat."""
    deadline = time.monotonic() + 5
    while True:
        connection = http.client.HTTPSConnection("127.0.0.1", port, context=context, timeout=7)
        connection.request("GET", path, headers=authorized | {"Accept": "text/event-stream"})
        response = connection.getresponse()
        if response.status == 200:
            break
        raw = response.read(1048577)
        status = response.status
        response.close()
        connection.close()
        refused = frozen.parse_json(raw)
        validate("Problem", refused)
        # A refused read registration owns no subscription. This is not a
        # mutation replay or a cleanup inference.
        assert status in (429, 503) and time.monotonic() < deadline, ("stream admission", status, refused["code"])
        time.sleep(0.05)
    assert response.getheader("Content-Type") == "text/event-stream"
    block = bytearray()
    while not block.endswith(b"\n\n"):
        line = response.readline(16385)
        assert line and len(block) + len(line) <= 16384, "first stream block"
        block.extend(line)
    return connection, response, bytes(block)


def stream_ends(response, seconds):
    """Whether the open stream reaches its end within the wall deadline.
    Heartbeats and event blocks before the end are read and discarded."""
    deadline = time.monotonic() + seconds
    while time.monotonic() < deadline:
        try:
            line = response.readline(16385)
        except http.client.IncompleteRead:
            return True
        except (ConnectionError, ssl.SSLError):
            return True
        if not line:
            return True
    return False


def credential_lifecycle():
    """WM-023 section 7 through the real HTTPS manager, numbered as in the
    B8 requirement. Store-level rotation, cutoff and idempotency facts stay
    with manager/test/CommandCheck.hs and credential_cli.py."""
    marker = "acatambientmarker" + secrets.token_hex(16)
    synthetic = "acatsyntheticbearer" + secrets.token_hex(24)
    bearers = {"fixture": bearer}
    outputs = [work / "credential"]

    def issue(name, scopes):
        output = work / ("credential-" + name)
        value = administration({"version": 1, "operation": "issue-credential", "label": "Lifecycle " + name,
                                "scopes": scopes, "profileIds": ["profile_1"],
                                "expiresAt": "2999-01-01T00:00:00Z", "outputFile": str(output)})
        outputs.append(output)
        bearers[name] = output.read_bytes().decode("ascii")
        return value["result"]["credential"], {"Authorization": "Bearer " + bearers[name]}

    def listed():
        values = administration({"version": 1, "operation": "list-credentials"})["result"]["credentials"]
        return {item["credentialId"]: item for item in values}

    def status_of(path, authorized, method="GET", payload=None, headers=None):
        return request(path, authorized | (headers or {}), method=method, payload=payload)[:2]

    environment = dict(os.environ, ACAT_LIFECYCLE_MARKER=marker)
    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors, env=environment)
        try:
            wait_ready(process)
            for _ in range(3):
                status, problem, _ = request("/v1/capabilities", {"Authorization": "Bearer " + synthetic})
                assert status == 401 and problem["code"] == "unauthenticated", "a synthetic bearer marker must not authenticate"

            # Step 1. Credentials A and B, and a live worker at the person question.
            credential_a, a_auth = issue("a", ["observe", "submit", "control"])
            credential_b, b_auth = issue("b", ["observe", "control"])
            status, capabilities, raw = request("/v1/capabilities", a_auth)
            assert status == 200 and capabilities["scopes"] == ["observe", "submit", "control"]
            validate("Capabilities", capabilities, raw)
            status, catalogue, raw = request("/v1/workflows?profileId=profile_1", a_auth)
            assert status == 200
            validate("WorkflowPage", catalogue, raw)
            workflow = next(item for item in catalogue["items"] if item["name"] == "mixed-controls")
            create = json.dumps({"workflowId": workflow["id"], "descriptorRevision": workflow["revision"],
                                 "profileId": workflow["profileId"], "profileRevision": workflow["profileRevision"]},
                                separators=(",", ":")).encode()

            def create_request(authorized):
                key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
                status, created, raw = request("/v1/requests", authorized | {
                    "Content-Type": "application/json", "Idempotency-Key": key}, method="POST", payload=create)
                assert status == 201, ("request creation", status, created.get("code"))
                validate("Request", created, raw)
                return created

            created = create_request(a_auth)
            a_attempts = []
            a_client = mixed_client(capabilities, a_auth, a_attempts)
            approval, run = approve_mixed(created, workflow, a_client)
            base = "/v1/runs/" + run
            head, answered, recovered_by_a = drive_mixed(run, a_client, stop_at_question=True)
            assert head is not None and answered == 0
            control, _, _ = a_client[0](base + "/control", "RunControl")
            assert control["supervision"] == "owned" and control["decisionHeadId"] == head
            cursor = a_client[0]("/v1/snapshot", "OverviewSnapshot")[0]["cursor"]
            status, value, _ = request(base + "/control", b_auth)
            assert status == 200 and value["decisionHeadId"] == head, "credential B observes the live run"
            # The worker environment is the explicit operator environment of the
            # profile. The ambient marker of the manager process is the positive
            # control that ps shows environments at all.
            shown = process_environment(process.pid)
            assert shown is not None and marker.encode() in shown, "ps does not show the manager environment"
            inspected = [(pid, shown) for pid in descendants(process.pid)
                         for shown in [process_environment(pid)] if shown is not None]
            assert inspected, "the live run has no worker process to inspect"
            assert not [pid for pid, shown in inspected if marker.encode() in shown], "a worker inherited the ambient manager environment"
            workers = len(inspected)
            print("PASS credential-lifecycle step 1: credentials A (observe, submit, control) and B (observe, control) issued through",
                  "the administration socket; A created, enqueued and approved mixed-controls run", run,
                  "and the worker waits live at person question", head, flush=True)

            # Step 2. Rotation overlap, receipt replay across rotation, and the cutoff.
            before = time.monotonic()
            rotated = administration({"version": 1, "operation": "rotate-credential",
                                      "credentialId": credential_a["credentialId"],
                                      "expiresAt": "2999-01-01T00:00:00Z", "outputFile": str(work / "credential-a2")})
            after = time.monotonic()
            outputs.append(work / "credential-a2")
            bearers["a2"] = (work / "credential-a2").read_bytes().decode("ascii")
            a2_auth = {"Authorization": "Bearer " + bearers["a2"]}
            credential_a2 = rotated["result"]["credential"]
            assert rotated["result"]["previousCredentialId"] == credential_a["credentialId"]
            metadata = listed()
            old, new = metadata[credential_a["credentialId"]], metadata[credential_a2["credentialId"]]
            assert old["state"] == "active" and old["expiresAt"] == "2999-01-01T00:00:00Z", ("predecessor during overlap", old)
            assert new["state"] == "active" and new["clientId"] == old["clientId"] and new["scopes"] == old["scopes"]
            for name, authorized in (("A", a_auth), ("A'", a2_auth)):
                for path in ("/v1/capabilities", base + "/control", approval):
                    status, value = status_of(path, authorized)
                    assert status == 200, ("overlap authentication", name, path, status, value.get("code"))
            _, enqueue_path, enqueue_headers, enqueue_payload, receipt_uri, _ = next(item for item in a_attempts if item[0] == "enqueue")
            status, replayed, _, _ = exchange(enqueue_path, enqueue_headers | a2_auth, method="POST", payload=enqueue_payload)
            assert status == 202 and replayed["links"]["self"] == receipt_uri, ("rotated replay", status, replayed.get("code"))
            validate("CommandReceipt", replayed)
            status, original = status_of(receipt_uri, a2_auth)
            assert status == 200 and original["id"] == replayed["id"] and original["operation"] == "enqueue"
            # Four drafts with large literals make the overview of this client
            # a page set of at least four pages for step 3.
            drafts = []
            for _ in range(4):
                draft = create_request(a2_auth)
                a2_client = mixed_client(capabilities, a2_auth)
                current, tag, _ = a2_client[0](draft["links"]["self"], "Request")
                a2_client[2](draft["links"]["self"], {"operation": "set-input", "input": {
                    "name": workflow["inputs"][0]["name"], "source": "literal", "value": "x" * 600000}}, tag)
                drafts.append(draft["id"])
            last_accepted = None
            while True:
                status, value = status_of("/v1/capabilities", a_auth)
                now = time.monotonic()
                if status == 401:
                    break
                assert status == 200 and now < after + 65, ("predecessor during overlap", status, value.get("code"))
                last_accepted = now
                time.sleep(0.25)
            assert last_accepted is not None and before + 59.5 <= now <= after + 63, (
                "the predecessor cutoff is not sixty seconds after rotation", now - before, now - after)
            assert value["code"] == "unauthenticated"
            operation_id = receipt_uri.rsplit("/", 1)[1]
            preparation = next(item for item in a_attempts if item[0] == "approve")[1]
            refused_paths = ["/v1/capabilities", "/v1/profiles", "/v1/snapshot", "/v1/workflows?profileId=profile_1",
                             "/v1/workflows/" + workflow["id"], created["links"]["self"], preparation, receipt_uri,
                             base, base + "/control", base + "/snapshot", base + "/outputs", "/v1/decisions/" + head,
                             "/v1/artifacts/artifact_" + "0" * 32, "/v1/events?after=" + cursor]
            for path in refused_paths:
                status, value = status_of(path, a_auth)
                assert status == 401 and value["code"] == "unauthenticated", ("predecessor after cutoff", path, status)
            status, value = status_of("/v1/events?after=" + cursor, a_auth, headers={"Accept": "text/event-stream"})
            assert status == 401, ("predecessor stream after cutoff", status)
            key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
            status, value = status_of("/v1/requests", a_auth, method="POST", payload=create,
                                      headers={"Content-Type": "application/json", "Idempotency-Key": key})
            assert status == 401, ("predecessor POST after cutoff", status)
            status, value = status_of(enqueue_path, a_auth, method="POST", payload=enqueue_payload, headers=enqueue_headers)
            assert status == 401, ("predecessor replay after cutoff", status)
            status, value = status_of("/v1/capabilities", a2_auth)
            assert status == 200, "the rotated credential outlives the predecessor cutoff"
            metadata = listed()
            old, new = metadata[credential_a["credentialId"]], metadata[credential_a2["credentialId"]]
            assert old["state"] == "revoked" and old["expiresAt"] == "2999-01-01T00:00:00Z", ("predecessor after cutoff", old)
            assert new["state"] == "active"
            print(f"PASS credential-lifecycle step 2: A' rotated from A; A and A' both authenticated during the overlap; A' replayed",
                  f"the retained enqueue receipt {operation_id} through the Idempotency-Key of A; A was refused 401 on",
                  f"{len(refused_paths) + 3} routes from {now - before:.2f} s after the rotation start while list-credentials",
                  "reports A revoked with expiry 2999-01-01T00:00:00Z still in the future", flush=True)

            # Step 3. Revocation of A' during a retained page set, an open
            # stream, a known receipt and a known outputs page.
            status, first, raw = request("/v1/snapshot", a2_auth)
            assert status == 200, ("overview page", status, first.get("code"))
            validate("OverviewSnapshot", first, raw)
            assert first["page"]["index"] == 0 and first["page"]["next"] is not None
            status, second, raw = request(first["page"]["next"], a2_auth)
            assert status == 200 and second["page"]["setId"] == first["page"]["setId"], ("second page", status, second.get("code"))
            validate("OverviewSnapshot", second, raw)
            # A page token binds its client. Credential B presents the retained
            # continuation of A' and receives view-expired, and A' then reads
            # that page of its retained set.
            status, value = status_of(second["page"]["next"], b_auth)
            assert status == 410 and value["code"] == "view-expired", ("foreign page token", status, value.get("code"))
            status, third, raw = request(second["page"]["next"], a2_auth)
            assert status == 200 and third["page"]["setId"] == first["page"]["setId"], ("third page", status, third.get("code"))
            validate("OverviewSnapshot", third, raw)
            continuation = third["page"]["next"]
            assert continuation is not None, "the overview page set has fewer than four pages"
            connection, stream, block = open_stream("/v1/events?after=" + first["cursor"], a2_auth)
            try:
                for path in (receipt_uri, base + "/outputs"):
                    status, value = status_of(path, a2_auth)
                    assert status == 200, ("retained read before revocation", path, status, value.get("code"))
                administration({"version": 1, "operation": "revoke-credential", "credentialId": credential_a2["credentialId"]})
                ended = stream_ends(stream, 15)
            finally:
                stream.close()
                connection.close()
            assert ended, "the open stream of the revoked credential did not end"
            for path in (continuation, receipt_uri, base + "/outputs"):
                status, value = status_of(path, a2_auth)
                assert status == 401 and value["code"] == "unauthenticated", ("revoked retained read", path, status)
            key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
            status, value = status_of("/v1/requests", a2_auth, method="POST", payload=create,
                                      headers={"Content-Type": "application/json", "Idempotency-Key": key})
            assert status == 401, ("revoked POST", status)
            assert listed()[credential_a2["credentialId"]]["state"] == "revoked"
            b_client = mixed_client(capabilities, b_auth)
            control, _, _ = b_client[0](base + "/control", "RunControl")
            assert control["supervision"] == "owned" and control["decisionHeadId"] == head, (
                "the revocation stopped the live run", control["supervision"], control["decisionHeadId"])
            # The overview now holds the large drafts, so B reads the run and its
            # decisions directly.
            _, answered_by_b, recovered_by_b = drive_mixed(run, b_client, overview=False)
            assert answered_by_b == 1 and recovered_by_a + recovered_by_b >= 1
            artifact = verified_download(run, b_client, b_auth)
            for authorized in (a2_auth, a_auth):
                status, value = status_of(artifact["download"], authorized, headers={"Accept": "application/octet-stream"})
                assert status == 401 and value["code"] == "unauthenticated", ("revoked download", status)
            print("PASS credential-lifecycle step 3: after revoking A', its page continuation, command receipt, outputs page,",
                  "artifact download and new POST each returned 401 and its open stream ended; B then saw the run owned,",
                  "answered the question, and the run reached terminal success with verified bytes", flush=True)

            # Step 4. The scope boundary. The administration command refuses
            # reload-profiles, and no local operation changes the scopes or
            # profiles of a credential, so an observe-only credential shows it.
            administration({"version": 1, "operation": "reload-profiles"}, refused="state-conflict")
            credential_o, o_auth = issue("o", ["observe"])
            for path in ("/v1/profiles", base, base + "/control", base + "/outputs"):
                status, value = status_of(path, o_auth)
                assert status == 200, ("observe-only read", path, status, value.get("code"))
            # A receipt read requires observe and the scopes of its operation, so
            # the receipt of the enqueue, a submit operation, stays hidden.
            status, value = status_of(receipt_uri, o_auth)
            assert status == 403 and value["code"] == "insufficient-scope", ("observe-only receipt read", status)
            for name, authorized in (("observe-only", o_auth), ("B", b_auth)):
                key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
                status, value = status_of("/v1/requests", authorized, method="POST", payload=create,
                                          headers={"Content-Type": "application/json", "Idempotency-Key": key})
                assert status == 403 and value["code"] == "insufficient-scope", ("submit without scope", name, status)
            print("PASS credential-lifecycle step 4: the administration command refused reload-profiles with state-conflict; an",
                  "observe-only credential read the run with 200, and received 403 insufficient-scope for the enqueue receipt",
                  "and for POST, as did B without submit; B presenting the retained page token of A' received 410 view-expired",
                  "while A' then read that page", flush=True)
            status, value = status_of("/v1/capabilities", {"Authorization": "Bearer " + synthetic})
            assert status == 401
        finally:
            if process.poll() is None:
                process.terminate()
            process.wait(timeout=25)
            (work / "server-0.exit").write_text(str(process.returncode) + "\n")
    assert not (work / "admin/admin.sock").exists(), "joined original local administration leaves no socket"

    # Step 5. No bearer and no marker bytes in any fixture file except the
    # credential output files.
    for path in outputs:
        assert path.read_bytes().decode("ascii") in bearers.values(), "a credential output file does not hold its bearer"
    needles = [("bearer " + name, value.encode()) for name, value in bearers.items()]
    needles += [("ambient marker", marker.encode()), ("synthetic bearer marker", synthetic.encode())]
    scanned = []
    for path in sorted(work.rglob("*")):
        if path in outputs or path.is_symlink() or not path.is_file():
            continue
        data = path.read_bytes()
        found = [name for name, needle in needles if needle in data]
        assert not found, ("secret bytes in a fixture file", str(path.relative_to(work)), found)
        scanned.append(path.relative_to(work))
    names = [str(path) for path in scanned]
    required = {"server stdout": ["server-0.stdout"], "server stderr": ["server-0.stderr"],
                "manager log": [name for name in names if name.startswith("manager/flow/") and name.endswith(".ndjson")],
                "run flow log": [name for name in names if name.startswith("manager/runs/") and name.endswith("/flow.ndjson")],
                "run events": [name for name in names if name.startswith("manager/runs/") and name.endswith("/events.ndjson")],
                "database": [name for name in names if name.endswith("coordination.sqlite3")]}
    missing = [kind for kind, found in required.items() if not found or not all(name in names for name in found)]
    assert not missing, ("the scan did not cover", missing)
    print(f"PASS credential-lifecycle step 5: {len(scanned)} fixture files, including server output, the manager log, the run",
          f"flow and event logs and the database, hold none of {len(bearers)} bearers, the ambient marker or the synthetic",
          f"bearer marker; {workers} live worker processes show no ambient marker", flush=True)


if lifecycle:
    credential_lifecycle()
    raise SystemExit(0)


# The fixed bytes that warp-tls 3.4.14 writes for DenyInsecure "HTTPS required"
# before it closes a plaintext connection. Its source string continues the
# first three header lines with twelve spaces, a backslash and the letter r
# before each line feed, so these bytes are not a well-formed HTTP response.
PLAINTEXT_REFUSAL = (b"HTTP/1.1 426 Upgrade Required" + b" " * 12 + b"\\r\n"
                     b"Upgrade: TLS/1.0, HTTP/1.1" + b" " * 12 + b"\\r\n"
                     b"Connection: Upgrade" + b" " * 12 + b"\\r\n"
                     b"Content-Type: text/plain\r\n\r\nHTTPS required")
ALLOWED_ORIGIN = "https://example.invalid"
# Header names that a response may carry besides CORS headers when it holds
# no resource state: the protected headers and the Warp transport headers.
TRANSPORT_HEADERS = {"cache-control", "x-content-type-options", "vary", "date", "server", "content-length",
                     "transfer-encoding"}


class Replay:
    """Received response bytes presented to http.client as a socket."""
    def __init__(self, data):
        self.data = data

    def makefile(self, mode):
        return io.BytesIO(self.data)


def boundary_checks():
    """WM-024 through the real TLS 1.3 manager, one PASS line per negative."""
    host = f"127.0.0.1:{port}"
    authorization = "Bearer " + bearer
    responses = []

    def connect(timeout=10):
        return context.wrap_socket(socket.create_connection(("127.0.0.1", port), timeout=timeout),
                                   server_hostname="127.0.0.1")

    def read_response(connection, method):
        response = http.client.HTTPResponse(connection, method=method)
        response.begin()
        body = response.read(2097153)
        headers = [(name.lower(), value) for name, value in response.getheaders()]
        return response.status, headers, body

    def check(status, headers, body):
        """Every response carries the protected headers and exposes Location
        only on 201 and 202. A refusal is a frozen-contract problem."""
        names = [name for name, _ in headers]
        received = dict(headers)
        assert received.get("cache-control") == "no-store", ("Cache-Control", status, headers)
        assert received.get("x-content-type-options") == "nosniff", ("nosniff", status, headers)
        assert received.get("vary") == "Origin", ("Vary", status, headers)
        assert names.count("vary") == 1 and names.count("cache-control") == 1, ("duplicate protected header", headers)
        assert "location" not in received or status in (201, 202), ("Location outside 201 and 202", status, headers)
        assert not 300 <= status < 400, ("redirect", status, headers)
        responses.append(status)
        if status >= 400:
            value = frozen.parse_json(body)
            validate("Problem", value, body)
            return value["code"]
        return None

    def raw(data, method="GET", timeout=10):
        """Send raw request bytes over one new TLS connection and read one response."""
        with connect(timeout) as connection:
            connection.sendall(data)
            status, headers, body = read_response(connection, method)
        return status, check(status, headers, body), dict(headers), body

    def compose(method, target, fields, body=b""):
        lines = [f"{method} {target} HTTP/1.1"] + [f"{name}: {value}" for name, value in fields]
        return ("\r\n".join(lines) + "\r\n\r\n").encode() + body

    def get(target, fields=None, method="GET"):
        base = [("Host", host), ("Authorization", authorization)] if fields is None else fields
        return raw(compose(method, target, base), method)

    def refused(result, status, code, what):
        assert result[0] == status and (code is None or result[1] == code), (what, result[0], result[1])

    environment = dict(os.environ)
    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors, env=environment)
        try:
            wait_ready(process)
            status, capabilities, _ = request("/v1/capabilities", {"Authorization": authorization})
            assert status == 200
            validate("Capabilities", capabilities)
            limit = int(capabilities["limits"]["globalConnections"])
            assert limit == configuration["limits"]["globalConnections"]
            refused(get("/v1/capabilities"), 200, None, "authorized control request")

            # Plaintext HTTP bytes receive only the fixed DenyInsecure refusal.
            for data in (compose("GET", "/v1/capabilities", [("Host", host), ("Authorization", authorization)]),
                         compose("GET", "/v1/unknown", [("Host", host)]),
                         compose("POST", "/v1/requests", [("Host", host), ("Authorization", authorization),
                                                          ("Content-Type", "application/json"), ("Content-Length", "2")], b"{}")):
                with socket.create_connection(("127.0.0.1", port), timeout=10) as plain:
                    plain.sendall(data)
                    received = bytearray()
                    while True:
                        chunk = plain.recv(65536)
                        if not chunk:
                            break
                        received.extend(chunk)
                        assert len(received) <= 65536
                assert bytes(received) == PLAINTEXT_REFUSAL, ("plaintext refusal", bytes(received))
            print("PASS boundary plaintext: three plaintext HTTP requests, one with a valid bearer, each received only the fixed",
                  "warp-tls DenyInsecure bytes (426 Upgrade Required, text/plain \"HTTPS required\") and a close, with no",
                  "resource state, no authentication and no bearer path", flush=True)

            legacy = ssl.create_default_context(cafile=str(cert))
            legacy.minimum_version = legacy.maximum_version = ssl.TLSVersion.TLSv1_2
            try:
                with legacy.wrap_socket(socket.create_connection(("127.0.0.1", port), timeout=10),
                                        server_hostname="127.0.0.1") as connection:
                    raise AssertionError("a TLS 1.2-only client completed a handshake " + str(connection.version()))
            except ssl.SSLError as failure:
                reason = failure.reason
            print("PASS boundary TLS 1.2: a TLS 1.2-only client was refused during the handshake:", reason, flush=True)

            # Host.
            refused(raw(b"GET /v1/capabilities HTTP/1.1\r\nAuthorization: " + authorization.encode() + b"\r\n\r\n"),
                    400, "malformed-request", "missing Host")
            refused(get("/v1/capabilities", [("Host", "untrusted.invalid"), ("Authorization", authorization)]),
                    400, "malformed-request", "different Host")
            refused(get("/v1/capabilities", [("Host", "127.0.0.1:1"), ("Authorization", authorization)]),
                    400, "malformed-request", "Host with another port")
            refused(get("/v1/capabilities", [("Host", "127.0.0.1"), ("Authorization", authorization)]),
                    400, "malformed-request", "Host without its port")
            for target in (f"https://{host}/v1/capabilities", f"http://{host}/v1/capabilities",
                           "https://untrusted.invalid/v1/capabilities"):
                refused(get(target), 400, "malformed-request", ("absolute-form target", target))
            refused(get("*", method="OPTIONS"), 400, "malformed-request", "asterisk-form target")
            print("PASS boundary Host: a missing Host, a different Host, another port, a Host without its port, three",
                  "absolute-form request targets and an asterisk-form OPTIONS target each returned 400 malformed-request",
                  "with a valid bearer", flush=True)

            # Paths.
            outcomes = {}
            for target in ("/v1//capabilities", "//v1/capabilities", "/v1/./capabilities", "/v1/../v1/capabilities",
                           "/v1/%2e/capabilities", "/v1/%2E%2E/v1/capabilities", "/v1/capabilities/", "/v1/",
                           "/v1/capabilities/.", "/./v1/capabilities"):
                result = get(target)
                assert result[0] in (400, 404), ("path refusal", target, result[0], result[1])
                outcomes[target] = f"{result[0]} {result[1]}"
            print("PASS boundary paths: empty, dot and trailing segments gave 400 or 404 and never a 3xx:", outcomes, flush=True)

            # Ambient authority carriers.
            for extra in (("Cookie", "session=not-authority"), ("Forwarded", "for=127.0.0.1"),
                          ("X-Forwarded-For", "127.0.0.1"), ("X-Forwarded-Host", host)):
                refused(get("/v1/capabilities", [("Host", host), ("Authorization", authorization), extra]),
                        400, "malformed-request", extra[0])
            for name in ("token", "access_token", "authorization", "Access_Token"):
                refused(get("/v1/capabilities?" + name + "=" + bearer, [("Host", host)]), 400, "malformed-request", name)
                refused(get("/v1/capabilities?" + name + "=" + bearer), 400, "malformed-request", name)
            print("PASS boundary ambient authority: Cookie, Forwarded, X-Forwarded-For, X-Forwarded-Host and query parameters",
                  "token, access_token, authorization and Access_Token each returned 400 malformed-request, with and without",
                  "a bearer header", flush=True)

            # Duplicate framing headers.
            refused(get("/v1/capabilities", [("Host", host), ("Authorization", authorization), ("Authorization", authorization)]),
                    400, "malformed-request", "duplicate Authorization")
            refused(get("/v1/capabilities", [("Host", host), ("Host", host), ("Authorization", authorization)]),
                    400, "malformed-request", "duplicate Host")
            refused(get("/v1/capabilities", [("Host", host), ("Authorization", authorization),
                                             ("Content-Length", "0"), ("Content-Length", "0")]),
                    400, "malformed-request", "duplicate Content-Length")
            print("PASS boundary duplicates: duplicate Authorization, Host and Content-Length each returned 400 malformed-request", flush=True)

            key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
            mutation = [("Host", host), ("Authorization", authorization), ("Content-Type", "application/json"),
                        ("Idempotency-Key", key)]
            body = b'{"workflowId":"workflow_x"}'
            refused(raw(compose("POST", "/v1/requests", mutation + [("Transfer-Encoding", "chunked"), ("Content-Length", str(len(body)))],
                                f"{len(body):x}\r\n".encode() + body + b"\r\n0\r\n\r\n"), "POST"),
                    400, "malformed-request", "Transfer-Encoding with Content-Length")
            print("PASS boundary Transfer-Encoding: Transfer-Encoding with Content-Length returned 400 malformed-request", flush=True)
            for coding in ("gzip", "identity"):
                refused(raw(compose("POST", "/v1/requests", mutation + [("Content-Encoding", coding), ("Content-Length", str(len(body)))],
                                    body), "POST"), 415, "content-coding-refused", ("Content-Encoding", coding))
            refused(get("/v1/capabilities", [("Host", host), ("Authorization", authorization), ("Content-Encoding", "gzip")]),
                    415, "content-coding-refused", "Content-Encoding on GET")
            print("PASS boundary Content-Encoding: gzip and identity on POST and gzip on GET each returned 415 content-coding-refused", flush=True)

            duplicate = b'{"workflowId":"workflow_a","workflowId":"workflow_b"}'
            refused(raw(compose("POST", "/v1/requests", mutation + [("Content-Length", str(len(duplicate)))], duplicate), "POST"),
                    400, "duplicate-field", "duplicate JSON field")
            print("PASS boundary duplicate field: a JSON body with a repeated member returned 400 duplicate-field", flush=True)

            # The strict decoder checks members in order, so a repeated member
            # after the nested one is reached only when the nesting is admitted.
            def nested(depth):
                return b'{"extra":' + b"[" * (depth - 1) + b"]" * (depth - 1) + b',"extra":1}'
            deep = raw(compose("POST", "/v1/requests", mutation + [("Content-Length", str(len(nested(65))))], nested(65)), "POST")
            refused(deep, 400, "malformed-request", "JSON nesting of depth 65")
            shallow = raw(compose("POST", "/v1/requests", mutation + [("Content-Length", str(len(nested(64))))], nested(64)), "POST")
            refused(shallow, 400, "duplicate-field", "JSON nesting of depth 64")
            print("PASS boundary nesting: JSON nesting of depth 65 returned 400 malformed-request, while the same body at depth",
                  "64 passed the nesting check and reached its repeated member, which returned 400 duplicate-field", flush=True)

            # A declared body above 2 MiB refuses before the body is read.
            started = time.monotonic()
            refused(raw(compose("POST", "/v1/requests", mutation + [("Content-Length", str(2097153))]), "POST", timeout=10),
                    413, "size-limit", "declared body above 2 MiB")
            elapsed = time.monotonic() - started
            assert elapsed < 5, ("declared body refusal waited for the body", elapsed)
            print(f"PASS boundary body limit: Content-Length 2097153 with no body bytes returned 413 size-limit after {elapsed:.2f} s,",
                  "before any body byte was sent", flush=True)

            # Header limits.
            refused(get("/v1/capabilities", [("Host", host), ("Authorization", authorization), ("X-Pad", "a" * 16500)]),
                    400, "malformed-request", "headers above 16 KiB")
            fields = [("Host", host), ("Authorization", authorization)]
            hundred = fields + [(f"X-Field-{index}", "v") for index in range(100 - len(fields))]
            refused(get("/v1/capabilities", hundred), 200, None, "exactly 100 header fields")
            over = hundred + [("X-Field-extra", "v")]
            many = get("/v1/capabilities", over)
            refused(many, 413, "size-limit", "101 header fields")
            print("PASS boundary headers: a 16.5 KiB header block returned 400 malformed-request; exactly 100 header fields were",
                  "served with 200, and 101 header fields returned 413 size-limit", flush=True)

            # CORS preflight and origin refusals.
            preflight = [("Host", host), ("Origin", ALLOWED_ORIGIN), ("Access-Control-Request-Method", "GET"),
                         ("Access-Control-Request-Headers", "authorization, if-match")]
            status, code, headers, body = get("/v1/capabilities", preflight, method="OPTIONS")
            assert status == 204 and not body, ("allowed preflight", status, code)
            assert headers.get("access-control-allow-origin") == ALLOWED_ORIGIN
            assert headers.get("access-control-allow-methods") == "GET"
            assert headers.get("access-control-allow-headers") == "authorization, if-match"
            extra = [name for name in headers if not name.startswith("access-control-") and name not in TRANSPORT_HEADERS]
            assert not extra and "etag" not in headers and "content-type" not in headers, ("preflight state", headers)
            actual = get("/v1/capabilities", [("Host", host), ("Origin", ALLOWED_ORIGIN)])
            refused(actual, 401, "unauthenticated", "actual request without a bearer")
            assert actual[2].get("access-control-allow-origin") == ALLOWED_ORIGIN
            print("PASS boundary preflight: an allowed origin, method and headers without a bearer returned 204 with only",
                  sorted(headers), "and no body; the same actual request without a bearer returned 401 unauthenticated", flush=True)
            for name, fields in (("forbidden origin", [("Host", host), ("Origin", "https://untrusted.invalid"),
                                                       ("Access-Control-Request-Method", "GET")]),
                                 ("null origin", [("Host", host), ("Origin", "null"), ("Access-Control-Request-Method", "GET")]),
                                 ("forbidden method", [("Host", host), ("Origin", ALLOWED_ORIGIN),
                                                       ("Access-Control-Request-Method", "POST")]),
                                 ("forbidden header", [("Host", host), ("Origin", ALLOWED_ORIGIN),
                                                       ("Access-Control-Request-Method", "GET"),
                                                       ("Access-Control-Request-Headers", "authorization, x-custom")]),
                                 ("absent origin", [("Host", host), ("Access-Control-Request-Method", "GET")])):
                result = get("/v1/capabilities", fields, method="OPTIONS")
                refused(result, 403, "origin-refused", ("preflight", name))
                assert not [key for key in result[2] if key.startswith("access-control-allow-")] or name in (
                    "forbidden method", "forbidden header"), ("refused preflight grants", name, result[2])
            for origin in ("https://untrusted.invalid", "null", "https://example.invalid:443", "http://example.invalid"):
                result = get("/v1/capabilities", [("Host", host), ("Authorization", authorization), ("Origin", origin)])
                refused(result, 403, "origin-refused", ("actual request origin", origin))
                assert not [key for key in result[2] if key.startswith("access-control-")], ("refused origin exposure", origin)
            print("PASS boundary origin: a preflight with a forbidden origin, Origin null, a forbidden method, a forbidden header",
                  "or no origin, and an authorized request from four origins outside the allowlist, each returned 403",
                  "origin-refused", flush=True)
            _, _, allowed, _ = get("/v1/capabilities", [("Host", host), ("Authorization", authorization), ("Origin", ALLOWED_ORIGIN)])
            assert allowed.get("access-control-allow-origin") == ALLOWED_ORIGIN
            assert allowed.get("access-control-expose-headers") == "ETag, Location, Retry-After"
            _, _, native_headers, _ = get("/v1/capabilities")
            assert not [key for key in native_headers if key.startswith("access-control-")], native_headers
            # A created draft is the one 201 of this mode. Its Location is exposed
            # to the allowed origin.
            status, catalogue, _ = request("/v1/workflows?profileId=profile_1", {"Authorization": authorization})
            assert status == 200
            workflow = catalogue["items"][0]
            create = json.dumps({"workflowId": workflow["id"], "descriptorRevision": workflow["revision"],
                                 "profileId": workflow["profileId"], "profileRevision": workflow["profileRevision"]},
                                separators=(",", ":")).encode()
            key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
            status, code, created, body = raw(compose("POST", "/v1/requests", [
                ("Host", host), ("Authorization", authorization), ("Origin", ALLOWED_ORIGIN), ("Content-Type", "application/json"),
                ("Idempotency-Key", key), ("Content-Length", str(len(create)))], create), "POST")
            assert status == 201 and created.get("location") == frozen.parse_json(body)["links"]["self"], ("created draft", status, code)
            assert created.get("access-control-expose-headers") == "ETag, Location, Retry-After"
            assert created.get("access-control-allow-origin") == ALLOWED_ORIGIN
            print("PASS boundary exposure: every response carried Cache-Control no-store, nosniff and Vary: Origin; ETag,",
                  "Location and Retry-After were exposed only to the allowed origin, including the Location of a 201 draft,",
                  f"and no response outside 201 and 202 carried Location ({len(responses)} responses checked)", flush=True)

            # Slow input.
            started = time.monotonic()
            received = b""
            with connect(40) as connection:
                connection.sendall(b"GET /v1/capabilities HTTP/1.1\r\nHost: " + host.encode() + b"\r\n")
                connection.settimeout(0.5)
                closed = None
                while closed is None and time.monotonic() - started < 40:
                    try:
                        connection.sendall(b"X")
                    except (ConnectionError, ssl.SSLError, OSError):
                        closed = time.monotonic() - started
                        break
                    try:
                        chunk = connection.recv(65536)
                        if not chunk:
                            closed = time.monotonic() - started
                        received += chunk
                    except (TimeoutError, socket.timeout):
                        pass
                    except (ConnectionError, ssl.SSLError, OSError):
                        closed = time.monotonic() - started
            assert closed is not None and 14 <= closed <= 35, ("trickled headers", closed)
            assert received == b"", ("trickled headers received a response", received[:200])
            print(f"PASS boundary slow headers: headers trickled one byte every 0.5 s were closed after {closed:.1f} s with no",
                  "response bytes", flush=True)
            key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
            slow_fields = [("Host", host), ("Authorization", authorization), ("Content-Type", "application/json"),
                           ("Idempotency-Key", key), ("Content-Length", "200")]
            started = time.monotonic()
            with connect(40) as connection:
                connection.sendall(compose("POST", "/v1/requests", slow_fields))
                connection.settimeout(0.5)
                answered = None
                reply = bytearray()
                ended = None
                while answered is None and time.monotonic() - started < 40:
                    try:
                        connection.sendall(b" ")
                    except (ConnectionError, ssl.SSLError, OSError) as failure:
                        ended = (time.monotonic() - started, repr(failure))
                        break
                    # Application data only. The ssl module consumes the TLS 1.3
                    # session tickets that make the raw socket readable at once.
                    try:
                        chunk = connection.recv(65536)
                    except (TimeoutError, socket.timeout):
                        continue
                    answered = time.monotonic() - started
                    reply.extend(chunk)
                assert answered is not None and reply, ("trickled body received no response", answered, ended)
                connection.settimeout(10)
                while True:
                    try:
                        chunk = connection.recv(65536)
                    except (ConnectionError, ssl.SSLError):
                        break
                    if not chunk:
                        break
                    reply.extend(chunk)
                    assert len(reply) <= 1048576
            status, headers, body = read_response(Replay(bytes(reply)), "POST")
            code = check(status, headers, body)
            assert status == 400 and code == "malformed-request" and 14 <= answered <= 20, ("trickled body", status, code, answered)
            print(f"PASS boundary slow body: a JSON body trickled one byte every 0.5 s returned 400 malformed-request after",
                  f"{answered:.1f} s", flush=True)

            # Connection limit.
            held = [connect() for _ in range(limit)]
            waiting = context.wrap_socket(socket.create_connection(("127.0.0.1", port), timeout=10),
                                          server_hostname="127.0.0.1", do_handshake_on_connect=False)
            try:
                waiting.settimeout(3)
                try:
                    waiting.do_handshake()
                    raise AssertionError("a connection above the limit was served while the limit was held")
                except (TimeoutError, socket.timeout):
                    pass
                held.pop().close()
                waiting.settimeout(10)
                released = time.monotonic()
                waiting.do_handshake()
                waiting.sendall(compose("GET", "/v1/capabilities", [("Host", host), ("Authorization", authorization)]))
                status, headers, body = read_response(waiting, "GET")
                check(status, headers, body)
                assert status == 200, ("released connection", status)
                served = time.monotonic() - released
            finally:
                waiting.close()
                for connection in held:
                    connection.close()
            refused(get("/v1/capabilities"), 200, None, "authorized request after the connection limit")
            print(f"PASS boundary connections: with {limit} idle TLS connections held, one more connection received no",
                  f"handshake for 3 s; it completed and was served 200 {served:.2f} s after one held connection was released,",
                  "and a new authorized request then returned 200", flush=True)
        finally:
            if process.poll() is None:
                process.terminate()
            process.wait(timeout=25)
            (work / "server-0.exit").write_text(str(process.returncode) + "\n")
    assert not (work / "admin/admin.sock").exists(), "joined original local administration leaves no socket"
    for channel in ("stdout", "stderr"):
        assert bearer.encode() not in (work / f"server-0.{channel}").read_bytes()
    print("PASS boundary: every WM-024 negative held against the running TLS 1.3 manager, and the manager shut down",
          "with its original joins", flush=True)


if boundary:
    boundary_checks()
    raise SystemExit(0)


def legacy_frontend_run():
    """Complete one scripted prompt-source run through the local frontend
    session of the runner, with the legacy retention root as its state
    directory. The frontend writes a version-2 supervisor manifest and a
    runtime store with a result. Returns the run directory."""
    workspace = work / "legacy-workspace"
    workspace.mkdir(mode=0o700)
    environment = {key: value for key, value in os.environ.items() if not key.startswith("AGENT_CAT_")}
    environment["XDG_CONFIG_HOME"] = str(workspace / "config")
    prepare = {"version": 1, "operation": "prepare", "workflow": "prompt-source", "stateDirectory": str(LEGACY_ROOT),
               "targetArguments": ["--scripted"],
               "inputs": [{"name": "input", "source": "literal", "value": "legacy history fixture"}]}
    with (work / "legacy-frontend.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "frontend"], cwd=workspace, env=environment,
                                   stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=errors)
        try:
            process.stdin.write(json.dumps(prepare).encode() + b"\n")
            process.stdin.flush()
            preview = json.loads(process.stdout.readline())
            assert preview["operation"] == "prepared", ("legacy frontend preparation", preview)
            process.stdin.write(json.dumps({"version": 1, "operation": "start",
                                            "approvalId": preview["approvalId"]}).encode() + b"\n")
            process.stdin.flush()
            frames = [json.loads(line) for line in process.stdout]
            assert process.wait(timeout=60) == 0, ("legacy frontend exit", process.returncode)
        finally:
            if process.poll() is None:
                process.kill()
                process.wait()
    assert frames and frames[-1]["event"]["type"] == "run.completed", ("legacy frontend run", frames[-1:])
    directory = LEGACY_ROOT / "runs" / preview["runId"]
    manifest = json.loads((directory / "supervisor-manifest.json").read_bytes())
    assert manifest["frontendManifestVersion"] == 2 and "invocation" not in manifest
    return directory


def clone_legacy_runs(directory, count):
    """Copy the completed run directory count times into the same retention
    root, each copy under a new run identifier, so that the root holds
    count + 1 legacy entries without count more runs. The catalogue reader
    checks the run identifier of the supervisor manifest against the
    directory name, the runtime manifest and every event envelope against the
    supervisor manifest, and the result document against the run. Each copy
    therefore replaces the original identifier in every file that holds it,
    and then records the size and SHA-256 digest of its rewritten result in
    the run.completed event. Each file and directory of a copy keeps the
    private mode of its original. Returns the result bytes of every entry."""
    original = directory.name.encode()
    results = [(directory / "runtime" / "result.json").read_bytes()]
    for number in range(1, count + 1):
        name = f"{directory.name}-clone-{number:03d}"
        target = directory.parent / name
        shutil.copytree(directory, target, symlinks=True)
        for path in sorted(target.rglob("*")):
            source_mode = stat.S_IMODE((directory / path.relative_to(target)).lstat().st_mode)
            assert stat.S_IMODE(path.lstat().st_mode) == source_mode, ("clone mode", path)
            if path.is_file() and original in (raw := path.read_bytes()):
                path.write_bytes(raw.replace(original, name.encode()))
        result = (target / "runtime" / "result.json").read_bytes()
        events = target / "runtime" / "events.ndjson"
        lines = events.read_bytes().splitlines()
        completed = json.loads(lines[-1])
        reference = completed["event"].get("result") or {}
        assert completed["event"]["type"] == "run.completed" and reference.get("path") == "result.json", (
            "clone result reference", completed["event"])
        reference.update(bytes=str(len(result)), sha256=hashlib.sha256(result).hexdigest())
        lines[-1] = json.dumps(completed, ensure_ascii=False, separators=(",", ":"), sort_keys=True).encode()
        events.write_bytes(b"\n".join(lines) + b"\n")
        assert json.loads((target / "supervisor-manifest.json").read_bytes())["runId"] == name
        assert json.loads(result)["runId"] == name
        results.append(result)
    return results


def page_checks():
    """WM-025 page and read verification through the real HTTPS manager,
    numbered as in the B13 requirement. Each case prints one PASS line."""
    authorized = {"Authorization": "Bearer " + bearer}
    bodies = []
    big = 900000

    def representation_tag(target, raw):
        return '"http_' + hashlib.sha256(target.encode() + b"\n" + raw).hexdigest() + '"'

    def page(target, credential, schema):
        """One page read. A 200 page must be schema-valid and carry the
        representation tag of its exact bytes. A 503 is a new bounded read."""
        deadline = time.monotonic() + 5
        while True:
            status, value, raw, received = exchange(target, credential)
            if status != 503 or time.monotonic() >= deadline:
                break
            time.sleep(0.05)
        if status == 200:
            validate(schema, value, raw)
            # The first page of an export or lineage collection carries the
            # strong collection revision, which an export or lineage POST
            # supplies as If-Match.
            expected = ('"' + value["page"]["revision"] + '"'
                        if re.fullmatch(r"/v1/runs/[A-Za-z0-9_-]+/(exports|lineage-requests)", target)
                        else representation_tag(target, raw))
            assert received.get("etag") == expected, ("page ETag", target, received.get("etag"))
            bodies.append((target, raw))
        return status, value

    def refused(target, credential, status, code, what):
        actual, value = page(target, credential, "Problem")
        assert actual == status and value.get("code") == code, (what, target, actual, value.get("code"))

    def opened(path, credential, schema):
        status, value = page(path, credential, schema)
        assert status == 200, ("first page", path, status, value.get("code"))
        assert value["page"]["index"] == 0 and value["page"]["next"] is not None, ("multi-page set", path)
        return value

    def rest(pages, credential, schema, between=None):
        """Read the remaining pages of an open set. The between callback runs
        once after the first page. Every page has the set, revision, count and
        index of its position."""
        value = pages[-1]
        while value["page"]["next"] is not None:
            if between is not None:
                between()
                between = None
            status, value = page(value["page"]["next"], credential, schema)
            assert status == 200, ("continuation", status, value.get("code"))
            for key in ("setId", "revision", "expiresAt", "totalItems"):
                assert value["page"][key] == pages[0]["page"][key], ("page set field", key)
            assert value["page"]["index"] == len(pages), ("page index", value["page"]["index"], len(pages))
            pages.append(value)
        return pages

    def whole(path, credential, schema, between=None):
        status, value = page(path, credential, schema)
        assert status == 200, ("first page", path, status, value.get("code"))
        assert value["page"]["index"] == 0
        return rest([value], credential, schema, between)

    def identities(pages):
        found = []
        for value in pages:
            for item in value["items"]:
                found.append((item["kind"], item[item["kind"]]["id"]) if "kind" in item and item["kind"] in item else item["id"])
        return found

    def union(pages):
        found = identities(pages)
        assert len(found) == len(set(found)), ("duplicate page items", len(found), len(set(found)))
        assert len(found) == pages[0]["page"]["totalItems"], ("missing page items", len(found), pages[0]["page"]["totalItems"])
        return set(found)

    def issue(name, scopes):
        output = work / ("credential-" + name)
        value = administration({"version": 1, "operation": "issue-credential", "label": "Pages " + name,
                                "scopes": scopes, "profileIds": ["profile_1"],
                                "expiresAt": "2999-01-01T00:00:00Z", "outputFile": str(output)})
        return value["result"]["credential"], {"Authorization": "Bearer " + output.read_bytes().decode("ascii")}

    def interrupted(target, credential):
        """Send one page request over a raw TLS connection with a small
        receive buffer, read the start of the response and reset the
        connection while the manager is still sending the page."""
        raw_socket = socket.socket()
        raw_socket.setsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF, 4096)
        raw_socket.settimeout(10)
        raw_socket.connect(("127.0.0.1", port))
        connection = context.wrap_socket(raw_socket, server_hostname="127.0.0.1")
        try:
            connection.sendall((f"GET {target} HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\n"
                                f"Authorization: {credential['Authorization']}\r\n\r\n").encode())
            start = connection.recv(64)
            assert start.startswith(b"HTTP/1.1 200"), ("interrupted page status", start[:32])
            connection.setsockopt(socket.SOL_SOCKET, socket.SO_LINGER, (1).to_bytes(4, sys.byteorder) + (0).to_bytes(4, sys.byteorder))
        finally:
            connection.close()

    environment = dict(os.environ)
    legacy_results = clone_legacy_runs(legacy_frontend_run(), LEGACY_ENTRIES - 1)
    assert len(set(legacy_results)) == LEGACY_ENTRIES
    # A binding of a path that is not a configured retention root refuses
    # the start before the listener opens.
    unbound = subprocess.run([str(runner), "--manager", "serve", "--config", str(config),
                              "--legacy-history", str(work / "unconfigured") + "=profile_1"],
                             capture_output=True, env=environment, timeout=60)
    assert unbound.returncode == 1 and b"manager configuration or HTTPS listener is unavailable" in unbound.stderr, (
        "unconfigured legacy root", unbound.returncode, unbound.stderr[-400:])
    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "--legacy-history", f"{LEGACY_ROOT}=profile_1",
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors, env=environment)
        try:
            wait_ready(process)
            status, capabilities, raw = request("/v1/capabilities", authorized)
            assert status == 200 and capabilities["limits"]["pageSetsPerClient"] == 2
            assert capabilities["limits"]["globalPageSets"] == 8 and capabilities["limits"]["pageSetLifetimeSeconds"] == 60
            status, catalogue, raw = request("/v1/workflows?profileId=profile_1", authorized)
            assert status == 200
            workflow = next(item for item in catalogue["items"] if item["name"] == "mixed-controls")
            create = json.dumps({"workflowId": workflow["id"], "descriptorRevision": workflow["revision"],
                                 "profileId": workflow["profileId"], "profileRevision": workflow["profileRevision"]},
                                separators=(",", ":")).encode()

            def create_request():
                key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
                status, created, raw = request("/v1/requests", authorized | {
                    "Content-Type": "application/json", "Idempotency-Key": key}, method="POST", payload=create)
                assert status == 201, ("request creation", status, created.get("code"))
                validate("Request", created, raw)
                return created

            # A terminal run gives the pages a run store, native identifiers
            # and a worker invocation for case 8.
            run = run_mixed(create_request(), workflow, capabilities, authorized)
            client = mixed_client(capabilities, authorized)
            observed, _, mutate, _ = client
            name = workflow["inputs"][0]["name"]

            def set_input(draft, value):
                _, tag, _ = observed(draft["links"]["self"], "Request")
                mutate(draft["links"]["self"], {"operation": "set-input", "input": {
                    "name": name, "source": "literal", "value": value}}, tag)

            drafts = []
            for letter in "abc":
                draft = create_request()
                set_input(draft, letter * big)
                drafts.append(draft)
            _, e_auth = issue("expiry", ["observe"])
            credential_v, v_auth = issue("view", ["observe"])
            credential_r, r_auth = issue("revoked", ["observe"])

            # The set of the expiry credential opens now and is read again
            # after its sixty-second lifetime.
            expiry_start = time.monotonic()
            expiring = opened("/v1/snapshot", e_auth, "OverviewSnapshot")
            status, second = page(expiring["page"]["next"], e_auth, "OverviewSnapshot")
            assert status == 200 and second["page"]["next"] is not None, ("expiry set continuation", status)
            expiring_token = second["page"]["next"]

            # Case 1. Every page of two multi-page sets.
            snapshot_pages = whole("/v1/snapshot", authorized, "OverviewSnapshot")
            request_pages = whole("/v1/requests", authorized, "RequestPage")
            snapshot_union, request_union = union(snapshot_pages), union(request_pages)
            assert len(snapshot_pages) >= 2 and len(request_pages) >= 2, (len(snapshot_pages), len(request_pages))
            assert {draft["id"] for draft in drafts} <= request_union
            assert {("request", draft["id"]) for draft in drafts} <= snapshot_union

            # Case 2. Binding and expiry.
            bound = opened("/v1/snapshot", authorized, "OverviewSnapshot")
            continuation = bound["page"]["next"]
            token = continuation.split("pageToken=", 1)[1]
            refused(continuation, other_authorized, 410, "view-expired", "another client")
            for target in ("/v1/requests?pageToken=" + token, f"/v1/runs/{run}/snapshot?pageToken=" + token,
                           f"/v1/decisions?runId={run}&pageToken=" + token, "/v1/decisions?pageToken=" + token):
                refused(target, authorized, 410, "view-expired", "another path or query")
            rest([bound], authorized, "OverviewSnapshot")
            viewed = opened("/v1/snapshot", v_auth, "OverviewSnapshot")
            rotated = administration({"version": 1, "operation": "rotate-credential",
                                      "credentialId": credential_v["credentialId"],
                                      "expiresAt": "2999-01-01T00:00:00Z", "outputFile": str(work / "credential-view2")})
            assert rotated["result"]["previousCredentialId"] == credential_v["credentialId"]
            v2_auth = {"Authorization": "Bearer " + (work / "credential-view2").read_bytes().decode("ascii")}
            status, _, _ = request("/v1/capabilities", v_auth)
            assert status == 200, "the rotated predecessor still authenticates during the overlap"
            refused(viewed["page"]["next"], v_auth, 410, "view-expired", "predecessor after the view change")
            refused(viewed["page"]["next"], v2_auth, 410, "view-expired", "successor after the view change")
            remaining = expiry_start + 62 - time.monotonic()
            if remaining > 0:
                time.sleep(remaining)
            refused(expiring_token, e_auth, 410, "view-expired", "token after its lifetime")
            print("PASS pages case 2: a continuation token returned 410 view-expired for another client, on four other",
                  "paths or queries, after a credential rotation changed the view (for the predecessor and the successor)",
                  "and 62 s after its set was reserved; the owner then read the refused set to its end", flush=True)

            # Case 3. The per-client quota, and retirement at the last page.
            held_snapshot = opened("/v1/snapshot", authorized, "OverviewSnapshot")
            held_requests = opened("/v1/requests", authorized, "RequestPage")
            status, value, _, _ = exchange("/v1/snapshot", authorized)
            assert status == 429 and value["code"] == "storage-quota", ("third page set", status, value.get("code"))
            validate("Problem", value)
            rest([held_snapshot], authorized, "OverviewSnapshot")
            print("PASS pages case 3: with two open sets of one client, a third first page returned 429 storage-quota",
                  "while the global bound of 8 had room", flush=True)

            # Case 6. An interrupted send releases its set. The client holds
            # one set, so a released interrupted set leaves room for one more.
            interrupted("/v1/snapshot", authorized)
            deadline = time.monotonic() + 5
            while True:
                status, value = page("/v1/snapshot", authorized, "OverviewSnapshot")
                if status == 200 or time.monotonic() >= deadline:
                    break
                assert status == 429 and value["code"] == "storage-quota", ("set after interruption", status, value.get("code"))
                time.sleep(0.05)
            assert status == 200 and value["page"]["next"] is not None, ("set after interruption", status, value.get("code"))
            after_interruption = value
            status, value, _, _ = exchange("/v1/snapshot", authorized)
            assert status == 429 and value["code"] == "storage-quota", ("quota after interruption", status, value.get("code"))
            rest([held_requests], authorized, "RequestPage")
            rest([after_interruption], authorized, "OverviewSnapshot")
            print("PASS pages case 6: a client reset its connection during a first page; the manager released that set,",
                  "so the client with one open set was admitted one more and then refused a third with 429; the last",
                  "pages of both sets then released them", flush=True)

            # Case 4. A mutation between page 1 and page 2.
            added = []
            retained = whole("/v1/requests", authorized, "RequestPage", between=lambda: added.append(create_request()))
            assert union(retained) == request_union, ("retained set items", union(retained) ^ request_union)
            assert added[0]["id"] not in identities(retained[1:]), "the retained page 2 lists the new request"
            fresh = whole("/v1/requests", authorized, "RequestPage")
            assert union(fresh) == request_union | {added[0]["id"]} and fresh[0]["page"]["revision"] != retained[0]["page"]["revision"]
            print("PASS pages case 4: a request created between page 1 and page 2 was absent from the", len(retained),
                  "pages of the retained set, which kept its revision and items, and a fresh set listed it", flush=True)

            # Case 5. Revocation.
            revoked = opened("/v1/snapshot", r_auth, "OverviewSnapshot")
            administration({"version": 1, "operation": "revoke-credential", "credentialId": credential_r["credentialId"]})
            refused(revoked["page"]["next"], r_auth, 401, "unauthenticated", "revoked continuation")
            print("PASS pages case 5: a revoked credential received 401 unauthenticated for the continuation of its open set", flush=True)

            # Case 1, completed. The same identities in one page after the
            # large literals are removed.
            for draft in drafts:
                _, tag, _ = observed(draft["links"]["self"], "Request")
                mutate(draft["links"]["self"], {"operation": "remove-input", "name": name}, tag)
            one_snapshot = whole("/v1/snapshot", authorized, "OverviewSnapshot")
            one_requests = whole("/v1/requests", authorized, "RequestPage")
            assert len(one_snapshot) == 1 and len(one_requests) == 1
            assert union(one_snapshot) == snapshot_union | {("request", added[0]["id"])}, "snapshot union differs from one page"
            assert union(one_requests) == request_union | {added[0]["id"]}, "request union differs from one page"
            print(f"PASS pages case 1: /v1/snapshot spanned {len(snapshot_pages)} pages and /v1/requests {len(request_pages)};",
                  "each page ETag equalled the representation tag of its exact bytes, and the union of each set had no",
                  "duplicate and no missing item against a later one-page read of the same view with smaller items", flush=True)

            # Case 7. One item larger than a page.
            oversized = create_request()
            set_input(oversized, "z" * 1100000)
            for path in ("/v1/requests", "/v1/snapshot"):
                refused(path, authorized, 413, "view-too-large", "oversized item")
            for path in ("/v1/runs", f"/v1/runs/{run}/snapshot"):
                whole(path, authorized, "RunPage" if path == "/v1/runs" else "RunSnapshot")
            print("PASS pages case 7: a request with one item larger than the page bound made /v1/requests and",
                  "/v1/snapshot return 413 view-too-large, and the refused sets held no capacity", flush=True)

            # Case 8. Redaction over every page body of this mode.
            for path, schema in (("/v1/runs", "RunPage"), ("/v1/decisions", "DecisionPage"),
                                 (f"/v1/decisions?runId={run}", "DecisionPage"), (f"/v1/runs/{run}/snapshot", "RunSnapshot"),
                                 (f"/v1/runs/{run}/outputs", "OutputPage"), (f"/v1/runs/{run}/exports", "ExportPage"),
                                 (f"/v1/runs/{run}/lineage-requests", "LineagePage"), ("/v1/profiles", "ProfilePage")):
                whole(path, authorized, schema)
            markers = private_markers() + [PAGES_ENVIRONMENT_MARKER.encode()]
            stores = work / "manager" / "runs" / "runs"
            assert stores.is_dir() and any(stores.iterdir()), "the run has no run store to redact"
            # The frozen run snapshot carries the runtime backend spelling of
            # its target and attempts, "acp:<adapter>", as targetLabel. That
            # public runtime label is the only permitted form of the adapter
            # name, and only in run snapshot pages. No other argv element may
            # appear in any page.
            runtime_label = b'"targetLabel":"acp:mixed-adapter"'
            labelled, leaked = 0, []
            for target, raw in bodies:
                if re.fullmatch(r"/v1/runs/[A-Za-z0-9_-]+/snapshot(\?pageToken=[A-Za-z0-9_-]+)?", target):
                    labelled += raw.count(runtime_label)
                    raw = raw.replace(runtime_label, b"")
                leaked += [(target, marker) for marker in markers if marker in raw]
            assert not leaked, ("page body holds private bytes", leaked[:4])
            assert labelled, "no run snapshot page carried the runtime target label"
            print(f"PASS pages case 8: {len(bodies)} page bodies hold none of {len(markers)} private markers: the fixture",
                  "root with the manager root and run stores, native run identifiers, argv and the worker environment value;",
                  f"the adapter name appears only in {labelled} runtime targetLabel values of run snapshot pages", flush=True)

            # Case 9. Two credentials download the same artifact at the same
            # time. The Store has two artifact response places, so neither
            # download is refused, and both receive the verified bytes.
            artifact = verified_download(run, client, authorized)
            _, d_auth = issue("download", ["observe"])
            rounds = 8
            for number in range(rounds):
                start = threading.Barrier(2)
                received = [None, None]

                def download(slot, credential):
                    connection = http.client.HTTPSConnection("127.0.0.1", port, context=context, timeout=7)
                    try:
                        connection.connect()
                        start.wait(timeout=7)
                        connection.request("GET", artifact["download"], headers=credential | {"Accept": "application/octet-stream"})
                        response = connection.getresponse()
                        received[slot] = (response.status, response.getheader("Content-Type"),
                                          response.read(int(artifact["bytes"]) + 1048577))
                    finally:
                        connection.close()

                threads = [threading.Thread(target=download, args=(slot, credential))
                           for slot, credential in enumerate((authorized, d_auth))]
                for thread in threads:
                    thread.start()
                for thread in threads:
                    thread.join(timeout=20)
                for slot, outcome in enumerate(received):
                    assert outcome is not None, ("concurrent download ended without a response", number, slot)
                    status, kind, body = outcome
                    assert status == 200, ("concurrent download refused", number, slot, status, body[:200])
                    assert kind == "application/octet-stream", ("concurrent download type", number, slot, kind)
                    assert len(body) == int(artifact["bytes"]) and hashlib.sha256(body).hexdigest() == artifact["sha256"], (
                        "concurrent download bytes", number, slot)
            print(f"PASS pages case 9: in {rounds} rounds, two credentials downloaded the same artifact at the same time",
                  "through the running manager, and both received its exact verified bytes", flush=True)

            # Case 10. The legacy entries of the bound retention root: the
            # completed run and its copies, more than the 256 legacy entries
            # that one window of /v1/runs decodes.
            run_pages = whole("/v1/runs", authorized, "RunPage")
            union(run_pages)
            items = [item for value in run_pages for item in value["items"]]
            assert [item["id"] for item in items] == sorted(item["id"] for item in items), "run collection order"
            legacy = [item for item in items if item.get("supervision") == "observer"]
            assert len(legacy) == LEGACY_ENTRIES, ("every legacy entry", len(legacy), LEGACY_ENTRIES)
            assert [item["id"] for item in items if item.get("supervision") != "observer"] == [run], "the managed run"
            assert len(run_pages) >= 2 and run_pages[0]["page"]["totalItems"] == LEGACY_ENTRIES + 1, (
                len(run_pages), run_pages[0]["page"]["totalItems"])
            prompt_source = next(item["id"] for item in catalogue["items"] if item["name"] == "prompt-source")
            for entry in legacy:
                validate("Run", entry)
                assert entry["id"] != run and entry["profileId"] == "profile_1" and entry["requestId"] is None
                assert entry["manifest"] == {"kind": "versioned", "frontendManifestVersion": 2}, entry["manifest"]
                assert entry["runtime"]["status"] == "succeeded" and entry["integrity"] == "valid", (entry["runtime"], entry["integrity"])
                assert entry["verification"]["state"] == "referenced", entry["verification"]
                assert entry["workflowId"] == prompt_source
            # The detail of the first, middle and last legacy entry. At least
            # two of the three are copies.
            for entry in (legacy[0], legacy[len(legacy) // 2], legacy[-1]):
                base = "/v1/runs/" + entry["id"]
                status, detail, raw, received = fetch(base, authorized)
                assert status == 200, ("legacy detail", status, detail.get("code"))
                validate("Run", detail, raw)
                assert detail == entry, ("legacy detail differs from its collection item", detail, entry)
                assert received.get("etag") == representation_tag(base, raw), ("legacy detail ETag", received.get("etag"))
            # The checks below use the last of these entries, its base path and its detail.
            status, again, _, _ = fetch(base, authorized)
            assert status == 200 and again == detail, "a second legacy detail read differs"

            def legacy_download(entry):
                connection = http.client.HTTPSConnection("127.0.0.1", port, context=context, timeout=7)
                try:
                    connection.request("GET", "/v1/artifacts/" + entry["verification"]["artifactId"],
                                       headers=authorized | {"Accept": "application/octet-stream"})
                    response = connection.getresponse()
                    downloaded = response.read(max(map(len, legacy_results)) + 1)
                    assert response.status == 200 and response.getheader("Content-Type") == "application/octet-stream", (
                        "legacy result download", response.status)
                finally:
                    connection.close()
                assert downloaded in legacy_results, "legacy result bytes"
                return downloaded

            # Each entry has its own result, so two different downloads
            # include the result of at least one copy.
            assert legacy_download(legacy[0]) != legacy_download(legacy[-1]), "two legacy entries downloaded one result"
            tag = '"' + entry["revision"] + '"'
            key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
            status, value, _, _ = exchange(base + "/control", authorized | {
                "Content-Type": "application/json", "Idempotency-Key": key, "If-Match": tag},
                method="POST", payload=b'{"operation":"cancel"}')
            assert status == 403 and value["code"] == "insufficient-scope", ("legacy control", status, value.get("code"))
            for path in (base + "/control", base + "/snapshot", base + "/outputs", base + "/exports",
                         base + "/lineage-requests", "/v1/decisions?runId=" + entry["id"]):
                status, value, _, _ = exchange(path, authorized)
                assert status == 403 and value["code"] == "insufficient-scope", ("legacy run resource", path, status, value.get("code"))
            connection = http.client.HTTPSConnection("127.0.0.1", port, context=context, timeout=7)
            try:
                connection.request("POST", base, body=b"{}", headers=authorized | {"Content-Type": "application/json"})
                response = connection.getresponse()
                response.read(65536)
                assert response.status == 405, ("legacy run mutation", response.status)
            finally:
                connection.close()
            status, value, _, _ = exchange(base, other_authorized)
            assert status == 404 and value["code"] == "unavailable-resource", ("legacy entry of another profile", status, value.get("code"))
            status, after, _, _ = fetch(base, authorized)
            assert status == 200 and after == detail, "a refused mutation changed the legacy entry"
            (work / "legacy-run.json").write_bytes(raw)
            print(f"PASS pages case 10: {len(run_pages)} pages of /v1/runs listed each of the {LEGACY_ENTRIES} legacy",
                  "entries of the bound retention root (one completed run and its copies) and the managed run once,",
                  "in identifier order; the item and GET", "/v1/runs/{id}", "were equal and schema-valid for three",
                  "legacy entries, two results downloaded with the exact retained bytes of two different entries,",
                  "a control POST and every run subresource returned 403 insufficient-scope, a POST to the run",
                  "returned 405, and another profile's credential received 404", flush=True)
        finally:
            if process.poll() is None:
                process.terminate()
            process.wait(timeout=25)
            (work / "server-0.exit").write_text(str(process.returncode) + "\n")
    assert not (work / "admin/admin.sock").exists(), "joined original local administration leaves no socket"
    print("PASS pages: every WM-025 page case held against the running TLS 1.3 manager", flush=True)


if pages_mode:
    page_checks()
    raise SystemExit(0)


def event_checks():
    """WM-026 event verification through the real HTTPS manager, numbered as
    in the B14 requirement. Each case prints one PASS line. Subscriber quota
    and revocation of open streams are shown by the base mode and by the
    manager-artifact-check stream-ingestion and ordinary-stream modes, so this
    mode does not repeat them."""
    authorized = {"Authorization": "Bearer " + bearer}
    json_accept = {"Accept": "application/json"}

    def number(cursor):
        alias, _, position = cursor.rpartition(".")
        assert alias and position.isdigit(), ("cursor form", cursor)
        return int(position)

    def alias(cursor):
        return cursor.rpartition(".")[0]

    def poll(cursor, credential):
        """Every JSON batch from the cursor until hasMore is false. Returns
        the events in order and the final cursor."""
        events = []
        while True:
            status, batch, raw = request("/v1/events?after=" + cursor, credential | json_accept)
            assert status == 200, ("poll", status, batch.get("code"))
            validate("EventBatch", batch, raw)
            assert alias(batch["cursor"]) == alias(cursor) and number(batch["cursor"]) >= number(cursor), ("poll cursor", cursor, batch["cursor"])
            events += batch["events"]
            cursor = batch["cursor"]
            if not batch["hasMore"]:
                return events, cursor

    def block(response):
        """One complete SSE block, heartbeat or event."""
        found = bytearray()
        while not found.endswith(b"\n\n"):
            line = response.readline(16385)
            assert line and len(found) + len(line) <= 16384, "complete stream block"
            found.extend(line)
        return bytes(found)

    def streamed(response, first, last):
        """The events of the complete blocks of an open stream, from its first
        block until the event with the given number. Heartbeats carry no event."""
        blocks, events = [first], frozen.parse_sse(first)
        while not events or number(events[-1]["id"]) < last:
            blocks.append(block(response))
            events += frozen.parse_sse(blocks[-1])
        return blocks, events

    def attach(credential, cursor):
        return open_stream("/v1/events", credential | {"Last-Event-ID": cursor})

    def create_request(credential, capabilities, workflow):
        key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
        body = {"workflowId": workflow["id"], "descriptorRevision": workflow["revision"],
                "profileId": workflow["profileId"], "profileRevision": workflow["profileRevision"]}
        status, created, raw = request("/v1/requests", credential | {"Content-Type": "application/json", "Idempotency-Key": key},
                                       method="POST", payload=json.dumps(body, separators=(",", ":")).encode())
        assert status == 201, ("request creation", status, created.get("code"))
        validate("Request", created, raw)
        return created

    def resources(events):
        return [event["data"]["resource"] for event in events]

    def serve(iteration):
        output = (work / f"server-{iteration}.stdout").open("wb")
        errors = (work / f"server-{iteration}.stderr").open("wb")
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        return process, output, errors

    def stop(iteration, process, output, errors):
        try:
            if process.poll() is None:
                process.terminate()
            process.wait(timeout=25)
            (work / f"server-{iteration}.exit").write_text(str(process.returncode) + "\n")
        finally:
            output.close()
            errors.close()

    process, output, errors = serve(0)
    try:
        wait_ready(process)
        status, capabilities, _ = request("/v1/capabilities", authorized)
        assert status == 200
        status, other_capabilities, _ = request("/v1/capabilities", other_authorized)
        assert status == 200
        status, catalogue, _ = request("/v1/workflows?profileId=profile_1", authorized)
        assert status == 200 and catalogue["items"]
        workflow = catalogue["items"][0]
        status, other_catalogue, _ = request("/v1/workflows?profileId=profile_2", other_authorized)
        assert status == 200 and other_catalogue["items"]
        other_workflow = other_catalogue["items"][0]

        # Case 1. Both credentials take a snapshot and its cursor before any
        # mutation. The mutations then commit, and SSE and polling attach at
        # the snapshot cursor of the first credential.
        status, snapshot, raw = request("/v1/snapshot", authorized)
        assert status == 200 and snapshot["items"] == [] and snapshot["page"]["next"] is None
        validate("OverviewSnapshot", snapshot, raw)
        status, other_snapshot, raw = request("/v1/snapshot", other_authorized)
        assert status == 200 and other_snapshot["items"] == []
        validate("OverviewSnapshot", other_snapshot, raw)
        start, other_start = snapshot["cursor"], other_snapshot["cursor"]
        assert alias(start) == capabilities["streamId"] and alias(other_start) == other_capabilities["streamId"]
        assert number(start) == number(other_start), ("both snapshots share one durable position", start, other_start)
        mine, theirs = [], []
        mine.append(create_request(authorized, capabilities, workflow)["id"])
        mine.append(create_request(authorized, capabilities, workflow)["id"])
        theirs.append(create_request(other_authorized, other_capabilities, other_workflow)["id"])
        mine.append(create_request(authorized, capabilities, workflow)["id"])
        polled, high = poll(start, authorized)
        (work / "events-polled.json").write_text(json.dumps(polled, indent=1, default=str))
        numbers = [number(event["id"]) for event in polled]
        assert numbers and numbers[0] == number(start) + 1, ("gap between the snapshot and the first event", start, numbers[:1])
        assert numbers == sorted(set(numbers)) and numbers[-1] == number(high), ("polled order", numbers, high)
        assert all(event["data"]["resource"].rsplit("/", 1)[-1] not in theirs for event in polled), "the first credential saw the other profile"
        for ident in mine:
            assert "/v1/requests/" + ident in resources(polled), ("mutation without an invalidation", ident)
        connection, response, first = attach(authorized, start)
        try:
            blocks, sse = streamed(response, first, number(high))
            assert sse == polled, ("SSE and polling differ", resources(sse), resources(polled))
            # One later mutation reaches the open stream once, after every
            # earlier event, and polling from the old end sees exactly it.
            mine.append(create_request(authorized, capabilities, workflow)["id"])
            live, latest = poll(high, authorized)
            assert live and all(number(event["id"]) > number(high) for event in live), ("live poll", live)
            more, streamed_live = streamed(response, block(response), number(latest))
            assert streamed_live == live, ("live SSE and polling differ", resources(streamed_live), resources(live))
            assert "/v1/requests/" + mine[-1] in resources(live)
            blocks += more
            (work / "events-attached.sse").write_bytes(b"".join(blocks))
        finally:
            response.close()
            connection.close()
        polled += live
        high = latest
        print(f"PASS events case 1: SSE and polling attached at snapshot cursor {number(start)} delivered the same",
              f"{len(polled)} events in order, each once, from {number(start) + 1} with no gap after the snapshot, and one",
              "live mutation reached the open stream once after them", flush=True)

        # Case 2. The credential of the other profile polls the same range.
        # Its cursor advances over every invisible record to the same durable
        # position, and it receives none of the invisible resources.
        seen, other_high = poll(other_start, other_authorized)
        (work / "events-other.json").write_text(json.dumps(seen, indent=1, default=str))
        other_numbers = [number(event["id"]) for event in seen]
        assert number(other_high) == number(high) and alias(other_high) == alias(other_start), ("filtered advance", other_high, high)
        assert other_numbers == sorted(set(other_numbers)), ("filtered order", other_numbers)
        leaked = [event for event in seen if any(event["data"]["resource"].endswith("/" + ident) for ident in mine)]
        assert not leaked, ("the other credential received invisible resources", leaked[:2])
        assert "/v1/requests/" + theirs[0] in resources(seen), "the other credential missed its own request"
        assert other_numbers[0] > number(other_start) + 1, ("no numeric gap before the first visible event", other_numbers)
        # Together the two filtered projections cover every durable position
        # of the range, so each gap of one is a record of the other.
        covered = set(number(event["id"]) for event in polled) | set(other_numbers)
        assert covered == set(range(number(start) + 1, number(high) + 1)), ("uncovered positions", sorted(covered))
        print(f"PASS events case 2: the other-profile credential advanced from {number(other_start)} to {number(other_high)}",
              f"over {len(polled) - len(seen)} invisible records, accepted numeric gaps {other_numbers}, and received",
              f"none of the {len(mine)} invisible requests", flush=True)

        # Case 3. A stream is dropped in the middle of a block. Reconnection
        # at the last complete identifier delivers the partial block again,
        # complete, and repeats no complete block.
        assert len(polled) >= 3
        connection, response, first = attach(authorized, start)
        try:
            complete = frozen.parse_sse(first)
            assert complete == polled[:1], "first reconnect-case block"
            complete += frozen.parse_sse(block(response))
            assert complete == polled[:2], "second reconnect-case block"
            partial = response.readline(16385)
            assert partial == ("id: " + polled[2]["id"] + "\n").encode(), ("partial block start", partial)
        finally:
            response.close()
            connection.close()
        connection, response, first = attach(authorized, complete[-1]["id"])
        try:
            _, resumed = streamed(response, first, number(high))
        finally:
            response.close()
            connection.close()
        assert resumed == polled[2:], ("reconnection repeated or lost a block", resources(resumed)[:3])
        for accept in ("text/event-stream", "application/json"):
            status, problem, _ = request("/v1/events?after=" + start, authorized | {"Accept": accept, "Last-Event-ID": start})
            assert status == 400 and problem["code"] == "malformed-request", ("both cursor channels", accept, status, problem.get("code"))
        print(f"PASS events case 3: after a drop inside block {number(polled[2]['id'])}, Last-Event-ID {number(complete[-1]['id'])}",
              f"delivered that block complete and the {len(resumed) - 1} later blocks, with no complete block repeated;",
              "after with Last-Event-ID returns 400 malformed-request for SSE and polling", flush=True)
        before_restart = (capabilities["streamId"], other_capabilities["streamId"], high, other_high)
        # An ordinary shutdown ends an attached stream at a block boundary
        # with a complete response, and the manager then exits. The stream
        # belongs to the other client, because the two streams that this
        # client closed in case 3 keep its subscriptions until their next
        # write fails.
        connection, response, first = attach(other_authorized, other_high)
        try:
            assert frozen.parse_sse(first) == [], "the held stream starts with a heartbeat"
            process.terminate()
            ending = time.monotonic()
            tail = bytearray()
            while True:
                line = response.readline(16385)
                if not line:
                    break
                tail.extend(line)
                assert len(tail) <= 16384 and time.monotonic() < ending + 10, "the held stream did not end"
            assert tail.endswith(b"\n\n") or not tail, "the held stream ended inside a block"
            assert frozen.parse_sse(bytes(tail)) == [], "the held stream carried an event after the shutdown"
            ended = time.monotonic() - ending
        finally:
            response.close()
            connection.close()
        process.wait(timeout=25)
        exited = time.monotonic() - ending
    finally:
        stop(0, process, output, errors)
    print(f"PASS events shutdown: an ordinary shutdown ended the attached stream completely after {ended:.1f} s,",
          f"and the manager exited after {exited:.1f} s", flush=True)

    # Case 4. An ordinary restart keeps the public stream alias and every
    # cursor taken before it.
    process, output, errors = serve(1)
    try:
        wait_ready(process)
        status, capabilities, _ = request("/v1/capabilities", authorized)
        assert status == 200
        status, other_capabilities, _ = request("/v1/capabilities", other_authorized)
        assert status == 200
        assert (capabilities["streamId"], other_capabilities["streamId"]) == before_restart[:2], ("restart changed a stream alias", before_restart[:2])
        replayed, replay_high = poll(start, authorized)
        assert replayed[:len(polled)] == polled and alias(replay_high) == alias(start), "restart changed the retained replay"
        after, after_high = poll(before_restart[2], authorized)
        assert after == replayed[len(polled):] and after_high == replay_high
        other_after, other_after_high = poll(before_restart[3], other_authorized)
        assert number(other_after_high) == number(replay_high)
        connection, response, first = attach(authorized, before_restart[2])
        response.close()
        connection.close()
        status, snapshot, _ = request("/v1/snapshot", authorized)
        assert status == 200 and alias(snapshot["cursor"]) == capabilities["streamId"] and number(snapshot["cursor"]) == number(replay_high)
        print(f"PASS events case 4: after an ordinary restart the streamIds are unchanged, the snapshot cursor {number(start)}",
              f"replays the same {len(polled)} events, and the pre-restart cursors {number(before_restart[2])} and",
              f"{number(before_restart[3])} resume by polling and SSE with {len(after)} later events", flush=True)
    finally:
        stop(1, process, output, errors)
    assert not (work / "admin/admin.sock").exists(), "joined original local administration leaves no socket"
    for iteration in (0, 1):
        for channel in ("stdout", "stderr"):
            assert bearer.encode() not in (work / f"server-{iteration}.{channel}").read_bytes()
    print("NOTE events case 5: the subscriber quota and revocation of open streams are shown by the base mode of this",
          "harness and by the B7 stream checks, and are not repeated here", flush=True)
    print("PASS events-lifecycle: every WM-026 event case held against the running TLS 1.3 manager", flush=True)

def route_checks():
    """GET /v1/runs/{id}/routes through the real HTTPS manager after one
    mixed run. Each numbered case prints one PASS line."""
    import sqlite3
    import urllib.parse
    authorized = {"Authorization": "Bearer " + bearer}
    json_accept = {"Accept": "application/json"}
    restricted = {"engine-result", "failure"}

    def number(cursor):
        alias, _, position = cursor.rpartition(".")
        assert alias.startswith("route_") and position.isdigit(), ("route cursor form", cursor)
        return int(position)

    def alias(cursor):
        return cursor.rpartition(".")[0]

    def batch(run, credential, after=None, route=None, extra=None):
        query = []
        if after is not None:
            query.append("after=" + after)
        if route is not None:
            query.append("route=" + urllib.parse.quote(route, safe=""))
        target = f"/v1/runs/{run}/routes" + ("?" + "&".join(query) if query else "")
        return request(target, credential | json_accept | (extra or {}))

    def walk(run, credential, route=None):
        """Every batch from the start until hasMore is false. Returns the
        records in order, the final cursor and the number of batches."""
        records, cursor, batches = [], None, 0
        while True:
            status, value, raw = batch(run, credential, cursor, route)
            assert status == 200, ("route batch", status, value.get("code"))
            validate("RouteBatch", value, raw)
            assert len(raw) <= 1048576
            if cursor is not None:
                assert alias(value["cursor"]) == alias(cursor) and number(value["cursor"]) >= number(cursor), ("route cursor", cursor, value["cursor"])
            assert value["oldestCursor"] == alias(value["cursor"]) + ".0", ("route floor", value["oldestCursor"])
            for record in value["records"]:
                assert record["id"] == alias(value["cursor"]) + "." + str(record["position"] + 1), ("record id", record["id"], record["position"])
                assert record["position"] < number(value["cursor"]), ("record after the batch cursor", record["position"], value["cursor"])
            records += value["records"]
            cursor = value["cursor"]
            batches += 1
            if not value["hasMore"]:
                return records, cursor, batches
            assert batches < 1024, "route pages did not end"

    def database_rows():
        """Every row of every table of the coordination database, read through
        a read-only connection."""
        found = sorted((work / "manager").rglob("coordination.sqlite3"))
        assert len(found) == 1, ("coordination database", found)
        connection = sqlite3.connect(found[0].as_uri() + "?mode=ro", uri=True)
        try:
            tables = [row[0] for row in connection.execute("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")]
            return {table: sorted(repr(row) for row in connection.execute(f'SELECT * FROM "{table}"')) for table in tables}
        finally:
            connection.close()

    def manager_batch(credential, after=None, route=None, extra=None):
        query = []
        if after is not None:
            query.append("after=" + after)
        if route is not None:
            query.append("route=" + urllib.parse.quote(route, safe=""))
        return request("/v1/routes" + ("?" + "&".join(query) if query else ""), credential | json_accept | (extra or {}))

    def manager_walk(credential, route=None, after=None):
        """Every manager route batch from the cursor, or from the floor, until
        hasMore is false. Returns the records, the final cursor and the floor."""
        records, cursor, batches = [], after, 0
        while True:
            status, value, raw = manager_batch(credential, cursor, route)
            assert status == 200, ("manager route batch", status, value.get("code"))
            validate("ManagerRouteBatch", value, raw)
            assert len(raw) <= 1048576
            floor = number(value["oldestCursor"])
            assert alias(value["oldestCursor"]) == alias(value["cursor"]), ("manager route floor alias", value["oldestCursor"])
            if cursor is not None:
                assert alias(value["cursor"]) == alias(cursor) and number(value["cursor"]) >= number(cursor), ("manager cursor", cursor, value["cursor"])
            for record in value["records"]:
                assert record["id"] == alias(value["cursor"]) + "." + str(record["position"] + 1), ("manager record id", record["id"])
                assert floor <= record["position"] < number(value["cursor"]), ("manager record outside the batch", record["position"])
            records += value["records"]
            cursor = value["cursor"]
            batches += 1
            if not value["hasMore"]:
                return records, cursor, floor
            assert batches < 1024, "manager route pages did not end"

    def manager_named(records, request_id, run_id):
        """The enqueue and approve commands with their receipts, the review and
        the start relay of the request and its run, each found exactly once."""
        def one(label, predicate):
            found = [record for record in records if predicate(record)]
            assert len(found) == 1, ("manager route record", label, len(found))
            return found[0]
        named = {}
        for operation in ("enqueue", "approve"):
            # The run has exactly one enqueue and one approve command.
            named[operation] = one(operation, lambda r: r["schema"] == "command" and r["body"]["operation"] == operation)
            named[operation + "-receipt"] = one(operation + " receipt", lambda r: r["schema"] == "receipt"
                                                and r["replyTo"] == named[operation]["position"])
            assert named[operation + "-receipt"]["about"]["command"] == named[operation]["about"]["command"]
        assert named["enqueue"]["about"]["request"] == request_id, ("enqueue request", named["enqueue"]["about"])
        named["review"] = one("review", lambda r: r["schema"] == "review" and r["about"].get("request") == request_id)
        named["start"] = one("start relay", lambda r: r["schema"] == "relay" and r["about"].get("managerRun") == run_id
                             and r["about"].get("command") == named["approve"]["about"]["command"])
        if "body" in named["start"]:
            assert named["start"]["body"]["kind"] == "start"
        return named

    def flow_entries(name, flow_dir, active):
        """The manager-log entries that the flow verb of the runner reads, by
        position, and the retained floor, after the manager has exited. The
        run store of the run is read with it, so that the relays join."""
        stores = sorted(work.glob("manager/runs/runs/*/runtime"))
        completed = subprocess.run([str(runner), "flow", str(flow_dir)] + [str(store) for store in stores],
                                   stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=60)
        (work / (name + ".ndjson")).write_bytes(completed.stdout)
        (work / (name + ".stderr")).write_bytes(completed.stderr)
        lines = [json.loads(line) for line in completed.stdout.splitlines()]
        assert lines and "summary" in lines[-1], ("flow verb", completed.returncode, completed.stderr[-2000:])
        entries = {line["position"]: line for line in lines[:-1] if line["log"] == str(active)}
        assert entries and all(line["log"] in [str(active)] + [str(store) for store in stores] for line in lines[:-1])
        manager_logs = [item for item in lines[-1]["summary"]["logs"] if item["kind"] == "manager"]
        assert len(manager_logs) == 1, ("flow verb manager logs", lines[-1]["summary"]["logs"])
        return entries, manager_logs[0]["floor"]

    def compare_flow(records, entries):
        for record in records:
            entry = entries[record["position"]]
            for field in ("schema", "from", "to", "about", "replyTo", "at"):
                assert record[field] == entry.get(field), ("manager record differs from the flow verb", record["position"], field)
            if "claim" in record:
                assert record["claim"] == entry["claim"] and "body" not in record, ("manager claim check", record["position"])
            else:
                assert record["body"] == entry["body"], ("manager inline body", record["position"])

    def record_owner(entry):
        """The owner row of a manager-log entry, by the rule of the manager route."""
        about, schema = entry.get("about", {}), entry.get("schema")
        if schema in ("command", "receipt"):
            return ("commands", about.get("command"))
        if schema == "review":
            return ("requests", about.get("request"))
        if schema == "relay":
            return ("runs", about["managerRun"]) if "managerRun" in about else ("requests", about.get("request"))
        if schema == "notice" and isinstance(entry.get("body"), dict):
            kind = entry["body"].get("notice")
            if kind == "command-changed":
                return ("commands", about.get("command"))
            if kind in ("review-ended", "request-ended"):
                return ("requests", about.get("request"))
        return None

    def database_owners():
        """Every command, request and run identifier of profile_1."""
        found = sorted((work / "manager").rglob("coordination.sqlite3"))
        connection = sqlite3.connect(found[0].as_uri() + "?mode=ro", uri=True)
        try:
            return {(table, row[0]) for table in ("commands", "requests", "runs")
                    for row in connection.execute(f"SELECT id FROM {table} WHERE profile_id='profile_1'")}
        finally:
            connection.close()

    def seal(active, sealed_dir, start):
        sealed_dir.parent.mkdir(mode=0o700, exist_ok=True)
        sealed_dir.mkdir(mode=0o700, exist_ok=True)
        active.rename(sealed_dir / ("%020d.ndjson" % start))

    def route_block(response):
        """One complete block of an open route stream."""
        found = bytearray()
        while not found.endswith(b"\n\n"):
            line = response.readline(16385)
            assert line and len(found) + len(line) <= 16384, "complete route stream block"
            found.extend(line)
        return bytes(found)

    def route_open(path, credential, cursor=None, seconds=30):
        """Open one route stream and read its first complete block, which the
        manager writes at once. A registration refused with 429 storage-quota
        is tried again: a stream whose client closed its connection keeps its
        subscription until its next write fails, at the latest at its next
        heartbeat."""
        deadline = time.monotonic() + seconds
        headers = credential | {"Accept": "text/event-stream"} | ({"Last-Event-ID": cursor} if cursor else {})
        while True:
            connection = http.client.HTTPSConnection("127.0.0.1", port, context=context, timeout=20)
            connection.request("GET", path, headers=headers)
            response = connection.getresponse()
            if response.status == 200:
                break
            raw = response.read(1048577)
            status = response.status
            response.close()
            connection.close()
            refused = frozen.parse_json(raw)
            validate("Problem", refused)
            assert status == 429 and refused["code"] == "storage-quota" and time.monotonic() < deadline, (
                "route stream admission", path, status, refused["code"])
            time.sleep(0.25)
        assert response.getheader("Content-Type") == "text/event-stream"
        return connection, response, route_block(response)

    def route_read(response, first, until):
        """The blocks and completed entries of an open route stream, from its
        first block until an entry whose id names at least the position."""
        blocks, entries = [first], frozen.parse_route_sse(first)
        while not entries or number(entries[-1]["id"]) < until:
            blocks.append(route_block(response))
            entries += frozen.parse_route_sse(blocks[-1])
        return blocks, entries

    def same_record(streamed, polled):
        """Whether a streamed record is the polled record, or the polled
        record with its body replaced by the size notice of an oversized block."""
        if streamed == polled:
            return True
        body = streamed.get("body")
        rest = {key: value for key, value in streamed.items() if key != "body"}
        return ("body" in polled and isinstance(body, dict) and body.get("omitted") == "size"
                and isinstance(body.get("bytes"), int) and body["bytes"] > 0
                and rest == {key: value for key, value in polled.items() if key != "body"})

    def records_of(entries, schema):
        found = [entry["data"] for entry in entries if "data" in entry]
        for entry in entries:
            if "data" in entry:
                assert entry["event"] == "route." + entry["data"]["schema"], ("route event name", entry["event"])
                validate(schema, entry["data"])
        return found

    def issue(label):
        output = work / ("credential-" + label)
        administration({"version": 1, "operation": "issue-credential", "label": "Routes " + label,
                        "scopes": ["observe", "control"], "profileIds": ["profile_1"],
                        "expiresAt": "2999-01-01T00:00:00Z", "outputFile": str(output)})
        return {"Authorization": "Bearer " + output.read_bytes().decode("ascii")}

    def closing(connection, response):
        response.close()
        connection.close()

    @contextlib.contextmanager
    def serving(index):
        with (work / f"server-{index}.stdout").open("wb") as output, (work / f"server-{index}.stderr").open("wb") as errors:
            process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                        "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
            try:
                wait_ready(process)
                yield process
            finally:
                if process.poll() is None:
                    process.terminate()
                process.wait(timeout=25)

    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        try:
            wait_ready(process)
            status, capabilities, _ = request("/v1/capabilities", authorized)
            assert status == 200
            status, catalogue, _ = request("/v1/workflows?profileId=profile_1", authorized)
            assert status == 200
            workflow = next(item for item in catalogue["items"] if item["name"] == "mixed-controls")
            key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
            body = {"workflowId": workflow["id"], "descriptorRevision": workflow["revision"],
                    "profileId": workflow["profileId"], "profileRevision": workflow["profileRevision"]}
            status, created, raw = request("/v1/requests", authorized | {"Content-Type": "application/json", "Idempotency-Key": key},
                                           method="POST", payload=json.dumps(body, separators=(",", ":")).encode())
            assert status == 201, ("request creation", status, created.get("code"))
            run = run_mixed(created, workflow, capabilities, authorized)
            observer_file = work / "credential-observer"
            administration({"version": 1, "operation": "issue-credential", "label": "Routes observer",
                            "scopes": ["observe"], "profileIds": ["profile_1"],
                            "expiresAt": "2999-01-01T00:00:00Z", "outputFile": str(observer_file)})
            observer = {"Authorization": "Bearer " + observer_file.read_bytes().decode("ascii")}
            stranger_file = work / "credential-stranger"
            administration({"version": 1, "operation": "issue-credential", "label": "Routes other profile",
                            "scopes": ["observe", "control"], "profileIds": ["profile_2"],
                            "expiresAt": "2999-01-01T00:00:00Z", "outputFile": str(stranger_file)})
            stranger = {"Authorization": "Bearer " + stranger_file.read_bytes().decode("ascii")}

            # The local run store of the run: its event log and its run log.
            stores = [entry for entry in (work / "manager" / "runs" / "runs").iterdir()]
            assert len(stores) == 1, ("run stores", stores)
            runtime = stores[0] / "runtime"
            sequences = [int(json.loads(line)["sequence"]) for line in (runtime / "events.ndjson").read_bytes().splitlines()]
            local = [frozen.parse_json(line) for line in (runtime / "flow.ndjson").read_bytes().splitlines()]
            schemas = [line["schema"] for line in local]
            assert sequences and restricted & set(schemas), ("the mixed run log has no event or no restricted record", schemas)
            before = database_rows()

            # Case 1. An observe-only credential receives exactly the event
            # records, each naming a line of the event log in order.
            public, public_end, _ = walk(run, observer)
            (work / "routes-observer.json").write_text(json.dumps(public, indent=1, ensure_ascii=False, default=str))
            assert all(record["class"] == "public" and record["schema"] == "event" for record in public), "observer received a non-public record"
            assert [record["event"]["sequence"] for record in public] == sequences, ("event records differ from the event log", len(public), len(sequences))
            assert [record["position"] for record in public] == [i for i, name in enumerate(schemas) if name == "event"]
            assert number(public_end) == len(local), ("observer cursor end", public_end, len(local))
            print(f"PASS routes case 1: the observe-only credential received the {len(public)} event records, which name",
                  "the lines of the event log of the run in order", flush=True)

            # Case 2. A control credential of the same profile also receives
            # the actor records, and no credential receives a restricted one.
            served, served_end, batches = walk(run, authorized)
            (work / "routes-control.json").write_text(json.dumps(served, indent=1, ensure_ascii=False, default=str))
            expected = [i for i, name in enumerate(schemas) if name not in restricted]
            assert [record["position"] for record in served] == expected, "control credential records differ from the local run log"
            for record in served:
                line = local[int(record["position"])]
                assert record["class"] == ("public" if record["schema"] == "event" else "actor")
                for field in ("schema", "from", "to", "about", "at"):
                    assert record[field] == line[field], ("record field differs from the run log", record["position"], field)
                assert record["replyTo"] == line.get("replyTo"), ("record replyTo differs from the run log", record["position"])
                content = line["body"]
                if "inline" in content:
                    assert record["body"] == content["inline"] and "claim" not in record, ("inline body", record["position"])
                elif "claim" in content:
                    assert record["claim"] == content["claim"] and "body" not in record, ("claim check", record["position"])
                else:
                    assert record["event"] == {"sequence": content["event"]}, ("event number", record["position"])
            for name in ("start", "question", "answer", "control"):
                assert name in {record["schema"] for record in served}, ("control credential missed a record schema", name)
            assert not restricted & {record["schema"] for record in served + public}, "a restricted record was served"
            assert number(served_end) == number(public_end) == len(local)
            print(f"PASS routes case 2: the control credential received {len(served)} public and actor records in {batches}",
                  f"batches, including start, question, answer and control, and no credential received one of the",
                  f"{len(local) - len(expected)} restricted records", flush=True)

            # Case 3. The route predicate filters.
            questions, _, _ = walk(run, authorized, "schema=question")
            assert questions and questions == [record for record in served if record["schema"] == "question"], "route schema=question"
            workflow_events, _, _ = walk(run, observer, "schema=event,from=workflow:" + local[0]["about"]["nativeRun"])
            assert workflow_events == public, "route schema=event,from=workflow"
            hidden, _, _ = walk(run, observer, "schema=question")
            assert hidden == [], "the route predicate exposed an actor record to the observer"
            status, problem, _ = batch(run, authorized, route="unknown=1")
            assert status == 400 and problem["code"] == "malformed-request", ("malformed route", status, problem.get("code"))
            print(f"PASS routes case 3: schema=question selected the {len(questions)} question records, a sender term kept",
                  "every event record, the observer received no question, and an unknown field refused", flush=True)

            # Case 4. Paging through after returns every record once.
            for index, record in enumerate(served):
                status, value, raw = batch(run, authorized, record["id"])
                assert status == 200, ("resume", status, value.get("code"))
                validate("RouteBatch", value, raw)
                following = served[index + 1:index + 1 + len(value["records"])]
                assert value["records"] == following, ("resume from a record id", record["id"])
            status, value, _ = batch(run, authorized, served_end)
            assert status == 200 and value["records"] == [] and not value["hasMore"] and value["cursor"] == served_end
            status, problem, _ = batch(run, authorized, served[0]["id"], extra={"Last-Event-ID": served[0]["id"]})
            assert status == 400 and problem["code"] == "malformed-request", ("after with Last-Event-ID", status)
            status, value, _ = request(f"/v1/runs/{run}/routes", authorized | json_accept | {"Last-Event-ID": served[0]["id"]})
            assert status == 200 and value["records"][0] == served[1], "Last-Event-ID resume"
            print(f"PASS routes case 4: resuming after each of the {len(served)} record ids returned the following records",
                  "exactly once, the end cursor returned an empty final batch, and Last-Event-ID resumes", flush=True)

            # Case 5. A wrong-alias or future cursor returns 410.
            wrong = "route_" + "0" * 64 + ".1"
            status, problem, _ = batch(run, authorized, wrong)
            assert status == 410 and problem["code"] == "view-expired", ("wrong alias", status, problem.get("code"))
            status, problem, _ = batch(run, authorized, public_end)
            assert status == 410 and problem["code"] == "view-expired", ("another credential's alias", status, problem.get("code"))
            future = alias(served_end) + "." + str(number(served_end) + 1)
            status, problem, _ = batch(run, authorized, future)
            assert status == 410 and problem["code"] == "cursor-expired", ("future cursor", status, problem.get("code"))
            status, problem, _ = request(f"/v1/runs/{run}/routes", authorized | {"Accept": "text/plain"})
            assert status == 409 and problem["code"] == "unsupported-operation", ("route Accept", status, problem.get("code"))
            print("PASS routes case 5: a wrong alias and the alias of another credential returned 410 view-expired, a",
                  "future cursor returned 410 cursor-expired, and Accept text/plain returned 409", flush=True)

            # Case 6. Route reads write nothing to the database.
            after = database_rows()
            changed = [table for table in sorted(set(before) | set(after)) if before.get(table) != after.get(table)]
            assert not changed, ("route reads changed the database", changed)
            print(f"PASS routes case 6: the {len(before)} tables of the database are unchanged across the route reads", flush=True)

            # Case 7. A control credential of the profile receives the
            # manager-log records of the mixed run as actor records.
            managed, managed_end, floor = manager_walk(authorized)
            (work / "manager-routes-control.json").write_text(json.dumps(managed, indent=1, ensure_ascii=False, default=str))
            assert floor == 0, ("manager route floor before any prune", floor)
            assert managed and all(record["class"] == "actor" for record in managed), "manager route served a record of another class"
            assert {record["schema"] for record in managed} <= {"command", "receipt", "review", "relay", "notice"}
            named = manager_named(managed, created["id"], run)
            print("PASS routes case 7: the control credential received", len(managed), "manager-log records, including the enqueue",
                  "command at", named["enqueue"]["position"], "and its receipt, the review at", named["review"]["position"],
                  "the approve command at", named["approve"]["position"], "and its receipt, and the start relay at",
                  named["start"]["position"], flush=True)

            # Case 8. An observe-only credential receives no manager-log record,
            # and its cursor advances over every record as a filtered gap.
            hidden, hidden_end, _ = manager_walk(observer)
            assert hidden == [], ("the observe-only credential received manager-log records", [r["position"] for r in hidden])
            assert number(hidden_end) >= number(managed_end) > named["start"]["position"], ("observe-only cursor", hidden_end, managed_end)
            print("PASS routes case 8: the observe-only credential received no manager-log record, and its cursor advanced to",
                  number(hidden_end), flush=True)

            # Case 9. A control credential of another profile receives none of
            # the records of the first profile.
            foreign, foreign_end, _ = manager_walk(stranger)
            assert not {record["position"] for record in foreign} & {record["position"] for record in managed}, "another profile received a record"
            assert foreign == [] and number(foreign_end) >= number(managed_end), ("other profile manager route", foreign_end)
            print("PASS routes case 9: a control credential of profile_2 received no manager-log record of profile_1, and its",
                  "cursor advanced to", number(foreign_end), flush=True)

            # Case 10. The route predicate, paging and the 410 cursors of the
            # manager route behave as those of the run route.
            commands, _, _ = manager_walk(authorized, "schema=command")
            expected = [record for record in managed if record["schema"] == "command"]
            assert commands[:len(expected)] == expected and all(r["schema"] == "command" for r in commands), "manager route schema=command"
            for index, record in enumerate(managed):
                status, value, raw = manager_batch(authorized, record["id"])
                assert status == 200, ("manager resume", status, value.get("code"))
                validate("ManagerRouteBatch", value, raw)
                following = managed[index + 1:index + 1 + len(value["records"])]
                assert value["records"][:len(following)] == following, ("manager resume from a record id", record["id"])
            status, problem, _ = manager_batch(authorized, "route_" + "0" * 64 + ".1")
            assert status == 410 and problem["code"] == "view-expired", ("manager wrong alias", status, problem.get("code"))
            status, problem, _ = manager_batch(authorized, served_end)
            assert status == 410 and problem["code"] == "view-expired", ("run-route alias on the manager route", status, problem.get("code"))
            status, problem, _ = manager_batch(authorized, alias(managed_end) + "." + str(number(hidden_end) + 100000))
            assert status == 410 and problem["code"] == "cursor-expired", ("manager future cursor", status, problem.get("code"))
            status, problem, _ = request("/v1/routes", authorized | {"Accept": "text/plain"})
            assert status == 409 and problem["code"] == "unsupported-operation", ("manager route Accept", status, problem.get("code"))
            status, problem, _ = manager_batch(authorized, managed[0]["id"], extra={"Last-Event-ID": managed[0]["id"]})
            assert status == 400 and problem["code"] == "malformed-request", ("manager after with Last-Event-ID", status)
            after = database_rows()
            changed = [table for table in sorted(set(before) | set(after)) if before.get(table) != after.get(table)]
            assert not changed, ("manager route reads changed the database", changed)
            print(f"PASS routes case 10: schema=command selected the {len(expected)} commands, resuming after each of the",
                  f"{len(managed)} record ids returned the following records, a wrong alias and a run-route cursor returned",
                  "410 view-expired, a future cursor returned 410 cursor-expired, Accept text/plain returned 409, and the",
                  "database is unchanged", flush=True)
        finally:
            if process.poll() is None:
                process.terminate()
            process.wait(timeout=25)

    # Case 11. Each served record is the entry that the flow verb reads from
    # the same manager log, and every other retained record is a gap: a
    # failure record, or a record whose profile does not resolve.
    flow_dir = work / "manager" / "flow"
    logs = sorted(flow_dir.glob("*.ndjson"))
    assert len(logs) == 1, ("manager logs", logs)
    active, stream = logs[0], logs[0].stem
    entries, flow_floor = flow_entries("manager-flow-1", flow_dir, active)
    assert flow_floor == 0
    owners = database_owners()
    compare_flow(managed, entries)
    ends = number(managed_end)
    expected = [p for p in sorted(entries) if p < ends and entries[p]["schema"] != "failure" and record_owner(entries[p]) in owners]
    assert [record["position"] for record in managed] == expected, ("served positions differ from the resolved flow records",
                                                                     [record["position"] for record in managed], expected)
    gaps = [p for p in sorted(entries) if p < ends and p not in expected]
    assert any(entries[p]["schema"] == "notice" and entries[p]["body"].get("notice") == "lifetime" for p in gaps), "no lifetime gap"
    print(f"PASS routes case 11: the {len(managed)} served records equal the flow-verb entries of the manager log, and the",
          f"{len(gaps)} other records, lifetime notices included, are gaps", flush=True)

    # Case 12. A cursor survives a seal. The first lifetime left one active
    # file. Sealing moves it to its segment name, as the writer does, and the
    # next lifetime writes a new active file.
    sealed_dir = flow_dir / "sealed" / stream
    assert not sealed_dir.exists() or not any(sealed_dir.iterdir()), ("the manager log already has sealed segments", sealed_dir)
    first_count = len(active.read_bytes().splitlines())
    seal(active, sealed_dir, 0)
    with serving(1):
        resumed, resumed_end, floor = manager_walk(authorized, after=named["enqueue"]["id"])
        index = managed.index(named["enqueue"])
        assert floor == 0 and alias(resumed_end) == alias(managed_end), ("manager cursor after a seal", floor, resumed_end)
        assert resumed[:len(managed) - index - 1] == managed[index + 1:], "resume across a seal"
        status, capabilities, _ = request("/v1/capabilities", authorized)
        assert status == 200
        status, catalogue, _ = request("/v1/workflows?profileId=profile_1", authorized)
        workflow = next(item for item in catalogue["items"] if item["name"] == "mixed-controls")
        body = {"workflowId": workflow["id"], "descriptorRevision": workflow["revision"],
                "profileId": workflow["profileId"], "profileRevision": workflow["profileRevision"]}
        key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
        status, draft, _ = request("/v1/requests", authorized | {"Content-Type": "application/json", "Idempotency-Key": key},
                                   method="POST", payload=json.dumps(body, separators=(",", ":")).encode())
        assert status == 201, ("draft creation", status, draft.get("code"))
        later, later_end, _ = manager_walk(authorized, after=managed_end)
        creation = [record for record in later if record["schema"] == "command" and record["body"]["operation"] == "create"]
        assert len(creation) == 1 and creation[0]["position"] >= first_count, ("draft create command after the seal", creation, first_count)
        replies = [record for record in later if record["schema"] == "receipt" and record["replyTo"] == creation[0]["position"]]
        assert len(replies) == 1, "draft create receipt after the seal"
        whole, whole_end, _ = manager_walk(authorized)
        assert whole[:len(managed)] == managed and whole[len(managed):] == later, "a walk from the floor crosses the sealed segment"
    print(f"PASS routes case 12: after a seal at position {first_count}, a cursor of the first lifetime resumed across the",
          f"sealed segment with the same alias, and the create command at {creation[0]['position']} and its receipt followed",
          "in the new active file", flush=True)

    # Case 13. The oldest cursor is the retained floor, and a cursor below it
    # returns 410. The second lifetime is sealed as well, and the oldest
    # segment is then removed, as the pruner removes it.
    second_count = len(active.read_bytes().splitlines())
    seal(active, sealed_dir, first_count)
    (sealed_dir / ("%020d.ndjson" % 0)).unlink()
    with serving(2):
        kept, kept_end, floor = manager_walk(authorized)
        assert floor == first_count, ("retained floor after a prune", floor, first_count)
        assert alias(kept_end) == alias(managed_end)
        retained = [record for record in later if record["position"] >= first_count]
        assert retained and kept[:len(retained)] == retained, "the records above the floor after a prune"
        status, value, raw = manager_batch(authorized)
        assert status == 200 and value["oldestCursor"] == alias(managed_end) + "." + str(first_count), ("oldest cursor", value["oldestCursor"])
        for position in (0, first_count - 1):
            status, problem, _ = manager_batch(authorized, alias(managed_end) + "." + str(position))
            assert status == 410 and problem["code"] == "cursor-expired", ("cursor below the floor", position, status, problem.get("code"))
        status, value, raw = manager_batch(authorized, alias(managed_end) + "." + str(first_count))
        assert status == 200 and value["records"][:1] == retained[:1], "cursor at the floor"
        status, value, raw = manager_batch(authorized, creation[0]["id"])
        assert status == 200 and value["records"][:1] == replies, "resume after the create command above the floor"
    entries, flow_floor = flow_entries("manager-flow-3", flow_dir, active)
    assert flow_floor == first_count, ("flow verb floor", flow_floor)
    compare_flow(kept, entries)
    print(f"PASS routes case 13: after a prune the oldest cursor names the floor {first_count}, cursors at 0 and",
          f"{first_count - 1} returned 410 cursor-expired, the cursor at the floor and the create command id resumed, and",
          f"the {len(kept)} records above the floor equal the flow-verb entries; the second sealed segment holds {second_count} records", flush=True)
    # Cases 14 to 20 read both routes as server-sent events.
    run_path = f"/v1/runs/{run}/routes"
    with serving(3) as process:
        status, capabilities, _ = request("/v1/capabilities", authorized)
        assert status == 200
        stream_before = capabilities["streamId"]

        # Case 14. SSE on the run route delivers the records of the JSON
        # batches, each as one block named route.<schema>, and the route
        # predicate selects the same records as in JSON.
        polled, polled_end, _ = walk(run, authorized)
        assert polled == served and polled_end == served_end, "the run log changed after the run"
        connection, response, first = route_open(run_path, authorized)
        try:
            blocks, entries = route_read(response, first, number(served[-1]["id"]))
        finally:
            closing(connection, response)
        (work / "routes-run.sse").write_bytes(b"".join(blocks))
        streamed = records_of(entries, "RouteRecord")
        assert len(streamed) == len(served) and all(same_record(a, b) for a, b in zip(streamed, served)), (
            "SSE and JSON records of the run route differ", len(streamed), len(served))
        oversized = sum(1 for a, b in zip(streamed, served) if a != b)
        connection, response, first = route_open(run_path + "?route=" + urllib.parse.quote("schema=question", safe=""), authorized)
        try:
            _, entries = route_read(response, first, number(questions[-1]["id"]))
        finally:
            closing(connection, response)
        assert [record for record in records_of(entries, "RouteRecord")] == questions, "SSE route predicate"
        print(f"PASS routes case 14: SSE on the run route delivered the {len(streamed)} records of the JSON batches in",
              f"order, one block each with the event route.<schema> ({oversized} with an omitted body), and",
              f"schema=question selected the same {len(questions)} records", flush=True)

        # Case 15. Attaching at a JSON cursor delivers the later records
        # exactly once, through Last-Event-ID and through after, and an
        # attachment at the end cursor starts with a heartbeat.
        middle = len(served) // 2
        for label, path, cursor in (("Last-Event-ID", run_path, served[middle]["id"]),
                                    ("after", run_path + "?after=" + served[middle]["id"], None)):
            connection, response, first = route_open(path, authorized, cursor)
            try:
                _, entries = route_read(response, first, number(served[-1]["id"]))
            finally:
                closing(connection, response)
            later = records_of(entries, "RouteRecord")
            assert len(later) == len(served) - middle - 1 and all(same_record(a, b) for a, b in zip(later, served[middle + 1:])), (
                "attachment at a JSON cursor", label)
        connection, response, first = route_open(run_path, authorized, served_end)
        closing(connection, response)
        assert first == b": heartbeat\n\n", ("attachment at the end cursor", first)
        print(f"PASS routes case 15: attaching at the JSON cursor of record {middle} through Last-Event-ID and through",
              f"after delivered the {len(served) - middle - 1} later records exactly once, and the end cursor started",
              "with a heartbeat", flush=True)

        # Case 16. A stream dropped inside its third block is resumed with the
        # id of its last complete block, and no complete block is repeated.
        # A request with after and Last-Event-ID returns 400 on both routes.
        assert len(served) >= 3
        connection, response, first = route_open(run_path, authorized)
        try:
            complete = records_of(frozen.parse_route_sse(first) + frozen.parse_route_sse(route_block(response)), "RouteRecord")
            assert complete == served[:2], "the first two blocks of the dropped stream"
            partial = response.readline(16385)
            assert partial == ("id: " + served[2]["id"] + "\n").encode(), ("partial block start", partial)
        finally:
            closing(connection, response)
        connection, response, first = route_open(run_path, authorized, served[1]["id"])
        try:
            _, entries = route_read(response, first, number(served[-1]["id"]))
        finally:
            closing(connection, response)
        resumed = records_of(entries, "RouteRecord")
        assert len(resumed) == len(served) - 2 and all(same_record(a, b) for a, b in zip(resumed, served[2:])), (
            "the reconnection repeated or lost a block")
        for path, cursor in ((run_path, served[0]["id"]), ("/v1/routes", managed[0]["id"])):
            status, problem, _ = request(path + "?after=" + cursor, authorized | {"Accept": "text/event-stream", "Last-Event-ID": cursor})
            assert status == 400 and problem["code"] == "malformed-request", ("after with Last-Event-ID on SSE", path, status)
        print(f"PASS routes case 16: after a drop inside block {number(served[2]['id'])}, Last-Event-ID",
              f"{number(served[1]['id'])} delivered that record complete and the {len(resumed) - 1} later records, with",
              "no complete block repeated, and after with Last-Event-ID returned 400 on both routes", flush=True)

        # Case 17. SSE on the manager route delivers the records of the JSON
        # batches. An observe-only credential receives cursor blocks only. A
        # record appended while a stream is open reaches it before the next
        # heartbeat.
        managed_now, managed_now_end, floor = manager_walk(authorized)
        assert managed_now and floor == first_count
        connection, response, first = route_open("/v1/routes", authorized)
        try:
            _, entries = route_read(response, first, number(managed_now[-1]["id"]))
        finally:
            closing(connection, response)
        streamed_managed = records_of(entries, "ManagerRouteRecord")
        assert len(streamed_managed) == len(managed_now) and all(same_record(a, b) for a, b in zip(streamed_managed, managed_now)), (
            "SSE and JSON records of the manager route differ")
        _, observer_end, _ = manager_walk(observer)
        connection, response, first = route_open("/v1/routes", observer)
        try:
            _, entries = route_read(response, first, number(observer_end))
        finally:
            closing(connection, response)
        assert entries and all(set(entry) == {"id"} for entry in entries), ("the observe-only manager stream", entries[:2])
        assert entries[-1]["id"] == observer_end, ("the cursor block of the observe-only stream", entries[-1], observer_end)
        live_credential = issue("live")
        # A cursor alias belongs to the credential, so the live stream
        # attaches at the end cursor of its own credential.
        _, live_start, _ = manager_walk(live_credential)
        connection, response, first = route_open("/v1/routes", live_credential, live_start)
        try:
            attached = time.monotonic()
            assert first == b": heartbeat\n\n", ("the live manager stream starts with a heartbeat", first)
            status, catalogue, _ = request("/v1/workflows?profileId=profile_1", authorized)
            workflow = next(item for item in catalogue["items"] if item["name"] == "mixed-controls")
            body = {"workflowId": workflow["id"], "descriptorRevision": workflow["revision"],
                    "profileId": workflow["profileId"], "profileRevision": workflow["profileRevision"]}
            key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
            status, draft, _ = request("/v1/requests", authorized | {"Content-Type": "application/json", "Idempotency-Key": key},
                                       method="POST", payload=json.dumps(body, separators=(",", ":")).encode())
            assert status == 201, ("live draft creation", status, draft.get("code"))
            posted = time.monotonic()
            live = frozen.parse_route_sse(route_block(response))
            arrived = time.monotonic()
        finally:
            closing(connection, response)
        live_records = records_of(live, "ManagerRouteRecord")
        assert live_records and live_records[0]["schema"] == "command" and live_records[0]["body"]["operation"] == "create", (
            "the first block after the heartbeat is the live create command", live)
        assert arrived - attached < 15, ("the live record came after the heartbeat interval", arrived - attached)
        live_command = live_records[0]
        polled_live, _, _ = manager_walk(live_credential, after=live_start)
        assert polled_live[:1] == [live_command], "the live record differs from its JSON batch"
        print(f"PASS routes case 17: SSE on the manager route delivered the {len(streamed_managed)} records of the JSON",
              f"batches, the observe-only stream carried cursor blocks only up to {number(observer_end)}, and the create",
              f"command at {live_command['position']} reached an open stream {arrived - posted:.2f} s after its POST",
              f"and {arrived - attached:.2f} s after the attaching heartbeat", flush=True)

        # Case 18. Route streams share the per-client reader quota of
        # /v1/events: with an event stream and a run-route stream open, a
        # manager-route stream and a third event stream of the same client
        # are refused as /v1/events refuses them.
        quota = issue("quota")
        status, snapshot, _ = request("/v1/snapshot", quota)
        assert status == 200
        _, quota_end, _ = walk(run, quota)
        held = [open_stream("/v1/events", quota | {"Last-Event-ID": snapshot["cursor"]})[:2],
                route_open(run_path, quota, quota_end)[:2]]
        try:
            status, refused_route, _ = request("/v1/routes", quota | {"Accept": "text/event-stream"})
            status_events, refused_events, _ = request("/v1/events", quota | {"Accept": "text/event-stream", "Last-Event-ID": snapshot["cursor"]})
        finally:
            for pair in held:
                closing(*pair)
        assert (status, refused_route["code"]) == (status_events, refused_events["code"]) == (429, "storage-quota"), (
            "the reader quota", status, refused_route.get("code"), status_events, refused_events.get("code"))
        print("PASS routes case 18: with one event stream and one run-route stream open, a manager-route stream and a",
              "third event stream of the same client both returned 429 storage-quota", flush=True)

        # Case 19. An ordinary shutdown ends open route streams at a block
        # boundary with a complete response.
        ending_credential = issue("shutdown")
        _, ending_run, _ = walk(run, ending_credential)
        _, ending_manager, _ = manager_walk(ending_credential)
        held = [route_open(run_path, ending_credential, ending_run), route_open("/v1/routes", ending_credential, ending_manager)]
        restart_cursor = live_command["id"]
        try:
            process.terminate()
            ending = time.monotonic()
            for connection, response, _ in held:
                tail = bytearray()
                while True:
                    try:
                        line = response.readline(16385)
                    except http.client.IncompleteRead:
                        line = b""
                    if not line:
                        break
                    tail.extend(line)
                    assert time.monotonic() < ending + 10, "a route stream did not end at the shutdown"
                assert tail.endswith(b"\n\n") or not tail, "a route stream ended inside a block"
                frozen.parse_route_sse(bytes(tail))
            ended = time.monotonic() - ending
        finally:
            for connection, response, _ in held:
                closing(connection, response)
        process.wait(timeout=25)
        exited = time.monotonic() - ending
    print(f"PASS routes case 19: an ordinary shutdown ended an open run-route stream and an open manager-route stream",
          f"completely after {ended:.1f} s, and the manager exited after {exited:.1f} s", flush=True)

    # Case 20. After an ordinary restart the stream alias is unchanged, and
    # cursors taken before the restart resume both route streams.
    with serving(4):
        status, capabilities, _ = request("/v1/capabilities", authorized)
        assert status == 200 and capabilities["streamId"] == stream_before, "the restart changed the stream alias"
        connection, response, first = route_open(run_path, authorized, served[middle]["id"])
        try:
            _, entries = route_read(response, first, number(served[-1]["id"]))
        finally:
            closing(connection, response)
        later = records_of(entries, "RouteRecord")
        assert len(later) == len(served) - middle - 1 and all(same_record(a, b) for a, b in zip(later, served[middle + 1:])), (
            "run-route resume after the restart")
        following, _, _ = manager_walk(live_credential, after=restart_cursor)
        assert following, "no manager record after the live command"
        connection, response, first = route_open("/v1/routes", live_credential, restart_cursor)
        try:
            _, entries = route_read(response, first, number(following[-1]["id"]))
        finally:
            closing(connection, response)
        resumed_managed = records_of(entries, "ManagerRouteRecord")
        assert len(resumed_managed) == len(following) and all(same_record(a, b) for a, b in zip(resumed_managed, following)), (
            "manager-route resume after the restart")
        assert resumed_managed[0]["schema"] == "receipt" and resumed_managed[0]["replyTo"] == live_command["position"], (
            "the first record after the live command is its receipt", resumed_managed[0]["schema"])
    print(f"PASS routes case 20: after an ordinary restart the streamId is unchanged, the run-route cursor of record",
          f"{middle} resumed with {len(later)} records, and the manager-route cursor of the live command resumed with",
          f"its receipt and {len(resumed_managed) - 1} later records", flush=True)
    print("PASS routes: every run-route and manager-route case held against the running TLS 1.3 manager", flush=True)


def endpoint_checks():
    """The tui-endpoints mode. See ENDPOINTS for the steps."""
    from tui_probe import TuiSession
    authorized = {"Authorization": "Bearer " + bearer}
    with socket.socket() as unused:
        unused.bind(("127.0.0.1", 0))
        closed_port = unused.getsockname()[1]
    profiles = []
    for name, endpoint in (("ep1", f"https://127.0.0.1:{port}/v1"), ("ep2", f"https://127.0.0.1:{port}/v1"),
                           ("unreachable", f"https://127.0.0.1:{closed_port}/v1")):
        path = work / ("client-profile-" + name + ".json")
        path.write_text(json.dumps({"version": 1, "endpoint": endpoint,
                                    "credentialFile": str(work / ("credential-" + ("ep1" if name == "unreachable" else name))),
                                    "caFile": str(cert)}))
        path.chmod(0o600)
        profiles.append(path)

    def identity_row(session):
        """The endpoint identity row of the shell header."""
        rows = [row for row in session.screen.lines()[:3] if f"manager 127.0.0.1:{port}" in row]
        assert len(rows) == 1, ("the shell header has no single identity row", session.screen.lines()[:3])
        return rows[0]

    def save(session, name):
        (work / ("tui-endpoints-" + name + ".screen.txt")).write_text(session.screen.text())

    def switch(session, moves, number, scopes, absent):
        """Open the Endpoints view, select the profile and require its active session and identity."""
        session.send(b"E")
        session.wait_screen("Manager endpoints")
        session.send(moves + b"\r")
        screen = session.wait_screen(f"> {number}. active  {profiles[number - 1]}")
        save(session, f"switch-{number}")
        row = identity_row(session)
        assert "scopes " + scopes in row and (absent is None or "scopes " + absent not in row), (
            "the identity row does not show the credential of the new endpoint", number, row)
        return screen

    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        try:
            wait_ready(process)
            status, overview, raw = request("/v1/snapshot", authorized)
            assert status == 200 and overview["items"] == [], "the endpoints mode does not start from an empty manager"
            command = [os.environ["TUI_CHECK"], "--tui", "--service"] + [str(path) for path in profiles] + ["+RTS", "-N" + native, "-RTS"]
            client_state = work / "unused-client-state"
            with harness_reads_only(), TuiSession(runner, client_state, command=command, explicit_state=False) as session:
                # 1. Endpoint one is active with the identity of its credential.
                session.wait_screen("Manager profiles")
                session.wait_screen("profile_1")
                session.send(b"\r")
                session.wait_screen("Manager workflows")
                row = identity_row(session)
                assert "scopes observe submit" in row and "scopes observe submit control" not in row, row
                session.send(b"E")
                screen = session.wait_screen("Manager endpoints")
                save(session, "initial")
                for line in (f"> 1. active  {profiles[0]}", f"  2. not connected  {profiles[1]}", f"  3. not connected  {profiles[2]}"):
                    assert line in screen, ("the Endpoints view lacks a profile line", line)
                session.send(b"\x1b")
                session.wait_screen("Manager workflows")
                print("PASS tui-endpoints 1: the Endpoints view lists the three profiles with endpoint one active, and Esc returns to the workflows browser", flush=True)
                # 2. A request created through endpoint one.
                session.send(b"\r")
                deadline = time.monotonic() + 30
                while True:
                    status, overview, raw = request("/v1/snapshot", authorized)
                    assert status == 200
                    requests = [item["request"] for item in overview["items"] if item["kind"] == "request"]
                    if requests:
                        break
                    assert time.monotonic() < deadline, "JOURNEY-DEADLINE the request of endpoint one did not appear"
                    session.pump(0.2)
                assert len(requests) == 1, requests
                created = requests[0]
                deadline = time.monotonic() + 30
                while "request validator current" not in session.screen.text() and "manager request: draft" not in session.screen.text():
                    assert time.monotonic() < deadline, ("JOURNEY-DEADLINE the created request was not observed", session.screen.text())
                    session.pump(0.1)
                if "request validator current" in session.screen.text():
                    session.send(b"\x1b")
                session.wait_screen(created["id"])
                save(session, "created")
                print("PASS tui-endpoints 2: endpoint one created request", created["id"], "and shows it", flush=True)
                # 3. The switch to endpoint two shows its identity and no earlier selection.
                screen = switch(session, b"\x1b[B", 2, "observe submit control", None)
                assert f"  1. not connected  {profiles[0]}" in screen, "endpoint one is not closed after the switch"
                session.send(b"\x1b")
                screen = session.wait_screen("Manager profiles")
                save(session, "after-switch")
                assert created["id"] not in screen, "the selection of endpoint one remains after the switch"
                assert "Request: " not in screen and "request validator" not in screen, "an observation of endpoint one remains"
                session.send(b"\r")
                session.wait_screen("Manager workflows")
                print("PASS tui-endpoints 3: the switch to endpoint two shows its credential scopes, clears the selection and observations, and its session reads the catalogue", flush=True)
                # 4. A failed switch keeps endpoint two working.
                session.send(b"E")
                session.wait_screen("Manager endpoints")
                session.send(b"\x1b[B\r")
                screen = session.wait_screen(f"3. failed: manager unreachable  {profiles[2]}")
                save(session, "failed")
                assert f"  2. active  {profiles[1]}" in screen, "a failed switch changed the active endpoint"
                assert "scopes observe submit control" in identity_row(session), "a failed switch changed the identity"
                session.wait_screen("endpoint switch failed: manager unreachable")
                session.send(b"\x1b")
                session.wait_screen("Manager workflows")
                session.send(b"h")
                session.wait_screen("Esc BACK")
                session.send(b"\x1b")
                session.wait_screen("Manager workflows")
                session.send(b"\x1b")
                session.wait_screen("Manager profiles")
                print("PASS tui-endpoints 4: a switch to the unreachable profile fails with its fixed reason and endpoint two keeps its identity and reads", flush=True)
                # 5. The switch back opens a new session of endpoint one.
                screen = switch(session, b"\x1b[A", 1, "observe submit", "observe submit control")
                assert f"  2. not connected  {profiles[1]}" in screen
                session.send(b"\x1b")
                session.wait_screen("Manager profiles")
                session.send(b"\r")
                session.wait_screen("Manager workflows")
                print("PASS tui-endpoints 5: the switch back to endpoint one opens a new session with its identity and catalogue", flush=True)
                session.send(b"q")
                assert session.wait_exit(20) == 0
                session.assert_restored()
            assert not client_state.exists(), "the service TUI created local runner state"
            status, overview, raw = request("/v1/snapshot", authorized)
            assert status == 200
            requests = [item["request"] for item in overview["items"] if item["kind"] == "request"]
            assert [item["id"] for item in requests] == [created["id"]] and requests[0]["phase"] == "draft", (
                "the switches changed the manager requests", requests)
            (work / "tui-endpoints-overview.json").write_bytes(raw)
            print("PASS tui-endpoints 6: the manager holds only the one draft request of endpoint one after the switches and the detach", flush=True)
        finally:
            if process.poll() is None:
                process.terminate()
            process.wait(timeout=25)
            (work / "server-0.exit").write_text(str(process.returncode) + "\n")


def overview_checks():
    """The tui-overview mode. See OVERVIEW for the steps."""
    harness = tui_fixture.harness

    def save(session, name):
        (work / ("tui-overview-" + name + ".screen.txt")).write_text(session.screen.text())

    def create_draft(chosen=None):
        """Create one draft request of the mixed workflow of the first
        profile, or of the chosen workflow, through HTTP with the credential
        of the harness."""
        chosen = chosen or workflow
        key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
        body = {"workflowId": chosen["id"], "descriptorRevision": chosen["revision"],
                "profileId": chosen["profileId"], "profileRevision": chosen["profileRevision"]}
        status, created, raw = request("/v1/requests", harness | {"Content-Type": "application/json", "Idempotency-Key": key},
                                       method="POST", payload=json.dumps(body, separators=(",", ":")).encode())
        assert status == 201, ("request creation", status, created.get("code"))
        validate("Request", created, raw)
        assert created["phase"] == "draft" and created["admission"]["reasons"], (
            "the created request has no blocking reason", created["admission"])
        return created

    def live_header(session, state="live"):
        assert any("Manager overview" in row and "delivery " + state in row for row in session.screen.lines()[:3]), (
            "the delivery state is not " + state, session.screen.lines()[:3])

    def open_overview(session):
        """Select the profile and open the Manager overview view."""
        session.wait_screen("Manager profiles")
        session.wait_screen("profile_1")
        session.send(b"\r")
        session.wait_screen("Manager workflows")
        session.send(b"O")
        return session.wait_screen("Manager overview")

    def hold_readers():
        """Open the two SSE readers of the TUI credential on /v1/events from
        the cursor of an overview of that credential. A registration refused
        with 429 storage-quota is tried again: the stream of the TUI that
        quit keeps its subscription until its next write fails, at the
        latest at its next heartbeat."""
        tui = {"Authorization": "Bearer " + (work / "credential-tui").read_bytes().decode("ascii")}
        status, own, _ = request("/v1/snapshot", tui)
        assert status == 200, ("TUI credential overview", status)
        held = []
        deadline = time.monotonic() + 40
        while len(held) < 2:
            connection = http.client.HTTPSConnection("127.0.0.1", port, context=context, timeout=60)
            connection.request("GET", "/v1/events?after=" + own["cursor"], headers=tui | {"Accept": "text/event-stream"})
            response = connection.getresponse()
            if response.status == 200:
                assert response.getheader("Content-Type") == "text/event-stream"
                held.append((connection, response))
                continue
            raw = response.read(1048577)
            status = response.status
            response.close()
            connection.close()
            refused = frozen.parse_json(raw)
            validate("Problem", refused)
            assert status == 429 and refused["code"] == "storage-quota" and time.monotonic() < deadline, (
                "TUI credential reader admission", status, refused["code"])
            time.sleep(0.25)
        return held

    def details(screen):
        """The details column joined without separators, so that a long
        identifier that wraps across rows stays one string."""
        return "".join(line.split("│", 1)[1].strip() for line in screen.splitlines() if "│" in line)

    def focus_row(session, label, value):
        """Move the overview focus to the row whose list label starts with
        label and whose details contain value, such as "Run:" and a run
        identifier. Returns the screen."""
        session.send(b"\x1b[A" * 16)
        session.settle()
        for _ in range(16):
            screen = session.screen.text()
            if "> " + label in screen and value in details(screen).replace(" ", ""):
                return screen
            session.send(b"\x1b[B")
            session.settle()
        raise AssertionError(("no overview row has the label and the value", label, value, session.screen.text()))

    def open_run(session, run):
        """Focus the row of this run and open it with Enter. Returns the
        screen of its question head."""
        focus_row(session, "run Running", "Run:" + run)
        session.send(b"\r")
        return session.wait_screen("Your answer", timeout=20)

    def leave(session):
        """Esc from the live monitor back to the overview."""
        session.send(b"\x1b")
        session.wait_screen("Manager overview", timeout=10)
        return session.wait_screen("Overview: current", timeout=10)

    def run_rows(screen):
        """The number of run rows that the overview list shows."""
        return sum(1 for line in screen.splitlines() if line.split("│", 1)[0].strip().lstrip("> ").startswith("run Running"))

    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        try:
            wait_ready(process)
            status, overview, raw = request("/v1/snapshot", harness)
            assert status == 200 and overview["items"] == [], "the overview mode does not start from an empty manager"
            status, capabilities, _ = request("/v1/capabilities", harness)
            assert status == 200
            status, catalogue, _ = request("/v1/workflows?profileId=profile_1", harness)
            assert status == 200
            workflow = next(item for item in catalogue["items"] if item["name"] == "mixed-controls")
            with tui_fixture.session() as session:
                # 1. The overview of the bootstrap shows the empty manager.
                open_overview(session)
                screen = session.wait_screen("Overview: current; requests: 0, preparations: 0, runs: 0, decisions: 0")
                assert "No rows are visible." in screen, "the empty overview lists a row"
                session.wait_screen("delivery live", timeout=20)
                assert any("Manager overview" in row and "delivery live" in row for row in session.screen.lines()[:3]), (
                    "the header lacks the live delivery state", session.screen.lines()[:3])
                save(session, "empty")
                status, overview, _ = request("/v1/snapshot", harness)
                assert status == 200 and overview["items"] == [], ("the manager overview is not empty", status, overview.get("items"))
                print("PASS tui-overview 1: O opens the Manager overview, which shows the empty overview that the TUI read after the profiles loaded",
                      "and that the harness reads, and the header shows delivery live", flush=True)
                # 2. A request that the harness creates appears without a key press.
                created = create_draft()
                reasons = created["admission"]["reasons"]
                created_at = time.monotonic()
                screen = session.wait_screen("Overview: current; requests: 1, preparations: 0, runs: 0, decisions: 0", timeout=3)
                elapsed = time.monotonic() - created_at
                save(session, "created")
                live_header(session)
                for line in ("> request draft", "Phase: draft", "Admission: " + created["admission"]["state"],
                             "Blocking reasons: " + ", ".join(reasons)):
                    assert line in screen, ("the overview lacks a line of the created request", line)
                for value in ("Request:" + created["id"], "Workflow:" + workflow["id"]):
                    assert value in details(screen), ("the overview details lack the created request", value)
                print("PASS tui-overview 2: without a key press the overview lists request", created["id"], "with phase draft and blocking reasons",
                      ", ".join(reasons), f"after {elapsed:.2f} seconds, and the delivery state reads live", flush=True)
                # 3. Runtime status changes of a run reach the overview
                # without a key press. The overview lists live requests and
                # active runs, so the terminal run and its released request
                # leave it.
                client = mixed_client(capabilities, harness)
                _, run = approve_mixed(created, workflow, client)
                head, _, _ = drive_mixed(run, client, stop_at_question=True, overview=False)
                screen = session.wait_screen("decision question", timeout=3)
                assert "run Running" in screen, "the overview lacks the running run"
                save(session, "running")
                running, _, _ = client[0]("/v1/runs/" + run + "/snapshot", "RunSnapshot")
                running_control, _, _ = client[0]("/v1/runs/" + run + "/control", "RunControl")
                assert running["runtime"]["status"] == "running" and running_control["decisionHeadId"] == head, (
                    "the manager does not hold the run at its question", running["runtime"]["status"], running_control["decisionHeadId"], head)
                print("PASS tui-overview 3a: without a key press the overview shows run", run, "Running with its question, as the manager",
                      "publishes it with head", head, flush=True)
                # 3b. The held run opens from the overview by its identifier,
                # keeps a typed answer draft, and Esc leaves it running.
                held_before, _, _ = client[0]("/v1/runs/" + run + "/snapshot", "RunSnapshot")
                decision_before, _, _ = client[0]("/v1/decisions/" + head, "Decision")
                for _ in range(8):
                    if "> run Running" in session.screen.text():
                        break
                    session.send(b"\x1b[B")
                    session.settle()
                screen = session.wait_screen("> run Running", timeout=5)
                assert "Run:" + run in details(screen).replace(" ", ""), "the focused overview row is not the held run"
                session.send(b"\r")
                session.wait_screen("Your answer", timeout=20)
                save(session, "held-open")
                draft = "pc18 held draft"
                session.send(draft.encode())
                session.wait_screen(draft, timeout=10)
                save(session, "held-draft")
                session.send(b"\x1b")
                screen = session.wait_screen("Manager overview", timeout=10)
                screen = session.wait_screen("> run Running", timeout=10)
                assert "Your answer" not in screen and draft not in screen, "Esc did not return to the overview"
                save(session, "held-left")
                held_after, _, _ = client[0]("/v1/runs/" + run + "/snapshot", "RunSnapshot")
                control_after, _, _ = client[0]("/v1/runs/" + run + "/control", "RunControl")
                decision_after, _, _ = client[0]("/v1/decisions/" + head, "Decision")
                assert held_after["runtime"]["status"] == "running", ("Esc changed the held run", held_after["runtime"]["status"])
                assert control_after["decisionHeadId"] == head and decision_after["state"] == "pending" \
                    and decision_after["revision"] == decision_before["revision"], "Esc changed the pending question"
                assert held_after["controlAcks"] == held_before["controlAcks"], "Esc sent a manager control"
                print("PASS tui-overview 3b: Enter on the focused run row opened run", run, "by its identifier with its question head,",
                      "and Esc returned to the overview while the run stays running with the same pending question and no new control acknowledgement",
                      flush=True)
                # 3c. Reopening the run shows the same draft, after a safety
                # read and after a resize.
                session.send(b"\r")
                session.wait_screen("Your answer", timeout=20)
                session.wait_screen(draft, timeout=10)
                time.sleep(6)
                session.wait_screen(draft, timeout=5)
                session.resize(30, 100)
                session.wait_screen(draft, timeout=10)
                session.resize(24, 80)
                screen = session.wait_screen(draft, timeout=10)
                save(session, "held-reopen")
                assert "Your answer" in screen, "the reopened run lost its question head"
                session.send(b"\x1b")
                session.wait_screen("Manager overview", timeout=10)
                reopened_snapshot, _, _ = client[0]("/v1/runs/" + run + "/snapshot", "RunSnapshot")
                reopened_control, _, _ = client[0]("/v1/runs/" + run + "/control", "RunControl")
                assert reopened_snapshot["runtime"]["status"] == "running" and reopened_control["decisionHeadId"] == head \
                    and reopened_snapshot["controlAcks"] == held_before["controlAcks"], "reopening the run changed the manager run"
                print("PASS tui-overview 3c: the reopened run showed the typed answer draft again, after a safety read and after a resize,",
                      "and Esc returned to the overview", flush=True)
                # 4. While the first run waits at its question, the
                # workflows browser of the second profile creates a second
                # request, and the TUI types its literal input and enqueues it.
                status, catalogue_2, _ = request("/v1/workflows?profileId=profile_2", harness)
                assert status == 200
                index_2 = next(i for i, item in enumerate(catalogue_2["items"]) if item["name"] == "mixed-controls")
                workflow_2 = catalogue_2["items"][index_2]
                session.send(b"\x1b")
                session.wait_screen("Manager workflows")
                session.send(b"\x1b")
                session.wait_screen("Manager profiles")
                session.send(b"\x1b[B\r")
                screen = session.wait_screen("Manager workflows")
                assert "profile_2" in screen, "the workflows browser does not show the second profile"
                session.send(b"\x1b[B" * index_2 + b"\r")
                session.wait_screen("request validator current", timeout=30)
                session.send(b"\x1b[200~" + MIXED_TEXT.encode() + b"\x1b[201~")
                session.send(b"\x04")
                session.wait_screen("Enter REQUEST REVIEW", timeout=30)
                session.send(b"\r")
                session.wait_screen("Approve exact manager review", timeout=45)
                save(session, "second-review")
                status, current, _ = request("/v1/snapshot", harness)
                assert status == 200
                created_2 = [item["request"] for item in current["items"]
                             if item["kind"] == "request" and item["request"]["profileId"] == "profile_2"]
                assert len(created_2) == 1 and created_2[0]["phase"] == "review", ("the TUI request of the second profile", created_2)
                still, _, _ = client[0]("/v1/runs/" + run + "/snapshot", "RunSnapshot")
                still_control, _, _ = client[0]("/v1/runs/" + run + "/control", "RunControl")
                assert still["runtime"]["status"] == "running" and still_control["decisionHeadId"] == head, (
                    "the first run did not continue at its question while the TUI created the second request")
                print("PASS tui-overview 4: the workflows browser of profile_2 created request", created_2[0]["id"],
                      "and the TUI enqueued it to review while run", run, "kept running at its question", flush=True)
                # 5. The harness approves the second request and stops its run
                # at its question. Both runs then run at once.
                _, run_2 = approve_review(created_2[0], workflow_2, client)
                head_2, _, _ = drive_mixed(run_2, client, stop_at_question=True, overview=False)
                session.wait_screen("Your answer", timeout=30)
                save(session, "second-question")
                screen = leave(session)
                screen = session.wait_screen("Overview: current; requests: 2, preparations: 0, runs: 2, decisions: ", timeout=10)
                save(session, "two-runs")
                assert run_rows(screen) == 2 and screen.count("decision question") == 2, "the overview does not list two running runs"
                for ident, profile in ((run, "profile_1"), (run_2, "profile_2")):
                    screen = focus_row(session, "run Running", "Run:" + ident)
                    assert "Profile: " + profile in screen and "Runtime status: Running" in screen, (
                        "the run row lacks its own profile and status", ident)
                print("PASS tui-overview 5: the overview lists runs", run, "and", run_2,
                      "as Running with their own profiles and question decisions", flush=True)
                # 6. An answer draft survives a switch to the other run and back.
                screen = open_run(session, run)
                assert draft in session.wait_screen(draft, timeout=10), "the first run lost its draft"
                leave(session)
                screen = open_run(session, run_2)
                save(session, "second-open")
                assert draft not in screen, "the second run shows the draft of the first run"
                draft_2 = "pc19 second draft"
                session.send(draft_2.encode())
                session.wait_screen(draft_2, timeout=10)
                leave(session)
                open_run(session, run)
                screen = session.wait_screen(draft, timeout=10)
                save(session, "first-reopen")
                assert draft_2 not in screen, "the first run shows the draft of the second run"
                leave(session)
                for ident, decision_id in ((run, head), (run_2, head_2)):
                    unchanged, _, _ = client[0]("/v1/runs/" + ident + "/control", "RunControl")
                    assert unchanged["decisionHeadId"] == decision_id, ("a switch changed a pending question", ident)
                print("PASS tui-overview 6: the answer draft of run", run, "survived a switch to run", run_2,
                      "and back, and each run showed only its own draft", flush=True)
                # 7. A third request waits behind the two held reservations.
                third = create_draft()
                enqueue_mixed(third, workflow, client)
                queued, _, _ = client[1](third["links"]["self"], "Request",
                                         lambda value: value["phase"] == "queued" and value["admission"]["reasons"] == ["capacity"])
                screen = session.wait_screen("Overview: current; requests: 3, preparations: 0, runs: 2, decisions: ", timeout=10)
                screen = focus_row(session, "request queued 1 of 1", "Request:" + third["id"])
                save(session, "queued")
                for line in ("Phase: queued", "Profile: profile_1", "Profile queue position: 1 of 1", "Blocking reasons: capacity"):
                    assert line in screen, ("the queued request row lacks a line", line)
                print("PASS tui-overview 7: request", third["id"], "is queued with blocking reason capacity and position 1 of 1",
                      "among the queued requests of profile_1, at manager position", queued["admission"]["position"], flush=True)
                session.send(b"\x1b")
                session.wait_screen("Manager workflows")
                session.send(b"q")
                assert session.wait_exit(20) == 0
                session.assert_restored()
            # 8. The restarted TUI lists both active runs and opens one.
            with tui_fixture.session() as session:
                open_overview(session)
                screen = session.wait_screen("Overview: current; requests: 3, preparations: 0, runs: 2, decisions: ", timeout=20)
                save(session, "restarted")
                assert run_rows(screen) == 2, "the restarted TUI does not list two running runs"
                focus_row(session, "run Running", "Run:" + run)
                focus_row(session, "request queued 1 of 1", "Request:" + third["id"])
                screen = open_run(session, run_2)
                save(session, "restarted-open")
                assert draft not in screen and draft_2 not in screen, "the restarted TUI shows a draft of the earlier TUI"
                reopened, _, _ = client[0]("/v1/runs/" + run_2 + "/control", "RunControl")
                assert reopened["decisionHeadId"] == head_2, "opening the run changed its question"
                leave(session)
                print("PASS tui-overview 8: the restarted TUI lists runs", run, "and", run_2, "and the queued request, and Enter opens",
                      "the question of run", run_2, flush=True)
                # 9. The runs keep independent statuses: the first run ends
                # and leaves the overview while the second stays at its question.
                _, answered, recovered = drive_mixed(run, client, overview=False)
                assert answered and recovered, ("mixed workflow decisions", answered, recovered)
                finished_at = time.monotonic()
                while True:
                    screen = session.screen.text()
                    if "Overview: current;" in screen and " runs: 1," in screen:
                        break
                    assert time.monotonic() < finished_at + 3, ("the overview still lists the terminal run", screen)
                    session.pump(0.05)
                elapsed = time.monotonic() - finished_at
                screen = focus_row(session, "run Running", "Run:" + run_2)
                save(session, "first-succeeded")
                assert run_rows(screen) == 1, "the overview does not list exactly the second run"
                assert "Run:" + run not in details(screen).replace(" ", ""), "the overview still lists the terminal run"
                live_header(session)
                print("PASS tui-overview 9: without a key press the overview drops run", run,
                      f"{elapsed:.2f} seconds after the harness observed the terminal status Succeeded, and run", run_2,
                      "stays Running at its question", flush=True)
                # 10. The third request leaves the queue. The harness completes
                # it and the second run, and the overview becomes empty.
                _, run_3 = approve_review(third, workflow, client)
                for ident in (run_3, run_2):
                    _, answered, recovered = drive_mixed(ident, client, overview=False)
                    assert answered and recovered, ("mixed workflow decisions", ident, answered, recovered)
                screen = session.wait_screen("Overview: current; requests: 0, preparations: 0, runs: 0, decisions: 0", timeout=10)
                save(session, "succeeded")
                assert "No rows are visible." in screen, "the overview still lists a terminal run"
                print("PASS tui-overview 10: request", third["id"], "left the queue as run", run_3,
                      "and the overview became empty after runs", run_3, "and", run_2, "succeeded", flush=True)
                # 11. A further request appears without a key press.
                second = create_draft()
                screen = session.wait_screen("Overview: current; requests: 1, preparations: 0, runs: 0, decisions: 0", timeout=3)
                save(session, "second")
                assert "Request:" + second["id"] in details(screen), "the overview details lack the further request"
                status, current, _ = request("/v1/snapshot", harness)
                assert status == 200 and [item["request"]["id"] for item in current["items"] if item["kind"] == "request"] == [second["id"]], (
                    "the manager overview does not hold exactly the further request", status)
                live_header(session)
                print("PASS tui-overview 11: without a key press the overview lists the further request", second["id"], flush=True)
                session.send(b"\x1b")
                session.wait_screen("Manager workflows")
                session.send(b"q")
                assert session.wait_exit(20) == 0
                session.assert_restored()
            # 12. With no free SSE reader the restarted TUI polls and still
            # shows an HTTP change within 3 seconds.
            held = hold_readers()
            try:
                with tui_fixture.session() as session:
                    open_overview(session)
                    session.wait_screen("Overview: current; requests: 1, preparations: 0, runs: 0, decisions: 0")
                    session.wait_screen("delivery polling", timeout=20)
                    live_header(session, "polling")
                    save(session, "polling")
                    fourth = create_draft()
                    created_at = time.monotonic()
                    screen = session.wait_screen("Overview: current; requests: 2, preparations: 0, runs: 0, decisions: 0", timeout=3)
                    elapsed = time.monotonic() - created_at
                    save(session, "polled")
                    live_header(session, "polling")
                    status, current, _ = request("/v1/snapshot", harness)
                    assert status == 200 and sorted(item["request"]["id"] for item in current["items"] if item["kind"] == "request") == sorted(
                        [second["id"], fourth["id"]]), ("the manager overview does not hold the two requests that the TUI lists", status)
                    print("PASS tui-overview 12: with both SSE readers of its credential held, the restarted TUI shows delivery polling and lists request",
                          fourth["id"], f"without a key press after {elapsed:.2f} seconds", flush=True)
                    # 13. A free reader returns delivery to live.
                    for connection, response in held:
                        response.close()
                        connection.close()
                    held = []
                    released_at = time.monotonic()
                    session.wait_screen("delivery live", timeout=60)
                    live_header(session)
                    save(session, "relive")
                    status, current, _ = request("/v1/snapshot", harness)
                    assert status == 200 and len([item for item in current["items"] if item["kind"] == "request"]) == 2, (
                        "the manager overview changed while the delivery state returned to live", status)
                    print("PASS tui-overview 13: after the harness released the readers, the delivery state returned to live after",
                          f"{time.monotonic() - released_at:.2f} seconds", flush=True)
                    # 14. A refused read keeps the overview and marks it stale.
                    process.terminate()
                    process.wait(timeout=25)
                    try:
                        exchange("/v1/snapshot", harness)
                    except ConnectionRefusedError:
                        pass
                    else:
                        raise AssertionError("the stopped manager still answers the harness")
                    session.send(b"g")
                    screen = session.wait_screen("Overview: stale (TransportUnavailable); the last complete overview is retained")
                    save(session, "stale")
                    assert screen.count("request draft") == 2, "the stale overview lost a request row"
                    for line in ("> request draft", "Phase: draft"):
                        assert line in screen, ("the stale overview lost a line of the selected request", line)
                    assert any("Request:" + item["id"] in details(screen) and "Blocking reasons: " + ", ".join(item["admission"]["reasons"]) in screen
                               for item in (second, fourth)), "the stale overview lost the selected request"
                    print("PASS tui-overview 14: with the manager stopped, g keeps both requests and marks the overview stale with TransportUnavailable",
                          flush=True)
                    session.send(b"\x1b")
                    session.wait_screen("Manager workflows")
                    session.send(b"q")
                    assert session.wait_exit(20) == 0
                    session.assert_restored()
            finally:
                for connection, response in held:
                    response.close()
                    connection.close()
            assert not tui_fixture.client_state.exists(), "the service TUI created local runner state"
            print("PASS tui-overview: the overview view followed the manager overview through the actual service TUI in", lifecycle_elapsed(), flush=True)
        finally:
            if process.poll() is None:
                process.terminate()
            process.wait(timeout=25)
            (work / "server-0.exit").write_text(str(process.returncode) + "\n")


def input_checks():
    """The tui-inputs mode. See INPUTS for the steps."""
    harness = tui_fixture.harness
    editor_text = "Captured \u03bb editor input \u2014 caf\u00e9 \u96ea\nsecond line"
    editor_bytes = editor_text.encode()
    line = "\ufeffFile capture \u03bb \u2014 caf\u00e9 \u96ea\r\n".encode()
    file_bytes = line * (100000 // len(line)) + b"last line\n"
    marker = "pc20capture" + secrets.token_hex(8)
    file_path = work / (marker + ".txt")
    file_path.write_bytes(file_bytes)

    def save(session, name):
        (work / ("tui-inputs-" + name + ".screen.txt")).write_text(session.screen.text())

    def database_commands(request_id, preparations):
        """The number of removal, discard and withdrawal commands of the
        request and of these preparations of it in the coordination
        database, read through a read-only connection."""
        import sqlite3
        found = sorted((work / "manager").rglob("coordination.sqlite3"))
        assert len(found) == 1, ("coordination database", found)
        connection = sqlite3.connect(found[0].as_uri() + "?mode=ro", uri=True)
        try:
            resources = ["/v1/requests/" + request_id] + ["/v1/preparations/" + ident for ident in preparations]
            marks = ",".join("?" * len(resources))
            rows = connection.execute("SELECT operation, count(*) FROM commands WHERE operation IN ('remove-input','discard','withdraw')"
                                      " AND resource_uri IN (" + marks + ") GROUP BY operation", resources).fetchall()
            return dict(rows)
        finally:
            connection.close()

    def new_request(session, index):
        """Select profile_1 and create a request of the captured-input
        workflow from the workflows browser. Returns the input screen."""
        session.wait_screen("Manager profiles")
        session.wait_screen("profile_1")
        session.send(b"\r")
        session.wait_screen("Manager workflows")
        session.send(b"\x1b[A" * 40 + b"\x1b[B" * index + b"\r")
        return session.wait_screen("request validator current", timeout=30)

    def reviewed(expected, bytes_):
        """The single request in review whose input is a capture of these
        exact bytes, read through HTTP with the credential of the harness."""
        status, overview, _ = request("/v1/snapshot", harness)
        assert status == 200
        requests = [item["request"] for item in overview["items"] if item["kind"] == "request"
                    and item["request"]["phase"] == "review" and item["request"]["id"] not in expected]
        assert len(requests) == 1, ("the TUI request in review", requests)
        status, created, raw = request("/v1/requests/" + requests[0]["id"], harness)
        assert status == 200
        validate("Request", created, raw)
        supplied = created["readiness"]["supplied"]
        assert len(supplied) == 1 and supplied[0]["name"] == "input" and supplied[0]["source"] == "capture", (
            "the request input is not a capture", supplied)
        status, preparation, raw = request("/v1/preparations/" + created["preparationId"], harness)
        assert status == 200
        validate("Preparation", preparation, raw)
        inputs = [{"name": "input", "source": "capture", "bytes": str(len(bytes_)), "sha256": hashlib.sha256(bytes_).hexdigest()}]
        assert preparation["review"]["inputs"] == inputs, ("the exact review of the captured input", preparation["review"]["inputs"], inputs)
        return created, supplied[0]["captureId"], raw

    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        try:
            wait_ready(process)
            status, capabilities, _ = request("/v1/capabilities", harness)
            assert status == 200
            status, catalogue, _ = request("/v1/workflows?profileId=profile_1", harness)
            assert status == 200
            index = next(i for i, item in enumerate(catalogue["items"]) if item["name"] == "captured-input")
            assert [item["name"] for item in catalogue["items"][index]["inputs"]] == ["input"]
            with tui_fixture.session() as session:
                # 1. Ctrl-T captures the editor text, and Ctrl-R removes it.
                new_request(session, index)
                session.send(b"\x1b[200~" + editor_text.encode() + b"\x1b[201~")
                session.settle()
                session.send(b"\x14")
                screen = session.wait_screen("Captured inputs:", timeout=30)
                session.wait_screen("Enter REQUEST REVIEW", timeout=30)
                save(session, "editor-request")
                status, overview, _ = request("/v1/snapshot", harness)
                assert status == 200
                captured = [item["request"] for item in overview["items"] if item["kind"] == "request"]
                assert len(captured) == 1 and [(entry["name"], entry["source"]) for entry in captured[0]["readiness"]["supplied"]] == [
                    ("input", "capture")], ("the manager request does not supply the captured input", captured)
                session.send(b"e")
                session.wait_screen("Ctrl-R REMOVE INPUT", timeout=10)
                session.send(b"\x12")
                removed_screen = session.wait_screen("Missing inputs: input", timeout=30)
                save(session, "removed-request")
                assert "Captured inputs:" not in removed_screen and "Enter REQUEST REVIEW" not in removed_screen, (
                    "the request screen still shows the removed input")
                status, overview, _ = request("/v1/snapshot", harness)
                assert status == 200
                drafts = [item["request"] for item in overview["items"] if item["kind"] == "request"]
                assert len(drafts) == 1, ("the TUI request", drafts)
                status, removed, raw = request("/v1/requests/" + drafts[0]["id"], harness)
                assert status == 200
                validate("Request", removed, raw)
                assert removed["phase"] == "draft" and removed["readiness"]["supplied"] == [] and removed["readiness"]["missing"] == ["input"], (
                    "the removed input is still supplied", removed["readiness"])
                print("PASS tui-inputs 1: Ctrl-R removed the captured input of request", removed["id"],
                      "and the request screen and the request readiness name the input as missing", flush=True)
                session.send(b"e")
                session.wait_screen("Ctrl-R REMOVE INPUT", timeout=10)
                session.send(b"\x1b[200~" + editor_text.encode() + b"\x1b[201~")
                session.settle()
                session.send(b"\x14")
                screen = session.wait_screen("Captured inputs:", timeout=30)
                session.wait_screen("Enter REQUEST REVIEW", timeout=30)
                session.send(b"\r")
                session.wait_screen("Approve exact manager review", timeout=45)
                save(session, "editor-review")
                first, capture_id, raw = reviewed((), editor_bytes)
                (work / "tui-inputs-editor-review.json").write_bytes(raw)
                assert "input: capture " + capture_id in screen.replace("\n", ""), "the request screen does not name the capture"
                print("PASS tui-inputs 2: Ctrl-T captured the editor text of request", first["id"], "as capture", capture_id,
                      "and the TUI showed the exact review, which names the input as capture with", len(editor_bytes),
                      "bytes and SHA-256", hashlib.sha256(editor_bytes).hexdigest(), flush=True)
                # 2. X and y discard the review, and Enter prepares a new one.
                discarded_reviews = []
                for _ in range(2):
                    preparation_id = reviewed((), editor_bytes)[0]["preparationId"]
                    discarded_reviews.append(preparation_id)
                    session.send(b"X")
                    session.wait_screen("Confirm discard", timeout=10)
                    save(session, "discard-confirmation")
                    session.send(b"y")
                    session.wait_screen("Phase: draft", timeout=45)
                    session.wait_screen("Enter REQUEST REVIEW", timeout=30)
                    status, draft, raw = request("/v1/requests/" + first["id"], harness)
                    assert status == 200
                    validate("Request", draft, raw)
                    assert draft["phase"] == "draft" and draft["preparationId"] is None, ("the discarded request", draft["phase"], draft["preparationId"])
                    if len(discarded_reviews) == 1:
                        session.send(b"\r")
                        session.wait_screen("Approve exact manager review", timeout=45)
                        again = reviewed((), editor_bytes)[0]
                        assert again["id"] == first["id"] and again["preparationId"] != preparation_id, (
                            "the review after the discard", again["preparationId"], preparation_id)
                print("PASS tui-inputs 3: X and y discarded the review", discarded_reviews[0], "the request returned to draft with a null",
                      "preparationId, and Enter prepared the new review", discarded_reviews[1], flush=True)
                # 3. W opens the withdrawal confirmation, n closes it, and W with y withdraws.
                session.send(b"W")
                session.wait_screen("Confirm withdrawal", timeout=10)
                session.send(b"n")
                session.wait_screen("withdraw was not sent: the confirmation was closed.", timeout=10)
                status, kept, _ = request("/v1/requests/" + first["id"], harness)
                assert status == 200 and kept["phase"] == "draft" and "withdraw" not in database_commands(first["id"], discarded_reviews), (
                    "the closed confirmation withdrew the request", status, kept.get("phase"))
                session.send(b"W")
                session.wait_screen("Confirm withdrawal", timeout=10)
                session.send(b"y")
                session.wait_screen("Phase: withdrawn", timeout=30)
                save(session, "withdrawn-request")
                status, withdrawn, raw = request("/v1/requests/" + first["id"], harness)
                assert status == 200
                validate("Request", withdrawn, raw)
                assert withdrawn["phase"] == "withdrawn", ("the withdrawn request", withdrawn["phase"])
                counts = database_commands(first["id"], discarded_reviews)
                assert counts == {"remove-input": 1, "discard": 2, "withdraw": 1}, ("each confirmed operation is sent once", counts)
                print("PASS tui-inputs 4: n closed the withdrawal confirmation without a send, W and y withdrew request", first["id"],
                      "and the database holds one command of each removal, discard and withdrawal:", counts, flush=True)
                session.send(b"q")
                assert session.wait_exit(20) == 0
                session.assert_restored()
            with tui_fixture.session() as session:
                # 2. Ctrl-O opens the path editor, and Ctrl-D captures the file.
                new_request(session, index)
                session.send(b"\x0f")
                session.wait_screen("Capture a local file")
                session.send(str(work / "absent-file.txt").encode())
                session.send(b"\x04")
                session.wait_screen("ERROR: the file cannot be read", timeout=10)
                session.send(b"\x1b")
                session.wait_screen("request validator current", timeout=10)
                session.send(b"\x0f")
                session.wait_screen("Capture a local file")
                session.send(str(file_path).encode())
                session.send(b"\x04")
                session.wait_screen("Captured inputs:", timeout=30)
                session.wait_screen("Enter REQUEST REVIEW", timeout=30)
                save(session, "file-request")
                session.send(b"\r")
                session.wait_screen("Approve exact manager review", timeout=45)
                save(session, "file-review")
                second, file_capture, raw = reviewed((first["id"],), file_bytes)
                (work / "tui-inputs-file-review.json").write_bytes(raw)
                print("PASS tui-inputs 5: a missing path kept the path editor open with its read failure, and Ctrl-O captured the local file of",
                      len(file_bytes), "bytes for request", second["id"], "as capture", file_capture,
                      "with its exact SHA-256 in the review the TUI showed", flush=True)
                session.send(b"q")
                assert session.wait_exit(20) == 0
                session.assert_restored()
            # 3. The manager received the bytes and never the path.
            leaked = [str(path) for path in (work / "manager").rglob("*") if path.is_file() and marker.encode() in path.read_bytes()]
            assert leaked == [], ("a manager file names the captured file path", leaked)
            print("PASS tui-inputs 6: no file of the manager root contains the path of the captured file", flush=True)
            assert not tui_fixture.client_state.exists(), "the service TUI created local runner state"
            print("PASS tui-inputs: the editor and file captures reached the exact review, and the removal, the discards and the withdrawal",
                  "completed once each through the actual service TUI in", lifecycle_elapsed(), flush=True)
        finally:
            if process.poll() is None:
                process.terminate()
            process.wait(timeout=25)
            (work / "server-0.exit").write_text(str(process.returncode) + "\n")


def model_questions(records, occurrence):
    """The run-log questions of the occurrence to a model, in log order.
    The control modes and the tui-redirect mode share it."""
    return [record for record in records if record["schema"] == "question" and str(record["about"].get("occurrence")) == occurrence
            and isinstance(record["to"].get("to"), dict) and "model" in record["to"]["to"]]


def occurrence_of(snapshot, occurrence):
    """The occurrence of a run snapshot with the identifier."""
    assert snapshot["page"]["next"] is None, "the run snapshot has more than one page"
    found = [item for item in snapshot["items"] if item["occurrenceId"] == occurrence]
    assert len(found) == 1, ("snapshot occurrence", occurrence, len(found))
    return found[0]

def running_attempts(snapshot, occurrence):
    """The running attempts of the occurrence in a run snapshot, or none
    when the snapshot does not hold the occurrence yet."""
    found = [item for item in snapshot["items"] if item["occurrenceId"] == occurrence]
    return [attempt for item in found for attempt in item.get("attempts", []) if attempt["state"] == "running"]


def attempt_events(store, occurrence):
    """The attempt start and end events and the occurrence.redirected
    events of the occurrence in events.ndjson of the run store."""
    events = [json.loads(line) for line in (store / "events.ndjson").read_bytes().splitlines()]
    events = [event.get("event", event) for event in events]
    mine = lambda event: str(event.get("occurrenceId", (event.get("attemptId") or {}).get("occurrenceId"))) == occurrence
    attempts = [event for event in events if event["type"] in ("attempt.started", "attempt.completed", "attempt.failed") and mine(event)]
    redirected = [event for event in events if event["type"] == "occurrence.redirected" and mine(event)]
    return attempts, redirected


class ControlHarness:
    """The harness side of the modes that send run controls through a
    client: tui-controls, tui-redirect and the client-controls modes. It
    creates, approves and settles runs with the credential of the harness,
    and reads their facts. label names the evidence files that ended
    writes. client holds the read and mutation steps of mixed_client."""

    TERMINAL = ("succeeded", "failed", "cancelled")

    def __init__(self, harness, capabilities, label):
        self.harness, self.capabilities, self.label = harness, capabilities, label
        self.client = mixed_client(capabilities, harness)

    def start(self, profile, name="mixed-controls"):
        """Create, enqueue and approve one request of the named workflow of
        the profile through HTTP with the credential of the harness. Returns
        the run."""
        status, catalogue, _ = request("/v1/workflows?profileId=" + profile, self.harness)
        assert status == 200, ("control catalogue", profile, status)
        workflow = next(item for item in catalogue["items"] if item["name"] == name)
        body = {"workflowId": workflow["id"], "descriptorRevision": workflow["revision"],
                "profileId": workflow["profileId"], "profileRevision": workflow["profileRevision"]}
        key = self.capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
        status, created, raw = request("/v1/requests", self.harness | {"Content-Type": "application/json", "Idempotency-Key": key},
                                       method="POST", payload=json.dumps(body, separators=(",", ":")).encode())
        assert status == 201, ("control request creation", profile, status, created.get("code"))
        validate("Request", created, raw)
        _, run = approve_mixed(created, workflow, self.client)
        return run

    def snapshot(self, run):
        value, _, _ = self.client[0]("/v1/runs/" + run + "/snapshot", "RunSnapshot")
        return value

    def ended(self, run, expected):
        """Wait until the run is terminal, keep its snapshot and require the
        expected terminal status."""
        value, _, raw = self.client[1]("/v1/runs/" + run + "/snapshot", "RunSnapshot",
            lambda value: value["runtime"] is not None and value["runtime"]["status"] in self.TERMINAL)
        (work / (self.label + "-" + run + "-terminal.json")).write_bytes(raw)
        assert value["runtime"]["status"] == expected, ("control run terminal status", run, value["runtime"]["status"], expected)

    def offered(self, run, ready):
        """The controls of the run once the predicate holds."""
        value, _, _ = self.client[1]("/v1/runs/" + run + "/control", "RunControl", ready)
        return value

    def until_recovery(self, run):
        """Answer each question head of the run with typed false until the
        head is a recovery decision. Returns that decision."""
        observed, _, mutate, _ = self.client
        deadline = time.monotonic() + 60
        while True:
            assert time.monotonic() < deadline, ("recovery head deadline", run)
            control, _, _ = observed("/v1/runs/" + run + "/control", "RunControl")
            head = control["decisionHeadId"]
            if head is None:
                time.sleep(0.05)
                continue
            decision, tag, _ = observed("/v1/decisions/" + head, "Decision")
            if decision["kind"] == "recovery":
                return decision
            mutate("/v1/decisions/" + head, {"operation": "answer", "occurrenceId": decision["address"]["occurrenceId"],
                                             "generation": decision["generation"], "value": False}, tag)

    def settle(self, run, expected):
        """Answer each remaining question head with typed false until the
        run ends, and require the expected terminal status. A recovery head
        fails the step."""
        observed, _, mutate, _ = self.client
        deadline = time.monotonic() + 90
        while True:
            value = self.snapshot(run)
            if value["runtime"] is not None and value["runtime"]["status"] in self.TERMINAL:
                break
            assert time.monotonic() < deadline, ("settle deadline", run)
            control, _, _ = observed("/v1/runs/" + run + "/control", "RunControl")
            head = control["decisionHeadId"]
            if head is None:
                time.sleep(0.05)
                continue
            decision, tag, _ = observed("/v1/decisions/" + head, "Decision")
            assert decision["kind"] == "question", ("an unexpected recovery head", run, decision["kind"])
            mutate("/v1/decisions/" + head, {"operation": "answer", "occurrenceId": decision["address"]["occurrenceId"],
                                             "generation": decision["generation"], "value": False}, tag)
        self.ended(run, expected)

    def run_records(self, run):
        """Every run-log record of the run that GET /v1/runs/{id}/routes
        serves to the credential of the harness, over all batches."""
        records, cursor = [], None
        for _ in range(1024):
            target = f"/v1/runs/{run}/routes" + ("" if cursor is None else "?after=" + cursor)
            status, value, raw = request(target, self.harness | {"Accept": "application/json"})
            assert status == 200, ("run route batch", run, status, value.get("code"))
            validate("RouteBatch", value, raw)
            records += value["records"]
            cursor = value["cursor"]
            if not value["hasMore"]:
                return records
        raise AssertionError(("run route pages did not end", run))

    def one_control(self, run, operation, command):
        """The command is the only command of the controls of the run, and it
        reached its effect. Returns its receipt."""
        rows = self.command_rows(["/v1/runs/" + run + "/control"])
        assert [(row[0], row[1], row[2]) for row in rows] == [(command.rsplit("/", 1)[1], operation, "effect-observed")], (
            "the client did not send exactly one " + operation + " that reached its effect", run, rows)
        receipt, _, raw = self.client[0](command, "CommandReceipt")
        (work / (self.label + "-" + operation + "-receipt.json")).write_bytes(raw)
        return receipt

    @staticmethod
    def manager_control(records, command):
        """The one run-log control record of the command from the manager."""
        found = [record for record in records if record["schema"] == "control" and record["about"].get("command") == command.rsplit("/", 1)[1]]
        assert len(found) == 1 and found[0]["from"] == "manager", ("the run-log control of the command", command, found)
        return found[0]

    def steered(self, run, command, occurrence, attempt, text):
        """The steer command is the only command of the controls of the run,
        it reached the effect steered for the attempt, and the run log holds
        its one control record from the manager and one steer record, both
        with the timing interrupt-now and the text. Returns the control
        record and the steer records."""
        receipt = self.one_control(run, "steer", command)
        assert receipt["effect"]["kind"] == "steered" and receipt["effect"]["address"] == {"occurrenceId": occurrence, "attemptId": attempt}, (
            "steer effect", receipt["effect"], occurrence, attempt)
        records = self.run_records(run)
        (work / (self.label + "-steer-routes.json")).write_text(json.dumps(records, default=str))
        control = self.manager_control(records, command)
        assert control["body"]["control"]["command"] == {"type": "steerOccurrence", "timing": "interrupt-now", "text": text}, (
            "the run-log control of the steer", control["body"])
        steers = [record for record in records if record["schema"] == "steer"]
        assert [(str(record["about"].get("occurrence")), record["body"].get("steering"), record["body"].get("text")) for record in steers] == [
            (occurrence, "interrupt-now", text)], ("the run-log steer records", steers)
        return control, steers

    @staticmethod
    def command_rows(run_resources):
        """The identifier, operation, state and runtime acknowledgement of
        each command of these resources in the coordination database, in
        acceptance order, read through a read-only connection."""
        import sqlite3
        found = sorted((work / "manager").rglob("coordination.sqlite3"))
        assert len(found) == 1, ("coordination database", found)
        connection = sqlite3.connect(found[0].as_uri() + "?mode=ro", uri=True)
        try:
            marks = ",".join("?" * len(run_resources))
            return [(row[0], row[1], row[2], None if row[3] is None else json.loads(row[3])) for row in connection.execute(
                "SELECT id, operation, state, acknowledgement FROM commands WHERE resource_uri IN (" + marks + ") ORDER BY rowid",
                run_resources).fetchall()]
        finally:
            connection.close()

    @classmethod
    def commands(cls, run_resources):
        """The operations of the commands of these resources."""
        return [row[1] for row in cls.command_rows(run_resources)]

    @staticmethod
    def new_store(before):
        """The one run store that is not in before, once it exists."""
        deadline = time.monotonic() + 20
        while True:
            stores = sorted(set(work.glob("manager/runs/runs/*/runtime")) - before)
            if len(stores) == 1:
                return stores[0]
            assert len(stores) == 0 and time.monotonic() < deadline, ("new run store", stores)
            time.sleep(0.05)


def tui_control_checks():
    """The tui-controls and tui-redirect modes. See TUI_CONTROLS and
    TUI_REDIRECT for the steps. Both share the helpers below and those of
    ControlHarness."""
    harness = tui_fixture.harness

    def save(session, name):
        (work / (tui_mode + "-" + name + ".screen.txt")).write_text(session.screen.text())

    def details(screen):
        return "".join(line.split("\u2502", 1)[1].strip() for line in screen.splitlines() if "\u2502" in line)

    def open_run(session, run):
        """Open the run from its row of the Manager overview."""
        deadline = time.monotonic() + 30
        while True:
            session.send(b"\x1b[A" * 16)
            session.settle()
            for _ in range(16):
                screen = session.screen.text()
                if "> run Running" in screen and "Run:" + run in details(screen).replace(" ", ""):
                    session.send(b"\r")
                    session.wait_screen("Approval receipt:", timeout=20)
                    return session.wait_screen("Runtime: Running", timeout=20)
                session.send(b"\x1b[B")
                session.settle()
            assert time.monotonic() < deadline, ("the overview lists no running row of the run", run, session.screen.text())
            session.send(b"g")
            session.pump(0.5)

    def leave(session):
        """Esc from the live monitor back to the overview."""
        session.send(b"\x1b")
        return session.wait_screen("Manager overview", timeout=10)

    def answer_person(run):
        """Answer the person question of a held profile_steer run with typed
        false, so that the live monitor shows the held attempt without a
        question head. The steerable attempt holds its turn until a steer."""
        control = offered(run, lambda value: value["decisionHeadId"] is not None)
        decision, tag, _ = client[0]("/v1/decisions/" + control["decisionHeadId"], "Decision")
        assert decision["kind"] == "question", ("held run head", decision["kind"])
        client[2]("/v1/decisions/" + decision["id"], {"operation": "answer", "occurrenceId": decision["address"]["occurrenceId"],
                                                     "generation": decision["generation"], "value": False}, tag)
        return offered(run, lambda value: value["decisionHeadId"] is None and value["cancelAllowed"]
                       and any(offer["operation"] == "steer" for offer in value["offers"]))

    def runtime_labels(start):
        """The runtime labels that the TUI wrote to the PTY after the byte offset start."""
        text = bytes(session.output[start:]).decode("utf-8", "replace")
        return set(RUNTIME_LINE.findall(text))

    def press(keys, expect, operation, timeout=30, failure=None, forbidden=None):
        """Send the keys and wait for the expected screen text. A mutation
        key is deferred while a page-set read is in flight, and a deferred
        key is never replayed, so a new numbered key outcome that names the
        deferral of the operation sends the keys again, as the operator does.
        A redraw of an earlier key outcome is not a new deferral. A screen
        that shows the forbidden text before the expected text, or a
        deadline, fails with the failure message when one is given. Returns
        the screen and the number of deferrals."""
        deadline = time.monotonic() + timeout
        deferred = 0
        deferral = re.compile(r"Key (\d+): " + re.escape(operation) + r" deferred during a page-set read\.")
        seen = max([int(number) for number in re.findall(r"Key (\d+):", session.screen.text())], default=0)

        def shows(screen):
            # A key outcome wider than the terminal wraps over two rows.
            return expect in screen or squeeze(expect) in squeeze(screen)

        while True:
            for key in keys:
                session.send(key)
                if key != keys[-1]:
                    session.pump(0.2)
            while True:
                session.pump()
                screen = session.screen.text()
                if shows(screen):
                    session.settle()
                    return session.screen.text(), deferred
                if forbidden is not None and forbidden in screen:
                    # One frame can arrive in several reads, so the rest of
                    # the frame may still bring the expected text.
                    session.settle()
                    screen = session.screen.text()
                    assert shows(screen), (failure or "the TUI showed the forbidden text first", forbidden, screen)
                    return screen, deferred
                found = deferral.search(screen)
                if found and int(found.group(1)) > seen:
                    seen = int(found.group(1))
                    deferred += 1
                    # The read that deferred the key is still in flight, so
                    # the operator waits a moment before pressing again.
                    pause = time.monotonic() + 0.3
                    while time.monotonic() < pause:
                        session.pump(0.05)
                    break
                assert time.monotonic() < deadline and session.process.poll() is None, (
                    failure or "the TUI screen did not show the expected text", expect, session.screen.text())
            assert deferred <= 20, ("the key was deferred too often", operation, session.screen.text())

    def store_flow(name, store):
        completed = subprocess.run([str(runner), "flow", str(store)], stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=60)
        (work / (name + ".ndjson")).write_bytes(completed.stdout)
        (work / (name + ".stderr")).write_bytes(completed.stderr)
        lines = [json.loads(line) for line in completed.stdout.splitlines()]
        assert lines and "summary" in lines[-1] and completed.returncode == 0 and lines[-1]["summary"]["verified"], (
            "the flow verb did not verify the ended run log", name, completed.returncode, completed.stderr[-2000:])
        return lines[:-1]

    def redirect_window(run):
        """The redirect offer of the open dispatch window of the
        two-candidate question of the run, as the harness reads it."""
        control = offered(run, lambda value: any(offer["operation"] == "redirect" and len(offer["targets"]) == 2 for offer in value["offers"]))
        window = next(offer for offer in control["offers"] if offer["operation"] == "redirect")
        assert window["targets"][0].endswith("@primary") and window["targets"][1].endswith("@spare"), ("dispatch targets", window["targets"])
        return window

    def answer_question(run):
        """Answer the person question of a mixed-controls run with typed
        false. It is pending beside the engine question, and its question
        head would take the digit keys of the live monitor."""
        control = offered(run, lambda value: value["decisionHeadId"] is not None)
        decision, tag, _ = client[0]("/v1/decisions/" + control["decisionHeadId"], "Decision")
        assert decision["kind"] == "question", ("mixed-controls head", decision["kind"])
        client[2]("/v1/decisions/" + decision["id"], {"operation": "answer", "occurrenceId": decision["address"]["occurrenceId"],
                                                     "generation": decision["generation"], "value": False}, tag)

    def listing(occurrence, place, targets):
        """The redirect line of the live monitor for these offered targets."""
        return "Redirect occurrence " + occurrence + place + ": " + "   ".join(str(index + 1) + " " + target for index, target in enumerate(targets))

    def wait_listing(text, timeout):
        """Wait until the live monitor shows the redirect line, which wraps
        at 80 columns. Returns the screen."""
        deadline = time.monotonic() + timeout
        while squeeze(text) not in squeeze(session.screen.text()):
            assert time.monotonic() < deadline and session.process.poll() is None, (
                "the live monitor does not show the redirect line", text, session.screen.text())
            session.pump(0.05)
        session.settle()
        return session.screen.text()

    def digit(offer, target):
        """The digit key of the target in the offer."""
        return str(offer["targets"].index(target) + 1).encode()

    def redirects(run):
        """The redirect commands of the run in acceptance order."""
        return [row for row in command_rows(["/v1/runs/" + run + "/control"]) if row[1] == "redirect"]

    def held(run, occurrence):
        """The one running attempt of the occurrence."""
        value, _, _ = client[1]("/v1/runs/" + run + "/snapshot", "RunSnapshot", lambda value: len(running_attempts(value, occurrence)) == 1)
        return running_attempts(value, occurrence)[0]

    def redirect_steps(session):
        """The steps of the tui-redirect mode. See TUI_REDIRECT."""
        # 1. A window redirect, a local refusal, a rejected-stale redirect
        # and a live redirect of the held attempt.
        before = set(work.glob("manager/runs/runs/*/runtime"))
        run = start("profile_live")
        store = new_store(before)
        window = redirect_window(run)
        occurrence = window["address"]["occurrenceId"]
        first, spare = window["targets"]
        answer_question(run)
        open_run(session, run)
        wait_listing(listing(occurrence, " in its dispatch window", window["targets"]), 20)
        save(session, "live-window")
        _, deferrals = press([digit(window, first)], "Control: redirected occurrence " + occurrence + " to " + first, "redirect")
        control = offered(run, lambda value: any(offer["operation"] == "redirect" and spare in offer["targets"] and first not in offer["targets"]
                                                 for offer in value["offers"]))
        live = next(offer for offer in control["offers"] if offer["operation"] == "redirect")
        assert live["targets"] == [spare], ("live redirect targets", live["targets"])
        attempt = held(run, occurrence)
        number = attempt["address"]["attemptId"]
        shown = listing(occurrence, ", attempt " + number + " in flight", live["targets"])
        wait_listing(shown, 20)
        save(session, "live-offer")
        screen, deferred = press([b"9"], "redirect did not start: the manager offers no target 9 for occurrence " + occurrence + ".", "redirect")
        deferrals += deferred
        refusal = re.search(r"Key (\d+): redirect did not start: the manager offers no target 9", screen)
        assert refusal and len(redirects(run)) == 1, ("the digit without a target was not refused locally", refusal and refusal.group(0), redirects(run))
        _, deferred = press([digit(live, spare)], "Control: redirected occurrence " + occurrence + " from attempt " + number + " to " + spare, "redirect")
        deferrals += deferred
        save(session, "live-redirected")
        rows = redirects(run)
        assert len(rows) == 2 and rows[1][2] == "effect-observed", ("the live redirect command", rows)
        assert commands(["/v1/runs/" + run + "/control"]) == ["redirect"] * 2, "the TUI sent a command other than the two redirects"
        settle(run, "succeeded")
        completed = occurrence_of(snapshot_of(run), occurrence)
        assert completed["state"] == "completed" and completed["source"] == "asked:" + spare, (
            "live redirect answer source", completed["state"], completed["source"])
        attempts, redirected = attempt_events(store, occurrence)
        assert [event["type"] for event in attempts] == ["attempt.started", "attempt.failed", "attempt.started", "attempt.completed"], (
            "live redirect attempts", attempts)
        assert [(event["controlId"], event["target"]) for event in redirected] == [(rows[0][0], first), (rows[1][0], spare)], (
            "occurrence.redirected events", redirected)
        records = store_flow(tui_mode + "-live-flow", store)
        questions = model_questions(records, occurrence)
        assert [record["to"] for record in questions] == [{"to": {"model": first}}, {"to": {"model": spare}}], (
            "live redirect questions", [record["to"] for record in questions])
        failures = [record for record in records if record["schema"] == "failure" and record.get("replyTo") == questions[0]["position"]]
        assert len(failures) == 1, ("the failure of the held question", failures)
        print("PASS tui-redirect 1: in the dispatch window of run", run, "digit", digit(window, first).decode(), "redirected occurrence", occurrence,
              "to", first, "; while attempt", number, "held its turn, the monitor listed", live["targets"], ", 9 was refused locally as key outcome",
              refusal.group(1), "without a command, and the redirect to", spare, "showed the redirect from attempt", number, "; the stopped attempt ended",
              "attempt.failed, the run log holds the failure of question", questions[0]["position"], "and question", questions[1]["position"],
              "to", spare, ", and the run succeeded with its answer", "; deferred key presses:", deferrals, flush=True)
        leave(session)

        # 2. A dispatch-window redirect puts the chosen target first.
        before = set(work.glob("manager/runs/runs/*/runtime"))
        run = start("profile_live")
        store = new_store(before)
        window = redirect_window(run)
        occurrence = window["address"]["occurrenceId"]
        first, spare = window["targets"]
        answer_question(run)
        open_run(session, run)
        wait_listing(listing(occurrence, " in its dispatch window", window["targets"]), 20)
        _, deferrals = press([digit(window, spare)], "Control: redirected occurrence " + occurrence + " to " + spare, "redirect")
        save(session, "window-redirected")
        rows = redirects(run)
        assert len(rows) == 1 and rows[0][2] == "effect-observed", ("the window redirect command", rows)
        settle(run, "succeeded")
        completed = occurrence_of(snapshot_of(run), occurrence)
        assert completed["state"] == "completed" and completed["source"] == "asked:" + spare, (
            "window redirect answer source", completed["state"], completed["source"])
        attempts, redirected = attempt_events(store, occurrence)
        assert [event["type"] for event in attempts] == ["attempt.started", "attempt.completed"], ("window redirect attempts", attempts)
        assert [(event["controlId"], event["target"]) for event in redirected] == [(rows[0][0], spare)], ("occurrence.redirected events", redirected)
        records = store_flow(tui_mode + "-window-flow", store)
        questions = model_questions(records, occurrence)
        assert [record["to"] for record in questions] == [{"to": {"model": spare}}], ("window redirect questions", [record["to"] for record in questions])
        print("PASS tui-redirect 2: in the dispatch window of run", run, "digit", digit(window, spare).decode(), "redirected occurrence", occurrence,
              "to", spare, "; the monitor showed the redirect, the run log holds one question, question", questions[0]["position"], "to", spare,
              ", and the run succeeded with its answer", "; deferred key presses:", deferrals, flush=True)
        leave(session)

        # 3. No redirect of an effect in flight.
        before = set(work.glob("manager/runs/runs/*/runtime"))
        run = start("profile_live_effect", "controlled-effect")
        store = new_store(before)
        window = redirect_window(run)
        occurrence = window["address"]["occurrenceId"]
        first, spare = window["targets"]
        open_run(session, run)
        wait_listing(listing(occurrence, " in its dispatch window", window["targets"]), 20)
        _, deferrals = press([digit(window, first)], "Control: redirected occurrence " + occurrence + " to " + first, "redirect")
        attempt = held(run, occurrence)
        control, _, _ = client[0]("/v1/runs/" + run + "/control", "RunControl")
        assert not any(offer["operation"] == "redirect" for offer in control["offers"]), ("effect redirect offered", control["offers"])
        deadline = time.monotonic() + 5
        while "Redirect occurrence" in session.screen.text():
            assert time.monotonic() < deadline, ("the monitor still lists a redirect of the effect", session.screen.text())
            session.pump(0.1)
        save(session, "effect-in-flight")
        screen, deferred = press([b"1"], "redirect did not start: the manager offers no redirect for this run.", "redirect")
        deferrals += deferred
        refusal = re.search(r"Key (\d+): redirect did not start: the manager offers no redirect", screen)
        still = running_attempts(snapshot_of(run), occurrence)
        assert [item["address"] for item in still] == [attempt["address"]], ("the effect attempt ended before the refusal was checked", still)
        rows = redirects(run)
        assert refusal and len(rows) == 1, ("the redirect of the effect was not refused locally", refusal and refusal.group(0), rows)
        settle(run, "succeeded")
        completed = occurrence_of(snapshot_of(run), occurrence)
        assert completed["source"] == "asked:" + first, ("effect answer source", completed["source"])
        attempts, redirected = attempt_events(store, occurrence)
        assert [event["type"] for event in attempts] == ["attempt.started", "attempt.completed"], ("effect attempts", attempts)
        assert [(event["controlId"], event["target"]) for event in redirected] == [(rows[0][0], first)], ("effect occurrence.redirected events", redirected)
        print("PASS tui-redirect 3: while effect attempt", attempt["address"]["attemptId"], "of run", run, "was in flight, the monitor listed no",
              "redirect target, 1 was refused locally as key outcome", refusal.group(1), "without a command, and the run succeeded with the",
              "answer of", first, "; deferred key presses:", deferrals, flush=True)
        leave(session)

        # 4. A rejected-stale redirect shows its acknowledgement and is not sent again.
        run = start("profile_live_stale")
        window = redirect_window(run)
        occurrence = window["address"]["occurrenceId"]
        first, spare = window["targets"]
        answer_question(run)
        open_run(session, run)
        wait_listing(listing(occurrence, " in its dispatch window", window["targets"]), 20)
        _, deferrals = press([digit(window, first)], "Control: redirected occurrence " + occurrence + " to " + first, "redirect")
        attempt = held(run, occurrence)
        number = attempt["address"]["attemptId"]
        wait_listing(listing(occurrence, ", attempt " + number + " in flight", [spare]), 20)
        _, deferred = press([b"1"], "Control: redirected occurrence " + occurrence + " from attempt " + number + " to " + spare, "redirect")
        deferrals += deferred
        control = offered(run, lambda value: any(offer["operation"] == "redirect" and offer["targets"] == [first] for offer in value["offers"]))
        attempt = held(run, occurrence)
        assert attempt["address"]["attemptId"] != number, ("the spare candidate holds no new attempt", attempt["address"])
        wait_listing(listing(occurrence, ", attempt " + attempt["address"]["attemptId"] + " in flight", [first]), 20)
        save(session, "stale-offer")
        _, deferred = press([b"1"], "Control: redirect to " + first + ": runtime acknowledgement rejected-stale", "redirect")
        deferrals += deferred
        save(session, "rejected-stale")
        screen = session.screen.text()
        assert "Outcome unresolved" not in screen and "x requests an exact resend" not in screen, "the rejected redirect offered a resend"
        rows = redirects(run)
        assert len(rows) == 3 and rows[2][3] is not None and rows[2][3]["state"] == "rejected-stale" and rows[2][2] != "effect-observed", (
            "the rejected redirect command", rows)
        still = held(run, occurrence)
        assert still["address"] == attempt["address"], ("the rejected redirect stopped the attempt of the spare candidate", attempt["address"], still["address"])
        session.pump(1.0)
        assert len(redirects(run)) == 3, "the TUI sent the rejected redirect again"
        while True:
            _, deferred = press([b"c"], "Confirm cancel", "cancel")
            deferrals += deferred
            screen, deferred = press([b"y"], "Control: cancel accepted", "cancel")
            deferrals += deferred
            if "Control: cancel accepted" in screen:
                break
        ended(run, "cancelled")
        assert commands(["/v1/runs/" + run + "/control"]) == ["redirect"] * 3 + ["cancel"], "the TUI sent a command other than three redirects and one cancel"
        print("PASS tui-redirect 4: after the redirects of run", run, "to", first, "and then to", spare, ", the redirect of attempt",
              attempt["address"]["attemptId"], "back to", first, "showed its rejected-stale acknowledgement", rows[2][3]["state"],
              "without a resend offer or a second send while the attempt kept running, and c and y cancelled the run",
              "; deferred key presses:", deferrals, flush=True)
        leave(session)

    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        try:
            wait_ready(process)
            status, capabilities, _ = request("/v1/capabilities", harness)
            assert status == 200 and "control" in capabilities["scopes"]
            runs = ControlHarness(harness, capabilities, tui_mode)
            client = runs.client
            start, snapshot_of, ended, offered, settle = runs.start, runs.snapshot, runs.ended, runs.offered, runs.settle
            answer_until_recovery = runs.until_recovery
            run_records, command_rows, commands, new_store = runs.run_records, runs.command_rows, runs.commands, runs.new_store
            with tui_fixture.session() as session:
                session.wait_screen("Manager profiles")
                session.wait_screen(TUI_MODES[tui_mode][0][0])
                session.send(b"\r")
                session.wait_screen("Manager workflows")
                session.send(b"O")
                session.wait_screen("Manager overview")
                if tui_mode == TUI_REDIRECT:
                    redirect_steps(session)
                    session.send(b"q")
                    assert session.wait_exit(20) == 0
                    session.assert_restored()
                    assert not tui_fixture.client_state.exists(), "the service TUI created local runner state"
                    print("PASS tui-redirect: the dispatch-window and live redirects, the rejected-stale acknowledgement and the local refusals ran",
                          "through the actual service TUI, which quit with status 0 and restored the terminal, in", lifecycle_elapsed(), flush=True)
                    return

                # 1. c and y cancel a held run. The control presses Esc
                # instead of y, so the TUI sends no cancel.
                run = start("profile_steer")
                answer_person(run)
                open_run(session, run)
                session.wait_screen("c CANCEL", timeout=20)
                save(session, "cancel-open")
                confirm = b"\x1b" if cancel_control else b"y"
                if cancel_control:
                    print("CONTROL pressed Esc instead of y in the cancel confirmation", flush=True)
                begin = len(session.output)
                deferrals = 0
                while True:
                    _, deferred = press([b"c"], "Confirm cancel", "cancel")
                    save(session, "cancel-confirmation")
                    deferrals += deferred
                    # A deferred y closes the confirmation, so c opens it again.
                    screen, deferred = press([confirm], "Control: cancel accepted", "cancel", timeout=20,
                                             failure=CANCEL_ORDER, forbidden="Runtime: Cancelled")
                    deferrals += deferred
                    if "Control: cancel accepted" in screen:
                        break
                save(session, "cancel-accepted")
                assert commands(["/v1/runs/" + run + "/control"]) == ["cancel"], (CANCEL_ORDER, "no cancel command while the TUI shows cancel accepted")
                screen = session.wait_screen("Control: cancel accepted; the runtime status is Cancelled", timeout=30)
                assert "Runtime: Cancelled" in screen, "the live monitor does not show the cancelled runtime status"
                save(session, "cancelled")
                ended(run, "cancelled")
                labels = runtime_labels(begin)
                assert not labels & {"Succeeded", "Failed"}, ("the cancelled run was shown as finished", labels)
                text = bytes(session.output[begin:]).decode("utf-8", "replace")
                waiting = "waiting for the runtime status Cancelled" in text
                sent = commands(["/v1/runs/" + run + "/control"])
                assert sent == ["cancel"], ("the TUI sent other than one cancel", sent)
                print("PASS tui-controls 1: c and y sent one cancel of held run", run, "; the live monitor showed cancel accepted",
                      "(with the waiting line first)" if waiting else "(the receipt and the cancelled status arrived in one read)",
                      "and then the runtime status Cancelled, the run ended cancelled, and the runtime labels after the key were",
                      sorted(labels), "; deferred key presses:", deferrals, flush=True)
                leave(session)

                # 2. i and Ctrl-D steer a held run.
                run = start("profile_steer")
                control = answer_person(run)
                offer = next(offer for offer in control["offers"] if offer["operation"] == "steer")
                open_run(session, run)
                session.wait_screen("i/b STEER", timeout=20)
                _, deferrals = press([b"i"], "Steer \u00b7 interrupt-now", "steer")
                session.send("Focus on the patch \u03bb.".encode())
                session.wait_screen("Focus on the patch \u03bb.", timeout=10)
                save(session, "steer-editor")
                _, deferred = press([b"\x04"], "Control: steered", "steer")
                deferrals += deferred
                save(session, "steered")
                records = run_records(run)
                steers = [record for record in records if record["schema"] == "steer"]
                assert steers, "the run log holds no steer record"
                sent = commands(["/v1/runs/" + run + "/control"])
                assert sent == ["steer"], ("the TUI sent other than one steer", sent)
                settle(run, "succeeded")
                print("PASS tui-controls 2: i opened the steer editor below the monitor, Ctrl-D sent one interrupt-now steer of attempt",
                      offer["address"], "of run", run, "; the live monitor showed the effect steered, the run log holds", len(steers),
                      "steer record, and the run succeeded", "; deferred key presses:", deferrals, flush=True)
                leave(session)

                # 3. f fails over the recovery of a two-candidate question.
                before = set(work.glob("manager/runs/runs/*/runtime"))
                run = start("profile_route")
                store = new_store(before)
                decision = answer_until_recovery(run)
                assert any(item["choice"] == "failover" for item in decision["choices"]), ("failover not published", decision["choices"])
                open_run(session, run)
                session.wait_screen("f FAILOVER", timeout=20)
                save(session, "failover-open")
                _, deferrals = press([b"f"], "Control: failed over", "choose-recovery")
                save(session, "failed-over")
                sent = commands(["/v1/decisions/" + decision["id"]])
                assert sent == ["choose-recovery"], ("the TUI sent other than one recovery choice", sent)
                settle(run, "succeeded")
                records = store_flow("tui-controls-failover-flow", store)
                occurrence = decision["address"]["occurrenceId"]
                questions = [record for record in records if record["schema"] == "question" and str(record["about"].get("occurrence")) == occurrence
                             and isinstance(record["to"].get("to"), dict) and "model" in record["to"]["to"]]
                assert len(questions) == 2 and questions[1]["to"]["to"]["model"].endswith("@spare"), (
                    "fail-over questions", [(record["position"], record["to"]) for record in questions])
                answers = [record for record in records if record["schema"] == "answer" and record.get("replyTo") == questions[1]["position"]]
                assert len(answers) == 1 and answers[0]["from"] == {"model": questions[1]["to"]["to"]["model"]}, ("spare answer", answers)
                print("PASS tui-controls 3: f sent one failover choice for decision", decision["id"], "of run", run,
                      "; the live monitor showed failed over, the run succeeded, and its run log holds question", questions[1]["position"],
                      "to", questions[1]["to"]["to"]["model"], "with its answer", "; deferred key presses:", deferrals, flush=True)
                leave(session)

                # 4. f and i are refused locally, and a abandons.
                run = start("profile_1")
                decision = answer_until_recovery(run)
                control, _, _ = client[0]("/v1/runs/" + run + "/control", "RunControl")
                assert not any(offer["operation"] == "steer" for offer in control["offers"]), ("unexpected steer offer", control["offers"])
                open_run(session, run)
                session.wait_screen("a ABANDON", timeout=20)
                screen, deferrals = press([b"i"], "steer did not start: the manager offers no interrupt-now steer for this run.", "steer")
                first = re.search(r"Key (\d+): steer did not start: the manager offers no interrupt-now", screen)
                screen, deferred = press([b"b"], "steer did not start: the manager offers no next-boundary steer for this run.", "steer")
                deferrals += deferred
                second = re.search(r"Key (\d+): steer did not start: the manager offers no next-boundary", screen)
                assert first and second and int(second.group(1)) > int(first.group(1)), (
                    "the local refusals are not numbered outcomes", first and first.group(0), second and second.group(0))
                save(session, "refused")
                assert commands(["/v1/decisions/" + decision["id"], "/v1/runs/" + run + "/control"]) == [], "a refused key sent a command"
                _, deferred = press([b"a"], "Control: abandoned", "choose-recovery")
                deferrals += deferred
                save(session, "abandoned")
                sent = commands(["/v1/decisions/" + decision["id"]])
                assert sent == ["choose-recovery"], ("the TUI sent other than one recovery choice", sent)
                status, resolved, _ = request("/v1/decisions/" + decision["id"], harness)
                ending = resolved["code"] if status == 404 else resolved.get("state")
                assert (status == 404 and ending == "unavailable-resource") or (status == 200 and ending != "pending"), (
                    "the abandoned decision is still pending", status, ending)
                queue, _, _ = client[0]("/v1/decisions?runId=" + run, "DecisionPage")
                assert decision["id"] not in [item["id"] for item in queue["items"]], "the abandoned decision is still queued"
                settle(run, "failed")
                print("PASS tui-controls 4: i and b at the recovery decision", decision["id"], "were refused locally as key outcomes",
                      first.group(1), "and", second.group(1), "without a command, a sent one abandon choice, the live monitor showed abandoned,",
                      "the decision left the run queue (" + str(status) + " " + str(ending) + ") and run", run, "ended failed", "; deferred key presses:", deferrals, flush=True)
                session.send(b"q")
                assert session.wait_exit(20) == 0
                session.assert_restored()
            assert not tui_fixture.client_state.exists(), "the service TUI created local runner state"
            print("PASS tui-controls: the cancel, steer, fail-over and abandon controls ran through the actual service TUI in", lifecycle_elapsed(), flush=True)
        finally:
            if process.poll() is None:
                process.terminate()
            process.wait(timeout=25)
            (work / "server-0.exit").write_text(str(process.returncode) + "\n")


def decisions_checks():
    """The tui-decisions mode. See TUI_DECISIONS for the steps."""
    harness = tui_fixture.harness
    requests = work / "adapter-requests"
    terminal = ("succeeded", "failed", "cancelled")

    def save(session, name):
        (work / ("tui-decisions-" + name + ".screen.txt")).write_text(session.screen.text())

    def details(screen):
        """The details column joined without separators, so that a long
        identifier that wraps across rows stays one string."""
        return "".join(line.split("\u2502", 1)[1].strip() for line in screen.splitlines() if "\u2502" in line).replace(" ", "")

    def start(client, profile, name="prompt-source"):
        """Create, enqueue and approve one request of the named workflow and
        profile through HTTP with the credential of the harness. Returns the
        run, its pending decision head and its run store."""
        before = set(work.glob("manager/runs/runs/*/runtime"))
        status, catalogue, _ = request("/v1/workflows?profileId=" + profile, harness)
        assert status == 200, ("decisions catalogue", profile, status)
        workflow = next(item for item in catalogue["items"] if item["name"] == name)
        key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
        body = {"workflowId": workflow["id"], "descriptorRevision": workflow["revision"],
                "profileId": workflow["profileId"], "profileRevision": workflow["profileRevision"]}
        status, created, raw = request("/v1/requests", harness | {"Content-Type": "application/json", "Idempotency-Key": key},
                                       method="POST", payload=json.dumps(body, separators=(",", ":")).encode())
        assert status == 201, ("decisions request creation", status, created.get("code"))
        validate("Request", created, raw)
        _, run = approve_mixed(created, workflow, client)
        control, _, _ = client[1]("/v1/runs/" + run + "/control", "RunControl", lambda value: value["decisionHeadId"] is not None)
        stores = sorted(set(work.glob("manager/runs/runs/*/runtime")) - before)
        assert len(stores) == 1, ("decisions run stores", run, stores)
        return run, control["decisionHeadId"], stores[0]

    def focused(session, decision):
        """Wait until the focused row of the Decisions view shows this
        decision in its details. Returns the screen."""
        deadline = time.monotonic() + 10
        while True:
            screen = session.screen.text()
            if "Decision:" + decision in details(screen):
                return screen
            assert time.monotonic() < deadline, ("the focused decision row is not the decision", decision, screen)
            session.pump(0.1)

    def send_answer(session):
        """Press Ctrl-D twice in one write until the TUI starts the answer.
        The first press starts the answer, and the second must show the
        numbered key outcome of an answer in flight. An answer key is
        deferred while a page-set read is in flight, and a deferred key is
        never replayed, so a new numbered key outcome that names the deferral
        sends both presses again, as the operator does. Any other key outcome
        fails. Returns the number of the in-flight key outcome."""
        deferral = re.compile(r"Key (\d+): answer deferred during a page-set read\.")
        in_flight = re.compile(r"Key (\d+): answer did not start: an answer to this decision is in flight\.")
        refusal = re.compile(r"Key (\d+): (.*)")
        seen = max([int(number) for number in re.findall(r"Key (\d+):", session.screen.text())], default=0)
        for _ in range(10):
            session.send(b"\x04\x04")
            deadline = time.monotonic() + 15
            while True:
                session.pump()
                screen = session.screen.text()
                found = in_flight.search(screen)
                if found and int(found.group(1)) > seen:
                    # Only an answer to this decision in the command lane
                    # gives this outcome, so the first press started it.
                    return int(found.group(1))
                found = deferral.search(screen)
                if found and int(found.group(1)) > seen:
                    seen = int(found.group(1))
                    session.settle()
                    seen = max([seen] + [int(number) for number in re.findall(r"Key (\d+):", session.screen.text())])
                    break
                other = refusal.search(screen)
                assert not (other and int(other.group(1)) > seen), ("the answer key was refused", other.group(2) if other else "")
                assert time.monotonic() < deadline, ("the answer key showed no outcome", screen)
        raise AssertionError("the answer did not start after ten presses")

    def answer(session, run, store, text):
        """Enter on the focused head opens its run at the head. The TUI types
        the answer and sends it with Ctrl-D. The run must succeed with the
        typed text as its only recorded answer."""
        session.send(b"\r")
        screen = session.wait_screen("Your answer", timeout=20)
        save(session, run + "-head")
        assert "Esc DECISIONS" in screen, ("the live monitor of a run opened from the Decisions view does not name Esc DECISIONS", screen)
        session.send(text.encode())
        session.wait_screen(text, timeout=10)
        outcomes.append(send_answer(session))
        try:
            snapshot, _, raw = client[1]("/v1/runs/" + run + "/snapshot", "RunSnapshot",
                lambda value: value["runtime"] is not None and value["runtime"]["status"] in terminal)
        finally:
            save(session, run + "-sent")
            _, _, control = client[0]("/v1/runs/" + run + "/control", "RunControl")
            (work / ("tui-decisions-" + run + "-control.json")).write_bytes(control)
        (work / ("tui-decisions-" + run + "-terminal.json")).write_bytes(raw)
        assert snapshot["runtime"]["status"] == "succeeded", ("decisions run terminal status", run, snapshot["runtime"]["status"])
        answers = json.loads((store / "answers.json").read_bytes())["answers"]
        assert [record["answer"] for record in answers] == [text], ("recorded answers", run, [record["answer"] for record in answers])
        published = [(item["occurrenceId"], item["answer"], item["source"]) for item in snapshot["items"]]
        assert published == [("0", text, "asked:person model:fixed-point")], ("the published answer of the run", run, published)
        assert [(ack["command"], ack["state"]) for ack in snapshot["controlAcks"]] == [("answer", "delivered")], (
            "the run does not acknowledge exactly one delivered answer", run, snapshot["controlAcks"])
        relayed = requests.read_text().splitlines() if requests.exists() else []
        assert "session/prompt" not in relayed, ("the adapter received a turn for a person-routed ask", relayed)
        save(session, run + "-answered")

    outcomes = []

    def back(session, count):
        """Esc from the live monitor returns to the Decisions view, which
        must list this number of pending heads without a key press."""
        session.send(b"\x1b")
        session.wait_screen("Manager decisions", timeout=10)
        return session.wait_screen("Decisions: current; pending heads: " + str(count), timeout=10)

    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        try:
            wait_ready(process)
            status, capabilities, _ = request("/v1/capabilities", harness)
            assert status == 200
            client = mixed_client(capabilities, harness)
            with tui_fixture.session() as session:
                # 1. D opens the Decisions view, which shows no pending head.
                session.wait_screen("Manager profiles")
                session.wait_screen("profile_1")
                session.send(b"\r")
                session.wait_screen("Manager workflows")
                session.wait_screen("D DECISIONS")
                session.send(b"D")
                session.wait_screen("Manager decisions")
                screen = session.wait_screen("Decisions: current; pending heads: 0", timeout=20)
                assert "No rows are visible." in screen, "the empty Decisions view lists a row"
                save(session, "empty")
                status, listed, _ = request("/v1/decisions", harness)
                assert status == 200 and listed["items"] == [], ("the manager lists a pending decision head", status, listed.get("items"))
                print("PASS tui-decisions 1: D on the workflows browser opens the Decisions view, which shows no pending head", flush=True)

                # 2. Two person-routed asks appear in manager observation order.
                run_a, head_a, store_a = start(client, "profile_1")
                run_b, head_b, store_b = start(client, "profile_2")
                screen = session.wait_screen("Decisions: current; pending heads: 2", timeout=10)
                status, listed, raw = request("/v1/decisions", harness)
                assert status == 200, ("decision heads", status)
                validate("DecisionPage", listed, raw)
                (work / "tui-decisions-heads.json").write_bytes(raw)
                order = [item["id"] for item in listed["items"]]
                assert sorted(order) == sorted([head_a, head_b]), ("the decision heads are not the heads of the two runs", order, head_a, head_b)
                for item in listed["items"]:
                    assert item["question"]["code"] == "text" and item["question"]["addressee"] == "person model:fixed-point", (
                        "a head is not the person-routed ask", item["id"], item["question"]["code"], item["question"]["addressee"])
                runs = {head_a: (run_a, store_a), head_b: (run_b, store_b)}
                session.send(b"\x1b[A" * 4)
                session.settle()
                for index, decision in enumerate(order):
                    screen = focused(session, decision)
                    shown = details(screen)
                    for line in ("Run:" + runs[decision][0], "Kind:question", "Answertype:text", "Addressee:personmodel:fixed-point"):
                        assert line in shown, ("the focused head lacks a detail line", decision, line)
                    if index + 1 < len(order):
                        session.send(b"\x1b[B")
                        session.settle()
                save(session, "two-heads")
                print("PASS tui-decisions 2: without a key press the Decisions view lists heads", ", ".join(order),
                      "in the order of GET /v1/decisions, each a text ask addressed to person model:fixed-point", flush=True)

                # 3. Enter on the second head opens its run, and the typed answer completes it.
                second = order[1]
                run, store = runs[second]
                answer(session, run, store, "Answered from the Decisions view, second head.")
                other, _, _ = client[0]("/v1/decisions/" + order[0], "Decision")
                assert other["state"] == "pending", ("the answer reached the other head", order[0], other["state"])
                print("PASS tui-decisions 3: Enter on head", second, "opened run", run, "at its head with Esc DECISIONS, the typed",
                      "answer completed the run with that text as its only recorded answer and no adapter turn, and head", order[0],
                      "stayed pending", flush=True)

                # 4. Esc returns to the Decisions view without the answered head.
                screen = back(session, 1)
                first = order[0]
                focused(session, first)
                save(session, "one-head")
                status, listed, _ = request("/v1/decisions", harness)
                assert status == 200 and [item["id"] for item in listed["items"]] == [first], (
                    "the manager does not list exactly the other head", status, listed.get("items"))
                run, store = runs[first]
                answer(session, run, store, "Answered from the Decisions view, first head.")
                print("PASS tui-decisions 4: without a key press the Decisions view dropped head", second, "and listed only head", first,
                      ", and its typed answer completed run", run, flush=True)

                # 5. The Decisions view lists no pending head.
                screen = back(session, 0)
                assert "No rows are visible." in screen, "the Decisions view still lists a row"
                save(session, "done")
                status, listed, _ = request("/v1/decisions", harness)
                assert status == 200 and listed["items"] == [], ("the manager still lists a pending decision head", status, listed.get("items"))
                print("PASS tui-decisions 5: after both answers the Decisions view lists no pending head; the second Ctrl-D of each answer",
                      "showed the in-flight key outcomes", outcomes, flush=True)

                # 6. A structured question shows its schema, and a wrong field type is refused locally.
                run, first, store = start(client, "profile_1", "structured-person")
                session.wait_screen("Decisions: current; pending heads: 1", timeout=10)
                status, listed, _ = request("/v1/decisions", harness)
                assert status == 200 and [item["id"] for item in listed["items"]] == [first] and "json" in listed["items"][0]["question"]["code"] \
                    and sorted(listed["items"][0]["question"]["editorSchema"]["properties"]) == ["notes", "ok"], (
                    "the manager does not list exactly the structured head", status, listed.get("items"))
                screen = focused(session, first)
                shown = details(screen)
                for line in ("Run:" + run, "Answertype:structured", "Answerschema:{\"notes\":[string],\"ok\":boolean}", "Addressee:personfirst"):
                    assert line in shown, ("the structured head lacks a detail line", first, line)
                session.send(b"\r")
                session.wait_screen("Your answer", timeout=20)
                screen = session.wait_screen("structured JSON {\"notes\": [string], \"ok\": boolean}", timeout=10)
                save(session, "structured-head")
                invalid = '{"ok": "yes", "notes": []}'
                session.send(invalid.encode())
                session.wait_screen(invalid, timeout=10)
                seen = max([int(number) for number in re.findall(r"Key (\d+):", session.screen.text())], default=0)
                session.send(b"\x04")
                refused = re.compile(r"Key (\d+): answer did not start: answer field ok must be a boolean")
                deadline = time.monotonic() + 10
                while not ((found := refused.search(session.screen.text())) and int(found.group(1)) > seen):
                    assert time.monotonic() < deadline, ("the invalid structured answer was not refused locally", session.screen.text())
                    session.pump(0.1)
                save(session, "structured-refused")
                pending, _, _ = client[0]("/v1/decisions/" + first, "Decision")
                assert pending["state"] == "pending", ("a locally refused answer changed the decision", pending["state"])
                print("PASS tui-decisions 6: the structured head of run", run, "showed its answer schema, and the answer with a string",
                      "field ok was refused before any send as key outcome", found.group(1), "while decision", first, "stayed pending", flush=True)

                # 7. A stale answer receives 412, keeps its draft and sends nothing by itself.
                session.send(b"\x7f" * len(invalid))
                deadline = time.monotonic() + 10
                while invalid in session.screen.text():
                    assert time.monotonic() < deadline, ("the editor kept the invalid text", session.screen.text())
                    session.pump(0.1)
                draft = '{"ok": true, "notes": ["kept draft"]}'
                session.send(draft.encode())
                session.wait_screen(draft, timeout=10)
                head, tag, _ = client[0]("/v1/decisions/" + first, "Decision")
                theirs = {"ok": False, "notes": ["harness answer"]}
                os.kill(session.process.pid, signal.SIGSTOP)
                try:
                    client[2]("/v1/decisions/" + first, {"operation": "answer", "occurrenceId": head["address"]["occurrenceId"],
                                                         "generation": head["generation"], "value": theirs}, tag)
                    session.send(b"\x04")
                finally:
                    os.kill(session.process.pid, signal.SIGCONT)
                screen = session.wait_screen("answer refused: 412 stale-revision; decision changed; draft kept", timeout=20)
                save(session, "stale-refused")
                control, _, _ = client[1]("/v1/runs/" + run + "/control", "RunControl",
                                          lambda value: value["decisionHeadId"] not in (None, first))
                second = control["decisionHeadId"]
                screen = session.wait_screen("Request 2 \u00b7 structured JSON", timeout=20)
                assert draft in screen, ("the second question does not show the kept draft", screen)
                save(session, "stale-kept")
                time.sleep(2)
                waiting, _, _ = client[0]("/v1/decisions/" + second, "Decision")
                assert waiting["state"] == "pending", ("the TUI sent the kept draft by itself", waiting["state"])
                recorded = [record["answer"] for record in json.loads((store / "answers.json").read_bytes())["answers"]]
                assert recorded == [theirs], ("the stale TUI answer reached the run", recorded)
                outcomes.append(send_answer(session))
                try:
                    snapshot, _, raw = client[1]("/v1/runs/" + run + "/snapshot", "RunSnapshot",
                        lambda value: value["runtime"] is not None and value["runtime"]["status"] in terminal)
                finally:
                    save(session, "structured-sent")
                (work / ("tui-decisions-" + run + "-terminal.json")).write_bytes(raw)
                assert snapshot["runtime"]["status"] == "succeeded", ("structured run terminal status", run, snapshot["runtime"]["status"])
                recorded = {record["occurrenceId"]: record["answer"] for record in json.loads((store / "answers.json").read_bytes())["answers"]}
                assert recorded == {"0": theirs, "1": json.loads(draft)}, ("structured recorded answers by occurrence", recorded)
                # The snapshot publishes a structured answer as its compact JSON text.
                published = {item["occurrenceId"]: json.loads(item["answer"]) for item in snapshot["items"]}
                assert published == recorded, ("the published answers of the structured run", published)
                print("PASS tui-decisions 7: the TUI answer to decision", first, "after the harness answer received 412 stale-revision,",
                      "the draft moved to decision", second, "without a send, and Ctrl-D sent it, so run", run,
                      "recorded the typed values", recorded, flush=True)
                session.send(b"q")
                assert session.wait_exit(20) == 0
                session.assert_restored()
            print("PASS tui-decisions: person-routed asks were answered from the Decisions view of the actual service TUI in", lifecycle_elapsed(), flush=True)
        finally:
            if process.poll() is None:
                process.terminate()
            process.wait(timeout=25)
            (work / "server-0.exit").write_text(str(process.returncode) + "\n")


def history_checks():
    """The tui-history mode. See TUI_HISTORY for the steps."""
    harness = tui_fixture.harness
    clone_legacy_runs(legacy_frontend_run(), HISTORY_LEGACY_ENTRIES - 1)
    terminal = ("succeeded", "failed", "cancelled")

    def save(session, name):
        (work / ("tui-history-" + name + ".screen.txt")).write_text(session.screen.text())

    def run_to_success(client):
        """Create, enqueue, approve and complete one prompt-source request of
        profile_1 through HTTP with the credential of the harness. Returns
        the run identifier."""
        status, catalogue, _ = request("/v1/workflows?profileId=profile_1", harness)
        assert status == 200, ("history catalogue", status)
        workflow = next(item for item in catalogue["items"] if item["name"] == "prompt-source")
        key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
        body = {"workflowId": workflow["id"], "descriptorRevision": workflow["revision"],
                "profileId": workflow["profileId"], "profileRevision": workflow["profileRevision"]}
        status, created, raw = request("/v1/requests", harness | {"Content-Type": "application/json", "Idempotency-Key": key},
                                       method="POST", payload=json.dumps(body, separators=(",", ":")).encode())
        assert status == 201, ("history request creation", status, created.get("code"))
        validate("Request", created, raw)
        _, run = approve_mixed(created, workflow, client)
        snapshot, _, raw = client[1]("/v1/runs/" + run + "/snapshot", "RunSnapshot",
            lambda value: value["runtime"] is not None and value["runtime"]["status"] in terminal)
        (work / ("tui-history-" + run + "-terminal.json")).write_bytes(raw)
        assert snapshot["runtime"]["status"] == "succeeded", ("history run terminal status", run, snapshot["runtime"]["status"])
        return run

    def all_runs():
        """Every page of /v1/runs of the harness credential, in order."""
        pages, raws = [], []
        target = "/v1/runs"
        while target is not None:
            status, value, raw = request(target, harness)
            assert status == 200, ("history run page", target, status, value.get("code"))
            validate("RunPage", value, raw)
            assert value["page"]["index"] == len(pages), ("history page index", value["page"]["index"], len(pages))
            pages.append(value)
            raws.append(raw)
            target = value["page"]["next"]
        (work / "tui-history-runs.ndjson").write_bytes(b"\n".join(raws) + b"\n")
        return [item for page in pages for item in page["items"]]

    def open_detail(session, run):
        """Enter opens the read-only detail of the focused run."""
        session.send(b"\r")
        session.wait_screen("Manager run detail", timeout=10)
        screen = session.wait_screen("Run detail: current", timeout=20)
        assert "Run: " + run in screen, ("the run detail names another run", run, screen)
        return screen

    def retrieve(session):
        """r retrieves the verified result of the shown run."""
        session.send(b"r")
        return session.wait_screen("Result: verified ", timeout=30)

    def back(session):
        session.send(b"\x1b")
        return session.wait_screen("History: current; runs: " + str(HISTORY_LEGACY_ENTRIES + 2), timeout=15)

    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "--legacy-history", f"{LEGACY_ROOT}=profile_1",
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        try:
            wait_ready(process)
            status, capabilities, _ = request("/v1/capabilities", harness)
            assert status == 200
            client = mixed_client(capabilities, harness)
            with tui_fixture.session() as session:
                # 1. H opens the History view with the legacy entries only.
                session.wait_screen("Manager profiles")
                session.wait_screen("profile_1")
                session.send(b"\r")
                session.wait_screen("Manager workflows")
                session.wait_screen("H HISTORY")
                session.send(b"H")
                session.wait_screen("Manager history")
                screen = session.wait_screen(f"History: current; runs: {HISTORY_LEGACY_ENTRIES} (managed 0, legacy {HISTORY_LEGACY_ENTRIES})", timeout=30)
                assert "Supervision: observer" in screen, ("the first legacy entry does not show observer supervision", screen)
                save(session, "legacy-only")
                listed = all_runs()
                assert len(listed) == HISTORY_LEGACY_ENTRIES and all(item["supervision"] == "observer" for item in listed), (
                    "the manager history is not the legacy entries only", len(listed))
                print("PASS tui-history 1: H on the workflows browser opens the History view, which lists the",
                      HISTORY_LEGACY_ENTRIES, "legacy entries with observer supervision and no managed run", flush=True)

                # 2. Two runs complete, and the view counts them without a key press.
                earlier = run_to_success(client)
                later = run_to_success(client)
                screen = session.wait_screen(f"History: current; runs: {HISTORY_LEGACY_ENTRIES + 2} (managed 2, legacy {HISTORY_LEGACY_ENTRIES})",
                                             timeout=30)
                save(session, "two-runs")
                print("PASS tui-history 2: runs", earlier, "and", later, "succeeded through HTTP, and without a key press the History view",
                      "counted both managed runs and the", HISTORY_LEGACY_ENTRIES, "legacy entries", flush=True)

                # 3. The TUI lists every run in the identifier order of all windows.
                listed = all_runs()
                order = [item["id"] for item in listed]
                assert len(order) == HISTORY_LEGACY_ENTRIES + 2 and len(set(order)) == len(order), ("history run count", len(order))
                assert order == sorted(order), "the /v1/runs items are not in identifier order"
                legacy_positions = [index for index, item in enumerate(listed) if item["supervision"] == "observer"]
                assert len(legacy_positions) == HISTORY_LEGACY_ENTRIES and len(legacy_positions) > 256, (
                    "the legacy entries do not exceed one window", len(legacy_positions))
                samples = [(order.index(earlier), earlier), (order.index(later), later)] + [
                    (legacy_positions[place], order[legacy_positions[place]]) for place in (0, 255, 256, len(legacy_positions) - 1)]
                for index, run in sorted(samples):
                    shown = history_focus(session, index, run)
                    if run in (earlier, later):
                        supervision = next(item["supervision"] for item in listed if item["id"] == run)
                        assert supervision != "observer", ("a managed run has observer supervision", run)
                        for line in ("Runtimestatus:Succeeded", "Supervision:" + supervision):
                            assert line in shown, ("the managed run row lacks a detail line", run, line)
                    else:
                        assert "Supervision:observer" in shown, ("the legacy row lacks observer supervision", run)
                save(session, "order")
                print("PASS tui-history 3: the harness read", len(order), "runs over every page of /v1/runs in identifier order, more legacy",
                      "entries than one window holds, and the History rows at positions", sorted(index for index, _ in samples),
                      "named the same runs, both managed runs and the legacy entries on both sides of the window bound", flush=True)

                # 4. The verified result of the earlier run is retrieved and saved with exact bytes.
                history_focus(session, order.index(earlier), earlier)
                screen = open_detail(session, earlier)
                assert "Runtime status: Succeeded" in screen and "Result: r retrieves the verified bytes" in screen, (
                    "the run detail of the earlier run is not a succeeded run before retrieval", screen)
                save(session, "earlier-detail")
                screen = retrieve(session)
                save(session, "earlier-retrieved")
                retrieved_screen = session.screen.text()
                saved_path = work / "tui-history-saved-result.bin"
                assert not os.path.lexists(saved_path)
                session.wait_screen("s SAVE RESULT", timeout=10)
                session.send(b"s")
                session.wait_screen("Save verified result", timeout=10)
                session.send(str(saved_path).encode())
                session.send(b"\x04")
                artifact = verified_download(earlier, client, harness)
                size = int(artifact["bytes"])
                outcome = "Saved the verified " + str(size) + " bytes to " + str(saved_path)
                deadline = time.monotonic() + 15
                while squeeze(outcome) not in squeeze(session.screen.text()):
                    assert time.monotonic() < deadline, ("the TUI save outcome did not appear", session.screen.text())
                    session.pump()
                save(session, "earlier-saved")
                assert squeeze("Result SHA-256: " + artifact["sha256"]) in squeeze(retrieved_screen), (
                    "the run detail does not show the artifact digest")
                saved = saved_path.read_bytes()
                saved_status = os.lstat(saved_path)
                downloaded = (work / "verified-result.json").read_bytes()
                assert stat.S_ISREG(saved_status.st_mode) and stat.S_IMODE(saved_status.st_mode) == 0o600, ("saved mode", oct(saved_status.st_mode))
                assert saved == downloaded and len(saved) == size and hashlib.sha256(saved).hexdigest() == artifact["sha256"], (
                    "the saved bytes differ from the artifact bytes")
                print("PASS tui-history 4: the read-only detail of run", earlier, "showed Succeeded, r retrieved its verified result, and s saved",
                      size, "bytes with mode 0600 that equal the artifact bytes and SHA-256", artifact["sha256"], "of the harness download", flush=True)

                # 5. The results of both runs are kept by run identifier.
                back(session)
                history_focus(session, order.index(later), later)
                open_detail(session, later)
                retrieve(session)
                save(session, "later-retrieved")
                outputs, _, _ = client[0]("/v1/runs/" + later + "/outputs", "OutputPage")
                later_result = next(item for item in outputs["items"] if item["kind"] == "result")
                assert later_result["verification"]["state"] == "verified", ("the later result is not verified", later_result["verification"])
                for text in ("Result: verified " + later_result["artifact"]["bytes"] + " bytes", "Result SHA-256: " + later_result["artifact"]["sha256"]):
                    assert squeeze(text) in squeeze(session.screen.text()), ("the later run detail does not show the published result", text)
                back(session)
                history_focus(session, order.index(earlier), earlier)
                screen = open_detail(session, earlier)
                screen = session.wait_screen("Result: verified " + str(size) + " bytes", timeout=10)
                assert "Result: r retrieves the verified bytes" not in screen and "s SAVE RESULT" in screen, (
                    "the earlier run lost its retained result", screen)
                save(session, "earlier-kept")
                print("PASS tui-history 5: after the retrieval of run", later, "the detail of run", earlier,
                      "still showed its retained verified result without another r", flush=True)

                # 6. A legacy entry shows its representation and no retrieval.
                back(session)
                legacy = order[legacy_positions[0]]
                history_focus(session, legacy_positions[0], legacy)
                screen = open_detail(session, legacy)
                assert "Supervision: observer" in screen and "a legacy entry publishes no size and digest" in screen, (
                    "the legacy detail lacks its supervision or its result line", screen)
                session.send(b"r")
                session.wait_screen("result not retrieved: a legacy entry publishes no size and digest for its result", timeout=10)
                save(session, "legacy-detail")
                legacy_view, _, _ = client[0]("/v1/runs/" + legacy, "Run")
                assert legacy_view["supervision"] == "observer", ("the manager does not publish the legacy entry as observed", legacy_view["supervision"])
                print("PASS tui-history 6: the detail of legacy entry", legacy, "showed observer supervision, and r stated that a legacy entry",
                      "publishes no size and digest for its result", flush=True)

                # 7. The earlier run is exported once, and its export download verifies.
                back(session)
                history_focus(session, order.index(earlier), earlier)
                open_detail(session, earlier)
                session.wait_screen("e EXPORT", timeout=10)
                export_name = "tui-history-export.json"
                session.send(b"e")
                session.wait_screen("Export verified result", timeout=10)
                session.send(export_name.encode())
                session.send(b"\x04")
                deadline = time.monotonic() + 30
                while not all(squeeze(text) in squeeze(session.screen.text()) for text in ("Export " + export_name + ": export_", "state published",
                                                                                           "Export download: verified ")):
                    assert time.monotonic() < deadline, ("the TUI export outcome did not appear", session.screen.text())
                    session.pump()
                save(session, "export")
                status, exports, raw = request("/v1/runs/" + earlier + "/exports", harness)
                assert status == 200, ("history export collection", status, exports.get("code"))
                validate("ExportPage", exports, raw)
                (work / "tui-history-exports.json").write_bytes(raw)
                assert len(exports["items"]) == 1, ("the export was not published once", exports["items"])
                receipt = exports["items"][0]
                assert receipt["name"] == export_name and receipt["state"] == "published" and receipt["runId"] == earlier, receipt
                assert squeeze("Export " + export_name + ": " + receipt["id"] + " state published") in squeeze(session.screen.text()), (
                    "the TUI does not show the published export receipt", receipt["id"])
                assert squeeze("Export download: verified " + receipt["bytes"] + " bytes, SHA-256 " + receipt["sha256"]) in squeeze(
                    session.screen.text()), ("the TUI does not show the verified size and SHA-256 of the export", receipt["bytes"], receipt["sha256"])
                connection = http.client.HTTPSConnection("127.0.0.1", port, context=context, timeout=15)
                try:
                    connection.request("GET", receipt["download"], headers=harness | {"Accept": "application/octet-stream"})
                    response = connection.getresponse()
                    exported = response.read(int(receipt["bytes"]) + 1)
                    assert response.status == 200 and response.getheader("Content-Type") == "application/octet-stream", (
                        "history export download", response.status)
                finally:
                    connection.close()
                (work / "tui-history-export.bin").write_bytes(exported)
                published = work / "manager" / "runs" / "exports" / export_name
                assert len(exported) == int(receipt["bytes"]) and hashlib.sha256(exported).hexdigest() == receipt["sha256"], (
                    "the export download differs from its receipt")
                assert published.read_bytes() == exported, "the export download differs from the published file"
                result = frozen.parse_json(downloaded)["result"]
                document = json.dumps(result, separators=(",", ":"), ensure_ascii=False).encode() + b"\n"
                assert exported == document and frozen.parse_json(exported) == result, (
                    "the exported bytes are not the code and value of the verified result", exported, document)
                print("PASS tui-history 7: e on the detail of run", earlier, "exported its verified result once as", export_name,
                      "; the TUI showed receipt", receipt["id"], "with the state published and the verified", receipt["bytes"],
                      "bytes with SHA-256", receipt["sha256"], ", and the harness download and the published file hold the code and value",
                      "of the verified result bytes as compact JSON followed by one LF", flush=True)

                # 8. l and r restart the earlier run, and the approved child run succeeds.
                def shown(text, timeout):
                    """Wait until the screen shows the text, also when it wraps."""
                    deadline = time.monotonic() + timeout
                    while squeeze(text) not in squeeze(session.screen.text()):
                        assert time.monotonic() < deadline, ("the TUI did not show", text, session.screen.text())
                        session.pump(0.1)
                    return session.screen.text()

                def mutation_key(key, expected, timeout):
                    """Send a mutation key until the screen shows the expected text.
                    A key that a page-set read deferred, or an approval that a
                    transient lane state deferred, shows a numbered outcome and
                    sends nothing, so the key is sent again, as an operator
                    does."""
                    deferred = re.compile(r"(Key|Approval key) (\d+): (\S+ deferred during a page-set read|Approval did not start: "
                                          r"(a manager command is in progress|the displayed review is stale))")
                    seen = {match.group(2) for match in deferred.finditer(session.screen.text())}
                    deadline = time.monotonic() + timeout
                    session.send(key)
                    while squeeze(expected) not in squeeze(session.screen.text()):
                        assert time.monotonic() < deadline, ("the TUI did not show", expected, session.screen.text())
                        fresh = {match.group(2) for match in deferred.finditer(session.screen.text())} - seen
                        if fresh:
                            seen |= fresh
                            session.send(key)
                        session.pump(0.1)
                    return session.screen.text()

                def lineage_page(run):
                    status, value, raw = request("/v1/runs/" + run + "/lineage-requests", harness)
                    assert status == 200, ("history lineage collection", run, status, value.get("code"))
                    validate("LineagePage", value, raw)
                    return value, raw

                def settled(run):
                    """Wait until the supervision of the run ended."""
                    return client[1]("/v1/runs/" + run, "Run", lambda value: value["supervision"] not in ("owned", "cleanup-pending"))[0]

                def child_request(run, operation):
                    """The one child request of the run with this operation."""
                    page, raw = lineage_page(run)
                    (work / ("tui-history-lineage-" + operation + ".json")).write_bytes(raw)
                    children = [item for item in page["items"] if item["lineage"] == operation]
                    assert len(children) == 1 and children[0]["parentRunId"] == run, ("the lineage collection of the run", run, page["items"])
                    return children[0]

                def child_review(child):
                    """The live preparation of the child request."""
                    deadline = time.monotonic() + 30
                    while True:
                        current, _, _ = client[0]("/v1/requests/" + child["id"], "Request")
                        if current["preparationId"] is not None:
                            break
                        assert time.monotonic() < deadline, ("the child request has no preparation", child["id"])
                        time.sleep(0.1)
                    preparation, _, raw = client[0]("/v1/preparations/" + current["preparationId"], "Preparation")
                    (work / ("tui-history-review-" + child["lineage"] + ".json")).write_bytes(raw)
                    return preparation

                settled(earlier)
                session.send(b"l")
                shown("Lineage of run " + earlier, 15)
                shown("r restart: eligible", 10)
                assert all(squeeze(line) in squeeze(session.screen.text()) for line in ("s resume: eligible", "f fork: eligible")), (
                    "the lineage menu does not list every operation as eligible", session.screen.text())
                save(session, "lineage-menu")
                mutation_key(b"r", "Lineage: restart of run " + earlier + "; the inputs come from the parent run", 30)
                session.wait_screen("Enter REQUEST REVIEW", timeout=30)
                save(session, "restart-request")
                restart_child = child_request(earlier, "restart")
                assert restart_child["phase"] == "draft" and squeeze("Request: " + restart_child["id"]) in squeeze(session.screen.text()), (
                    "the TUI does not show the restart child request", restart_child["id"])
                mutation_key(b"\r", "Approve exact manager review", 45)
                shown("Lineage: restart of run " + earlier, 10)
                shown("Lineage edits: none", 10)
                save(session, "restart-review")
                preparation = child_review(restart_child)
                assert preparation["review"]["lineage"] == {"parentRunId": earlier, "operation": "restart", "edits": []}, (
                    "the restart review lineage", preparation["review"].get("lineage"))
                # The complete summary review fits 80x24, its two lineage
                # rows and all five selectors included, so y approves there.
                # The key bar offers y only for a current review that fits.
                shown("y APPROVE EXACT REVIEW AND RUN", 10)
                shown("Preparation: " + preparation["id"], 10)
                for name in ("reviewDigest", "requestRevision", "profileRevision", "descriptorRevision", "processGeneration"):
                    shown(name + preparation[name], 10)
                assert "RESIZE TO REVIEW" not in session.screen.text(), ("the restart review does not fit 80x24", session.screen.text())
                save(session, "restart-review-80x24")
                mutation_key(b"y", "Runtime: Succeeded", 90)
                save(session, "restart-run")
                associated, _, _ = client[0]("/v1/requests/" + restart_child["id"], "Request")
                restarted = associated["runId"]
                assert restarted is not None and restarted != earlier, ("the restart child run", restarted)
                run_view = settled(restarted)
                assert run_view["parentRunId"] == earlier and run_view["lineage"] == "restart", (
                    "the restarted run lineage", run_view["parentRunId"], run_view["lineage"])
                snapshot, _, raw = client[0]("/v1/runs/" + restarted + "/snapshot", "RunSnapshot")
                (work / "tui-history-restarted-snapshot.json").write_bytes(raw)
                assert snapshot["runtime"]["status"] == "succeeded", ("the restarted run status", snapshot["runtime"]["status"])
                print("PASS tui-history 8: l and r on the detail of run", earlier, "created the child request", restart_child["id"],
                      "whose request screen and review named the parent and the operation restart; the complete review fit 80x24, y",
                      "approved it there, and its run", restarted,
                      "succeeded with parentRunId", earlier, "and lineage restart", flush=True)

                # 9. l, f and one replacement fork the restarted run, and the child review shows the edit.
                # The retrieval of the verified result records its verification,
                # which changes the revision of the run and so the entity tag of
                # its lineage collection. The menu opens after it.
                session.wait_screen("Result: verified", timeout=30)
                session.send(b"l")
                shown("Lineage of run " + restarted, 15)
                shown("f fork: eligible", 10)
                session.send(b"f")
                shown("Fork of run " + restarted, 10)
                shown("> occurrence 0 (text): keep", 10)
                session.send(b"\r")
                shown("Replacement answer for occurrence 0 (text)", 10)
                replacement = "Forked answer."
                session.send(replacement.encode())
                session.send(b"\x04")
                shown("> occurrence 0 (text): replace with " + json.dumps(replacement), 10)
                save(session, "fork-edits")
                mutation_key(b"\x04", "Lineage: fork of run " + restarted + "; the inputs come from the parent run", 30)
                session.wait_screen("Enter REQUEST REVIEW", timeout=30)
                fork_child = child_request(restarted, "fork")
                mutation_key(b"\r", "Approve exact manager review", 45)
                shown("Lineage: fork of run " + restarted, 10)
                preparation = child_review(fork_child)
                lineage = preparation["review"]["lineage"]
                assert lineage["parentRunId"] == restarted and lineage["operation"] == "fork" and [
                    (edit["operation"], edit["occurrenceId"]) for edit in lineage["edits"]] == [("replace", "0")], ("the fork review lineage", lineage)
                shown("Lineage edits: replace occurrence 0 (answer SHA-256 " + lineage["edits"][0]["sha256"] + ")", 10)
                # The complete fork review fits 80x24, so the key bar offers y.
                shown("y APPROVE EXACT REVIEW AND RUN", 10)
                for name in ("reviewDigest", "requestRevision", "profileRevision", "descriptorRevision", "processGeneration"):
                    shown(name + preparation[name], 10)
                assert "RESIZE TO REVIEW" not in session.screen.text(), ("the fork review does not fit 80x24", session.screen.text())
                save(session, "fork-review")
                print("PASS tui-history 9: l, f, Enter and Ctrl-D on the live monitor of run", restarted, "forked it with one replacement of",
                      "occurrence 0 as child request", fork_child["id"], "; the TUI review showed the replacement with SHA-256",
                      lineage["edits"][0]["sha256"], "as the child preparation states it, and the complete review fit 80x24 with y offered",
                      flush=True)
                session.send(b"q")
                assert session.wait_exit(20) == 0
                session.assert_restored()
            print("PASS tui-history: the History view of the actual service TUI listed every run across windows, saved a verified result,",
                  "exported it once, restarted it to a succeeded child run and forked that run with one replacement in", lifecycle_elapsed(), flush=True)
        finally:
            if process.poll() is None:
                process.terminate()
            process.wait(timeout=25)
            (work / "server-0.exit").write_text(str(process.returncode) + "\n")


def capture_checks():
    """POST /v1/captures through the real HTTPS manager. Each numbered case
    prints one PASS line."""
    authorized = {"Authorization": "Bearer " + bearer}
    observer = {"Authorization": "Bearer " + (work / "credential-observe").read_bytes().decode("ascii")}
    # Raw UTF-8 with a BOM, CRLF, a trailing LF and multibyte code points,
    # longer than one 65536-byte upload chunk.
    line = "\ufeffCapture λ — café 雪\r\n".encode()
    content = line * (200000 // len(line)) + b"last line\n"

    def upload(credential, request_id, key, body):
        """One capture POST. Returns the status, the decoded body, the raw body and the headers."""
        connection = http.client.HTTPSConnection("127.0.0.1", port, context=context, timeout=15)
        try:
            connection.request("POST", "/v1/captures?requestId=" + request_id, body=body,
                               headers=credential | {"Content-Type": "application/octet-stream", "Idempotency-Key": key})
            response = connection.getresponse()
            raw = response.read(1048577)
            assert len(raw) <= 1048576
            assert response.getheader("Cache-Control") == "no-store"
            assert response.getheader("X-Content-Type-Options") == "nosniff"
            value = frozen.parse_json(raw)
            if response.status >= 400:
                validate("Problem", value, raw)
            return response.status, value, raw, dict((name.lower(), text) for name, text in response.getheaders())
        finally:
            connection.close()

    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        try:
            wait_ready(process)
            status, capabilities, _ = request("/v1/capabilities", authorized)
            assert status == 200
            validate("Capabilities", capabilities)
            assert capabilities["limits"]["captureBytes"] == 67108864
            status, catalogue, _ = request("/v1/workflows?profileId=profile_1", authorized)
            assert status == 200
            workflow = next(item for item in catalogue["items"] if item["name"] == "captured-input")
            assert [item["name"] for item in workflow["inputs"]] == ["input"]
            create = {"workflowId": workflow["id"], "descriptorRevision": workflow["revision"],
                      "profileId": workflow["profileId"], "profileRevision": workflow["profileRevision"]}
            key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
            status, created, raw = request("/v1/requests", authorized | {"Content-Type": "application/json", "Idempotency-Key": key},
                                           method="POST", payload=json.dumps(create, separators=(",", ":")).encode())
            assert status == 201, ("request creation", status, created.get("code"))
            validate("Request", created, raw)

            # Case 1. The capture receipt names the exact uploaded bytes.
            capture_key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
            status, receipt, raw, headers = upload(authorized, created["id"], capture_key, content)
            assert status == 202, ("capture upload", status, receipt.get("code"))
            validate("CaptureReceipt", receipt, raw)
            (work / "capture-receipt.json").write_bytes(raw)
            assert receipt["requestId"] == created["id"] and receipt["profileId"] == "profile_1"
            assert receipt["bytes"] == str(len(content)) and receipt["sha256"] == hashlib.sha256(content).hexdigest(), (
                "capture receipt differs from the uploaded bytes", receipt["bytes"], receipt["sha256"])
            location = headers.get("location", "")
            assert location.startswith("/v1/commands/"), ("capture Location", location)
            status, command, raw = request(location, authorized)
            assert status == 200, ("capture command", status, command.get("code"))
            validate("CommandReceipt", command, raw)
            assert command["operation"] == "capture" and command["links"]["self"] == location, (command["operation"], command["links"])
            print("PASS captures case 1: POST /v1/captures returned 202 with a CaptureReceipt of", receipt["bytes"],
                  "bytes and SHA-256", receipt["sha256"], "equal to the uploaded bytes, and Location names its capture command", flush=True)

            # Case 2. A same-key replay returns the same receipt and command.
            status, replay, raw, replay_headers = upload(authorized, created["id"], capture_key, content)
            assert status == 202, ("capture replay", status, replay.get("code"))
            validate("CaptureReceipt", replay, raw)
            assert replay == receipt and replay_headers.get("location") == location, ("capture replay differs", replay, replay_headers.get("location"))
            print("PASS captures case 2: a same-key capture replay returned the same receipt", receipt["id"], "and the same command", flush=True)

            # Case 3. A credential without the submit scope is refused.
            other_key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
            status, problem, _, _ = upload(observer, created["id"], other_key, b"observe only\n")
            assert status == 403 and problem["code"] == "insufficient-scope", ("observe-only capture", status, problem.get("code"))
            print("PASS captures case 3: a credential with observe only received 403 insufficient-scope", flush=True)

            # Case 4. The capture is the request input through the exact review.
            observed, wait_for, mutate, _ = mixed_client(capabilities, authorized)
            request_uri = created["links"]["self"]
            current, tag, _ = observed(request_uri, "Request")
            mutate(request_uri, {"operation": "set-input", "input": {"name": "input", "source": "capture", "captureId": receipt["id"]}}, tag)
            current, tag, raw = observed(request_uri, "Request")
            (work / "capture-request.json").write_bytes(raw)
            assert not current["readiness"]["missing"] and not current["readiness"]["errors"], current["readiness"]
            assert current["readiness"]["supplied"] == [{"name": "input", "source": "capture", "captureId": receipt["id"]}], current["readiness"]["supplied"]
            mutate(request_uri, {"operation": "enqueue"}, tag)
            current, _, _ = wait_for(request_uri, "Request", lambda value: value["preparationId"] is not None)
            preparation, tag, raw = observed("/v1/preparations/" + current["preparationId"], "Preparation")
            (work / "capture-review.json").write_bytes(raw)
            assert preparation["state"] == "live"
            assert preparation["review"]["inputs"] == [{"name": "input", "source": "capture", "bytes": receipt["bytes"], "sha256": receipt["sha256"]}], (
                "exact review of the capture", preparation["review"]["inputs"])
            print("PASS captures case 4: set-input bound the capture, and the exact review names the input as capture with the receipt size and digest", flush=True)

            # Case 5. Approval starts the run, and the program receives the capture.
            selectors = ("reviewDigest", "requestRevision", "profileRevision", "descriptorRevision", "processGeneration")
            mutate("/v1/preparations/" + preparation["id"], {"operation": "approve", **{name: preparation[name] for name in selectors}}, tag)
            current, _, _ = wait_for(request_uri, "Request", lambda value: value["runId"] is not None)
            run = current["runId"]
            snapshot, _, raw = wait_for("/v1/runs/" + run + "/snapshot", "RunSnapshot",
                lambda value: value["runtime"] is not None and value["runtime"]["status"] in ("succeeded", "failed", "cancelled"))
            (work / "capture-terminal-snapshot.json").write_bytes(raw)
            assert snapshot["runtime"]["status"] == "succeeded", ("capture run terminal status", snapshot["runtime"]["status"])
            answer_files = sorted(work.glob("manager/runs/runs/*/runtime/answers.json"))
            assert len(answer_files) == 1, ("capture run store answers", answer_files)
            prompts = [entry["question"].get("prompt") for entry in json.loads(answer_files[0].read_bytes())["answers"]]
            assert "fixed-point source: " + hashlib.sha256(content).hexdigest() in prompts, ("the program did not receive the captured bytes", prompts)
            print("PASS captures case 5: approval started run", run, "which succeeded, and its program received the SHA-256 of the captured bytes", flush=True)
        finally:
            if process.poll() is None:
                process.terminate()
            process.wait(timeout=25)
            (work / "server-0.exit").write_text(str(process.returncode) + "\n")
    print("PASS mutations-captures: every capture case held against the running TLS 1.3 manager", flush=True)


def discard_checks():
    """The discard operation of POST /v1/preparations/{id} through the real
    HTTPS manager. Each numbered case prints one PASS line."""
    authorized = {"Authorization": "Bearer " + bearer}
    observer = {"Authorization": "Bearer " + (work / "credential-observe").read_bytes().decode("ascii")}
    discard_body = json.dumps({"operation": "discard"}, separators=(",", ":")).encode()

    def discard(credential, preparation_id, key, tag):
        """One discard POST. Returns the status, the decoded body and the raw body."""
        headers = credential | {"Content-Type": "application/json", "Idempotency-Key": key, "If-Match": tag}
        status, value, raw, _ = exchange("/v1/preparations/" + preparation_id, headers, method="POST", payload=discard_body)
        validate("Problem" if status >= 400 else "CommandReceipt", value, raw)
        return status, value, raw

    def settled(path, schema, ready, failure):
        """Read the resource until ready holds, within a deadline."""
        deadline = time.monotonic() + 40
        while True:
            value, tag, raw = observed(path, schema)
            if ready(value):
                return value, tag, raw
            if time.monotonic() >= deadline:
                (work / "discard-wait-last.json").write_bytes(raw)
                raise AssertionError(failure)
            time.sleep(0.05)

    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        try:
            wait_ready(process)
            status, capabilities, _ = request("/v1/capabilities", authorized)
            assert status == 200
            validate("Capabilities", capabilities)
            new_key = lambda: capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
            observed, wait_for, mutate, _ = mixed_client(capabilities, authorized)
            status, catalogue, _ = request("/v1/workflows?profileId=profile_1", authorized)
            assert status == 200
            workflow = next(item for item in catalogue["items"] if item["name"] == "prompt-source")
            assert [item["name"] for item in workflow["inputs"]] == ["input"]
            create = {"workflowId": workflow["id"], "descriptorRevision": workflow["revision"],
                      "profileId": workflow["profileId"], "profileRevision": workflow["profileRevision"]}
            status, created, raw = request("/v1/requests", authorized | {"Content-Type": "application/json", "Idempotency-Key": new_key()},
                                           method="POST", payload=json.dumps(create, separators=(",", ":")).encode())
            assert status == 201, ("request creation", status, created.get("code"))
            validate("Request", created, raw)
            request_uri = created["links"]["self"]
            current, tag, _ = observed(request_uri, "Request")
            mutate(request_uri, {"operation": "set-input", "input": {"name": "input", "source": "literal", "value": "Discard fixture input."}}, tag)
            current, tag, _ = observed(request_uri, "Request")
            mutate(request_uri, {"operation": "enqueue"}, tag)
            current, _, _ = wait_for(request_uri, "Request", lambda value: value["preparationId"] is not None)
            first, first_tag, raw = observed("/v1/preparations/" + current["preparationId"], "Preparation")
            (work / "discard-review.json").write_bytes(raw)
            assert first["state"] == "live" and first["reason"] is None and current["phase"] == "review", (first["state"], current["phase"])
            first_uri = "/v1/preparations/" + first["id"]

            # Case 1. A stale If-Match refuses and changes nothing.
            status, problem, _ = discard(authorized, first["id"], new_key(), '"' + current["revision"] + '"')
            assert status == 412 and problem["code"] == "stale-revision", ("stale discard", status, problem.get("code"))
            still, still_tag, _ = observed(first_uri, "Preparation")
            assert still["state"] == "live" and still_tag == first_tag, ("stale discard changed the preparation", still["state"])
            print("PASS discard case 1: a discard with a stale If-Match received 412 stale-revision, and the preparation stayed live", flush=True)

            # Case 2. A credential without submit and control is refused.
            status, problem, _ = discard(observer, first["id"], new_key(), first_tag)
            assert status == 403 and problem["code"] == "insufficient-scope", ("observe-only discard", status, problem.get("code"))
            still, still_tag, _ = observed(first_uri, "Preparation")
            assert still["state"] == "live" and still_tag == first_tag, ("observe-only discard changed the preparation", still["state"])
            print("PASS discard case 2: a credential with observe only received 403 insufficient-scope, and the preparation stayed live", flush=True)

            # Case 3. The discard ends the review as discarded and returns the request to draft.
            discard_key = new_key()
            status, receipt, raw = discard(authorized, first["id"], discard_key, first_tag)
            assert status == 202, ("discard", status, receipt.get("code"))
            (work / "discard-receipt.json").write_bytes(raw)
            assert receipt["operation"] == "discard" and receipt["resource"] == first_uri, (receipt["operation"], receipt["resource"])
            command_uri = receipt["links"]["self"]
            command, _, raw = settled(command_uri, "CommandReceipt",
                lambda value: value["state"] in ("effect-observed", "refused", "unresolved"), "discard command deadline")
            (work / "discard-command.json").write_bytes(raw)
            assert command["state"] == "effect-observed", ("discard command", command["state"], command.get("refusal"))
            assert command["effect"]["kind"] == "discarded" and command["effect"]["resource"] == request_uri, command["effect"]
            ended, _, raw = observed(first_uri, "Preparation")
            (work / "discard-preparation.json").write_bytes(raw)
            assert ended["state"] == "invalidated" and ended["reason"] == "discarded", (ended["state"], ended["reason"])
            current, tag, raw = settled(request_uri, "Request", lambda value: value["phase"] == "draft", "request did not return to draft")
            (work / "discard-request.json").write_bytes(raw)
            assert current["admission"]["state"] == "released" and current["preparationId"] is None and current["runId"] is None, (
                current["admission"], current["preparationId"], current["runId"])
            print("PASS discard case 3: discard command", receipt["id"], "reached effect-observed with the effect discarded,",
                  "preparation", first["id"], "shows invalidated with the reason discarded, and the request returned to draft",
                  "with admission released and a null preparationId", flush=True)

            # Case 4. A same-key replay returns the same receipt.
            status, replay, _ = discard(authorized, first["id"], discard_key, first_tag)
            assert status == 202 and replay["id"] == receipt["id"] and replay["links"]["self"] == command_uri, (
                "discard replay", status, replay.get("id"), replay.get("code"))
            print("PASS discard case 4: a same-key discard replay returned the same receipt", receipt["id"], flush=True)

            # Case 5. A later enqueue of the draft publishes a fresh review.
            mutate(request_uri, {"operation": "enqueue"}, tag)
            current, _, _ = wait_for(request_uri, "Request",
                lambda value: value["phase"] == "review" and value["preparationId"] not in (None, first["id"]))
            second, second_tag, _ = observed("/v1/preparations/" + current["preparationId"], "Preparation")
            assert second["state"] == "live" and second["id"] != first["id"], (second["state"], second["id"])
            print("PASS discard case 5: a later enqueue of the draft published the fresh review", second["id"], flush=True)

            # Case 6. A discard after approval refuses with state-conflict.
            selectors = ("reviewDigest", "requestRevision", "profileRevision", "descriptorRevision", "processGeneration")
            mutate("/v1/preparations/" + second["id"], {"operation": "approve", **{name: second[name] for name in selectors}}, second_tag)
            current, _, _ = wait_for(request_uri, "Request", lambda value: value["runId"] is not None)
            consumed, consumed_tag, _ = observed("/v1/preparations/" + second["id"], "Preparation")
            assert consumed["state"] == "consumed", consumed["state"]
            status, problem, _ = discard(authorized, second["id"], new_key(), consumed_tag)
            assert status == 409 and problem["code"] == "state-conflict", ("discard after approval", status, problem.get("code"))
            _, ended_tag, _ = observed(first_uri, "Preparation")
            status, problem, _ = discard(authorized, first["id"], new_key(), ended_tag)
            assert status == 409 and problem["code"] == "state-conflict", ("discard of a discarded preparation", status, problem.get("code"))
            snapshot, _, _ = wait_for("/v1/runs/" + current["runId"] + "/snapshot", "RunSnapshot",
                lambda value: value["runtime"] is not None and value["runtime"]["status"] in ("succeeded", "failed", "cancelled"))
            assert snapshot["runtime"]["status"] == "succeeded", snapshot["runtime"]["status"]
            print("PASS discard case 6: a discard after approval and a new-key discard of the discarded preparation received",
                  "409 state-conflict, and run", current["runId"], "succeeded", flush=True)
        finally:
            if process.poll() is None:
                process.terminate()
            process.wait(timeout=25)
            (work / "server-0.exit").write_text(str(process.returncode) + "\n")

    # Case 7. The manager log records the discard command, its receipt, the
    # discard relay and the review and request endings.
    flow_dir = work / "manager" / "flow"
    stores = sorted(work.glob("manager/runs/runs/*/runtime"))
    completed = subprocess.run([str(runner), "flow", str(flow_dir)] + [str(store) for store in stores],
                               stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=60)
    (work / "discard-flow.ndjson").write_bytes(completed.stdout)
    (work / "discard-flow.stderr").write_bytes(completed.stderr)
    lines = [json.loads(line) for line in completed.stdout.splitlines()]
    assert lines and "summary" in lines[-1], ("flow verb", completed.returncode, completed.stderr[-2000:])
    summary = lines[-1]["summary"]
    assert completed.returncode == 0 and summary["verified"] and not summary["problems"], ("flow verb", completed.returncode, summary["problems"])
    logs = sorted(flow_dir.glob("*.ndjson"))
    assert len(logs) == 1, logs
    manager = [line for line in lines[:-1] if line["log"] == str(logs[0])]
    commands = [line for line in manager if line["schema"] == "command" and line["about"].get("command") == receipt["id"]]
    assert len(commands) == 1 and commands[0]["body"]["operation"] == "discard" and commands[0]["body"]["resource"] == first_uri, (
        "discard command record", [line["body"] for line in commands])
    logged = commands[0]
    replies = [line for line in manager if line["schema"] == "receipt" and line["replyTo"] == logged["position"]]
    assert len(replies) == 1 and replies[0]["body"]["id"] == receipt["id"] and replies[0]["body"]["operation"] == "discard", "discard receipt record"
    relays = [line for line in manager if line["schema"] == "relay" and line["body"]["kind"] == "discard"
              and line["about"].get("command") == receipt["id"]]
    assert len(relays) == 1 and relays[0]["body"]["command"] == receipt["id"] and relays[0]["body"]["managerRun"] is None, (
        "discard relay record", [line["body"] for line in relays])
    notices = [line for line in manager if line["schema"] == "notice" and isinstance(line.get("body"), dict)]
    review_endings = [line for line in notices if line["body"].get("notice") == "review-ended" and line["body"]["preparation"] == first["id"]]
    assert len(review_endings) == 1 and review_endings[0]["body"]["reason"] == "discarded", ("review ending", [line["body"] for line in review_endings])
    request_endings = [line for line in notices if line["body"].get("notice") == "request-ended" and line["body"]["request"] == created["id"]]
    assert len(request_endings) == 1 and request_endings[0]["body"]["cause"] == "discarded" and request_endings[0]["about"].get("command") == receipt["id"], (
        "request ending", [(line["body"], line["about"]) for line in request_endings])
    assert logged["position"] < replies[0]["position"] < relays[0]["position"] < request_endings[0]["position"], (
        "manager-log order", logged["position"], replies[0]["position"], relays[0]["position"], request_endings[0]["position"])
    reviews = [item for item in summary["joins"]["reviews"] if item["preparation"] == first["id"]]
    assert len(reviews) == 1 and reviews[0]["commands"] == [logged["position"]] and reviews[0]["endings"] == [review_endings[0]["position"]], (
        "review join", reviews)
    print("PASS discard case 7: the manager log holds discard command", receipt["id"], "at position", logged["position"],
          "its receipt at", replies[0]["position"], "the discard relay that names it at", relays[0]["position"],
          "the review ending discarded at", review_endings[0]["position"], "and the request ending discarded at",
          request_endings[0]["position"], "and the flow verb joins the review to the command and the ending", flush=True)
    print("PASS mutations-discard: every discard case held against the running TLS 1.3 manager", flush=True)


if discard_mode:
    discard_checks()
    raise SystemExit(0)


def export_checks():
    """POST /v1/runs/{id}/exports through the real HTTPS manager. Each
    numbered case prints one PASS line."""
    authorized = {"Authorization": "Bearer " + bearer}
    name = "c14-export.json"
    body = json.dumps({"name": name}, separators=(",", ":")).encode()

    def export(run, key, tag, payload=body):
        """One export POST. Returns the status, the decoded body, the raw body and the headers."""
        headers = authorized | {"Content-Type": "application/json", "Idempotency-Key": key, "If-Match": tag}
        status, value, raw, received = exchange("/v1/runs/" + run + "/exports", headers, method="POST", payload=payload)
        validate("Problem" if status >= 400 else "CommandReceipt", value, raw)
        return status, value, raw, received

    def collection(run):
        """The first page of the export collection of the run and its ETag."""
        status, value, raw, received = fetch("/v1/runs/" + run + "/exports", authorized)
        assert status == 200, ("export collection", status, value.get("code"))
        validate("ExportPage", value, raw)
        assert value["runId"] == run and value["page"]["next"] is None, ("export collection page", value["page"])
        tag = received.get("etag")
        assert tag == '"' + value["page"]["revision"] + '"', ("export collection ETag", tag, value["page"]["revision"])
        return value, tag, raw

    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        try:
            wait_ready(process)
            status, capabilities, _ = request("/v1/capabilities", authorized)
            assert status == 200
            validate("Capabilities", capabilities)
            assert "export" in capabilities["scopes"], capabilities["scopes"]
            new_key = lambda: capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
            observed, wait_for, mutate, _ = mixed_client(capabilities, authorized)
            status, catalogue, _ = request("/v1/workflows?profileId=profile_1", authorized)
            assert status == 200
            workflow = next(item for item in catalogue["items"] if item["name"] == "prompt-source")
            create = {"workflowId": workflow["id"], "descriptorRevision": workflow["revision"],
                      "profileId": workflow["profileId"], "profileRevision": workflow["profileRevision"]}
            status, created, raw = request("/v1/requests", authorized | {"Content-Type": "application/json", "Idempotency-Key": new_key()},
                                           method="POST", payload=json.dumps(create, separators=(",", ":")).encode())
            assert status == 201, ("request creation", status, created.get("code"))
            validate("Request", created, raw)
            request_uri = created["links"]["self"]
            current, tag, _ = observed(request_uri, "Request")
            mutate(request_uri, {"operation": "set-input", "input": {"name": "input", "source": "literal", "value": "Export fixture input."}}, tag)
            current, tag, _ = observed(request_uri, "Request")
            mutate(request_uri, {"operation": "enqueue"}, tag)
            current, _, _ = wait_for(request_uri, "Request", lambda value: value["preparationId"] is not None)
            preparation, tag, _ = observed("/v1/preparations/" + current["preparationId"], "Preparation")
            selectors = ("reviewDigest", "requestRevision", "profileRevision", "descriptorRevision", "processGeneration")
            mutate("/v1/preparations/" + preparation["id"], {"operation": "approve", **{item: preparation[item] for item in selectors}}, tag)
            current, _, _ = wait_for(request_uri, "Request", lambda value: value["runId"] is not None)
            run = current["runId"]
            snapshot, _, _ = wait_for("/v1/runs/" + run + "/snapshot", "RunSnapshot",
                lambda value: value["runtime"] is not None and value["runtime"]["status"] in ("succeeded", "failed", "cancelled"))
            assert snapshot["runtime"]["status"] == "succeeded", snapshot["runtime"]["status"]
            # The release of the worker after the terminal status changes the
            # supervision of the run and with it the collection revision, so
            # the export waits until the supervision settles.
            wait_for("/v1/runs/" + run, "Run", lambda value: value["supervision"] not in ("owned", "cleanup-pending"))
            before, before_tag, raw = collection(run)
            (work / "exports-before.json").write_bytes(raw)
            assert before["items"] == [] and before["page"]["totalItems"] == 0, before["items"]

            # Case 1. The export is accepted, published and downloadable.
            export_key = new_key()
            status, receipt, raw, headers = export(run, export_key, before_tag)
            assert status == 202, ("export", status, receipt.get("code"))
            (work / "export-receipt.json").write_bytes(raw)
            collection_uri = "/v1/runs/" + run + "/exports"
            assert receipt["operation"] == "export" and receipt["resource"] == collection_uri, (receipt["operation"], receipt["resource"])
            assert headers.get("location") == "/v1/commands/" + receipt["id"], ("export Location", headers.get("location"))
            command, _, raw = wait_for(receipt["links"]["self"], "CommandReceipt",
                lambda value: value["state"] in ("effect-observed", "refused", "unresolved"))
            (work / "export-command.json").write_bytes(raw)
            export_uri = "/v1/exports/export_" + receipt["id"]
            assert command["state"] == "effect-observed", ("export command", command["state"], command.get("refusal"))
            assert command["effect"]["kind"] == "exported" and command["effect"]["resource"] == export_uri, command["effect"]
            detail, _, raw = observed(export_uri, "ExportReceipt")
            (work / "export-detail.json").write_bytes(raw)
            assert detail["state"] == "published" and detail["name"] == name and detail["runId"] == run, (detail["state"], detail["name"])
            assert detail["commandId"] == receipt["id"] and detail["download"] is not None, (detail["commandId"], detail["download"])
            after, after_tag, raw = collection(run)
            (work / "exports-after.json").write_bytes(raw)
            assert after["items"] == [detail] and after_tag != before_tag, ("export collection after the export", after["items"])
            connection = http.client.HTTPSConnection("127.0.0.1", port, context=context, timeout=15)
            try:
                connection.request("GET", detail["download"], headers=authorized | {"Accept": "application/octet-stream"})
                response = connection.getresponse()
                downloaded = response.read(int(detail["bytes"]) + 1)
                assert response.status == 200 and response.getheader("Content-Type") == "application/octet-stream", (
                    "export download", response.status)
            finally:
                connection.close()
            (work / "export-download.bin").write_bytes(downloaded)
            published = work / "manager" / "runs" / "exports" / name
            assert len(downloaded) == int(detail["bytes"]) and hashlib.sha256(downloaded).hexdigest() == detail["sha256"], (
                "export download differs from its receipt", len(downloaded), detail["bytes"])
            assert published.read_bytes() == downloaded, "export download differs from the published file"
            print("PASS exports case 1: export command", receipt["id"], "of run", run, "reached effect-observed with the effect exported,",
                  "the collection and", export_uri, "show it published, and", detail["download"], "returned", detail["bytes"],
                  "bytes with SHA-256", detail["sha256"], "equal to the receipt and to the published file", flush=True)

            # Case 2. A same-key replay returns the same receipt.
            status, replay, _, replay_headers = export(run, export_key, before_tag)
            assert status == 202 and replay["id"] == receipt["id"] and replay_headers.get("location") == headers.get("location"), (
                "export replay", status, replay.get("id"), replay.get("code"))
            again, again_tag, raw = collection(run)
            (work / "exports-replay.json").write_bytes(raw)
            assert again["items"] == [detail] and again_tag == after_tag, ("the replay changed the export collection", again_tag, after_tag)
            print("PASS exports case 2: a same-key export replay returned the same receipt", receipt["id"],
                  "and Location, and the collection kept one export", flush=True)

            # Case 3. The stale collection ETag refuses.
            other = json.dumps({"name": "c14-stale.json"}, separators=(",", ":")).encode()
            status, problem, _, _ = export(run, new_key(), before_tag, other)
            assert status == 412 and problem["code"] == "stale-revision", ("stale export", status, problem.get("code"))
            again, again_tag, _ = collection(run)
            assert again["items"] == [detail] and again_tag == after_tag, "the stale export changed the export collection"
            assert not (work / "manager" / "runs" / "exports" / "c14-stale.json").exists(), "the stale export published a file"
            print("PASS exports case 3: an export with the collection ETag from before the first export received",
                  "412 stale-revision, and the collection kept one export", flush=True)
        finally:
            if process.poll() is None:
                process.terminate()
            process.wait(timeout=25)
            (work / "server-0.exit").write_text(str(process.returncode) + "\n")
    print("PASS mutations-exports: every export case held against the running TLS 1.3 manager", flush=True)


def lineage_checks():
    """POST /v1/runs/{id}/lineage-requests through the real HTTPS manager.
    Each numbered case prints one PASS line."""
    authorized = {"Authorization": "Bearer " + bearer}
    # The typed answers of the three person questions of lineage-typed, by
    # occurrence. Occurrence 0 is the scripted model question.
    answers = {"1": False, "2": None, "3": {"ok": False, "notes": []}}

    def lineage(run, key, tag, body):
        """One lineage POST. Returns the status, the decoded body, the raw body and the headers."""
        payload = json.dumps(body, separators=(",", ":")).encode()
        headers = authorized | {"Content-Type": "application/json", "Idempotency-Key": key, "If-Match": tag}
        status, value, raw, received = exchange("/v1/runs/" + run + "/lineage-requests", headers, method="POST", payload=payload)
        validate("Problem" if status >= 400 else "CommandReceipt", value, raw)
        return status, value, raw, received

    def collection(run):
        """The first page of the lineage collection of the run and its ETag."""
        status, value, raw, received = fetch("/v1/runs/" + run + "/lineage-requests", authorized)
        assert status == 200, ("lineage collection", status, value.get("code"))
        validate("LineagePage", value, raw)
        assert value["runId"] == run and value["page"]["next"] is None, ("lineage collection page", value["page"])
        tag = received.get("etag")
        assert tag == '"' + value["page"]["revision"] + '"', ("lineage collection ETag", tag, value["page"]["revision"])
        return value, tag, raw

    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        try:
            wait_ready(process)
            status, capabilities, _ = request("/v1/capabilities", authorized)
            assert status == 200
            validate("Capabilities", capabilities)
            new_key = lambda: capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
            observed, wait_for, mutate, _ = mixed_client(capabilities, authorized)
            selectors = ("reviewDigest", "requestRevision", "profileRevision", "descriptorRevision", "processGeneration")

            def review(request_uri, name):
                """Enqueue the draft and return its live preparation and ETag."""
                current, tag, _ = observed(request_uri, "Request")
                mutate(request_uri, {"operation": "enqueue"}, tag)
                current, _, _ = wait_for(request_uri, "Request", lambda value: value["preparationId"] is not None)
                preparation, tag, raw = observed("/v1/preparations/" + current["preparationId"], "Preparation")
                (work / (name + "-review.json")).write_bytes(raw)
                assert preparation["state"] == "live", (name, preparation["state"])
                return preparation, tag

            def run_to_success(request_uri, preparation, tag, name):
                """Approve the preparation, answer every question of the run and
                return the run after its terminal success and settled supervision."""
                mutate("/v1/preparations/" + preparation["id"], {"operation": "approve", **{item: preparation[item] for item in selectors}}, tag)
                current, _, _ = wait_for(request_uri, "Request", lambda value: value["runId"] is not None)
                run = current["runId"]
                base = "/v1/runs/" + run
                deadline = time.monotonic() + 60
                while True:
                    snapshot, _, raw = observed(base + "/snapshot", "RunSnapshot")
                    runtime = snapshot["runtime"]
                    if runtime is not None and runtime["status"] in ("succeeded", "failed", "cancelled"):
                        (work / (name + "-terminal.json")).write_bytes(raw)
                        assert runtime["status"] == "succeeded", (name, runtime["status"])
                        break
                    assert time.monotonic() < deadline, (name, "terminal deadline")
                    control, _, _ = observed(base + "/control", "RunControl")
                    head = control["decisionHeadId"]
                    if head is None:
                        time.sleep(0.05)
                        continue
                    decision, decision_tag, _ = observed("/v1/decisions/" + head, "Decision")
                    occurrence = decision["address"]["occurrenceId"]
                    assert decision["kind"] == "question" and occurrence in answers, (name, decision["kind"], occurrence)
                    mutate("/v1/decisions/" + head, {"operation": "answer", "occurrenceId": occurrence,
                                                      "generation": decision["generation"], "value": answers[occurrence]}, decision_tag)
                wait_for(request_uri, "Request", lambda value: value["admission"]["state"] == "released")
                value, _, _ = wait_for(base, "Run", lambda value: value["supervision"] not in ("owned", "cleanup-pending"))
                return value

            def create_child(run, tag, body, name):
                """One accepted lineage request. Returns the key, receipt, headers and child request."""
                key = new_key()
                status, receipt, raw, headers = lineage(run, key, tag, body)
                assert status == 202, (name, status, receipt.get("code"))
                (work / (name + "-receipt.json")).write_bytes(raw)
                assert receipt["operation"] == body["operation"] and receipt["resource"] == "/v1/runs/" + run + "/lineage-requests", (
                    name, receipt["operation"], receipt["resource"])
                assert headers.get("location") == "/v1/commands/" + receipt["id"], (name, headers.get("location"))
                command, _, raw = wait_for(receipt["links"]["self"], "CommandReceipt",
                    lambda value: value["state"] in ("effect-observed", "refused", "unresolved"))
                (work / (name + "-command.json")).write_bytes(raw)
                assert command["state"] == "effect-observed" and command["effect"]["kind"] == "lineage-created", (
                    name, command["state"], command.get("effect"), command.get("refusal"))
                child, _, raw = observed(command["effect"]["resource"], "Request")
                (work / (name + "-child.json")).write_bytes(raw)
                assert child["parentRunId"] == run and child["lineage"] == body["operation"] and child["phase"] == "draft", (
                    name, child["parentRunId"], child["lineage"], child["phase"])
                return key, receipt, headers, child

            status, catalogue, _ = request("/v1/workflows?profileId=profile_1", authorized)
            assert status == 200
            workflow = next(item for item in catalogue["items"] if item["name"] == "lineage-typed")
            create = {"workflowId": workflow["id"], "descriptorRevision": workflow["revision"],
                      "profileId": workflow["profileId"], "profileRevision": workflow["profileRevision"]}
            status, created, raw = request("/v1/requests", authorized | {"Content-Type": "application/json", "Idempotency-Key": new_key()},
                                           method="POST", payload=json.dumps(create, separators=(",", ":")).encode())
            assert status == 201, ("request creation", status, created.get("code"))
            validate("Request", created, raw)
            request_uri = created["links"]["self"]
            current, tag, _ = observed(request_uri, "Request")
            mutate(request_uri, {"operation": "set-input", "input": {"name": "input", "source": "literal", "value": "Lineage fixture input."}}, tag)
            preparation, tag = review(request_uri, "parent")
            assert "lineage" not in preparation["review"], "a root review has a lineage"
            parent = run_to_success(request_uri, preparation, tag, "parent")
            run = parent["id"]
            before, before_tag, raw = collection(run)
            (work / "lineage-before.json").write_bytes(raw)
            assert before["items"] == [] and before["eligible"] == ["restart", "resume", "fork"] and before["refusal"] is None, (
                "lineage collection before the first request", before["items"], before["eligible"], before["refusal"])

            # Case 1. A restart creates a child request that names the parent,
            # and the approved child runs to success.
            restart_key, receipt, headers, child = create_child(run, before_tag, {"operation": "restart"}, "restart")
            after, after_tag, raw = collection(run)
            (work / "lineage-after.json").write_bytes(raw)
            assert [item["id"] for item in after["items"]] == [child["id"]] and after_tag != before_tag, (
                "lineage collection after the restart", [item["id"] for item in after["items"]])
            requests, _, raw = observed("/v1/requests", "RequestPage")
            (work / "requests-after.json").write_bytes(raw)
            listed = [item for item in requests["items"] if item["id"] == child["id"]]
            assert len(listed) == 1 and listed[0]["parentRunId"] == run and listed[0]["lineage"] == "restart", ("/v1/requests child", listed)
            child_uri = child["links"]["self"]
            preparation, tag = review(child_uri, "restart")
            assert preparation["review"].get("lineage") == {"parentRunId": run, "operation": "restart", "edits": []}, (
                "restart review lineage", preparation["review"].get("lineage"))
            restarted = run_to_success(child_uri, preparation, tag, "restart")
            assert restarted["parentRunId"] == run and restarted["lineage"] == "restart" and restarted["id"] != run, (
                "restarted run", restarted["parentRunId"], restarted["lineage"])
            print("PASS lineage case 1: restart command", receipt["id"], "of run", run, "created request", child["id"],
                  "that names the parent in its detail, /v1/requests, the lineage collection and its review lineage, and its approved run",
                  restarted["id"], "answered three questions and succeeded", flush=True)

            # Case 2. A same-key replay returns the same receipt.
            status, replay, _, replay_headers = lineage(run, restart_key, before_tag, {"operation": "restart"})
            assert status == 202 and replay["id"] == receipt["id"] and replay_headers.get("location") == headers.get("location"), (
                "lineage replay", status, replay.get("id"), replay.get("code"))
            again, again_tag, raw = collection(run)
            (work / "lineage-replay.json").write_bytes(raw)
            assert [item["id"] for item in again["items"]] == [child["id"]], ("the replay changed the lineage collection", again["items"])
            print("PASS lineage case 2: a same-key restart replay returned the same receipt", receipt["id"],
                  "and Location, and the collection kept one child", flush=True)

            # Case 3. The stale collection ETag refuses.
            status, problem, _, _ = lineage(run, new_key(), before_tag, {"operation": "restart"})
            assert status == 412 and problem["code"] == "stale-revision", ("stale lineage request", status, problem.get("code"))
            again, again_tag, _ = collection(run)
            assert [item["id"] for item in again["items"]] == [child["id"]], "the stale lineage request changed the collection"
            print("PASS lineage case 3: a restart with the collection ETag from before the first request received",
                  "412 stale-revision, and the collection kept one child", flush=True)

            # Case 4. A resume creates a child whose review names the parent.
            _, resume_receipt, _, resumed = create_child(run, again_tag, {"operation": "resume"}, "resume")
            preparation, tag = review(resumed["links"]["self"], "resume")
            assert preparation["review"].get("lineage") == {"parentRunId": run, "operation": "resume", "edits": []}, (
                "resume review lineage", preparation["review"].get("lineage"))
            discard = json.dumps({"operation": "discard"}, separators=(",", ":")).encode()
            status, discarded, _, _ = exchange("/v1/preparations/" + preparation["id"],
                authorized | {"Content-Type": "application/json", "Idempotency-Key": new_key(), "If-Match": tag},
                method="POST", payload=discard)
            assert status == 202, ("resume discard", status, discarded.get("code"))
            wait_for(resumed["links"]["self"], "Request", lambda value: value["phase"] == "draft" and value["admission"]["state"] == "released")
            print("PASS lineage case 4: resume command", resume_receipt["id"], "created request", resumed["id"],
                  "whose review names the parent", run, "with the operation resume", flush=True)

            # Case 5. A fork with an answer replacement reaches the child review.
            _, current_tag, _ = collection(run)
            edits = [{"occurrenceId": "1", "operation": "replace", "answer": True}]
            _, fork_receipt, _, forked = create_child(run, current_tag, {"operation": "fork", "edits": edits}, "fork")
            preparation, _ = review(forked["links"]["self"], "fork")
            shown = preparation["review"].get("lineage")
            assert shown is not None and shown["parentRunId"] == run and shown["operation"] == "fork", ("fork review lineage", shown)
            assert [(edit["operation"], edit["occurrenceId"]) for edit in shown["edits"]] == [("replace", "1")] and re.fullmatch(
                "[0-9a-f]{64}", shown["edits"][0]["sha256"]), ("fork review edits", shown["edits"])
            final, _, raw = collection(run)
            (work / "lineage-final.json").write_bytes(raw)
            assert [item["id"] for item in final["items"]] == sorted([child["id"], resumed["id"], forked["id"]]), (
                "final lineage collection", [item["id"] for item in final["items"]])
            print("PASS lineage case 5: fork command", fork_receipt["id"], "with a replacement of occurrence 1 created request",
                  forked["id"], "whose review names the parent", run, "and the replaced occurrence", flush=True)
        finally:
            if process.poll() is None:
                process.terminate()
            process.wait(timeout=25)
            (work / "server-0.exit").write_text(str(process.returncode) + "\n")
    print("PASS mutations-lineage: every lineage case held against the running TLS 1.3 manager", flush=True)


def control_checks():
    """Cancel, steer, retry, abandon and answer through POST
    /v1/runs/{id}/control and POST /v1/decisions/{id} of the real HTTPS
    manager. Each numbered case prints one PASS line."""
    authorized = {"Authorization": "Bearer " + bearer}
    peer = {"Authorization": "Bearer " + (work / "credential-peer").read_bytes().decode("ascii")}
    terminal = ("succeeded", "failed", "cancelled")
    # The live-redirect cases leave here the facts that the joined flow check
    # reads after the manager exits.
    live_facts = {}

    def post(path, credential, capabilities, body, tag):
        """One control POST. Returns the status and the decoded body."""
        key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
        payload = json.dumps(body, separators=(",", ":")).encode()
        headers = credential | {"Content-Type": "application/json", "Idempotency-Key": key, "If-Match": tag}
        status, value, raw, _ = exchange(path, headers, method="POST", payload=payload)
        validate("Problem" if status >= 400 else "CommandReceipt", value, raw)
        return status, value

    def start(client, capabilities, profile, name="mixed-controls"):
        """Create, enqueue and approve one request of the named workflow of
        the profile. Returns the run."""
        credential = client[3]
        status, catalogue, _ = request("/v1/workflows?profileId=" + profile, credential)
        assert status == 200, ("control catalogue", profile, status)
        workflow = next(item for item in catalogue["items"] if item["name"] == name)
        create = {"workflowId": workflow["id"], "descriptorRevision": workflow["revision"],
                  "profileId": workflow["profileId"], "profileRevision": workflow["profileRevision"]}
        key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
        status, created, raw = request("/v1/requests", credential | {"Content-Type": "application/json", "Idempotency-Key": key},
                                       method="POST", payload=json.dumps(create, separators=(",", ":")).encode())
        assert status == 201, ("control request creation", profile, status, created.get("code"))
        validate("Request", created, raw)
        _, run = approve_mixed(created, workflow, client)
        return run

    def run_records(run, credential):
        """Every run-log route record of the run that the credential receives."""
        records, cursor = [], None
        for _ in range(1024):
            target = f"/v1/runs/{run}/routes" + ("" if cursor is None else "?after=" + cursor)
            status, value, raw = request(target, credential | {"Accept": "application/json"})
            assert status == 200, ("run route batch", run, status, value.get("code"))
            validate("RouteBatch", value, raw)
            records += value["records"]
            cursor = value["cursor"]
            if not value["hasMore"]:
                return records
        raise AssertionError(("run route pages did not end", run))

    def ended(client, run, expected):
        """Wait for the terminal runtime status of the run and require the expected one."""
        snapshot, _, raw = client[1](f"/v1/runs/{run}/snapshot", "RunSnapshot",
            lambda value: value["runtime"] is not None and value["runtime"]["status"] in terminal)
        (work / f"control-{run}-terminal.json").write_bytes(raw)
        assert snapshot["runtime"]["status"] == expected, ("control run terminal status", run, snapshot["runtime"]["status"], expected)

    def effect(client, receipt_uri, kind):
        """The effect-observed receipt of a control command with the effect kind."""
        command, _, raw = client[0](receipt_uri, "CommandReceipt")
        assert command["state"] == "effect-observed" and command["effect"]["kind"] == kind, (
            "control effect", receipt_uri, command["state"], command["effect"])
        return command

    def queue(client, run):
        """The identifiers of the pending FIFO queue of the run, in order."""
        page, _, _ = client[0]("/v1/decisions?runId=" + run, "DecisionPage")
        return [item["id"] for item in page["items"]]

    def act(client, capabilities, run, head, choice):
        """Act on the head decision of the run. A question receives typed
        false through the decision. A recovery receives retry through the
        run control, or choose-recovery with the choice through the
        decision. Returns the receipt URI and the expected effect kind."""
        observed, _, mutate, _ = client
        decision, decision_tag, _ = observed("/v1/decisions/" + head, "Decision")
        assert decision["position"] == 0 and decision["state"] == "pending" and decision["runId"] == run, (
            "control head", head, decision["position"], decision["state"])
        body = {"occurrenceId": decision["address"]["occurrenceId"], "generation": decision["generation"]}
        if decision["kind"] == "question":
            return mutate("/v1/decisions/" + head, dict(body, operation="answer", value=False), decision_tag), "answer-accepted"
        control, control_tag, _ = observed(f"/v1/runs/{run}/control", "RunControl")
        assert control["decisionHeadId"] == head, ("control head moved", control["decisionHeadId"], head)
        if choice == "retry":
            assert any(offer["operation"] == "retry" and offer["generation"] == decision["generation"]
                       and offer["address"] == decision["address"] for offer in control["offers"]), ("retry not offered", control["offers"])
            return mutate(f"/v1/runs/{run}/control", dict(body, operation="retry"), control_tag), "retried"
        assert any(offer["operation"] == "choose-recovery" and offer["generation"] == decision["generation"]
                   and any(item["choice"] == choice for item in offer["choices"]) for offer in control["offers"]), (
            "recovery choice not offered", choice, control["offers"])
        return mutate("/v1/decisions/" + head, dict(body, operation="choose-recovery", choice=choice), decision_tag), "recovery-chosen"

    def new_store(before):
        """The one run store that appeared after the stores in before."""
        deadline = time.monotonic() + 20
        while True:
            stores = sorted(set(work.glob("manager/runs/runs/*/runtime")) - before)
            if len(stores) == 1:
                return stores[0]
            assert len(stores) == 0 and time.monotonic() < deadline, ("new run store", stores)
            time.sleep(0.05)

    def store_flow(name, store):
        """The run-log records and the summary that the flow verb of the
        runner reads from the run store of an ended run."""
        completed = subprocess.run([str(runner), "flow", str(store)], stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=60)
        (work / (name + ".ndjson")).write_bytes(completed.stdout)
        (work / (name + ".stderr")).write_bytes(completed.stderr)
        lines = [json.loads(line) for line in completed.stdout.splitlines()]
        assert lines and "summary" in lines[-1], ("flow verb", name, completed.returncode, completed.stderr[-2000:])
        summary = lines[-1]["summary"]
        assert completed.returncode == 0 and summary["verified"] and not summary["problems"] and not summary["live"], (
            "the flow verb did not verify the ended run log", name, completed.returncode, summary["problems"])
        assert not summary["states"]["unacknowledged"], ("the run log has an unacknowledged control", name, summary["states"]["unacknowledged"])
        return lines[:-1], summary

    def acknowledged_control(records, identity):
        """The one run-log control of the command, from the manager, and the
        position of the first later event record that acknowledges it."""
        found = [record for record in records if record["schema"] == "control" and record["about"].get("command") == identity]
        assert len(found) == 1 and found[0]["from"] == "manager", ("run-log control of command", identity, [record["from"] for record in found])
        control = found[0]
        acknowledgements = [record["position"] for record in records if record["schema"] == "event" and record["position"] > control["position"]
                            and record["event"]["line"]["event"]["type"] == "control.ack"
                            and record["event"]["line"]["event"]["controlId"] == identity]
        assert acknowledgements, ("run-log control acknowledgement", identity)
        return control, acknowledgements[0]

    def settle(client, capabilities, run, choice):
        """Act on each head decision of the run until it ends: typed false
        for a question and choose-recovery with the choice for a recovery.
        Returns the recovery commands and the decisions they acted on."""
        recoveries = []
        deadline = time.monotonic() + 90
        while True:
            snapshot, _, _ = client[0](f"/v1/runs/{run}/snapshot", "RunSnapshot")
            if snapshot["runtime"] is not None and snapshot["runtime"]["status"] in terminal:
                return recoveries
            assert time.monotonic() < deadline, ("routing run terminal deadline", run)
            control, _, _ = client[0](f"/v1/runs/{run}/control", "RunControl")
            if control["decisionHeadId"] is None:
                time.sleep(0.05)
                continue
            decision, _, _ = client[0]("/v1/decisions/" + control["decisionHeadId"], "Decision")
            uri, kind = act(client, capabilities, run, control["decisionHeadId"], choice)
            command = effect(client, uri, kind)
            if command["operation"] == "choose-recovery":
                recoveries.append((command, decision))

    def routing_cases(first, first_capabilities):
        """Fail-over and redirect of the two-candidate question of
        profile_route through /v1, with the run-log and event evidence."""
        # Case 1. A choose-recovery fail-over through the decision asks the
        # spare candidate. The run log holds the relayed control and its
        # acknowledgement, a failure for the first question and a new question
        # to the spare candidate.
        before = set(work.glob("manager/runs/runs/*/runtime"))
        run = start(first, first_capabilities, "profile_route")
        store = new_store(before)
        recoveries = settle(first, first_capabilities, run, "failover")
        ended(first, run, "succeeded")
        assert len(recoveries) == 1, ("fail-over recoveries", [command["id"] for command, _ in recoveries])
        failover, decision = recoveries[0]
        assert any(item["choice"] == "failover" for item in decision["choices"]), ("failover not offered", decision["choices"])
        occurrence = decision["address"]["occurrenceId"]
        records, _ = store_flow("routing-failover-flow", store)
        control, acknowledgement = acknowledged_control(records, failover["id"])
        questions = model_questions(records, occurrence)
        assert len(questions) == 2, ("fail-over questions", [(record["position"], record["to"]) for record in questions])
        asked, spare = questions
        failures = [record for record in records if record["schema"] == "failure" and record.get("replyTo") == asked["position"]]
        assert len(failures) == 1 and asked["position"] < control["position"] < failures[0]["position"] < spare["position"], (
            "fail-over order", asked["position"], control["position"], [record["position"] for record in failures], spare["position"])
        first_target, spare_target = asked["to"]["to"]["model"], spare["to"]["to"]["model"]
        assert first_target.endswith("@primary") and spare_target.endswith("@spare"), ("fail-over targets", first_target, spare_target)
        answers = [record for record in records if record["schema"] == "answer" and record.get("replyTo") == spare["position"]]
        assert len(answers) == 1 and answers[0]["from"] == {"model": spare_target}, ("spare answer", [record["from"] for record in answers])
        print("PASS controls-routing case 1: choose-recovery command", failover["id"], "chose failover for occurrence", occurrence,
              "of run", run, "and the run succeeded; the run log holds control", control["position"], "from the manager with",
              "acknowledgement event", acknowledgement, "failure", failures[0]["position"], "for question", asked["position"], "to",
              first_target, "and question", spare["position"], "to", spare_target, "with its answer", flush=True)

        # Case 2. A redirect through the run control inside the dispatch
        # window asks the chosen target. The run log holds the relayed control,
        # its acknowledgement and a question to that target, and events.ndjson
        # holds occurrence.redirected.
        before = set(work.glob("manager/runs/runs/*/runtime"))
        run = start(first, first_capabilities, "profile_route")
        store = new_store(before)
        base = "/v1/runs/" + run
        control, tag, raw = first[1](base + "/control", "RunControl",
            lambda value: any(offer["operation"] == "redirect" for offer in value["offers"]))
        (work / "control-redirect-before.json").write_bytes(raw)
        offer = next(offer for offer in control["offers"] if offer["operation"] == "redirect")
        occurrence = offer["address"]["occurrenceId"]
        assert len(offer["targets"]) == 2 and offer["targets"][0].endswith("@primary"), ("redirect targets", offer["targets"])
        target = offer["targets"][-1]
        uri = first[2](base + "/control", {"operation": "redirect", "occurrenceId": occurrence, "target": target}, tag)
        redirect = effect(first, uri, "redirected")
        assert settle(first, first_capabilities, run, "abandon") == [], "a redirected run offered a recovery"
        ended(first, run, "succeeded")
        records, _ = store_flow("routing-redirect-flow", store)
        control, acknowledgement = acknowledged_control(records, redirect["id"])
        questions = model_questions(records, occurrence)
        assert len(questions) == 1 and questions[0]["to"] == {"to": {"model": target}} and control["position"] < questions[0]["position"], (
            "redirected questions", control["position"], [(record["position"], record["to"]) for record in questions])
        answers = [record for record in records if record["schema"] == "answer" and record.get("replyTo") == questions[0]["position"]]
        assert len(answers) == 1 and answers[0]["from"] == {"model": target}, ("redirected answer", [record["from"] for record in answers])
        events = [json.loads(line) for line in (store / "events.ndjson").read_bytes().splitlines()]
        events = [event.get("event", event) for event in events]
        redirected = [event for event in events if event["type"] == "occurrence.redirected"]
        assert len(redirected) == 1 and redirected[0]["target"] == target and str(redirected[0]["occurrenceId"]) == occurrence, (
            "occurrence.redirected event", redirected)
        print("PASS controls-routing case 2: redirect command", redirect["id"], "sent occurrence", occurrence, "of run", run,
              "to", target, "inside the dispatch window and reached the effect redirected; the run log holds control",
              control["position"], "from the manager with acknowledgement event", acknowledgement, "and question", questions[0]["position"],
              "to", target, "with its answer, events.ndjson holds occurrence.redirected, and the run succeeded", flush=True)

    def close_window(client, run):
        """Close the dispatch window of the two-candidate question of the run
        at once by a redirect to its first target. Returns the occurrence,
        the two targets and the redirect command."""
        base = "/v1/runs/" + run
        control, tag, _ = client[1](base + "/control", "RunControl",
            lambda value: any(offer["operation"] == "redirect" and len(offer["targets"]) == 2 for offer in value["offers"]))
        window = next(offer for offer in control["offers"] if offer["operation"] == "redirect")
        occurrence = window["address"]["occurrenceId"]
        first_target, spare_target = window["targets"]
        assert first_target.endswith("@primary") and spare_target.endswith("@spare"), ("dispatch targets", window["targets"])
        uri = client[2](base + "/control", {"operation": "redirect", "occurrenceId": occurrence, "target": first_target}, tag)
        return occurrence, first_target, spare_target, effect(client, uri, "redirected")

    def live_cases(first, first_capabilities):
        """Live redirect of an in-flight attempt through /v1, and its refusal
        for an effect in flight."""
        # Case 1. While the first candidate of a question that is not an
        # effect holds its turn, the run control offers a redirect to the
        # spare target from the approved policy. The redirect is accepted, and
        # the run completes with the answer of the spare candidate.
        before = set(work.glob("manager/runs/runs/*/runtime"))
        run = start(first, first_capabilities, "profile_live")
        store = new_store(before)
        base = "/v1/runs/" + run
        occurrence, first_target, spare_target, window_command = close_window(first, run)
        control, tag, raw = first[1](base + "/control", "RunControl",
            lambda value: any(offer["operation"] == "redirect" for offer in value["offers"]))
        (work / "live-redirect-offer.json").write_bytes(raw)
        offers = [offer for offer in control["offers"] if offer["operation"] == "redirect"]
        assert len(offers) == 1 and offers[0]["address"] == {"occurrenceId": occurrence} and offers[0]["targets"] == [spare_target], (
            "live redirect offer", offers)
        snapshot, _, _ = first[0](base + "/snapshot", "RunSnapshot")
        running = running_attempts(snapshot, occurrence)
        assert len(running) == 1, ("running attempt", running)
        uri = first[2](base + "/control", {"operation": "redirect", "occurrenceId": occurrence, "target": spare_target}, tag)
        live_command = effect(first, uri, "redirected")
        assert settle(first, first_capabilities, run, "abandon") == [], "a redirected run offered a recovery"
        ended(first, run, "succeeded")
        snapshot, _, _ = first[0](base + "/snapshot", "RunSnapshot")
        completed = occurrence_of(snapshot, occurrence)
        assert completed["state"] == "completed" and completed["source"] == "asked:" + spare_target, (
            "live redirect answer source", completed["state"], completed["source"])
        attempts, redirected = attempt_events(store, occurrence)
        assert [event["type"] for event in attempts] == ["attempt.started", "attempt.failed", "attempt.started", "attempt.completed"], (
            "live redirect attempts", attempts)
        assert live_command["id"] in attempts[1]["message"], ("stopped attempt message", attempts[1])
        assert [(event["controlId"], event["target"]) for event in redirected] == [
            (window_command["id"], first_target), (live_command["id"], spare_target)], ("occurrence.redirected events", redirected)
        live_facts["redirect"] = (run, store, occurrence, first_target, spare_target, live_command["id"], window_command["id"])
        print("PASS live-redirect case 1: while", first_target, "held its turn, the run control of run", run, "offered redirect of",
              "occurrence", occurrence, "to", spare_target, "only; redirect command", live_command["id"], "reached the effect redirected,",
              "the stopped attempt ended attempt.failed naming the command, the run succeeded with the answer of", spare_target,
              "and events.ndjson holds occurrence.redirected for the window command and the live command", flush=True)

        # Case 2. A redirect of an effect in flight refuses at admission with
        # unsupported-operation. The attempt keeps running, the run completes
        # with the answer of the first candidate, and nothing is re-routed.
        before = set(work.glob("manager/runs/runs/*/runtime"))
        run = start(first, first_capabilities, "profile_live_effect", "controlled-effect")
        store = new_store(before)
        base = "/v1/runs/" + run
        occurrence, first_target, spare_target, window_command = close_window(first, run)
        snapshot, _, _ = first[1](base + "/snapshot", "RunSnapshot", lambda value: running_attempts(value, occurrence))
        effect_occurrence = occurrence_of(snapshot, occurrence)
        assert effect_occurrence["intent"] == "effect", ("effect occurrence intent", effect_occurrence["intent"])
        running = running_attempts(snapshot, occurrence)
        control, tag, raw = first[0](base + "/control", "RunControl")
        (work / "live-redirect-effect-control.json").write_bytes(raw)
        assert not any(offer["operation"] == "redirect" for offer in control["offers"]), ("effect redirect offered", control["offers"])
        status, problem = post(base + "/control", authorized, first_capabilities,
                               {"operation": "redirect", "occurrenceId": occurrence, "target": spare_target}, tag)
        assert status == 409 and problem["code"] == "unsupported-operation", ("effect live redirect", status, problem.get("code"))
        snapshot, _, _ = first[0](base + "/snapshot", "RunSnapshot")
        still = running_attempts(snapshot, occurrence)
        assert [attempt["address"] for attempt in still] == [attempt["address"] for attempt in running], (
            "the effect attempt ended before the refusal was checked", running, still)
        assert settle(first, first_capabilities, run, "abandon") == [], "the effect run offered a recovery"
        ended(first, run, "succeeded")
        snapshot, _, _ = first[0](base + "/snapshot", "RunSnapshot")
        assert occurrence_of(snapshot, occurrence)["source"] == "asked:" + first_target, (
            "effect answer source", occurrence_of(snapshot, occurrence)["source"])
        attempts, redirected = attempt_events(store, occurrence)
        assert [event["type"] for event in attempts] == ["attempt.started", "attempt.completed"], ("effect attempts", attempts)
        assert [(event["controlId"], event["target"]) for event in redirected] == [(window_command["id"], first_target)], (
            "effect occurrence.redirected events", redirected)
        records, _ = store_flow("live-redirect-effect-flow", store)
        questions = model_questions(records, occurrence)
        assert [record["to"] for record in questions] == [{"to": {"model": first_target}}], ("effect questions", questions)
        assert not [record for record in records if record["schema"] == "failure"], "the effect run log holds a failure"
        assert [record["about"].get("command") for record in records if record["schema"] == "control"] == [window_command["id"]], (
            "effect run-log controls", [record["about"] for record in records if record["schema"] == "control"])
        print("PASS live-redirect case 2: the run control of run", run, "offered no redirect of effect occurrence", occurrence,
              "in flight, a redirect to", spare_target, "refused with 409 unsupported-operation while attempt", running[0]["address"]["attemptId"],
              "kept running, the run succeeded with the answer of", first_target, "and the run log holds one question and",
              "only the window control", flush=True)

    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        try:
            wait_ready(process)
            clients = {}
            for label, credential in (("first", authorized), ("peer", peer)):
                status, capabilities, _ = request("/v1/capabilities", credential)
                assert status == 200 and "control" in capabilities["scopes"], ("control capabilities", label, status)
                validate("Capabilities", capabilities)
                assert sorted(capabilities["profileIds"]) == sorted(CONTROL_PROFILES), capabilities["profileIds"]
                clients[label] = (mixed_client(capabilities, credential), capabilities)
            first, first_capabilities = clients["first"]
            second, second_capabilities = clients["peer"]
            if routing_mode:
                routing_cases(first, first_capabilities)
                return
            if live_mode:
                live_cases(first, first_capabilities)
                return live_facts

            # Case 1. A cancel of a running run is acknowledged, and the run ends cancelled.
            run = start(first, first_capabilities, "profile_steer")
            base = "/v1/runs/" + run
            control, tag, raw = first[1](base + "/control", "RunControl",
                lambda value: any(offer["operation"] == "steer" for offer in value["offers"]))
            (work / "control-cancel-before.json").write_bytes(raw)
            assert control["cancelAllowed"] and control["supervision"] == "owned", ("cancel not allowed", control["cancelAllowed"])
            status, receipt = post(base + "/control", authorized, first_capabilities, {"operation": "cancel"}, tag)
            assert status == 202 and receipt["operation"] == "cancel" and receipt["resource"] == base + "/control", (
                "cancel", status, receipt.get("code"))
            command, _, raw = first[1](receipt["links"]["self"], "CommandReceipt",
                lambda value: value["acknowledgement"] is not None or value["state"] in ("refused", "unresolved"))
            (work / "control-cancel-command.json").write_bytes(raw)
            assert command["state"] in ("acknowledged", "effect-observed") and command["acknowledgement"]["state"] in ("accepted", "delivered"), (
                "cancel acknowledgement", command["state"], command["acknowledgement"])
            ended(first, run, "cancelled")
            records = run_records(run, authorized)
            controls = [record for record in records if record["schema"] == "control" and record["about"].get("command") == receipt["id"]]
            assert len(controls) == 1 and controls[0]["from"] == "manager", ("cancel run-log control", len(controls))
            print("PASS controls case 1: cancel command", receipt["id"], "of running run", run, "was acknowledged",
                  command["acknowledgement"]["state"], "and the run ended cancelled, with one run-log control from the manager", flush=True)

            # Case 2. A steer of the steerable running attempt reaches the effect steered.
            run = start(first, first_capabilities, "profile_steer")
            base = "/v1/runs/" + run
            control, tag, raw = first[1](base + "/control", "RunControl",
                lambda value: any(offer["operation"] == "steer" for offer in value["offers"]))
            (work / "control-steer-before.json").write_bytes(raw)
            offer = next(offer for offer in control["offers"] if offer["operation"] == "steer")
            assert "interrupt-now" in offer["timings"] and "attemptId" in offer["address"], offer
            steer_uri = first[2](base + "/control", {"operation": "steer", "occurrenceId": offer["address"]["occurrenceId"],
                                 "attemptId": offer["address"]["attemptId"], "timing": "interrupt-now",
                                 "text": "Focus on the patch."}, tag)
            steer = effect(first, steer_uri, "steered")
            assert steer["effect"]["address"] == offer["address"], ("steer effect address", steer["effect"]["address"], offer["address"])
            records = run_records(run, authorized)
            steers = [record for record in records if record["schema"] == "steer"]
            controls = [record for record in records if record["schema"] == "control" and record["about"].get("command") == steer["id"]]
            assert steers and len(controls) == 1 and controls[0]["from"] == "manager", ("steer run-log records", len(steers), len(controls))
            print("PASS controls case 2: steer command", steer["id"], "of attempt", offer["address"], "of run", run,
                  "reached the effect steered, and the run log holds the relayed control and", len(steers), "steer record", flush=True)

            # Case 3. Two credentials answer the same head decision at the same time.
            control, _, _ = first[1](base + "/control", "RunControl", lambda value: value["decisionHeadId"] is not None)
            head = control["decisionHeadId"]
            decision, decision_tag, _ = first[0]("/v1/decisions/" + head, "Decision")
            assert decision["kind"] == "question" and decision["state"] == "pending", ("concurrent head", decision["kind"], decision["state"])
            body = {"operation": "answer", "occurrenceId": decision["address"]["occurrenceId"],
                    "generation": decision["generation"], "value": False}
            barrier = threading.Barrier(2)
            outcomes = {}

            def answer(label, credential, capabilities):
                barrier.wait(timeout=10)
                outcomes[label] = post("/v1/decisions/" + head, credential, capabilities, body, decision_tag)

            threads = [threading.Thread(target=answer, args=(label, credential, capabilities))
                       for label, credential, capabilities in (("first", authorized, first_capabilities), ("peer", peer, second_capabilities))]
            for thread in threads:
                thread.start()
            for thread in threads:
                thread.join(timeout=30)
            assert len(outcomes) == 2, ("concurrent answers did not return", sorted(outcomes))
            accepted = [(label, value) for label, (status, value) in outcomes.items() if status == 202]
            refused = [(label, status, value) for label, (status, value) in outcomes.items() if status != 202]
            assert len(accepted) == 1 and len(refused) == 1, ("concurrent answers", {label: status for label, (status, _) in outcomes.items()})
            winner, receipt = accepted[0]
            loser, refused_status, problem = refused[0]
            assert refused_status == 412 and problem["code"] == "stale-revision", ("concurrent answer refusal", refused_status, problem["code"])
            client = first if winner == "first" else second
            command, _, raw = client[1](receipt["links"]["self"], "CommandReceipt",
                lambda value: value["state"] in ("effect-observed", "refused", "unresolved"))
            (work / "control-answer-command.json").write_bytes(raw)
            assert command["state"] == "effect-observed" and command["effect"]["kind"] == "answer-accepted", ("answer effect", command["state"])
            assert command["acknowledgement"]["state"] == "delivered", ("answer acknowledgement", command["acknowledgement"])
            ended(first, run, "succeeded")
            records = run_records(run, authorized)
            questions = [record for record in records if record["schema"] == "question" and record["to"] == {"to": "manager"}]
            assert len(questions) == 1, ("person questions", len(questions))
            answers = [record for record in records if record["schema"] == "answer" and record["replyTo"] == questions[0]["position"]]
            assert len(answers) == 1 and answers[0]["about"].get("command") == receipt["id"] and answers[0]["body"] is False, (
                "run-log answers of the question", [(record["about"], record["body"]) for record in answers])
            print("PASS controls case 3: of two concurrent answers to head", head, "the", winner, "credential's command", receipt["id"],
                  "was delivered and reached answer-accepted, the", loser, "credential received 412 stale-revision,",
                  "and the run log holds one answer, and the run succeeded", flush=True)

            # Case 4. A non-head answer and an unoffered steer refuse, the
            # per-run FIFO order holds, and a retry through the run control
            # reaches the effect retried.
            run = start(second, second_capabilities, "profile_1")
            base = "/v1/runs/" + run
            pending = None
            deadline = time.monotonic() + 40
            while pending is None or len(pending) < 2:
                assert time.monotonic() < deadline, ("two pending decisions deadline", pending)
                time.sleep(0.05)
                pending = queue(second, run)
            head, later = pending
            control, control_tag, raw = second[0](base + "/control", "RunControl")
            (work / "control-fifo-before.json").write_bytes(raw)
            assert control["decisionHeadId"] == head, ("run control head", control["decisionHeadId"], head)
            assert not any(offer["operation"] == "steer" for offer in control["offers"]), ("unexpected steer offer", control["offers"])
            decision, decision_tag, _ = second[0]("/v1/decisions/" + later, "Decision")
            assert decision["position"] == 1 and decision["state"] == "pending", ("non-head decision", decision["position"], decision["state"])
            body = {"occurrenceId": decision["address"]["occurrenceId"], "generation": decision["generation"]}
            body.update({"operation": "answer", "value": False} if decision["kind"] == "question" else {"operation": "choose-recovery", "choice": "retry"})
            status, problem = post("/v1/decisions/" + later, peer, second_capabilities, body, decision_tag)
            assert status == 409 and problem["code"] == "decision-not-head", ("non-head answer", status, problem.get("code"))
            recovery = decision if decision["kind"] == "recovery" else second[0]("/v1/decisions/" + head, "Decision")[0]
            assert recovery["kind"] == "recovery", ("mixed-controls recovery decision", recovery["kind"])
            status, problem = post(base + "/control", peer, second_capabilities,
                                   {"operation": "steer", "occurrenceId": recovery["address"]["occurrenceId"], "attemptId": "0",
                                    "timing": "interrupt-now", "text": "No steer is offered."}, control_tag)
            assert status == 409 and problem["code"] == "unsupported-operation", ("unoffered steer", status, problem.get("code"))
            assert queue(second, run) == [head, later], ("the refusals changed the run queue", queue(second, run))
            order = []
            for expected in (head, later):
                control, _, _ = second[1](base + "/control", "RunControl", lambda value: value["decisionHeadId"] is not None)
                assert control["decisionHeadId"] == expected, ("per-run FIFO order", control["decisionHeadId"], expected)
                uri, kind = act(second, second_capabilities, run, expected, "retry")
                order.append(effect(second, uri, kind))
            ended(second, run, "succeeded")
            retried = next(command for command in order if command["operation"] == "retry")
            print("PASS controls case 4: non-head", later, "refused with 409 decision-not-head, an unoffered steer refused with",
                  "409 unsupported-operation, the queue kept", head, "before", later, "and the heads were acted on in that order,",
                  "retry command", retried["id"], "reached the effect retried, and run", run, "succeeded", flush=True)

            # Case 5. A choose-recovery abandon through the decision reaches
            # the effect recovery-chosen, and the run ends failed.
            run = start(second, second_capabilities, "profile_1")
            base = "/v1/runs/" + run
            abandoned = None
            deadline = time.monotonic() + 50
            while True:
                snapshot, _, _ = second[0](base + "/snapshot", "RunSnapshot")
                if snapshot["runtime"] is not None and snapshot["runtime"]["status"] in terminal:
                    break
                assert time.monotonic() < deadline, "abandon run terminal deadline"
                control, _, _ = second[0](base + "/control", "RunControl")
                if control["decisionHeadId"] is None:
                    time.sleep(0.05)
                    continue
                uri, kind = act(second, second_capabilities, run, control["decisionHeadId"], "abandon")
                command = effect(second, uri, kind)
                if command["operation"] == "choose-recovery":
                    abandoned = command
            assert abandoned is not None, "no recovery decision was abandoned"
            ended(second, run, "failed")
            print("PASS controls case 5: choose-recovery command", abandoned["id"], "chose abandon through the decision,",
                  "reached the effect recovery-chosen, and run", run, "ended failed", flush=True)
        finally:
            if process.poll() is None:
                process.terminate()
            process.wait(timeout=25)
            (work / "server-0.exit").write_text(str(process.returncode) + "\n")


def live_flow_checks(facts):
    """Read the manager log and the run stores with the flow verb after the
    manager exits, and require the joins of the live redirect command."""
    run, store, occurrence, first_target, spare_target, identity, window = facts["redirect"]
    flow_dir = work / "manager" / "flow"
    stores = sorted(work.glob("manager/runs/runs/*/runtime"))
    completed = subprocess.run([str(runner), "flow", str(flow_dir)] + [str(path) for path in stores],
                               stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=120)
    (work / "live-redirect-joined.ndjson").write_bytes(completed.stdout)
    (work / "live-redirect-joined.stderr").write_bytes(completed.stderr)
    lines = [json.loads(line) for line in completed.stdout.splitlines()]
    assert lines and "summary" in lines[-1], ("flow verb", completed.returncode, completed.stderr[-2000:])
    summary = lines[-1]["summary"]
    assert completed.returncode == 0 and summary["verified"] and not summary["problems"], ("flow verb", completed.returncode, summary["problems"])
    at = lambda log, position: {"log": log, "position": position}
    runlog = [line for line in lines[:-1] if line["log"] == str(store)]
    manager = [line for line in lines[:-1] if line["log"] not in [str(path) for path in stores]]
    commands = [line for line in manager if line["schema"] == "command" and line["about"].get("command") == identity]
    assert len(commands) == 1 and commands[0]["body"]["operation"] == "redirect" and commands[0]["body"]["resource"] == f"/v1/runs/{run}/control", (
        "live redirect command record", [line["body"] for line in commands])
    command = commands[0]
    receipts = [line for line in manager if line["schema"] == "receipt" and line["replyTo"] == command["position"] and line["log"] == command["log"]]
    assert len(receipts) == 1 and receipts[0]["body"]["id"] == identity and receipts[0]["body"]["state"] != "refused", (
        "live redirect receipt record", [line["body"] for line in receipts])
    relays = [line for line in manager if line["schema"] == "relay" and line["body"]["kind"] == "control" and line["about"].get("command") == identity]
    assert len(relays) == 1 and relays[0]["body"]["nativeRun"] == store.parent.name, ("live redirect relay record", [line["body"] for line in relays])
    relay = relays[0]
    delivered = [item["delivered"] for item in summary["joins"]["relays"] if item["relay"] == at(relay["log"], relay["position"])]
    assert len(delivered) == 1 and delivered[0] is not None and delivered[0]["log"] == str(store), ("live redirect relay delivery", delivered)
    control = next(line for line in runlog if line["position"] == delivered[0]["position"])
    assert control["schema"] == "control" and control["from"] == "manager" and control["about"].get("command") == identity, (
        "live redirect run-log control", control["schema"], control["from"], control["about"])
    acknowledged = [item["acknowledgement"] for item in summary["joins"]["controls"] if item["control"] == at(str(store), control["position"])]
    assert len(acknowledged) == 1 and acknowledged[0] is not None, ("live redirect acknowledgement", acknowledged)
    questions = [line for line in runlog if line["schema"] == "question" and str(line["about"].get("occurrence")) == occurrence
                 and isinstance(line["to"].get("to"), dict) and "model" in line["to"]["to"]]
    assert [line["to"]["to"]["model"] for line in questions] == [first_target, spare_target], (
        "live redirect questions", [(line["position"], line["to"]) for line in questions])
    asked, spare = questions
    failures = [line for line in runlog if line["schema"] == "failure" and line.get("replyTo") == asked["position"]]
    assert len(failures) == 1 and identity in json.dumps(failures[0]), ("live redirect failure", failures)
    assert asked["position"] < control["position"] < failures[0]["position"] < spare["position"], (
        "live redirect order", asked["position"], control["position"], failures[0]["position"], spare["position"])
    answers = [line for line in runlog if line["schema"] == "answer" and line.get("replyTo") == spare["position"]]
    assert len(answers) == 1 and answers[0]["from"] == {"model": spare_target}, ("spare answer", [line["from"] for line in answers])
    print("PASS live-redirect case 3: the flow verb joins redirect command", identity, "at manager position", command["position"],
          "its receipt at", receipts[0]["position"], "and its relay at", relay["position"], "to run-log control", control["position"],
          "from the manager with acknowledgement", acknowledged[0], "and the run log holds failure", failures[0]["position"],
          "for question", asked["position"], "to", first_target, "and question", spare["position"], "to", spare_target,
          "with its answer", flush=True)


def person_checks():
    """Asks named by the personAnswers policy field through the real HTTPS
    manager. Each numbered case prints one PASS line."""
    authorized = {"Authorization": "Bearer " + bearer}
    requests = work / "adapter-requests"
    answer_text = "Answered by a person through the manager."
    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        try:
            wait_ready(process)
            status, capabilities, _ = request("/v1/capabilities", authorized)
            assert status == 200
            validate("Capabilities", capabilities)
            observed, wait_for, mutate, _ = mixed_client(capabilities, authorized)
            def prepare(profile):
                """Create and enqueue one prompt-source request of the profile.
                Returns the request URI, the live preparation and its ETag."""
                status, catalogue, _ = request("/v1/workflows?profileId=" + profile, authorized)
                assert status == 200, ("person-answers catalogue", profile, status)
                workflow = next(item for item in catalogue["items"] if item["name"] == "prompt-source")
                create = {"workflowId": workflow["id"], "descriptorRevision": workflow["revision"],
                          "profileId": workflow["profileId"], "profileRevision": workflow["profileRevision"]}
                key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
                status, created, raw = request("/v1/requests", authorized | {"Content-Type": "application/json", "Idempotency-Key": key},
                                               method="POST", payload=json.dumps(create, separators=(",", ":")).encode())
                assert status == 201, ("request creation", profile, status, created.get("code"))
                validate("Request", created, raw)
                request_uri = created["links"]["self"]
                current, tag, _ = observed(request_uri, "Request")
                mutate(request_uri, {"operation": "set-input", "input": {"name": "input", "source": "literal", "value": "Person answers fixture input."}}, tag)
                current, tag, _ = observed(request_uri, "Request")
                mutate(request_uri, {"operation": "enqueue"}, tag)
                current, _, _ = wait_for(request_uri, "Request", lambda value: value["preparationId"] is not None)
                preparation, tag, raw = observed("/v1/preparations/" + current["preparationId"], "Preparation")
                (work / ("person-review-" + profile + ".json")).write_bytes(raw)
                assert preparation["state"] == "live", preparation["state"]
                return request_uri, preparation, tag

            def approve(request_uri, preparation, tag):
                """Approve the exact review. Returns the run."""
                selectors = ("reviewDigest", "requestRevision", "profileRevision", "descriptorRevision", "processGeneration")
                mutate("/v1/preparations/" + preparation["id"], {"operation": "approve", **{name: preparation[name] for name in selectors}}, tag)
                current, _, _ = wait_for(request_uri, "Request", lambda value: value["runId"] is not None)
                return current["runId"]

            # Case 1. The review shows personAnswers in the target policy.
            request_uri, preparation, tag = prepare("profile_1")
            review = preparation["review"]
            assert review["personAnswering"] == "local-control", review["personAnswering"]
            assert review["policy"]["kind"] == "routed" and review["policy"].get("personAnswers") == ["model:fixed-point"], (
                "the review does not show personAnswers in the target policy", review["policy"])
            print("PASS person-answers case 1: the review of preparation", preparation["id"], "shows personAnswers",
                  review["policy"]["personAnswers"], "in the routed target policy under local-control", flush=True)

            # Case 2. After the approval the named ask is a pending question decision.
            run = approve(request_uri, preparation, tag)
            base = "/v1/runs/" + run
            control, _, _ = wait_for(base + "/control", "RunControl", lambda value: value["decisionHeadId"] is not None)
            head = control["decisionHeadId"]
            decision, decision_tag, raw = observed("/v1/decisions/" + head, "Decision")
            (work / "person-decision.json").write_bytes(raw)
            assert decision["kind"] == "question" and decision["state"] == "pending" and decision["runId"] == run, (
                "the named ask is not a pending question decision", decision["kind"], decision["state"])
            assert decision["question"]["code"] == "text" and decision["question"]["addressee"] == "person model:fixed-point", (
                "the named ask has another answer type or addressee", decision["question"]["code"], decision["question"]["addressee"])
            stores = sorted(work.glob("manager/runs/runs/*/runtime"))
            assert len(stores) == 1, ("person-answers run stores", stores)
            store = stores[0]
            events = [json.loads(line)["event"] for line in (store / "events.ndjson").read_bytes().splitlines()]
            started = [event for event in events if event["type"] == "occurrence.started"]
            assert [event["addressee"] for event in started] == ["person model:fixed-point"], (
                "the named ask did not start as a person ask", [event.get("addressee") for event in started])
            assert any(event["type"] == "occurrence.person-answer-pending" for event in events), "no person answer is pending"
            print("PASS person-answers case 2: after the approval run", run, "has the pending question decision", head,
                  "of answer type", decision["question"]["code"], "addressed to", decision["question"]["addressee"], "as its ask started", flush=True)

            # Case 3. A typed answer through the decision completes the ask
            # without an engine turn, and the run succeeds.
            body = {"operation": "answer", "occurrenceId": decision["address"]["occurrenceId"],
                    "generation": decision["generation"], "value": answer_text}
            answer_receipt = mutate("/v1/decisions/" + head, body, decision_tag)
            answer_command = answer_receipt.rsplit("/", 1)[1]
            snapshot, _, raw = wait_for(base + "/snapshot", "RunSnapshot",
                lambda value: value["runtime"] is not None and value["runtime"]["status"] in ("succeeded", "failed", "cancelled"))
            (work / "person-terminal-snapshot.json").write_bytes(raw)
            assert snapshot["runtime"]["status"] == "succeeded", ("person-answers run terminal status", snapshot["runtime"]["status"])
            answers = json.loads((store / "answers.json").read_bytes())["answers"]
            assert [record["answer"] for record in answers] == [answer_text], ("recorded answers", [record["answer"] for record in answers])
            events = [json.loads(line)["event"] for line in (store / "events.ndjson").read_bytes().splitlines()]
            assert not any(event["type"].startswith("attempt.") for event in events), (
                "an attempt happened for the named ask", [event["type"] for event in events if event["type"].startswith("attempt.")])
            relayed = requests.read_text().splitlines() if requests.exists() else []
            assert "session/prompt" not in relayed, ("the adapter received a turn for the named ask", relayed)
            print("PASS person-answers case 3: answer command", answer_command, "of decision", head, "delivered the typed answer,",
                  "the run succeeded with it as the only recorded answer, and no attempt happened and the adapter received no",
                  "session/prompt among its requests", relayed, flush=True)

            # Case 4. Without --person-answer the same launcher relays a turn,
            # so that the record of case 3 can show one. The model answers
            # and no decision is pending.
            request_uri, plain, tag = prepare("profile_plain")
            assert "personAnswers" not in plain["review"]["policy"], ("the plain review shows personAnswers", plain["review"]["policy"])
            plain_run = approve(request_uri, plain, tag)
            snapshot, _, _ = wait_for("/v1/runs/" + plain_run + "/snapshot", "RunSnapshot",
                lambda value: value["runtime"] is not None and value["runtime"]["status"] in ("succeeded", "failed", "cancelled"))
            assert snapshot["runtime"]["status"] == "succeeded", ("plain run terminal status", snapshot["runtime"]["status"])
            later = requests.read_text().splitlines()[len(relayed):]
            assert "session/prompt" in later, ("the plain run relayed no turn", later)
            status, queue, _ = request("/v1/decisions?runId=" + plain_run, authorized)
            assert status == 200 and queue["items"] == [], ("plain run decisions", status, queue.get("items"))
            print("PASS person-answers case 4: without --person-answer the review of", plain["id"], "has no personAnswers,",
                  "run", plain_run, "succeeded with no decision, and the same launcher relayed", later, flush=True)
        finally:
            if process.poll() is None:
                process.terminate()
            process.wait(timeout=25)
            (work / "server-0.exit").write_text(str(process.returncode) + "\n")

    # Case 5. The flow verb shows the answer from the answering principal.
    flow_dir = work / "manager" / "flow"
    stores = sorted(work.glob("manager/runs/runs/*/runtime"))
    assert len(stores) == 2 and store in stores, ("person-answers run stores", stores)
    completed = subprocess.run([str(runner), "flow", str(flow_dir)] + [str(path) for path in stores],
                               stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=120)
    (work / "person-answers-joined.ndjson").write_bytes(completed.stdout)
    (work / "person-answers-joined.stderr").write_bytes(completed.stderr)
    lines = [json.loads(line) for line in completed.stdout.splitlines()]
    assert lines and "summary" in lines[-1], ("flow verb", completed.returncode, completed.stderr[-2000:])
    summary = lines[-1]["summary"]
    assert completed.returncode == 0 and summary["verified"] and not summary["problems"], ("flow verb", completed.returncode, summary["problems"])
    at = lambda log, position: {"log": log, "position": position}
    runlog = [line for line in lines[:-1] if line["log"] == str(store)]
    manager = [line for line in lines[:-1] if line["log"] not in [str(path) for path in stores]]
    credential = issued["result"]["credential"]
    principal = {"principal": "credential", "credentialId": credential["credentialId"], "client": credential["clientId"]}
    commands = [line for line in manager if line["schema"] == "command" and line["about"].get("command") == answer_command]
    assert len(commands) == 1 and commands[0]["from"] == principal and commands[0]["body"]["operation"] == "answer", (
        "person answer command record", [(line["from"], line["body"].get("operation")) for line in commands])
    command = commands[0]
    assert command["body"]["body"]["json"].get("value") == answer_text, ("person answer command value", command["body"]["body"]["json"])
    questions = [line for line in runlog if line["schema"] == "question" and line["to"] == {"to": "manager"}]
    assert len(questions) == 1, ("person questions in the run log", [line["about"] for line in questions])
    question = questions[0]
    replies = [line for line in runlog if line["schema"] == "answer" and line.get("replyTo") == question["position"]]
    assert len(replies) == 1 and replies[0]["from"] == "manager" and replies[0]["about"].get("command") == answer_command and replies[0]["body"] == answer_text, (
        "run-log person answer", [(line["from"], line["about"], line["body"]) for line in replies])
    reply = replies[0]
    joined = [item for item in summary["joins"]["answers"] if item["answer"] == at(str(store), reply["position"])]
    assert joined == [{"answer": at(str(store), reply["position"]), "command": at(command["log"], command["position"]), "commandId": answer_command}], (
        "the run-log answer is not joined to the answer command of the credential", joined)
    engine = [line["position"] for line in runlog if line["schema"] in ("engine-start", "turn")]
    assert not engine, ("the run log has an engine start or turn", engine)
    print("PASS person-answers case 5: the flow verb joins run-log answer", reply["position"], "to question", question["position"],
          "and to answer command", answer_command, "at manager position", command["position"], "from credential", credential["credentialId"],
          "and the run log has no engine start or turn", flush=True)
    print("PASS person-answers: every person-answer case held against the running TLS 1.3 manager", flush=True)


def worker_failure_checks():
    """The failure ending of a lost worker through the real HTTPS manager.
    Each numbered case prints one PASS line."""
    authorized = {"Authorization": "Bearer " + bearer}
    terminal = ("succeeded", "failed", "cancelled")

    def groups(pids):
        """The process group of each live process in pids, with its command."""
        listing = subprocess.run(["ps", "-o", "pid=,pgid=,command="] + sum((["-p", str(pid)] for pid in pids), []),
                                 stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=10).stdout
        return [(int(pid), int(pgid), command) for pid, pgid, command in
                (line.strip().split(None, 2) for line in listing.splitlines() if line.strip())]

    def attempt(path, body, tag):
        """Send one command and return its status and its final receipt
        state, or the refusal code. A receipt that stays accepted or
        dispatch-attempted past the bound fails."""
        key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
        payload = json.dumps(body, separators=(",", ":")).encode()
        headers = authorized | {"Content-Type": "application/json", "Idempotency-Key": key, "If-Match": tag}
        status, receipt, raw, _ = exchange(path, headers, method="POST", payload=payload)
        if status != 202:
            return status, receipt["code"], None
        validate("CommandReceipt", receipt, raw)
        value, _, raw = wait_for(receipt["links"]["self"], "CommandReceipt",
            lambda value: value["state"] in ("effect-observed", "refused", "unresolved"))
        (work / ("lost-" + body["operation"] + "-receipt.json")).write_bytes(raw)
        return status, value["state"], value

    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        try:
            wait_ready(process)
            status, capabilities, raw = request("/v1/capabilities", authorized)
            assert status == 200
            validate("Capabilities", capabilities, raw)
            client = mixed_client(capabilities, authorized)
            observed, wait_for, _, _ = client
            status, catalogue, _ = request("/v1/workflows?profileId=profile_1", authorized)
            assert status == 200
            workflow = next(item for item in catalogue["items"] if item["name"] == "mixed-controls")
            create = json.dumps({"workflowId": workflow["id"], "descriptorRevision": workflow["revision"],
                                 "profileId": workflow["profileId"], "profileRevision": workflow["profileRevision"]},
                                separators=(",", ":")).encode()

            def create_request():
                key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
                status, created, raw = request("/v1/requests", authorized | {
                    "Content-Type": "application/json", "Idempotency-Key": key}, method="POST", payload=create)
                assert status == 201, ("request creation", status, created.get("code"))
                validate("Request", created, raw)
                return created

            # Case 1. A run waits at its person question with a live worker.
            _, run = approve_mixed(create_request(), workflow, client)
            base = "/v1/runs/" + run
            head, _, _ = drive_mixed(run, client, stop_at_question=True, overview=False)
            control, _, _ = observed(base + "/control", "RunControl")
            assert control["supervision"] == "owned" and control["decisionHeadId"] == head, (control["supervision"], control["decisionHeadId"])
            decision, _, _ = observed("/v1/decisions/" + head, "Decision")
            # The worker is the frontend proxy that the manager starts, in its
            # own process group, and the inner frontend worker that the proxy
            # starts in a second process group with the engine adapter. Both
            # groups are read from the live processes, never from a stored
            # PID. The proxy alone is not the worker: the inner worker
            # inherits the pipes of the manager and continues the run when
            # only the proxy dies.
            manager_group = os.getpgid(process.pid)
            tree = groups(descendants(process.pid))
            (work / "worker-processes.txt").write_text("".join(f"{pid} {pgid} {command}\n" for pid, pgid, command in tree))
            targets = sorted({pgid for _, pgid, _ in tree})
            assert targets and manager_group not in targets, ("worker process groups", targets, manager_group)
            print("PASS failures-worker case 1: run", run, "waits at person question", head, "under owned supervision, with",
                  len(tree), "worker processes in process groups", targets, flush=True)

            # Case 2. SIGKILL of the worker process groups ends in lost
            # supervision and never in a successful result.
            for group in targets:
                os.killpg(group, signal.SIGKILL)
            killed = time.monotonic()
            value, _, raw = wait_for(base, "Run", lambda value: value["supervision"] == "lost")
            lost_after = time.monotonic() - killed
            (work / "lost-run.json").write_bytes(raw)
            assert value["runtime"] is None or value["runtime"]["status"] != "succeeded", ("lost run runtime", value["runtime"])
            assert value["verification"]["state"] != "verified", ("lost run verification", value["verification"])
            assert "lost-supervision" in value["limitations"], ("lost run limitations", value["limitations"])
            control, control_tag, raw = observed(base + "/control", "RunControl")
            (work / "lost-control.json").write_bytes(raw)
            assert control["supervision"] == "lost" and not control["cancelAllowed"], ("lost run control", control["supervision"], control["cancelAllowed"])
            snapshot, _, _ = observed(base + "/snapshot", "RunSnapshot")
            assert snapshot["runtime"] is None or snapshot["runtime"]["status"] != "succeeded", ("lost run snapshot", snapshot["runtime"])
            outputs, _, _ = observed(base + "/outputs", "OutputPage")
            assert not [item for item in outputs["items"] if item["kind"] == "result" and item["verification"]["state"] == "verified"], (
                "the lost run shows a verified result", outputs["items"])
            print("PASS failures-worker case 2: after SIGKILL of the worker process groups, run", run, "shows lost supervision after",
                  round(lost_after, 2), "seconds with runtime", value["runtime"] and value["runtime"]["status"], "verification",
                  value["verification"]["state"], "and limitations", value["limitations"], flush=True)

            # Case 3. An answer and a cancel for the lost run are refused or
            # end unresolved, and neither is effect-observed.
            status, decision_now, raw, headers = exchange("/v1/decisions/" + head, authorized)
            (work / "lost-decision.json").write_bytes(raw)
            if status == 200:
                answer = {"operation": "answer", "occurrenceId": decision["address"]["occurrenceId"],
                          "generation": decision["generation"], "value": False}
                outcome = attempt("/v1/decisions/" + head, answer, headers["etag"])
            else:
                outcome = (status, decision_now["code"], None)
            assert outcome[0] != 202 or outcome[1] in ("refused", "unresolved"), ("lost run answer", outcome[:2])
            assert outcome[2] is None or outcome[2]["effect"] is None, ("lost run answer effect", outcome[2]["effect"])
            cancel = attempt(base + "/control", {"operation": "cancel"}, control_tag)
            assert cancel[0] != 202 or cancel[1] in ("refused", "unresolved"), ("lost run cancel", cancel[:2])
            assert cancel[2] is None or cancel[2]["effect"] is None, ("lost run cancel effect", cancel[2]["effect"])
            value, _, _ = observed(base, "Run")
            assert value["supervision"] == "lost" and (value["runtime"] is None or value["runtime"]["status"] != "succeeded")
            print("PASS failures-worker case 3: the answer of decision", head, "ended as", outcome[:2], "and the cancel ended as",
                  cancel[:2], "with no effect, and the run stays lost", flush=True)

            # Case 4. No worker process remains or starts for the lost run.
            remaining = descendants(process.pid)
            assert not remaining, ("processes remain after the worker loss", groups(remaining))
            stores = sorted(work.glob("manager/runs/runs/*/runtime"))
            assert len(stores) == 1, ("run stores after the worker loss", stores)
            lost_store = stores[0]
            starts = [line for line in (lost_store / "events.ndjson").read_bytes().splitlines()
                      if json.loads(line)["event"]["type"] == "run.started"]
            assert len(starts) == 1, ("the lost run started again", len(starts))
            print("PASS failures-worker case 4: no manager descendant remains and the run store of", run,
                  "holds one run start", flush=True)

            # Case 5. A new request on the same manager is reviewed,
            # approved and completes with a verified result.
            _, fresh = approve_mixed(create_request(), workflow, client)
            _, answered, recovered = drive_mixed(fresh, client, overview=False)
            assert answered and recovered, ("new run decisions", answered, recovered)
            artifact = verified_download(fresh, client, authorized)
            value, _, _ = observed(base, "Run")
            assert value["supervision"] == "lost", ("lost run after the new run", value["supervision"])
            print("PASS failures-worker case 5: new run", fresh, "on the same manager was reviewed, approved, answered and",
                  "retried, and succeeded with verified result", artifact["id"], flush=True)
        finally:
            if process.poll() is None:
                process.terminate()
            process.wait(timeout=25)
            (work / "server-0.exit").write_text(str(process.returncode) + "\n")

    # Case 6. The flow verb reports the run log of the lost run as ended
    # without its stop, never as complete.
    completed = subprocess.run([str(runner), "flow", str(lost_store)], stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=120)
    (work / "lost-flow.ndjson").write_bytes(completed.stdout)
    (work / "lost-flow.stderr").write_bytes(completed.stderr)
    lines = [json.loads(line) for line in completed.stdout.splitlines()]
    assert lines and "summary" in lines[-1], ("flow verb", completed.returncode, completed.stderr[-2000:])
    summary = lines[-1]["summary"]
    questions = [line["position"] for line in lines[:-1] if line.get("schema") == "question" and line["to"] == {"to": "manager"}]
    assert completed.returncode == 2 and summary["stop"] is None and summary["states"]["lostSupervision"], (
        "the flow verb does not report lost supervision", completed.returncode, summary["stop"], summary["states"])
    assert questions and set(questions) <= set(summary["states"]["uncertain"]), ("the person question is not uncertain", questions, summary["states"]["uncertain"])
    print("PASS failures-worker case 6: the flow verb exits 2 for the lost run log, with no stop, lost supervision and",
          "uncertain asks", summary["states"]["uncertain"], flush=True)
    print("PASS failures-worker: every worker-loss case held against the running TLS 1.3 manager", flush=True)


if worker_failure_mode:
    worker_failure_checks()
    raise SystemExit(0)


def manager_failure_checks():
    """The failure ending of a lost manager and the release of its quarantined
    reservations through three lifetimes of the real HTTPS manager with one
    profile and one execution reservation. The failures-launched mode runs
    launched_release in place of the three lifetimes. Each numbered case
    prints one PASS line."""
    import sqlite3
    authorized = {"Authorization": "Bearer " + bearer}
    flow_dir = work / "manager" / "flow"
    half = MANAGER_FAILURE_LEDGER // 2

    def serve(index):
        """Start one foreground manager lifetime on the same root and
        configuration and wait for HTTPS readiness."""
        with (work / f"server-{index}.stdout").open("wb") as output, (work / f"server-{index}.stderr").open("wb") as errors:
            process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                        "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        wait_ready(process)
        return process

    def process_groups():
        """Every live process with its process group and command, from one
        process listing."""
        listing = subprocess.run(["ps", "-Ao", "pid=,pgid=,command="], stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                 text=True, timeout=10, check=True).stdout
        return [(int(pid), int(pgid), command) for pid, pgid, command in
                (line.strip().split(None, 2) for line in listing.splitlines() if len(line.split(None, 2)) == 3)]

    def workers(process, index):
        """The worker processes of a manager lifetime and their process
        groups, which must differ from the process group of the manager."""
        tree = [entry for entry in process_groups() if entry[0] in set(descendants(process.pid))]
        (work / f"worker-processes-{index}.txt").write_text("".join(f"{pid} {pgid} {command}\n" for pid, pgid, command in tree))
        targets = sorted({pgid for _, pgid, _ in tree})
        assert targets and os.getpgid(process.pid) not in targets, ("worker process groups", targets, os.getpgid(process.pid))
        return tree, targets

    def vanished(targets, index):
        """Wait until no process of the worker groups remains, within the
        bound. Returns the seconds of the wait."""
        killed = time.monotonic()
        while True:
            remaining = [entry for entry in process_groups() if entry[1] in targets]
            if not remaining or time.monotonic() - killed > 30:
                break
            time.sleep(0.1)
        (work / f"worker-processes-after-kill-{index}.txt").write_text("".join(f"{pid} {pgid} {command}\n" for pid, pgid, command in remaining))
        assert not remaining, ("worker processes remain", remaining)
        return time.monotonic() - killed

    def kill(process, targets, index):
        """SIGKILL of the manager process. Each worker process sees its
        control channel end and stops within the bound. Returns the seconds
        until no process of the worker groups remained."""
        process.kill()
        process.wait(timeout=25)
        return vanished(targets, index)

    def ended(process, index, killed):
        """End a lifetime that a case left running, and check how it ended."""
        if process.poll() is None:
            process.kill() if killed else process.terminate()
        process.wait(timeout=25)
        (work / f"server-{index}.exit").write_text(str(process.returncode) + "\n")

    def log_files():
        """The sealed segments in start order, then the active file."""
        sealed = sorted((flow_dir / "sealed").glob("*/*.ndjson"))
        return sealed + sorted(flow_dir.glob("*.ndjson"))

    def log_bytes():
        """The bytes of the manager log and of its claim checks, as the
        writer counts them."""
        claims = [path for path in (flow_dir / "claims").rglob("*") if path.is_file()] if (flow_dir / "claims").is_dir() else []
        return sum(path.stat().st_size for path in log_files() + claims)

    def log_records():
        """Every record line of the manager log, in position order."""
        return [json.loads(line) for path in log_files() for line in path.read_bytes().splitlines()]

    def positioned():
        """Every record line of the manager log with its position: the
        sealed segments from the start of the oldest, then the active file."""
        sealed = sorted((flow_dir / "sealed").glob("*/*.ndjson"))
        position = int(sealed[0].name[:20]) if sealed else 0
        found = []
        for path in log_files():
            assert path not in sealed or int(path.name[:20]) == position, ("a sealed segment does not continue the positions", path, position)
            for line in path.read_bytes().splitlines():
                found.append((position, json.loads(line)))
                position += 1
        return found

    def orphan_replies(asks):
        """For each orphaned ask, by position, its sender and its expected
        reply body, the replies of the manager log that name it. Each must be
        the one reply of the manager to the sender, with that body."""
        replies = {}
        for position, record in positioned():
            if record.get("replyTo") in asks:
                replies.setdefault(record["replyTo"], []).append(record)
        for position, (sender, schema, body) in asks.items():
            found = replies.get(position, [])
            assert len(found) == 1 and found[0]["schema"] == schema and found[0]["from"] == "manager" \
                and found[0]["to"] == {"to": sender} and found[0]["body"] == {"inline": body}, (
                "the reply to an orphaned ask", position, schema, body, found)
        return sorted(asks)

    def lifetime_notice():
        """The body of the lifetime notice of the newest lifetime."""
        return [record for record in log_records() if record["schema"] == "notice"
                and record["body"]["inline"]["notice"] == "lifetime"][-1]["body"]["inline"]

    def names(record, identities):
        return bool(set(record["about"].values()) & identities)

    def start_relays(run):
        return [record for record in log_records() if record["schema"] == "relay"
                and record["body"].get("inline", {}).get("kind") == "start" and record["about"].get("managerRun") == run]

    def run_starts(store):
        return [line for line in (store / "events.ndjson").read_bytes().splitlines()
                if json.loads(line)["event"]["type"] == "run.started"]

    def mixed_workflow(profile):
        status, catalogue, _ = request("/v1/workflows?profileId=" + profile, authorized)
        assert status == 200
        found = next(item for item in catalogue["items"] if item["name"] == "mixed-controls")
        return found, json.dumps({"workflowId": found["id"], "descriptorRevision": found["revision"],
                                  "profileId": found["profileId"], "profileRevision": found["profileRevision"]},
                                 separators=(",", ":")).encode()

    def create_request(epoch, payload):
        key = epoch + "." + secrets.token_urlsafe(16)
        status, created, raw = request("/v1/requests", authorized | {
            "Content-Type": "application/json", "Idempotency-Key": key}, method="POST", payload=payload)
        assert status == 201, ("request creation", status, created.get("code"))
        validate("Request", created, raw)
        return created

    def database():
        found = sorted((work / "manager").rglob("coordination.sqlite3"))
        assert len(found) == 1, ("coordination database", found)
        return found[0].as_uri() + "?mode=ro"

    def read_store(statement, parameters=()):
        """The rows of one read-only query of the coordination database."""
        connection = sqlite3.connect(database(), uri=True)
        try:
            return [tuple(row) for row in connection.execute(statement, parameters)]
        finally:
            connection.close()

    def unchanged(action):
        """The value of the action, and whether no other connection changed
        the database and nothing was appended to the manager log meanwhile."""
        observer = sqlite3.connect(database(), uri=True)
        try:
            version_before = observer.execute("PRAGMA data_version").fetchone()[0]
            log_before = log_bytes()
            value = action()
            version_after = observer.execute("PRAGMA data_version").fetchone()[0]
        finally:
            observer.close()
        return value, version_after == version_before and log_bytes() == log_before

    def canonical_digest(facts):
        """The SHA-256 of the canonical JSON bytes of the facts: sorted keys,
        no whitespace, and UTF-8 text."""
        return hashlib.sha256(json.dumps(facts, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode()).hexdigest()

    def release(quarantine, evidence, digest, refused=None):
        return administration({"version": 1, "operation": "release-quarantine", "quarantineId": quarantine,
                               "cleanupEvidenceId": evidence, "cleanupEvidenceDigest": digest}, refused=refused)

    def release_and_run(epoch, client, quarantine, facts, case, queued=None):
        """A new request stays queued with capacity behind the quarantined
        reservation. A given queued pair of the request and its workflow
        names a request that the caller created and enqueued before. Otherwise
        the request is created and enqueued here. check-store lists the
        reservation and check-quarantine
        gives the clean evidence of the facts, without a change. A release
        with a wrong digest and a release of an unknown identity refuse
        without a change, and the request stays queued. The release with the
        evidence frees the capacity. The request then reaches review without
        another client command, and its approved run completes with a
        verified result. Releases of the held reservation of that run and of
        the released reservation refuse with state-conflict."""
        observed, wait_for, _, _ = client
        if queued is None:
            workflow, payload = mixed_workflow("profile_1")
            waiting = create_request(epoch, payload)
            enqueue_mixed(waiting, workflow, client)
        else:
            waiting, workflow = queued
        waiting_uri = waiting["links"]["self"]
        current, _, _ = wait_for(waiting_uri, "Request", lambda value: value["admission"]["reasons"] == ["capacity"])
        assert current["phase"] == "queued" and current["preparationId"] is None, ("queued request", current["phase"], current["preparationId"])
        (checked, answers), same = unchanged(lambda: (
            administration({"version": 1, "operation": "check-store"})["result"],
            [administration({"version": 1, "operation": "check-quarantine", "quarantineId": quarantine})["result"] for _ in range(2)]))
        assert same, ("check-store or check-quarantine changed the database or the manager log", case)
        assert checked == {"integrity": "valid", "quarantineIds": [quarantine]}, ("check-store", case, checked, quarantine)
        once, twice = answers
        digest = canonical_digest(facts)
        assert once["quarantineId"] == quarantine and once["state"] == "clean" and once["processGeneration"] == facts["processGeneration"], (
            "check-quarantine of a quarantined reservation", case, once)
        assert once["cleanupEvidenceDigest"] == digest and once["cleanupEvidenceId"] == "cleanup_" + digest[:32], (
            "the evidence digest differs from the canonical facts", case, once, facts)
        assert once["expiresAt"] is not None and all(twice[key] == once[key] for key in
            ("quarantineId", "state", "cleanupEvidenceId", "cleanupEvidenceDigest", "processGeneration")), ("two checks differ", case, once, twice)
        _, same = unchanged(lambda: (
            release(quarantine, once["cleanupEvidenceId"], "0" * 64, refused="cleanup-unverified"),
            release("reservation_unknown", once["cleanupEvidenceId"], digest, refused="state-conflict")))
        assert same, ("a refused release changed the database or the manager log", case)
        time.sleep(1)
        current, _, _ = observed(waiting_uri, "Request")
        assert current["phase"] == "queued" and current["preparationId"] is None and current["admission"]["reasons"] == ["capacity"], (
            "the request left the queue after a refused release", case, current["phase"], current["admission"])
        released = release(quarantine, once["cleanupEvidenceId"], digest)["result"]
        assert released == {"quarantineId": quarantine, "state": "released"}, ("release-quarantine", case, released)
        _, run = approve_review(waiting, workflow, client)
        held = [ident for (ident,) in read_store("SELECT id FROM reservations WHERE request_id=? AND state='held'", (waiting["id"],))]
        assert len(held) == 1, ("the held reservation of the new run", case, held)
        administration({"version": 1, "operation": "check-quarantine", "quarantineId": held[0]}, refused="state-conflict")
        release(held[0], once["cleanupEvidenceId"], digest, refused="state-conflict")
        release(quarantine, once["cleanupEvidenceId"], digest, refused="state-conflict")
        assert read_store("SELECT state,slot FROM reservations WHERE id=?", (quarantine,)) == [("released", None)]
        assert not read_store("SELECT 1 FROM reservation_resources WHERE reservation_id=?", (quarantine,))
        _, answered, recovered = drive_mixed(run, client, overview=False)
        assert answered and recovered, ("decisions of the new run", case, answered, recovered)
        artifact = verified_download(run, client, authorized)
        print(f"PASS {sys.argv[5]} case {case}: request", waiting["id"], "waited with capacity behind quarantined reservation",
              quarantine, "; check-quarantine gave", once["cleanupEvidenceId"], "over the recomputed facts of", facts["evidence"],
              "; a wrong digest refused with cleanup-unverified and an unknown identity with state-conflict without a change;",
              "the release freed the capacity, the request reached review without another client command, and run", run,
              "succeeded with verified result", artifact["id"], "; releases of held reservation", held[0],
              "and of the released reservation refused with state-conflict", flush=True)
        return waiting, run

    def stopped(targets):
        """Every live process of the worker groups, with whether ps shows it
        stopped, from one process listing."""
        listing = subprocess.run(["ps", "-Ao", "pid=,pgid=,stat="], stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                 text=True, timeout=10, check=True).stdout
        return [(int(pid), stat.startswith("T")) for pid, pgid, stat in
                (line.split() for line in listing.splitlines() if len(line.split()) == 3) if int(pgid) in targets]

    def launched_release():
        """The failures-launched mode. See LAUNCHED_FAILURE for the steps. The
        harness signals only the worker process groups of its own manager,
        which it reads from the live processes before the manager dies, never
        from a stored PID."""
        first = serve(0)
        try:
            status, capabilities, raw = request("/v1/capabilities", authorized)
            assert status == 200
            validate("Capabilities", capabilities, raw)
            epoch = capabilities["authorityEpoch"]
            client = mixed_client(capabilities, authorized)
            observed, _, _, _ = client
            workflow, create = mixed_workflow("profile_1")

            # Case 1. A run waits at its person question with a live worker.
            lost_request = create_request(epoch, create)
            _, run = approve_mixed(lost_request, workflow, client)
            head, _, _ = drive_mixed(run, client, stop_at_question=True, overview=False)
            control, _, _ = observed("/v1/runs/" + run + "/control", "RunControl")
            assert control["supervision"] == "owned" and control["decisionHeadId"] == head, (control["supervision"], control["decisionHeadId"])
            tree, targets = workers(first, 0)
            print("PASS failures-launched case 1: run", run, "waits at person question", head, "under owned supervision, with",
                  len(tree), "worker processes in process groups", targets, flush=True)

            # Case 2. SIGSTOP of the worker process groups, then SIGKILL of
            # the manager process. Darwin's waitid also reports a stopped
            # child for WEXITED, and the group monitor of the manager must
            # not read that report as an exit and kill the stopped group, so
            # the harness waits for many monitor polls before the kill. The
            # frontend proxy and the inner frontend worker each lead their
            # own session, so the death of the manager orphans no process
            # group of its session and the kernel sends them no signal.
            # Every worker process stays, stopped, and the inner worker
            # keeps the owner lock.
            listing = subprocess.run(["ps", "-Ao", "pid=,ppid="], stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                     text=True, timeout=10, check=True).stdout
            children = {int(pid) for pid, parent in (line.split() for line in listing.splitlines()) if int(parent) == first.pid}
            proxies = sorted({pgid for pid, pgid, _ in tree if pid in children})
            assert proxies and set(proxies) != set(targets), ("the proxy group and the inner worker session", proxies, tree)
            for group in targets:
                os.killpg(group, signal.SIGSTOP)
            deadline = time.monotonic() + 10
            while not all(halted for _, halted in stopped(targets)):
                assert time.monotonic() < deadline, ("the worker processes did not stop", stopped(targets))
                time.sleep(0.05)
            time.sleep(1)
            held = stopped(targets)
            assert sorted(pid for pid, _ in held) == sorted(pid for pid, _, _ in tree) and all(halted for _, halted in held), (
                "the stopped worker processes before the manager loss", held, tree)
            first.kill()
            first.wait(timeout=25)
            time.sleep(1)
            held = stopped(targets)
            assert sorted(pid for pid, _ in held) == sorted(pid for pid, _, _ in tree) and all(halted for _, halted in held), (
                "the stopped worker processes after the manager loss", held, proxies, tree)
        finally:
            ended(first, 0, True)
        assert first.returncode == -signal.SIGKILL, ("the first lifetime did not end by SIGKILL", first.returncode)
        native_runs = {native for (native,) in read_store("SELECT native_run_id FROM runs WHERE id=?", (run,))}
        assert len(native_runs) == 1, ("native run of the lost run", native_runs)
        lost_store = work / "manager" / "runs" / "runs" / native_runs.pop() / "runtime"
        assert (lost_store.parent / "owner.lock").is_file(), ("the owner lock of the lost run", lost_store.parent)

        def terminal_events():
            return [line for line in (lost_store / "events.ndjson").read_bytes().splitlines()
                    if json.loads(line)["event"]["type"] in ("run.completed", "run.failed", "run.cancelled")]
        assert not terminal_events(), ("the run log of the stopped run holds a terminal record", terminal_events())
        print("PASS failures-launched case 2: after SIGSTOP of process groups", targets, "the manager kept them for one second,",
              "and after SIGKILL of the manager all", len(held), "worker processes, with proxy group", proxies,
              ", remain stopped and the run log of", run, "holds no terminal record", flush=True)
        lost_reservations = [ident for (ident,) in read_store(
            "SELECT id FROM reservations WHERE request_id=? AND state!='released'", (lost_request["id"],))]
        assert len(lost_reservations) == 1, ("the reservation of the lost run", lost_reservations)
        quarantine = lost_reservations[0]

        second = serve(1)
        try:
            # Case 3. The restart quarantines the reservation of the lost run.
            # A new request waits with capacity. While the stopped inner
            # worker holds the owner lock, check-quarantine reports
            # cleanup-required, and a release refuses with cleanup-unverified,
            # without a change.
            status, capabilities, raw = request("/v1/capabilities", authorized)
            assert status == 200
            validate("Capabilities", capabilities, raw)
            client = mixed_client(capabilities, authorized)
            observed, wait_for, _, _ = client
            generation = lifetime_notice()["processGeneration"]
            assert read_store("SELECT state FROM reservations WHERE id=?", (quarantine,)) == [("quarantined",)], (
                "the reservation of the lost run after the restart", read_store("SELECT state FROM reservations WHERE id=?", (quarantine,)))
            value, _, _ = observed("/v1/runs/" + run, "Run")
            assert value["supervision"] == "lost", ("the lost run", value["supervision"])
            workflow, create = mixed_workflow("profile_1")
            waiting = create_request(epoch, create)
            enqueue_mixed(waiting, workflow, client)
            current, _, _ = wait_for(waiting["links"]["self"], "Request", lambda value: value["admission"]["reasons"] == ["capacity"])
            assert current["phase"] == "queued" and current["preparationId"] is None, ("queued request", current["phase"], current["preparationId"])
            facts = {"evidence": "owner-released", "reservationId": quarantine, "runId": run, "processGeneration": generation}
            digest = canonical_digest(facts)
            (required, refusals), same = unchanged(lambda: (
                administration({"version": 1, "operation": "check-quarantine", "quarantineId": quarantine})["result"],
                [release(quarantine, "cleanup_" + digest[:32], digest, refused="cleanup-unverified"),
                 release(quarantine, "cleanup_" + digest[:32], "0" * 64, refused="cleanup-unverified")]))
            assert same, "check-quarantine or a refused release changed the database or the manager log while the owner lock was held"
            assert required == {"quarantineId": quarantine, "state": "cleanup-required", "cleanupEvidenceId": None,
                                "cleanupEvidenceDigest": None, "processGeneration": generation, "expiresAt": None}, (
                "check-quarantine while the owner lock is held", required)
            current, _, _ = observed(waiting["links"]["self"], "Request")
            assert current["phase"] == "queued" and current["admission"]["reasons"] == ["capacity"], (
                "the request left the queue after a refused release", current["phase"], current["admission"])
            print("PASS failures-launched case 3: while the stopped worker holds the owner lock, check-quarantine of", quarantine,
                  "reports cleanup-required and release-quarantine refuses with cleanup-unverified for the owner-released",
                  "digest and for a wrong digest, without a change, and request", waiting["id"], "waits with capacity", flush=True)

            # Case 4. SIGKILL of the stopped worker process groups. Once no
            # process of them remains, the run log still holds no terminal
            # record.
            for group in targets:
                os.killpg(group, signal.SIGKILL)
            gone_after = vanished(targets, 1)
            assert not terminal_events(), ("the run log of the killed run holds a terminal record", terminal_events())
            print("PASS failures-launched case 4: after SIGKILL of the stopped process groups", targets, "no process remained after",
                  round(gone_after, 2), "seconds, and the run log of", run, "holds no terminal record", flush=True)

            # Case 5. check-quarantine reports clean with the owner-released
            # evidence. The release with it frees the capacity, and the queued
            # request reaches review without another client command and
            # completes.
            _, second_run = release_and_run(epoch, client, quarantine, facts, "5", queued=(waiting, workflow))
            value, _, _ = observed("/v1/runs/" + run, "Run")
            assert value["supervision"] == "lost", ("the lost run after the release", value["supervision"])
            assert not terminal_events(), "the release changed the run store of the lost run"
        finally:
            ended(second, 1, False)
        print("PASS failures-launched: the launched quarantine of run", run, "was released with owner-released evidence once its",
              "stopped worker processes were gone, and run", second_run, "completed with one execution reservation", flush=True)

    if launched_failure_mode:
        return launched_release()

    # The first lifetime.
    first = serve(0)
    try:
        status, capabilities, raw = request("/v1/capabilities", authorized)
        assert status == 200
        validate("Capabilities", capabilities, raw)
        epoch = capabilities["authorityEpoch"]
        attempts = []
        client = mixed_client(capabilities, authorized, attempts)
        observed, wait_for, mutate, _ = client
        workflow, create = mixed_workflow("profile_1")

        # Case 1. A run waits at its person question with a live worker, and
        # a withdrawn padding request takes the manager log above the byte
        # trigger of the pruner.
        lost_request = create_request(epoch, create)
        _, run = approve_mixed(lost_request, workflow, client)
        base = "/v1/runs/" + run
        head, _, _ = drive_mixed(run, client, stop_at_question=True, overview=False)
        control, _, _ = observed(base + "/control", "RunControl")
        assert control["supervision"] == "owned" and control["decisionHeadId"] == head, (control["supervision"], control["decisionHeadId"])
        padding = create_request(epoch, create)
        padding_uri = padding["links"]["self"]
        # Each literal replaces the previous one, so that the request view
        # stays within its one-MiB bound, while each command record keeps its
        # own claim check.
        for letter in "abc":
            current, tag, _ = observed(padding_uri, "Request")
            mutate(padding_uri, {"operation": "set-input", "input": {"name": workflow["inputs"][0]["name"],
                "source": "literal", "value": letter * 900000}}, tag)
        current, tag, _ = observed(padding_uri, "Request")
        mutate(padding_uri, {"operation": "withdraw"}, tag)
        current, _, _ = observed(padding_uri, "Request")
        assert current["phase"] == "withdrawn", ("padding request phase", current["phase"])
        assert not (flow_dir / "sealed").exists(), ("the first lifetime sealed a segment", sorted((flow_dir / "sealed").rglob("*")))
        before_kill = log_bytes()
        assert before_kill > half, ("the manager log does not reach the byte trigger", before_kill, half)
        tree, targets = workers(first, 0)
        print("PASS failures-manager case 1: run", run, "waits at person question", head, "under owned supervision, with",
              len(tree), "worker processes in process groups", targets, "and the manager log holds", before_kill,
              "bytes above the byte trigger", half, flush=True)

        # Case 2. SIGKILL of the manager process.
        stopped_after = kill(first, targets, 0)
    finally:
        ended(first, 0, True)
    assert first.returncode == -signal.SIGKILL, ("the first lifetime did not end by SIGKILL", first.returncode)
    # The run store of the lost run, by the native run identity of the Store.
    native_runs = {native for (native,) in read_store("SELECT native_run_id FROM runs WHERE id=?", (run,))}
    assert len(native_runs) == 1, ("native run of the lost run", native_runs)
    lost_store = work / "manager" / "runs" / "runs" / native_runs.pop() / "runtime"
    initial_stores = sorted(work.glob("manager/runs/runs/*/runtime"))
    assert initial_stores == [lost_store], ("run stores after the manager loss", initial_stores)
    assert len(run_starts(lost_store)) == 1 and len(start_relays(run)) == 1, ("starts of the lost run", len(run_starts(lost_store)), len(start_relays(run)))
    print("PASS failures-manager case 2: after SIGKILL of the manager, no process of the worker groups", targets, "remains after",
          round(stopped_after, 2), "seconds", flush=True)

    # Case 3. While no manager runs, seal the manager log in two segments as
    # the writer seals it: the records of the lost run, then the padding.
    actives = sorted(flow_dir.glob("*.ndjson"))
    assert len(actives) == 1, ("manager logs after the first lifetime", actives)
    active = actives[0]
    stream = active.name[:-len(".ndjson")]
    raw_lines = active.read_bytes().splitlines(keepends=True)
    assert raw_lines and all(line.endswith(b"\n") for line in raw_lines), "the first lifetime left a torn manager log"
    records = [json.loads(line) for line in raw_lines]
    first_lifetime = records[0]
    assert first_lifetime["schema"] == "notice" and first_lifetime["body"]["inline"]["notice"] == "lifetime", ("first record", first_lifetime["schema"])
    assert not [record for record in records if record["schema"] == "notice" and record["body"]["inline"]["notice"] == "shutdown"], (
        "the killed lifetime wrote a shutdown notice")
    split = next(index for index, record in enumerate(records) if record["about"].get("request") == padding["id"])
    # A crash after the COMMIT of the padding withdrawal and before its
    # receipt leaves its command ask without a reply, and a crash after the
    # command record of a further command and before its COMMIT leaves an ask
    # whose command has no ledger row. The harness truncates the log after the
    # withdrawal ask and appends such an ask, a copy of the withdrawal ask
    # with a fresh command identifier.
    withdrawal = next(item[5] for item in attempts if item[0] == "withdraw")
    withdraw_at = next(index for index, record in enumerate(records)
                       if record["schema"] == "command" and record["about"].get("command") == withdrawal["id"])
    assert split < withdraw_at and all(names(record, {padding["id"], withdrawal["id"]}) for record in records[withdraw_at + 1:]), (
        "a record after the withdrawal ask names other work", [record["schema"] for record in records[withdraw_at + 1:]])
    rolled_id = "command_" + secrets.token_hex(24)
    assert len(rolled_id) == len(withdrawal["id"]) and raw_lines[withdraw_at].count(withdrawal["id"].encode()) == 1
    raw_lines = raw_lines[:withdraw_at + 1] + [raw_lines[withdraw_at].replace(withdrawal["id"].encode(), rolled_id.encode())]
    records = [json.loads(line) for line in raw_lines]
    rolled_at = len(raw_lines) - 1
    ledger_before = dict(read_store("SELECT id,state FROM commands"))
    assert withdrawal["id"] in ledger_before and rolled_id not in ledger_before, "the ledger rows of the orphaned asks"
    lost_identities = {lost_request["id"], run}
    assert any(names(record, lost_identities) for record in records[:split]), "the first segment names no record of the lost run"
    assert not [index for index, record in enumerate(records) if index >= split and names(record, lost_identities)], (
        "a record of the lost run follows the padding")
    sealed_dir = flow_dir / "sealed" / stream
    sealed_dir.parent.mkdir(mode=0o700, exist_ok=True)
    sealed_dir.mkdir(mode=0o700)
    for start, end in ((0, split), (split, len(raw_lines))):
        segment = sealed_dir / ("%020d.ndjson" % start)
        segment.write_bytes(b"".join(raw_lines[start:end]))
        segment.chmod(0o600)
    active.unlink()
    sealed_bytes = log_bytes()
    assert sealed_bytes > half, ("the sealed manager log does not reach the byte trigger", sealed_bytes, half)
    print("PASS failures-manager case 3: the manager log of the killed lifetime has no shutdown notice and is sealed at",
          split, "of", len(records), "records, with", sealed_bytes, "bytes above the byte trigger", half,
          "; the withdrawal ask at", withdraw_at, "and the ask at", rolled_at, "without a ledger row have no reply", flush=True)

    lost_reservations = [ident for (ident,) in read_store(
        "SELECT id FROM reservations WHERE request_id=? AND state!='released'", (lost_request["id"],))]
    assert len(lost_reservations) == 1, ("the reservation of the lost run", lost_reservations)

    # The second lifetime.
    second = serve(1)
    try:
        # Case 4. The new lifetime begins with its lifetime notice and
        # reconciliation counts, and answers each orphaned command ask of the
        # killed lifetime: the withdrawal with its current receipt and the
        # ask without a ledger row with lifetime-ended. No command executes
        # again. A lost run is terminal for pruning, so the pruning round at
        # open removes the segment of the lost run and moves the floor.
        status, capabilities, raw = request("/v1/capabilities", authorized)
        assert status == 200
        validate("Capabilities", capabilities, raw)
        client = mixed_client(capabilities, authorized)
        observed, wait_for, mutate, _ = client
        actives = sorted(flow_dir.glob("*.ndjson"))
        assert actives == [active], ("manager logs of the second lifetime", actives)
        body = lifetime_notice()
        generation = body["processGeneration"]
        reconciliation = body["reconciliation"]
        assert generation != first_lifetime["body"]["inline"]["processGeneration"], ("the second lifetime notice", generation)
        # The owned run becomes lost, its dispatch-attempted approval becomes
        # unresolved, and its reservation is quarantined. Nothing else changes.
        assert reconciliation == {"preparations": 0, "requests": 0, "runs": 1, "commands": 1, "reservations": 1,
                                  "observations": 0, "uploads": 0}, ("the reconciliation counts of the second lifetime", reconciliation)
        starts = sorted(int(path.name[:20]) for path in sealed_dir.glob("*.ndjson"))
        assert starts == [split], ("the pruning round at open kept the segment of the lost run", starts)
        assert positioned()[0][0] == split and not start_relays(run), ("the floor after the pruning round at open", positioned()[0][0])
        ledger_after = dict(read_store("SELECT id,state FROM commands"))
        changed = {ident for ident in ledger_after if ledger_after[ident] != ledger_before.get(ident)}
        assert ledger_after.keys() == ledger_before.keys() and len(changed) == 1 and ledger_after[changed.pop()] == "unresolved", (
            "the restart executed or changed a command beyond the reconciliation", ledger_before, ledger_after)
        current_withdrawal, _, _ = observed(withdrawal["links"]["self"], "CommandReceipt")
        credential_sender = records[withdraw_at]["from"]
        answered = orphan_replies({
            withdraw_at: (credential_sender, "receipt", current_withdrawal),
            rolled_at: (credential_sender, "failure", {"class": "refused", "message": "lifetime-ended"})})
        print("PASS failures-manager case 4: the second lifetime begins with lifetime notice", generation,
              "and reconciliation counts", reconciliation, "; it answers the orphaned asks at", answered,
              "with the receipt that GET returns and with lifetime-ended, executes no command again,",
              "and the pruning round at open removes the segment of the lost run and keeps", starts, flush=True)

        # Case 4a. status through the live channel reports the serving
        # lifetime and the quarantined reservation, without a change.
        status_value, same = unchanged(lambda: administration({"version": 1, "operation": "status"})["result"])
        assert same, "status changed the database or the manager log"
        assert status_value["state"] == "serving" and status_value["processGeneration"] == generation, ("status of the second lifetime", status_value)
        assert status_value["activeReservations"] == 1, ("active reservations after the restart", status_value)
        print("PASS failures-manager case 4a: status reports", status_value["state"], "with", status_value["activeReservations"],
              "active reservation, without a database change or a manager-log append", flush=True)

        # Case 5. The run shows lost supervision, and no start is dispatched
        # again.
        value, _, raw = observed(base, "Run")
        (work / "lost-run.json").write_bytes(raw)
        assert value["supervision"] == "lost" and "lost-supervision" in value["limitations"], (
            "lost run", value["supervision"], value["limitations"])
        assert value["runtime"] is None or value["runtime"]["status"] != "succeeded", ("lost run runtime", value["runtime"])
        assert value["verification"]["state"] != "verified", ("lost run verification", value["verification"])
        control, _, raw = observed(base + "/control", "RunControl")
        (work / "lost-control.json").write_bytes(raw)
        assert control["supervision"] == "lost" and not control["cancelAllowed"], ("lost run control", control["supervision"], control["cancelAllowed"])
        assert sorted(work.glob("manager/runs/runs/*/runtime")) == initial_stores, "a run store appeared after the restart"
        assert len(run_starts(lost_store)) == 1 and not start_relays(run), ("starts of the lost run after the restart",
            len(run_starts(lost_store)), len(start_relays(run)))
        print("PASS failures-manager case 5: run", run, "shows lost supervision with runtime", value["runtime"] and value["runtime"]["status"],
              "and verification", value["verification"]["state"], "; its store holds one run start and the retained manager log no new start relay", flush=True)

        # Case 6. An exact replay of an earlier command returns the receipt
        # of its first response. The approval of the lost run is unresolved,
        # and its replay dispatches no start.
        replays = []
        for operation in ("enqueue", "approve"):
            _, path, headers, payload, receipt_uri, original = next(item for item in attempts if item[0] == operation)
            status, replayed, raw, _ = exchange(path, headers, method="POST", payload=payload)
            assert status == 202, ("exact replay after the restart", operation, status, replayed.get("code"))
            validate("CommandReceipt", replayed, raw)
            assert replayed == original and replayed["links"]["self"] == receipt_uri, (
                "the replay receipt differs from the original receipt", operation, replayed, original)
            current, _, _ = observed(receipt_uri, "CommandReceipt")
            replays.append((operation, original["id"], original["state"], current["state"]))
        assert replays[1][3] == "unresolved", ("the approval of the lost run", replays[1])
        assert sorted(work.glob("manager/runs/runs/*/runtime")) == initial_stores and not start_relays(run), (
            "the replay of the approval dispatched a start")
        print("PASS failures-manager case 6: exact replays returned the original receipts (operation, command, original state,",
              "current state)", replays, "and the replay of the unresolved approval dispatched no start", flush=True)

        # Case 7. The quarantined reservation of the lost run holds the only
        # execution slot until the operator releases it with the evidence of
        # its terminal record: the first event record of the run log whose
        # event ends the run.
        events = {json.loads(line)["sequence"]: json.loads(line)["event"]["type"]
                  for line in (lost_store / "events.ndjson").read_bytes().splitlines()}
        run_log = (lost_store / "flow.ndjson").read_bytes().splitlines()
        stop = next(index for index, line in enumerate(run_log) if json.loads(line)["schema"] == "event"
                    and events.get(str(json.loads(line)["body"]["event"])) in ("run.completed", "run.failed", "run.cancelled"))
        terminal_facts = {"evidence": "terminal-record", "reservationId": lost_reservations[0], "runId": run, "position": stop,
                          "recordSha256": hashlib.sha256(run_log[stop]).hexdigest(), "processGeneration": generation}
        _, second_run = release_and_run(epoch, client, lost_reservations[0], terminal_facts, "7")
        value, _, _ = observed(base, "Run")
        assert value["supervision"] == "lost", ("the lost run after the release", value["supervision"])
        assert len(run_starts(lost_store)) == 1 and not start_relays(run), "the lost run started again"

        # Case 8. A request waits in review with a live preparation when the
        # manager is killed again.
        workflow, create = mixed_workflow("profile_1")
        review_request = create_request(epoch, create)
        review_uri = review_request["links"]["self"]
        enqueue_mixed(review_request, workflow, client)
        current, _, _ = wait_for(review_uri, "Request", lambda value: value["preparationId"] is not None)
        review_preparation, _, _ = observed("/v1/preparations/" + current["preparationId"], "Preparation")
        assert current["phase"] == "review" and review_preparation["state"] == "live", (
            "request in review", current["phase"], review_preparation["state"])
        tree, targets = workers(second, 1)
        review_stopped = kill(second, targets, 1)
    finally:
        ended(second, 1, True)
    assert second.returncode == -signal.SIGKILL, ("the second lifetime did not end by SIGKILL", second.returncode)
    review_reservations = [ident for (ident,) in read_store(
        "SELECT id FROM reservations WHERE request_id=? AND state!='released'", (review_request["id"],))]
    assert len(review_reservations) == 1, ("the reservation of the request in review", review_reservations)
    review_natives = {native for (native,) in read_store("SELECT native_run_id FROM preparations WHERE request_id=?", (review_request["id"],))}
    # A crash after the command record of a release and before its receipt
    # leaves an administration ask without a reply. The harness appends two
    # such asks to the killed log: a copy of the committed release of the
    # second lifetime, whose reservation is released, and a copy that names
    # the reservation of the request in review, which no release committed.
    release_line = next(line for path in log_files() for line in path.read_bytes().splitlines()
                        if json.loads(line)["schema"] == "command"
                        and json.loads(line)["body"].get("inline", {}).get("quarantineId") == lost_reservations[0])
    uncertain_line = release_line.replace(lost_reservations[0].encode(), review_reservations[0].encode()).replace(
        lost_request["id"].encode(), review_request["id"].encode())
    assert release_line.count(lost_reservations[0].encode()) == 1 and release_line.count(lost_request["id"].encode()) == 1 \
        and len(uncertain_line) == len(release_line), "the release ask copies"
    active_bytes = active.read_bytes()
    assert active_bytes.endswith(b"\n"), "the second lifetime left a torn manager log"
    committed_at = positioned()[-1][0] + 1
    active.write_bytes(active_bytes + release_line + b"\n" + uncertain_line + b"\n")
    operator_sender = json.loads(release_line)["from"]
    print("PASS failures-manager case 8: request", review_request["id"], "waited in review with", len(tree),
          "worker processes in process groups", targets, "; after SIGKILL of the manager none remained after",
          round(review_stopped, 2), "seconds ; the release asks at", [committed_at, committed_at + 1], "have no reply", flush=True)

    # The approval of the completed run of the second lifetime has a
    # terminal observation of its run.
    (second_approval, second_terminal), = read_store(
        "SELECT s.command_id,u.terminal_observed FROM start_intents s JOIN runs u ON u.id=s.run_id WHERE s.run_id=?", (second_run,))
    assert second_terminal == 1, ("the completed run of the second lifetime has no terminal observation", second_run)
    ledger_before = {ident: (state, revision) for ident, state, revision in read_store("SELECT id,state,revision FROM commands")}
    assert ledger_before[second_approval][0] == "dispatch-attempted", ("the approval of the completed run", ledger_before[second_approval])

    # The third lifetime.
    third = serve(2)
    try:
        # Case 9. The restart invalidates the live preparation and the
        # prepared admission observation of the request in review, refuses
        # the request and quarantines its reservation, which never launched a
        # run. The approval of the completed run of the second lifetime stays
        # dispatch-attempted: a start command whose run has a terminal
        # observation is not reclassified, so the restart changes no command.
        # The operator releases the quarantine with its no-launch evidence,
        # and a new request runs.
        status, capabilities, raw = request("/v1/capabilities", authorized)
        assert status == 200
        validate("Capabilities", capabilities, raw)
        client = mixed_client(capabilities, authorized)
        observed, _, _, _ = client
        body = lifetime_notice()
        generation = body["processGeneration"]
        assert body["reconciliation"] == {"preparations": 1, "requests": 1, "runs": 0, "commands": 0, "reservations": 1,
                                          "observations": 1, "uploads": 0}, ("the reconciliation counts of the third lifetime", body["reconciliation"])
        ledger_after = {ident: (state, revision) for ident, state, revision in read_store("SELECT id,state,revision FROM commands")}
        assert ledger_after == ledger_before, ("the restart of the third lifetime changed a command", ledger_before, ledger_after)
        # The open answers the orphaned release asks: the committed release
        # with committed-receipt-lost and the other with outcome-uncertain.
        # Neither releases a reservation.
        released = orphan_replies({
            committed_at: (operator_sender, "failure", {"class": "refused", "message": "committed-receipt-lost"}),
            committed_at + 1: (operator_sender, "failure", {"class": "refused", "message": "outcome-uncertain"})})
        assert read_store("SELECT state FROM reservations WHERE id=?", (review_reservations[0],)) == [("quarantined",)], (
            "an orphaned release ask released a reservation")
        status_value = administration({"version": 1, "operation": "status"})["result"]
        assert status_value["processGeneration"] == generation and status_value["activeReservations"] == 1, ("status of the third lifetime", status_value)
        quarantine = review_reservations[0]
        (review_phase,), = read_store("SELECT phase FROM requests WHERE id=?", (review_request["id"],))
        no_launch_facts = {
            "evidence": "no-launch", "reservationId": quarantine, "requestId": review_request["id"], "requestPhase": review_phase,
            "preparationStates": [state for (state,) in read_store(
                "SELECT state FROM preparations WHERE reservation_id=? ORDER BY id", (quarantine,))],
            "admissionObservationState": next((state for (state,) in read_store(
                "SELECT state FROM admission_observations WHERE reservation_id=?", (quarantine,))), None),
            "resourceKeys": [[kind, key] for kind, key in read_store(
                "SELECT kind,resource_key FROM reservation_resources WHERE reservation_id=? ORDER BY kind,resource_key", (quarantine,))],
            "processGeneration": generation}
        assert review_phase == "refused" and no_launch_facts["resourceKeys"] == [["operator", "fixture_one"]], (
            "the facts of the request in review", no_launch_facts)
        _, third_run = release_and_run(epoch, client, quarantine, no_launch_facts, "9")
        value, _, _ = observed(base, "Run")
        assert value["supervision"] == "lost", ("the lost run in the third lifetime", value["supervision"])
        print("PASS failures-manager case 9a: the third lifetime answers the orphaned release asks at", released,
              "with committed-receipt-lost and outcome-uncertain and releases no reservation for them", flush=True)
    finally:
        ended(third, 2, False)

    # Case 10. The flow verb reports no undecided command, the retained
    # lifetimes before the third without their shutdown notices and the third
    # with it, the floor past the pruned segment of the lost run, the consent
    # of each retained start relay, and each release command with its one
    # reply: a receipt for the two releases that committed with their
    # receipts, and the failure of the two orphaned release asks. The run log
    # of the lost run ends with the stop that the worker wrote when its
    # control input closed.
    stores = [store for store in sorted(work.glob("manager/runs/runs/*/runtime")) if store.parent.name not in review_natives]
    assert len(stores) == 3 and lost_store in stores, ("run stores after the third lifetime", stores)
    retained = positioned()
    flow_status, flowed, summary = read_flow("manager-failure-flow", [flow_dir] + stores)
    assert flow_status == 2 and summary["verified"] and not summary["problems"], (
        "the flow verb does not verify the logs of the three lifetimes", flow_status, summary["problems"])
    assert summary["states"]["undecided"] == [], ("undecided commands after the restarts", summary["states"]["undecided"])
    manager_summary = next(item for item in summary["logs"] if item["kind"] == "manager")
    floor = retained[0][0]
    assert manager_summary["floor"] == floor and floor >= split, ("manager log floor", manager_summary["floor"], floor, split)
    lifetimes = summary["joins"]["lifetimes"]
    notices = [position for position, record in retained if record["schema"] == "notice" and record["body"]["inline"]["notice"] == "lifetime"]
    assert [item["lifetime"]["position"] for item in lifetimes] == notices and notices[0] > 0 and lifetimes[-1]["shutdown"] is not None \
        and all(item["shutdown"] is None for item in lifetimes[:-1]), ("lifetimes", lifetimes, notices)
    assert summary["states"]["lifetimeWithoutShutdown"] == [item["lifetime"] for item in lifetimes[:-1]], (
        "lost lifetimes", summary["states"]["lifetimeWithoutShutdown"])
    assert not summary["states"]["unresolvedDelivery"], ("unresolved deliveries", summary["states"]["unresolvedDelivery"])
    starts_flowed = [record for record in flowed if record["schema"] == "relay" and record["body"]["kind"] == "start"]
    assert starts_flowed and len(summary["consent"]) == len(starts_flowed) and all(item["verified"] for item in summary["consent"]), (
        "consent", summary["consent"])
    relays = [record for record in starts_flowed if record["about"].get("managerRun") == run]
    assert not relays, ("start relays of the lost run in the flow verb", len(relays))
    releases = [record for record in flowed if record["schema"] == "command" and record["body"].get("administration") == "release-quarantine"]
    orphaned_releases = {committed_at: "committed-receipt-lost", committed_at + 1: "outcome-uncertain"}
    assert [record["body"]["quarantineId"] for record in releases] == [lost_reservations[0], lost_reservations[0], quarantine, quarantine] \
        and [record["position"] for record in releases][1:3] == sorted(orphaned_releases), (
        "release commands in the flow verb", [(record["position"], record["body"]) for record in releases])
    for record in releases:
        replies = [reply for reply in flowed if reply.get("replyTo") == record["position"]]
        if record["position"] in orphaned_releases:
            assert len(replies) == 1 and replies[0]["schema"] == "failure" and replies[0]["body"] == {
                "class": "refused", "message": orphaned_releases[record["position"]]}, ("the reply to an orphaned release ask", record["position"], replies)
        else:
            assert len(replies) == 1 and replies[0]["schema"] == "receipt" and replies[0]["body"]["operation"] == "release-quarantine" \
                and replies[0]["body"]["result"] == {"quarantineId": record["body"]["quarantineId"], "state": "released"}, (
                "the receipt of a release command", record["position"], replies)
    lost_report = next(item["report"] for item in summary["logs"] if item["kind"] == "run" and item["log"] == str(lost_store))
    last_event = json.loads((lost_store / "events.ndjson").read_bytes().splitlines()[-1])["event"]
    assert lost_report["stop"] is not None and last_event["type"] == "run.cancelled", (
        "the run log of the lost run has no stop of its worker", lost_report["stop"], last_event["type"])
    print("PASS failures-manager case 10: the flow verb exits 2 with no undecided command and verifies", len(summary["consent"]),
          "retained consents; it reports lifetimes", [item["lifetime"]["position"] for item in lifetimes[:-1]],
          "without their shutdown notices and the third lifetime with shutdown notice", lifetimes[-1]["shutdown"],
          "; it decodes the release commands at", [record["position"] for record in releases],
          "each with its one reply; floor", floor, "past the pruned segment of the lost run, and its run log stops at", lost_report["stop"],
          "with", last_event["type"], repr(last_event.get("message")), flush=True)
    print("PASS failures-manager: every manager-loss and quarantine-release case held across three lifetimes of the TLS 1.3 manager",
          second_run, third_run, flush=True)


if manager_failure_mode or launched_failure_mode:
    manager_failure_checks()
    raise SystemExit(0)


def tui_failure_checks():
    """The tui-failures mode. See TUI_FAILURES for the steps."""
    import sqlite3
    harness = tui_fixture.harness

    def save(session, name):
        (work / ("tui-failures-" + name + ".screen.txt")).write_text(session.screen.text())

    def serve(index):
        """Start one foreground manager lifetime on the same root and
        configuration and wait for HTTPS readiness."""
        with (work / f"server-{index}.stdout").open("wb") as output, (work / f"server-{index}.stderr").open("wb") as errors:
            process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                        "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        wait_ready(process)
        return process

    def header(session):
        return " ".join(session.screen.lines()[:3])

    def own_processes(pid):
        """The processes other than pid whose parent is pid or whose process
        group is the group of pid. TuiSession starts the TUI as the leader of
        its own session and process group."""
        listed = subprocess.run(["ps", "-A", "-o", "pid=,ppid=,pgid="], stdout=subprocess.PIPE, check=True, timeout=10).stdout.decode()
        rows = [tuple(map(int, line.split())) for line in listed.splitlines() if line.strip()]
        return [row for row in rows if row[0] != pid and (row[1] == pid or row[2] == pid)]

    def still_running(run, head):
        """Read through the harness credential that the run still runs at its
        pending question under owned supervision."""
        snapshot, _, _ = observed("/v1/runs/" + run + "/snapshot", "RunSnapshot")
        control, _, _ = observed("/v1/runs/" + run + "/control", "RunControl")
        run_view, _, _ = observed("/v1/runs/" + run, "Run")
        assert snapshot["runtime"] is not None and snapshot["runtime"]["status"] == "running", ("the held run does not run", snapshot["runtime"])
        assert control["decisionHeadId"] == head and run_view["supervision"] == "owned", (
            "the held run left its question or its supervision", control["decisionHeadId"], run_view["supervision"])

    def open_run(session, run):
        """Open the held run from the Manager overview at its question."""
        focus_row(session, "run Running", "Run:" + run, 30)
        session.send(b"\r")
        session.wait_screen("Your answer", timeout=20)
        return session.wait_screen("Observation: current", timeout=20)

    def create_draft(chosen=None):
        """Create a draft of the mixed workflow, or of the given catalogue
        entry, through the harness credential."""
        chosen = chosen or workflow
        key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
        body = {"workflowId": chosen["id"], "descriptorRevision": chosen["revision"],
                "profileId": chosen["profileId"], "profileRevision": chosen["profileRevision"]}
        status, created, raw = request("/v1/requests", harness | {"Content-Type": "application/json", "Idempotency-Key": key},
                                       method="POST", payload=json.dumps(body, separators=(",", ":")).encode())
        assert status == 201, ("request creation", status, created.get("code"))
        validate("Request", created, raw)
        return created

    lifetimes = [serve(0)]
    try:
        status, capabilities, _ = request("/v1/capabilities", harness)
        assert status == 200
        status, catalogue, _ = request("/v1/workflows?profileId=profile_1", harness)
        assert status == 200
        workflow = next(item for item in catalogue["items"] if item["name"] == "mixed-controls")
        client = mixed_client(capabilities, harness)
        observed, wait_for, _, _ = client
        # The complete exact review of the mixed workflow fits at 140x36.
        with tui_fixture.session(rows=36, columns=140) as session:
            # 1. A held run is open in the TUI, and a second request waits
            # for the one execution reservation.
            held = create_draft()
            _, run = approve_mixed(held, workflow, client)
            head, _, _ = drive_mixed(run, client, stop_at_question=True, overview=False)
            queued = create_draft()
            enqueue_mixed(queued, workflow, client)
            wait_for(queued["links"]["self"], "Request", lambda value: value["phase"] == "queued" and value["admission"]["reasons"] == ["capacity"])
            session.wait_screen("Manager profiles")
            session.wait_screen("profile_1")
            session.send(b"\r")
            session.wait_screen("Manager workflows")
            session.send(b"O")
            session.wait_screen("Manager overview")
            focus_row(session, "request queued 1 of 1", "Request:" + queued["id"], 20)
            focus_row(session, "run Running", "Run:" + run, 20)
            session.send(b"\r")
            session.wait_screen("Your answer", timeout=20)
            screen = session.wait_screen("Observation: current", timeout=20)
            save(session, "held")
            assert "Runtime: Running" in screen and "supervision" not in screen, "the held run is not shown running under owned supervision"
            print("PASS tui-failures 1: the TUI shows run", run, "at its question", head, "with the current observation, and request",
                  queued["id"], "is queued with capacity behind it", flush=True)
            # 2. SIGKILL of the manager.
            commands_before = command_ids()
            lifetimes[0].kill()
            lifetimes[0].wait(timeout=25)
            assert lifetimes[0].returncode == -signal.SIGKILL, ("the first lifetime did not end by SIGKILL", lifetimes[0].returncode)
            killed_at = time.monotonic()
            session.wait_screen("manager unreachable since", timeout=20)
            elapsed = time.monotonic() - killed_at
            screen = session.wait_screen("Observation: stale (", timeout=10)
            save(session, "unreachable")
            assert "manager unreachable since" in header(session), ("the header lacks the unreachable state", header(session))
            for line in ("Your answer", "Runtime: Running", "the last complete observation is retained"):
                assert squeeze(line) in squeeze(screen), ("the unreachable TUI lost a line of the held run", line)
            assert not any(word in screen for word in ("Succeeded", "Cancelled", "Terminal:")), "the unreachable TUI invented an ending"
            print("PASS tui-failures 2: after SIGKILL of the manager the header shows the unreachable state after", f"{elapsed:.2f}",
                  "seconds, and the live monitor keeps the question and the last observation of run", run, "marked stale", flush=True)
            # 3. A new lifetime on the same root. The TUI reconnects without
            # a key press and shows the run of the earlier lifetime as lost.
            time.sleep(2)
            lifetimes.append(serve(1))
            started_at = time.monotonic()
            while True:
                screen = session.screen.text()
                if "manager unreachable" not in screen and "Observation: current" in screen and "supervision lost" in screen:
                    break
                assert time.monotonic() < started_at + 30, ("the TUI did not reconnect", screen)
                session.pump(0.1)
            reconnected = time.monotonic() - started_at
            while not re.search(r"delivery (live|polling)", header(session)):
                assert time.monotonic() < started_at + 60, ("the event worker did not reconnect", header(session))
                session.pump(0.1)
            screen = session.screen.text()
            save(session, "reconnected")
            lost, _, raw = observed("/v1/runs/" + run + "/snapshot", "RunSnapshot")
            (work / "tui-failures-lost-snapshot.json").write_bytes(raw)
            run_view, _, _ = observed("/v1/runs/" + run, "Run")
            assert run_view["supervision"] == "lost", ("the run of the earlier lifetime", run_view["supervision"])
            published = lost["runtime"]["status"] if lost["runtime"] is not None else None
            shown = RUNTIME_LINE.search(screen)
            assert published != "succeeded" and "Succeeded" not in screen, "the run of the earlier lifetime is shown as completed"
            assert (shown is None and published is None and "Runtime: not yet observed; supervision lost" in screen) or (
                shown is not None and LABEL_STATUS[shown.group(1)] == published and squeeze(shown.group(0) + "; supervision lost") in squeeze(screen)), (
                "the live monitor does not show the runtime status of the snapshot", published, screen)
            assert command_ids() == commands_before, "a command was added while the manager was lost or after its restart"
            print("PASS tui-failures 3: without a key press the TUI left the unreachable state", f"{reconnected:.2f}",
                  "seconds after the restart, the header shows", re.search(r"delivery (live|polling)", header(session)).group(0),
                  ", run", run, "shows lost supervision with the runtime status", published, "of its snapshot,",
                  "and no command was added", flush=True)
            # 4. The operator releases the quarantined reservation. The queued
            # request reaches review, the TUI approves it, and its run
            # completes in the live monitor.
            checked = administration({"version": 1, "operation": "check-store"})["result"]
            assert checked["integrity"] == "valid" and len(checked["quarantineIds"]) == 1, ("check-store", checked)
            quarantine = checked["quarantineIds"][0]
            evidence = administration({"version": 1, "operation": "check-quarantine", "quarantineId": quarantine})["result"]
            assert evidence["state"] == "clean", ("check-quarantine", evidence)
            released = administration({"version": 1, "operation": "release-quarantine", "quarantineId": quarantine,
                                       "cleanupEvidenceId": evidence["cleanupEvidenceId"],
                                       "cleanupEvidenceDigest": evidence["cleanupEvidenceDigest"]})["result"]
            assert released == {"quarantineId": quarantine, "state": "released"}, ("release-quarantine", released)
            session.send(b"\x1b")
            session.wait_screen("Manager overview", timeout=10)
            focus_row(session, "request review", "Request:" + queued["id"], 30)
            save(session, "review-row")
            session.send(b"\r")
            session.wait_screen("Approve exact manager review", timeout=45)
            save(session, "review")
            mutation_key(session, b"y", "Approval receipt:", 60)
            associated, _, _ = wait_for(queued["links"]["self"], "Request", lambda value: value["runId"] is not None)
            second_run = associated["runId"]
            _, answered, recovered = drive_mixed(second_run, client, overview=False)
            assert answered and recovered, ("decisions of the new run", answered, recovered)
            artifact = verified_download(second_run, client, harness)
            screen = session.wait_screen("Result: verified", timeout=60)
            save(session, "completed")
            assert "Runtime: Succeeded" in screen and squeeze("Run: " + second_run) in squeeze(screen), "the live monitor does not show the completed run"
            assert squeeze("Result SHA-256: " + artifact["sha256"]) in squeeze(screen), "the TUI result digest differs from the harness download"
            print("PASS tui-failures 4: after release-quarantine of", quarantine, "request", queued["id"], "reached review without a",
                  "client command, the TUI approved it, and run", second_run, "succeeded in the live monitor with verified result", artifact["id"], flush=True)
            # The restart published a new profile revision, so the catalogue
            # is read again.
            status, catalogue, _ = request("/v1/workflows?profileId=profile_1", harness)
            assert status == 200
            current = next(item for item in catalogue["items"] if item["name"] == "mixed-controls")
            # 5. A stale answer receives 412 and keeps its draft.
            structured = next(item for item in catalogue["items"] if item["name"] == "structured-person")
            stores_before = set(work.glob("manager/runs/runs/*/runtime"))
            _, stale_run = approve_mixed(create_draft(structured), structured, client)
            control, _, _ = wait_for("/v1/runs/" + stale_run + "/control", "RunControl", lambda value: value["decisionHeadId"] is not None)
            first = control["decisionHeadId"]
            stores = sorted(set(work.glob("manager/runs/runs/*/runtime")) - stores_before)
            assert len(stores) == 1, ("the run store of the structured run", stale_run, stores)
            session.send(b"\x1b")
            session.wait_screen("Manager overview", timeout=10)
            focus_row(session, "run Running", "Run:" + stale_run, 30)
            session.send(b"\r")
            session.wait_screen("Your answer", timeout=20)
            session.wait_screen("structured JSON {\"notes\": [string], \"ok\": boolean}", timeout=20)
            draft = '{"ok": true, "notes": ["kept draft"]}'
            session.send(draft.encode())
            session.wait_screen(draft, timeout=10)
            head, tag, _ = observed("/v1/decisions/" + first, "Decision")
            theirs = {"ok": False, "notes": ["harness answer"]}
            body = {"operation": "answer", "occurrenceId": head["address"]["occurrenceId"], "generation": head["generation"], "value": theirs}
            if stale_control:
                # The control lets the TUI answer first. Its answer is
                # delivered, and the later harness answer receives 412.
                mutation_key(session, b"\x04", "Request 2 \u00b7 structured JSON", 30)
                wait_for("/v1/runs/" + stale_run + "/control", "RunControl", lambda value: value["decisionHeadId"] not in (None, first))
                key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
                status, problem, _, _ = exchange("/v1/decisions/" + first, harness | {
                    "Content-Type": "application/json", "Idempotency-Key": key, "If-Match": tag},
                    method="POST", payload=json.dumps(body, separators=(",", ":")).encode())
                assert status == 412 and problem["code"] == "stale-revision", ("the late harness answer", status, problem.get("code"))
            else:
                os.kill(session.process.pid, signal.SIGSTOP)
                try:
                    client[2]("/v1/decisions/" + first, body, tag)
                    session.send(b"\x04")
                finally:
                    os.kill(session.process.pid, signal.SIGCONT)
            refused = "answer refused: 412 stale-revision; decision changed; draft kept"
            deadline = time.monotonic() + 20
            while squeeze(refused) not in squeeze(session.screen.text()):
                assert time.monotonic() < deadline, STALE_KEPT_DRAFT
                session.pump(0.1)
            save(session, "stale-refused")
            control, _, _ = wait_for("/v1/runs/" + stale_run + "/control", "RunControl", lambda value: value["decisionHeadId"] not in (None, first))
            second = control["decisionHeadId"]
            screen = session.wait_screen("Request 2 \u00b7 structured JSON", timeout=20)
            assert draft in screen, ("the second question does not show the kept draft", screen)
            save(session, "stale-kept")
            time.sleep(2)
            waiting, _, _ = observed("/v1/decisions/" + second, "Decision")
            assert waiting["state"] == "pending", ("the TUI sent the kept draft by itself", waiting["state"])
            recorded = [record["answer"] for record in json.loads((stores[0] / "answers.json").read_bytes())["answers"]]
            assert recorded == [theirs], ("the stale TUI answer reached the run", recorded)
            mutation_key(session, b"\x04", "Runtime: Succeeded", 60)
            snapshot, _, _ = wait_for("/v1/runs/" + stale_run + "/snapshot", "RunSnapshot",
                                      lambda value: value["runtime"] is not None and value["runtime"]["status"] in ("succeeded", "failed", "cancelled"))
            save(session, "stale-sent")
            assert snapshot["runtime"]["status"] == "succeeded", ("structured run terminal status", snapshot["runtime"]["status"])
            recorded = {record["occurrenceId"]: record["answer"] for record in json.loads((stores[0] / "answers.json").read_bytes())["answers"]}
            assert recorded == {"0": theirs, "1": json.loads(draft)}, ("structured recorded answers by occurrence", recorded)
            print("PASS tui-failures 5: the TUI answer to decision", first, "of run", stale_run, "after the harness answer received 412",
                  "stale-revision, the draft moved to decision", second, "without a send, and Ctrl-D sent it, so the run recorded", recorded, flush=True)
            # 6. A held run is open in the TUI when the harness revokes the
            # TUI credential.
            third = create_draft(current)
            _, held_run = approve_mixed(third, current, client)
            held_head, _, _ = drive_mixed(held_run, client, stop_at_question=True, overview=False)
            session.send(b"\x1b")
            session.wait_screen("Manager overview", timeout=10)
            open_run(session, held_run)
            assert not own_processes(session.process.pid), ("the service TUI owns a process", own_processes(session.process.pid))
            commands_before = command_ids()
            administration({"version": 1, "operation": "revoke-credential", "credentialId": tui_fixture.credential_ids["tui"]})
            revoked_at = time.monotonic()
            while "credential refused" not in header(session):
                assert time.monotonic() < revoked_at + 30, ("the TUI did not show the refused credential", session.screen.text())
                session.pump(0.1)
            refused_after = time.monotonic() - revoked_at
            session.settle()
            screen = session.screen.text()
            save(session, "credential-refused")
            assert squeeze("credential refused: no mutation or automatic refresh starts; g reads again") in squeeze(screen), (
                "the status line does not name the refused credential", screen)
            assert "Your answer" in screen and not any(word in screen for word in ("Succeeded", "Cancelled", "Terminal:")), (
                "the refused TUI lost the held run or invented an ending", screen)
            session.send(b"false")
            session.settle()
            session.send(b"\x04")
            session.wait_screen("answer did not start:", timeout=10)
            assert re.search(r"Key \d+: answer did not start: (the credential was refused|the decision observation is stale)\.", session.screen.text()), (
                "Ctrl-D did not refuse the answer", session.screen.text())
            session.send(b"\x1b")
            session.wait_screen("Manager overview", timeout=10)
            session.send(b"\x1b")
            session.wait_screen("Manager workflows", timeout=10)
            session.send(b"\r")
            session.wait_screen("create did not start: the credential was refused.", timeout=10)
            save(session, "credential-refused-create")
            still_running(held_run, held_head)
            assert command_ids() == commands_before, "the TUI sent a command after its credential was refused"
            tui_pid = session.process.pid
            assert not own_processes(tui_pid), ("the service TUI owns a process", own_processes(tui_pid))
            session.send(b"q")
            assert session.wait_exit(20) == 0
            session.assert_restored()
            assert not own_processes(tui_pid), ("a process of the quit TUI remains", own_processes(tui_pid))
            still_running(held_run, held_head)
            print("PASS tui-failures 6: after revocation of the TUI credential the header showed credential refused after", f"{refused_after:.2f}",
                  "seconds, Ctrl-D and Enter started nothing, no command was added, run", held_run, "still runs at question", held_head,
                  "and q quit the TUI with no child process", flush=True)
        # 7. A second TUI session with a new credential quits with Ctrl-C
        # while the held run is open.
        renewed = tui_fixture.renew("tui-renewed")
        with tui_fixture.session(rows=36, columns=140, client_profile=renewed) as session:
            session.wait_screen("Manager profiles")
            session.wait_screen("profile_1")
            session.send(b"\r")
            session.wait_screen("Manager workflows")
            session.send(b"O")
            session.wait_screen("Manager overview")
            open_run(session, held_run)
            save(session, "renewed-held")
            tui_pid = session.process.pid
            assert not own_processes(tui_pid), ("the service TUI owns a process", own_processes(tui_pid))
            session.send(b"\x03")
            assert session.wait_exit(20) == 0
            session.assert_restored()
            assert not own_processes(tui_pid), ("a process of the quit TUI remains", own_processes(tui_pid))
            still_running(held_run, held_head)
            print("PASS tui-failures 7: a second TUI session with a new credential opened run", held_run, "and quit with Ctrl-C;",
                  "no process of the TUI remains, and the run still runs at question", held_head, flush=True)
        # 8. During the delay window of the forwarder the TUI switches from
        # the forwarder profile to the direct profile, and no late response
        # of the earlier endpoint appears.
        forwarder = DelayForwarder(forward_listener, port, FORWARD_DELAY)
        direct = tui_fixture.renew("tui-delay")
        forwarded = work / "client-profile-forward.json"
        forwarded.write_text(json.dumps(dict(json.loads(direct.read_text()),
                                             endpoint=f"https://127.0.0.1:{forward_listener.getsockname()[1]}/v1")))
        forwarded.chmod(0o600)
        withdrawn = create_draft(current)
        with tui_fixture.session(rows=36, columns=140, client_profiles=[forwarded, direct]) as session:
            session.wait_screen("Manager profiles")
            session.wait_screen("profile_1")
            session.send(b"E")
            screen = session.wait_screen("Manager endpoints")
            assert f"> 1. active  {forwarded}" in screen and f"  2. not connected  {direct}" in screen, (
                "the forwarder profile is not the active endpoint", screen)
            session.send(b"\x1b")
            session.wait_screen("Manager profiles")
            session.send(b"\r")
            session.wait_screen("Manager workflows")
            session.send(b"O")
            session.wait_screen("Manager overview")
            focus_row(session, "request draft", "Request:" + withdrawn["id"], 30)
            save(session, "forwarded-overview")
            assert f"manager 127.0.0.1:{forward_listener.getsockname()[1]} " in header(session), (
                "the header does not name the forwarder address", header(session))
            assert forwarder.connections > 0, "the TUI did not connect through the forwarder"
            forwarder.open_window(60)
            opened_at = time.monotonic()
            session.send(b"g")
            # The manager answers the read at once, and the forwarder holds the
            # answer for FORWARD_DELAY seconds.
            session.pump(1.0)
            _, draft_tag, _ = observed(withdrawn["links"]["self"], "Request")
            client[2](withdrawn["links"]["self"], {"operation": "withdraw"}, draft_tag)
            session.send(b"E")
            session.wait_screen("Manager endpoints")
            session.send(b"\x1b[B\r")
            screen = session.wait_screen(f"> 2. active  {direct}", timeout=10)
            switched_at = time.monotonic()
            save(session, "switched")
            late = forwarder.pending_at(switched_at)
            assert switched_at < opened_at + FORWARD_DELAY and late, (
                "the switch did not happen while the forwarder held delayed bytes of the earlier endpoint",
                round(switched_at - opened_at, 2), late)
            assert f"  1. not connected  {forwarded}" in screen, ("the forwarder endpoint is not closed after the switch", screen)
            frames = 0
            # The identity row of the header names the manager address of the
            # active session.
            forward_address = f"manager 127.0.0.1:{forward_listener.getsockname()[1]} "

            def watched(key, needle):
                """Send the key and check every frame until the screen shows
                the needle: no frame may show the earlier endpoint as active,
                a draft row or the withdrawn request."""
                nonlocal frames
                session.send(key)
                deadline = time.monotonic() + 20
                while True:
                    session.pump(0.05)
                    screen = session.screen.text()
                    frames += 1
                    assert "request draft" not in screen and withdrawn["id"] not in squeeze(details(screen)) \
                        and "1. active" not in screen and forward_address not in header(session), (
                        "a late response of the earlier endpoint appeared after the switch", screen)
                    if needle is not None and needle in screen:
                        return screen
                    assert time.monotonic() < deadline, ("the TUI did not show", needle, screen)
                    if needle is None and time.monotonic() >= until:
                        return screen

            # Every frame is checked from the switch until the delayed bytes
            # are due and three seconds more, and at least three seconds
            # after the Manager overview of the direct endpoint opens.
            until = max(late_chunk[2] for late_chunk in late) + 3
            watched(b"\x1b", "Manager profiles")
            watched(b"\r", "Manager workflows")
            watched(b"O", "Manager overview")
            listed, _, _ = observed("/v1/snapshot", "OverviewSnapshot")
            assert not any(item["kind"] == "request" and item["request"]["id"] == withdrawn["id"] for item in listed["items"]), (
                "the manager overview still lists the withdrawn request")
            reached = time.monotonic()
            until = max(until, reached + 3)
            screen = watched(b"", None)
            assert "Manager overview" in screen and f"manager 127.0.0.1:{port} " in header(session), (
                "the TUI does not show the Manager overview of the direct endpoint", screen)
            save(session, "after-delay")
            focus_row(session, "run Running", "Run:" + held_run, 10)
            session.send(b"E")
            screen = session.wait_screen("Manager endpoints")
            assert f"> 2. active  {direct}" in screen and f"  1. not connected  {forwarded}" in screen, (
                "the endpoints changed after the delay", screen)
            session.send(b"q")
            assert session.wait_exit(20) == 0
            session.assert_restored()
        print("PASS tui-failures 8: g started an overview read through the forwarder, request", withdrawn["id"], "was withdrawn,",
              "and the switch to the direct profile happened", f"{switched_at - opened_at:.2f}", "seconds after the delay window opened,",
              "while the forwarder held", len(late), "delayed chunks of the earlier endpoint; the Manager overview of the direct endpoint",
              "opened", f"{reached - switched_at:.2f}", "seconds after the switch, and in", frames, "frames until",
              f"{until - switched_at:.2f}", "seconds after the switch no frame showed the earlier endpoint as active or the withdrawn draft,",
              "and the forwarder dropped", forwarder.dropped, "chunks of closed connections", flush=True)
        assert not tui_fixture.client_state.exists(), "the service TUI created local runner state"
        print("PASS tui-failures: the service TUI followed a manager loss and restart, a stale answer, a refused credential, a quit during",
              "a held run and an endpoint change during delayed responses", flush=True)
    finally:
        for process in lifetimes:
            if process.poll() is None:
                process.terminate()
            process.wait(timeout=25)


def size_checks():
    """The tui-sizes mode and its broken-draft control. See TUI_SIZES for
    the steps."""
    harness = tui_fixture.harness
    small, standard, large = (12, 40), (24, 80), (36, 140)
    selectors = ("reviewDigest", "requestRevision", "profileRevision", "descriptorRevision", "processGeneration")
    # The numbered outcome of a key that a read deferred, or that met a stale
    # observation or a command in progress. It sends nothing, so the
    # operator presses the key again.
    deferred = re.compile(r"(Key|Approval key) (\d+): (\S+ deferred during a page-set read|\S+ did not start: (a command is in progress"
                          r"|the decision observation is stale|the control observation is stale)|Approval did not start: "
                          r"(a manager command is in progress|the displayed review is stale|a manager page-set read is in progress))")
    read_deferred = "Approval did not start: a manager page-set read is in progress. Press y again."

    def save(session, name):
        (work / ("tui-sizes-" + name + ".screen.txt")).write_text(session.screen.text())

    def resize(session, size, marker, name):
        """Resize the terminal, wait for the redraw of the TUI at the new
        size, and require the marker on the redrawn screen. Returns the
        screen."""
        rows, columns = size
        start = len(session.output)
        session.resize(rows, columns)
        deadline = time.monotonic() + 15
        while len(session.output) == start:
            assert time.monotonic() < deadline and session.process.poll() is None, ("the TUI did not redraw after the resize", name, size)
            session.pump()
        session.settle()
        while squeeze(marker) not in squeeze(session.screen.text()):
            if time.monotonic() >= deadline or session.process.poll() is not None:
                save(session, f"{name}-{columns}x{rows}-missing")
                raise AssertionError(("the redrawn screen lacks its view", name, size, marker, session.screen.text()))
            session.pump()
        session.settle()
        save(session, f"{name}-{columns}x{rows}")
        return session.screen.text()

    def boxed(screen, label):
        """The text of the first row inside the editor box whose top border
        carries the label, without box drawing and white space, or None."""
        lines = screen.splitlines()
        for index, line in enumerate(lines[:-1]):
            if label in line:
                return squeeze(lines[index + 1])
        return None

    def mutation_key(session, key, expected, timeout):
        """Send a mutation key until the screen shows one of the expected
        texts. A deferred key sends nothing and shows a numbered outcome, so
        the key is sent again, as an operator does."""
        seen = {match.group(2) for match in deferred.finditer(session.screen.text())}
        deadline = time.monotonic() + timeout
        session.send(key)
        while not any(squeeze(text) in squeeze(session.screen.text()) for text in expected):
            assert time.monotonic() < deadline and session.process.poll() is None, ("the TUI did not show", expected, session.screen.text())
            fresh = {match.group(2) for match in deferred.finditer(session.screen.text())} - seen
            if fresh:
                seen |= fresh
                session.pump(1.0)
                session.send(key)
            session.pump(0.1)
        return session.screen.text()

    def approval_key(session, last, expected):
        """Press y on the summary review until its notice is other than a
        deferral, and require the expected notice. Returns the number of the
        press and the screen."""
        def shown(number, line, compact, text):
            # An approval-start notice lasts only until the TUI observes the
            # association, so the first row from the PTY output also counts.
            # A narrow terminal wraps the notice, so the screen counts too.
            return notice_is(line, number, text) or squeeze(f"Approval key {number}: {text}") in compact

        for _ in range(5):
            _, (last, line) = key_notice(session, b"y", last, "the TUI showed no approval-key notice")
            session.settle()
            screen = session.screen.text()
            compact = squeeze(screen)
            if shown(last, line, compact, expected):
                return last, screen
            assert any(shown(last, line, compact, text) for text in APPROVAL_DEFERRED + (read_deferred,)), (
                "the approval key showed another outcome", expected, line, screen)
            session.pump(1.0)
        raise AssertionError(("the approval key was deferred five times", expected))

    def review_state(submitted, preparation, tag):
        """Read through HTTP that the request is in review and that its
        preparation is live and unchanged."""
        current, _, _ = observed(submitted["links"]["self"], "Request")
        assert current["runId"] is None and current["phase"] == "review" and current["preparationId"] == preparation["id"], (
            "the request left its review", current["phase"], current["runId"])
        still, still_tag, _ = observed("/v1/preparations/" + preparation["id"], "Preparation")
        assert still["state"] == "live" and still["revision"] == preparation["revision"] and still_tag == tag, (
            "the preparation changed", still["state"])

    def supplied(value):
        """Whether the overview holds one request, and that request
        supplies every input."""
        drafts = [item["request"] for item in value["items"] if item["kind"] == "request"]
        return len(drafts) == 1 and bool(drafts[0]["readiness"]["supplied"]) and not drafts[0]["readiness"]["missing"]

    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
    try:
        wait_ready(process)
        status, capabilities, _ = request("/v1/capabilities", harness)
        assert status == 200
        status, catalogue, _ = request("/v1/workflows?profileId=profile_1", harness)
        assert status == 200
        index = next(i for i, item in enumerate(catalogue["items"]) if item["name"] == "mixed-controls")
        workflow = catalogue["items"][index]
        client = mixed_client(capabilities, harness)
        observed, wait_for, _, _ = client
        literal = MIXED_TEXT
        draft = squeeze(literal)
        answer = JOURNEY_ANSWER.decode()
        with harness_reads_only(), tui_fixture.session(rows=small[0], columns=small[1]) as session:
            # 1. The setup draft survives the resizes.
            session.wait_screen("profile_1")
            session.send(b"\r")
            session.wait_screen("Manager workflows")
            save(session, "catalogue-40x12")
            session.send(b"\x1b[B" * index + b"\r")
            session.wait_screen("request validator current", timeout=20)
            session.send(b"\x1b[200~" + literal.encode() + b"\x1b[201~")
            deadline = time.monotonic() + 10
            while draft not in squeeze(session.screen.text()):
                assert time.monotonic() < deadline and session.process.poll() is None, ("the pasted literal is not shown at 40x12", session.screen.text())
                session.pump()
            save(session, "setup-draft-40x12")
            if tui_mode == TUI_SIZES_BROKEN:
                session.send(b"\x7f" * len(literal))
                session.settle()
                print("CONTROL cleared the input editor with Backspace before the resize", flush=True)
            for size in (standard, small):
                screen = resize(session, size, "Input •", "setup")
                assert draft in squeeze(screen), DRAFT_SURVIVES
            session.send(b"\x04")
            snapshot, _, _ = wait_for("/v1/snapshot", "OverviewSnapshot", supplied)
            submitted = next(item["request"] for item in snapshot["items"] if item["kind"] == "request")
            assert submitted["readiness"]["supplied"] == [{"name": "input", "source": "literal", "value": literal}], (
                DRAFT_SURVIVES, submitted["readiness"]["supplied"])
            print("PASS tui-sizes 1: the setup draft survived the resizes to 80x24 and back to 40x12, and Ctrl-D supplied exactly",
                  "the typed literal to request", submitted["id"], flush=True)
            # 2. At 40x12 the selectors do not all fit, and y is refused.
            session.wait_screen("REQUEST REVIEW", timeout=20)
            save(session, "request-40x12")
            session.send(b"\r")
            deadline = time.monotonic() + 45
            while "Approve exact manager review" not in session.screen.text():
                assert time.monotonic() < deadline and session.process.poll() is None, ("the TUI showed no review", session.screen.text())
                session.pump()
            session.settle()
            save(session, "review-40x12")
            current, _, _ = wait_for(submitted["links"]["self"], "Request", lambda value: value["preparationId"] is not None)
            preparation, preparation_tag, _ = observed("/v1/preparations/" + current["preparationId"], "Preparation")
            fitting = [name for name in selectors if squeeze(name + preparation[name]) in squeeze(session.screen.text())]
            assert len(fitting) < len(selectors), ("every selector fits at 40x12, so the consent rule permits approval", fitting)
            last, _ = approval_key(session, 0, "Approval did not start: the complete review does not fit. Resize the terminal.")
            save(session, "review-refused-40x12")
            review_state(submitted, preparation, preparation_tag)
            print("PASS tui-sizes 2: at 40x12", len(fitting), "of", len(selectors), "selectors fit, y showed the notice that the",
                  "complete review does not fit, and request", submitted["id"], "stayed in review with preparation", preparation["id"],
                  "live and unchanged", flush=True)
            # 3. The review survives the resize, and y approves at 80x24.
            screen = resize(session, standard, "Approve exact manager review", "review")
            compact = squeeze(screen)
            assert squeeze("Preparation: " + preparation["id"]) in compact, ("the review did not survive the resize", screen)
            for name in selectors:
                assert squeeze(name + preparation[name]) in compact, ("a displayed review selector is clipped at 80x24", name)
            review_state(submitted, preparation, preparation_tag)
            last, _ = approval_key(session, last, APPROVAL_STARTED)
            associated, _, _ = wait_for(submitted["links"]["self"], "Request", lambda value: value["runId"] is not None)
            run = associated["runId"]
            base = "/v1/runs/" + run
            print("PASS tui-sizes 3: the review of preparation", preparation["id"], "survived the resize to 80x24 with the five",
                  "selectors unclipped, and y approved it: request", submitted["id"], "names run", run, flush=True)
            # 4. The typed answer survives the resize. The TUI answers and
            # retries in the order that the manager presents the heads.
            order = []
            deadline = time.monotonic() + 150
            while len(order) < 2:
                assert time.monotonic() < deadline and session.process.poll() is None, ("the decision heads did not appear", order)
                snapshot, _, _ = observed(base + "/snapshot", "RunSnapshot")
                assert snapshot["runtime"] is None or snapshot["runtime"]["status"] not in ("succeeded", "failed", "cancelled"), (
                    "the run ended before both heads", snapshot["runtime"])
                control, _, _ = observed(base + "/control", "RunControl")
                head = control["decisionHeadId"]
                decision = observed("/v1/decisions/" + head, "Decision")[0] if head is not None else None
                if decision is None or decision["kind"] in order:
                    session.pump(0.2)
                    continue
                if decision["kind"] == "question":
                    question_occurrence = decision["address"]["occurrenceId"]
                    session.wait_screen("Answer •", timeout=30)
                    save(session, "question")
                    session.send(JOURNEY_ANSWER)
                    typed_deadline = time.monotonic() + 10
                    while boxed(session.screen.text(), "Answer •") != answer:
                        assert time.monotonic() < typed_deadline, ("the typed answer is not shown", session.screen.text())
                        session.pump()
                    screen = resize(session, large, "Answer •", "answer")
                    assert boxed(screen, "Answer •") == answer, ("JOURNEY-ASSERT the typed answer survives resize", screen)
                    print("PASS tui-sizes 4a: the typed answer", answer, "of question", head, "survived the resize to 140x36", flush=True)
                    mutation_key(session, b"\x04", ("Answer sent to the manager", "Recovery required", "Terminal: "), 45)
                else:
                    session.wait_screen("r RETRY", timeout=30)
                    save(session, "recovery")
                    mutation_key(session, b"r", ("preparing explicit retry", "sending one retry attempt", "manager intent accepted",
                                                  "Answer •", "Terminal: "), 45)
                # A resolved decision may leave the observable queue, so the
                # harness waits until the run controls name another head.
                wait_for(base + "/control", "RunControl", lambda value: value["decisionHeadId"] != head)
                order.append(decision["kind"])
            print("PASS tui-sizes 4b: the TUI answered the question and retried the recovery in the manager order",
                  " then ".join(order), flush=True)
            # 5. Terminal success, the verified result and the save.
            wait_for(base + "/snapshot", "RunSnapshot", lambda value: value["runtime"] is not None and value["runtime"]["status"] == "succeeded")
            deadline = time.monotonic() + 45
            while not ("Terminal: succeeded" in session.screen.text() and "Result SHA-256: " in session.screen.text()):
                assert time.monotonic() < deadline and session.process.poll() is None, ("the TUI showed no verified result", session.screen.text())
                session.pump(0.2)
            session.settle()
            save(session, "result")
            artifact = verified_download(run, client, harness)
            screen = session.screen.text()
            for row in ("Result: verified " + str(int(artifact["bytes"])) + " bytes", "Result SHA-256: " + artifact["sha256"]):
                assert row in screen, ("the result size or digest differs from the verified artifact", row)
            answer_files = sorted(work.glob("manager/runs/runs/*/runtime/answers.json"))
            assert len(answer_files) == 1, ("run store answers", answer_files)
            recorded = [entry["answer"] for entry in json.loads(answer_files[0].read_bytes())["answers"]
                        if entry["occurrenceId"] == question_occurrence]
            assert len(recorded) == 1 and recorded[0] is False, ("JOURNEY-ASSERT typed answer is not JSON false", recorded)
            saved_path = work / "tui-sizes-saved-result.bin"
            session.send(b"s")
            session.wait_screen("Save verified result", timeout=15)
            session.send(str(saved_path).encode())
            session.send(b"\x04")
            session.wait_screen("Saved the verified", timeout=15)
            save(session, "saved")
            saved = saved_path.read_bytes()
            assert stat.S_IMODE(os.lstat(saved_path).st_mode) == 0o600, ("the saved file mode", oct(os.lstat(saved_path).st_mode))
            assert saved == (work / "verified-result.json").read_bytes() and hashlib.sha256(saved).hexdigest() == artifact["sha256"], (
                "the saved bytes differ from the verified download")
            # The save closes its dialog and returns to the live monitor.
            session.wait_screen("s SAVE RESULT", timeout=15)
            print("PASS tui-sizes 5: the live monitor shows terminal success and verified result", artifact["id"], "of", artifact["bytes"],
                  "bytes, the run store records JSON false, and s saved the exact bytes with mode 0600", flush=True)
            # 6. Every view redraws at every size. At every size the live
            # monitor shows terminal success and the verified size and
            # SHA-256 of the harness download. At 40x12 the other service
            # lines do not all fit, and the Terminal and Result lines keep
            # their rows.
            outcome = ("Terminal: succeeded", "Result: verified " + str(int(artifact["bytes"])) + " bytes",
                       "Result SHA-256: " + artifact["sha256"])
            for size in (small, standard, large):
                screen = squeeze(resize(session, size, outcome[2], "live"))
                for row in outcome:
                    assert squeeze(row) in screen, ("the live monitor lacks its outcome row", size, row)
            session.send(b"\x1b")
            session.wait_screen("Manager overview", timeout=10)
            views = ((b"", "Manager overview", "overview"), (b"D", "Manager decisions", "decisions"), (b"H", "Manager history", "history"))
            for key, title, name in views:
                if key:
                    session.send(key)
                    session.wait_screen(title, timeout=10)
                for size in (small, standard, large):
                    resize(session, size, title, name)
                if name == "history":
                    session.send(b"\x1b[H")
                    deadline = time.monotonic() + 20
                    while run not in squeeze(session.screen.text()):
                        assert time.monotonic() < deadline and session.process.poll() is None, ("the History view does not list the run", run)
                        session.pump(0.2)
                    save(session, "history-run")
                session.send(b"\x1b")
                session.wait_screen("Manager workflows", timeout=10)
            print("PASS tui-sizes 6: the live monitor, the Manager overview, the Manager decisions view and the History view redrew",
                  "at 40x12, 80x24 and 140x36, the live monitor showed terminal success and the verified size and SHA-256 at each",
                  "size, and the History view lists run", run, flush=True)
            session.send(b"q")
            assert session.wait_exit(20) == 0, "the service TUI did not exit with status 0"
            session.assert_restored()
        assert not tui_fixture.client_state.exists(), "the service TUI created local runner state"
        print("PASS tui-sizes: the service journey completed through the keyboard at 40x12, 80x24 and 140x36, the drafts and the",
              "review survived every resize, and q restored the terminal", flush=True)
    finally:
        if process.poll() is None:
            process.terminate()
        process.wait(timeout=25)


def run_vitest(test_file, environment, report_file, log_file, steps, poll=None):
    """Run one live check of ext-pi with node from PATH in ext-pi, with the
    variables of environment and AGENT_CAT_MANAGER_REPORT set to report_file
    added to the environment of the harness, and give its report. poll, when
    given, runs about every 50 milliseconds while the check runs. The check
    must exit with status 0 within 720 seconds, vitest must report its steps
    passed, and the report file must exist."""
    environment = dict(os.environ, AGENT_CAT_MANAGER_REPORT=str(report_file), **environment)
    with log_file.open("wb") as log:
        child = subprocess.Popen(["node", "node_modules/vitest/vitest.mjs", "run", test_file],
                                 cwd=source / "ext-pi", env=environment, stdout=log, stderr=subprocess.STDOUT)
        try:
            deadline = time.monotonic() + 720
            while child.poll() is None:
                assert time.monotonic() < deadline, ("the ext-pi live check exceeded 720 seconds", test_file)
                if poll is not None:
                    poll()
                time.sleep(0.05)
        finally:
            if child.poll() is None:
                child.kill()
                child.wait()
    text = re.sub(r"\x1b\[[0-9;]*m", "", log_file.read_text(errors="replace"))
    assert child.returncode == 0, ("the ext-pi live check failed", test_file, child.returncode, text[-4000:])
    assert re.search(r"Tests\s+%d passed \(%d\)" % (steps, steps), text) and report_file.is_file(), (
        "the ext-pi live check did not run its steps", test_file, text[-4000:])
    return json.loads(report_file.read_bytes())


def pi_client_checks():
    """The pi-client mode. See PI_CLIENT for the steps."""
    harness = tui_fixture.harness
    report_path = work / "pi-client-report.json"
    log_path = work / "pi-client-vitest.log"
    ui_report_path = work / "pi-client-ui-report.json"
    ui_log_path = work / "pi-client-ui-vitest.log"
    clone_legacy_runs(legacy_frontend_run(), LEGACY_ENTRIES - 1)
    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "--legacy-history", f"{LEGACY_ROOT}=profile_1",
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
    try:
        with harness_reads_only():
            wait_ready(process)
            status, capabilities, _ = request("/v1/capabilities", harness)
            assert status == 200, ("capabilities", status)
            status, catalogue, _ = request("/v1/workflows?profileId=profile_1", harness)
            assert status == 200, ("catalogue", status)
            workflow = next(item for item in catalogue["items"] if item["name"] == "mixed-controls")
            status, overview, _ = request("/v1/snapshot", harness)
            assert status == 200 and not overview["items"], ("the overview is not empty before the check", status)
            cursor = overview["cursor"]
            # The running manager issues the credential of the human-path
            # check through its administration root.
            ui_profile = tui_fixture.renew("pi-ui")
            client = mixed_client(capabilities, harness)
            observed = client[0]

            harness_answers = []

            def harness_answer(handshake):
                """Answer the decision that the handshake file names with JSON
                false through HTTP with the harness credential, wait until the
                command reaches its effect, and write the command to the file
                with the suffix .done."""
                global posts_forbidden
                named = json.loads(handshake.read_bytes())["decision"]
                decision, tag, _ = observed(named, "Decision")
                assert decision["state"] == "pending" and decision["kind"] == "question", ("the named decision", decision["state"], decision["kind"])
                body = {"operation": "answer", "occurrenceId": decision["address"]["occurrenceId"], "generation": decision["generation"], "value": False}
                key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
                previous, posts_forbidden = posts_forbidden, False
                try:
                    status, receipt, raw = request(named, harness | {"Content-Type": "application/json", "Idempotency-Key": key, "If-Match": tag},
                                                   method="POST", payload=json.dumps(body, separators=(",", ":")).encode())
                finally:
                    posts_forbidden = previous
                assert status == 202, ("the harness answer", status, receipt.get("code"))
                validate("CommandReceipt", receipt, raw)
                command = receipt["links"]["self"]
                deadline = time.monotonic() + 40
                while True:
                    settled, _, _ = observed(command, "CommandReceipt")
                    if settled["state"] in ("effect-observed", "refused", "unresolved"):
                        break
                    assert time.monotonic() < deadline, ("the harness answer did not settle", settled["state"])
                    time.sleep(0.05)
                assert settled["state"] == "effect-observed", ("the harness answer", settled["state"], settled.get("refusal"))
                harness_answers.append((named, command))
                written = handshake.with_name(handshake.name + ".tmp")
                written.write_text(json.dumps({"command": command}))
                os.replace(written, handshake.with_name(handshake.name + ".done"))

            def vitest(test_file, profile, report_file, log_file, steps, handshake=None):
                """Run one live check of ext-pi with the client profile and give
                its report. With a handshake file, answer the decision that the
                check names there first, once."""
                environment = {"AGENT_CAT_MANAGER_PROFILE": str(profile)}
                if handshake is not None:
                    environment["AGENT_CAT_MANAGER_HARNESS_ANSWER"] = str(handshake)

                def poll():
                    if handshake is not None and handshake.is_file() and not harness_answers:
                        harness_answer(handshake)

                return run_vitest(test_file, environment, report_file, log_file, steps, poll)

            def prompts():
                """The question prompt of every answer of every run store, by run store."""
                return {path: [entry["question"].get("prompt") or "" for entry in json.loads(path.read_bytes())["answers"]]
                        for path in work.glob("manager/runs/runs/*/runtime/answers.json")}

            def succeeded(run_id):
                snapshot, _, _ = observed("/v1/runs/" + run_id + "/snapshot", "RunSnapshot")
                assert snapshot["runtime"] is not None and snapshot["runtime"]["status"] == "succeeded", ("run status", run_id, snapshot["runtime"])

            ui = vitest("test/manager-ui-live.test.ts", ui_profile, ui_report_path, ui_log_path, 14, work / "pi-client-harness-answer.json")
            ui_receipts = command_receipts(cursor, harness)
            # The reads of the session check count only the commands after this cursor.
            status, middle, _ = request("/v1/snapshot", harness)
            assert status == 200, ("snapshot after the human path", status)
            session_cursor = middle["cursor"]
            literal, _, _ = observed("/v1/requests/" + ui["literalRequestId"], "Request")
            assert literal["readiness"]["supplied"] == [{"name": "input", "source": "literal", "value": PI_UI_LITERAL}], (
                "the request did not supply exactly the literal", literal["readiness"]["supplied"])
            assert literal["runId"] == ui["literalRunId"] and literal["phase"] == "associated", ("literal request", literal["runId"], literal["phase"])
            succeeded(ui["literalRunId"])
            run_prompts = prompts()
            assert any(prompt.startswith("fixed-point source: " + PI_UI_LITERAL) for values in run_prompts.values() for prompt in values), (
                "the program did not receive the literal", run_prompts)
            print("PASS pi-client 1: /wfm request", ui["literalRequestId"], "supplied exactly the literal with its leading spaces,",
                  "and run", ui["literalRunId"], "succeeded with the literal as the input of its program", flush=True)
            preparation, _, _ = observed("/v1/preparations/" + ui["literalPreparationId"], "Preparation")
            approvals = [receipt for _, receipt in ui_receipts
                         if receipt["operation"] == "approve" and receipt["resource"] == "/v1/preparations/" + ui["literalPreparationId"]]
            assert len(approvals) == 1 and approvals[0]["state"] not in ("refused", "unresolved"), (
                "the approve command of the displayed review", approvals)
            selectors = ("reviewDigest", "requestRevision", "profileRevision", "descriptorRevision", "processGeneration")
            assert preparation["state"] == "consumed" and ui["approveBody"] == {"operation": "approve", **{name: preparation[name] for name in selectors}}, (
                "the approve command does not name the exact review selectors", preparation["state"], ui["approveBody"])
            print("PASS pi-client 2: the one approve command of preparation", ui["literalPreparationId"], "named its exact review selectors,",
                  "review digest", preparation["reviewDigest"], "and the approval consumed the preparation and started the run", flush=True)
            captured, _, _ = observed("/v1/requests/" + ui["capturedRequestId"], "Request")
            captured_bytes = PI_UI_CAPTURED.encode("utf-8")
            captured_digest = hashlib.sha256(captured_bytes).hexdigest()
            assert captured["readiness"]["supplied"] == [{"name": "input", "source": "capture", "captureId": ui["captureId"]}], (
                "the captured-input request does not supply the capture", captured["readiness"]["supplied"])
            assert ui["captureSha256"] == captured_digest and ui["captureBytes"] == len(captured_bytes), ("capture report", ui)
            assert captured["runId"] == ui["capturedRunId"], ("captured request run", captured["runId"])
            succeeded(ui["capturedRunId"])
            assert any("fixed-point source: " + captured_digest in values for values in run_prompts.values()), (
                "the program did not receive the captured bytes", run_prompts)
            print("PASS pi-client 3: the captured-input request supplied capture", ui["captureId"], "of", len(captured_bytes),
                  "bytes, and run", ui["capturedRunId"], "succeeded with the SHA-256 of the captured bytes as the input of its program", flush=True)
            declined = "/v1/preparations/" + ui["declinedPreparationId"]
            commands = [(receipt["operation"], receipt["state"], (receipt["effect"] or {}).get("kind"))
                        for _, receipt in ui_receipts if receipt["resource"] == declined]
            assert commands == [("discard", "effect-observed", "discarded")], ("the commands of the declined preparation", commands)
            withdrawn, _, _ = observed("/v1/requests/" + ui["declinedRequestId"], "Request")
            discarded, _, _ = observed(declined, "Preparation")
            assert withdrawn["phase"] == "withdrawn" and withdrawn["runId"] is None and discarded["state"] == "invalidated" and discarded["reason"] == "discarded", (
                "the declined request", withdrawn["phase"], discarded["state"], discarded["reason"])
            print("PASS pi-client 4: the declined review of preparation", ui["declinedPreparationId"], "has no approve command, the later",
                  "discard reached the effect discarded from review, and request", ui["declinedRequestId"], "is withdrawn", flush=True)
            def person_answers(literal):
                """The answers of the person question of every run whose input is the literal, from the run stores."""
                return [entry["answer"] for path in work.glob("manager/runs/runs/*/runtime/answers.json")
                        for entry in json.loads(path.read_bytes())["answers"]
                        if (entry["question"].get("prompt") or "").startswith("Independent confirmation? " + literal)]

            def receipts_of(operation, resource):
                return [(uri, receipt) for uri, receipt in ui_receipts if receipt["operation"] == operation and receipt["resource"] == resource]

            monitored = ui["monitoredRunId"]
            answered = receipts_of("answer", "/v1/decisions/" + ui["answeredDecisionId"])
            retried = receipts_of("retry", "/v1/runs/" + monitored + "/control")
            assert [uri for uri, _ in answered] == [ui["answerCommand"]] and [uri for uri, _ in retried] == [ui["retryCommand"]], (
                "the answer and retry commands of the monitored run", [uri for uri, _ in answered], [uri for uri, _ in retried], ui)
            assert all(receipt["state"] == "effect-observed" for _, receipt in answered + retried), ("a command of the monitored run",)
            assert person_answers(PI_UI_ANSWERED) == [False], ("the run store does not record JSON false", person_answers(PI_UI_ANSWERED))
            succeeded(monitored)
            artifact = verified_download(monitored, client, harness)
            assert int(artifact["bytes"]) == ui["resultBytes"] and artifact["sha256"] == ui["resultSha256"], (
                "the monitored result differs from the harness download", artifact["bytes"], artifact["sha256"], ui)
            print("PASS pi-client 5: /wfm-monitor showed run", monitored, "and its question, /wfm-answer sent answer command",
                  ui["answerCommand"], "whose answer the run store records as JSON false, the offered retry", ui["retryCommand"],
                  "reached its effect, the run succeeded, and the monitor showed the Terminal and Result lines of the verified",
                  artifact["bytes"], "bytes with the SHA-256", artifact["sha256"], "of the harness download", flush=True)
            stale = "/v1/decisions/" + ui["staleDecisionId"]
            assert harness_answers == [(stale, ui["harnessAnswerCommand"])], ("the harness answer", harness_answers, ui)
            preempted = receipts_of("answer", stale)
            assert [uri for uri, _ in preempted] == [ui["harnessAnswerCommand"]] and preempted[0][1]["state"] == "effect-observed", (
                "the commands of the preempted decision", [(uri, receipt["state"]) for uri, receipt in preempted])
            # The manager serves only pending decisions.
            status, resolved, _ = request(stale, harness)
            assert status == 404 and resolved["code"] == "unavailable-resource", ("the preempted decision is still served", status)
            queue, _, _ = observed("/v1/decisions?runId=" + ui["staleRunId"], "DecisionPage")
            assert ui["staleDecisionId"] not in [item["id"] for item in queue["items"]], "the preempted decision is still queued"
            assert person_answers(PI_UI_STALE) == [False], ("the run store of the preempted run", person_answers(PI_UI_STALE))
            ending, _, _ = observed("/v1/runs/" + ui["staleRunId"] + "/snapshot", "RunSnapshot")
            expected_ending = "failed" if ui["staleRecovery"] == "Abandon" else "succeeded"
            assert ending["runtime"] is not None and ending["runtime"]["status"] == expected_ending, (
                "the preempted run", ui["staleRecovery"], ending["runtime"])
            print("PASS pi-client 6: the harness answered decision", ui["staleDecisionId"], "first with command", ui["harnessAnswerCommand"],
                  "while the editor of /wfm-answer was open, the 412 answer of the extension left no command and the draft was kept,",
                  "and run", ui["staleRunId"], "ended", expected_ending, "after the offered", ui["staleRecovery"], flush=True)
            cancelled = ui["cancelledRunId"]
            cancelled_request, _, _ = observed("/v1/requests/" + ui["cancelledRequestId"], "Request")
            assert cancelled_request["runId"] == cancelled and cancelled_request["readiness"]["supplied"] == [
                {"name": "input", "source": "literal", "value": PI_UI_CANCELLED}], ("the cancelled request", cancelled_request["runId"])
            cancels = receipts_of("cancel", "/v1/runs/" + cancelled + "/control")
            assert [uri for uri, _ in cancels] == [ui["cancelCommand"]], ("the cancel commands of the cancelled run", [uri for uri, _ in cancels], ui)
            cancel_receipt = cancels[0][1]
            assert cancel_receipt["state"] in ("acknowledged", "effect-observed") and cancel_receipt["acknowledgement"] is not None \
                and cancel_receipt["acknowledgement"]["state"] in ("accepted", "queued", "delivered"), ("the cancel receipt", cancel_receipt)
            ending, _, _ = observed("/v1/runs/" + cancelled + "/snapshot", "RunSnapshot")
            assert ending["runtime"] is not None and ending["runtime"]["status"] == "cancelled", ("the cancelled run", ending["runtime"])
            print("PASS pi-client 7: /wfm-cancel sent the one cancel command", ui["cancelCommand"], "of run", cancelled,
                  "whose receipt records the runtime acknowledgement", cancel_receipt["acknowledgement"]["state"],
                  repr(cancel_receipt["acknowledgement"]["message"]), "and the run ended cancelled", flush=True)
            saved_path = Path(ui["savedPath"])
            saved_status = os.lstat(saved_path)
            assert ui["savedRunId"] == monitored and stat.S_ISREG(saved_status.st_mode) and stat.S_IMODE(saved_status.st_mode) == 0o600, (
                "the saved result", ui["savedRunId"], oct(saved_status.st_mode))
            artifact = verified_download(monitored, client, harness)
            saved = saved_path.read_bytes()
            assert saved == (work / "verified-result.json").read_bytes() and len(saved) == int(artifact["bytes"]) \
                and hashlib.sha256(saved).hexdigest() == artifact["sha256"], "the saved bytes differ from the harness download"
            print("PASS pi-client 8: /wfm-result saved the verified result of run", monitored, "once to", saved_path, "with mode 0600 and the",
                  len(saved), "bytes of the harness download, and a second save to the same path refused", flush=True)
            exports_uri = "/v1/runs/" + ui["exportRunId"] + "/exports"
            status, exports, raw = request(exports_uri, harness)
            assert status == 200, ("the export collection", status, exports.get("code"))
            validate("ExportPage", exports, raw)
            assert [(item["id"], item["name"], item["state"]) for item in exports["items"]] == [(ui["exportId"], ui["exportName"], "published")], (
                "the export was not published once", exports["items"])
            export_receipt = exports["items"][0]
            assert int(export_receipt["bytes"]) == ui["exportBytes"] and export_receipt["sha256"] == ui["exportSha256"], ("the export receipt", export_receipt, ui)
            exported_commands = receipts_of("export", exports_uri)
            assert [uri for uri, _ in exported_commands] == [ui["exportCommand"]] and exported_commands[0][1]["state"] == "effect-observed" \
                and exported_commands[0][1]["effect"]["resource"] == "/v1/exports/" + ui["exportId"], ("the export commands", exported_commands)
            connection = http.client.HTTPSConnection("127.0.0.1", port, context=context, timeout=15)
            try:
                connection.request("GET", export_receipt["download"], headers=harness | {"Accept": "application/octet-stream"})
                response = connection.getresponse()
                exported = response.read(int(export_receipt["bytes"]) + 1)
                assert response.status == 200, ("the export download", response.status)
            finally:
                connection.close()
            assert len(exported) == int(export_receipt["bytes"]) and hashlib.sha256(exported).hexdigest() == export_receipt["sha256"], (
                "the export download differs from its receipt")
            assert (work / "manager" / "runs" / "exports" / ui["exportName"]).read_bytes() == exported, "the export download differs from the published file"
            print("PASS pi-client 9: /wfm-export sent the one export command", ui["exportCommand"], "of run", ui["exportRunId"],
                  "and the manager published", ui["exportName"], "once as", ui["exportId"], "whose download of", len(exported),
                  "bytes verifies against the SHA-256", export_receipt["sha256"], "of the receipt and equals the published file", flush=True)
            def lineage_child(operation, number, edits, verify_store=None):
                """Require that the one lineage command of the operation on the
                parent run of the report is the command of the report with the
                effect lineage-created on the child request, that the lineage
                collection of the parent holds only that child, that the one
                approval of the child preparation consumed it, that its review
                names the parent run, the operation and the edits, and that the
                child run succeeded and names the parent run and the operation.
                When verify_store is given, it checks the run store of the
                succeeded child and gives the text that the PASS line adds."""
                parent = ui[operation + "ParentRunId"]
                request_id, run_id, preparation_id = ui[operation + "RequestId"], ui[operation + "RunId"], ui[operation + "PreparationId"]
                lineage_uri = "/v1/runs/" + parent + "/lineage-requests"
                created = receipts_of(operation, lineage_uri)
                assert [uri for uri, _ in created] == [ui[operation + "Command"]] \
                    and created[0][1]["state"] == "effect-observed" and created[0][1]["effect"]["kind"] == "lineage-created" \
                    and created[0][1]["effect"]["resource"] == "/v1/requests/" + request_id, ("the lineage commands", operation, created)
                status, lineage, raw = request(lineage_uri, harness)
                assert status == 200, ("the lineage collection", operation, status, lineage.get("code"))
                validate("LineagePage", lineage, raw)
                assert [(item["id"], item["lineage"], item["parentRunId"]) for item in lineage["items"]] == [(request_id, operation, parent)], (
                    "the lineage collection of the parent run", operation, lineage["items"])
                child, _, _ = observed("/v1/requests/" + request_id, "Request")
                assert child["runId"] == run_id and child["phase"] == "associated" and child["parentRunId"] == parent \
                    and child["lineage"] == operation, ("the child request", operation, child["runId"], child["phase"])
                child_preparation, _, _ = observed("/v1/preparations/" + preparation_id, "Preparation")
                child_approvals = receipts_of("approve", "/v1/preparations/" + preparation_id)
                assert len(child_approvals) == 1 and child_approvals[0][1]["state"] not in ("refused", "unresolved"), (
                    "the approval of the child", operation, child_approvals)
                assert child_preparation["requestId"] == request_id and child_preparation["state"] == "consumed" \
                    and child_preparation["review"]["lineage"] == {"parentRunId": parent, "operation": operation, "edits": edits}, (
                    "the review lineage of the child", operation, child_preparation["state"], child_preparation["review"].get("lineage"))
                child_run, _, _ = observed("/v1/runs/" + run_id, "Run")
                assert child_run["parentRunId"] == parent and child_run["lineage"] == operation, (
                    "the child run", operation, child_run["parentRunId"], child_run["lineage"])
                succeeded(run_id)
                stored = "" if verify_store is None else ", " + verify_store()
                print(f"PASS pi-client {number}: /wfm-{operation} sent the one {operation} command", ui[operation + "Command"], "of run", parent,
                      "with child request", request_id, ", the approval of its exact review with the", operation, "lineage" +
                      ("" if not edits else " and the edits " + json.dumps(edits)), "started run", run_id,
                      ", which succeeded and names the parent run and the lineage", operation + stored, flush=True)

            assert ui["restartParentRunId"] == ui["literalRunId"], ("the restart parent", ui["restartParentRunId"])
            lineage_child("restart", 10, [])
            assert ui["resumeParentRunId"] == ui["capturedRunId"], ("the resume parent", ui["resumeParentRunId"])
            lineage_child("resume", 11, [])
            # The fork edit commits to the SHA-256 of the JSON encoding of the replacement answer.
            fork_sha256 = hashlib.sha256(json.dumps(PI_UI_FORKED, ensure_ascii=False, separators=(",", ":")).encode("utf-8")).hexdigest()
            assert ui["forkParentRunId"] == ui["restartRunId"] and ui["forkSha256"] == fork_sha256, (
                "the fork parent and edit", ui["forkParentRunId"], ui["forkSha256"], fork_sha256)
            fork_edits = [{"occurrenceId": ui["forkOccurrenceId"], "operation": "replace", "sha256": fork_sha256}]

            def fork_store():
                """Require that the supervisor manifest of the fork child names
                the parent run store and the edits, and that the run store of
                the child holds the replacement answer at the edited
                occurrence, where the parent run store holds another answer."""
                stores = work / "manager" / "runs" / "runs"
                [(child_native,)] = read_coordination("SELECT native_run_id FROM runs WHERE id=?", (ui["forkRunId"],))
                [(parent_native,)] = read_coordination("SELECT native_run_id FROM runs WHERE id=?", (ui["forkParentRunId"],))
                manifest = json.loads((stores / child_native / "supervisor-manifest.json").read_bytes())
                assert (manifest["lineage"], manifest["parentRunId"], manifest["lineageEdits"]) == ("fork", parent_native, fork_edits), (
                    "the supervisor manifest of the fork child", manifest["lineage"], manifest["parentRunId"], manifest["lineageEdits"])

                def answers(native):
                    return [(entry["answer"], entry.get("replaced", False)) for entry in json.loads(
                        (stores / native / "runtime" / "answers.json").read_bytes())["answers"] if entry["occurrenceId"] == ui["forkOccurrenceId"]]

                parent_answers, child_answers = answers(parent_native), answers(child_native)
                assert len(parent_answers) == 1 and parent_answers[0][0] != PI_UI_FORKED and child_answers == [(PI_UI_FORKED, True)], (
                    "the edited occurrence of the fork child", parent_answers, child_answers)
                return ("and its run store holds the replacement answer at occurrence " + ui["forkOccurrenceId"] +
                        " in place of the answer of the parent run")

            lineage_child("fork", 12, fork_edits, fork_store)
            history, observers, history_pages, target = [], 0, 0, "/v1/runs"
            while target is not None:
                status, value, raw = request(target, harness)
                assert status == 200, ("history page", target, status, value.get("code"))
                validate("RunPage", value, raw)
                assert value["page"]["index"] == history_pages, ("history page index", value["page"]["index"], history_pages)
                history_pages += 1
                history.extend(item["id"] for item in value["items"])
                observers += sum(1 for item in value["items"] if item["supervision"] == "observer")
                target = value["page"]["next"]
            children = [ui["restartRunId"], ui["resumeRunId"], ui["forkRunId"]]
            assert history_pages >= 2 and observers == LEGACY_ENTRIES and len(history) == len(set(history)), (
                "the history pages", history_pages, observers, len(history))
            assert history == ui["historyRuns"] and all(run in history for run in children), (
                "the /wfm-history runs differ from every page of /v1/runs", history, ui["historyRuns"])
            print("PASS pi-client 13: /wfm-history listed the", len(history), "runs of the", history_pages, "pages of /v1/runs, the",
                  LEGACY_ENTRIES, "legacy entries included, each once in the order of the collection, with the restart, resume and fork children",
                  flush=True)
            tool_declined = "/v1/preparations/" + ui["toolDeclinedPreparationId"]
            commands = [(receipt["operation"], receipt["state"], (receipt["effect"] or {}).get("kind"))
                        for _, receipt in ui_receipts if receipt["resource"] == tool_declined]
            assert commands == [("discard", "effect-observed", "discarded")], ("the commands of the declined tool review", commands)
            withdrawn, _, _ = observed("/v1/requests/" + ui["toolDeclinedRequestId"], "Request")
            assert withdrawn["phase"] == "withdrawn" and withdrawn["runId"] is None and withdrawn["readiness"]["supplied"] == [
                {"name": "input", "source": "literal", "value": PI_UI_TOOL_DECLINED}], ("the declined tool request", withdrawn["phase"], withdrawn["runId"])
            print("PASS pi-client 14: the tool start of request", ui["toolDeclinedRequestId"], "whose exact review the human declined has no",
                  "approve command for preparation", ui["toolDeclinedPreparationId"], ", and the later discard and withdraw ended it", flush=True)
            tool_request, _, _ = observed("/v1/requests/" + ui["toolRequestId"], "Request")
            assert tool_request["readiness"]["supplied"] == [{"name": "input", "source": "literal", "value": PI_UI_TOOL_ANSWERED}] \
                and tool_request["runId"] == ui["toolRunId"] and tool_request["phase"] == "associated", ("the tool request", tool_request["runId"], tool_request["phase"])
            tool_preparation, _, _ = observed("/v1/preparations/" + ui["toolPreparationId"], "Preparation")
            tool_approvals = receipts_of("approve", "/v1/preparations/" + ui["toolPreparationId"])
            assert len(tool_approvals) == 1 and tool_approvals[0][1]["state"] not in ("refused", "unresolved") and tool_preparation["state"] == "consumed" \
                and tool_preparation["requestId"] == ui["toolRequestId"], ("the approval of the tool review", tool_approvals, tool_preparation["state"])
            tool_answers = receipts_of("answer", "/v1/decisions/" + ui["toolAnsweredDecisionId"])
            tool_retries = receipts_of("retry", "/v1/runs/" + ui["toolRunId"] + "/control")
            assert [uri for uri, _ in tool_answers] == [ui["toolAnswerCommand"]] and [uri for uri, _ in tool_retries] == [ui["toolRetryCommand"]] \
                and all(receipt["state"] == "effect-observed" for _, receipt in tool_answers + tool_retries), (
                "the answer and retry commands of the tool run", [uri for uri, _ in tool_answers], [uri for uri, _ in tool_retries], ui)
            assert person_answers(PI_UI_TOOL_ANSWERED) == [False], ("the run store of the tool run", person_answers(PI_UI_TOOL_ANSWERED))
            succeeded(ui["toolRunId"])

            def transitions(request_id, decision_id, run_id):
                """The operations of the commands of a request, its approved preparation, its answered decision and the controls of its
                run, in receipt order. An associated request names no preparation, so the approval names it."""
                approved = [receipt["resource"] for _, receipt in ui_receipts
                            if receipt["operation"] == "approve" and observed(receipt["resource"], "Preparation")[0]["requestId"] == request_id]
                assert len(approved) == 1, ("the approvals of request", request_id, approved)
                resources = ("/v1/requests/" + request_id, approved[0], "/v1/decisions/" + decision_id, "/v1/runs/" + run_id + "/control")
                return [receipt["operation"] for _, receipt in ui_receipts if receipt["resource"] in resources]

            human_path = transitions(ui["monitoredRequestId"], ui["answeredDecisionId"], ui["monitoredRunId"])
            tool_path = transitions(ui["toolRequestId"], ui["toolAnsweredDecisionId"], ui["toolRunId"])
            assert tool_path == human_path == ["set-input", "enqueue", "approve", "answer", "retry"], ("the tool and human transitions", tool_path, human_path)
            print("PASS pi-client 15: the tool request", ui["toolRequestId"], "supplied exactly its literal, its one confirmed approval consumed preparation",
                  ui["toolPreparationId"], ", the confirmed tool answer", ui["toolAnswerCommand"], "is recorded as JSON false in the run store,",
                  "the confirmed tool retry", ui["toolRetryCommand"], "reached its effect, run", ui["toolRunId"], "succeeded, and the tool and the",
                  "human path reached the same manager transitions", tool_path, flush=True)
            ui_stores = set(run_prompts)
            report = vitest("test/manager-live.test.ts", tui_fixture.client_profile, report_path, log_path, 7)
            assert report["reconnectLastEventId"] == report["reconnectCursor"] and report["pollEvents"] > 0, ("report delivery", report)
            print("PASS pi-client 16: the ext-pi session ran its seven steps against the protected endpoint, the forced SSE drop",
                  "resumed with Last-Event-ID", report["reconnectCursor"], "and", report["events"], "delivered events, of which",
                  report["pollEvents"], "came through polling, equal the polling listing", flush=True)
            status, requests, _ = request("/v1/requests", harness)
            assert status == 200 and sorted(item["id"] for item in requests["items"]) == sorted(
                [report["requestId"], report["secondRequestId"], ui["literalRequestId"], ui["capturedRequestId"], ui["declinedRequestId"],
                 ui["monitoredRequestId"], ui["staleRequestId"], ui["cancelledRequestId"], ui["restartRequestId"], ui["resumeRequestId"],
                 ui["forkRequestId"], ui["toolDeclinedRequestId"], ui["toolRequestId"]]), (
                "the manager holds other than the requests of the two checks", status)
            submitted, _, _ = observed("/v1/requests/" + report["requestId"], "Request")
            expected = [{"name": declaration["name"], "source": "literal", "value": MIXED_TEXT} for declaration in workflow["inputs"]]
            assert submitted["readiness"]["supplied"] == expected, ("the request did not supply exactly the literal", submitted["readiness"])
            assert submitted["runId"] == report["runId"] and submitted["phase"] == "associated", (
                "the request does not name the run", submitted["runId"], submitted["phase"])
            print("PASS pi-client 17: request", report["requestId"], "supplied exactly the Unicode literal and names run", report["runId"],
                  flush=True)
            receipts = command_receipts(session_cursor, harness)
            answers = [(uri, receipt) for uri, receipt in receipts if receipt["operation"] == "answer"]
            retries = [(uri, receipt) for uri, receipt in receipts if receipt["operation"] == "retry"]
            assert [uri for uri, _ in answers] == [report["answerCommand"]] and [uri for uri, _ in retries] == [report["retryCommand"]], (
                "the answer and retry commands differ from the report", [uri for uri, _ in answers], [uri for uri, _ in retries])
            assert all(receipt["state"] == "effect-observed" for _, receipt in answers + retries), ("a command did not reach its effect",)
            # Only the run stores of the session check count here.
            answer_files = sorted(set(work.glob("manager/runs/runs/*/runtime/answers.json")) - ui_stores)
            assert 1 <= len(answer_files) <= 2, ("run store answers", answer_files)
            # The run stores also record the model answers of the runs, so
            # only the entries of the occurrence that the answer command
            # addressed count. The second run waits at that occurrence, so it
            # has no entry for it.
            answer_receipt = answers[0][1]
            occurrence = (((answer_receipt["effect"] or {}).get("address") or {}).get("occurrenceId")
                          or (answer_receipt["acknowledgement"] or {}).get("occurrenceId"))
            assert occurrence is not None, ("the answer receipt names no occurrence", answer_receipt)
            recorded = [entry["answer"] for path in answer_files for entry in json.loads(path.read_bytes())["answers"]
                        if entry["occurrenceId"] == occurrence]
            assert recorded == [False], ("the run store does not record the answer as JSON false", occurrence, recorded)
            print("PASS pi-client 18: the run store records the answer as JSON false, and answer command", report["answerCommand"],
                  "and retry command", report["retryCommand"], "reached their effects", flush=True)
            snapshot, _, _ = observed("/v1/runs/" + report["runId"] + "/snapshot", "RunSnapshot")
            assert snapshot["runtime"] is not None and snapshot["runtime"]["status"] == "succeeded", ("run status", snapshot["runtime"])
            artifact = verified_download(report["runId"], client, harness)
            assert int(artifact["bytes"]) == report["resultBytes"] and artifact["sha256"] == report["resultSha256"], (
                "the ext-pi result differs from the harness download", artifact["bytes"], artifact["sha256"], report)
            print("PASS pi-client 19: run", report["runId"], "succeeded, and the verified result of", artifact["bytes"],
                  "bytes has the SHA-256", artifact["sha256"], "of the ext-pi download", flush=True)
            second = report["secondRunId"]
            secondary, _, _ = observed("/v1/requests/" + report["secondRequestId"], "Request")
            assert secondary["runId"] == second and secondary["phase"] == "associated", (
                "the second request does not name the second run", secondary["runId"], secondary["phase"])
            snapshot, _, _ = observed("/v1/runs/" + second + "/snapshot", "RunSnapshot")
            assert snapshot["runtime"] is not None and snapshot["runtime"]["status"] == "running" and snapshot["supervision"] == "owned", (
                "the second run does not keep running under owned supervision after the extension closed",
                snapshot["runtime"], snapshot["supervision"])
            control, _, _ = observed("/v1/runs/" + second + "/control", "RunControl")
            assert control["decisionHeadId"] is not None, ("the second run has no pending decision head", control)
            head, _, _ = observed("/v1/decisions/" + control["decisionHeadId"], "Decision")
            assert head["state"] == "pending" and head["kind"] == "question", ("the question of the second run is not pending", head["state"])
            print("PASS pi-client 20: after the extension and the session closed during their live streams, run", second,
                  "is still running under owned supervision, and its question", control["decisionHeadId"], "is pending", flush=True)
        print("PASS pi-client: the /wfm human path and the ext-pi manager session completed their journeys through the protected",
              "HTTPS endpoint, and the harness confirmed each step from manager facts, with no mutation except its first answer of the stale-answer step",
              flush=True)
    finally:
        if process.poll() is None:
            process.terminate()
        process.wait(timeout=25)


def client_controls_hold(runs):
    """Create and approve the two held runs of a client-controls mode with
    the credential of the harness: a mixed-controls run of profile_steer,
    once its controls offer a steer, and then a mixed-controls run of
    profile_live. Returns the steer run, the redirect run and the run store
    of the redirect run."""
    steer = runs.start("profile_steer")
    runs.offered(steer, lambda value: any(offer["operation"] == "steer" for offer in value["offers"]))
    before = set(work.glob("manager/runs/runs/*/runtime"))
    redirect = runs.start("profile_live")
    return steer, redirect, runs.new_store(before)


def client_controls_confirm(runs, steer, redirect, store, facts, steer_name, redirect_name):
    """Confirm the steer and the redirect that the client of a
    client-controls mode sent for the runs of client_controls_hold, settle
    both runs and print one PASS line for each. facts names the steer
    command, occurrence, attempt and text, and the redirect command,
    occurrence, attempt and target, with the keys of the report of
    ext-pi/test/manager-controls-live.test.ts. steer_name and redirect_name
    name the client commands in the PASS lines."""
    mode = sys.argv[5]

    # 1. The steer reached the offered attempt, and the run log holds the steer record.
    command, occurrence, attempt = facts["steerCommand"], facts["steerOccurrenceId"], facts["steerAttemptId"]
    control, steers = runs.steered(steer, command, occurrence, attempt, facts["steerText"])
    runs.settle(steer, "succeeded")
    print(f"PASS {mode} 1: {steer_name} sent the one steer command", command, "of attempt", attempt, "of occurrence", occurrence,
          "of run", steer, "with the timing interrupt-now and its editor text; it reached the effect steered, the run log holds control",
          control["position"], "from the manager and steer record", steers[0]["position"], "with the typed text, and the run succeeded", flush=True)

    # 2. The live redirect stopped the held attempt, and the spare candidate answered.
    command, occurrence, target = facts["redirectCommand"], facts["redirectOccurrenceId"], facts["redirectTarget"]
    receipt = runs.one_control(redirect, "redirect", command)
    assert receipt["effect"]["kind"] == "redirected" and target.endswith("@spare"), ("redirect effect", receipt["effect"], target)
    runs.settle(redirect, "succeeded")
    completed = occurrence_of(runs.snapshot(redirect), occurrence)
    assert completed["state"] == "completed" and completed["source"] == "asked:" + target, (
        "live redirect answer source", completed["state"], completed["source"])
    attempts, redirected = attempt_events(store, occurrence)
    command_id = command.rsplit("/", 1)[1]
    assert [event["type"] for event in attempts] == ["attempt.started", "attempt.failed", "attempt.started", "attempt.completed"], (
        "live redirect attempts", attempts)
    assert command_id in attempts[1]["message"], ("the stopped attempt does not name the redirect command", attempts[1])
    assert [(event["controlId"], event["target"]) for event in redirected] == [(command_id, target)], ("occurrence.redirected events", redirected)
    records = runs.run_records(redirect)
    (work / (mode + "-redirect-routes.json")).write_text(json.dumps(records, default=str))
    control = runs.manager_control(records, command)
    questions = model_questions(records, occurrence)
    assert len(questions) == 2 and questions[0]["to"]["to"]["model"].endswith("@primary") and questions[1]["to"] == {"to": {"model": target}}, (
        "live redirect questions", [record["to"] for record in questions])
    assert questions[0]["position"] < control["position"] < questions[1]["position"], (
        "the run-log control is not between the two questions", questions[0]["position"], control["position"], questions[1]["position"])
    print(f"PASS {mode} 2: {redirect_name} sent the one live redirect command", command, "of occurrence", occurrence, "of run", redirect,
          "from attempt", facts["redirectAttemptId"], "to", target, "; it reached the effect redirected, the held attempt ended attempt.failed",
          "naming the command, the run log holds question", questions[0]["position"], "to", questions[0]["to"]["to"]["model"], ", control",
          control["position"], "from the manager and question", questions[1]["position"], "to", target, ", and the run succeeded with the",
          "answer of", target, flush=True)


def pi_client_controls_checks():
    """The pi-client-controls mode. See PI_CLIENT_CONTROLS for the steps."""
    harness = tui_fixture.harness
    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
    try:
        wait_ready(process)
        status, capabilities, _ = request("/v1/capabilities", harness)
        assert status == 200 and "control" in capabilities["scopes"], ("capabilities", status)
        runs = ControlHarness(harness, capabilities, PI_CLIENT_CONTROLS)
        steer, redirect, store = client_controls_hold(runs)
        report = run_vitest("test/manager-controls-live.test.ts",
                            {"AGENT_CAT_MANAGER_PROFILE": str(tui_fixture.client_profile),
                             "AGENT_CAT_MANAGER_STEER_RUN": steer, "AGENT_CAT_MANAGER_REDIRECT_RUN": redirect},
                            work / "pi-client-controls-report.json", work / "pi-client-controls-vitest.log", 3)
        assert [report["steerRunId"], report["redirectRunId"], report["steerText"]] == [steer, redirect, PI_CONTROLS_STEER_TEXT], (
            "the report names other runs or another steering text", report)
        client_controls_confirm(runs, steer, redirect, store, report, "/wfm-steer", "/wfm-redirect")
        print("PASS pi-client-controls: /wfm-steer and /wfm-redirect of the ext-pi extension sent only the offered controls, each once,",
              "through the protected HTTPS endpoint, and the harness confirmed both from manager facts", flush=True)
    finally:
        if process.poll() is None:
            process.terminate()
        process.wait(timeout=25)
        (work / "server-0.exit").write_text(str(process.returncode) + "\n")


def emacs_live(home, test, log_path, variables):
    """Start the batch Emacs of an Emacs mode. It runs the ERT test named
    test of emacs/wf-manager-live.el in WF_EMACS_DIR with Emacs -Q, an
    environment built from EMACS_ALLOWLIST and variables, HOME set to home
    and user-emacs-directory set to home/.emacs.d, with its output in the
    file log_path. Returns the Popen object and the open log file."""
    environment = {name: os.environ[name] for name in EMACS_ALLOWLIST if name in os.environ}
    environment.update(HOME=str(home), **variables)
    command = [emacs_program, "-Q", "--batch",
               "--eval", "(setq user-emacs-directory " + json.dumps(str(home / ".emacs.d") + "/") + ")",
               "-L", emacs_directory, "-l", "wf-manager-live",
               "--eval", "(ert-run-tests-batch-and-exit " + json.dumps(test) + ")"]
    log = log_path.open("wb")
    return subprocess.Popen(command, cwd=home, env=environment, stdin=subprocess.DEVNULL,
                            stdout=log, stderr=subprocess.STDOUT), log


def emacs_live_report(child, log_path, report_path, steps):
    """The report of a finished batch Emacs of an Emacs mode. It refuses a
    report of another harness version with one sentence, and it requires
    exit status 0, one passed ERT test and the steps in order."""
    text = log_path.read_text(errors="replace")
    report = json.loads(report_path.read_bytes()) if report_path.is_file() else None
    if report is not None and report.get("harnessVersion") != EMACS_HARNESS_VERSION:
        raise SystemExit(f"The {sys.argv[5]} mode requires harness version {EMACS_HARNESS_VERSION}, and the report of "
                         f"wf-manager-live.el states version {report.get('harnessVersion')!r}, so the agent-cat and "
                         "agent-workflows checkouts are not a matching pair.")
    assert child.returncode == 0, ("the Emacs live check failed", child.returncode, text[-4000:])
    assert re.search(r"Ran 1 tests?, 1 results? as expected, 0 unexpected", text) and report is not None, (
        "the Emacs live check did not run its one test", text[-4000:])
    assert report["steps"] == steps, ("the Emacs live check did not complete its steps", report["steps"])
    return report


def emacs_client_controls_checks():
    """The emacs-client-controls mode. See EMACS_CLIENT_CONTROLS for the steps."""
    harness = tui_fixture.harness
    mode = EMACS_CLIENT_CONTROLS
    report_path = work / (mode + "-report.json")
    log_path = work / (mode + "-ert.log")
    held_path = work / (mode + "-held.json")
    retried_path = work / (mode + "-retried.json")
    home = work / "emacs-home"
    home.mkdir(mode=0o700)
    (home / ".emacs.d").mkdir(mode=0o700)
    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
    try:
        wait_ready(process)
        status, capabilities, _ = request("/v1/capabilities", harness)
        assert status == 200 and "control" in capabilities["scopes"], ("capabilities", status)
        runs = ControlHarness(harness, capabilities, mode)
        observed = runs.client[0]
        steer, redirect, store = client_controls_hold(runs)
        retry = cancel = None
        retry_receipt = None
        child, log = emacs_live(home, "wf-manager-live-controls", log_path,
                                {"WF_MANAGER_PROFILE": str(tui_fixture.client_profile), "WF_MANAGER_STEER_RUN": steer,
                                 "WF_MANAGER_REDIRECT_RUN": redirect, "WF_MANAGER_HELD": str(held_path),
                                 "WF_MANAGER_RETRIED": str(retried_path), "WF_MANAGER_REPORT": str(report_path)})
        try:
            deadline = time.monotonic() + 600
            while child.poll() is None:
                assert time.monotonic() < deadline, "the Emacs live check exceeded 600 seconds"
                if retry is None and held_path.is_file():
                    # The check has sent the steer and the redirect. The
                    # harness confirms both and settles both runs, then
                    # starts the run of the retry and the run of the cancel.
                    facts = json.loads(held_path.read_bytes())
                    assert facts["steerText"] == EMACS_CONTROLS_STEER_TEXT, ("the steering text of the check", facts["steerText"])
                    client_controls_confirm(runs, steer, redirect, store, facts, "wf-control steer", "wf-control redirect")
                    retry = runs.start("profile_1")
                    recovery = runs.until_recovery(retry)
                    assert any(offer["operation"] == "retry" for offer in runs.offered(retry, lambda value: True)["offers"]), (
                        "the recovery of the retry run offers no retry", recovery["choices"])
                    cancel = runs.start("profile_steer")
                    runs.offered(cancel, lambda value: value["cancelAllowed"] and value["supervision"] == "owned"
                                 and any(offer["operation"] == "steer" for offer in value["offers"]))
                    written = held_path.with_name(held_path.name + ".tmp")
                    written.write_text(json.dumps({"retryRunId": retry, "cancelRunId": cancel}))
                    os.replace(written, held_path.with_name(held_path.name + ".done"))
                if retry is not None and retry_receipt is None and retried_path.is_file():
                    # The check has sent the retry. It is the only command of
                    # the controls of the run, and it reached its effect.
                    command = json.loads(retried_path.read_bytes())["retryCommand"]
                    rows = runs.command_rows(["/v1/runs/" + retry + "/control"])
                    assert [(row[0], row[1], row[2]) for row in rows] == [(command.rsplit("/", 1)[1], "retry", "effect-observed")], (
                        "the check did not send exactly one retry that reached its effect", rows)
                    retry_receipt, _, raw = observed(command, "CommandReceipt")
                    (work / (mode + "-retry-receipt.json")).write_bytes(raw)
                    assert retry_receipt["effect"]["kind"] == "retried" \
                        and retry_receipt["effect"]["address"]["occurrenceId"] == recovery["address"]["occurrenceId"], (
                        "retry effect", retry_receipt["effect"], recovery["address"])
                    runs.settle(retry, "succeeded")
                    retried_path.with_name(retried_path.name + ".done").write_text("{}")
                time.sleep(0.05)
        finally:
            if child.poll() is None:
                child.kill()
                child.wait()
            log.close()
        report = emacs_live_report(child, log_path, report_path, ["steer", "redirect", "retry", "cancel"])
        # 3. The retry.
        assert report["retryRunId"] == retry and "retry" in report["retryChoices"] \
            and "Terminal: succeeded" in report["retryFinalLines"], ("the retry step", report["retryChoices"], report["retryFinalLines"])
        print(f"PASS {mode} 3: wf-control listed", report["retryChoices"], "for run", retry, "at its recovery decision", recovery["id"],
              "and sent the one retry command", report["retryCommand"], "; it reached the effect retried, the run succeeded, and the view",
              "showed Terminal: succeeded", flush=True)
        # 4. The declined and the confirmed cancel.
        rows = runs.command_rows(["/v1/runs/" + cancel + "/control"])
        assert [(row[0], row[1]) for row in rows] == [(report["cancelCommand"].rsplit("/", 1)[1], "cancel")] \
            and rows[0][3] is not None and rows[0][3]["state"] in ("accepted", "queued", "delivered"), (
            "the check did not send exactly one cancel that the runtime accepted", rows)
        runs.ended(cancel, "cancelled")
        assert report["declinedSent"] == [] and "cancel" in report["cancelChoices"] \
            and "Terminal: cancelled" in report["cancelFinalLines"], (
            "the cancel step", report["declinedSent"], report["cancelChoices"], report["cancelFinalLines"])
        print(f"PASS {mode} 4: wf-kill with the answer no sent nothing, and wf-control then sent the one cancel command",
              report["cancelCommand"], "of run", cancel, "after the answer yes; the runtime acknowledgement is", rows[0][3]["state"],
              ", the run ended cancelled, and the view showed Terminal: cancelled", flush=True)
        # 5. Only the offered controls, each once.
        sent = report["controlCommands"]
        expected = [("/v1/runs/" + run + "/control", operation) for run, operation in
                    ((steer, "steer"), (redirect, "redirect"), (retry, "retry"), (cancel, "cancel"))]
        assert [(item["resource"], item["body"]["operation"]) for item in sent] == expected \
            and all(item["media"] == "application/json" and item["ifMatch"].startswith('"') for item in sent), (
            "the commands of the check", sent)
        listings = {"steer": report["steerChoices"], "redirect": report["redirectChoices"],
                    "retry": report["retryChoices"], "cancel": report["cancelChoices"]}
        assert all(any(label == operation or label.startswith(operation + ":") for label in listings[operation])
                   for operation in listings), ("a sent control was not a listed choice", listings)
        commands = {run: [(row[1], row[2]) for row in runs.command_rows(["/v1/runs/" + run + "/control"])]
                    for run in (steer, redirect, retry, cancel)}
        assert [len(rows) for rows in commands.values()] == [1, 1, 1, 1] \
            and [rows[0][0] for rows in commands.values()] == ["steer", "redirect", "retry", "cancel"], (
            "the controls of the four runs", commands)
        print(f"PASS {mode} 5: the check sent exactly the offered steer, redirect, retry and cancel, each once with the entity tag",
              "of the controls as If-Match, each a choice that wf-control listed, and the coordination database holds exactly",
              commands, flush=True)
        print(f"PASS {mode}: wf-control and wf-kill of the service mode of wf.el sent only the offered controls, each once,",
              "through the protected HTTPS endpoint, and the harness confirmed each from manager facts", flush=True)
    finally:
        if process.poll() is None:
            process.terminate()
        process.wait(timeout=25)
        (work / "server-0.exit").write_text(str(process.returncode) + "\n")


def emacs_client_checks():
    """The emacs-client mode. See EMACS_CLIENT for the steps."""
    def all_requests():
        # The page drafts make /v1/requests a page set of several pages, so
        # the harness reads every page.
        listed, following = [], "/v1/requests"
        while following is not None:
            status, page, raw = request(following, harness)
            assert status == 200, ("requests", following, status)
            validate("RequestPage", page, raw)
            listed += page["items"]
            following = page["page"]["next"]
        return listed
    harness = tui_fixture.harness
    profile_path = tui_fixture.client_profile
    profile = json.loads(profile_path.read_bytes())
    report_path = work / "emacs-client-report.json"
    log_path = work / "emacs-client-ert.log"
    revoke_path = work / "emacs-client-revoke.json"
    revoked_path = work / "emacs-client-revoke.json.done"
    run_path = work / "emacs-client-run.json"
    ran_path = work / "emacs-client-run.json.done"
    finish_path = work / "emacs-client-finish.json"
    finished_path = work / "emacs-client-finish.json.done"
    download_path = work / "emacs-client-download.bin"
    answer_path = work / "emacs-client-answer.json"
    drive_path = work / "emacs-client-drive.json"
    home = work / "emacs-home"
    home.mkdir(mode=0o700)
    (home / ".emacs.d").mkdir(mode=0o700)
    # A local port that a listener held and released has no listener.
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as probe:
        probe.bind(("127.0.0.1", 0))
        closed_port = probe.getsockname()[1]
    unreachable_path = work / "client-profile-emacs-unreachable.json"
    unreachable_path.write_text(json.dumps({"version": 1, "endpoint": f"https://127.0.0.1:{closed_port}/v1",
                                            "credentialFile": str(work / "credential-emacs-second"), "caFile": str(cert)}))
    unreachable_path.chmod(0o600)
    saved_path = work / "emacs-client-saved-result.bin"
    clone_legacy_runs(legacy_frontend_run(), LEGACY_ENTRIES - 1)
    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "--legacy-history", f"{LEGACY_ROOT}=profile_1",
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
    try:
        with harness_reads_only():
            wait_ready(process)
            # The second client credential of the same manager and its profile.
            second_path = tui_fixture.renew("emacs-second")
            # The third client credential, whose profile the history step
            # switches to.
            third_path = tui_fixture.renew("emacs-third")
            second_client = {"Authorization": "Bearer " + (work / "credential-emacs-second").read_bytes().decode("ascii")}
            status, capabilities, _ = request("/v1/capabilities", harness)
            assert status == 200, ("capabilities", status)
            status, catalogue, _ = request("/v1/workflows?profileId=profile_1", harness)
            assert status == 200, ("catalogue", status)
            workflow = next(item for item in catalogue["items"] if item["name"] == "mixed-controls")
            status, overview, _ = request("/v1/snapshot", harness)
            assert status == 200 and not overview["items"], ("the overview is not empty before the check", status)
            cursor = overview["cursor"]
            views_client = mixed_client(capabilities, harness)
            harness_answers = []

            def harness_answer(handshake):
                """Answer the decision that the handshake file names with JSON
                false with the harness credential, wait until the command
                reaches its effect, and write the command to the file with the
                suffix .done."""
                named = json.loads(handshake.read_bytes())["decision"]
                decision, tag, _ = views_client[0](named, "Decision")
                assert decision["state"] == "pending" and decision["kind"] == "question", (
                    "the named decision", decision["state"], decision["kind"])
                body = {"operation": "answer", "occurrenceId": decision["address"]["occurrenceId"],
                        "generation": decision["generation"], "value": False}
                key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
                with harness_acts():
                    status, receipt, raw = request(named, harness | {"Content-Type": "application/json", "Idempotency-Key": key,
                                                                     "If-Match": tag},
                                                   method="POST", payload=json.dumps(body, separators=(",", ":")).encode())
                assert status == 202, ("the harness answer", status, receipt.get("code"))
                validate("CommandReceipt", receipt, raw)
                command = receipt["links"]["self"]
                deadline = time.monotonic() + 40
                while True:
                    settled, _, _ = views_client[0](command, "CommandReceipt")
                    if settled["state"] in ("effect-observed", "refused", "unresolved"):
                        break
                    assert time.monotonic() < deadline, ("the harness answer did not settle", settled["state"])
                    time.sleep(0.05)
                assert settled["state"] == "effect-observed", ("the harness answer", settled["state"], settled.get("refusal"))
                harness_answers.append((named, command))
                written = handshake.with_name(handshake.name + ".tmp")
                written.write_text(json.dumps({"command": command}))
                os.replace(written, handshake.with_name(handshake.name + ".done"))

            revoked = False
            run = listed = receipts = runs = started = closed = snapshot = driven = views_drive = None
            answered = recovered = 0
            child, log = emacs_live(home, "wf-manager-live-session", log_path,
                                    {"WF_MANAGER_PROFILE": str(profile_path), "WF_MANAGER_SECOND_PROFILE": str(second_path),
                                     "WF_MANAGER_UNREACHABLE_PROFILE": str(unreachable_path),
                                     "WF_MANAGER_REPORT": str(report_path), "WF_MANAGER_RUN": str(run_path),
                                     "WF_MANAGER_REVOKE": str(revoke_path), "WF_MANAGER_FINISH": str(finish_path),
                                     "WF_MANAGER_DOWNLOAD": str(download_path), "WF_MANAGER_ANSWER": str(answer_path),
                                     "WF_MANAGER_DRIVE": str(drive_path), "WF_MANAGER_THIRD_PROFILE": str(third_path),
                                     "WF_MANAGER_RESULT": str(saved_path)})
            with log:
                try:
                    deadline = time.monotonic() + 600
                    while child.poll() is None:
                        assert time.monotonic() < deadline, "the Emacs live check exceeded 600 seconds"
                        if run is None and run_path.is_file():
                            # The check has sent all its commands. The harness
                            # keeps the requests and the command receipts of
                            # the check, then acts: it creates and approves one
                            # run with its own credential.
                            listed = all_requests()
                            receipts = command_receipts(cursor, harness)
                            runs = ControlHarness(harness, capabilities, EMACS_CLIENT)
                            with harness_acts():
                                run = runs.start("profile_1")
                            started = command_receipts(cursor, harness)
                            ran_path.write_text(json.dumps({"runId": run}))
                        if run is not None and closed is None and finish_path.is_file():
                            # The check has closed its first session. The
                            # harness keeps the run and the command receipts,
                            # then drives the run to its terminal success, so
                            # that the check can export its result.
                            closed = command_receipts(cursor, harness)
                            snapshot = runs.snapshot(run)
                            with harness_acts():
                                _, answered, recovered = drive_mixed(run, runs.client, overview=False)
                            # The release of the worker after the terminal
                            # status changes the supervision of the run and
                            # with it the revision of the export collection.
                            runs.client[1]("/v1/runs/" + run, "Run",
                                           lambda value: value["supervision"] not in ("owned", "cleanup-pending"))
                            driven = command_receipts(cursor, harness)
                            finished_path.write_text("{}")
                        if answer_path.is_file() and not harness_answers:
                            # The check has opened the editor of the stale
                            # decision, and the harness answers it first.
                            harness_answer(answer_path)
                        if views_drive is None and drive_path.is_file():
                            # The check has killed the view of the stale run.
                            # The harness keeps the command receipts and the
                            # snapshot of that run, then drives both runs of
                            # the views step to their terminal success.
                            named = json.loads(drive_path.read_bytes())
                            before = command_receipts(cursor, harness)
                            stale_snapshot, _, _ = views_client[0]("/v1/runs/" + named["staleRunId"] + "/snapshot", "RunSnapshot")
                            with harness_acts():
                                for run_id in (named["answeredRunId"], named["staleRunId"]):
                                    drive_mixed(run_id, views_client, overview=False)
                            views_drive = (named, before, stale_snapshot, command_receipts(cursor, harness))
                            drive_path.with_name(drive_path.name + ".done").write_text("{}")
                        if not revoked and revoke_path.is_file():
                            # The one action of the harness during the check.
                            administration({"version": 1, "operation": "revoke-credential",
                                            "credentialId": tui_fixture.credential_ids["emacs-second"]})
                            revoked = True
                            revoked_path.write_text("{}")
                        time.sleep(0.05)
                finally:
                    if child.poll() is None:
                        child.kill()
                        child.wait()
            report = emacs_live_report(child, log_path, report_path,
                                       ["bind", "draft", "stale", "pages", "overview", "follow", "unreachable", "switch",
                                        "revoke", "close", "export", "service", "requests", "views", "lineage",
                                        "history"])
            assert report["prompts"] == 0, ("the Emacs live check prompted", report["prompts"])
            # 1. The binding.
            assert report["scheme"] == "https" and profile["endpoint"].startswith("https://127.0.0.1:"), (
                "the binding is not over TLS", report["scheme"], profile["endpoint"])
            assert re.fullmatch(r"[0-9a-f]{32}", report["endpointIdentity"]), ("endpoint identity", report["endpointIdentity"])
            assert report["authorityEpoch"] == capabilities["authorityEpoch"], (
                "the binding names another authority epoch", report["authorityEpoch"])
            print("PASS emacs-client 1: batch Emacs bound GET /v1/capabilities over TLS with the profile CA", profile["caFile"],
                  "with no prompt, endpoint identity", report["endpointIdentity"], "and authority epoch", report["authorityEpoch"], flush=True)
            # 2. The draft and its replay.
            request_id = report["requestId"]
            assert [report["createStatus"], report["replayStatus"], report["replayEqual"]] == [201, 201, True], (
                "the draft POST and its replay", report["createStatus"], report["replayStatus"], report["replayEqual"])
            assert report["workflowId"] == workflow["id"], ("the draft names another workflow", report["workflowId"])
            page_requests = report["pageRequests"]
            assert len(page_requests) == 3 and len(set(page_requests + [request_id])) == 4, ("the page drafts", page_requests)
            assert sorted(item["id"] for item in listed) == sorted([request_id] + page_requests) \
                and all(item["workflowId"] == workflow["id"] for item in listed), (
                "the manager does not hold exactly the drafts of the check", [item["id"] for item in listed])
            # The command events after the start cursor name one create
            # command of the draft and then the set-input command, so the
            # replay and the stale command left no command. The create and
            # set-input commands of the page drafts follow.
            assert [(receipt["operation"], receipt["resource"]) for _, receipt in receipts] == [
                ("create", "/v1/requests"), ("set-input", "/v1/requests/" + request_id)] + [
                pair for page in page_requests for pair in (("create", "/v1/requests"), ("set-input", "/v1/requests/" + page))], (
                "the commands of the check", [(resource, receipt["operation"]) for resource, receipt in receipts])
            print("PASS emacs-client 2: the draft POST with an Idempotency-Key gave 201, the same key gave 201 with the same draft",
                  request_id, "and the manager holds only that request of workflow mixed-controls, the three page drafts and one",
                  "create command for each", flush=True)
            # 3. The set-input command and the stale If-Match.
            status, current, raw, headers = fetch("/v1/requests/" + request_id, harness)
            assert status == 200, ("request", status)
            validate("Request", current, raw)
            assert current["readiness"]["supplied"] == [{"name": report["inputName"], "source": "literal", "value": EMACS_LITERAL}], (
                "the request did not supply exactly the literal", current["readiness"]["supplied"])
            assert report["literal"] == EMACS_LITERAL, ("the report names another literal", report["literal"])
            assert headers.get("etag") == report["currentTag"] and report["currentTag"] != report["staleTag"], (
                "entity tags", headers.get("etag"), report["currentTag"], report["staleTag"])
            assert report["setInputState"] == "effect-observed" and report["staleRefusal"] == [412, "stale-revision"], (
                "the set-input command and the stale refusal", report["setInputState"], report["staleRefusal"])
            assert receipts[1][0] == report["setInputCommand"] and receipts[1][1]["state"] == "effect-observed", (
                "the set-input command", receipts[1][0], receipts[1][1]["state"])
            print("PASS emacs-client 3: set-input command", report["setInputCommand"], "reached its effect and the request supplied",
                  "exactly the literal, and the second set-input with the earlier If-Match", report["staleTag"],
                  "received the typed refusal 412 stale-revision and left no command", flush=True)
            # 4. The page drafts and the overview of all pages.
            for page in page_requests:
                status, value, raw = request("/v1/requests/" + page, harness)
                assert status == 200, ("page draft", page, status)
                validate("Request", value, raw)
                assert [(item["source"], len(item["value"])) for item in value["readiness"]["supplied"]] == [
                    ("literal", EMACS_PAGE_CHARACTERS)], ("the page draft did not supply its literal", page)
            # Each page draft fills more than half of a page of 1048576 bytes.
            assert report["overviewPages"] >= len(page_requests), ("the overview did not span the pages", report["overviewPages"])
            assert report["overviewRequests"] == sorted([request_id] + page_requests), (
                "the overview of the check names other requests", report["overviewRequests"])
            assert re.fullmatch(r"[A-Za-z0-9_-]{1,128}\.(0|[1-9][0-9]*)", report["overviewCursor"]), ("overview cursor", report["overviewCursor"])
            print("PASS emacs-client 4: the session assembled the overview over all its", report["overviewPages"], "pages before it",
                  "installed it, with the four drafts of the check as its request members and the cursor", report["overviewCursor"], flush=True)
            # 5. The run of the harness through the follow loop.
            assert run is not None and report["followRunId"] == run, ("the followed run", run, report["followRunId"])
            assert [report["deliveryState"], report["generation"]] == ["poll", 0] and report["polls"] >= 1, (
                "the follow loop", report["deliveryState"], report["generation"], report["polls"])
            print("PASS emacs-client 5: run", run, "of the harness appeared in the overview of the session after",
                  report["polls"], "polling batches with no read of the check itself, with the delivery state poll and generation 0",
                  flush=True)
            # 6. The switch to the profile with no listener.
            assert report["unreachableFailure"] == "wf-manager-transport-unavailable" and report["unreachableKept"] is True, (
                "the unreachable switch", report["unreachableFailure"], report["unreachableKept"])
            assert report["pollsAfterUnreachable"] >= report["pollsBeforeUnreachable"] + 2, (
                "the follow loop after the unreachable switch", report["pollsBeforeUnreachable"], report["pollsAfterUnreachable"])
            print("PASS emacs-client 6: the switch to port", closed_port, "with no listener failed with",
                  "wf-manager-transport-unavailable, and the session kept its binding and polled from",
                  report["pollsBeforeUnreachable"], "to", report["pollsAfterUnreachable"], "batches", flush=True)
            # 7. The switch to the second profile.
            assert re.fullmatch(r"[0-9a-f]{32}", report["switchIdentity"]) and report["switchIdentity"] != report["endpointIdentity"], (
                "the identity of the second binding", report["switchIdentity"], report["endpointIdentity"])
            assert report["switchEpoch"] == capabilities["authorityEpoch"], ("the epoch of the second binding", report["switchEpoch"])
            assert report["switchGeneration"] > report["generation"], ("the generation of the switch", report["switchGeneration"])
            # The run of the harness adds its own request to the drafts of the check.
            # The requests step creates three more requests after this step.
            created = [report["literalRequestId"], report["capturedRequestId"], report["declinedRequestId"],
                       report["answeredRequestId"], report["staleRequestId"]] + [
                           report[prefix + "RequestId"] for prefix in ("restart", "resume", "rerun", "fork")]
            held = sorted(item["id"] for item in all_requests() if item["id"] not in created)
            assert len(held) == 5 and set([request_id] + page_requests) <= set(held), ("the requests after the check", held)
            assert report["switchOverviewRequests"] == held and report["switchOverviewRuns"] == [run], (
                "the overview of the second binding", report["switchOverviewRequests"], report["switchOverviewRuns"])
            assert report["resolvedReferences"] == report["overviewItems"] >= 5, (
                "the references of the second overview", report["resolvedReferences"], report["overviewItems"])
            assert report["delayedReads"] >= 1 and report["delayedOverwrote"] is False, (
                "the delayed read of the earlier generation", report["delayedReads"], report["delayedOverwrote"])
            assert report["earlierRefusal"] == ["wf-manager-wrong-endpoint", "wf-manager-wrong-endpoint"] \
                and report["switchDelivery"] == "poll", ("the earlier reference", report["earlierRefusal"], report["switchDelivery"])
            print("PASS emacs-client 7: the switch to the second credential", tui_fixture.credential_ids["emacs-second"],
                  "committed with endpoint identity", report["switchIdentity"], "and generation", report["switchGeneration"],
                  "after its overview of", report["overviewItems"], "members loaded, every member reference read 200,",
                  report["delayedReads"], "delayed read(s) of the earlier generation changed nothing, a reference of the first binding",
                  "was refused as wrong-endpoint, and the second binding polls", flush=True)
            # 8. The revoked second credential.
            assert revoked and report["revokedRefusal"] == [401, "unauthenticated"], ("the revoked read", revoked, report["revokedRefusal"])
            assert report["followEnd"] == "refused", ("the follow loop after the revocation", report["followEnd"])
            status, refused, _ = request("/v1/snapshot", second_client)
            assert status == 401 and refused["code"] == "unauthenticated", ("the harness read with the revoked credential", status)
            print("PASS emacs-client 8: after the harness revoked credential", tui_fixture.credential_ids["emacs-second"],
                  "the follow loop of the session ended refused and the next read of batch Emacs received the typed refusal",
                  "401 unauthenticated with no prompt", flush=True)
            # 9. The kill of the reference buffer and the close.
            assert [report["processesAfterClose"], report["buffersAfterClose"], report["timersAfterClose"],
                    report["bufferKilled"], report["directoryRemoved"]] == [0, [], 0, True, True], (
                "the session left a process, a buffer, a timer or a directory", report["processesAfterClose"],
                report["buffersAfterClose"], report["timersAfterClose"], report["bufferKilled"], report["directoryRemoved"])
            assert snapshot["runtime"] is None or snapshot["runtime"]["status"] not in ControlHarness.TERMINAL, (
                "the run ended during the check", snapshot["runtime"])
            assert [(resource, receipt["operation"]) for resource, receipt in closed] == [
                (resource, receipt["operation"]) for resource, receipt in started], (
                "the check sent a command after the run handshake", [(resource, receipt["operation"]) for resource, receipt in closed])
            assert not any(receipt["operation"] == "cancel" for _, receipt in closed), "a cancel command exists"
            print("PASS emacs-client 9: after the kill of a buffer that holds a session reference and the close, no network",
                  "process, url.el buffer, timer or transport directory remains, run", run, "has not ended, and the",
                  len(closed), "command receipts after the start cursor are those of the run handshake with no cancel command",
                  flush=True)
            print("PASS emacs-client 10: run", run, "then succeeded after", answered, "answer(s) and", recovered,
                  "retry(s) of the harness", flush=True)
            # 11. The export command, its receipt and the verified download.
            command_uri = report["exportCommand"]
            assert report["exportSent"] == "delivered" and re.fullmatch(r"/v1/commands/[A-Za-z0-9_-]{1,128}", command_uri), (
                "the export send", report["exportSent"], command_uri)
            final = command_receipts(cursor, harness)
            assert [resource for resource, _ in final][:len(driven) + 1] == [resource for resource, _ in driven] + [command_uri], (
                "the commands after the drive", [resource for resource, _ in final][len(driven):])
            status, receipt, raw = request(command_uri, harness)
            assert status == 200, ("export receipt", status)
            validate("CommandReceipt", receipt, raw)
            assert receipt["operation"] == "export" and receipt["resource"] == "/v1/runs/" + run + "/exports" \
                and receipt["state"] == "effect-observed" == report["exportState"], (
                "the export receipt", receipt["operation"], receipt["resource"], receipt["state"])
            assert receipt["effect"]["kind"] == "exported" and receipt["effect"]["resource"] == report["exportResource"], (
                "the export effect", receipt["effect"], report["exportResource"])
            status, detail, raw = request(report["exportResource"], harness)
            assert status == 200, ("export", status)
            validate("ExportReceipt", detail, raw)
            assert detail["state"] == "published" and detail["runId"] == run and detail["commandId"] == receipt["id"] \
                and detail["download"] == report["exportDownload"], ("the export", detail["state"], detail["download"])
            connection = http.client.HTTPSConnection("127.0.0.1", port, context=context, timeout=15)
            try:
                connection.request("GET", detail["download"], headers=harness | {"Accept": "application/octet-stream"})
                response = connection.getresponse()
                downloaded = response.read(int(detail["bytes"]) + 1)
                assert response.status == 200 and response.getheader("Content-Type") == "application/octet-stream", (
                    "the harness download", response.status)
            finally:
                connection.close()
            (work / "emacs-client-harness-download.bin").write_bytes(downloaded)
            assert len(downloaded) == int(detail["bytes"]) and hashlib.sha256(downloaded).hexdigest() == detail["sha256"], (
                "the harness download differs from the export", len(downloaded), detail["bytes"])
            assert download_path.read_bytes() == downloaded and report["downloadBytes"] == len(downloaded) \
                and report["downloadSha256"] == detail["sha256"], ("the Emacs download differs from the harness download",
                                                                    report["downloadBytes"], report["downloadSha256"])
            assert [report["wrongDigestRefusal"], report["wrongSizeRefusal"]] == ["wf-manager-invalid-response"] * 2, (
                "the downloads with a wrong digest or size", report["wrongDigestRefusal"], report["wrongSizeRefusal"])
            print("PASS emacs-client 11: export command", command_uri, "of run", run, "reached its receipt with the state",
                  "effect-observed and the effect", report["exportResource"], "which the harness read, the verified download of",
                  detail["download"], "matched the harness download of", len(downloaded), "bytes byte for byte, and a wrong",
                  "digest and a wrong size were each refused with wf-manager-invalid-response", flush=True)
            # 12. The service step.
            status, listed_profiles, raw = request("/v1/profiles", harness)
            assert status == 200 and listed_profiles["page"]["next"] is None, ("profiles", status)
            validate("ProfilePage", listed_profiles, raw)
            ready = sorted(item["id"] for item in listed_profiles["items"] if item["readiness"] == "ready")
            assert report["serviceProfiles"] == ready and ready, ("the profiles that wf-run listed", report["serviceProfiles"], ready)
            status, listed_workflows, raw = request("/v1/workflows?profileId=" + ready[0], harness)
            assert status == 200 and listed_workflows["page"]["next"] is None, ("workflows", status)
            validate("WorkflowPage", listed_workflows, raw)
            names = sorted(item["name"] for item in listed_workflows["items"])
            assert report["serviceWorkflows"] == names, ("the workflows that wf-run listed", report["serviceWorkflows"], names)
            assert report["serviceRunRefusal"] is None, ("the end of wf-run after the listings", report["serviceRunRefusal"])
            help_text = next(item["help"] for item in listed_workflows["items"] if item["name"] == "mixed-controls")
            assert report["serviceHelp"].endswith(help_text) and "mixed-controls" in report["serviceHelp"], (
                "the help text of wf-help", report["serviceHelp"][:400])
            refusals = report["serviceRefusals"]
            assert sorted(refusals) == sorted(EMACS_LOCAL_COMMANDS) and all(
                isinstance(refusals[name], str) and refusals[name].startswith(name + " works only in local mode")
                for name in EMACS_LOCAL_COMMANDS), ("the refusals of the local-only commands", refusals)
            assert all(re.search(r"the review of .wf-run.", refusals[name]) for name in ("wf-plan", "wf-cost")), (
                "wf-plan and wf-cost do not name the review of wf-run", refusals)
            assert report["serviceLocalCalls"] == 0, ("the local-only commands started a process or sent a request",
                                                      report["serviceLocalCalls"])
            # The commands after the export command are those of the requests
            # step, which step 13 states.
            sent = report["requestCommands"]
            requests_end = len(driven) + 1 + len(sent)
            later = [receipt for _, receipt in final[len(driven) + 1:requests_end]]
            operations = ["create" if item["resource"] == "/v1/requests" else
                          "capture" if item["resource"].startswith("/v1/captures?") else item["body"]["operation"]
                          for item in sent]
            assert [receipt["operation"] for receipt in later] == operations, (
                "the service step sent a command", [receipt["operation"] for receipt in later], operations)
            assert sorted(item["id"] for item in all_requests()) == sorted(held + created), (
                "the requests after the service step", sorted(item["id"] for item in all_requests()))
            diagnostics = report["serviceDiagnostics"]
            assert f"Endpoint: {profile['endpoint']}\n" in diagnostics \
                and f"Scopes: {', '.join(capabilities['scopes'])}\n" in diagnostics \
                and "Delivery state: poll\n" in diagnostics \
                and f"Endpoint identity: {report['serviceIdentity']}\n" in diagnostics, ("the diagnostics of wf-diagnostics", diagnostics)
            assert report["serviceLocal"] is True, ("wf-local", report["serviceLocal"])
            print("PASS emacs-client 12: in service mode, keys drove wf-service, and wf-run listed the profiles", ready,
                  "and the", len(names), "workflows of the catalogue that the harness reads, and C-g then ended it with no request",
                  "and no refusal, wf-help showed the catalogue help text, the", len(EMACS_LOCAL_COMMANDS), "local-only commands",
                  "refused with their messages and sent nothing, the commands after the export command are exactly",
                  "those of the requests step,",
                  "wf-diagnostics showed the endpoint, the scopes", capabilities["scopes"], "and the delivery state poll,",
                  "and wf-local closed the session", flush=True)
            # 13. The requests step: the literal reached the run program.
            selectors = ("reviewDigest", "requestRevision", "profileRevision", "descriptorRevision", "processGeneration")
            client = mixed_client(capabilities, harness)
            observed = client[0]

            def terminal(run_id):
                snapshot, _, _ = client[1]("/v1/runs/" + run_id + "/snapshot", "RunSnapshot",
                    lambda value: value["runtime"] is not None and value["runtime"]["status"] in ("succeeded", "failed", "cancelled"))
                assert snapshot["runtime"]["status"] == "succeeded", ("run status", run_id, snapshot["runtime"]["status"])

            def prompts():
                return [entry["question"].get("prompt") or "" for path in work.glob("manager/runs/runs/*/runtime/answers.json")
                        for entry in json.loads(path.read_bytes())["answers"]]

            literal, _, _ = observed("/v1/requests/" + report["literalRequestId"], "Request")
            assert literal["readiness"]["supplied"] == [{"name": "input", "source": "literal", "value": MIXED_TEXT}], (
                "the request did not supply exactly the literal", literal["readiness"]["supplied"])
            assert literal["runId"] == report["literalRunId"] and literal["phase"] == "associated", (
                "the literal request", literal["runId"], literal["phase"])
            terminal(report["literalRunId"])
            assert any(prompt.startswith("fixed-point source: " + MIXED_TEXT) for prompt in prompts()), (
                "the program did not receive the literal", prompts())
            literal_set = [item for item in sent if item["resource"] == "/v1/requests/" + report["literalRequestId"]
                           and item["body"].get("operation") == "set-input"]
            assert [item["body"]["input"] for item in literal_set] == [{"name": "input", "source": "literal", "value": MIXED_TEXT}], (
                "the set-input of the literal", literal_set)
            print("PASS emacs-client 13: in the setup form of wf-run, the keys typed the Unicode literal through the Multiline source,",
                  "the one set-input command sent its exact text, request", report["literalRequestId"], "supplied exactly MIXED_TEXT,",
                  "and run", report["literalRunId"], "succeeded with the literal as the input of its program", flush=True)
            # 14. The review buffer showed the exact review, and the only
            # approve command carries its selectors and entity tag.
            preparation, _, _ = observed("/v1/preparations/" + report["literalPreparationId"], "Preparation")
            text = report["literalReviewText"]
            assert preparation["state"] == "consumed" and preparation["reviewDigest"] == report["literalReviewDigest"], (
                "the literal preparation", preparation["state"], preparation["reviewDigest"])
            assert all(f"  {name}: {preparation[name]}\n" in text for name in selectors) \
                and f"  If-Match: {report['literalEtag']}\n" in text \
                and f"Program SHA-256: {preparation['review']['programHash']}\n" in text, (
                "the review buffer does not show the exact review", text[:2000])
            for prefix in ("literal", "captured"):
                resource = "/v1/preparations/" + report[prefix + "PreparationId"]
                approvals = [receipt for receipt in later if receipt["operation"] == "approve" and receipt["resource"] == resource]
                assert len(approvals) == 1 and approvals[0]["state"] not in ("refused", "unresolved"), (
                    "the approve command of the displayed review", prefix, approvals)
                approved, _, _ = observed(resource, "Preparation")
                bodies = [item for item in sent if item["resource"] == resource]
                assert bodies == [{"resource": resource, "media": "application/json", "ifMatch": report[prefix + "Etag"],
                                   "body": {"operation": "approve", **{name: approved[name] for name in selectors}}}], (
                    "the approve command does not name the exact review selectors", prefix, bodies)
                assert report[prefix + "Outcomes"] == ["approve", "run"], ("the review outcomes", prefix, report[prefix + "Outcomes"])
            print("PASS emacs-client 14: the review buffer of preparation", report["literalPreparationId"], "showed review digest",
                  report["literalReviewDigest"], "with every selector and the entity tag", report["literalEtag"], "that the harness",
                  "reads, and the one approve command of each of the two approved reviews carried its selectors and the entity tag",
                  "of its review as If-Match after the confirmation", flush=True)
            # 15. The capture reached the run program.
            captured, _, _ = observed("/v1/requests/" + report["capturedRequestId"], "Request")
            captured_bytes = EMACS_CAPTURED.encode("utf-8")
            captured_digest = hashlib.sha256(captured_bytes).hexdigest()
            supplied = captured["readiness"]["supplied"]
            assert len(supplied) == 1 and supplied[0]["source"] == "capture" and supplied[0]["name"] == "input", (
                "the captured-input request does not supply a capture", supplied)
            uploads = [item for item in sent if item["resource"] == "/v1/captures?requestId=" + report["capturedRequestId"]]
            assert uploads == [{"resource": uploads[0]["resource"], "media": "application/octet-stream", "ifMatch": None,
                                "body": {"bytes": len(captured_bytes), "sha256": captured_digest}}], ("the capture upload", uploads)
            assert report["capturedSha256"] == captured_digest and report["capturedBytes"] == len(captured_bytes), (
                "the captured file", report["capturedSha256"], report["capturedBytes"])
            capture_receipts = [receipt for receipt in later if receipt["operation"] == "capture"]
            assert len(capture_receipts) == 1, ("the capture commands", capture_receipts)
            assert captured["runId"] == report["capturedRunId"], ("captured request run", captured["runId"])
            terminal(report["capturedRunId"])
            assert "fixed-point source: " + captured_digest in prompts(), ("the program did not receive the captured bytes", prompts())
            print("PASS emacs-client 15: the File source uploaded", len(captured_bytes), "exact bytes with SHA-256", captured_digest,
                  "through POST /v1/captures as application/octet-stream, set-input bound capture", supplied[0]["captureId"],
                  "of request", report["capturedRequestId"], "and run", report["capturedRunId"],
                  "succeeded with that SHA-256 as the input of its program", flush=True)
            # 16. The declined review sent nothing, and its discard reached the effect.
            declined = "/v1/preparations/" + report["declinedPreparationId"]
            commands = [(receipt["operation"], receipt["state"], (receipt["effect"] or {}).get("kind"))
                        for receipt in later if receipt["resource"] == declined]
            assert commands == [("discard", "effect-observed", "discarded")], ("the commands of the declined preparation", commands)
            assert report["declinedSentAfterNo"] == [] and report["declinedOutcomes"] == ["discard", "withdraw"], (
                "the declined review", report["declinedSentAfterNo"], report["declinedOutcomes"])
            withdrawn, _, _ = observed("/v1/requests/" + report["declinedRequestId"], "Request")
            discarded, _, _ = observed(declined, "Preparation")
            assert withdrawn["phase"] == "withdrawn" and withdrawn["runId"] is None and discarded["state"] == "invalidated" \
                and discarded["reason"] == "discarded", ("the declined request", withdrawn["phase"], discarded["state"], discarded["reason"])
            print("PASS emacs-client 16: the answer no to the approval of preparation", report["declinedPreparationId"],
                  "sent nothing, so the preparation has no approve command, the discard key reached the effect discarded,",
                  "and the withdraw key withdrew request", report["declinedRequestId"], flush=True)
            # 17. The editor contents survived a refresh during setup.
            assert report["editorBefore"] == report["editorAfter"] == MIXED_TEXT and report["editorRedrawn"] is True, (
                "the setup form after the refresh", report["editorBefore"], report["editorAfter"], report["editorRedrawn"])
            print("PASS emacs-client 17: wf-refresh in the open setup form read the request again and drew new widgets,",
                  "and the typed literal stayed exactly MIXED_TEXT before and after the refresh", flush=True)
            # 18. The answer no of the views step reached its decision as JSON false.
            assert views_drive is not None, "the views step did not ask the harness to drive its runs"
            named, before_drive, stale_snapshot, after_drive = views_drive
            answered_run, stale_run = report["answeredRunId"], report["staleRunId"]
            assert named == {"answeredRunId": answered_run, "staleRunId": stale_run}, ("the drive handshake", named)
            answered_decision = "/v1/decisions/" + report["answeredDecisionId"]
            stale_decision = "/v1/decisions/" + report["staleDecisionId"]
            views_sent = report["viewsCommands"]
            views_receipts = final[requests_end:]

            def person_answers(literal):
                """The answers of the person question of every run whose input is the literal, from the run stores."""
                return [entry["answer"] for path in work.glob("manager/runs/runs/*/runtime/answers.json")
                        for entry in json.loads(path.read_bytes())["answers"]
                        if (entry["question"].get("prompt") or "").startswith("Independent confirmation? " + literal)]

            answers = [(uri, receipt) for uri, receipt in views_receipts
                       if receipt["operation"] == "answer" and receipt["resource"] == answered_decision]
            assert len(answers) == 1 and answers[0][1]["state"] == "effect-observed", (
                "the answer command of the answered run", [(uri, receipt["state"]) for uri, receipt in answers])
            bodies = [item for item in views_sent if item["resource"] == answered_decision]
            assert len(bodies) == 1 and bodies[0]["body"]["operation"] == "answer" and bodies[0]["body"]["value"] is False \
                and isinstance(bodies[0]["ifMatch"], str), ("the answer body of the run view", bodies)
            assert person_answers(EMACS_ANSWERED) == [False], ("the run store does not record JSON false", person_answers(EMACS_ANSWERED))
            print("PASS emacs-client 18: in the run view of run", answered_run, "wf-answer sent the answer no to decision",
                  report["answeredDecisionId"], "as JSON false with the entity tag", bodies[0]["ifMatch"], "as If-Match, its command",
                  answers[0][0], "reached effect-observed, and the run store records JSON false", flush=True)
            # 19. The decision that the harness answered first gave 412, and the draft stayed.
            assert harness_answers == [(stale_decision, report["harnessAnswerCommand"])], ("the harness answer", harness_answers)
            preempted = [(uri, receipt) for uri, receipt in views_receipts if receipt["resource"] == stale_decision]
            assert [uri for uri, _ in preempted] == [report["harnessAnswerCommand"]] \
                and preempted[0][1]["state"] == "effect-observed", (
                "the commands of the preempted decision", [(uri, receipt["state"]) for uri, receipt in preempted])
            stale_posts = [item for item in views_sent if item["resource"] == stale_decision]
            assert len(stale_posts) == 1 and stale_posts[0]["body"]["value"] is False, ("the stale answer of the run view", stale_posts)
            status, resolved, _ = request(stale_decision, harness)
            assert status == 404 and resolved["code"] == "unavailable-resource", ("the preempted decision is still served", status)
            refusal = report["staleAnswerRefusal"]
            assert isinstance(refusal, str) and (
                f"Decision {report['staleDecisionId']} changed before the answer arrived (412 stale-revision).  "
                "Nothing was sent again.  The draft \"no\" is kept.") in refusal \
                and "no longer the pending head (404 unavailable-resource), so the kept draft is not sent" in refusal, (
                "the report of the stale answer", refusal)
            assert report["staleAnswerDraft"] == "no", ("the kept draft", report["staleAnswerDraft"])
            assert person_answers(EMACS_STALE) == [False], ("the run store of the preempted run", person_answers(EMACS_STALE))
            print("PASS emacs-client 19: the harness answered decision", report["staleDecisionId"], "first with command",
                  report["harnessAnswerCommand"], "while the answer editor was open, the one answer of the run view received",
                  "412 stale-revision and left no command, and the draft no was kept and reported", flush=True)
            # 20. The kill of the view of a running run sent no command.
            def pair(item):
                resource = item["resource"]
                operation = "create" if resource == "/v1/requests" else item["body"]["operation"]
                return operation, resource

            expected = [pair(item) for item in views_sent if item is not stale_posts[0]]
            before = [(uri, receipt) for uri, receipt in before_drive[requests_end:]]
            assert [(receipt["operation"], receipt["resource"]) for uri, receipt in before
                    if uri != report["harnessAnswerCommand"]] == expected \
                and [uri for uri, _ in before].count(report["harnessAnswerCommand"]) == 1, (
                "the commands of the views step", [(receipt["operation"], receipt["resource"]) for _, receipt in before], expected)
            assert report["killedWatched"] is False, "the session still watches a resource of the killed view"
            assert stale_snapshot["runtime"] is not None and stale_snapshot["runtime"]["status"] not in (
                "succeeded", "failed", "cancelled", "orphaned"), ("the stale run ended after the kill", stale_snapshot["runtime"])
            assert not any(receipt["operation"] == "cancel" for _, receipt in final), "a cancel command exists"
            lineage_receipts = final[len(after_drive):]
            assert [uri for uri, _ in final[:len(after_drive)]] == [uri for uri, _ in after_drive] \
                and all(receipt["operation"] == "retry" for _, receipt in after_drive[len(before_drive):]), (
                "a command after the drive", [receipt["operation"] for _, receipt in final[len(before_drive):]])
            assert report["killEmacsClosed"] is True and report["viewsCommandsAfter"] == views_sent, (
                "the function of kill-emacs-hook", report["killEmacsClosed"])
            ended, _, _ = views_client[0]("/v1/runs/" + stale_run + "/snapshot", "RunSnapshot")
            assert ended["runtime"] is not None and ended["runtime"]["status"] == "succeeded", ("the stale run", ended["runtime"])
            print("PASS emacs-client 20: after the kill of the view of run", stale_run, "the run was still",
                  stale_snapshot["runtime"]["status"], "with no cancel command and no command of the check, and it then",
                  "succeeded, and the function of kill-emacs-hook closed only the transport", flush=True)
            # 21. Two run views followed their own runs, and the view ends with the Terminal and Result lines.
            waiting, stale_lines = report["answeredWaitingLines"], report["staleRecoveryLines"]
            answered_id, stale_id = report["answeredDecisionId"], report["staleDecisionId"]
            assert waiting[0].startswith("Service run " + answered_run) \
                and any(line.startswith("  Head " + answered_id + ": pending question") for line in waiting) \
                and not any(stale_run in line or stale_id in line for line in waiting), ("the view of the answered run", waiting)
            assert stale_lines[0].startswith("Service run " + stale_run) \
                and any(line.startswith("  Head ") and ": pending recovery" in line for line in stale_lines) \
                and not any(answered_run in line or answered_id in line or stale_id in line for line in stale_lines), (
                "the view of the stale run", stale_lines)
            assert any(line.startswith("  Head ") and ": pending recovery" in line for line in report["answeredRecoveryLines"]), (
                "the view of the answered run after the answer", report["answeredRecoveryLines"])
            final_lines = report["answeredFinalLines"]
            for prefix in ("Runtime: ", "Supervision: ", "Verification: ", "Decisions: ", "Offers: "):
                assert sum(line.startswith(prefix) for line in final_lines) == 1, ("the line of the view", prefix, final_lines)
            artifact = verified_download(answered_run, views_client, harness)
            harness_result = (work / "verified-result.json").read_bytes()
            assert final_lines[-3:] == ["Terminal: succeeded", "Result: verified " + str(int(artifact["bytes"])) + " bytes",
                                        "Result SHA-256: " + artifact["sha256"]], ("the outcome lines of the view", final_lines)
            print("PASS emacs-client 21: the views of runs", answered_run, "and", stale_run, "followed their own runs, one at",
                  "its question while the other was at its recovery, and the view of", answered_run, "ended with the Terminal",
                  "line and the Result lines of the verified", int(artifact["bytes"]), "bytes that the harness downloads", flush=True)
            # 22. wf-result saved the verified result once, with mode 0600.
            saved_stat = saved_path.lstat()
            saved = saved_path.read_bytes()
            assert report["resultFile"] == str(saved_path) and stat.S_ISREG(saved_stat.st_mode) \
                and stat.S_IMODE(saved_stat.st_mode) == 0o600 and report["resultMode"] == "600", (
                "the saved file", report["resultFile"], oct(saved_stat.st_mode), report["resultMode"])
            assert saved == harness_result and len(saved) == int(artifact["bytes"]) == report["resultBytes"] \
                and hashlib.sha256(saved).hexdigest() == artifact["sha256"] == report["resultSha256"], (
                "the saved result differs from the harness download", len(saved), report["resultBytes"], report["resultSha256"])
            assert isinstance(report["resultRefusal"], str) and str(saved_path) + " exists, so the result was not saved" in (
                report["resultRefusal"]) and report["resultKept"] is True, ("the second save", report["resultRefusal"], report["resultKept"])
            print("PASS emacs-client 22: in the view of run", answered_run, "that the history opened, wf-result saved", len(saved),
                  "bytes with SHA-256", artifact["sha256"], "and mode 0600 to", saved_path, "which equal the harness download,",
                  "and a second save to the same file was refused and left the file as it was", flush=True)
            # 23. wf-history listed every run of /v1/runs in the order of the collection.
            history, observers, history_pages = run_history(harness)
            managed = [run, report["literalRunId"], report["capturedRunId"], answered_run, stale_run]
            assert history_pages >= 2 and observers == LEGACY_ENTRIES and len(history) == len(set(history)) \
                and all(item in history for item in managed), ("the history pages", history_pages, observers, len(history))
            assert report["historyRuns"] == history and report["historyPages"] == history_pages \
                and report["historyObservers"] == LEGACY_ENTRIES, (
                "the wf-history rows differ from every page of /v1/runs", report["historyPages"], report["historyObservers"],
                len(report["historyRuns"]), len(history))
            assert report["historyViewLines"][0].startswith("Service run " + answered_run) \
                and "Terminal: succeeded" in report["historyViewLines"], ("the view that RET opened", report["historyViewLines"])
            print("PASS emacs-client 23: wf-history listed the", len(history), "runs of the", history_pages, "pages of /v1/runs, the",
                  LEGACY_ENTRIES, "legacy entries included, each once in the order of the collection, and RET opened the",
                  "read-only view of run", answered_run, flush=True)
            # 24. A history row of the first credential, opened after the
            # switch to the third credential, refused and was not retargeted.
            assert re.fullmatch(r"[0-9a-f]{32}", report["historyIdentity"]) \
                and re.fullmatch(r"[0-9a-f]{32}", report["historySwitchIdentity"]) \
                and report["historySwitchIdentity"] != report["historyIdentity"], (
                "the identities of the history step", report["historyIdentity"], report["historySwitchIdentity"])
            foreign = report["historyForeignRefusal"]
            assert isinstance(foreign, str) and f"The history row of run {answered_run} cannot be opened" in foreign \
                and "Reference of another endpoint" in foreign, ("the refusal of the row of the first endpoint", foreign)
            assert report["historyForeignReads"] == [] and report["historyForeignView"] is False, (
                "the row of the first endpoint was retargeted", report["historyForeignReads"], report["historyForeignView"])
            print("PASS emacs-client 24: after the switch to credential", tui_fixture.credential_ids["emacs-third"],
                  "with endpoint identity", report["historySwitchIdentity"], "RET on the history row of run", answered_run,
                  "of endpoint", report["historyIdentity"], "was refused with wrong-endpoint, and no read and no view of the run",
                  "followed on the new binding", flush=True)
            # 25 to 27. The lineage step: its commands are the commands
            # after the drive and its retries, in order.
            lineage_sent = report["lineageCommands"]

            def lineage_operation(item):
                return "export" if item["resource"].endswith("/exports") else item["body"]["operation"]

            assert [(receipt["resource"], receipt["operation"]) for _, receipt in lineage_receipts] == [
                (item["resource"], lineage_operation(item)) for item in lineage_sent] \
                and [uri for uri, _ in lineage_receipts] == [item["location"] for item in lineage_sent], (
                "the commands of the lineage step", [(receipt["resource"], receipt["operation"]) for _, receipt in lineage_receipts],
                [(item["resource"], item["location"]) for item in lineage_sent])
            fork_sha256 = hashlib.sha256(json.dumps(EMACS_FORKED, ensure_ascii=False, separators=(",", ":")).encode("utf-8")).hexdigest()
            fork_edits = [{"occurrenceId": report["forkOccurrenceId"], "operation": "replace", "sha256": fork_sha256}]

            def lineage_child(prefix, operation, parent, edits, index):
                """Require that the three commands of the child at index are its
                lineage command, its enqueue and the approve of its exact
                review, with the effects and facts that the manager states."""
                request_id, run_id, preparation_id = (report[prefix + "RequestId"], report[prefix + "RunId"],
                                                      report[prefix + "PreparationId"])
                lineage_uri = "/v1/runs/" + parent + "/lineage-requests"
                assert report[prefix + "ParentRunId"] == parent, ("the parent of the child", prefix, report[prefix + "ParentRunId"])
                sent = lineage_sent[3 * index:3 * index + 3]
                body = {"operation": operation} if not edits else {
                    "operation": "fork", "edits": [{"occurrenceId": report["forkOccurrenceId"], "operation": "replace",
                                                    "answer": EMACS_FORKED}]}
                assert [(item["resource"], item["body"]) for item in sent] == [
                    (lineage_uri, body), ("/v1/requests/" + request_id, {"operation": "enqueue"}),
                    ("/v1/preparations/" + preparation_id, sent[2]["body"])] \
                    and sent[2]["body"]["operation"] == "approve" and all(isinstance(item["ifMatch"], str) for item in sent), (
                    "the commands of the child", prefix, sent)
                created_receipt = lineage_receipts[3 * index][1]
                assert created_receipt["state"] == "effect-observed" and created_receipt["effect"]["kind"] == "lineage-created" \
                    and created_receipt["effect"]["resource"] == "/v1/requests/" + request_id, (
                    "the lineage command", prefix, created_receipt["state"], created_receipt["effect"])
                approval = lineage_receipts[3 * index + 2][1]
                assert approval["operation"] == "approve" and approval["state"] not in ("refused", "unresolved"), (
                    "the approval of the child", prefix, approval["state"])
                status, lineage, raw = request(lineage_uri, harness)
                assert status == 200, ("the lineage collection", prefix, status, lineage.get("code"))
                validate("LineagePage", lineage, raw)
                assert [(item["lineage"], item["parentRunId"]) for item in lineage["items"] if item["id"] == request_id] == [
                    (operation, parent)], ("the lineage collection of the parent run", prefix, lineage["items"])
                child, _, _ = observed("/v1/requests/" + request_id, "Request")
                assert child["runId"] == run_id and child["phase"] == "associated" and child["parentRunId"] == parent \
                    and child["lineage"] == operation, ("the child request", prefix, child["runId"], child["phase"])
                assert report[prefix + "ReviewRun"] is None and report[prefix + "Outcomes"] == ["approve", "run"], (
                    "the review of the child before its approval", prefix, report[prefix + "ReviewRun"], report[prefix + "Outcomes"])
                text = report[prefix + "ReviewText"]
                assert f"Lineage: {operation} of run {parent}\n" in text and f"Review of request {request_id}, preparation {preparation_id}" in text, (
                    "the review buffer of the child", prefix, text[:2000])
                child_preparation, _, _ = observed("/v1/preparations/" + preparation_id, "Preparation")
                assert child_preparation["requestId"] == request_id and child_preparation["state"] == "consumed" \
                    and child_preparation["review"]["lineage"] == {"parentRunId": parent, "operation": operation, "edits": edits}, (
                    "the review lineage of the child", prefix, child_preparation["state"], child_preparation["review"].get("lineage"))
                child_run, _, _ = observed("/v1/runs/" + run_id, "Run")
                assert child_run["parentRunId"] == parent and child_run["lineage"] == operation \
                    and [report[prefix + "RunParent"], report[prefix + "RunLineage"]] == [parent, operation], (
                    "the child run", prefix, child_run["parentRunId"], child_run["lineage"])
                terminal(run_id)
                return request_id, run_id

            restart = lineage_child("restart", "restart", report["literalRunId"], [], 0)
            resume = lineage_child("resume", "resume", report["capturedRunId"], [], 1)
            rerun = lineage_child("rerun", "restart", report["capturedRunId"], [], 2)
            fork = lineage_child("fork", "fork", restart[1], fork_edits, 3)
            fork_text = report["forkReviewText"]
            assert f"  replace occurrence {report['forkOccurrenceId']} with the answer of SHA-256 {fork_sha256}\n" in fork_text \
                and EMACS_FORKED not in fork_text, ("the fork review shows the answer and not its SHA-256", fork_text[:2000])
            assert report["forkPrefill"] == (report["forkTargetAnswer"] or ""), (
                "the replacement minibuffer did not start with the published answer", report["forkPrefill"], report["forkTargetAnswer"])
            print("PASS emacs-client 25: M-x wf-restart on the history row of run", report["literalRunId"], "S in the view of run",
                  report["capturedRunId"], "and F in the view of the restart child", restart[1], "created the child requests", restart[0],
                  resume[0], "and", fork[0], "through the lineage collection of each parent, each child named its parent and its",
                  "operation and no run until the one approve command of its exact review with its lineage, the fork replaced",
                  "occurrence", report["forkOccurrenceId"], "with the SHA-256", fork_sha256, "and the child runs", restart[1], resume[1],
                  "and", fork[1], "succeeded and name their parents", flush=True)
            print("PASS emacs-client 26: g, which runs wf-rerun, in the view of run", report["capturedRunId"],
                  "created the restart child request", rerun[0], "whose approved run", rerun[1], "succeeded and names the parent run",
                  "and the lineage restart", flush=True)
            # 27. The export of the lineage step.
            exported_run = report["serviceExportRunId"]
            export_item, export_receipt = lineage_sent[-1], lineage_receipts[-1][1]
            assert exported_run == answered_run and report["serviceExportName"] == EMACS_SERVICE_EXPORT \
                and len(lineage_sent) == 13 and export_item["resource"] == "/v1/runs/" + exported_run + "/exports" \
                and export_item["body"] == {"name": EMACS_SERVICE_EXPORT} and isinstance(export_item["ifMatch"], str) \
                and export_item["location"] == report["serviceExportCommand"], ("the export command of the lineage step", export_item)
            assert export_receipt["state"] == "effect-observed" and export_receipt["effect"]["kind"] == "exported" \
                and export_receipt["effect"]["resource"] == "/v1/exports/export_" + export_receipt["id"], (
                "the export receipt", export_receipt["state"], export_receipt["effect"])
            status, detail, raw = request(export_receipt["effect"]["resource"], harness)
            assert status == 200, ("the export of the lineage step", status)
            validate("ExportReceipt", detail, raw)
            assert detail["state"] == "published" and detail["name"] == EMACS_SERVICE_EXPORT and detail["runId"] == exported_run, (
                "the export of the lineage step", detail["state"], detail["name"])
            status, exports, raw = request("/v1/runs/" + exported_run + "/exports", harness)
            assert status == 200 and [item["id"] for item in exports["items"] if item["name"] == EMACS_SERVICE_EXPORT] == [detail["id"]], (
                "the export collection of the run", status, exports.get("items"))
            connection = http.client.HTTPSConnection("127.0.0.1", port, context=context, timeout=15)
            try:
                connection.request("GET", detail["download"], headers=harness | {"Accept": "application/octet-stream"})
                response = connection.getresponse()
                exported = response.read(int(detail["bytes"]) + 1)
                assert response.status == 200, ("the harness download of the export", response.status)
            finally:
                connection.close()
            assert len(exported) == int(detail["bytes"]) and hashlib.sha256(exported).hexdigest() == detail["sha256"], (
                "the export download differs from its receipt", len(exported), detail["bytes"])
            text = report["serviceExportText"]
            assert text.startswith(f"Export {EMACS_SERVICE_EXPORT}: {detail['id']} state published, command {export_receipt['id']}\n"
                                   f"Export download: verified {len(exported)} bytes, SHA-256 {detail['sha256']}\n"
                                   f"Exports of run {exported_run}: {len(exports['items'])}\n") \
                and f"  {EMACS_SERVICE_EXPORT}  {detail['id']}  published  {len(exported)} bytes  SHA-256 {detail['sha256']}\n" in text, (
                "the export buffer", text)
            print("PASS emacs-client 27: M-x wf-export on the history row of run", exported_run, "sent the one export command",
                  report["serviceExportCommand"], "which reached the effect exported, the manager published",
                  EMACS_SERVICE_EXPORT, "as", detail["id"], "whose download of", len(exported), "bytes verifies against the SHA-256",
                  detail["sha256"], "and the export buffer states that receipt, the verified download and the export collection",
                  flush=True)
        print("PASS emacs-client: the Emacs transport bound, created and replayed a draft, received the typed 412 and 401",
              "refusals, assembled the overview over all its pages, followed a run of the harness through event polls, kept its",
              "binding after an unreachable switch, switched to a second credential with generation fencing, closed",
              "cleanly, sent an export command whose receipt it read, downloaded and verified the export against the",
              "protected HTTPS endpoint, drove the service mode of wf.el with keys, created, set up, reviewed and",
              "approved two requests whose programs received their literal and captured inputs, declined, discarded",
              "and withdrew a third, followed two runs in two views, answered no as JSON false, kept the draft of a",
              "412 answer, killed a view with no command, created restart, resume, fork and rerun children whose",
              "runs started only after the approval of their exact reviews, exported a verified result, saved a",
              "verified result once, listed every run of the history over its pages and refused a history row of",
              "another endpoint, and the harness confirmed each step from manager facts",
              flush=True)
    finally:
        if process.poll() is None:
            process.terminate()
        process.wait(timeout=25)
        (work / "server-0.exit").write_text(str(process.returncode) + "\n")


# The variables that the Pi host takes from the environment of the harness.
PI_HOST_ALLOWLIST = ("PATH", "TERM", "LANG", "LC_ALL", "TMPDIR", "USER", "LOGNAME", "SHELL")
# The provider, model and fixed reply of ext-pi/test/fixtures/faux-model.ts.
PI_FAUX_PROVIDER = "agent-cat-faux"
PI_FAUX_MODEL = "faux-1"
PI_FAUX_REPLY = "agent-cat faux reply"


def provider_key_names(names):
    """The names of a set of environment variables that name a provider key."""
    return sorted(name for name in names if name.endswith("_API_KEY") or name.startswith("AWS_"))


class PiHost:
    """The shared Pi launcher of the Pi host modes. It starts the built Pi
    fork with ext-pi and the faux provider in a new pseudo-terminal, with an
    environment built from PI_HOST_ALLOWLIST and new HOME, Pi configuration
    and state directories under work/NAME. script is the text of the faux
    script file. The client profile defaults to the profile of the credential
    pi of TuiModeFixture. test_hooks sets AGENT_CAT_PI_TEST_HOOKS to 1, which
    registers the stream test hooks of ext-pi. runner_path sets
    AGENT_CAT_RUNNER, the absolute path of the local runner of ext-pi."""

    def __init__(self, name, script="", client_profile=None, rows=36, columns=140, test_hooks=False, runner_path=None):
        from tui_probe import TuiSession
        self.root = work / name
        self.root.mkdir(mode=0o700)
        self.home, self.agent, self.state = self.root / "home", self.root / "pi-agent", self.root / "state"
        for directory in (self.home, self.agent, self.state):
            directory.mkdir(mode=0o700)
        self.script = self.root / "faux-script.json"
        self.script.write_text(script)
        self.client_profile = client_profile or tui_fixture.client_profile
        self.environment = {name: os.environ[name] for name in PI_HOST_ALLOWLIST if name in os.environ}
        self.environment.update(HOME=str(self.home), PI_CODING_AGENT_DIR=str(self.agent), PI_TELEMETRY="0",
                                AGENT_CAT_MANAGER_PROFILES=json.dumps([str(self.client_profile)]),
                                AGENT_CAT_FAUX_SCRIPT=str(self.script))
        if test_hooks:
            self.environment["AGENT_CAT_PI_TEST_HOOKS"] = "1"
        if runner_path is not None:
            self.environment["AGENT_CAT_RUNNER"] = runner_path
        cli = source / "ext-pi/node_modules/@earendil-works/pi-coding-agent/dist/cli.js"
        assert cli.is_file(), ("the built Pi fork is not linked into ext-pi/node_modules", str(cli))
        self.command = ["node", str(cli), "--offline", "--no-extensions", "--no-skills", "--no-prompt-templates",
                        "--no-themes", "--no-context-files", "--approve",
                        "-e", str(source / "ext-pi/src/index.ts"), "-e", str(source / "ext-pi/test/fixtures/faux-model.ts"),
                        "--provider", PI_FAUX_PROVIDER, "--model", PI_FAUX_MODEL]
        # TuiSession sets TERM and AGENT_CAT_STATE_DIR above this environment.
        self.session = TuiSession(runner, self.state, rows=rows, columns=columns, command=self.command,
                                  environment=self.environment)
        self.session.alternate_screen = False

    def __enter__(self):
        return self

    def __exit__(self, _kind, _failure, _traceback):
        self.session.__exit__(_kind, _failure, _traceback)

    def save_screen(self, label):
        """Write the current screen to work/NAME/LABEL.screen.txt."""
        (self.root / (label + ".screen.txt")).write_text(self.session.screen.text())

    def save_output(self):
        """Write the retained PTY output of Pi to work/NAME/output.bin."""
        (self.root / "output.bin").write_bytes(bytes(self.session.output))

    def quit(self):
        """End Pi with /quit, and require exit status 0 and the terminal
        modes of the pseudo-terminal restored. Pi draws without the
        alternate screen, so only the modes and the visible cursor apply."""
        self.session.send(b"/quit\r")
        status = self.session.wait_exit(20)
        assert status == 0, ("Pi did not exit with status 0", status)
        self.session.assert_restored(alternate_screen=False)
        return status


def pi_home_marks():
    """The modification times of .pi, .pi/agent/sessions and the session
    directory of the working directory under the HOME of the harness and
    the home directory of the account, None for an absent path, and the
    name of that session directory."""
    import pwd
    slug = "--" + os.getcwd().strip("/").replace("/", "-") + "--"
    marks = {}
    for home in sorted({os.environ["HOME"], pwd.getpwuid(os.getuid()).pw_dir}):
        for path in (Path(home) / ".pi", Path(home) / ".pi/agent/sessions", Path(home) / ".pi/agent/sessions" / slug):
            try:
                marks[str(path)] = os.stat(path).st_mtime_ns
            except FileNotFoundError:
                marks[str(path)] = None
    return marks, slug


def pi_host_smoke_checks():
    """The pi-host-smoke mode. See PI_HOST_SMOKE for the steps."""
    endpoint = f"https://127.0.0.1:{port}/v1"
    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
    try:
        wait_ready(process)
        marks, slug = pi_home_marks()
        with PiHost("pi-host") as pi:
            try:
                environment = pi.environment
                assert set(environment) <= set(PI_HOST_ALLOWLIST) | {"HOME", "PI_CODING_AGENT_DIR", "PI_TELEMETRY",
                                                                   "AGENT_CAT_MANAGER_PROFILES", "AGENT_CAT_FAUX_SCRIPT"}, sorted(environment)
                assert not provider_key_names(environment) and environment["PI_TELEMETRY"] == "0", sorted(environment)
                assert json.loads(environment["AGENT_CAT_MANAGER_PROFILES"]) == [str(tui_fixture.client_profile)], environment["AGENT_CAT_MANAGER_PROFILES"]
                shown = process_environment(pi.session.process.pid)
                assert shown is not None, "the Pi process exited before ps read its environment"
                names = set(re.findall(rb"(?:^|\s)([A-Za-z_][A-Za-z0-9_]*)=", shown))
                names = {name.decode() for name in names}
                assert not provider_key_names(names), ("a provider key reached Pi", provider_key_names(names))
                assert re.search(rb"(?:^|\s)PI_TELEMETRY=0(?:\s|$)", shown), "PI_TELEMETRY=0 is not in the environment of Pi"
                print("PASS pi-host-smoke 1: Pi started from the allowlist environment with HOME", pi.home, "and PI_CODING_AGENT_DIR", pi.agent,
                      "of the fixture, PI_TELEMETRY=0, AGENT_CAT_MANAGER_PROFILES the JSON array of the client profile, and no provider key",
                      "in the environment of the running process", flush=True)

                screen = pi.session.wait_screen("[Extensions]", timeout=60)
                deadline = time.monotonic() + 30
                while not (PI_FAUX_MODEL in screen and squeeze("Manager connected: " + endpoint) in squeeze(screen)):
                    assert time.monotonic() < deadline and pi.session.process.poll() is None, (
                        "Pi did not show the faux model and the manager connection", screen)
                    pi.session.pump(0.1)
                    screen = pi.session.screen.text()
                loaded = screen.split("[Extensions]", 1)[1].split("\n")[1]
                assert {"faux-model.ts", "src"} <= {item.strip() for item in loaded.split(",")}, ("the loaded extensions", loaded)
                pi.save_screen("started")
                print("PASS pi-host-smoke 2: Pi loaded ext-pi and the faux extension, selected the faux model", PI_FAUX_MODEL,
                      "and notified the connection to", endpoint, flush=True)

                live = re.compile(re.escape(squeeze("Connection: connected to " + endpoint + " (endpoint identity")) + r"[^)]*\),deliverylive")
                deadline = time.monotonic() + 30
                while True:
                    pi.session.send(b"/wfm-status\r")
                    settle = time.monotonic() + 2
                    while time.monotonic() < settle and not live.search(squeeze(pi.session.screen.text())):
                        pi.session.pump(0.1)
                    if live.search(squeeze(pi.session.screen.text())):
                        break
                    assert time.monotonic() < deadline and pi.session.process.poll() is None, (
                        "/wfm-status did not show delivery live", pi.session.screen.text())
                pi.save_screen("wfm-status")
                print("PASS pi-host-smoke 3: /wfm-status showed the connection to", endpoint, "with delivery live", flush=True)

                pi.session.send(b"Reply to the agent-cat host check.\r")
                pi.session.wait_screen(PI_FAUX_REPLY + " 1", timeout=30)
                pi.save_screen("reply")
                sessions = sorted(pi.agent.glob("sessions/*/*.jsonl"))
                assert [path.parent.name for path in sessions] == [slug], ("the isolated session files", [str(path) for path in sessions])
                replies = [entry["message"] for entry in map(json.loads, sessions[0].read_text().splitlines())
                           if entry.get("type") == "message" and entry["message"].get("role") == "assistant"]
                assert [(message["provider"], message["model"], message["content"]) for message in replies] == [
                    (PI_FAUX_PROVIDER, PI_FAUX_MODEL, [{"type": "text", "text": PI_FAUX_REPLY + " 1"}])], replies
                print("PASS pi-host-smoke 4: one prompt gave the faux reply", repr(PI_FAUX_REPLY + " 1"), "on the screen, and the session file",
                      sessions[0].name, "of the isolated configuration records it from", PI_FAUX_PROVIDER + "/" + PI_FAUX_MODEL, flush=True)

                pi.quit()
                print("PASS pi-host-smoke 5: /quit ended Pi with exit status 0 and the terminal modes restored", flush=True)
            except BaseException:
                pi.save_screen("failure")
                raise
        after, _ = pi_home_marks()
        assert after == marks, ("Pi wrote below the .pi directory of a real home", marks, after)
        print("PASS pi-host-smoke 6: the modification times of", ", ".join(marks), "did not change", flush=True)
        print("PASS pi-host-smoke: the built Pi fork started in an isolated home with ext-pi and the faux provider, reached the manager",
              "with live delivery, replied from the faux provider and quit cleanly", flush=True)
    finally:
        if process.poll() is None:
            process.terminate()
        process.wait(timeout=25)


def pi_host_checks():
    """The pi-host and pi-host-broken-answer modes. See PI_HOST for the steps."""
    harness = tui_fixture.harness
    endpoint = f"https://127.0.0.1:{port}/v1"
    answer = PI_HOST_ANSWER.decode()
    terminal = ("succeeded", "failed", "cancelled", "orphaned")
    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
    try:
        with harness_reads_only():
            wait_ready(process)
            status, capabilities, _ = request("/v1/capabilities", harness)
            assert status == 200, ("capabilities", status)
            status, profiles, _ = request("/v1/profiles", harness)
            assert status == 200 and [item["id"] for item in profiles["items"]] == ["profile_1"], ("profiles", status)
            status, catalogue, _ = request("/v1/workflows?profileId=profile_1", harness)
            assert status == 200, ("catalogue", status)
            index = next(i for i, item in enumerate(catalogue["items"]) if item["name"] == "mixed-controls")
            workflow = catalogue["items"][index]
            status, overview, _ = request("/v1/snapshot", harness)
            assert status == 200 and not overview["items"], ("the overview is not empty before the check", status)
            cursor = overview["cursor"]
            client = mixed_client(capabilities, harness)
            observed = client[0]
            selectors = ("reviewDigest", "requestRevision", "profileRevision", "descriptorRevision", "processGeneration")
            # The pseudo-terminal of the Pi process that the helpers below
            # drive. The last step starts Pi again and rebinds it.
            session = None

            def shown(needles, timeout, what):
                """Pump until the screen shows every needle, compared
                without white space so that wrapped rows join, and give
                the screen."""
                deadline = time.monotonic() + timeout
                while True:
                    screen = session.screen.text()
                    if all(squeeze(needle) in squeeze(screen) for needle in needles):
                        session.settle()
                        return session.screen.text()
                    assert time.monotonic() < deadline and session.process.poll() is None, (what, needles, screen)
                    session.pump(0.1)

            def until(path, schema, ready, timeout=40):
                """Read the resource until ready holds, and pump the
                pseudo-terminal between the reads. Node writes to a
                terminal synchronously, so Pi stops while its output is
                not read."""
                deadline = time.monotonic() + timeout
                while True:
                    value, tag, raw = observed(path, schema)
                    if ready(value):
                        return value, tag, raw
                    assert time.monotonic() < deadline and session.process.poll() is None, (
                        "observation deadline", path, session.screen.text())
                    session.pump(0.1)

            def typed(text, what):
                """Type the text and wait until the screen shows it."""
                session.send(text.encode())
                return shown([text], 15, what)

            def printed(needles, after, timeout, what):
                """Pump until the output of Pi after the byte offset, without
                its control sequences and white space, holds every needle,
                and give that text. Pi redraws its screen, so a notice can
                leave the screen before the harness reads it."""
                deadline = time.monotonic() + timeout
                while True:
                    text = squeeze(re.sub(r"\x1b\[[0-9;?]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)|\x1b[@-Z\\-_]", "",
                                          bytes(session.output[after:]).decode("utf-8", "replace")))
                    if all(squeeze(needle) in text for needle in needles):
                        session.settle()
                        return text
                    assert time.monotonic() < deadline and session.process.poll() is None, (what, needles, session.screen.text())
                    session.pump(0.1)

            def still_running(run, head):
                """Read through the harness credential that the run still
                runs at its pending head under owned supervision."""
                snapshot, _, _ = observed("/v1/runs/" + run + "/snapshot", "RunSnapshot")
                control, _, _ = observed("/v1/runs/" + run + "/control", "RunControl")
                run_view, _, _ = observed("/v1/runs/" + run, "Run")
                decision, _, _ = observed("/v1/decisions/" + head, "Decision")
                assert snapshot["runtime"] is not None and snapshot["runtime"]["status"] == "running", ("the held run does not run", snapshot["runtime"])
                assert control["decisionHeadId"] == head and decision["state"] == "pending" and run_view["supervision"] == "owned", (
                    "the held run left its head or its supervision", control["decisionHeadId"], decision["state"], run_view["supervision"])

            def create_and_approve(label):
                """Create a request of profile_1 and mixed-controls that
                supplies the typed literal through /wfm by keys, and
                approve its exact review by key and the confirmation. Give
                the request, the displayed preparation and the run."""
                status, listed, _ = request("/v1/requests", harness)
                assert status == 200, ("requests", status)
                known = {item["id"] for item in listed["items"]}
                session.send(b"/wfm\r")
                shown(["Workflow of profile_1", "mixed-controls"], 30, "/wfm showed no workflow selection of profile_1")
                pi.save_screen(label + "-workflows")
                session.send(b"\x1b[B" * index)
                shown(["→ mixed-controls"], 10, "the arrow keys did not select mixed-controls")
                session.send(b"\r")
                shown(["Input input (declared source", "→ Literal text"], 30, "/wfm showed no input source selection")
                session.send(b"\r")
                shown(["Input input: exact literal text"], 15, "/wfm opened no literal editor")
                typed(PI_HOST_LITERAL, "the typed literal is not shown")
                pi.save_screen(label + "-literal")
                session.send(b"\r")
                created, request_uri, preparation_uri, preparation = reviewed_request(known, label)
                run = approve_shown(request_uri, preparation_uri, preparation, label)
                return created, preparation, run

            def reviewed_request(known, label):
                """Wait for the one request of profile_1 and mixed-controls
                that is not in known. It must supply exactly the literal and
                leave the draft phase through its one enqueue command, and Pi
                must show the exact review of its preparation with the five
                selectors. Give the request, its resource, the resource of
                the preparation and the displayed preparation."""

                def enqueued(value):
                    items = [item["request"] for item in value["items"] if item["kind"] == "request" and item["request"]["id"] not in known]
                    return len(items) == 1 and items[0]["phase"] != "draft"

                snapshot, _, _ = until("/v1/snapshot", "OverviewSnapshot", enqueued)
                request_uri = next(item["request"] for item in snapshot["items"]
                                   if item["kind"] == "request" and item["request"]["id"] not in known)["links"]["self"]
                created, _, _ = observed(request_uri, "Request")
                assert created["profileId"] == "profile_1" and created["workflowId"] == workflow["id"], (
                    "the request names another profile or workflow", created["profileId"], created["workflowId"])
                assert created["readiness"]["supplied"] == [{"name": "input", "source": "literal", "value": PI_HOST_LITERAL}], (
                    "the request did not supply exactly the typed literal", created["readiness"]["supplied"])
                enqueues = [receipt for _, receipt in command_receipts(cursor, harness)
                            if receipt["operation"] == "enqueue" and receipt["resource"] == request_uri]
                assert len(enqueues) == 1 and enqueues[0]["state"] == "effect-observed", ("the enqueue command", enqueues)
                current, _, _ = until(request_uri, "Request", lambda value: value["phase"] == "review" and value["preparationId"] is not None)
                preparation_uri = "/v1/preparations/" + current["preparationId"]
                preparation, _, _ = observed(preparation_uri, "Preparation")
                review = shown(["Review of request " + created["id"] + ", preparation " + preparation["id"], "a approve after confirmation"]
                               + [name + ": " + str(preparation[name]) for name in selectors], 45, "Pi showed no exact review with its selectors")
                pi.save_screen(label + "-review")
                assert squeeze("Workflow: " + workflow["id"]) in squeeze(review) and squeeze("Profile: profile_1") in squeeze(review), (
                    "the review does not name the workflow and the profile", review)
                return created, request_uri, preparation_uri, preparation

            def approve_shown(request_uri, preparation_uri, preparation, label):
                """Approve the displayed review with a and Yes, and give the
                run that the request then names. The manager must hold
                exactly one approve command of the preparation."""
                session.send(b"a")
                shown(["Approve this exact review?", preparation["reviewDigest"], "→ Yes"], 15, "a opened no approval confirmation")
                pi.save_screen(label + "-approve")
                session.send(b"\r")
                associated, _, _ = until(request_uri, "Request", lambda value: value["runId"] is not None)
                run = associated["runId"]
                shown(["Execution: the manager started run " + run], 45, "Pi did not report the started run")
                consumed, _, _ = observed(preparation_uri, "Preparation")
                approvals = [receipt for _, receipt in command_receipts(cursor, harness)
                             if receipt["operation"] == "approve" and receipt["resource"] == preparation_uri]
                assert consumed["state"] == "consumed" and len(approvals) == 1 and approvals[0]["state"] not in ("refused", "unresolved"), (
                    "the approval of the displayed review", consumed["state"], approvals)
                assert all(consumed[name] == preparation[name] for name in selectors), "the consumed preparation differs from the displayed review"
                return run

            def answer_heads(run, kinds, report=False):
                """Act in Pi on each head of the run in the order that the
                manager presents them, until each of the kinds has had its
                turn or the run ends. At a question the typed answer is
                sent, and at a recovery head the offered Retry. Give the
                kinds in the order handled, the occurrence of the question
                and the handled heads."""
                base = "/v1/runs/" + run
                order, heads = [], []
                question_occurrence = None
                deadline = time.monotonic() + 150
                while not set(kinds) <= set(order):
                    assert time.monotonic() < deadline and session.process.poll() is None, ("the decision heads did not appear", run, order)
                    snapshot, _, _ = observed(base + "/snapshot", "RunSnapshot")
                    if snapshot["runtime"] is not None and snapshot["runtime"]["status"] in terminal:
                        break
                    control, _, _ = observed(base + "/control", "RunControl")
                    head = control["decisionHeadId"]
                    decision = observed("/v1/decisions/" + head, "Decision")[0] if head is not None else None
                    if decision is None or decision["kind"] in order:
                        session.pump(0.2)
                        continue
                    occurrence = decision["address"]["occurrenceId"]
                    session.send(("/wfm-answer " + run + "\r").encode())
                    if decision["kind"] == "question":
                        question_occurrence = occurrence
                        shown(["Answer of decision " + head], 30, "/wfm-answer opened no answer editor")
                        typed(answer, "the typed answer is not shown")
                        pi.save_screen("answer")
                        session.send(b"\r")
                        shown(["reached decision " + head], 45, "Pi did not report the answer")
                        until(base + "/control", "RunControl", lambda value: value["decisionHeadId"] != head)
                        item = None
                        answer_deadline = time.monotonic() + 45
                        while item is None or item["answer"] is None:
                            assert time.monotonic() < answer_deadline, ("the answered occurrence publishes no answer", item)
                            after, _, _ = observed(base + "/snapshot", "RunSnapshot")
                            item = next(value for value in after["items"] if value["occurrenceId"] == occurrence)
                            session.pump(0.2)
                        # The snapshot publishes a flag answer as its rendered text,
                        # "no" for false and "yes" for true.
                        assert item["code"] == "flag" and {"no": False, "yes": True}.get(item["answer"], item["answer"]) is False, PI_HOST_FALSE
                        if report:
                            print("PASS pi-host 4a: /wfm-answer sent the typed answer", answer, "to question", head,
                                  "and the occurrence publishes the rendered false answer no", flush=True)
                    else:
                        shown(["Recovery of decision " + head], 30, "/wfm-answer opened no recovery selection")
                        for _ in range(8):
                            if "→ Retry" in session.screen.text():
                                break
                            session.send(b"\x1b[B")
                            session.settle()
                        shown(["→ Retry"], 10, "the recovery selection offers no Retry")
                        pi.save_screen("recovery")
                        session.send(b"\r")
                        shown(["Recovery Retry reached decision " + head], 45, "Pi did not report the retry")
                        until(base + "/control", "RunControl", lambda value: value["decisionHeadId"] != head)
                        if report:
                            print("PASS pi-host 4b: /wfm-answer chose the offered Retry of recovery decision", head, flush=True)
                    order.append(decision["kind"])
                    heads.append(head)
                return order, question_occurrence, heads

            def events_after(after):
                """The events of /v1/events after the cursor, over every
                polling batch, read through the harness credential."""
                events = []
                for _ in range(256):
                    status, batch, raw, _ = fetch("/v1/events?after=" + after, harness | {"Accept": "application/json"})
                    assert status == 200, ("event read", status, batch.get("code"))
                    validate("EventBatch", batch, raw)
                    events += batch["events"]
                    after = batch["cursor"]
                    if not batch["hasMore"]:
                        return events
                raise AssertionError("event pages")

            def row_after(prefix):
                """The rest of the last screen row that starts with the prefix."""
                rows = [line.strip() for line in session.screen.lines() if line.strip().startswith(prefix)]
                assert rows, ("no screen row starts with", prefix, session.screen.text())
                return rows[-1][len(prefix):].strip()

            def model_checks():
                """The pi-host-model and pi-host-model-decline modes. See
                PI_HOST_MODEL for the steps."""
                nonlocal session, pi
                local_runner = str(runner.resolve())
                inputs = json.dumps({"input": PI_HOST_LITERAL}, ensure_ascii=False)
                start = {"action": "manager-start", "workflow": "mixed-controls", "inputsJson": inputs, "grantId": "grant-forged", "approved": True}
                started = "started run (run_[0-9a-f]+) for request"

                def call(identifier, arguments, from_result=None):
                    return {"toolCall": {"name": "agent_cat_workflow", "arguments": arguments, "id": identifier,
                                         **({"fromResult": from_result} if from_result else {})}}

                script = [call("model-start-1", start), {"text": "Model turn 1 ended."},
                          call("model-start-2", start), {"text": "Model turn 2 ended."},
                          call("model-answer", {"action": "manager-answer", "answer": "false"}, {"runId": started}), {"text": "Model turn 3 ended."},
                          call("model-retry", {"action": "manager-control", "controlKind": "retry"}, {"runId": started}), {"text": "Model turn 4 ended."},
                          call("model-local-start", {"action": "start", "workflow": "mixed-controls", "inputsJson": inputs, "launchTarget": "scripted",
                                                     "grantId": "grant-forged"}), {"text": "Model turn 5 ended."}]

                def turn(text):
                    """Type the prompt of the next model turn."""
                    session.send(text.encode() + b"\r")

                def ended(number):
                    shown(["Model turn " + str(number) + " ended."], 120, "the model did not end turn " + str(number))

                def decline(what):
                    """Move the open confirmation to No and decline it."""
                    session.send(b"\x1b[B")
                    shown(["→ No"], 10, "the confirmation of " + what + " offers no No")
                    session.send(b"\r")

                def approvals():
                    return [receipt for _, receipt in command_receipts(cursor, harness) if receipt["operation"] == "approve"]

                def confirmed_request(label):
                    """Confirm the request confirmation of a model start by
                    Enter on Yes, and give the request with its review."""
                    status, listed, _ = request("/v1/requests", harness)
                    assert status == 200, ("requests", status)
                    known = {item["id"] for item in listed["items"]}
                    shown(["Create manager request?", "profile=profile_1", "workflow=mixed-controls (" + workflow["id"] + ")",
                           "input input=" + json.dumps(PI_HOST_LITERAL, ensure_ascii=False) + " (literal)", "→ Yes"], 60,
                          "Pi showed no request confirmation of the model start")
                    pi.save_screen(label + "-create")
                    session.send(b"\r")
                    return reviewed_request(known, label)

                with PiHost("pi-host-model", script=json.dumps(script, ensure_ascii=False), runner_path=local_runner) as pi:
                    session = pi.session
                    try:
                        session.wait_screen("[Extensions]", timeout=60)
                        shown(["Manager connected: " + endpoint], 30, "Pi did not notify the manager connection")

                        # 1. A forged grant and approval, and the exact review declined by key.
                        turn("Start mixed-controls through the manager.")
                        created1, request_uri1, preparation_uri1, preparation1 = confirmed_request("model-first")
                        session.send(b"a")
                        shown(["Approve this exact review?", preparation1["reviewDigest"], "→ Yes"], 15, "a opened no approval confirmation")
                        pi.save_screen("model-first-approve")
                        decline("the first review")
                        shown(["Review declined. No approval was sent. Request " + created1["id"] + " stays in review"], 30,
                              "Pi did not report the declined review")
                        ended(1)
                        first, _, _ = observed(request_uri1, "Request")
                        first_preparation, _, _ = observed(preparation_uri1, "Preparation")
                        assert approvals() == [], ("an approve command exists after the declined review", approvals())
                        assert first["phase"] == "review" and first["runId"] is None and first_preparation["state"] == "live", (
                            "the request of the declined review left review", first["phase"], first["runId"], first_preparation["state"])
                        # The request in review holds the resources of profile_1,
                        # so the human withdraws it before the next start.
                        session.send(("/wfm-withdraw " + created1["id"] + "\r").encode())
                        shown(["Request " + created1["id"] + " is withdrawn."], 30, "/wfm-withdraw did not withdraw the declined request")
                        withdrawn, _, _ = observed(request_uri1, "Request")
                        assert withdrawn["phase"] not in ("draft", "queued", "preparing", "review") and withdrawn["runId"] is None, (
                            "the withdrawn request", withdrawn["phase"], withdrawn["runId"])
                        print("PASS pi-host-model 1: the model start with grantId grant-forged and approved true created request", created1["id"],
                              "only after Enter on Yes of its request confirmation, Pi showed the exact review of preparation", preparation1["id"],
                              "and its approval confirmation, the decline by key sent no approve command, the request stayed in review with no run,",
                              "and /wfm-withdraw moved it to", withdrawn["phase"], flush=True)

                        # 2. The same start, approved by key after the exact review.
                        turn("Start mixed-controls through the manager again.")
                        created2, request_uri2, preparation_uri2, preparation2 = confirmed_request("model-second")
                        if sys.argv[5] == PI_HOST_MODEL_DECLINE:
                            session.send(b"a")
                            shown(["Approve this exact review?", preparation2["reviewDigest"], "→ Yes"], 15, "a opened no approval confirmation")
                            decline("the second review")
                            shown(["Review declined. No approval was sent. Request " + created2["id"] + " stays in review"], 30,
                                  "Pi did not report the declined review")
                            ended(2)
                            second, _, _ = observed(request_uri2, "Request")
                            assert second["runId"] is not None, PI_HOST_MODEL_STARTED
                        run = approve_shown(request_uri2, preparation_uri2, preparation2, "model-second")
                        ended(2)
                        base = "/v1/runs/" + run
                        first, _, _ = observed(request_uri1, "Request")
                        assert first["runId"] is None and [receipt["resource"] for receipt in approvals()] == [preparation_uri2], (
                            "the approvals after the second start", first["runId"], approvals())
                        print("PASS pi-host-model 2: the repeated model start created request", created2["id"], "after its request confirmation,",
                              "a and Yes of its exact review sent the one approve command of preparation", preparation2["id"] + ",",
                              "and request", created2["id"], "names run", run, flush=True)

                        # 3. The model answer false, confirmed by key.
                        held, _, _ = until(base + "/control", "RunControl", lambda value: value["decisionHeadId"] is not None, timeout=90)
                        question = held["decisionHeadId"]
                        decision = observed("/v1/decisions/" + question, "Decision")[0]
                        assert decision["kind"] == "question", ("the first head of the run", decision["kind"])
                        occurrence = decision["address"]["occurrenceId"]
                        turn("Answer the question of the run with false.")
                        shown(["Send manager answer?", "decision=" + question, "run=" + run, "value=false", "→ Yes"], 60,
                              "Pi showed no confirmation of the model answer")
                        pi.save_screen("model-answer")
                        session.send(b"\r")
                        shown(["Answer false reached decision " + question + " of run " + run], 60, "Pi did not report the model answer")
                        ended(3)
                        answers = [receipt for _, receipt in command_receipts(cursor, harness)
                                   if receipt["operation"] == "answer" and receipt["resource"] == "/v1/decisions/" + question]
                        assert len(answers) == 1 and answers[0]["state"] == "effect-observed", ("the answer command", answers)
                        snapshot, _, _ = until(base + "/snapshot", "RunSnapshot", lambda value: any(
                            item["occurrenceId"] == occurrence and item["answer"] is not None for item in value["items"]))
                        item = next(value for value in snapshot["items"] if value["occurrenceId"] == occurrence)
                        assert item["code"] == "flag" and item["answer"] == "no", ("the published answer", item["code"], item["answer"])
                        print("PASS pi-host-model 3: the model answer showed decision", question, "of run", run, "with value false,",
                              "Enter on Yes sent its one answer command, and the occurrence publishes the rendered false answer no", flush=True)

                        # 4. The model retry, confirmed by key, and terminal success.
                        recovering, _, _ = until(base + "/control", "RunControl",
                                                 lambda value: value["decisionHeadId"] not in (None, question), timeout=90)
                        recovery = recovering["decisionHeadId"]
                        assert observed("/v1/decisions/" + recovery, "Decision")[0]["kind"] == "recovery", ("the second head of the run",)
                        turn("Retry the run.")
                        shown(["Send manager control?", "kind=retry", "run=" + run, "decision=" + recovery, "→ Yes"], 60,
                              "Pi showed no confirmation of the model retry")
                        pi.save_screen("model-retry")
                        session.send(b"\r")
                        shown(["reached decision " + recovery + " of run " + run], 60, "Pi did not report the model retry")
                        ended(4)
                        retries = [receipt for _, receipt in command_receipts(cursor, harness)
                                   if receipt["operation"] == "retry" and receipt["resource"] == base + "/control"]
                        assert len(retries) == 1 and retries[0]["state"] == "effect-observed", ("the retry command", retries)
                        until(base + "/snapshot", "RunSnapshot", lambda value: value["runtime"] is not None and value["runtime"]["status"] in terminal,
                              timeout=90)
                        final, _, _ = observed(base + "/snapshot", "RunSnapshot")
                        assert final["runtime"]["status"] == "succeeded", ("the run did not succeed", final["runtime"])
                        recorded = [entry["answer"] for path in work.glob("manager/runs/runs/*/runtime/answers.json")
                                    for entry in json.loads(path.read_bytes())["answers"] if entry["occurrenceId"] == occurrence]
                        assert len(recorded) == 1 and recorded[0] is False, ("the run store does not record JSON false", recorded)
                        print("PASS pi-host-model 4: the model retry showed kind retry of run", run, "at recovery decision", recovery + ",",
                              "Enter on Yes sent its one retry command, the run succeeded, and the run store records JSON false", flush=True)

                        # 5. The local start with a forged grant, declined at its exact launch review.
                        local_runs = pi.state / "runs"
                        turn("Start mixed-controls locally.")
                        shown(["Launch agent-cat workflow?", "target=scripted (offline, no commands)",
                               "input input=" + json.dumps(PI_HOST_LITERAL, ensure_ascii=False), "→ Yes"], 60,
                              "Pi showed no local launch review of the model start")
                        pi.save_screen("model-local-review")
                        decline("the local launch review")
                        ended(5)
                        assert not local_runs.exists() or not any(local_runs.iterdir()), (
                            "the declined local start created a run directory", sorted(map(str, local_runs.iterdir())))
                        print("PASS pi-host-model 5: the model local start with launchTarget scripted and grantId grant-forged showed the local",
                              "exact launch review, and the decline by key created no run directory under", local_runs, flush=True)

                        # 6. /wf-grant is not a command.
                        commands_before = command_ids()
                        offset = len(session.output)
                        session.send(b"/wf-grant grant-forged\r")
                        printed(["Unknown command /wf-grant. Nothing was sent to the model."], offset, 15, "/wf-grant gave no unknown-command notice")
                        pi.save_screen("model-wf-grant")
                        pi.quit()
                        sessions = sorted(pi.agent.glob("sessions/*/*.jsonl"))
                        assert len(sessions) == 1, ("the session files of Pi", [str(path) for path in sessions])
                        messages = [entry["message"] for entry in map(json.loads, sessions[0].read_text().splitlines()) if entry.get("type") == "message"]
                        prompts = [message for message in messages if message.get("role") == "user"]
                        assert len(prompts) == 5 and not any("/wf-grant" in json.dumps(message, ensure_ascii=False) for message in prompts), (
                            "the prompts of the session", prompts)
                        assert [message["content"] for message in messages if message.get("role") == "assistant"][-1] == [
                            {"type": "text", "text": "Model turn 5 ended."}], "the model replied after /wf-grant"
                        assert command_ids() == commands_before, "a command reached the manager after /wf-grant"
                        print("PASS pi-host-model 6: /wf-grant gave the unknown-command notice of ext-pi, the session records no prompt with it",
                              "and no further model reply, the manager holds no new command, and /quit ended Pi with exit status 0", flush=True)
                    except BaseException:
                        pi.save_screen("failure")
                        pi.save_output()
                        raise
                print("PASS pi-host-model: a model-supplied grantId or approved field started nothing, only the human confirmation of the",
                      "exact review started the run, the model answer and retry reached the manager after their confirmations and the run",
                      "succeeded with JSON false, the declined local start created nothing, and /wf-grant is not a command", flush=True)

            if pi_host_model_mode:
                model_checks()
                return

            with PiHost("pi-host", test_hooks=True) as pi:
                session = pi.session
                try:
                    session.wait_screen("[Extensions]", timeout=60)
                    shown(["Manager connected: " + endpoint], 30, "Pi did not notify the manager connection")
                    # 1 and 2. Workflow selection, the literal, the enqueue, the
                    # exact review and its approval by key.
                    created, preparation, run = create_and_approve("first")
                    base = "/v1/runs/" + run
                    print("PASS pi-host 1: /wfm selected profile_1 and", workflow["name"], "by keys, request", created["id"],
                          "supplied exactly the typed literal", repr(PI_HOST_LITERAL), "and its one enqueue command reached its effect", flush=True)
                    print("PASS pi-host 2: Pi showed the exact review of preparation", preparation["id"], "with its five selectors, review digest",
                          preparation["reviewDigest"] + ", a and Yes sent its one approve command, and request", created["id"], "names run", run, flush=True)

                    # 3. The live monitor shows the question.
                    question = "Independent confirmation? " + PI_HOST_LITERAL
                    session.send(("/wfm-monitor " + run + "\r").encode())
                    shown(["Service run " + run + ", workflow mixed-controls", "Runtime: running", question], 90,
                          "the monitor did not show the running run with its question")
                    pi.save_screen("monitor-question")
                    session.send(b"q")
                    session.settle()
                    print("PASS pi-host 3: /wfm-monitor showed run", run, "running with its question", repr(question), flush=True)

                    # 4. The typed answer and the offered retry, in the order of the manager.
                    order, question_occurrence, _ = answer_heads(run, ("question", "recovery"), report=True)
                    assert sorted(order) == ["question", "recovery"], ("the heads of the run", order)
                    print("PASS pi-host 4: Pi answered the heads in the manager order", " then ".join(order), flush=True)

                    # 5. Terminal success and the verified result.
                    until(base + "/snapshot", "RunSnapshot", lambda value: value["runtime"] is not None and value["runtime"]["status"] == "succeeded")
                    artifact = verified_download(run, client, harness)
                    session.send(("/wfm-monitor " + run + "\r").encode())
                    shown(["Terminal: succeeded", "Result: verified " + str(int(artifact["bytes"])) + " bytes",
                           "Result SHA-256: " + artifact["sha256"]], 60, "the monitor did not show the verified result")
                    pi.save_screen("monitor-result")
                    session.send(b"q")
                    session.settle()
                    recorded = [entry["answer"] for path in work.glob("manager/runs/runs/*/runtime/answers.json")
                                for entry in json.loads(path.read_bytes())["answers"] if entry["occurrenceId"] == question_occurrence]
                    assert len(recorded) == 1 and recorded[0] is False, (PI_HOST_FALSE, recorded)
                    print("PASS pi-host 5: /wfm-monitor showed terminal success and the verified result of", artifact["bytes"],
                          "bytes with the SHA-256", artifact["sha256"], "of the harness download, and the run store records JSON false", flush=True)

                    # 6. The verified save.
                    saved_path = work / "pi-host-saved-result.json"
                    session.send(("/wfm-result " + run + "\r").encode())
                    shown(["Path of a new file for the verified " + str(int(artifact["bytes"])) + " bytes of run " + run], 30,
                          "/wfm-result opened no path dialog")
                    typed(str(saved_path), "the typed path is not shown")
                    session.send(b"\r")
                    shown(["Saved the verified " + str(int(artifact["bytes"])) + " bytes of run " + run], 30, "Pi did not report the save")
                    pi.save_screen("saved")
                    saved = saved_path.read_bytes()
                    assert stat.S_IMODE(os.lstat(saved_path).st_mode) == 0o600, ("the saved file mode", oct(os.lstat(saved_path).st_mode))
                    assert saved == (work / "verified-result.json").read_bytes() and hashlib.sha256(saved).hexdigest() == artifact["sha256"], (
                        "the saved bytes differ from the harness download")
                    print("PASS pi-host 6: /wfm-result saved the", len(saved), "verified bytes of run", run, "to", saved_path,
                          "with mode 0600 and the exact bytes of the harness download", flush=True)

                    # 7. The history.
                    session.send(b"/wfm-history\r")
                    shown(["History: 1 managed runs and 0 observer entries",
                           run + " " + workflow["id"] + " profile profile_1 succeeded, supervision", "result verified"], 30,
                          "/wfm-history did not list the run as a succeeded managed run")
                    pi.save_screen("history")
                    print("PASS pi-host 7: /wfm-history listed run", run, "of", workflow["id"], "as the one managed run, succeeded with a verified result",
                          flush=True)

                    # 8. The restart child, its lineage review and its approval by key.
                    lineage_uri = base + "/lineage-requests"
                    until(lineage_uri, "LineagePage", lambda value: "restart" in value["eligible"], timeout=60)
                    session.send(("/wfm-restart " + run + "\r").encode())
                    deadline = time.monotonic() + 45
                    while True:
                        status, listed, _ = request("/v1/requests", harness)
                        assert status == 200, ("requests", status)
                        children = [item["id"] for item in listed["items"] if item["parentRunId"] == run]
                        if children:
                            break
                        assert time.monotonic() < deadline and session.process.poll() is None, ("/wfm-restart created no child", session.screen.text())
                        session.pump(0.2)
                    assert len(children) == 1, ("the restart children of the run", children)
                    child_id = children[0]
                    child_uri = "/v1/requests/" + child_id
                    child, _, _ = until(child_uri, "Request", lambda value: value["phase"] == "review" and value["preparationId"] is not None)
                    assert child["parentRunId"] == run and child["lineage"] == "restart", ("the child request", child["parentRunId"], child["lineage"])
                    child_preparation_uri = "/v1/preparations/" + child["preparationId"]
                    child_preparation, _, _ = observed(child_preparation_uri, "Preparation")
                    assert child_preparation["review"]["lineage"] == {"parentRunId": run, "operation": "restart", "edits": []}, (
                        "the lineage of the child review", child_preparation["review"].get("lineage"))
                    shown(["Review of request " + child_id + ", preparation " + child_preparation["id"]], 45, "Pi showed no review of the child")
                    # The lineage line ends the review, so j scrolls to it.
                    lineage_row = "Lineage: restart of run " + run
                    deadline = time.monotonic() + 15
                    while not any(line.strip() == lineage_row for line in session.screen.lines()):
                        assert time.monotonic() < deadline, ("the child review shows no lineage row", session.screen.text())
                        session.send(b"j")
                        session.settle()
                    pi.save_screen("restart-review")
                    child_run = approve_shown(child_uri, child_preparation_uri, child_preparation, "restart")
                    answer_heads(child_run, ("question", "recovery"))
                    until("/v1/runs/" + child_run + "/snapshot", "RunSnapshot",
                          lambda value: value["runtime"] is not None and value["runtime"]["status"] in terminal, timeout=90)
                    child_view, _, _ = observed("/v1/runs/" + child_run, "Run")
                    child_snapshot, _, _ = observed("/v1/runs/" + child_run + "/snapshot", "RunSnapshot")
                    assert child_snapshot["runtime"]["status"] == "succeeded", ("the child run did not succeed", child_snapshot["runtime"])
                    assert child_view["parentRunId"] == run and child_view["lineage"] == "restart", (
                        "the child run lineage", child_view["parentRunId"], child_view["lineage"])
                    restarts = [receipt for _, receipt in command_receipts(cursor, harness)
                                if receipt["operation"] == "restart" and receipt["resource"] == lineage_uri]
                    assert len(restarts) == 1 and restarts[0]["state"] == "effect-observed" and restarts[0]["effect"]["kind"] == "lineage-created" \
                        and restarts[0]["effect"]["resource"] == child_uri, ("the restart command", restarts)
                    print("PASS pi-host 8: /wfm-restart created child request", child_id, "with one restart command, Pi showed its exact review",
                          "with the row", repr(lineage_row) + ", a and Yes approved preparation", child_preparation["id"], "and child run", child_run,
                          "succeeded with parentRunId", run, "and lineage restart", flush=True)

                    # 9. The export and its verified download.
                    export_name = "pi-host-export.json"
                    offset = len(session.output)
                    session.send(("/wfm-export " + run + " " + export_name + "\r").encode())
                    screen = printed(["Export " + export_name + ": export_", "state published", "Export download: verified ",
                                      "Exports of run " + run + ": 1"], offset, 45, "Pi did not report the published export")
                    pi.save_screen("export")
                    status, exports, raw = request(base + "/exports", harness)
                    assert status == 200, ("export collection", status, exports.get("code"))
                    validate("ExportPage", exports, raw)
                    assert len(exports["items"]) == 1, ("the export was not published once", exports["items"])
                    receipt = exports["items"][0]
                    assert receipt["name"] == export_name and receipt["state"] == "published" and receipt["runId"] == run, receipt
                    assert squeeze("Export " + export_name + ": " + receipt["id"] + " state published") in squeeze(screen), (
                        "Pi does not show the published export receipt", receipt["id"])
                    assert squeeze("Export download: verified " + str(receipt["bytes"]) + " bytes, SHA-256 " + receipt["sha256"]) in squeeze(screen), (
                        "Pi does not show the verified size and SHA-256 of the export", receipt["bytes"], receipt["sha256"])
                    connection = http.client.HTTPSConnection("127.0.0.1", port, context=context, timeout=15)
                    try:
                        connection.request("GET", receipt["download"], headers=harness | {"Accept": "application/octet-stream"})
                        response = connection.getresponse()
                        exported = response.read(int(receipt["bytes"]) + 1)
                        assert response.status == 200 and response.getheader("Content-Type") == "application/octet-stream", (
                            "export download", response.status)
                    finally:
                        connection.close()
                    assert len(exported) == int(receipt["bytes"]) and hashlib.sha256(exported).hexdigest() == receipt["sha256"], (
                        "the export download differs from its receipt")
                    assert (work / "manager" / "runs" / "exports" / export_name).read_bytes() == exported, (
                        "the export download differs from the published file")
                    print("PASS pi-host 9: /wfm-export published", receipt["id"], "named", export_name, "and Pi showed its verified",
                          receipt["bytes"], "bytes with the SHA-256", receipt["sha256"] + ", which equal the harness download and the published file",
                          flush=True)

                    # 10. A second request held at its question, a forced drop of
                    # the event stream of Pi, and the next events of the run.
                    created2, preparation2, run2 = create_and_approve("second")
                    held, _, _ = until("/v1/runs/" + run2 + "/control", "RunControl", lambda value: value["decisionHeadId"] is not None, timeout=90)
                    question2 = held["decisionHeadId"]
                    assert observed("/v1/decisions/" + question2, "Decision")[0]["kind"] == "question", ("the first head of the second run",)
                    # The harness starts its own view again by reading a new overview.
                    status, view, raw = request("/v1/snapshot", harness)
                    assert status == 200, ("overview", status)
                    validate("OverviewSnapshot", view, raw)
                    assert [item["run"]["id"] for item in view["items"] if item["kind"] == "run" and item["run"]["id"] == run2] == [run2], (
                        "the new overview does not list the second run")
                    session.send(b"/wfm-debug-reconnect\r")
                    shown(["Test hook: dropped the event stream after event "], 15, "/wfm-debug-reconnect did not report the drop")
                    drop_at = row_after("Test hook: dropped the event stream after event ")
                    order2, _, _ = answer_heads(run2, ("question",))
                    assert order2 == ["question"], ("the heads of the second run", order2)
                    recovering, _, _ = until("/v1/runs/" + run2 + "/control", "RunControl",
                                             lambda value: value["decisionHeadId"] not in (None, question2), timeout=60)
                    recovery2 = recovering["decisionHeadId"]
                    assert observed("/v1/decisions/" + recovery2, "Decision")[0]["kind"] == "recovery", ("the second head of the second run",)
                    session.send(("/wfm-monitor " + run2 + "\r").encode())
                    shown(["Service run " + run2 + ", workflow mixed-controls", "Runtime: running", "Decisions: 1 pending",
                           "Head " + recovery2 + ": pending recovery"], 60, "the monitor did not show the next head of the second run")
                    pi.save_screen("monitor-after-drop")
                    session.send(b"q")
                    session.settle()
                    deadline = time.monotonic() + 30
                    while True:
                        session.send(b"/wfm-debug-events\r")
                        shown(["Test hook: event stream dropped after event " + drop_at], 15, "/wfm-debug-events did not list the events")
                        rows = [line.strip() for line in session.screen.lines()]
                        first = max(i for i, line in enumerate(rows) if line.startswith("Test hook: event stream dropped after event "))
                        block = squeeze("".join(rows[first:]))
                        assert squeeze("Events delivered after the drop: ") in block, ("/wfm-debug-events shows no event count", rows[first:])
                        delivered = re.search(re.escape(squeeze("Events delivered after the drop: ")) + r"([0-9]+)of", block)
                        count = int(delivered.group(1)) if delivered else 0
                        # A cursor belongs to the authorization view of its
                        # credential, so the harness reads from its own cursor
                        # and keeps the events after the drop position.
                        events = [event for event in events_after(cursor)
                                  if int(event["id"].rsplit(".", 1)[1]) > int(drop_at.rsplit(".", 1)[1])]
                        ids = [event["id"] for event in events]
                        next_head = [i for i, event in enumerate(events)
                                     if event["event"] == "decision.changed" and event["data"]["resource"] == "/v1/decisions/" + recovery2]
                        if next_head and next_head[0] < count:
                            break
                        assert time.monotonic() < deadline, ("Pi did not receive the event of the next head", count, ids)
                        session.pump(0.5)
                    pi.save_screen("events-after-drop")
                    assert squeeze("Connections after the drop: stream " + drop_at) in block, (
                        "the first connection after the drop did not resume from the last delivered event", drop_at, block)
                    # Each authorization view names its own stream, and the
                    # views share the sequence numbers of the durable log.
                    assert all(event_id.rsplit(".", 1)[0] == cursor.rsplit(".", 1)[0] for event_id in ids), ("the events of another stream", ids)
                    listed = squeeze("Events delivered after the drop: " + str(count) + " of stream " + drop_at.rsplit(".", 1)[0] + ": "
                                     + " ".join(event_id.rsplit(".", 1)[1] for event_id in ids[:count]))
                    assert count <= len(ids) and listed in block, (
                        "the events delivered after the drop differ from the events of the manager", ids, block)
                    print("PASS pi-host 10: request", created2["id"], "started run", run2, "at question", question2 + ",",
                          "the harness read a new overview, /wfm-debug-reconnect dropped the stream of Pi after event", drop_at,
                          "and the stream resumed with Last-Event-ID", drop_at + ", the Pi answer moved the run to recovery head", recovery2,
                          "which the monitor showed, and the", count, "events that Pi received after the drop equal the events of the manager",
                          "from that cursor, without a gap", flush=True)

                    # 11. The reload of the extension.
                    session.send(b"/reload\r")
                    shown(["Reloaded keybindings, extensions"], 60, "Pi did not reload the extensions")
                    live = re.compile(re.escape(squeeze("Connection: connected to " + endpoint + " (endpoint identity")) + r"[^)]*\),deliverylive")
                    status_row = squeeze("  " + run2 + "  running  owned supervision  " + workflow["id"])
                    deadline = time.monotonic() + 30
                    while True:
                        session.send(b"/wfm-status\r")
                        settle = time.monotonic() + 2
                        while time.monotonic() < settle and not (live.search(squeeze(session.screen.text()))
                                                                 and status_row in squeeze(session.screen.text())):
                            session.pump(0.1)
                        if live.search(squeeze(session.screen.text())) and status_row in squeeze(session.screen.text()):
                            break
                        assert time.monotonic() < deadline and session.process.poll() is None, (
                            "/wfm-status after the reload did not show the second run with delivery live", session.screen.text())
                    pi.save_screen("reloaded")
                    still_running(run2, recovery2)
                    print("PASS pi-host 11: /reload reloaded ext-pi, /wfm-status showed delivery live and run", run2,
                          "running under owned supervision, and the harness read it running at its pending head", recovery2, flush=True)

                    # 12. Quit.
                    pi.quit()
                    still_running(run2, recovery2)
                    print("PASS pi-host 12: /quit ended Pi with exit status 0, and run", run2, "still runs under owned supervision at its pending head",
                          recovery2, flush=True)
                except BaseException:
                    pi.save_screen("failure")
                    pi.save_output()
                    raise

            # 13. Pi starts again with the same client profile, and the harness
            # revokes its credential.
            with PiHost("pi-host-again") as pi:
                session = pi.session
                try:
                    session.wait_screen("[Extensions]", timeout=60)
                    shown(["Manager connected: " + endpoint], 30, "Pi did not connect again with the same client profile")
                    commands_before = command_ids()
                    administration({"version": 1, "operation": "revoke-credential", "credentialId": tui_fixture.credential_ids["pi"]})
                    refusal = "the manager refused the credential (401 unauthenticated). No manager command is sent."
                    shown(["Manager refused: " + refusal], 30, "Pi did not show the refused credential")
                    pi.save_screen("revoked")
                    session.send(b"/wfm\r")
                    shown(["The manager is not connected. /wfm-status states the connection."], 15, "/wfm did not refuse to start")
                    session.send(b"/wfm-status\r")
                    shown(["Connection: refused for " + str(tui_fixture.client_profile) + ": " + refusal], 15,
                          "/wfm-status did not show the refused connection")
                    pi.save_screen("revoked-status")
                    assert command_ids() == commands_before, "Pi sent a command after its credential was refused"
                    still_running(run2, recovery2)
                    pi.quit()
                    print("PASS pi-host 13: Pi connected again with the same client profile, the harness revoked its credential, Pi showed",
                          repr("Manager refused: " + refusal) + ", /wfm started nothing, the ledger holds no new command, and run", run2,
                          "still runs at its pending head", flush=True)
                except BaseException:
                    pi.save_screen("failure")
                    pi.save_output()
                    raise
        print("PASS pi-host: the built Pi fork created, approved, answered with JSON false, retried, monitored to terminal success,",
              "saved the verified result, listed the history, restarted with lineage, exported, resumed its event stream without a gap,",
              "reloaded and quit with a held run under manager supervision, and refused a revoked credential, driven by keys", flush=True)
    finally:
        if process.poll() is None:
            process.terminate()
        process.wait(timeout=25)


def emacs_service_cleanup(artifacts, extra=()):
    """After the manager of an Emacs service mode stopped, require that no
    child remains, and remove the fixture secrets, the Emacs homes below
    artifacts and the extra paths. One listing gives the descendants of the
    harness and the processes whose command names the fixture directory,
    apart from the listing itself, the harness and its ancestors. Returns
    the number of removed paths."""
    listing = subprocess.Popen(["ps", "-Ao", "pid=,ppid=,command="], stdout=subprocess.PIPE, text=True)
    rows = [line.split(None, 2) for line in listing.communicate(timeout=10)[0].splitlines()]
    assert listing.returncode == 0, "the process listing failed"
    parents = {int(row[0]): int(row[1]) for row in rows}
    ancestors, pid = set(), os.getpid()
    while pid in parents and pid not in ancestors:
        ancestors.add(pid)
        pid = parents[pid]
    below, grown = {os.getpid()}, True
    while grown:
        grown = False
        for row in rows:
            if int(row[1]) in below and int(row[0]) not in below:
                below.add(int(row[0]))
                grown = True
    remaining = [row for row in rows if int(row[0]) != listing.pid and int(row[0]) not in ancestors and (
        int(row[0]) in below or (len(row) == 3 and str(work) in row[2]))]
    assert not remaining, ("a child of the journey remains", remaining)
    removed = ([work / "credential"] + sorted(work.glob("credential-*")) + [tui_fixture.client_profile] + sorted(artifacts.glob("*/home"))
               + [path for path in extra if path != tui_fixture.client_profile])
    for path in removed:
        if path.is_dir():
            shutil.rmtree(path)
        else:
            path.unlink()
    assert not any(path.exists() for path in removed), "a fixture credential or home remains"
    return len(removed)


def emacs_service_checks():
    """The emacs-service and emacs-service-broken-answer modes. See
    EMACS_SERVICE for the steps."""
    harness = tui_fixture.harness
    mode = sys.argv[5]
    selectors = ("reviewDigest", "requestRevision", "profileRevision", "descriptorRevision", "processGeneration")
    artifacts = work / "emacs-service"
    report_path = work / "emacs-service-report.json"
    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
    try:
        wait_ready(process)
        status, capabilities, _ = request("/v1/capabilities", harness)
        assert status == 200, ("capabilities", status)
        status, profiles, _ = request("/v1/profiles", harness)
        assert status == 200 and [item["id"] for item in profiles["items"]] == ["profile_1"], ("profiles", status)
        status, catalogue, _ = request("/v1/workflows?profileId=profile_1", harness)
        assert status == 200, ("catalogue", status)
        workflow = next(item for item in catalogue["items"] if item["name"] == "mixed-controls")
        status, overview, _ = request("/v1/snapshot", harness)
        assert status == 200 and not overview["items"], ("the overview is not empty before the journey", status)
        cursor = overview["cursor"]
        client = mixed_client(capabilities, harness)
        observed = client[0]
        environment = {name: os.environ[name] for name in EMACS_ALLOWLIST if name in os.environ}
        command = [sys.executable, "-B", emacs_ui, "--service", str(tui_fixture.client_profile), str(report_path),
                   "--service-answer", EMACS_SERVICE_ANSWER, "--emacs", emacs_program,
                   "--source", os.path.join(emacs_directory, "wf.el"), "--artifacts", str(artifacts)]
        with harness_reads_only():
            completed = subprocess.run(command, env=environment, stdin=subprocess.DEVNULL, timeout=840)
        report = json.loads(report_path.read_bytes()) if report_path.exists() else {"steps": []}
        assert completed.returncode == 0, ("the Emacs service journey of " + emacs_ui + " failed", completed.returncode, report["steps"])
        assert report["version"] == EMACS_SERVICE_REPORT_VERSION, (
            f"The {mode} mode requires report version {EMACS_SERVICE_REPORT_VERSION}, and {emacs_ui} wrote version {report['version']}.")
        assert report["steps"] == ["1", "2", "3", "4", "5", "6a", "6b", "7", "8", "9"], ("the steps of the journey", report["steps"])
        assert report["literal"] == EMACS_SERVICE_LITERAL and report["answer"] == EMACS_SERVICE_ANSWER, (
            "the report names another literal or answer", report["literal"], report["answer"])
        run = report["run"]
        base = "/v1/runs/" + run
        receipts = [receipt for _, receipt in command_receipts(cursor, harness)]

        # 1. The request and its literal.
        status, listed, _ = request("/v1/requests", harness)
        assert status == 200 and len(listed["items"]) == 1, ("the requests of the journey", status, listed.get("items"))
        created = listed["items"][0]
        request_uri = created["links"]["self"]
        assert created["id"] == report["reviewRequest"] and created["profileId"] == "profile_1" and created["workflowId"] == workflow["id"], (
            "the request names another identifier, profile or workflow", created["id"], created["profileId"], created["workflowId"])
        assert created["readiness"]["supplied"] == [{"name": "input", "source": "literal", "value": EMACS_SERVICE_LITERAL}], (
            "the request did not supply exactly the typed literal", created["readiness"]["supplied"])
        enqueues = [receipt for receipt in receipts if receipt["operation"] == "enqueue" and receipt["resource"] == request_uri]
        assert len(enqueues) == 1 and enqueues[0]["state"] == "effect-observed", ("the enqueue command", enqueues)
        sizes = [item["size"] for item in report["setupTexts"]]
        assert sizes == ["40x12", "140x36", "80x24"] and all(EMACS_SERVICE_LITERAL in item["text"] for item in report["setupTexts"]), (
            "the setup form did not keep the literal at each size", sizes)
        print("PASS emacs-service 1: wf-service and wf-run chose profile_1 and", workflow["name"], "by keys, request", created["id"],
              "supplied exactly the typed literal", repr(EMACS_SERVICE_LITERAL) + ", its one enqueue command reached its effect,",
              "and the setup form kept the literal at", ", ".join(sizes), flush=True)

        # 2. The exact review.
        preparation_uri = "/v1/preparations/" + report["reviewPreparation"]
        preparation, _, _ = observed(preparation_uri, "Preparation")
        text = report["reviewText"]
        assert f"Review of request {created['id']}, preparation {preparation['id']}" in text, ("the review names another preparation", text[:2000])
        assert all(f"  {name}: {preparation[name]}\n" in text for name in selectors) \
            and f"Program SHA-256: {preparation['review']['programHash']}\n" in text \
            and f"Workflow: {workflow['id']}\n" in text and "Profile: profile_1\n" in text, (
            "the review buffer does not show the exact review", text[:2000])
        assert [item["size"] for item in report["reviewTexts"]] == sizes and all(item["text"] == text for item in report["reviewTexts"]), (
            "the review changed at a resize")
        print("PASS emacs-service 2: the review buffer showed preparation", preparation["id"], "with review digest", preparation["reviewDigest"],
              "and each approval selector that the harness reads, the same at", ", ".join(sizes), flush=True)

        # 3. The approval.
        approvals = [receipt for receipt in receipts if receipt["operation"] == "approve" and receipt["resource"] == preparation_uri]
        assert len(approvals) == 1 and approvals[0]["state"] not in ("refused", "unresolved"), ("the approve command of the review", approvals)
        assert preparation["state"] == "consumed", ("the approved preparation", preparation["state"])
        associated, _, _ = observed(request_uri, "Request")
        assert associated["runId"] == run, ("the request names another run", associated["runId"], run)
        assert preparation["reviewDigest"] in report["approvePrompt"], ("the confirmation does not name the review digest", report["approvePrompt"])
        print("PASS emacs-service 3: a and yes sent the one approve command of preparation", preparation["id"], "after the confirmation",
              "with its review digest, and request", created["id"], "names run", run, flush=True)

        # 4. The answer of the question.
        question, recovery = report["question"], report["recovery"]
        # The manager serves only pending decisions, so the run store names
        # the occurrence of the person question.
        entries = [entry for path in work.glob("manager/runs/runs/*/runtime/answers.json")
                   for entry in json.loads(path.read_bytes())["answers"]
                   if (entry["question"].get("prompt") or "").startswith("Independent confirmation? " + EMACS_SERVICE_LITERAL)]
        assert len(entries) == 1, ("the run store holds no single answer of the person question", len(entries))
        occurrence = entries[0]["occurrenceId"]
        recorded = [entry["answer"] for entry in entries]
        snapshot, _, _ = observed(base + "/snapshot", "RunSnapshot")
        item = next(value for value in snapshot["items"] if value["occurrenceId"] == occurrence)
        # The snapshot publishes a flag answer as its rendered text, "no" for
        # false and "yes" for true.
        assert item["code"] == "flag" and {"no": False, "yes": True}.get(item["answer"], item["answer"]) is False \
            and recorded == [False], (EMACS_SERVICE_FALSE, item["answer"], recorded)
        assert [entry["size"] for entry in report["answerTexts"]] == sizes and all(
            entry["text"] == EMACS_SERVICE_ANSWER for entry in report["answerTexts"]), ("the answer editor lost the typed answer at a resize")
        answers = [receipt for receipt in receipts if receipt["operation"] == "answer"]
        assert len(answers) == 1 and answers[0]["resource"] == "/v1/decisions/" + question \
            and answers[0]["state"] == "effect-observed", ("the answer command", answers)
        print("PASS emacs-service 4: a and the typed answer", EMACS_SERVICE_ANSWER, "reached question", question + ", kept at",
              ", ".join(sizes) + ", the snapshot publishes the rendered false answer no, and the run store records JSON false", flush=True)

        # 5. The retry.
        retries = [receipt for receipt in receipts if receipt["operation"] == "retry"]
        assert len(retries) == 1 and retries[0]["resource"] == base + "/control" and retries[0]["state"] == "effect-observed", (
            "the retry command", retries)
        assert sorted(report["kinds"]) == ["question", "recovery"] and report["heads"] == [
            question if kind == "question" else recovery for kind in report["kinds"]], ("the handled heads", report["heads"], report["kinds"])
        print("PASS emacs-service 5: c sent the one offered retry of recovery decision", recovery + ", and its command reached its effect.",
              "The heads came in the order", " then ".join(report["kinds"]), flush=True)

        # 6. Terminal success and the verified result.
        snapshot, _, _ = observed(base + "/snapshot", "RunSnapshot")
        assert snapshot["runtime"] is not None and snapshot["runtime"]["status"] == "succeeded", ("the run did not succeed", snapshot["runtime"])
        artifact = verified_download(run, client, harness)
        assert report["finalLines"][-3:] == ["Terminal: succeeded", "Result: verified " + str(int(artifact["bytes"])) + " bytes",
                                             "Result SHA-256: " + artifact["sha256"]], ("the last lines of the view", report["finalLines"][-3:])
        print("PASS emacs-service 6: run", run, "succeeded, and its view showed the verified result of", artifact["bytes"],
              "bytes with the SHA-256", artifact["sha256"], "of the harness download", flush=True)

        # 7. The saved result.
        saved_path = Path(report["savedPath"])
        saved = saved_path.read_bytes()
        assert stat.S_IMODE(os.lstat(saved_path).st_mode) == 0o600, ("the saved file mode", oct(os.lstat(saved_path).st_mode))
        assert saved == (work / "verified-result.json").read_bytes() and len(saved) == int(artifact["bytes"]) \
            and hashlib.sha256(saved).hexdigest() == artifact["sha256"], "the saved bytes differ from the harness download"
        print("PASS emacs-service 7: r saved the", len(saved), "verified bytes of run", run, "to", saved_path,
              "with mode 0600, the size, the SHA-256 and the exact bytes of the harness download", flush=True)

        # 8. The terminal.
        assert report["exitStatus"] == 0 and report["terminalAfter"] == report["terminalBefore"], (
            "the terminal attributes after Emacs", report["exitStatus"])
        print("PASS emacs-service 8: C-x C-c ended Emacs with exit status 0, and the terminal attributes after its exit equal",
              "the attributes before its start", flush=True)
    finally:
        if process.poll() is None:
            process.terminate()
        process.wait(timeout=25)

    # 9. No child remains, and the fixture secrets and homes are removed.
    removed = emacs_service_cleanup(artifacts)
    print("PASS emacs-service 9: no Emacs, url or fixture process remains after the manager stopped, and the harness removed",
          removed, "credential, client profile and home paths", flush=True)
    print(f"PASS {mode}: Emacs selected the profile, set up, reviewed and approved mixed-controls, answered JSON false, sent the",
          "offered retry, followed the run to terminal success and saved the verified result, driven only by keys at 80x24",
          "with resizes to 40x12 and 140x36", flush=True)


def emacs_lifecycle_checks():
    """The emacs-service-lifecycle mode. See EMACS_SERVICE_LIFECYCLE for the
    steps."""
    harness = tui_fixture.harness
    mode = sys.argv[5]
    artifacts = work / "emacs-service-lifecycle"
    report_path = work / "emacs-service-lifecycle-report.json"
    handshake = work / "emacs-service-lifecycle-handshake"
    handshake.mkdir(mode=0o700)
    clone_legacy_runs(legacy_frontend_run(), LEGACY_ENTRIES - 1)

    def serve(index):
        """Start one foreground manager lifetime on the same root and
        configuration and wait for HTTPS readiness."""
        with (work / f"server-{index}.stdout").open("wb") as output, (work / f"server-{index}.stderr").open("wb") as errors:
            process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                        "--legacy-history", f"{LEGACY_ROOT}=profile_1",
                                        "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        wait_ready(process)
        return process

    # The command identifiers of the coordination database at each
    # handshake of the script, the preparations of the lineage children and
    # the command receipts before the restart.
    marks, prepared, earlier = {}, {}, {}

    def act(name, facts):
        """Do the action of the handshake name of the script and return the
        answer. stop-manager reads the preparations of the lineage children
        that the report names, since a new lifetime serves no preparation of
        an earlier lifetime, and the command receipts, since the restart
        makes the start of the lost run unresolved. It then kills the
        manager with SIGKILL.
        start-manager starts a new lifetime on the same root and
        configuration, and quit and kill-view only record the commands."""
        marks[name] = command_ids()
        if name == "stop-manager":
            named = json.loads(report_path.read_bytes())
            for child in ("forkRun", "restartRun"):
                prepared[child], _, _ = observed("/v1/preparations/" + named[child]["preparation"], "Preparation")
            earlier.update((receipt["id"], receipt) for _, receipt in command_receipts(cursor, harness))
            lifetimes[-1].kill()
            lifetimes[-1].wait(timeout=25)
            assert lifetimes[-1].returncode == -signal.SIGKILL, ("the manager did not end by SIGKILL", lifetimes[-1].returncode)
            return {"lifetime": len(lifetimes) - 1, "status": lifetimes[-1].returncode}
        if name == "start-manager":
            lifetimes.append(serve(len(lifetimes)))
            return {"lifetime": len(lifetimes) - 1}
        assert name in ("quit", "kill-view"), ("an unknown handshake of the lifecycle", name, facts)
        return {"commands": len(marks[name])}

    lifetimes = [serve(0)]
    try:
        status, capabilities, _ = request("/v1/capabilities", harness)
        assert status == 200 and "control" in capabilities["scopes"], ("capabilities", status)
        status, overview, _ = request("/v1/snapshot", harness)
        assert status == 200, ("snapshot", status)
        cursor = overview["cursor"]
        runs = ControlHarness(harness, capabilities, mode)
        observed = runs.client[0]
        environment = {name: os.environ[name] for name in EMACS_ALLOWLIST if name in os.environ}
        command = [sys.executable, "-B", emacs_ui, "--service", str(tui_fixture.client_profile), str(report_path),
                   "--service-case", "lifecycle", "--service-handshake", str(handshake), "--emacs", emacs_program,
                   "--source", os.path.join(emacs_directory, "wf.el"), "--artifacts", str(artifacts)]
        handled = []
        with harness_reads_only():
            script = subprocess.Popen(command, env=environment, stdin=subprocess.DEVNULL)
            try:
                deadline = time.monotonic() + 840
                while script.poll() is None:
                    assert time.monotonic() < deadline, "the Emacs service lifecycle did not end in 840 seconds"
                    for path in sorted(handshake.glob("*.json")):
                        if path.stem not in handled:
                            handled.append(path.stem)
                            answer = handshake / (path.stem + ".done.new")
                            answer.write_text(json.dumps(act(path.stem, json.loads(path.read_text()))))
                            answer.rename(handshake / (path.stem + ".done"))
                    time.sleep(0.05)
            finally:
                if script.poll() is None:
                    script.kill()
                script.wait(timeout=25)
        ended = command_ids()
        report = json.loads(report_path.read_bytes()) if report_path.exists() else {"steps": []}
        assert script.returncode == 0, ("the Emacs service lifecycle of " + emacs_ui + " failed", script.returncode, report["steps"])
        assert report["version"] == LIFECYCLE_REPORT_VERSION, (
            f"The {mode} mode requires report version {LIFECYCLE_REPORT_VERSION}, and {emacs_ui} wrote version {report['version']}.")
        assert report["steps"] == [str(number) for number in range(1, 23)], ("the steps of the lifecycle", report["steps"])
        assert handled == ["stop-manager", "start-manager", "quit", "kill-view"], ("the handshakes of the lifecycle", handled)
        assert [report[name] for name in ("first", "second", "capture", "steer", "answer", "forked", "forkOccurrence", "export",
                                          "pending")] == [
            LIFECYCLE_FIRST, LIFECYCLE_SECOND, LIFECYCLE_CAPTURE, LIFECYCLE_STEER, "false", LIFECYCLE_FORKED,
            LIFECYCLE_FORK_OCCURRENCE, LIFECYCLE_EXPORT, LIFECYCLE_PENDING], "the report names other literals"
        first, second, captured = report["firstRun"], report["secondRun"], report["capturedRun"]
        fork, restart, pending = report["forkRun"], report["restartRun"], report["pendingRun"]
        receipts = [receipt for _, receipt in command_receipts(cursor, harness)]

        def stores_of(prompt):
            """The run store, the event envelopes and the lineage of the
            supervisor manifest of each run whose events name the prompt."""
            found = []
            for store in sorted(work.glob("manager/runs/runs/*/runtime")):
                envelopes = [json.loads(line) for line in (store / "events.ndjson").read_bytes().splitlines()]
                if any(envelope["event"].get("prompt") == prompt for envelope in envelopes):
                    manifest = json.loads((store.parent / "supervisor-manifest.json").read_bytes())
                    found.append((store, envelopes, manifest["lineage"]))
            return found

        def store_of(prompt, child=False):
            """The run store and the event envelopes of the one run that
            started an occurrence with the prompt, of a lineage child when
            child holds and of a run without lineage otherwise."""
            found = [(store, envelopes) for store, envelopes, lineage in stores_of(prompt) if (lineage is not None) == child
                     and any(envelope["event"]["type"] == "occurrence.started" and envelope["event"].get("prompt") == prompt
                             for envelope in envelopes)]
            assert len(found) == 1, ("the run store of the prompt", prompt, child, len(found))
            return found[0]

        def at(envelope):
            return datetime.datetime.fromisoformat(envelope["timestamp"].replace("Z", "+00:00"))

        # 1. The two delayed requests.
        for facts, profile, literal in ((first, "profile_1", LIFECYCLE_FIRST), (second, "profile_2", LIFECYCLE_SECOND)):
            status, catalogue, _ = request("/v1/workflows?profileId=" + profile, harness)
            assert status == 200, ("catalogue", profile, status)
            workflow = next(item for item in catalogue["items"] if item["name"] == "delayed-person")
            created, _, _ = observed("/v1/requests/" + facts["request"], "Request")
            assert created["profileId"] == profile and created["workflowId"] == workflow["id"] and created["runId"] == facts["run"], (
                "the delayed request", facts["request"], created["profileId"], created["workflowId"], created["runId"])
            assert created["readiness"]["supplied"] == [{"name": "input", "source": "literal", "value": literal}], (
                "the request did not supply exactly the typed literal", created["readiness"]["supplied"])
            enqueues = [receipt for receipt in receipts if receipt["operation"] == "enqueue" and receipt["resource"] == created["links"]["self"]]
            approvals = [receipt for receipt in receipts if receipt["operation"] == "approve"
                         and receipt["resource"] == "/v1/preparations/" + facts["preparation"]]
            assert len(enqueues) == 1 and enqueues[0]["state"] == "effect-observed" and len(approvals) == 1 \
                and approvals[0]["state"] not in ("refused", "unresolved"), ("the enqueue and approve commands", enqueues, approvals)
        print("PASS emacs-service-lifecycle 1: at 140x36 wf-run created requests", first["request"], "of profile_1 and", second["request"],
              "of profile_2 for delayed-person with exactly the typed literals, each with one enqueue that reached its effect and one",
              "approve, and they name runs", first["run"], "and", second["run"], flush=True)

        # 2. The delayed questions, from the run log.
        delays = []
        for literal in (LIFECYCLE_FIRST, LIFECYCLE_SECOND):
            store, envelopes = store_of("Draft a reply: " + literal)
            kinds = [(envelope["event"]["type"], envelope["event"].get("addressee", "")) for envelope in envelopes]
            engine = kinds.index(("occurrence.started", "model fixed-point"))
            engine_occurrence = envelopes[engine]["event"]["occurrenceId"]
            done = next(index for index, envelope in enumerate(envelopes) if envelope["event"]["type"] == "occurrence.completed"
                        and envelope["event"]["occurrenceId"] == engine_occurrence)
            asked = kinds.index(("occurrence.started", "person owner"))
            assert engine < done < asked and envelopes[asked]["event"]["prompt"] == "Delayed confirmation? yes", (
                "the person question did not follow the engine answer", kinds)
            delays.append((at(envelopes[asked]) - at(envelopes[0])).total_seconds())
            assert delays[-1] >= LIFECYCLE_DELAY - 1, ("the person question was not delayed", delays[-1])
        assert report["splitHeads"] == [None, None], ("a question was pending when the windows were set up", report["splitHeads"])
        print("PASS emacs-service-lifecycle 2: the run logs show each person question started only after its engine occurrence",
              "completed,", " and ".join(f"{delay:.1f}" for delay in delays), "seconds after the start of its run, and no decision",
              "was pending when the two windows were set up", flush=True)

        # 3. The independent windows.
        for name in ("splitWindows", "askedWindows", "answeredWindows"):
            windows = report[name]
            assert windows[0]["point"] == 1 and windows[1]["point"] == windows[1]["maximum"] > 1 \
                and windows[0]["buffer"] == "*wf service run " + first["run"] + "*" \
                and windows[1]["buffer"] == "*wf service run " + second["run"] + "*", ("the window points", name, windows)
        assert all(report["splitLines"][index] != report["answeredLines"][index] for index in (0, 1)), (
            "a run made no progress while the windows followed it", report["splitLines"], report["answeredLines"])
        assert report["editorWindows"] == 3, ("the answer editor did not open in its own window", report["editorWindows"])
        print("PASS emacs-service-lifecycle 3: the window of run", first["run"], "kept its point at the start and the window of run",
              second["run"], "kept its point at the end when the windows were set up, when the question arrived and after the",
              "first run succeeded, both views changed meanwhile, and the answer editor opened in a third window", flush=True)

        # 4. The answer and the first run.
        question = report["question"]
        answers = [receipt for receipt in receipts if receipt["operation"] == "answer"]
        assert len(answers) == 1 and answers[0]["resource"] == "/v1/decisions/" + question \
            and answers[0]["state"] == "effect-observed", ("the answer command", answers)
        store, _ = store_of("Draft a reply: " + LIFECYCLE_FIRST)
        recorded = [entry for entry in json.loads((store / "answers.json").read_bytes())["answers"]
                    if entry["question"].get("prompt") == "Delayed confirmation? yes"]
        snapshot, _, _ = observed("/v1/runs/" + first["run"] + "/snapshot", "RunSnapshot")
        item = occurrence_of(snapshot, recorded[0]["occurrenceId"]) if len(recorded) == 1 else None
        assert [entry["answer"] for entry in recorded] == [False] and item["code"] == "flag" and item["answer"] == "no", (
            "the delayed question did not record JSON false", recorded, item and item["answer"])
        assert snapshot["runtime"]["status"] == "succeeded" and "Terminal: succeeded" in report["answeredLines"][0] \
            and any(line.startswith("Terminal: not yet") for line in report["answeredLines"][1]), (
            "the first run did not succeed while the second run ran", snapshot["runtime"]["status"], report["answeredLines"][1])
        print("PASS emacs-service-lifecycle 4: a and false sent the one answer of question", question, "of run", first["run"] + ",",
              "the run store records JSON false, the snapshot publishes no, and the run succeeded while run", second["run"],
              "had not ended", flush=True)

        # 5. The captured input.
        captured_bytes = LIFECYCLE_CAPTURE.encode("utf-8")
        digest = hashlib.sha256(captured_bytes).hexdigest()
        request_value, _, _ = observed("/v1/requests/" + captured["request"], "Request")
        supplied = request_value["readiness"]["supplied"]
        assert request_value["profileId"] == "profile_steer" and request_value["runId"] == captured["run"] and len(supplied) == 1 \
            and supplied[0]["name"] == "input" and supplied[0]["source"] == "capture", ("the captured request", request_value["profileId"], supplied)
        assert len([receipt for receipt in receipts if receipt["operation"] == "capture"]) == 1, "the capture commands"
        assert LIFECYCLE_CAPTURE in captured["formText"], "the setup form did not show the captured text"
        store_of("fixed-point source: " + digest)
        print("PASS emacs-service-lifecycle 5: at 80x24 the Buffer source captured the", len(captured_bytes), "bytes of the editor",
              "buffer as capture", supplied[0]["captureId"], "of request", captured["request"] + ", with one capture command, and the",
              "program of run", captured["run"], "asked for their SHA-256", digest, flush=True)

        # 6. The cancel.
        rows = runs.command_rows(["/v1/runs/" + second["run"] + "/control"])
        assert [row[1] for row in rows] == ["cancel"] and rows[0][3] is not None \
            and rows[0][3]["state"] in ("accepted", "queued", "delivered"), ("the cancel was not sent exactly once", rows)
        runs.ended(second["run"], "cancelled")
        assert "Terminal: cancelled" in report["cancelledLines"] and "Cancel run " + second["run"] in report["cancelPrompt"], (
            "the cancel step", report["cancelPrompt"], report["cancelledLines"])
        print("PASS emacs-service-lifecycle 6: C-c C-k and yes sent the one cancel command", rows[0][0], "of run", second["run"],
              "after the confirmation, the runtime acknowledgement is", rows[0][3]["state"] + ", and the run ended cancelled", flush=True)

        # 7. The steer.
        found = re.fullmatch(r"steer occurrence (\d+) attempt (\d+), interrupt-now", report["steerChoice"]["description"])
        assert found is not None, ("the steer choice", report["steerChoice"])
        sizes = ["40x12", "140x36", "80x24"]
        control_prompt = "Control of run " + captured["run"] + ": " + report["steerChoice"]["label"]
        assert [item["size"] for item in report["controlPromptTexts"]] == sizes \
            and all(item["text"] == control_prompt for item in report["controlPromptTexts"]), (
            "the open control prompt did not keep the typed label at each size", report["controlPromptTexts"])
        assert [item["size"] for item in report["steerTexts"]] == sizes \
            and all(item["text"] == LIFECYCLE_STEER for item in report["steerTexts"]), (
            "the steer editor did not keep exactly the typed text at each size", report["steerTexts"])
        rows = runs.command_rows(["/v1/runs/" + captured["run"] + "/control"])
        assert [row[1] for row in rows] == ["steer"], ("the steer was not sent exactly once", rows)
        control, steers = runs.steered(captured["run"], "/v1/commands/" + rows[0][0], found.group(1), found.group(2), LIFECYCLE_STEER)
        runs.ended(captured["run"], "succeeded")
        print("PASS emacs-service-lifecycle 7: the open control prompt kept the typed label", report["steerChoice"]["label"],
              "at", ", ".join(item["size"] for item in report["controlPromptTexts"]) + ", the steer editor kept exactly its",
              "typed text at", ", ".join(item["size"] for item in report["steerTexts"]) + ", and c and",
              report["steerChoice"]["label"], "sent the one steer command", rows[0][0],
              "of attempt", found.group(2), "of occurrence", found.group(1), "of run", captured["run"], "with the timing interrupt-now",
              "and its editor text. It reached the effect steered, the run log holds control", control["position"], "from the",
              "manager and steer record", steers[0]["position"], "with the typed text, and the run succeeded", flush=True)

        # 8. The history over every page. The runs of the later steps did
        # not exist when Emacs listed the history.
        history, observers, pages = run_history(harness)
        later = {fork["run"], restart["run"], pending["run"]}
        assert pages >= 2 and observers == LEGACY_ENTRIES and all(item["run"] in history for item in (first, second, captured)) \
            and later <= set(history), ("the history pages", pages, observers, len(history))
        listed = [run for run in history if run not in later]
        assert report["historyRuns"] == listed and report["historyPages"] == pages, (
            "the wf-history rows differ from every page of /v1/runs", report["historyPages"], len(report["historyRuns"]), len(listed))
        assert report["openedLines"][0].startswith("Service run " + first["run"]), ("the opened view", report["openedLines"][:1])
        print("PASS emacs-service-lifecycle 8: at 40x12 wf-history listed the", len(listed), "runs of all", pages, "pages of",
              "/v1/runs in the order of the collection, and RET opened the view of run", first["run"], flush=True)

        # 9. The saved result.
        artifact = verified_download(first["run"], runs.client, harness)
        saved_path = Path(report["savedPath"])
        saved = saved_path.read_bytes()
        assert stat.S_IMODE(os.lstat(saved_path).st_mode) == 0o600, ("the saved file mode", oct(os.lstat(saved_path).st_mode))
        assert saved == (work / "verified-result.json").read_bytes() and len(saved) == int(artifact["bytes"]) \
            and hashlib.sha256(saved).hexdigest() == artifact["sha256"], "the saved bytes differ from the harness download"
        print("PASS emacs-service-lifecycle 9: r saved the", len(saved), "verified bytes of run", first["run"], "to", saved_path,
              "with mode 0600 and exactly the bytes of the harness download", flush=True)

        # 10 and 11. The lineage children.
        def lineage_child(facts, preparation, operation, parent, edits):
            """Require that the child request of facts has exactly one lineage
            command of the parent, one enqueue and one approve of its exact
            review, with the effects and facts that the manager states. The
            preparation and the state of the approval are those that the
            harness read before the restart. Returns the receipt of the
            lineage command and the receipt of the approval."""
            lineage_uri = "/v1/runs/" + parent + "/lineage-requests"
            created = [receipt for receipt in receipts if receipt["resource"] == lineage_uri]
            enqueues = [receipt for receipt in receipts if receipt["resource"] == "/v1/requests/" + facts["request"]]
            approvals = [receipt for receipt in receipts if receipt["resource"] == "/v1/preparations/" + facts["preparation"]]
            assert [receipt["operation"] for receipt in created + enqueues + approvals] == [operation, "enqueue", "approve"], (
                "the commands of the child", operation, [(receipt["resource"], receipt["operation"]) for receipt in created + enqueues + approvals])
            assert created[0]["state"] == "effect-observed" and created[0]["effect"]["kind"] == "lineage-created" \
                and created[0]["effect"]["resource"] == "/v1/requests/" + facts["request"], (
                "the lineage command", operation, created[0]["state"], created[0]["effect"])
            assert earlier[approvals[0]["id"]]["state"] not in ("refused", "unresolved"), (
                "the approval of the child before the restart", operation, earlier[approvals[0]["id"]]["state"])
            status, lineage, raw = request(lineage_uri, harness)
            assert status == 200, ("the lineage collection", operation, status, lineage.get("code"))
            validate("LineagePage", lineage, raw)
            assert [(item["lineage"], item["parentRunId"]) for item in lineage["items"] if item["id"] == facts["request"]] == [
                (operation, parent)], ("the lineage collection of the parent run", operation, lineage["items"])
            child, _, _ = observed("/v1/requests/" + facts["request"], "Request")
            assert child["runId"] == facts["run"] and child["phase"] == "associated" and child["parentRunId"] == parent \
                and child["lineage"] == operation, ("the child request", operation, child["runId"], child["phase"])
            assert f"Lineage: {operation} of run {parent}\n" in facts["reviewText"] \
                and f"Review of request {facts['request']}, preparation {facts['preparation']}" in facts["reviewText"], (
                "the review buffer of the child", operation, facts["reviewText"][:2000])
            assert preparation["id"] == facts["preparation"] and preparation["requestId"] == facts["request"] and preparation["state"] == "consumed" \
                and preparation["review"]["lineage"] == {"parentRunId": parent, "operation": operation, "edits": edits}, (
                "the review lineage of the child", operation, preparation["state"], preparation["review"].get("lineage"))
            run_value, _, _ = observed("/v1/runs/" + facts["run"], "Run")
            assert run_value["parentRunId"] == parent and run_value["lineage"] == operation, (
                "the child run", operation, run_value["parentRunId"], run_value["lineage"])
            return created[0], approvals[0]

        forked_json = json.dumps(True, separators=(",", ":"))
        fork_sha256 = hashlib.sha256(forked_json.encode("utf-8")).hexdigest()
        fork_receipt, _ = lineage_child(fork, prepared["forkRun"], "fork", first["run"],
                                     [{"occurrenceId": LIFECYCLE_FORK_OCCURRENCE, "operation": "replace", "sha256": fork_sha256}])
        assert recorded[0]["occurrenceId"] == LIFECYCLE_FORK_OCCURRENCE and fork["forkPrefill"] == "no", (
            "the replacement minibuffer did not start with the published answer of the person question", recorded[0]["occurrenceId"],
            fork["forkPrefill"])
        assert f"  replace occurrence {LIFECYCLE_FORK_OCCURRENCE} with the answer of SHA-256 {fork_sha256}\n" in fork["reviewText"], (
            "the fork review does not show the SHA-256 of the replacement", fork["reviewText"][:2000])
        runs.ended(fork["run"], "succeeded")
        fork_snapshot, _, _ = observed("/v1/runs/" + fork["run"] + "/snapshot", "RunSnapshot")
        fork_item = occurrence_of(fork_snapshot, LIFECYCLE_FORK_OCCURRENCE)
        assert fork_item["code"] == "flag" and fork_item["answer"] == "yes", ("the fork child did not answer yes", fork_item.get("answer"))
        assert "Terminal: succeeded" in report["forkLines"], ("the view of the fork child", report["forkLines"])
        print("PASS emacs-service-lifecycle 10: at 80x24 F, the replacement", LIFECYCLE_FORKED, "of occurrence", LIFECYCLE_FORK_OCCURRENCE,
              "and send sent the one fork command", fork_receipt["id"], "of run", first["run"], "whose effect created request",
              fork["request"] + ". Its exact review showed the lineage and the SHA-256", fork_sha256, "of the replacement, its one",
              "approve started run", fork["run"], "with the published answer yes, and the run succeeded", flush=True)
        restart_receipt, restart_approval = lineage_child(restart, prepared["restartRun"], "restart", second["run"], [])
        print("PASS emacs-service-lifecycle 11: R sent the one restart command", restart_receipt["id"], "of run", second["run"],
              "whose effect created request", restart["request"] + ", and the one approve of its exact review with the lineage",
              "started run", restart["run"], flush=True)

        # 12. The export of the fork child.
        exports_uri = "/v1/runs/" + fork["run"] + "/exports"
        sent = [receipt for receipt in receipts if receipt["resource"] == exports_uri]
        assert [receipt["operation"] for receipt in sent] == ["export"] and sent[0]["state"] == "effect-observed" \
            and sent[0]["effect"]["kind"] == "exported" and sent[0]["effect"]["resource"] == "/v1/exports/export_" + sent[0]["id"], (
            "the export command", [(receipt["operation"], receipt["state"]) for receipt in sent])
        status, detail, raw = request(sent[0]["effect"]["resource"], harness)
        assert status == 200, ("the export receipt", status)
        validate("ExportReceipt", detail, raw)
        assert detail["state"] == "published" and detail["name"] == LIFECYCLE_EXPORT and detail["runId"] == fork["run"], (
            "the export", detail["state"], detail["name"], detail["runId"])
        status, exports, raw = request(exports_uri, harness)
        assert status == 200 and [item["id"] for item in exports["items"]] == [detail["id"]], (
            "the export collection of the run", status, exports.get("items"))
        connection = http.client.HTTPSConnection("127.0.0.1", port, context=context, timeout=15)
        try:
            connection.request("GET", detail["download"], headers=harness | {"Accept": "application/octet-stream"})
            response = connection.getresponse()
            exported = response.read(int(detail["bytes"]) + 1)
            assert response.status == 200, ("the harness download of the export", response.status)
        finally:
            connection.close()
        assert len(exported) == int(detail["bytes"]) and hashlib.sha256(exported).hexdigest() == detail["sha256"], (
            "the export download differs from its receipt", len(exported), detail["bytes"])
        assert report["exportText"].startswith(
            f"Export {LIFECYCLE_EXPORT}: {detail['id']} state published, command {sent[0]['id']}\n"
            f"Export download: verified {len(exported)} bytes, SHA-256 {detail['sha256']}\n"
            f"Exports of run {fork['run']}: 1\n"), ("the export buffer", report["exportText"])
        print("PASS emacs-service-lifecycle 12: E sent the one export command", sent[0]["id"], "of run", fork["run"], "and the",
              "manager published", LIFECYCLE_EXPORT, "as", detail["id"] + ". Its download of", len(exported), "bytes verifies",
              "against the SHA-256", detail["sha256"], "and the export buffer states that receipt, the verified download and the",
              "export collection", flush=True)

        # 13. The manager restart while the view of the restart child was
        # open at its question.
        restart_snapshot, _, _ = observed("/v1/runs/" + restart["run"] + "/snapshot", "RunSnapshot")
        restart_run, _, _ = observed("/v1/runs/" + restart["run"], "Run")
        published = restart_snapshot["runtime"]["status"] if restart_snapshot["runtime"] is not None else "not yet observed"
        held_question = report["heldQuestion"]
        assert report["stopped"] == {"lifetime": 0, "status": -signal.SIGKILL} and report["started"] == {"lifetime": 1}, (
            "the handshakes of the restart", report["stopped"], report["started"])
        assert "Supervision: owned" in report["heldLines"] and any(held_question in line for line in report["heldLines"]), (
            "the view of the restart child before the restart", report["heldLines"])
        assert "Delivery: unreachable" in report["lostLines"] and any(held_question in line for line in report["lostLines"]) \
            and not any(line.startswith("Terminal: ") and not line.startswith("Terminal: not yet") for line in report["lostLines"]), (
            "the view did not keep the run after the loss of the manager", report["lostLines"])
        assert restart_approval["state"] == "unresolved", ("the start of the lost run after the restart", restart_approval["state"])
        assert restart_run["supervision"] == "lost" and "Supervision: lost" in report["reconnectedLines"] \
            and "Delivery: poll" in report["reconnectedLines"] and "Runtime: " + published in report["reconnectedLines"], (
            "the view of the restarted manager", restart_run["supervision"], published, report["reconnectedLines"])
        # No command was added while the manager was lost or after its
        # restart until the next setup form, and no command of the later
        # steps repeats an earlier command.
        assert marks["start-manager"] == marks["stop-manager"], (
            "a command was added while the manager was lost", marks["start-manager"] - marks["stop-manager"])
        before = [receipt for receipt in receipts if receipt["id"] in marks["stop-manager"]]
        after = [receipt for receipt in receipts if receipt["id"] not in marks["stop-manager"]]
        assert {receipt["id"] for receipt in before} == marks["stop-manager"], ("the receipts before the restart", len(before))
        # A creation receipt names only the request collection, so the one
        # creation after the restart is the creation of the waiting request
        # of profile_1. Every other command is its target and its operation.
        creations = [receipt for receipt in after if receipt["operation"] == "create"]
        pairs = [(receipt["resource"], receipt["operation"]) for receipt in after if receipt["operation"] != "create"]
        pending_resources = {"/v1/requests/" + pending["request"], "/v1/preparations/" + pending["preparation"]}
        assert [(receipt["resource"], receipt["profileId"]) for receipt in creations] == [("/v1/requests", "profile_1")] \
            and all(resource in pending_resources for resource, _ in pairs) and len(set(pairs)) == len(pairs) \
            and not set(pairs) & {(receipt["resource"], receipt["operation"]) for receipt in before} \
            and [operation for _, operation in pairs if operation in ("enqueue", "approve")] == ["enqueue", "approve"], (
            "a command after the restart is not one command of the setup of run " + pending["run"],
            [(receipt["resource"], receipt["operation"]) for receipt in after])
        print("PASS emacs-service-lifecycle 13: the harness killed the manager while the view of run", restart["run"], "waited at",
              "its question", held_question + ". With no key the view reported the delivery unreachable and kept the question, and",
              "after the new lifetime it reconnected with the delivery poll, the supervision lost and the runtime status",
              published, "that the restarted manager publishes, which made the approved start unresolved. The", len(marks["stop-manager"]), "commands before the restart are",
              "the commands after the reconnect, and the", len(after), "later commands are each sent once for the setup of run",
              pending["run"], flush=True)

        # 14 to 16. The quit, the new Emacs and the kill of its view.
        pending_question = report["pendingQuestion"]
        assert marks["quit"] == marks["kill-view"] == ended, (
            "the quit of Emacs, the new Emacs or the kill of the view created a command", ended - marks["quit"])
        assert runs.command_rows(["/v1/runs/" + pending["run"] + "/control", "/v1/decisions/" + pending_question]) == [], (
            "a command names the run that waited at the quit", pending["run"])
        assert not [receipt for receipt in receipts if receipt["operation"] == "cancel" and receipt["resource"] != "/v1/runs/" + second["run"] + "/control"], (
            "a cancel command names another run than the cancelled run")
        pending_run, _, _ = observed("/v1/runs/" + pending["run"], "Run")
        pending_control, _, _ = observed("/v1/runs/" + pending["run"] + "/control", "RunControl")
        pending_decision, _, _ = observed("/v1/decisions/" + pending_question, "Decision")
        assert pending_run["supervision"] == "owned" and pending_control["decisionHeadId"] == pending_question \
            and pending_decision["state"] == "pending" and pending_decision["kind"] == "question", (
            "the run is not pending at its question under the manager", pending_run["supervision"], pending_control["decisionHeadId"],
            pending_decision["state"])
        assert report["exitStatus"] == 0 and report["terminalAfter"] == report["terminalBefore"], (
            "the terminal attributes after the quit of Emacs", report["exitStatus"])
        print("PASS emacs-service-lifecycle 14: C-x C-c quit Emacs with exit status 0 and the terminal attributes restored while",
              "run", pending["run"], "waited at its question", pending_question + ". The coordination database holds the same",
              len(ended), "commands before the quit and after the new Emacs ended, no cancel or answer names the run, and the",
              "manager still owns the run at its pending question", flush=True)
        assert "Supervision: owned" in report["foundLines"] and any(pending_question in line for line in report["foundLines"]), (
            "the new Emacs did not find the pending question", report["foundLines"])
        print("PASS emacs-service-lifecycle 15: in a new Emacs with the same profile, the view of run", pending["run"], "showed its",
              "pending question", pending_question, "and the supervision owned", flush=True)
        assert report["killedBuffer"] == "*wf service run " + pending["run"] + "*" and marks["kill-view"] == ended, (
            "the kill of the view", report["killedBuffer"])
        assert report["laterExitStatus"] == 0 and report["laterTerminalAfter"] == report["laterTerminalBefore"], (
            "the terminal attributes after the new Emacs", report["laterExitStatus"])
        print("PASS emacs-service-lifecycle 16: C-x k killed the view", report["killedBuffer"], "and sent no command, and the new",
              "Emacs ended with exit status 0 and the terminal attributes restored", flush=True)

        # The run of the quit ends with the answer of the harness, so that
        # no run is active when the manager stops.
        runs.settle(pending["run"], "succeeded")
    finally:
        for lifetime in lifetimes:
            if lifetime.poll() is None:
                lifetime.terminate()
            lifetime.wait(timeout=25)

    # 17. No child remains, and the fixture secrets and homes are removed.
    removed = emacs_service_cleanup(artifacts)
    print("PASS emacs-service-lifecycle 17: no Emacs, url or fixture process remains after the manager stopped, and the harness",
          "removed", removed, "credential, client profile and home paths", flush=True)
    print(f"PASS {mode}: Emacs followed two delayed runs in two windows with independent points at 140x36, answered a delayed",
          "question while the other run ran, captured an editor buffer, cancelled after the confirmation and steered at 80x24,",
          "listed every history page and saved the verified result of an earlier run at 40x12, made, reviewed and approved a fork",
          "child and a restart child and exported a result at 80x24, reconnected after a manager restart with no command sent",
          "again, and left a waiting run to the manager across a quit, a new Emacs and the kill of a view, driven only by keys",
          flush=True)


def emacs_controls_checks():
    """The emacs-service-controls mode. See EMACS_SERVICE_CONTROLS for the
    steps."""
    harness = tui_fixture.harness
    mode = sys.argv[5]
    artifacts = work / "emacs-service-controls"
    report_path = work / "emacs-service-controls-report.json"
    handshake = work / "emacs-service-controls-handshake"
    handshake.mkdir(mode=0o700)
    # The facts of each control, by the name of its handshakes.
    facts = {}

    def native_command(command):
        """The native runtime command of the control intent of the command."""
        found = read_coordination("SELECT native_command FROM control_intents WHERE command_id = ?", (command,))
        assert len(found) == 1, ("the control intent of the command", command, found)
        return found[0][0]

    def one_recovery(name, choice):
        """The one command of the decision of the named control is a
        choose-recovery with the choice that reached effect-observed.
        Returns the command identifier and its receipt."""
        decision = facts[name]["decision"]
        rows = runs.command_rows(["/v1/decisions/" + decision["id"]])
        assert [(row[1], row[2]) for row in rows] == [("choose-recovery", "effect-observed")], (
            "Emacs did not send exactly one recovery choice that reached its effect", name, rows)
        assert native_command(rows[0][0]) == choice + "Occurrence", ("the native command of the recovery choice", name, native_command(rows[0][0]))
        receipt, _, raw = observed("/v1/commands/" + rows[0][0], "CommandReceipt")
        (work / (mode + "-" + name + "-receipt.json")).write_bytes(raw)
        assert receipt["effect"]["kind"] == "recovery-chosen", ("recovery effect", name, receipt["effect"])
        assert rows[0][3] is not None and rows[0][3]["command"] == "choose-recovery", ("recovery acknowledgement", name, rows[0][3])
        return rows[0][0], receipt

    def act(name):
        """Do the action of the handshake name of the script and return the
        answer. A -ready handshake starts the run of the control and names
        it, and a -sent handshake confirms the control and settles the run."""
        if name in ("failover-ready", "abandon-ready"):
            control = name.split("-")[0]
            before = set(work.glob("manager/runs/runs/*/runtime"))
            run = runs.start("profile_route" if control == "failover" else "profile_1")
            store = runs.new_store(before)
            decision = runs.until_recovery(run)
            assert any(item["choice"] == control for item in decision["choices"]), (control + " not published", decision["choices"])
            facts[control] = {"run": run, "store": store, "decision": decision}
            return {"run": run, "decision": decision["id"]}
        if name == "failover-sent":
            run, decision = facts["failover"]["run"], facts["failover"]["decision"]
            facts["failover"]["command"], _ = one_recovery("failover", "failover")
            runs.settle(run, "succeeded")
            records = runs.run_records(run)
            (work / (mode + "-failover-routes.json")).write_text(json.dumps(records, default=str))
            occurrence = decision["address"]["occurrenceId"]
            questions = model_questions(records, occurrence)
            assert len(questions) == 2 and questions[1]["to"]["to"]["model"].endswith("@spare"), (
                "fail-over questions", [(record["position"], record["to"]) for record in questions])
            answers = [record for record in records if record["schema"] == "answer" and record.get("replyTo") == questions[1]["position"]]
            assert len(answers) == 1 and answers[0]["from"] == {"model": questions[1]["to"]["to"]["model"]}, ("spare answer", answers)
            facts["failover"]["questions"] = questions
            return {"status": "succeeded"}
        if name == "abandon-sent":
            run, decision = facts["abandon"]["run"], facts["abandon"]["decision"]
            facts["abandon"]["command"], _ = one_recovery("abandon", "abandon")
            queue, _, _ = observed("/v1/decisions?runId=" + run, "DecisionPage")
            assert decision["id"] not in [item["id"] for item in queue["items"]], "the abandoned decision is still queued"
            runs.settle(run, "failed")
            return {"status": "failed"}
        if name == "redirect-ready":
            before = set(work.glob("manager/runs/runs/*/runtime"))
            run = runs.start("profile_live")
            store = runs.new_store(before)
            control = runs.offered(run, lambda value: any(offer["operation"] == "redirect" and len(offer["targets"]) == 2
                                                          for offer in value["offers"]))
            window = next(offer for offer in control["offers"] if offer["operation"] == "redirect")
            assert window["targets"][0].endswith("@primary") and window["targets"][1].endswith("@spare"), ("dispatch targets", window["targets"])
            # The person question is pending beside the engine question, so the
            # harness answers it, and the dispatch window is the head of the view.
            control = runs.offered(run, lambda value: value["decisionHeadId"] is not None)
            question, tag, _ = observed("/v1/decisions/" + control["decisionHeadId"], "Decision")
            assert question["kind"] == "question", ("mixed-controls head", question["kind"])
            runs.client[2]("/v1/decisions/" + question["id"], {"operation": "answer", "occurrenceId": question["address"]["occurrenceId"],
                                                              "generation": question["generation"], "value": False}, tag)
            runs.offered(run, lambda value: value["decisionHeadId"] is None and any(
                offer["operation"] == "redirect" and offer["targets"] == window["targets"] for offer in value["offers"]))
            facts["redirect"] = {"run": run, "store": store, "window": window}
            return {"run": run, "occurrence": window["address"]["occurrenceId"], "targets": window["targets"]}
        assert name == "redirect-sent", ("an unknown handshake of the controls", name)
        run, store, window = facts["redirect"]["run"], facts["redirect"]["store"], facts["redirect"]["window"]
        occurrence, target = window["address"]["occurrenceId"], window["targets"][1]
        rows = runs.command_rows(["/v1/runs/" + run + "/control"])
        assert [(row[1], row[2]) for row in rows] == [("redirect", "effect-observed")] and native_command(rows[0][0]) == "redirectOccurrence", (
            "Emacs did not send exactly one redirect that reached its effect", rows)
        command = "/v1/commands/" + rows[0][0]
        receipt = runs.one_control(run, "redirect", command)
        acknowledgement = rows[0][3]
        assert receipt["effect"]["kind"] == "redirected" and acknowledgement is not None \
            and acknowledgement["state"] in ("accepted", "queued", "delivered") and acknowledgement["command"] == "redirect", (
            "redirect effect or acknowledgement", receipt["effect"], acknowledgement)
        runs.settle(run, "succeeded")
        completed = occurrence_of(runs.snapshot(run), occurrence)
        assert completed["state"] == "completed" and completed["source"] == "asked:" + target, (
            "redirect answer source", completed["state"], completed["source"])
        _, redirected = attempt_events(store, occurrence)
        assert [(event["controlId"], event["target"]) for event in redirected] == [(rows[0][0], target)], ("occurrence.redirected events", redirected)
        # The acknowledgement of /v1 names the command and no target. The
        # effect of the receipt names the runtime sequence of the one
        # occurrence.redirected event, which names the command and the
        # target, and the runtime acknowledgements of the command name it.
        envelopes = [json.loads(line) for line in (store / "events.ndjson").read_bytes().splitlines()]
        effected = [envelope for envelope in envelopes if envelope["sequence"] == receipt["effect"]["runtimeSequence"]]
        assert len(effected) == 1 and effected[0]["event"]["type"] == "occurrence.redirected" \
            and effected[0]["event"]["controlId"] == rows[0][0] and effected[0]["event"]["target"] == target, (
            "the runtime event of the redirect effect", effected)
        acks = [envelope["event"]["state"] for envelope in envelopes if envelope["event"]["type"] == "control.ack"
                and envelope["event"]["controlId"] == rows[0][0] and envelope["event"]["command"] == "redirectOccurrence"]
        assert acknowledgement["state"] in acks and "delivered" in acks, ("the runtime acknowledgements of the redirect", acks, acknowledgement)
        records = runs.run_records(run)
        (work / (mode + "-redirect-routes.json")).write_text(json.dumps(records, default=str))
        logged = runs.manager_control(records, command)
        assert logged["body"]["control"]["command"].get("target") == target, ("the run-log control of the redirect", logged["body"])
        questions = model_questions(records, occurrence)
        assert [record["to"] for record in questions] == [{"to": {"model": target}}] and logged["position"] < questions[0]["position"], (
            "redirected questions", logged["position"], [(record["position"], record["to"]) for record in questions])
        facts["redirect"].update(command=rows[0][0], acknowledgement=acknowledgement, control=logged, questions=questions,
                                 sequence=effected[0]["sequence"])
        return {"status": "succeeded"}

    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
    try:
        wait_ready(process)
        status, capabilities, _ = request("/v1/capabilities", harness)
        assert status == 200 and "control" in capabilities["scopes"], ("capabilities", status)
        runs = ControlHarness(harness, capabilities, mode)
        observed = runs.client[0]
        environment = {name: os.environ[name] for name in EMACS_ALLOWLIST if name in os.environ}
        command = [sys.executable, "-B", emacs_ui, "--service", str(tui_fixture.client_profile), str(report_path),
                   "--service-case", "controls", "--service-handshake", str(handshake), "--emacs", emacs_program,
                   "--source", os.path.join(emacs_directory, "wf.el"), "--artifacts", str(artifacts)]
        handled = []
        with harness_reads_only():
            script = subprocess.Popen(command, env=environment, stdin=subprocess.DEVNULL)
            try:
                deadline = time.monotonic() + 840
                while script.poll() is None:
                    assert time.monotonic() < deadline, "the Emacs service controls did not end in 840 seconds"
                    for path in sorted(handshake.glob("*.json")):
                        if path.stem not in handled:
                            handled.append(path.stem)
                            with harness_acts():
                                answered = act(path.stem)
                            answer = handshake / (path.stem + ".done.new")
                            answer.write_text(json.dumps(answered))
                            answer.rename(handshake / (path.stem + ".done"))
                    time.sleep(0.05)
            finally:
                if script.poll() is None:
                    script.kill()
                script.wait(timeout=25)
        report = json.loads(report_path.read_bytes()) if report_path.exists() else {"steps": []}
        assert script.returncode == 0, ("the Emacs service controls of " + emacs_ui + " failed", script.returncode, report["steps"], handled)
        assert report["version"] == EMACS_CONTROLS_REPORT_VERSION, (
            f"The {mode} mode requires report version {EMACS_CONTROLS_REPORT_VERSION}, and {emacs_ui} wrote version {report['version']}.")
        assert report["steps"] == ["1", "2", "3", "4", "5"], ("the steps of the controls", report["steps"])
        assert handled == ["failover-ready", "failover-sent", "abandon-ready", "abandon-sent", "redirect-ready", "redirect-sent"], (
            "the handshakes of the controls", handled)
        print(f"PASS {mode} 1: M-x wf-service selected the client profile", report["profile"], flush=True)

        # 2 and 3. The fail-over and the abandon.
        for step, name, label, status in (("2", "failover", "failover:1", "succeeded"), ("3", "abandon", "abandon", "failed")):
            shown, known = report[name], facts[name]
            assert shown["run"] == known["run"] and shown["decision"] == known["decision"]["id"] and shown["label"] == label \
                and label in [choice["label"] for choice in shown["choices"]] \
                and shown["typedText"] == "Control of run " + known["run"] + ": " + label, ("the " + name + " step", shown)
            assert "Terminal: " + status in shown["finalLines"], ("the last lines of the " + name + " view", shown["finalLines"])
            ended, _, _ = observed("/v1/runs/" + known["run"] + "/snapshot", "RunSnapshot")
            assert ended["runtime"]["status"] == status, ("the " + name + " run", ended["runtime"])
            spare = (" ; the run log holds question " + str(known["questions"][1]["position"]) + " to "
                     + known["questions"][1]["to"]["to"]["model"] + " with its answer") if name == "failover" else ""
            print(f"PASS {mode} {step}: in the view of run", known["run"], "the control prompt listed",
                  [choice["label"] for choice in shown["choices"]], ", and c,", label, "and RET sent the one choose-recovery command",
                  known["command"], "with the choice", name, "for decision", known["decision"]["id"] + "; it reached effect-observed"
                  + spare + ", the run ended", status, ", and the view showed Terminal:", status, flush=True)

        # 4. The redirect to the second listed target.
        shown, known = report["redirect"], facts["redirect"]
        target = known["window"]["targets"][1]
        listed = [choice for choice in shown["choices"] if choice["label"].startswith("redirect:")]
        assert shown["run"] == known["run"] and shown["target"] == target and len(listed) >= 2 \
            and shown["label"] == listed[1]["label"] and " to " + target + ", " in listed[1]["description"] \
            and shown["typedText"] == "Control of run " + known["run"] + ": " + shown["label"], ("the redirect step", shown)
        assert "Terminal: succeeded" in shown["finalLines"], ("the last lines of the redirect view", shown["finalLines"])
        print(f"PASS {mode} 4: in the view of run", known["run"], "the control prompt listed", [choice["label"] for choice in shown["choices"]],
              ", and c,", shown["label"], "and RET sent the one redirect command", known["command"], "of occurrence",
              known["window"]["address"]["occurrenceId"], "to the second listed target", target, "; it reached the effect redirected",
              "with the acknowledgement", known["acknowledgement"]["state"], "and the runtime event", known["sequence"],
              "occurrence.redirected of the command to", target + ", the run-log control", known["control"]["position"],
              "from the manager names", target, ", question", known["questions"][0]["position"], "went to", target,
              ", the run succeeded, and the view showed Terminal: succeeded", flush=True)

        # 5. The exit of Emacs.
        assert report["exitStatus"] == 0 and report["terminalAfter"] == report["terminalBefore"], (
            "the terminal attributes after Emacs", report["exitStatus"])
        print(f"PASS {mode} 5: M-x wf-local closed the session, and C-x C-c ended Emacs with exit status 0 and the terminal",
              "attributes of its start", flush=True)

        # 6. Only the listed controls, each once.
        expected = [("/v1/decisions/" + facts["failover"]["decision"]["id"], "choose-recovery", "failover"),
                    ("/v1/decisions/" + facts["abandon"]["decision"]["id"], "choose-recovery", "abandon"),
                    ("/v1/runs/" + known["run"] + "/control", "redirect", target)]
        sent = [(item["resource"], json.loads(item["body"])) for item in report["sent"]]
        assert [(resource, body["operation"], body.get("choice", body.get("target"))) for resource, body in sent] == expected, (
            "the commands of the session", sent)
        assert all(isinstance(item["ifMatch"], str) and item["ifMatch"].startswith('"') and item["ifMatch"] == item["readEtag"]
                   for item in report["sent"]), ("the If-Match of the commands", report["sent"])
        controls = read_coordination("SELECT id, operation, resource_uri, client_id, precondition FROM commands WHERE operation IN "
                                     "('cancel', 'steer', 'retry', 'choose-recovery', 'redirect') ORDER BY rowid")
        harness_clients = {client for (client,) in read_coordination("SELECT DISTINCT client_id FROM commands WHERE operation = 'create'")}
        assert [(row[2], row[1]) for row in controls] == [(resource, operation) for resource, operation, _ in expected] \
            and [row[0] for row in controls] == [facts["failover"]["command"], facts["abandon"]["command"], known["command"]] \
            and len({row[3] for row in controls}) == 1 and controls[0][3] not in harness_clients \
            and [row[4] for row in controls] == [item["ifMatch"] for item in report["sent"]], (
            "the control commands of the coordination database", controls, harness_clients)
        print(f"PASS {mode} 6: the session sent exactly the fail-over, the abandon and the redirect, each once with the entity tag",
              "of the read of its resource in the act of the control as If-Match, each a choice that the control prompt listed,",
              "and the control commands of the coordination database are exactly", [row[0] for row in controls],
              "from the client credential, with those preconditions; the harness sent no run control", flush=True)
    finally:
        if process.poll() is None:
            process.terminate()
        process.wait(timeout=25)
        (work / "server-0.exit").write_text(str(process.returncode) + "\n")

    # 7. No child remains, and the fixture secrets and homes are removed.
    removed = emacs_service_cleanup(artifacts)
    print(f"PASS {mode} 7: no Emacs, url or fixture process remains after the manager stopped, and the harness removed",
          removed, "credential, client profile and home paths", flush=True)
    print(f"PASS {mode}: Emacs sent a fail-over, an abandon and a redirect to the second listed target from the control prompt",
          "of the run view, each once, driven only by keys at 80x24, and the harness confirmed each from manager facts", flush=True)


class WitnessRecord:
    """The identity record of a cross-client witness mode. See step 14 of
    the cross-client mode. pids holds the process identifiers of each
    client, and steps holds the steps, each with its acting client, the
    process that acted, its runs and the commands that are new at its
    end."""

    def __init__(self):
        self.pids = {"tui": [], "emacs": [], "pi": []}
        self.steps = []
        self.receipts = {}

    def step_done(self, step, actor, runs_of_step):
        """Record the end of a step: the acting client, the process that
        acted, the runs and the commands that are new. The process of the
        harness is this process. An Emacs process is known only from its
        report, so write gives the steps of Emacs the first Emacs
        process."""
        known = {ident for entry in self.steps for ident in entry["commands"]}
        rows = read_coordination("SELECT id FROM commands ORDER BY rowid")
        process_id = os.getpid() if actor == "harness" else self.pids[actor][-1] if actor in ("tui", "pi") else None
        self.steps.append({"step": step, "actor": actor, "pid": process_id, "runs": list(runs_of_step),
                           "commands": [ident for (ident,) in rows if ident not in known]})

    def read_receipts(self, harness):
        """Read the receipt of every command of the coordination database
        while the manager runs, and keep the fields of the record."""
        rows = read_coordination("SELECT id, client_id, operation, resource_uri, request_id, run_id, preparation_id, decision_id, state "
                                 "FROM commands ORDER BY rowid")
        for ident, client, operation, resource, request_id, run_id, preparation_id, decision_id, state in rows:
            status, receipt, raw = request("/v1/commands/" + ident, harness)
            assert status == 200, ("the receipt of a command", ident, status)
            validate("CommandReceipt", receipt, raw)
            assert receipt["id"] == ident and receipt["operation"] == operation and receipt["resource"] == resource, (
                "the receipt differs from its command row", ident, receipt["operation"], receipt["resource"])
            self.receipts[ident] = {"id": ident, "client": client, "operation": operation, "resource": resource, "requestId": request_id,
                                    "runId": run_id, "preparationId": preparation_id, "decisionId": decision_id, "state": receipt["state"],
                                    "receipt": receipt["links"]["self"], "acceptedAt": receipt["acceptedAt"],
                                    "dispatchAttemptedAt": receipt["dispatchAttemptedAt"]}
        return self.receipts

    def write(self, name, mode, endpoint, negotiated, capabilities, manager, summary, downloaded, expected_actors, winners=None):
        """Write the record to work/NAME after the manager stopped. manager
        holds the records of the one manager log, and summary is the summary
        of the flow verb. Every command must be in exactly one step and have
        exactly one manager-log record in the one lifetime. The steps must
        have the expected actors, and each command must be from the
        credential of the actor of its step, or from the credential that
        winners names for it. A step of Emacs lists no command. The record
        must hold no bearer of the fixture and no run of 16 bytes of the
        downloaded result. Returns the path, the lifetime and the commands
        of each credential."""
        clients = tui_fixture.client_ids
        winners = winners or {}
        lifetimes = summary["joins"]["lifetimes"]
        assert len(lifetimes) == 1 and lifetimes[0]["shutdown"] is not None, ("the witness has other than one manager lifetime", lifetimes)
        notice = next(entry for entry in manager if entry["position"] == lifetimes[0]["lifetime"]["position"])
        assert notice["schema"] == "notice" and notice["body"]["notice"] == "lifetime", ("the lifetime notice of the manager log", notice["schema"])
        lifetime = {"processGeneration": notice["body"]["processGeneration"], "lifetimePosition": lifetimes[0]["lifetime"]["position"],
                    "shutdownPosition": lifetimes[0]["shutdown"]}
        for ident, entry in self.receipts.items():
            records_of = [item for item in manager if item["schema"] == "command" and item["about"].get("command") == ident]
            assert len(records_of) == 1 and lifetime["lifetimePosition"] < records_of[0]["position"] < lifetime["shutdownPosition"], (
                "a command has other than one manager-log record in the lifetime", ident, [item["position"] for item in records_of])
            entry.update(managerLogPosition=records_of[0]["position"], processGeneration=lifetime["processGeneration"])
        steps = self.steps
        listed = [ident for entry in steps for ident in entry["commands"]]
        assert sorted(listed) == sorted(self.receipts) and len(set(listed)) == len(listed), (
            "the steps do not list each command once", listed, sorted(self.receipts))
        names = {clients[name]: name for name in clients}
        for entry in steps:
            if entry["actor"] == "emacs":
                entry["pid"] = self.pids["emacs"][0]
            entry["commands"] = [self.receipts[ident] | {"credential": names[self.receipts[ident]["client"]]} for ident in entry["commands"]]
        identity = {"version": CROSS_RECORD_VERSION, "mode": mode, "endpoint": endpoint, "tls": negotiated,
                    "authorityEpoch": capabilities["authorityEpoch"], "lifetime": lifetime,
                    "credentials": {name: {"credentialId": tui_fixture.credential_ids[name], "client": clients[name]}
                                    for name in CrossClientFixture.CLIENTS + ("harness",)},
                    "processes": self.pids | {"harness": [os.getpid()]}, "steps": steps}
        encoded = json.dumps(identity, ensure_ascii=False, indent=2).encode()
        bearers = [path.read_bytes().strip() for path in [work / "credential"] + sorted(work.glob("credential-*"))]
        assert len(bearers) >= 4 and all(bearers), ("the bearers of the fixture", len(bearers))
        assert not [secret for secret in bearers if secret in encoded], "the identity record holds a bearer"
        window = 16
        fragments = [downloaded[at:at + window] for at in range(len(downloaded) - window + 1)]
        assert len(downloaded) >= window and not [fragment for fragment in fragments if fragment in encoded], (
            "the identity record holds bytes of the result")
        record_keys = {"id", "client", "credential", "operation", "resource", "requestId", "runId", "preparationId", "decisionId",
                       "state", "receipt", "acceptedAt", "dispatchAttemptedAt", "managerLogPosition", "processGeneration"}
        assert all(set(command) == record_keys for entry in steps for command in entry["commands"]), (
            "a command of the identity record has other fields", [sorted(set(command) ^ record_keys)
                                                                  for entry in steps for command in entry["commands"]])
        record_path = work / name
        record_path.write_bytes(encoded)
        actors = {entry["step"]: entry["actor"] for entry in steps}
        by_client = {name: [entry["id"] for step in steps for entry in step["commands"] if entry["credential"] == name] for name in clients}
        assert all(entry["pid"] is not None for entry in steps), ("a step names no process", [entry["step"] for entry in steps])
        assert actors == expected_actors, ("the steps name other actors", actors)
        senders = {command["id"]: (winners.get(command["id"], entry["actor"]), command["credential"])
                   for entry in steps for command in entry["commands"]}
        assert all(expected == found for expected, found in senders.values()), (
            "a command of a step is from another credential than the actor of the step",
            {ident: pair for ident, pair in senders.items() if pair[0] != pair[1]})
        assert not [command for entry in steps if entry["actor"] == "emacs" for command in entry["commands"]], (
            "a step of Emacs lists a command", [entry["step"] for entry in steps if entry["actor"] == "emacs" and entry["commands"]])
        return record_path, lifetime, by_client


def cross_client_checks():
    """The cross-client mode and its control: legs 1 and 2, the outputs of
    the leg 1 run and the identity record. See CROSS_CLIENT for the steps."""
    harness = tui_fixture.harness
    mode = sys.argv[5]
    endpoint = f"https://127.0.0.1:{port}/v1"
    artifacts = work / "cross-client-emacs"
    report_path = work / "cross-client-emacs-report.json"
    handshake = work / "cross-client-handshake"
    handshake.mkdir(mode=0o700)
    selectors = ("reviewDigest", "requestRevision", "profileRevision", "descriptorRevision", "processGeneration")
    clients = tui_fixture.client_ids
    tui_saved, emacs_saved = work / "cross-client-tui-result.bin", work / "cross-client-emacs-result.bin"
    # The process identifiers of each client, and the steps of the identity
    # record, each with the commands that are new at its end.
    record = WitnessRecord()
    pids, steps, step_done = record.pids, record.steps, record.step_done
    # The command of the step 8 race that took effect, and the credential
    # that sent it. Either the emacs or the tui credential can win.
    race_command = None

    def principal(name):
        """The manager-log principal of the credential name."""
        return {"principal": "credential", "credentialId": tui_fixture.credential_ids[name], "client": clients[name]}

    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
    pi = None
    try:
        wait_ready(process)
        status, capabilities, _ = request("/v1/capabilities", harness)
        assert status == 200, ("capabilities", status)
        status, catalogue, _ = request("/v1/workflows?profileId=profile_1", harness)
        assert status == 200, ("catalogue", status)
        index = next(i for i, item in enumerate(catalogue["items"]) if item["name"] == "mixed-controls")
        workflow = catalogue["items"][index]
        status, overview, _ = request("/v1/snapshot", harness)
        assert status == 200 and not overview["items"], ("the overview is not empty before the witness", status)
        cursor = overview["cursor"]
        observed = mixed_client(capabilities, harness)[0]
        # The three client profiles name the one manager endpoint and its
        # certificate authority, and a connection to it negotiates TLS 1.3.
        endpoints = {json.loads(path.read_text())["endpoint"] for path in tui_fixture.client_profiles.values()}
        assert endpoints == {endpoint}, ("the client profiles name another endpoint", endpoints)
        probe = ssl.create_default_context(cafile=str(cert))
        with socket.create_connection(("127.0.0.1", port), timeout=10) as raw, probe.wrap_socket(raw, server_hostname="127.0.0.1") as wrapped:
            negotiated = wrapped.version()
        assert negotiated == "TLSv1.3", ("the manager negotiated another TLS version", negotiated)
        # The pseudo-terminal of the client process that runs at the moment,
        # which the helpers below pump while the harness waits.
        session = None

        def until(path, schema, ready, timeout=45):
            """Read the resource until ready holds, and pump the
            pseudo-terminal of the running client between the reads."""
            deadline = time.monotonic() + timeout
            while True:
                value, tag, raw = observed(path, schema)
                if ready(value):
                    return value, tag, raw
                assert time.monotonic() < deadline and (session is None or session.process.poll() is None), (
                    "observation deadline", path, None if session is None else session.screen.text())
                if session is None:
                    time.sleep(0.1)
                else:
                    session.pump(0.1)

        def shown(needles, timeout, what):
            """Pump until the screen shows every needle, compared without
            white space so that wrapped rows join, and give the screen."""
            deadline = time.monotonic() + timeout
            while True:
                screen = session.screen.text()
                if all(squeeze(needle) in squeeze(screen) for needle in needles):
                    session.settle()
                    return session.screen.text()
                assert time.monotonic() < deadline and session.process.poll() is None, (what, needles, screen)
                session.pump(0.1)

        def approvals():
            return [receipt for _, receipt in command_receipts(cursor, harness) if receipt["operation"] == "approve"]

        def supplied(value):
            drafts = [item["request"] for item in value["items"] if item["kind"] == "request"]
            return len(drafts) == 1 and bool(drafts[0]["readiness"]["supplied"]) and not drafts[0]["readiness"]["missing"]

        with harness_reads_only():
            # 1. The TUI creates and enqueues the request by keys and quits at the review.
            with tui_fixture.session() as tui:
                session = tui
                pids["tui"].append(tui.process.pid)
                tui.wait_screen("Manager profiles")
                tui.wait_screen("profile_1")
                tui.send(b"\r")
                tui.wait_screen("Manager workflows")
                tui.wait_screen(catalogue["items"][0]["name"])
                tui.send(b"\x1b[B" * index + b"\r")
                tui.wait_screen("request validator current", timeout=20)
                tui.send(b"\x1b[200~" + CROSS_LITERAL_1.encode() + b"\x1b[201~")
                tui.send(b"\x04")
                snapshot, _, _ = until("/v1/snapshot", "OverviewSnapshot", supplied)
                submitted = next(item["request"] for item in snapshot["items"] if item["kind"] == "request")
                request_uri = submitted["links"]["self"]
                assert submitted["profileId"] == "profile_1" and submitted["workflowId"] == workflow["id"], (
                    "the TUI request names another profile or workflow", submitted["profileId"], submitted["workflowId"])
                assert submitted["readiness"]["supplied"] == [{"name": "input", "source": "literal", "value": CROSS_LITERAL_1}], (
                    "the TUI request did not supply exactly the typed literal", submitted["readiness"]["supplied"])
                tui.wait_screen("REQUEST REVIEW", timeout=20)
                tui.send(b"\r")
                shown(["Approve exact manager review"], 45, "the TUI showed no exact review")
                current, _, _ = until(request_uri, "Request", lambda value: value["phase"] == "review" and value["preparationId"] is not None)
                preparation_uri = "/v1/preparations/" + current["preparationId"]
                preparation, preparation_tag, _ = observed(preparation_uri, "Preparation")
                assert preparation["state"] == "live", ("the preparation of the TUI request", preparation["state"])
                (work / "cross-client-tui-review.screen.txt").write_text(tui.screen.text())
                tui.send(b"q")
                assert tui.wait_exit(20) == 0, "the TUI did not exit with status 0 at the review"
                tui.assert_restored()
            session = None
            still, _, _ = observed(request_uri, "Request")
            kept, kept_tag, _ = observed(preparation_uri, "Preparation")
            assert still["phase"] == "review" and still["runId"] is None and still["preparationId"] == preparation["id"], (
                "the TUI request left its review", still["phase"], still["runId"])
            assert kept["state"] == "live" and kept["revision"] == preparation["revision"] and kept_tag == preparation_tag, (
                "the preparation changed after the TUI quit", kept["state"])
            assert approvals() == [], "the manager holds an approve command before Pi"
            enqueues = [receipt for _, receipt in command_receipts(cursor, harness)
                        if receipt["operation"] == "enqueue" and receipt["resource"] == request_uri]
            assert len(enqueues) == 1 and enqueues[0]["state"] == "effect-observed", ("the enqueue command of the TUI", enqueues)
            print(f"PASS {mode} 1: the TUI with credential", tui_fixture.credential_ids["tui"], "created request", submitted["id"],
                  "of profile_1 and", workflow["name"], "by keys at 80x24 with exactly the literal", repr(CROSS_LITERAL_1) + ",",
                  "enqueued it, showed the exact review of preparation", preparation["id"], "and quit with q, without y, with exit",
                  "status 0 and the terminal restored; the request waits in review, the preparation is live, and no approve command exists",
                  flush=True)
            step_done("1", "tui", [])

            # 2. Pi opens the request of the TUI and approves its exact review.
            pi = PiHost("cross-client-pi", client_profile=tui_fixture.client_profiles["pi"])
            with pi:
                session = pi.session
                pids["pi"].append(session.process.pid)
                session.wait_screen("[Extensions]", timeout=60)
                shown(["Manager connected: " + endpoint], 30, "Pi did not notify the manager connection")
                session.send(("/wfm-review " + submitted["id"] + "\r").encode())
                displayed = [name + ": " + str(preparation[name]) for name in selectors]
                program = "Program SHA-256: " + preparation["review"]["programHash"]
                shown(["Review of request " + submitted["id"] + ", preparation " + preparation["id"], "a approve after confirmation",
                       program, "Workflow: " + workflow["id"], "Profile: profile_1"] + displayed, 45,
                      "Pi showed no exact review of the request of the TUI")
                pi.save_screen("review")
                session.send(b"a")
                shown(["Approve this exact review?", preparation["reviewDigest"], "→ Yes"], 15, "a opened no approval confirmation")
                pi.save_screen("approve")
                session.send(b"\r")
                associated, _, _ = until(request_uri, "Request", lambda value: value["runId"] is not None)
                run = associated["runId"]
                shown(["Execution: the manager started run " + run], 45, "Pi did not report the started run")
                consumed, _, _ = observed(preparation_uri, "Preparation")
                approved = approvals()
                assert consumed["state"] == "consumed" and all(consumed[name] == preparation[name] for name in selectors), (
                    "the consumed preparation differs from the review that Pi showed", consumed["state"])
                assert len(approved) == 1 and approved[0]["resource"] == preparation_uri and approved[0]["state"] not in ("refused", "unresolved"), (
                    "the approve command of Pi", approved)
                pi.quit()
            session = None
            print(f"PASS {mode} 2: Pi with credential", tui_fixture.credential_ids["pi"], "ran /wfm-review", submitted["id"],
                  "and showed the exact review of the request of the TUI with", ", ".join(selectors) + ",", repr(program), "and workflow",
                  workflow["id"] + "; a and Yes sent the one approve command", approved[0]["id"], "of preparation", preparation["id"] + ",",
                  "the preparation is consumed, request", submitted["id"], "names run", run + ", and /quit ended Pi with status 0", flush=True)
            step_done("2", "pi", [run])

            # 3. Emacs observes the run at its question head, opens the answer
            # editor and types false. Steps 4 to 6 run inside its handshake
            # open-answer, while the editor stays open.
            def pending_question(value):
                return any(item["state"] == "pending" and item["kind"] == "question" for item in value["items"])

            queue, _, _ = until("/v1/decisions?runId=" + run, "DecisionPage", pending_question, 120)
            question = next(item for item in queue["items"] if item["state"] == "pending" and item["kind"] == "question")
            control, _, _ = until("/v1/runs/" + run + "/control", "RunControl", lambda value: value["decisionHeadId"] is not None)
            assert control["decisionHeadId"] == question["id"], ("the head of the run is not its person question",
                                                                 control["decisionHeadId"], question["id"])
            question_decision, _, _ = observed("/v1/decisions/" + question["id"], "Decision")
            occurrence = question_decision["address"]["occurrenceId"]
            first_store = ControlHarness.new_store(set())

            def answer_rows(decision):
                """The identifier, client and state of each answer command of the decision."""
                return read_coordination("SELECT id, client_id, state FROM commands WHERE operation = 'answer' AND resource_uri = ? "
                                         "ORDER BY rowid", ("/v1/decisions/" + decision,))

            def recorded_answers(store, occurrence):
                """The answers that answers.json of the run store records for the occurrence."""
                path = store / "answers.json"
                entries = json.loads(path.read_bytes())["answers"] if path.exists() else []
                return [entry["answer"] for entry in entries if entry["occurrenceId"] == occurrence]

            pi_answer = None

            def open_answer(facts):
                """Steps 3 to 6, while the answer editor of Emacs is open."""
                nonlocal session, pi_answer
                question_lines = [line for line in facts["viewLines"] if question["id"] + ": pending question" in line]
                assert facts["run"] == run and facts["question"] == question["id"] and facts["head"] == question["id"] \
                    and facts["kind"] == "question", ("the head of the Emacs view", facts["head"], facts["kind"])
                assert len(question_lines) == 1 and facts["viewLines"][0].startswith("Service run " + run), (
                    "the Emacs view did not show the pending question of the run", facts["viewLines"])
                assert facts["editorBuffer"].startswith("*wf answer JSON") and facts["editorText"] == CROSS_EMACS_ANSWER, (
                    "the answer editor of Emacs does not hold the typed answer", facts["editorBuffer"], facts["editorText"])
                assert facts["sent"] == [], ("the Emacs session sent a command before the race", facts["sent"])
                print(f"PASS {mode} 3: Emacs with credential", tui_fixture.credential_ids["emacs"], "opened the view of run", run,
                      "with M-x wf-runs at 80x24 and showed its pending question as the head:", repr(question_lines[0].strip()) + ";",
                      "a opened the answer editor", facts["editorBuffer"], "with the typed text", repr(facts["editorText"]) + ",",
                      "and the session sent no command", flush=True)
                step_done("3", "emacs", [run])

                # 4. The clients of the commands.
                rows = read_coordination("SELECT id, operation, client_id, resource_uri FROM commands ORDER BY rowid")
                by_operation = {operation: [row for row in rows if row[1] == operation] for operation in ("create", "enqueue", "approve")}
                assert all(len(found) == 1 for found in by_operation.values()), ("the create, enqueue and approve commands", rows)
                create, enqueue, approve = by_operation["create"][0], by_operation["enqueue"][0], by_operation["approve"][0]
                assert create[2] == clients["tui"] and enqueue[2] == clients["tui"] and enqueue[3] == request_uri, (
                    "the create and enqueue commands do not name the tui client", create, enqueue, clients)
                assert approve[2] == clients["pi"] and approve[3] == preparation_uri and "/v1/commands/" + approve[0] == approved[0]["links"]["self"], (
                    "the approve command does not name the pi client", approve, clients)
                assert all(row[2] == clients["tui"] for row in rows if row[0] != approve[0]), (
                    "a command other than the approval names another client than the tui client", rows, clients)
                print(f"PASS {mode} 4: the commands table holds", str([row[1] for row in rows]) + ";", "the create", create[0], "and the enqueue",
                      enqueue[0], "name client", clients["tui"], "of the tui credential, the one approve", approve[0], "names client",
                      clients["pi"], "of the pi credential, and no command names client", clients["emacs"], "of the emacs credential or",
                      clients["harness"], "of the harness", flush=True)
                commands.update(enqueue=enqueue[0], approve=approve[0])
                step_done("4", "harness", [])

                # 5. The run still waits at its question.
                snapshot, _, _ = observed("/v1/runs/" + run + "/snapshot", "RunSnapshot")
                run_view, _, _ = observed("/v1/runs/" + run, "Run")
                decision, _, _ = observed("/v1/decisions/" + question["id"], "Decision")
                assert snapshot["runtime"] is not None and snapshot["runtime"]["status"] == "running" and run_view["supervision"] == "owned" \
                    and decision["state"] == "pending", ("the run left its question", snapshot["runtime"], run_view["supervision"], decision["state"])
                print(f"PASS {mode} 5: run", run, "still runs under owned supervision at its pending question", question["id"],
                      "while the answer editor of Emacs is open", flush=True)
                step_done("5", "harness", [run])

                # 6. Pi answers the same head with false, and the answer takes effect.
                pi_answer = PiHost("cross-client-pi-answer", client_profile=tui_fixture.client_profiles["pi"])
                with pi_answer:
                    session = pi_answer.session
                    pids["pi"].append(session.process.pid)
                    session.wait_screen("[Extensions]", timeout=60)
                    shown(["Manager connected: " + endpoint], 30, "Pi did not notify the manager connection")
                    session.send(("/wfm-answer " + run + "\r").encode())
                    shown(["Answer of decision " + question["id"]], 30, "/wfm-answer opened no answer editor")
                    session.send(CROSS_PI_ANSWER.encode())
                    shown([CROSS_PI_ANSWER], 15, "Pi does not show the typed answer")
                    pi_answer.save_screen("answer")
                    session.send(b"\r")
                    shown(["reached decision " + question["id"]], 45, "Pi did not report the answer")
                    deadline = time.monotonic() + 45
                    while not ((found := answer_rows(question["id"])) and found[0][2] == "effect-observed"):
                        assert time.monotonic() < deadline and len(found) <= 1, ("the answer of Pi did not reach its effect", found)
                        session.pump(0.1)
                    assert len(found) == 1 and found[0][1] == clients["pi"], ("the answer command of Pi", found, clients)
                    pi_answer.save_screen("answered")
                    pi_answer.quit()
                session = None
                commands["answer"] = found[0][0]
                print(f"PASS {mode} 6: Pi with credential", tui_fixture.credential_ids["pi"], "ran /wfm-answer", run,
                      "while the answer editor of Emacs was open and sent the typed answer", CROSS_PI_ANSWER, "to question", question["id"]
                      + "; its answer command", found[0][0], "of client", clients["pi"], "reached effect-observed, and /quit ended Pi with status 0",
                      flush=True)
                step_done("6", "pi", [run])
                return {}

            commands = {}
            environment = {name: os.environ[name] for name in EMACS_ALLOWLIST if name in os.environ}
            command = [sys.executable, "-B", emacs_ui, "--service", str(tui_fixture.client_profiles["emacs"]), str(report_path),
                       "--service-case", "witness", "--service-handshake", str(handshake), "--emacs", emacs_program,
                       "--source", os.path.join(emacs_directory, "wf.el"), "--artifacts", str(artifacts)]
            order = ["witness-ready", "open-answer", "save-result"]
            handled = []
            script = subprocess.Popen(command, env=environment, stdin=subprocess.DEVNULL)

            def handshake_facts(name, timeout):
                """Wait until the Emacs witness asks for the handshake name,
                which must be the next of order, and give its facts."""
                assert name == order[len(handled)], ("a handshake out of order", name, handled)
                path = handshake / (name + ".json")
                deadline = time.monotonic() + timeout
                while not path.exists():
                    early = [item.stem for item in handshake.glob("*.json") if item.stem not in handled]
                    assert not early, ("an unknown or early handshake of the witness", early, name, handled)
                    assert script.poll() is None, ("the Emacs witness ended before the handshake", name, script.returncode)
                    assert time.monotonic() < deadline, ("the Emacs witness did not ask for the handshake", name)
                    time.sleep(0.05)
                handled.append(name)
                return json.loads(path.read_text())

            def handshake_answer(name, reply):
                """Answer the handshake name with the JSON reply, which appears complete by a rename."""
                staged = handshake / (name + ".done.new")
                staged.write_text(json.dumps(reply))
                staged.rename(handshake / (name + ".done"))

            try:
                handshake_facts("witness-ready", 240)
                handshake_answer("witness-ready", {"run": run, "question": question["id"]})
                handshake_answer("open-answer", open_answer(handshake_facts("open-answer", 240)))
                facts = handshake_facts("save-result", 240)
                assert facts["run"] == run, ("the save-result handshake names another run", facts["run"])

                # 7. The later send of Emacs is refused, and the answer of Pi is the only one.
                sent = facts["sent"]
                assert len(sent) == 1 and sent[0]["resource"].endswith("/v1/decisions/" + question["id"]) and sent[0]["ifMatch"], (
                    "the Emacs session sent other than one answer of the question", sent)
                body = json.loads(sent[0]["body"])
                assert body["operation"] == "answer" and body["value"] is False, ("the answer that Emacs sent", body)
                assert facts["sentAfterRefusal"] == sent and facts["sentQuiet"] == sent, (
                    "the Emacs session sent again after the refusal", facts["sentAfterRefusal"], facts["sentQuiet"])
                refusal = facts["refusal"]
                assert "412 stale-revision" in refusal and question["id"] in refusal and "Nothing was sent again" in refusal, (
                    "the Emacs session did not show the refusal of the manager", refusal)
                assert refusal[:60] in facts["messagesAfter"] and facts["editorKept"] is True, (
                    "the refusal is not in *Messages*, or the editor lost its text", facts["editorKept"])
                found = answer_rows(question["id"])
                assert found == [(commands["answer"], clients["pi"], "effect-observed")], (
                    "the coordination database holds other than the one answer of Pi for the question", found)
                emacs_rows = read_coordination("SELECT id, operation FROM commands WHERE client_id = ?", (clients["emacs"],))
                assert emacs_rows == [], ("the refused answer of Emacs left a command", emacs_rows)
                stored = recorded_answers(first_store, occurrence)
                assert stored == [False], (CROSS_FALSE, stored)
                print(f"PASS {mode} 7: after the answer of Pi took effect, C-c C-c sent the open editor of Emacs once, and Emacs showed",
                      "the refusal of the manager:", repr(refusal[:120]) + ";", "the session sent nothing more and kept its draft, the",
                      "coordination database holds only the answer", commands["answer"], "of client", clients["pi"], "for decision",
                      question["id"], "in state effect-observed and no command of the emacs credential, and answers.json of",
                      first_store.parent.name, "records JSON false", flush=True)
                step_done("7", "emacs", [run])

                # 8. A second run of profile_2 is admitted beside the first, and
                # two concurrent answers to its question head take effect once.
                with harness_acts():
                    runs = ControlHarness(harness, capabilities, mode)
                    before = set(work.glob("manager/runs/runs/*/runtime"))
                    second = runs.start("profile_2")
                    second_store = runs.new_store(before)
                    admitted = []
                    for identifier in (run, second):
                        run_view, _, _ = observed("/v1/runs/" + identifier, "Run")
                        owner, _, _ = observed("/v1/requests/" + run_view["requestId"], "Request")
                        snapshot, _, _ = observed("/v1/runs/" + identifier + "/snapshot", "RunSnapshot")
                        assert owner["admission"]["state"] == "reserved" and run_view["supervision"] == "owned" \
                            and snapshot["runtime"] is not None and snapshot["runtime"]["status"] == "running", (
                            "the two runs do not hold their reservations at once", identifier, owner["admission"], run_view["supervision"])
                        admitted.append((identifier, owner["profileId"]))
                    control, _, _ = until("/v1/runs/" + second + "/control", "RunControl", lambda value: value["decisionHeadId"] is not None)
                    head = control["decisionHeadId"]
                    decision, decision_tag, _ = observed("/v1/decisions/" + head, "Decision")
                    assert decision["kind"] == "question" and decision["state"] == "pending" and decision["position"] == 0, (
                        "the head of the second run is not its pending question", decision["kind"], decision["state"])
                    race = {"operation": "answer", "occurrenceId": decision["address"]["occurrenceId"], "generation": decision["generation"],
                            "value": False}
                    payload = json.dumps(race, separators=(",", ":")).encode()
                    barrier = threading.Barrier(2)
                    outcomes = {}

                    def race_answer(name):
                        credential = {"Authorization": "Bearer " + (work / ("credential-" + name)).read_bytes().decode("ascii")}
                        headers = credential | {"Content-Type": "application/json", "If-Match": decision_tag,
                                                "Idempotency-Key": capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)}
                        barrier.wait(timeout=10)
                        status, value, raw, _ = exchange("/v1/decisions/" + head, headers, method="POST", payload=payload)
                        validate("Problem" if status >= 400 else "CommandReceipt", value, raw)
                        outcomes[name] = (status, value)

                    threads = [threading.Thread(target=race_answer, args=(name,)) for name in ("emacs", "tui")]
                    for thread in threads:
                        thread.start()
                    for thread in threads:
                        thread.join(timeout=30)
                    assert len(outcomes) == 2, ("the concurrent answers did not return", sorted(outcomes))
                    accepted = [(name, value) for name, (status, value) in outcomes.items() if status == 202]
                    refused = [(name, status, value) for name, (status, value) in outcomes.items() if status != 202]
                    assert len(accepted) == 1 and len(refused) == 1, ("the concurrent answers", {name: status for name, (status, _) in outcomes.items()})
                    winner, receipt = accepted[0]
                    race_command = {"id": receipt["id"], "credential": winner}
                    loser, refused_status, problem = refused[0]
                    assert refused_status == 412 and problem["code"] == "stale-revision", ("the refusal of the later answer", refused_status, problem["code"])
                    effected, _, raw = runs.client[1](receipt["links"]["self"], "CommandReceipt",
                        lambda value: value["state"] in ("effect-observed", "refused", "unresolved"))
                    (work / "cross-client-race-command.json").write_bytes(raw)
                    assert effected["state"] == "effect-observed" and effected["effect"]["kind"] == "answer-accepted", (
                        "the winning answer", effected["state"], effected["effect"])
                    found = answer_rows(head)
                    assert found == [(receipt["id"], clients[winner], "effect-observed")], (
                        "the coordination database holds other than the one winning answer", found)
                    stored = recorded_answers(second_store, decision["address"]["occurrenceId"])
                    assert stored == [False], ("answers.json of the second run does not record one JSON false", stored)
                    print(f"PASS {mode} 8: run", second, "of profile_2, which the harness created, enqueued and approved, was admitted while run",
                          run, "held its reservation (" + ", ".join(f"{identifier} of {profile} reserved" for identifier, profile in admitted) + ");",
                          "of two concurrent answers to its head", head, "at generation", decision["generation"], "the", winner,
                          "credential's command", receipt["id"], "reached effect-observed with answer-accepted, the", loser,
                          "credential received", refused_status, problem["code"] + ", the coordination database holds only that answer,",
                          "and answers.json of", second_store.parent.name, "records one JSON false", flush=True)
                    step_done("8", "harness", [run, second])

                    # 9. The harness settles the second run, which releases its reservation.
                    _, answered, recovered = drive_mixed(second, runs.client, overview=False)
                    assert (answered, recovered) == (0, 1), ("the harness settled the second run with other controls", answered, recovered)
                    runs.ended(second, "succeeded")
                    second_request = observed("/v1/runs/" + second, "Run")[0]["requestId"]
                    released, _, _ = runs.client[1]("/v1/requests/" + second_request, "Request",
                                                    lambda value: value["admission"]["state"] == "released")
                print(f"PASS {mode} 9: the harness sent the offered retry of run", second, "with its own credential, the run succeeded,",
                      "and request", second_request, "released its reservation", flush=True)
                step_done("9", "harness", [second])

                # 10. The TUI sends the offered retry of the first run by key and saves its verified result with s.
                recovery = runs.offered(run, lambda value: value["decisionHeadId"] not in (None, question["id"]))["decisionHeadId"]
                recovery_decision, _, _ = observed("/v1/decisions/" + recovery, "Decision")
                assert recovery_decision["kind"] == "recovery" and recovery_decision["state"] == "pending", (
                    "the next head of the first run is not its recovery", recovery_decision["kind"], recovery_decision["state"])
                control_uri = "/v1/runs/" + run + "/control"
                with tui_fixture.session() as tui:
                    session = tui
                    pids["tui"].append(tui.process.pid)
                    tui.wait_screen("Manager profiles")
                    tui.wait_screen("profile_1")
                    tui.send(b"\r")
                    tui.wait_screen("Manager workflows")
                    tui.send(b"O")
                    tui.wait_screen("Manager overview")
                    focus_row(tui, "run Running", "Run:" + run, 30)
                    tui.send(b"\r")
                    shown(["Recovery required", "r RETRY"], 30, "the TUI did not show the recovery of the first run")
                    (work / "cross-client-tui-recovery.screen.txt").write_text(tui.screen.text())
                    mutation_key(tui, b"r", "Terminal: succeeded", 120)
                    monitor = shown(["Terminal: succeeded", "Result SHA-256: "], 45, "the TUI showed no verified result")
                    (work / "cross-client-tui-succeeded.screen.txt").write_text(monitor)
                    tui.send(b"s")
                    tui.wait_screen("Save verified result", timeout=15)
                    tui.send(str(tui_saved).encode())
                    tui.send(b"\x04")
                    tui.wait_screen("Saved the verified", timeout=15)
                    (work / "cross-client-tui-saved.screen.txt").write_text(tui.screen.text())
                    tui.wait_screen("s SAVE RESULT", timeout=15)
                    tui.send(b"\x1b")
                    tui.wait_screen("Manager overview", timeout=10)
                    tui.send(b"q")
                    assert tui.wait_exit(20) == 0, "the TUI did not exit with status 0 after the retry"
                    tui.assert_restored()
                session = None
                retries = read_coordination("SELECT id, client_id, state FROM commands WHERE operation = 'retry' AND resource_uri = ?", (control_uri,))
                assert len(retries) == 1 and retries[0][1:] == (clients["tui"], "effect-observed"), (
                    "the TUI did not send the one retry of the first run", retries, clients)
                commands["retry"] = retries[0][0]
                runs.ended(run, "succeeded")
                artifact = verified_download(run, runs.client, harness)
                downloaded = (work / "verified-result.json").read_bytes()
                size = int(artifact["bytes"])
                for row in ("Result: verified " + str(size) + " bytes", "Result SHA-256: " + artifact["sha256"]):
                    assert squeeze(row) in squeeze(monitor), ("the live monitor of the TUI does not show the verified result", row)

                def saved_exactly(path, who):
                    """Require that path is a regular file with mode 0600 that
                    holds exactly the bytes of the harness download."""
                    status = os.lstat(path)
                    assert stat.S_ISREG(status.st_mode) and stat.S_IMODE(status.st_mode) == 0o600, (
                        "the result that " + who + " saved is not a regular file with mode 0600", oct(status.st_mode))
                    saved = path.read_bytes()
                    assert saved == downloaded and len(saved) == size and hashlib.sha256(saved).hexdigest() == artifact["sha256"], (
                        "the result that " + who + " saved differs from the harness download", len(saved))

                saved_exactly(tui_saved, "the TUI")
                print(f"PASS {mode} 10: a new TUI with credential", tui_fixture.credential_ids["tui"], "opened run", run, "from the Manager",
                      "overview at its recovery decision", recovery, "and r sent the one retry", retries[0][0], "of client", clients["tui"] + ";",
                      "it reached effect-observed, the run succeeded, the monitor showed the verified", size, "bytes and SHA-256",
                      artifact["sha256"], "of the harness download, s saved them to", tui_saved, "with mode 0600 and the exact bytes,",
                      "and q ended the TUI with status 0 and the terminal restored", flush=True)
                step_done("10", "tui", [run])

                # 11. Emacs saves the verified result with r in the view of the run.
                handshake_answer("save-result", {"path": str(emacs_saved)})
                deadline = time.monotonic() + 240
                while script.poll() is None:
                    assert time.monotonic() < deadline, "the Emacs witness did not end in 240 seconds after save-result"
                    time.sleep(0.05)
            finally:
                if script.poll() is None:
                    script.kill()
                script.wait(timeout=25)
            report = json.loads(report_path.read_bytes()) if report_path.exists() else {"steps": [], "version": None}
            assert script.returncode == 0, ("the Emacs witness of " + emacs_ui + " failed", script.returncode, report["steps"], handled)
            assert report["version"] == CROSS_EMACS_REPORT_VERSION, (
                f"The {mode} mode requires report version {CROSS_EMACS_REPORT_VERSION}, and {emacs_ui} wrote version {report['version']}.")
            assert report["steps"] == ["1", "2", "3", "4", "5", "6"] and handled == order, ("the steps of the witness", report["steps"], handled)
            assert report["profile"] == str(tui_fixture.client_profiles["emacs"]) and report["run"] == run \
                and report["question"] == question["id"], ("the run of the Emacs view", report["run"], report["question"])
            assert report["sent"] == facts["sent"], ("the Emacs session sent a command after save-result", report["sent"])
            assert report["exitStatus"] == 0 and report["terminalAfter"] == report["terminalBefore"], (
                "the terminal attributes after Emacs", report["exitStatus"])
            pids["emacs"].append(report["emacsPid"])
            assert report["savedPath"] == str(emacs_saved) and "Terminal: succeeded" in report["resultLines"] \
                and "Result SHA-256: " + artifact["sha256"] in report["resultLines"], (
                "the view of Emacs does not show the verified result of the harness download", report["resultLines"])
            assert str(size) + " bytes" in report["savedMessage"] and artifact["sha256"] in report["savedMessage"], (
                "Emacs did not report the size and the SHA-256 of the saved result", report["savedMessage"])
            saved_exactly(emacs_saved, "Emacs")
            print(f"PASS {mode} 11: Emacs with credential", tui_fixture.credential_ids["emacs"], "showed terminal success and",
                  repr("Result SHA-256: " + artifact["sha256"]), "in the view of run", run + ", r saved the verified result to", emacs_saved,
                  "with mode 0600 and the exact", size, "bytes of the harness download, and C-x C-c ended Emacs with status 0 and the",
                  "terminal attributes of its start", flush=True)
            step_done("11", "emacs", [run])

            # 12. Pi shows the verified result with /wfm-result.
            pi_result = PiHost("cross-client-pi-result", client_profile=tui_fixture.client_profiles["pi"])
            with pi_result:
                session = pi_result.session
                pids["pi"].append(session.process.pid)
                session.wait_screen("[Extensions]", timeout=60)
                shown(["Manager connected: " + endpoint], 30, "Pi did not notify the manager connection")
                session.send(("/wfm-result " + run + "\r").encode())
                shown(["Path of a new file for the verified " + str(size) + " bytes of run " + run], 150,
                      "/wfm-result opened no path dialog for the verified result")
                session.send(b"\r")
                shown_result = "Run " + run + ": verified " + str(size) + " bytes, SHA-256 " + artifact["sha256"] + "."
                shown([shown_result, "No path was named, so nothing was saved."], 30, "Pi did not show the verified result")
                pi_result.save_screen("result")
                pi_result.quit()
            session = None
            print(f"PASS {mode} 12: Pi with credential", tui_fixture.credential_ids["pi"], "ran /wfm-result", run, "and showed",
                  repr(shown_result), "with the size and the SHA-256 of the harness download, and /quit ended Pi with status 0", flush=True)
            step_done("12", "pi", [run])

            # The receipt of every command, for the identity record.
            receipts = record.read_receipts(harness)
    finally:
        if process.poll() is None:
            process.terminate()
        process.wait(timeout=25)
        (work / "server-0.exit").write_text(str(process.returncode) + "\n")

    # 13. The manager log names the senders, and the start relay follows the approval.
    flow_dir = work / "manager" / "flow"
    logs = sorted(flow_dir.glob("*.ndjson"))
    stores = sorted(work.glob("manager/runs/runs/*/runtime"))
    assert len(logs) == 1 and stores == sorted([first_store, second_store]), (
        "the witness has other than one manager log and two run stores", logs, stores)
    manager_path, store = str(logs[0]), first_store
    status, records, summary = read_flow("cross-client-flow", [flow_dir] + stores)
    assert status == 0 and summary["verified"] and not summary["problems"], ("the flow verb did not verify the witness logs", status, summary["problems"])
    manager = [record for record in records if record["log"] == manager_path]
    at = lambda log, position: {"log": log, "position": position}
    logged = {name: [record for record in manager if record["schema"] == "command" and record["about"].get("command") == commands[name]]
              for name in ("enqueue", "approve", "answer", "retry")}
    assert all(len(found) == 1 for found in logged.values()), ("the manager log has other than one record of each command", logged)
    senders = {"enqueue": "tui", "approve": "pi", "answer": "pi", "retry": "tui"}
    for name, sender in senders.items():
        assert logged[name][0]["from"] == principal(sender) and logged[name][0]["body"]["operation"] == name, (
            "the sender of a command in the manager log", name, logged[name][0]["from"], principal(sender))
    assert principal("tui") != principal("pi"), "the two senders are one principal"
    approval = logged["approve"][0]
    starts = [record for record in manager if record["schema"] == "relay" and record["body"]["kind"] == "start"
              and record["about"].get("command") == commands["approve"]]
    assert len(starts) == 1 and starts[0]["position"] > approval["position"] and starts[0]["body"]["nativeRun"] == store.parent.name, (
        "the start relay of the approval", [record["about"] for record in starts])
    start = starts[0]
    delivered = [item["delivered"] for item in summary["joins"]["relays"] if item["relay"] == at(manager_path, start["position"])]
    assert delivered == [at(str(store), 0)], ("the start relay is not joined to the run-log start", delivered)
    consent = [item for item in summary["consent"] if item["command"] == approval["position"]]
    assert len(consent) == 1 and consent[0]["verified"] and not consent[0]["problems"] \
        and consent[0]["relay"] == at(manager_path, start["position"]), ("the consent of the start relay", consent)
    print(f"PASS {mode} 13: the manager log holds the enqueue", commands["enqueue"], "and the retry", commands["retry"], "from",
          principal("tui"), "and the approve", commands["approve"], "and the answer", commands["answer"], "from", principal("pi"),
          "; the start relay at position", start["position"], "follows the approval at position", approval["position"], "and delivers",
          "run-log start 0 of", store.parent.name + ", and its consent verifies", flush=True)

    # 14. The identity record of the witness.
    assert race_command is not None and race_command["id"] in [ident for entry in steps if entry["step"] == "8" for ident in entry["commands"]], (
        "step 8 does not list the command of the answer race", race_command)
    expected_actors = {"1": "tui", "2": "pi", "3": "emacs", "4": "harness", "5": "harness", "6": "pi", "7": "emacs",
                       "8": "harness", "9": "harness", "10": "tui", "11": "emacs", "12": "pi"}
    record_path, lifetime, by_client = record.write(
        "cross-client-witness.json", mode, endpoint, negotiated, capabilities, manager, summary, downloaded, expected_actors,
        {race_command["id"]: race_command["credential"]})
    receipts = record.receipts
    assert preparation["processGeneration"] == lifetime["processGeneration"], (
        "the preparation names another process generation than the lifetime notice", preparation["processGeneration"])
    print(f"PASS {mode} 14: wrote", record_path, "with", len(steps), "steps and", len(receipts), "commands in manager lifetime",
          lifetime["processGeneration"], "(" + ", ".join(f"{name}: {len(found)}" for name, found in by_client.items()) + " commands,",
          "with the race command", race_command["id"], "from the", race_command["credential"], "credential);",
          "each command is in one step with its client, its correlated request, run, preparation and decision, its manager-log",
          "position and its receipt timestamps, and the record holds no bearer and no result bytes", flush=True)

    # 15. No child remains, and the fixture secrets and homes are removed.
    hosts = (pi, pi_answer, pi_result)
    removed = emacs_service_cleanup(artifacts, [tui_fixture.client_profiles[name] for name in CrossClientFixture.CLIENTS]
                                    + [host.home for host in hosts] + [host.agent for host in hosts] + [host.state for host in hosts])
    print(f"PASS {mode} 15: all clients quit, the manager stopped, no TUI, Emacs, Pi or fixture process remains, and the harness",
          "removed", removed, "credential, client profile and home paths", flush=True)
    elapsed = time.monotonic() - mode_started
    assert elapsed <= WITNESS_SECONDS, ("the witness took longer than its budget", round(elapsed), WITNESS_SECONDS)
    credentials = ", ".join(f"{name} {tui_fixture.credential_ids[name]} of client {clients[name]}"
                            for name in CrossClientFixture.CLIENTS + ("harness",))
    print(f"PASS {mode}: the TUI created, Pi approved and Emacs observed one run, Pi won the answer race against the open editor",
          "of Emacs, two concurrent HTTP answers took effect once, the TUI sent the retry to terminal success, and the TUI and Emacs",
          "saved and Pi showed its verified result with the SHA-256 of the harness download; the client processes were the TUI",
          "(pids " + ", ".join(map(str, pids["tui"])) + "), Emacs (pid " + ", ".join(map(str, pids["emacs"])) + ") and Pi (pids",
          ", ".join(map(str, pids["pi"])) + "), and the four credentials were", credentials + ", over one manager at", endpoint,
          f"that negotiates {negotiated}, in {elapsed:.0f} seconds", flush=True)


def cross_client_lifecycle_checks():
    """The cross-client-lifecycle mode: disconnection and reconnection,
    rotation and revocation, an ordinary restart with the lost run and the
    admission of a new request of its resource key, and a manager loss with
    the release of the quarantine. See CROSS_CLIENT_LIFECYCLE for the
    steps."""
    harness = tui_fixture.harness
    mode = sys.argv[5]
    endpoint = f"https://127.0.0.1:{port}/v1"
    artifacts = work / "cross-lifecycle-emacs"
    report_path = work / "cross-lifecycle-emacs-report.json"
    handshake = work / "cross-lifecycle-handshake"
    handshake.mkdir(mode=0o700)
    selectors = ("reviewDigest", "requestRevision", "profileRevision", "descriptorRevision", "processGeneration")
    clients, credentials = tui_fixture.client_ids, tui_fixture.credential_ids
    flow_dir = work / "manager" / "flow"
    pids = {"tui": [], "emacs": [], "pi": []}
    hosts = []
    # The pseudo-terminals of the TUI and Pi processes that run at the
    # moment. Node writes to a terminal synchronously, so every helper that
    # waits reads all of them.
    sessions = []

    def serve(index):
        """Start one foreground manager lifetime on the same root and
        configuration and wait for HTTPS readiness."""
        with (work / f"server-{index}.stdout").open("wb") as output, (work / f"server-{index}.stderr").open("wb") as errors:
            process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                        "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        wait_ready(process)
        return process

    def pump_all(wait=0.1):
        assert all(session.process.poll() is None for session in sessions), (
            "a client process ended while the harness waited", [session.process.poll() for session in sessions])
        if not sessions:
            time.sleep(wait)
        for session in sessions:
            session.pump(wait / len(sessions))

    def until(path, schema, ready, timeout=45):
        """Read the resource until ready holds, and read the pseudo-terminals between the reads."""
        deadline = time.monotonic() + timeout
        while True:
            value, tag, raw = observed(path, schema)
            if ready(value):
                return value, tag, raw
            assert time.monotonic() < deadline, ("observation deadline", path, [session.screen.text() for session in sessions])
            pump_all()

    def shown(session, needles, timeout, what):
        """Pump until the screen of the session shows every needle, compared
        without white space so that wrapped rows join, and give the screen."""
        deadline = time.monotonic() + timeout
        while True:
            screen = session.screen.text()
            if all(squeeze(needle) in squeeze(screen) for needle in needles):
                session.settle()
                return session.screen.text()
            assert time.monotonic() < deadline, (what, needles, screen)
            pump_all()

    def opened(session):
        sessions.append(session)
        return session

    def closed(session):
        sessions.remove(session)

    def pi_host(name, profile):
        host = PiHost(name, client_profile=profile)
        hosts.append(host)
        pids["pi"].append(host.session.process.pid)
        opened(host.session)
        shown(host.session, ["[Extensions]"], 60, "Pi did not start")
        shown(host.session, ["Manager connected: " + endpoint], 30, "Pi did not notify the manager connection")
        return host

    def pi_quit(host):
        closed(host.session)
        host.quit()
        host.session.__exit__(None, None, None)

    def tui_session():
        tui = tui_fixture.session()
        pids["tui"].append(tui.process.pid)
        opened(tui)
        tui.wait_screen("Manager profiles")
        tui.wait_screen("profile_1")
        tui.send(b"\r")
        tui.wait_screen("Manager workflows")
        return tui

    def tui_quit(tui, what, key=b"q"):
        tui.send(key)
        closed(tui)
        assert tui.wait_exit(20) == 0, "the TUI did not exit with status 0 " + what
        tui.assert_restored()
        tui.close()

    def save(session, label):
        (work / ("cross-lifecycle-" + label + ".screen.txt")).write_text(session.screen.text())

    def tui_open_run(tui, run, needles, label):
        """Open the overview from the workflow browser, focus the row of run
        and open its live monitor until it shows every needle."""
        tui.send(b"O")
        tui.wait_screen("Manager overview")
        deadline = time.monotonic() + 60
        while True:
            try:
                focus_row(tui, "run", "Run:" + run, 5)
                break
            except AssertionError:
                assert time.monotonic() < deadline, ("the overview does not list the run", run, tui.screen.text())
                tui.send(b"g")
                pump_all(0.5)
        tui.send(b"\r")
        screen = shown(tui, needles, 60, "the live monitor of the TUI did not show " + label)
        save(tui, label)
        return screen

    def published(run):
        """The supervision, limitations, runtime status and cancel offer that the manager publishes for run."""
        run_view, _, run_raw = observed("/v1/runs/" + run, "Run")
        snapshot, _, _ = observed("/v1/runs/" + run + "/snapshot", "RunSnapshot")
        control, _, control_raw = observed("/v1/runs/" + run + "/control", "RunControl")
        return {"supervision": run_view["supervision"], "limitations": run_view["limitations"],
                "runtime": snapshot["runtime"]["status"] if snapshot["runtime"] is not None else None,
                "cancelAllowed": control["cancelAllowed"], "controlSupervision": control["supervision"],
                "decisionHeadId": control["decisionHeadId"], "offers": [offer["operation"] for offer in control["offers"]]}

    def answer_rows(decision):
        return read_coordination("SELECT id, client_id, state FROM commands WHERE operation = 'answer' AND resource_uri = ? "
                                 "ORDER BY rowid", ("/v1/decisions/" + decision,))

    def pending_question(run):
        queue, _, _ = until("/v1/decisions?runId=" + run, "DecisionPage",
                            lambda value: any(item["state"] == "pending" and item["kind"] == "question" for item in value["items"]), 120)
        question = next(item for item in queue["items"] if item["state"] == "pending" and item["kind"] == "question")
        control, _, _ = until("/v1/runs/" + run + "/control", "RunControl", lambda value: value["decisionHeadId"] is not None)
        assert control["decisionHeadId"] == question["id"], ("the head of the run is not its person question", control["decisionHeadId"])
        return question

    def known_requests():
        status, listed, _ = request("/v1/requests", harness)
        assert status == 200, ("requests", status)
        return {item["id"] for item in listed["items"]}

    def new_request(known):
        snapshot, _, _ = until("/v1/snapshot", "OverviewSnapshot", lambda value: any(
            item["kind"] == "request" and item["request"]["id"] not in known and item["request"]["readiness"]["supplied"]
            for item in value["items"]))
        return next(item["request"] for item in snapshot["items"] if item["kind"] == "request" and item["request"]["id"] not in known)

    def pi_review_and_approve(pi, created, request_uri, label):
        """Show the exact review of the request in Pi and approve it with a
        and Yes. Give the displayed preparation and the run."""
        current, _, _ = until(request_uri, "Request", lambda value: value["phase"] == "review" and value["preparationId"] is not None)
        preparation_uri = "/v1/preparations/" + current["preparationId"]
        preparation, _, _ = observed(preparation_uri, "Preparation")
        shown(pi.session, ["Review of request " + created["id"] + ", preparation " + preparation["id"], "a approve after confirmation",
                           "Workflow: " + workflow["id"], "Profile: profile_1"] + [name + ": " + str(preparation[name]) for name in selectors],
              45, "Pi showed no exact review of request " + created["id"])
        pi.save_screen(label + "-review")
        pi.session.send(b"a")
        shown(pi.session, ["Approve this exact review?", preparation["reviewDigest"], "→ Yes"], 15, "a opened no approval confirmation")
        pi.session.send(b"\r")
        associated, _, _ = until(request_uri, "Request", lambda value: value["runId"] is not None)
        run = associated["runId"]
        shown(pi.session, ["Execution: the manager started run " + run], 45, "Pi did not report the started run")
        consumed, _, _ = observed(preparation_uri, "Preparation")
        approvals = read_coordination("SELECT id, client_id FROM commands WHERE operation = 'approve' AND resource_uri = ?", (preparation_uri,))
        assert consumed["state"] == "consumed" and all(consumed[name] == preparation[name] for name in selectors), (
            "the consumed preparation differs from the review that Pi showed", consumed["state"])
        assert len(approvals) == 1 and approvals[0][1] == clients["pi"], ("the approve command of Pi", approvals, clients["pi"])
        return preparation, run, approvals[0][0]

    order = ["observe-ready", "quit", "quitted", "reconnected", "held", "unreachable", "quarantined", "answered"]
    handled = []
    script = None

    def handshake_facts(name, timeout):
        """Wait until the Emacs script asks for the handshake name, which must be the next of order, and give its facts."""
        assert name == order[len(handled)], ("a handshake out of order", name, handled)
        path = handshake / (name + ".json")
        deadline = time.monotonic() + timeout
        while not path.exists():
            early = [item.stem for item in handshake.glob("*.json") if item.stem not in handled]
            assert not early, ("an unknown or early handshake of the Emacs script", early, name, handled)
            assert script.poll() is None, ("the Emacs script ended before the handshake", name, script.returncode)
            assert time.monotonic() < deadline, ("the Emacs script did not ask for the handshake", name)
            pump_all(0.05)
        handled.append(name)
        return json.loads(path.read_text())

    def handshake_answer(name, reply):
        staged = handshake / (name + ".done.new")
        staged.write_text(json.dumps(reply))
        staged.rename(handshake / (name + ".done"))

    lifetimes = [serve(0)]
    try:
        with harness_reads_only():
            status, capabilities, _ = request("/v1/capabilities", harness)
            assert status == 200, ("capabilities", status)
            status, catalogue, _ = request("/v1/workflows?profileId=profile_1", harness)
            assert status == 200, ("catalogue", status)
            index = next(i for i, item in enumerate(catalogue["items"]) if item["name"] == "mixed-controls")
            workflow = catalogue["items"][index]
            status, overview, _ = request("/v1/snapshot", harness)
            assert status == 200 and not overview["items"], ("the overview is not empty before the witness", status)
            client = mixed_client(capabilities, harness)
            observed = client[0]
            environment = {name: os.environ[name] for name in EMACS_ALLOWLIST if name in os.environ}
            script = subprocess.Popen([sys.executable, "-B", emacs_ui, "--service", str(tui_fixture.client_profiles["emacs"]),
                                       str(report_path), "--service-case", "witness-lifecycle", "--service-handshake", str(handshake),
                                       "--emacs", emacs_program, "--source", os.path.join(emacs_directory, "wf.el"),
                                       "--artifacts", str(artifacts)], env=environment, stdin=subprocess.DEVNULL)
            try:
                # 1. Pi creates, enqueues and approves the request, and the TUI observes the run.
                pi = pi_host("cross-lifecycle-pi", tui_fixture.client_profiles["pi"])
                known = known_requests()
                pi.session.send(b"/wfm\r")
                shown(pi.session, ["Manager profile", "profile_1", "profile_2"], 30, "/wfm showed no profile selection")
                pi.session.send(b"\r")
                shown(pi.session, ["Workflow of profile_1", "mixed-controls"], 30, "/wfm showed no workflow selection of profile_1")
                pi.session.send(b"\x1b[B" * index)
                shown(pi.session, ["→ mixed-controls"], 10, "the arrow keys did not select mixed-controls")
                pi.session.send(b"\r")
                shown(pi.session, ["Input input (declared source", "→ Literal text"], 30, "/wfm showed no input source selection")
                pi.session.send(b"\r")
                shown(pi.session, ["Input input: exact literal text"], 15, "/wfm opened no literal editor")
                pi.session.send(CROSS_LITERAL_2.encode())
                shown(pi.session, [CROSS_LITERAL_2], 15, "Pi does not show the typed literal")
                pi.save_screen("literal")
                pi.session.send(b"\r")
                created = new_request(known)
                request_uri = created["links"]["self"]
                assert created["profileId"] == "profile_1" and created["workflowId"] == workflow["id"], (
                    "the Pi request names another profile or workflow", created["profileId"], created["workflowId"])
                assert created["readiness"]["supplied"] == [{"name": "input", "source": "literal", "value": CROSS_LITERAL_2}], (
                    "the Pi request did not supply exactly the typed literal", created["readiness"]["supplied"])
                preparation, run, approve = pi_review_and_approve(pi, created, request_uri, "first")
                question = pending_question(run)
                rows = read_coordination("SELECT id, operation, client_id FROM commands ORDER BY rowid")
                assert [row[1] for row in rows if row[1] in ("create", "enqueue", "approve")] == ["create", "enqueue", "approve"] \
                    and all(row[2] == clients["pi"] for row in rows), ("the commands of the first request do not all name the pi client", rows, clients)
                tui = tui_session()
                monitor = tui_open_run(tui, run, ["Your answer", "Observation: current", "Runtime: Running", CROSS_LITERAL_2,
                                                  "Ctrl-C DETACH"], "observed")
                assert "supervision" not in monitor, ("the TUI does not show the run under owned supervision", monitor)
                handshake_facts("observe-ready", 300)
                handshake_answer("observe-ready", {"run": run, "question": question["id"]})
                facts = handshake_facts("quit", 300)
                assert facts["run"] == run and facts["head"] == question["id"] and facts["kind"] == "question" \
                    and "Supervision: owned" in facts["viewLines"] and "cancel" in facts["choices"] and facts["sent"] == [], (
                    "the Emacs view of the run before the quit", facts)
                print(f"PASS {mode} 1: Pi with credential", credentials["pi"], "created request", created["id"], "of profile_1 and",
                      workflow["name"], "through /wfm by keys with exactly the literal", repr(CROSS_LITERAL_2) + ", enqueued it and",
                      "approved preparation", preparation["id"], "with the one approve", approve + "; the", len(rows), "commands",
                      [row[1] for row in rows], "name client", clients["pi"], "of the pi credential, the Manager overview of the TUI",
                      "opened run", run, "at its question", question["id"], "and the view of Emacs showed it under the supervision",
                      "owned with the cancel choice", flush=True)

                # 2. All three clients close while the run waits at its question.
                before_quit = command_ids()
                tui_quit(tui, "after the detach", b"\x03")
                handshake_answer("quit", {})
                quitted = handshake_facts("quitted", 120)
                assert quitted["exitStatus"] == 0 and quitted["terminalRestored"] is True, ("the quit of Emacs", quitted)
                pi.save_screen("before-quit")
                pi_quit(pi)
                after_quit = command_ids()
                held = published(run)
                decision, _, _ = observed("/v1/decisions/" + question["id"], "Decision")
                assert after_quit == before_quit, ("a client sent a command when it closed", sorted(after_quit - before_quit))
                assert held["supervision"] == "owned" and held["decisionHeadId"] == question["id"] and decision["state"] == "pending", (
                    "the manager does not keep the run owned at its pending question", held, decision["state"])
                print(f"PASS {mode} 2: Ctrl-C detached the TUI from the live monitor with status 0 and the terminal restored,",
                      "C-x C-c quit Emacs with status 0 and the terminal attributes restored, and /quit ended Pi with status 0; the",
                      len(after_quit), "commands are the same before and after the three closes, and run", run, "is still owned",
                      "with its question", question["id"], "pending as the head", flush=True)

                # 3. Rotation of the emacs credential, and revocation of a fifth credential.
                old_emacs = {"Authorization": "Bearer " + (work / "credential-emacs").read_bytes().decode("ascii")}
                rotated = administration({"version": 1, "operation": "rotate-credential", "credentialId": credentials["emacs"],
                                          "expiresAt": "2999-01-01T00:00:00Z", "outputFile": str(work / "credential-emacs-rotated")})
                rotated_at = time.monotonic()
                rotated_id = rotated["result"]["credential"]["credentialId"]
                assert rotated["result"]["previousCredentialId"] == credentials["emacs"] \
                    and rotated["result"]["credential"]["clientId"] == clients["emacs"], ("the rotation of the emacs credential", rotated["result"])
                rotated_profile = tui_fixture.write_profile("emacs-rotated")
                new_emacs = {"Authorization": "Bearer " + (work / "credential-emacs-rotated").read_bytes().decode("ascii")}
                for name, authorized in (("old", old_emacs), ("rotated", new_emacs)):
                    status, value, _ = request("/v1/runs/" + run, authorized)
                    assert status == 200, ("a read with the " + name + " emacs credential in the overlap", status, value.get("code"))
                tui_fixture.issue("extra", ["observe"])
                extra = {"Authorization": "Bearer " + (work / "credential-extra").read_bytes().decode("ascii")}
                status, value, _ = request("/v1/runs/" + run, extra)
                assert status == 200, ("a read with the extra credential", status, value.get("code"))
                administration({"version": 1, "operation": "revoke-credential", "credentialId": credentials["extra"]})
                status, revoked, _ = request("/v1/runs/" + run, extra)
                assert status == 401 and revoked["code"] == "unauthenticated", ("the read after the revocation", status, revoked.get("code"))
                while True:
                    status, value, _ = request("/v1/runs/" + run, old_emacs)
                    if status == 401:
                        break
                    assert status == 200 and time.monotonic() < rotated_at + 75, ("the old emacs credential before its cutoff", status)
                    time.sleep(0.5)
                cutoff = time.monotonic() - rotated_at
                assert value["code"] == "unauthenticated", ("the refusal of the old emacs credential", value["code"])
                status, value, _ = request("/v1/runs/" + run, new_emacs)
                assert status == 200, ("the rotated emacs credential after the cutoff", status, value.get("code"))
                print(f"PASS {mode} 3: rotate-credential gave credential", rotated_id, "of client", clients["emacs"], "after",
                      credentials["emacs"] + ", and both read run", run, "in the overlap; the old credential was refused with 401",
                      f"unauthenticated {cutoff:.1f} seconds after the rotation while the rotated credential still reads, and the",
                      "fifth credential", credentials["extra"], "read once and was refused with 401 unauthenticated on the next read",
                      "after revoke-credential", flush=True)

                # 4. An ordinary restart of the manager.
                earlier = {ident: (resource, operation) for ident, resource, operation in
                           read_coordination("SELECT id, resource_uri, operation FROM commands")}
                lifetimes[0].send_signal(signal.SIGTERM)
                lifetimes[0].wait(timeout=25)
                (work / "server-0.exit").write_text(str(lifetimes[0].returncode) + "\n")
                assert lifetimes[0].returncode == 0, ("SIGTERM did not end the manager with status 0", lifetimes[0].returncode)
                logs = sorted(flow_dir.glob("*.ndjson"))
                assert len(logs) == 1, ("the manager logs", logs)
                logged_lines = logs[0].read_bytes().splitlines()
                last = json.loads(logged_lines[-1])
                assert last["schema"] == "notice" and last["body"]["inline"]["notice"] == "shutdown", (
                    "the manager log of the first lifetime does not end with its shutdown notice", last["schema"], last["body"])
                lifetimes.append(serve(1))
                restarted = published(run)
                approve_state = read_coordination("SELECT state FROM commands WHERE id = ?", (approve,))[0][0]
                (work / "cross-lifecycle-restart-state.json").write_text(json.dumps(
                    {"run": run, "held": held, "restarted": restarted, "approveState": approve_state}, indent=2))
                print(f"{mode} RESTART STATE run", run, "before", held, "after", restarted, "approve", approve_state, flush=True)
                assert restarted["supervision"] == "lost" and "lost-supervision" in restarted["limitations"] \
                    and restarted["controlSupervision"] == "lost" and restarted["cancelAllowed"] is False, (
                    "the restarted manager does not publish the run as lost without a cancel", restarted)
                print(f"PASS {mode} 4: SIGTERM ended the manager with status 0 and the shutdown notice of",
                      last["body"]["inline"]["processGeneration"], "at position", len(logged_lines) - 1, "of its log, and a new lifetime on the same root and configuration publishes run", run, "with the supervision",
                      restarted["supervision"] + ", the limitation lost-supervision, the runtime status", restarted["runtime"],
                      "and no cancel", flush=True)

                # 5. A new Emacs with the rotated profile, a new Pi and a new TUI show the lost run.
                status, catalogue, _ = request("/v1/workflows?profileId=profile_1", harness)
                assert status == 200, ("catalogue after the restart", status)
                index = next(i for i, item in enumerate(catalogue["items"]) if item["name"] == "mixed-controls")
                workflow = catalogue["items"][index]
                handshake_answer("quitted", {"profile": str(rotated_profile)})
                # The name keeps the bridge socket path of ext-pi, which
                # macOS truncates to 104 bytes, off every existing path of
                # the Pi host, as for the first Pi.
                pi = pi_host("cross-lifecycle-pi-2", tui_fixture.client_profiles["pi"])
                pi.session.send(("/wfm-monitor " + run + "\r").encode())
                runtime = restarted["runtime"] or "not yet observed"
                shown(pi.session, ["Service run " + run, "Runtime: " + runtime + "; supervision lost", "Offers: none"], 60,
                      "the Pi monitor did not show the lost run")
                pi.save_screen("lost")
                pi.session.send(b"q")
                pi.session.settle()
                tui = tui_session()
                label = next((label for label, status in LABEL_STATUS.items() if status == restarted["runtime"]), None)
                lost_screen = tui_open_run(tui, run, ["supervision lost"], "lost")
                assert (label is None and "Runtime: not yet observed; supervision lost" in lost_screen) or (
                    squeeze("Runtime: " + str(label) + "; supervision lost") in squeeze(lost_screen)), (
                    "the TUI does not show the runtime status of the lost run", restarted["runtime"], lost_screen)
                assert "c CANCEL" not in lost_screen, ("the TUI offers a cancel of the lost run", lost_screen)
                facts = handshake_facts("reconnected", 300)
                assert facts["run"] == run and "Supervision: lost" in facts["viewLines"] and "Runtime: " + runtime in facts["viewLines"] \
                    and "Offers: none" in facts["viewLines"] and "cancel" not in facts["choices"] and facts["sent"] == [], (
                    "the view of the second Emacs does not show the lost run", facts)
                assert command_ids() == set(earlier), ("a command was added across the restart and the reconnection",
                                                       sorted(command_ids() - set(earlier)))
                print(f"PASS {mode} 5: a new Emacs with the rotated credential", rotated_id + ", a new Pi and a new TUI each show run",
                      run, "with the supervision lost, the runtime status", runtime, "and no cancel offer, as the restarted",
                      "manager publishes it, and the", len(earlier), "commands of the first lifetime are the only commands", flush=True)

                # 6. The orderly close released the reservation of the lost
                # run, so a new request of the same resource key is admitted
                # at once and reaches review without a client command.
                checked = administration({"version": 1, "operation": "check-store"})["result"]
                assert checked["integrity"] == "valid" and checked["quarantineIds"] == [], ("check-store after the orderly close", checked)
                closed_reservations = read_coordination("SELECT state, pending_kind FROM reservations WHERE request_id = ?", (created["id"],))
                assert closed_reservations == [("released", "closed")], (
                    "the orderly close did not release the reservation of the lost run", closed_reservations)
                tui.send(b"\x1b")
                shown(tui, ["Manager overview"], 10, "Esc did not return to the overview")
                tui.send(b"\x1b")
                shown(tui, ["Manager workflows"], 10, "Esc did not return to the workflow browser")
                known = known_requests()
                tui.send(b"\x1b[B" * index + b"\r")
                shown(tui, ["request validator current"], 20, "the TUI opened no input editor")
                tui.send(b"\x1b[200~" + CROSS_LITERAL_3.encode() + b"\x1b[201~")
                tui.send(b"\x04")
                queued = new_request(known)
                queued_uri = queued["links"]["self"]
                assert queued["readiness"]["supplied"] == [{"name": "input", "source": "literal", "value": CROSS_LITERAL_3}], (
                    "the TUI request did not supply exactly the typed literal", queued["readiness"]["supplied"])
                shown(tui, ["REQUEST REVIEW"], 20, "the TUI showed no request review")
                tui.send(b"\r")
                enqueued = until(queued_uri, "Request", lambda value: value["phase"] != "draft")[0]
                enqueue_rows = read_coordination("SELECT id, client_id FROM commands WHERE operation = 'enqueue' AND resource_uri = ?", (queued_uri,))
                assert len(enqueue_rows) == 1 and enqueue_rows[0][1] == clients["tui"], ("the enqueue of the TUI", enqueue_rows)
                after_enqueue = command_ids()
                reviewed, _, _ = until(queued_uri, "Request", lambda value: value["phase"] == "review" and value["preparationId"] is not None, 60)
                shown(tui, ["Approve exact manager review", "Request: " + queued["id"]], 45, "the TUI showed no exact review of its request")
                save(tui, "review")
                assert command_ids() == after_enqueue, ("a command was added between the enqueue and the review",
                                                        sorted(command_ids() - after_enqueue))
                creations = read_coordination("SELECT operation, client_id FROM commands WHERE request_id = ? ORDER BY rowid", (queued["id"],))
                assert [operation for operation, _ in creations] == ["create", "set-input", "enqueue"] \
                    and all(client_id == clients["tui"] for _, client_id in creations), ("the commands of the TUI request", creations)
                print(f"PASS {mode} 6: check-store reports no quarantine and the orderly close released the reservation of run", run,
                      "with the pending kind closed; the TUI created request", queued["id"], "of profile_1 with exactly the literal",
                      repr(CROSS_LITERAL_3), "and enqueued it, it left the draft phase as", enqueued["phase"], "with the reasons",
                      enqueued["admission"]["reasons"], "and the key cross_one free, and it reached review with preparation",
                      reviewed["preparationId"], "without a client command after its enqueue", flush=True)

                # 7. Pi approves the request of the TUI, and its run is held
                # at its question while it holds the key cross_one.
                pi.session.send(("/wfm-review " + queued["id"] + "\r").encode())
                second_preparation, second, second_approve = pi_review_and_approve(pi, queued, queued_uri, "second")
                second_question = pending_question(second)
                # The TUI follows its request into the live monitor of its run.
                shown(tui, ["Your answer", "Observation: current", "Run: " + second, CROSS_LITERAL_3], 60,
                      "the live monitor of the TUI did not show the held run " + second)
                save(tui, "held")
                handshake_answer("reconnected", {"run": second, "question": second_question["id"]})
                facts = handshake_facts("held", 300)
                assert facts["run"] == second and facts["head"] == second_question["id"] and facts["kind"] == "question" \
                    and "Supervision: owned" in facts["viewLines"] and "cancel" in facts["choices"] and facts["sent"] == [], (
                    "the Emacs view of the held run", facts)
                held_reservation = read_coordination("SELECT id, state FROM reservations WHERE request_id = ? AND state != 'released'",
                                                     (queued["id"],))
                claims = read_coordination("SELECT resource_key FROM reservation_resources WHERE reservation_id = ?",
                                           (held_reservation[0][0],)) if len(held_reservation) == 1 else []
                assert len(held_reservation) == 1 and held_reservation[0][1] == "held" and claims == [("cross_one",)], (
                    "the run of the TUI request does not hold the key cross_one", held_reservation, claims)
                pi.save_screen("second-held")
                pi_quit(pi)
                print(f"PASS {mode} 7: Pi ran /wfm-review", queued["id"], "and approved preparation", second_preparation["id"],
                      "with the one approve", second_approve, "of client", clients["pi"] + "; run", second, "is held at its question",
                      second_question["id"], "with reservation", held_reservation[0][0], "holding the key cross_one, the TUI shows",
                      "it in its live monitor, the second Emacs shows it under the supervision owned, and /quit ended Pi", flush=True)

                # 8. A manager loss by SIGKILL while the run is held, and a
                # new lifetime on the same root and configuration.
                second_lifetime = command_ids()
                lifetimes[1].kill()
                lifetimes[1].wait(timeout=25)
                (work / "server-1.exit").write_text(str(lifetimes[1].returncode) + "\n")
                assert lifetimes[1].returncode == -signal.SIGKILL, ("the second lifetime did not end by SIGKILL", lifetimes[1].returncode)
                shown(tui, ["manager unreachable since", "Observation: stale ("], 30, "the TUI did not report the lost manager")
                save(tui, "unreachable")
                handshake_answer("held", {})
                facts = handshake_facts("unreachable", 120)
                assert facts["run"] == second and "Delivery: unreachable" in facts["viewLines"] and facts["sent"] == [], (
                    "the Emacs view of the held run after the kill", facts)
                lifetimes.append(serve(2))
                handshake_answer("unreachable", {})
                killed = published(second)
                assert killed["supervision"] == "lost" and "lost-supervision" in killed["limitations"] \
                    and killed["controlSupervision"] == "lost" and killed["cancelAllowed"] is False, (
                    "the third lifetime does not publish the held run as lost without a cancel", killed)
                checked = administration({"version": 1, "operation": "check-store"})["result"]
                assert checked["integrity"] == "valid" and checked["quarantineIds"] == [held_reservation[0][0]], (
                    "check-store after the manager loss", checked, held_reservation)
                quarantine = checked["quarantineIds"][0]
                assert read_coordination("SELECT state FROM reservations WHERE id = ?", (quarantine,)) == [("quarantined",)] \
                    and read_coordination("SELECT resource_key FROM reservation_resources WHERE reservation_id = ?", (quarantine,)) \
                    == [("cross_one",)], ("the quarantined reservation does not keep the key cross_one", quarantine)
                killed_label = next((label for label, status in LABEL_STATUS.items() if status == killed["runtime"]), None)
                killed_runtime = killed["runtime"] or "not yet observed"
                tui_lost = shown(tui, ["supervision lost", "Observation: current"], 60, "the TUI did not reconnect to the third lifetime")
                assert "manager unreachable" not in tui_lost and "c CANCEL" not in tui_lost and (
                    (killed_label is None and "Runtime: not yet observed; supervision lost" in tui_lost)
                    or squeeze("Runtime: " + str(killed_label) + "; supervision lost") in squeeze(tui_lost)), (
                    "the TUI does not show the held run as the third lifetime publishes it", killed, tui_lost)
                save(tui, "killed-lost")
                facts = handshake_facts("quarantined", 300)
                assert facts["run"] == second and "Supervision: lost" in facts["viewLines"] \
                    and "Runtime: " + killed_runtime in facts["viewLines"] and "Offers: none" in facts["viewLines"] \
                    and "cancel" not in facts["choices"] and facts["sent"] == [], ("the Emacs view of the run after the manager loss", facts)
                status, catalogue, _ = request("/v1/workflows?profileId=profile_1", harness)
                assert status == 200, ("catalogue after the manager loss", status)
                index = next(i for i, item in enumerate(catalogue["items"]) if item["name"] == "mixed-controls")
                workflow = catalogue["items"][index]
                pi = pi_host("cross-lifecycle-pi-3", tui_fixture.client_profiles["pi"])
                pi.session.send(("/wfm-monitor " + second + "\r").encode())
                shown(pi.session, ["Service run " + second, "Runtime: " + killed_runtime + "; supervision lost", "Offers: none"], 60,
                      "the Pi monitor did not show the run lost by the manager loss")
                pi.save_screen("killed-lost")
                pi.session.send(b"q")
                pi.session.settle()
                assert command_ids() == second_lifetime, ("a command was added across the manager loss",
                                                          sorted(command_ids() - second_lifetime))
                print(f"PASS {mode} 8: SIGKILL ended the second lifetime while run", second, "was held; the TUI reported the",
                      "unreachable manager and the second Emacs the delivery unreachable with no key; the third lifetime publishes",
                      "the run with the supervision lost, the runtime status", killed_runtime, "and no cancel, which the TUI, the",
                      "second Emacs and a new Pi each show, check-store lists the one quarantine", quarantine, "with the key",
                      "cross_one, and no command was added", flush=True)

                # 9. A new request of the key cross_one waits with
                # profile-busy until release-quarantine, and then reaches
                # review without a client command.
                tui.send(b"\x1b")
                shown(tui, ["Manager overview"], 10, "Esc did not return to the overview")
                tui_quit(tui, "after the manager loss")
                tui = tui_session()
                known = known_requests()
                tui.send(b"\x1b[B" * index + b"\r")
                shown(tui, ["request validator current"], 20, "the TUI opened no input editor")
                tui.send(b"\x1b[200~" + CROSS_LITERAL_4.encode() + b"\x1b[201~")
                tui.send(b"\x04")
                third_request = new_request(known)
                third_uri = third_request["links"]["self"]
                assert third_request["readiness"]["supplied"] == [{"name": "input", "source": "literal", "value": CROSS_LITERAL_4}], (
                    "the TUI request did not supply exactly the typed literal", third_request["readiness"]["supplied"])
                shown(tui, ["REQUEST REVIEW"], 20, "the TUI showed no request review")
                tui.send(b"\r")
                waiting = until(third_uri, "Request", lambda value: value["phase"] == "queued"
                                and value["admission"]["reasons"] == ["profile-busy"], 30)[0]
                after_enqueue = command_ids()
                creations = read_coordination("SELECT operation, client_id FROM commands WHERE request_id = ? ORDER BY rowid",
                                              (third_request["id"],))
                assert [operation for operation, _ in creations] == ["create", "set-input", "enqueue"] \
                    and all(client_id == clients["tui"] for _, client_id in creations), ("the commands of the third TUI request", creations)
                shown(tui, ["Phase: queued", "Blocking reasons: profile-busy"], 30, "the TUI does not show the profile-busy wait")
                save(tui, "profile-busy")
                pi.session.send(("/wfm-review " + third_request["id"] + "\r").encode())
                shown(pi.session, ["Request " + third_request["id"] + ": queued", "waiting for profile-busy"], 30,
                      "Pi does not show the profile-busy wait")
                pi.save_screen("profile-busy")
                deadline = time.monotonic() + 60
                checks = 0
                while True:
                    evidence = administration({"version": 1, "operation": "check-quarantine", "quarantineId": quarantine})["result"]
                    checks += 1
                    if evidence["state"] == "clean":
                        break
                    assert evidence["state"] == "cleanup-required" and time.monotonic() < deadline, ("check-quarantine", evidence)
                    pump_all(0.5)
                still, _, _ = observed(third_uri, "Request")
                assert still["phase"] == "queued" and still["admission"]["reasons"] == ["profile-busy"], (
                    "the request did not wait with profile-busy until the release", still["phase"], still["admission"]["reasons"])
                released = administration({"version": 1, "operation": "release-quarantine", "quarantineId": quarantine,
                                           "cleanupEvidenceId": evidence["cleanupEvidenceId"],
                                           "cleanupEvidenceDigest": evidence["cleanupEvidenceDigest"]})["result"]
                assert released == {"quarantineId": quarantine, "state": "released"}, ("release-quarantine", released)
                third_reviewed, _, _ = until(third_uri, "Request", lambda value: value["phase"] == "review"
                                             and value["preparationId"] is not None, 60)
                shown(tui, ["Approve exact manager review", "Request: " + third_request["id"]], 45,
                      "the TUI showed no exact review of its request after the release")
                save(tui, "released-review")
                assert command_ids() == after_enqueue, ("a command was added between the enqueue and the review",
                                                        sorted(command_ids() - after_enqueue))
                print(f"PASS {mode} 9: the TUI created request", third_request["id"], "of profile_1 with exactly the literal",
                      repr(CROSS_LITERAL_4), "and enqueued it; it waited queued with", waiting["admission"]["reasons"], "in the TUI",
                      "and in Pi behind quarantine", quarantine + "; after", checks, "check-quarantine reads it reported clean with",
                      evidence["cleanupEvidenceId"], "and release-quarantine with that identity and digest released it, and the",
                      "request reached review with preparation", third_reviewed["preparationId"], "without a client command after its",
                      "enqueue", flush=True)

                # 10. Pi approves, the second Emacs answers false, and Pi sends the retry.
                stores_before = set(work.glob("manager/runs/runs/*/runtime"))
                third_preparation, third, third_approve = pi_review_and_approve(pi, third_request, third_uri, "third")
                third_store = ControlHarness.new_store(stores_before)
                third_question = pending_question(third)
                handshake_answer("quarantined", {"run": third, "question": third_question["id"]})
                facts = handshake_facts("answered", 300)
                sent = facts["sent"]
                assert len(sent) == 1 and sent[0]["resource"].endswith("/v1/decisions/" + third_question["id"]) \
                    and json.loads(sent[0]["body"])["value"] is False, ("the second Emacs sent other than the one answer false", sent)
                deadline = time.monotonic() + 45
                while not ((found := answer_rows(third_question["id"])) and found[0][2] == "effect-observed"):
                    assert time.monotonic() < deadline and len(found) <= 1, ("the answer of Emacs did not reach its effect", found)
                    pump_all()
                assert len(found) == 1 and found[0][1] == clients["emacs"], ("the answer command of Emacs", found, clients["emacs"])
                recovery = until("/v1/runs/" + third + "/control", "RunControl",
                                 lambda value: value["decisionHeadId"] not in (None, third_question["id"]), 120)[0]["decisionHeadId"]
                recovery_decision, _, _ = observed("/v1/decisions/" + recovery, "Decision")
                assert recovery_decision["kind"] == "recovery", ("the next head of the third run", recovery_decision["kind"])
                pi.session.send(("/wfm-answer " + third + "\r").encode())
                shown(pi.session, ["Recovery of decision " + recovery], 30, "/wfm-answer opened no recovery selection")
                for _ in range(8):
                    if "→ Retry" in pi.session.screen.text():
                        break
                    pi.session.send(b"\x1b[B")
                    pi.session.settle()
                shown(pi.session, ["→ Retry"], 10, "the recovery selection offers no Retry")
                pi.session.send(b"\r")
                shown(pi.session, ["Recovery Retry reached decision " + recovery], 45, "Pi did not report the retry")
                until("/v1/runs/" + third + "/snapshot", "RunSnapshot",
                      lambda value: value["runtime"] is not None and value["runtime"]["status"] in ("succeeded", "failed", "cancelled"), 120)
                retries = read_coordination("SELECT id, client_id, state FROM commands WHERE operation = 'retry' AND resource_uri = ?",
                                            ("/v1/runs/" + third + "/control",))
                assert len(retries) == 1 and retries[0][1:] == (clients["pi"], "effect-observed"), ("the retry of Pi", retries)
                artifact = verified_download(third, client, harness)
                handshake_answer("answered", {})
                # The TUI follows its own request into the live monitor of its run.
                shown(tui, ["Terminal: succeeded", "Result SHA-256: " + artifact["sha256"],
                            "Result: verified " + str(int(artifact["bytes"])) + " bytes"], 60,
                      "the live monitor of the TUI did not show the verified result of run " + third)
                save(tui, "succeeded")
                tui.send(b"\x1b")
                shown(tui, ["Manager overview"], 10, "Esc did not return to the overview")
                tui_quit(tui, "after the terminal run")
                pi_quit(pi)
                recorded = [entry["answer"] for entry in json.loads((third_store / "answers.json").read_bytes())["answers"]
                            if entry["occurrenceId"] == third_question["address"]["occurrenceId"]]
                assert recorded == [False], (CROSS_FALSE, recorded)
                print(f"PASS {mode} 10: Pi approved preparation", third_preparation["id"], "with the one approve", third_approve,
                      "of client", clients["pi"] + "; the second Emacs answered question", third_question["id"], "of run", third,
                      "with false by keys, and its answer", found[0][0], "of client", clients["emacs"], "reached effect-observed;",
                      "Pi sent the retry", retries[0][0], "of recovery", recovery, "with its control choice, the run succeeded, the",
                      "TUI showed the terminal status and the verified", artifact["bytes"], "bytes with SHA-256", artifact["sha256"],
                      "and answers.json records JSON false", flush=True)
                deadline = time.monotonic() + 120
                while script.poll() is None:
                    assert time.monotonic() < deadline, "the Emacs script did not end after the handshake answered"
                    time.sleep(0.05)
            finally:
                if script.poll() is None:
                    script.kill()
                script.wait(timeout=25)
                for session in list(sessions):
                    sessions.remove(session)
                    session.__exit__(None, None, None)
            report = json.loads(report_path.read_bytes()) if report_path.exists() else {"steps": [], "version": None}
            assert script.returncode == 0, ("the Emacs script of " + emacs_ui + " failed", script.returncode, report["steps"], handled)
            assert report["version"] == CROSS_LIFECYCLE_REPORT_VERSION, (
                f"The {mode} mode requires report version {CROSS_LIFECYCLE_REPORT_VERSION}, and {emacs_ui} wrote version {report['version']}.")
            assert report["steps"] == [str(number) for number in range(1, 11)] and handled == order, ("the steps of Emacs", report["steps"], handled)
            assert report["firstExitStatus"] == 0 and report["firstTerminalAfter"] == report["firstTerminalBefore"] \
                and report["laterExitStatus"] == 0 and report["laterTerminalAfter"] == report["laterTerminalBefore"], (
                "the exits of the two Emacs processes", report["firstExitStatus"], report["laterExitStatus"])
            assert report["firstSent"] == [] and report["laterSent"] == sent, ("the commands of the Emacs sessions", report["firstSent"], report["laterSent"])
            pids["emacs"] += [report["emacsPid"], report["laterPid"]]
    finally:
        for lifetime in lifetimes:
            if lifetime.poll() is None:
                lifetime.send_signal(signal.SIGTERM)
            lifetime.wait(timeout=25)
        (work / f"server-{len(lifetimes) - 1}.exit").write_text(str(lifetimes[-1].returncode) + "\n")
    assert len(lifetimes) == 3 and lifetimes[-1].returncode == 0, (
        "SIGTERM did not end the third lifetime with status 0", [lifetime.returncode for lifetime in lifetimes])

    # 11. The manager log: three lifetimes, the killed one without its
    # shutdown notice, each command once, the senders, and no command sent
    # again.
    logs = sorted(flow_dir.glob("*.ndjson"))
    stores = sorted(work.glob("manager/runs/runs/*/runtime"))
    status, records, summary = read_flow("cross-lifecycle-flow", [flow_dir] + stores)
    assert status == 2 and summary["verified"] and not summary["problems"], ("the flow verb did not verify the logs", status, summary["problems"])
    assert summary["states"]["undecided"] == [], ("undecided commands after the restarts", summary["states"]["undecided"])
    lifetimes_read = summary["joins"]["lifetimes"]
    assert len(lifetimes_read) == 3 and [item["shutdown"] is not None for item in lifetimes_read] == [True, False, True], (
        "the manager lifetimes", lifetimes_read)
    assert summary["states"]["lifetimeWithoutShutdown"] == [lifetimes_read[1]["lifetime"]], (
        "the lifetimes without a shutdown notice", summary["states"]["lifetimeWithoutShutdown"])
    manager = [record for record in records if record["log"] == str(logs[0])]
    rows = read_coordination("SELECT id, resource_uri, operation, client_id FROM commands ORDER BY rowid")
    boundaries = [item["lifetime"]["position"] for item in lifetimes_read[1:]]
    for ident, resource, operation, _ in rows:
        logged = [record for record in manager if record["schema"] == "command" and record["about"].get("command") == ident]
        assert len(logged) == 1, ("a command has other than one manager-log record", ident, operation, len(logged))
        accepted_in = sum(logged[0]["position"] > boundary for boundary in boundaries)
        expected = 0 if ident in earlier else 1 if ident in second_lifetime else 2
        assert accepted_in == expected, ("a command is in another lifetime", ident, operation, accepted_in, expected)
    targets = [(resource, operation) for _, resource, operation, _ in rows if operation != "create"]
    assert len(set(targets)) == len(targets), ("a command repeats the target and the operation of an earlier command", targets)
    answer_record = next(record for record in manager if record["schema"] == "command" and record["about"].get("command") == found[0][0])
    assert answer_record["from"] == {"principal": "credential", "credentialId": rotated_id, "client": clients["emacs"]}, (
        "the answer of Emacs is not from the rotated credential", answer_record["from"])
    print(f"PASS {mode} 11: the manager log holds three lifetimes, the second without its shutdown notice, and the flow verb",
          "reports it as the one lifetime without a shutdown and no undecided command; each of the", len(rows), "commands has",
          "one record in the lifetime that accepted it (", len(earlier), len(second_lifetime) - len(earlier),
          len(rows) - len(second_lifetime), "), no command repeats the target and the operation of an earlier command, and the",
          "answer", found[0][0], "is from credential", rotated_id, "of client", clients["emacs"], flush=True)

    # 12. No child remains, and the fixture secrets and homes are removed.
    removed = emacs_service_cleanup(artifacts, [tui_fixture.client_profiles[name] for name in CrossClientFixture.CLIENTS]
                                    + [rotated_profile] + [host.home for host in hosts] + [host.agent for host in hosts]
                                    + [host.state for host in hosts])
    print(f"PASS {mode} 12: all clients quit, the manager stopped, no TUI, Emacs, Pi or fixture process remains, and the harness",
          "removed", removed, "credential, client profile and home paths", flush=True)
    elapsed = time.monotonic() - mode_started
    assert elapsed <= WITNESS_SECONDS, ("the witness took longer than its budget", round(elapsed), WITNESS_SECONDS)
    print(f"PASS {mode}: Pi created and approved a run that the TUI and Emacs observed, the three clients closed without a command,",
          "the emacs credential was rotated and a fifth credential revoked, SIGTERM restarted the manager, a new TUI, Pi and Emacs",
          "showed the run lost, a new request of its resource key was admitted at once and held, SIGKILL lost the manager, a",
          "further request waited with profile-busy until release-quarantine, and Pi, the rotated Emacs and the TUI took it to a",
          "verified result; the client processes were the TUI (pids " + ", ".join(map(str, pids["tui"])) + "), Emacs",
          "(pids " + ", ".join(map(str, pids["emacs"])) + ") and Pi (pids " + ", ".join(map(str, pids["pi"])) + "),",
          f"in {elapsed:.0f} seconds", flush=True)

def cross_client_lineage_checks():
    """The cross-client-lineage mode: the history and the lineage of the
    runs of the fixture across the TUI, Pi and Emacs. See
    CROSS_CLIENT_LINEAGE for the steps."""
    harness = tui_fixture.harness
    mode = sys.argv[5]
    endpoint = f"https://127.0.0.1:{port}/v1"
    artifacts = work / "cross-lineage-emacs"
    report_path = work / "cross-lineage-emacs-report.json"
    handshake = work / "cross-lineage-handshake"
    handshake.mkdir(mode=0o700)
    selectors = ("reviewDigest", "requestRevision", "profileRevision", "descriptorRevision", "processGeneration")
    clients = tui_fixture.client_ids
    record = WitnessRecord()
    pids = record.pids
    hosts = []
    # The pseudo-terminal of the client process that runs at the moment,
    # which the helpers below pump while the harness waits.
    session = None

    def pump(wait=0.1):
        if session is None:
            time.sleep(wait)
        else:
            assert session.process.poll() is None, ("a client process ended while the harness waited", session.screen.text())
            session.pump(wait)

    def shown(needles, timeout, what):
        """Pump until the screen shows every needle, compared without
        white space so that wrapped rows join, and give the screen."""
        deadline = time.monotonic() + timeout
        while True:
            screen = session.screen.text()
            if all(squeeze(needle) in squeeze(screen) for needle in needles):
                session.settle()
                return session.screen.text()
            assert time.monotonic() < deadline, (what, needles, screen)
            pump()

    def until(path, schema, ready, timeout=45):
        """Read the resource until ready holds, and pump the
        pseudo-terminal of the running client between the reads, since a
        client that writes to a full terminal waits."""
        deadline = time.monotonic() + timeout
        while True:
            value, tag, raw = observed(path, schema)
            if ready(value):
                return value, tag, raw
            assert time.monotonic() < deadline, ("observation deadline", path, None if session is None else session.screen.text())
            pump()

    def save(name):
        (work / ("cross-lineage-" + name + ".screen.txt")).write_text(session.screen.text())

    with (work / "server-0.stdout").open("wb") as output, (work / "server-0.stderr").open("wb") as errors:
        process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                    "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
    try:
        wait_ready(process)
        status, capabilities, _ = request("/v1/capabilities", harness)
        assert status == 200, ("capabilities", status)
        status, overview, _ = request("/v1/snapshot", harness)
        assert status == 200 and not overview["items"], ("the overview is not empty before the witness", status)
        probe = ssl.create_default_context(cafile=str(cert))
        with socket.create_connection(("127.0.0.1", port), timeout=10) as raw, probe.wrap_socket(raw, server_hostname="127.0.0.1") as wrapped:
            negotiated = wrapped.version()
        assert negotiated == "TLSv1.3", ("the manager negotiated another TLS version", negotiated)

        # 1. The harness creates and settles the two parents.
        runs = ControlHarness(harness, capabilities, mode)
        observed, wait_for = runs.client[0], runs.client[1]
        first, second = runs.start("profile_1"), runs.start("profile_2")
        parents = {}
        for parent in (first, second):
            _, answered, recovered = drive_mixed(parent, runs.client, overview=False)
            assert (answered, recovered) == (1, 1), ("the harness settled a parent with other controls", parent, answered, recovered)
            runs.ended(parent, "succeeded")
            wait_for("/v1/runs/" + parent, "Run", lambda value: value["supervision"] not in ("owned", "cleanup-pending"))
            parents[parent] = verified_download(parent, runs.client, harness)
        snapshot, _, _ = observed("/v1/runs/" + first + "/snapshot", "RunSnapshot")
        assert snapshot["page"]["next"] is None, "the snapshot of the first parent has more than one page"
        person = [item for item in snapshot["items"] if item["prompt"].startswith("Independent confirmation?")]
        assert len(person) == 1 and person[0]["state"] == "completed" and person[0]["code"] == "flag", (
            "the person occurrence of the first parent", person)
        occurrence = person[0]["occurrenceId"]
        lineage_uri = "/v1/runs/" + first + "/lineage-requests"
        wait_for(lineage_uri, "LineagePage", lambda value: "fork" in value["eligible"] and not value["items"])
        print(f"PASS {mode} 1: the harness with credential", tui_fixture.credential_ids["harness"], "created, approved and settled the",
              "mixed-controls runs", first, "of profile_1 and", second, "of profile_2 to terminal success, each with one answer and one",
              "retry, and downloaded their verified results; the lineage collection of", first, "lists fork as eligible and no child,",
              "and its person question is occurrence", occurrence, flush=True)
        record.step_done("1", "harness", [first, second])

        def history_of(count):
            """Every page of /v1/runs, which must list count runs."""
            history, observers, pages = run_history(harness)
            assert len(history) == count and len(set(history)) == count and observers == 0, (
                "the run history of the fixture", history, observers)
            return history, pages

        with harness_reads_only():
            # 2. The TUI History view lists the runs in the order of /v1/runs.
            history, pages = history_of(2)
            with tui_fixture.session() as tui:
                session = tui
                pids["tui"].append(tui.process.pid)
                tui.wait_screen("Manager profiles")
                tui.wait_screen("profile_1")
                tui.send(b"\r")
                tui.wait_screen("Manager workflows")
                tui.wait_screen("H HISTORY")
                tui.send(b"H")
                tui.wait_screen("Manager history")
                tui.wait_screen("History: current; runs: 2 (managed 2, legacy 0)", timeout=30)
                for index, run in enumerate(history):
                    history_focus(tui, index, run)
                save("tui-history")
                print(f"PASS {mode} 2: the TUI with credential", tui_fixture.credential_ids["tui"], "opened the History view with H at",
                      "80x24, which counts 2 managed runs, and its rows name", ", ".join(history), "in the order of the", pages,
                      "pages of /v1/runs", flush=True)
                record.step_done("2", "tui", history)

                # 3. The TUI forks the first parent with one replacement and leaves its review.
                history_focus(tui, history.index(first), first)
                tui.send(b"\r")
                tui.wait_screen("Manager run detail", timeout=10)
                shown(["Run detail: current", "Run: " + first], 20, "the TUI did not open the run detail of the first parent")
                tui.send(b"l")
                shown(["Lineage of run " + first, "f fork: eligible"], 15, "the TUI did not open the lineage menu of the first parent")
                tui.send(b"f")
                shown(["Fork of run " + first], 10, "f did not open the fork edits")
                target = "> occurrence " + occurrence + " (flag): keep"
                for _ in range(8):
                    if squeeze(target) in squeeze(tui.screen.text()):
                        break
                    tui.send(b"\x1b[B")
                    tui.settle()
                shown([target], 10, "the fork edits do not select the person occurrence")
                tui.send(b"\r")
                shown(["Replacement answer for occurrence " + occurrence + " (flag)"], 10, "Enter opened no replacement editor")
                tui.send(CROSS_FORKED.encode())
                tui.send(b"\x04")
                shown(["> occurrence " + occurrence + " (flag): replace with true"], 10, "the fork edits do not hold the replacement")
                save("tui-fork-edits")
                mutation_key(tui, b"\x04", "Lineage: fork of run " + first + "; the inputs come from the parent run", 30)
                tui.wait_screen("Enter REQUEST REVIEW", timeout=30)
                page, _, _ = observed(lineage_uri, "LineagePage")
                assert len(page["items"]) == 1 and page["items"][0]["lineage"] == "fork" and page["items"][0]["parentRunId"] == first, (
                    "the lineage collection of the first parent", page["items"])
                child_id = page["items"][0]["id"]
                child_uri = "/v1/requests/" + child_id
                mutation_key(tui, b"\r", "Approve exact manager review", 45)
                child, _, _ = until(child_uri, "Request", lambda value: value["phase"] == "review" and value["preparationId"] is not None)
                preparation_uri = "/v1/preparations/" + child["preparationId"]
                preparation, _, raw = observed(preparation_uri, "Preparation")
                (work / "cross-lineage-review.json").write_bytes(raw)
                forked_sha256 = hashlib.sha256(json.dumps(True, separators=(",", ":")).encode()).hexdigest()
                edits = [{"occurrenceId": occurrence, "operation": "replace", "sha256": forked_sha256}]
                assert preparation["state"] == "live" and preparation["review"]["lineage"] == {
                    "parentRunId": first, "operation": "fork", "edits": edits}, (
                    "the review lineage of the child", preparation["state"], preparation["review"].get("lineage"))
                edit_row = "Lineage edits: replace occurrence " + occurrence + " (answer SHA-256 " + forked_sha256 + ")"
                shown(["Lineage: fork of run " + first, edit_row, "Preparation: " + preparation["id"]], 15,
                      "the TUI review does not show the lineage of the child")
                save("tui-review")
                tui.send(b"q")
                assert tui.wait_exit(20) == 0, "the TUI did not exit with status 0 at the child review"
                tui.assert_restored()
            session = None
            still, _, _ = observed(child_uri, "Request")
            kept, _, _ = observed(preparation_uri, "Preparation")
            assert still["phase"] == "review" and still["runId"] is None and kept["state"] == "live", (
                "the child request left its review after the TUI quit", still["phase"], kept["state"])
            print(f"PASS {mode} 3: in the TUI, Enter on the History row of", first, "opened its run detail, and l, f, the person",
                  "occurrence", occurrence, "the replacement", repr(CROSS_FORKED), "and Ctrl-D forked it as child request", child_id + ";",
                  "Enter prepared its review", preparation["id"], "and the TUI showed", repr(edit_row) + ", and q quit without y, with exit",
                  "status 0 and the terminal restored, while the child waits in review", flush=True)
            record.step_done("3", "tui", [first])

            # 4. Pi lists the same runs with /wfm-history.
            pi = PiHost("lineage-pi", client_profile=tui_fixture.client_profiles["pi"])
            hosts.append(pi)
            with pi:
                session = pi.session
                pids["pi"].append(session.process.pid)
                session.wait_screen("[Extensions]", timeout=60)
                shown(["Manager connected: " + endpoint], 30, "Pi did not notify the manager connection")
                assert history_of(2)[0] == history, "the run history changed before /wfm-history"
                session.send(b"/wfm-history\r")
                header = "History: 2 managed runs and 0 observer entries"
                rows = []
                for run in history:
                    item, _, _ = observed("/v1/runs/" + run, "Run")
                    rows.append(f"  {run}  {item['workflowId']}  profile {item['profileId']}  succeeded, supervision {item['supervision']}")
                screen = shown([header] + rows + ["result verified"], 45, "/wfm-history did not list the runs of the fixture")
                listed = squeeze(screen)
                after = listed.rindex(squeeze(header))
                positions = [listed.find(squeeze(row), after) for row in rows]
                assert all(position > after for position in positions) and positions == sorted(positions), (
                    "/wfm-history lists the runs in another order than /v1/runs", positions, history)
                pi.save_screen("history")
                print(f"PASS {mode} 4: Pi with credential", tui_fixture.credential_ids["pi"], "ran /wfm-history and showed",
                      repr(header), "with the rows of", ", ".join(history), "in the order of /v1/runs", flush=True)
                record.step_done("4", "pi", history)

                # 5. Pi opens the child request and approves its exact lineage review.
                session.send(("/wfm-review " + child_id + "\r").encode())
                displayed = [name + ": " + str(preparation[name]) for name in selectors]
                shown(["Review of request " + child_id + ", preparation " + preparation["id"], "a approve after confirmation",
                       "Program SHA-256: " + preparation["review"]["programHash"], "Profile: profile_1"] + displayed, 45,
                      "Pi showed no exact review of the child request")
                lineage_rows = ["Lineage: fork of run " + first,
                                "replace occurrence " + occurrence + " with the answer of SHA-256 " + forked_sha256]
                deadline = time.monotonic() + 15
                while not all(any(line.strip() == row for line in session.screen.lines()) for row in lineage_rows):
                    assert time.monotonic() < deadline, ("the child review in Pi shows no lineage rows", session.screen.text())
                    session.send(b"j")
                    session.settle()
                pi.save_screen("review")
                session.send(b"a")
                shown(["Approve this exact review?", preparation["reviewDigest"], "→ Yes"], 15, "a opened no approval confirmation")
                session.send(b"\r")
                associated, _, _ = until(child_uri, "Request", lambda value: value["runId"] is not None)
                child_run = associated["runId"]
                shown(["Execution: the manager started run " + child_run], 45, "Pi did not report the started child run")
                pi.save_screen("approved")
                pi.quit()
            session = None
            consumed, _, _ = observed(preparation_uri, "Preparation")
            assert consumed["state"] == "consumed" and all(consumed[name] == preparation[name] for name in selectors), (
                "the consumed preparation differs from the review that Pi showed", consumed["state"])
            print(f"PASS {mode} 5: Pi ran /wfm-review", child_id, "and showed the exact review of preparation", preparation["id"], "with",
                  ", ".join(selectors), "and the rows", " and ".join(repr(row) for row in lineage_rows) + "; a and Yes approved it,",
                  "child run", child_run, "started, and /quit ended Pi with status 0", flush=True)
            record.step_done("5", "pi", [child_run])

            # 6 and 7. Emacs lists the history and shows the parent and the child.
            environment = {name: os.environ[name] for name in EMACS_ALLOWLIST if name in os.environ}
            command = [sys.executable, "-B", emacs_ui, "--service", str(tui_fixture.client_profiles["emacs"]), str(report_path),
                       "--service-case", "witness-lineage", "--service-handshake", str(handshake), "--emacs", emacs_program,
                       "--source", os.path.join(emacs_directory, "wf.el"), "--artifacts", str(artifacts)]
            script = subprocess.Popen(command, env=environment, stdin=subprocess.DEVNULL)
            try:
                ready = handshake / "lineage-ready.json"
                deadline = time.monotonic() + 240
                while not ready.exists():
                    assert script.poll() is None, ("the Emacs witness ended before the handshake lineage-ready", script.returncode)
                    assert time.monotonic() < deadline, "the Emacs witness did not ask for the handshake lineage-ready"
                    time.sleep(0.05)
                staged = handshake / "lineage-ready.done.new"
                staged.write_text(json.dumps({"parent": first, "child": child_run}))
                staged.rename(handshake / "lineage-ready.done")
                deadline = time.monotonic() + 300
                while script.poll() is None:
                    assert time.monotonic() < deadline, "the Emacs witness did not end in 300 seconds after lineage-ready"
                    time.sleep(0.05)
            finally:
                if script.poll() is None:
                    script.kill()
                script.wait(timeout=25)
            report = json.loads(report_path.read_bytes()) if report_path.exists() else {"steps": [], "version": None}
            assert script.returncode == 0, ("the Emacs witness of " + emacs_ui + " failed", script.returncode, report["steps"])
            assert report["version"] == CROSS_LINEAGE_REPORT_VERSION, (
                f"The {mode} mode requires report version {CROSS_LINEAGE_REPORT_VERSION}, and {emacs_ui} wrote version {report['version']}.")
            assert report["steps"] == ["1", "2", "3", "4", "5"] and report["profile"] == str(tui_fixture.client_profiles["emacs"]), (
                "the steps of the Emacs witness", report["steps"])
            assert report["exitStatus"] == 0 and report["terminalAfter"] == report["terminalBefore"] and report["sent"] == [], (
                "Emacs did not end cleanly without a command", report["exitStatus"], report["sent"])
            pids["emacs"].append(report["emacsPid"])
            history, pages = history_of(3)
            assert report["historyRuns"] == history and report["historyPages"] == pages and child_run in history, (
                "the wf-history rows differ from every page of /v1/runs", report["historyRuns"], history)
            print(f"PASS {mode} 6: Emacs with credential", tui_fixture.credential_ids["emacs"], "listed with M-x wf-history the",
                  len(history), "runs", ", ".join(history), "of the", pages, "pages of /v1/runs in the order of the collection", flush=True)
            record.step_done("6", "emacs", history)
            child_line = "Lineage: fork of run " + first
            assert report["parentLines"][0].startswith("Service run " + first) and "Lineage: root" in report["parentLines"] \
                and "Terminal: succeeded" in report["parentLines"], ("the Emacs view of the parent", report["parentLines"])
            artifact = verified_download(child_run, runs.client, harness)
            downloaded = (work / "verified-result.json").read_bytes()
            assert report["childLines"][0].startswith("Service run " + child_run) and child_line in report["childLines"] \
                and "Terminal: succeeded" in report["childLines"] \
                and "Result SHA-256: " + artifact["sha256"] in report["childLines"], ("the Emacs view of the child", report["childLines"])
            print(f"PASS {mode} 7: RET on the wf-history rows opened the Emacs views of", first, "with 'Lineage: root' and terminal",
                  "success and of", child_run, "with", repr(child_line) + ", terminal success and", repr("Result SHA-256: " + artifact["sha256"]) + ";",
                  "the session sent no command, and C-x C-c ended Emacs with status 0 and the terminal attributes of its start", flush=True)
            record.step_done("7", "emacs", [first, child_run])

            # 8. The child names its parent, its commands name their clients, and its result verifies.
            run_view, _, _ = observed("/v1/runs/" + child_run, "Run")
            child, _, _ = observed(child_uri, "Request")
            assert run_view["parentRunId"] == first and run_view["lineage"] == "fork" and child["parentRunId"] == first \
                and child["lineage"] == "fork" and child["runId"] == child_run and child["phase"] == "associated", (
                "the child does not name its parent and its operation", run_view["parentRunId"], run_view["lineage"], child["phase"])
            child_snapshot, _, _ = observed("/v1/runs/" + child_run + "/snapshot", "RunSnapshot")
            replaced = occurrence_of(child_snapshot, occurrence)
            assert child_snapshot["runtime"]["status"] == "succeeded" and replaced["answer"] == "yes", (
                "the fork child did not succeed with the replacement", child_snapshot["runtime"], replaced.get("answer"))
            rows = read_coordination("SELECT id, operation, client_id, resource_uri, state FROM commands WHERE resource_uri IN (?, ?, ?) "
                                     "ORDER BY rowid", (lineage_uri, child_uri, preparation_uri))
            assert [(row[1], row[2], row[3]) for row in rows] == [("fork", clients["tui"], lineage_uri), ("enqueue", clients["tui"], child_uri),
                                                                  ("approve", clients["pi"], preparation_uri)], (
                "the fork, enqueue and approve commands of the child", rows, clients)
            status, receipt, _ = request("/v1/commands/" + rows[0][0], harness)
            assert status == 200 and receipt["state"] == "effect-observed" and receipt["effect"]["kind"] == "lineage-created" \
                and receipt["effect"]["resource"] == child_uri, ("the fork command", status, receipt.get("state"), receipt.get("effect"))
            page, _, _ = observed(lineage_uri, "LineagePage")
            assert [(item["id"], item["lineage"], item["parentRunId"], item["runId"]) for item in page["items"]] == [
                (child_id, "fork", first, child_run)], ("the lineage collection of the first parent", page["items"])
            print(f"PASS {mode} 8: run", child_run, "and request", child_id, "name parent", first, "and the operation fork, the run",
                  "succeeded with the answer yes at occurrence", occurrence + ", the fork", rows[0][0], "and the enqueue", rows[1][0], "name",
                  "client", clients["tui"], "of the tui credential, the approve", rows[2][0], "names client", clients["pi"], "of the pi",
                  "credential,", lineage_uri, "lists the child, and the verified", artifact["bytes"], "bytes of the child downloaded with",
                  "SHA-256", artifact["sha256"], flush=True)
            record.step_done("8", "harness", [child_run])
            record.read_receipts(harness)
    finally:
        if process.poll() is None:
            process.terminate()
        process.wait(timeout=25)
        (work / "server-0.exit").write_text(str(process.returncode) + "\n")

    # 9. The identity record of the witness.
    flow_dir = work / "manager" / "flow"
    logs = sorted(flow_dir.glob("*.ndjson"))
    stores = sorted(work.glob("manager/runs/runs/*/runtime"))
    assert len(logs) == 1 and len(stores) == 3, ("the witness has other than one manager log and three run stores", logs, stores)
    status, records, summary = read_flow("cross-lineage-flow", [flow_dir] + stores)
    assert status == 0 and summary["verified"] and not summary["problems"], ("the flow verb did not verify the witness logs", status, summary["problems"])
    manager = [entry for entry in records if entry["log"] == str(logs[0])]
    expected_actors = {"1": "harness", "2": "tui", "3": "tui", "4": "pi", "5": "pi", "6": "emacs", "7": "emacs", "8": "harness"}
    record_path, lifetime, by_client = record.write("cross-client-lineage-witness.json", mode, endpoint, negotiated, capabilities,
                                                    manager, summary, downloaded, expected_actors)
    print(f"PASS {mode} 9: wrote", record_path, "with", len(record.steps), "steps and", len(record.receipts), "commands in manager lifetime",
          lifetime["processGeneration"], "(" + ", ".join(f"{name}: {len(found)}" for name, found in by_client.items()) + " commands);",
          "each command is in one step with its client and its manager-log position, and the record holds no bearer and no result bytes",
          flush=True)

    # 10. No child remains, and the fixture secrets and homes are removed.
    removed = emacs_service_cleanup(artifacts, [tui_fixture.client_profiles[name] for name in CrossClientFixture.CLIENTS]
                                    + [host.home for host in hosts] + [host.agent for host in hosts] + [host.state for host in hosts])
    print(f"PASS {mode} 10: all clients quit, the manager stopped, no TUI, Emacs, Pi or fixture process remains, and the harness",
          "removed", removed, "credential, client profile and home paths", flush=True)
    elapsed = time.monotonic() - mode_started
    assert elapsed <= WITNESS_SECONDS, ("the witness took longer than its budget", round(elapsed), WITNESS_SECONDS)
    print(f"PASS {mode}: the TUI, Pi and Emacs listed the runs of the fixture in the order of /v1/runs, the TUI forked run", first,
          "with one replacement, Pi approved the exact lineage review of child request", child_id, "and Emacs showed the parent and the",
          "succeeded child run", child_run, "with its lineage line; the client processes were the TUI (pid", ", ".join(map(str, pids["tui"])) + "),",
          "Pi (pid", ", ".join(map(str, pids["pi"])) + ") and Emacs (pid", ", ".join(map(str, pids["emacs"])) + "), over one manager at",
          endpoint, f"that negotiates {negotiated}, in {elapsed:.0f} seconds", flush=True)


def storage_checks():
    """The storage-error endings through four lifetimes of the real HTTPS
    manager. Each numbered case prints one PASS line."""
    import sqlite3
    authorized = {"Authorization": "Bearer " + bearer}
    flow_dir = work / "manager" / "flow"
    capacity = STORAGE_COMMAND_CAPACITY
    reserve = 16 * capacity
    ordinary_ceiling = STORAGE_LEDGER - reserve - capacity
    terminal = ("succeeded", "failed", "cancelled")

    def serve(index):
        """Start one foreground manager lifetime on the same root and wait
        for HTTPS readiness."""
        with (work / f"server-{index}.stdout").open("wb") as output, (work / f"server-{index}.stderr").open("wb") as errors:
            process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config),
                                        "+RTS", "-N" + native, "-RTS"], stdout=output, stderr=errors)
        wait_ready(process)
        return process

    def stop(process, index):
        """End one lifetime as the operator stops it and keep its exit status."""
        if process.poll() is None:
            process.terminate()
        process.wait(timeout=25)
        (work / f"server-{index}.exit").write_text(str(process.returncode) + "\n")

    def database(statement, parameters=()):
        """The rows of one query through a read-only connection to the
        coordination database."""
        found = sorted((work / "manager").rglob("coordination.sqlite3"))
        assert len(found) == 1, ("coordination database", found)
        connection = sqlite3.connect(found[0].as_uri() + "?mode=ro", uri=True)
        try:
            return connection.execute(statement, parameters).fetchall()
        finally:
            connection.close()

    def ledger():
        """The charge of the command ledger, as Commands.checkCapacity reads it."""
        rows = database("SELECT bytes FROM command_ledger_usage WHERE singleton=1")
        assert len(rows) == 1, ("command ledger usage", rows)
        return rows[0][0]

    def commands():
        return database("SELECT count(*) FROM commands")[0][0]

    def setup():
        """The capabilities, the mixed client, the mixed-controls workflow and
        its creation body for the current lifetime."""
        status, capabilities, raw = request("/v1/capabilities", authorized)
        assert status == 200
        validate("Capabilities", capabilities, raw)
        client = mixed_client(capabilities, authorized)
        status, catalogue, _ = request("/v1/workflows?profileId=profile_1", authorized)
        assert status == 200
        workflow = next(item for item in catalogue["items"] if item["name"] == "mixed-controls")
        create = json.dumps({"workflowId": workflow["id"], "descriptorRevision": workflow["revision"],
                             "profileId": workflow["profileId"], "profileRevision": workflow["profileRevision"]},
                            separators=(",", ":")).encode()
        return capabilities, client, workflow, create

    def create_attempt(capabilities, create):
        """One ordinary command, a request creation. Returns the status, the
        decoded body and the idempotency key."""
        key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
        status, value, raw, _ = exchange("/v1/requests", authorized | {"Content-Type": "application/json", "Idempotency-Key": key},
                                         method="POST", payload=create)
        if status == 201:
            validate("Request", value, raw)
        return status, value, key

    def created_request(capabilities, create):
        status, value, _ = create_attempt(capabilities, create)
        assert status == 201, ("request creation", status, value.get("code"))
        return value

    def unknown_key(key):
        return not database("SELECT id FROM commands WHERE idempotency_key=?", (key,))

    def cancel(capabilities, client, run, name):
        """Cancel the running run through its control and wait for the run to
        end. Returns the receipt and the acknowledged command."""
        observed, wait_for, _, _ = client
        base = "/v1/runs/" + run
        control, tag, _ = observed(base + "/control", "RunControl")
        assert control["cancelAllowed"] and control["supervision"] == "owned", ("cancel not allowed", control["cancelAllowed"], control["supervision"])
        key = capabilities["authorityEpoch"] + "." + secrets.token_urlsafe(16)
        status, receipt, raw, _ = exchange(base + "/control", authorized | {"Content-Type": "application/json", "Idempotency-Key": key,
                                           "If-Match": tag}, method="POST", payload=b'{"operation":"cancel"}')
        assert status == 202, (name + " cancel", status, receipt.get("code"))
        validate("CommandReceipt", receipt, raw)
        command, _, raw = wait_for(receipt["links"]["self"], "CommandReceipt",
            lambda value: value["acknowledgement"] is not None or value["state"] in ("refused", "unresolved"))
        (work / (name + "-cancel-command.json")).write_bytes(raw)
        assert command["state"] in ("acknowledged", "effect-observed"), (name + " cancel state", command["state"])
        snapshot, _, raw = wait_for(base + "/snapshot", "RunSnapshot",
            lambda value: value["runtime"] is not None and value["runtime"]["status"] in terminal)
        (work / (name + "-cancel-terminal.json")).write_bytes(raw)
        assert snapshot["runtime"]["status"] == "cancelled", (name + " run terminal status", snapshot["runtime"]["status"])
        return receipt, command

    def refused_download(artifact, name):
        """Request the content of the artifact and require a refusal. Returns
        the status and the frozen problem code."""
        connection = http.client.HTTPSConnection("127.0.0.1", port, context=context, timeout=7)
        try:
            connection.request("GET", artifact["download"], headers=authorized | {"Accept": "application/octet-stream"})
            response = connection.getresponse()
            body = response.read(1048577)
            status = response.status
            media = response.getheader("Content-Type")
        finally:
            connection.close()
        (work / (name + "-download.body")).write_bytes(body)
        assert status != 200 and media != "application/octet-stream", (name + " download served bytes", status, media, len(body))
        value = frozen.parse_json(body)
        validate("Problem", value, body)
        return status, value["code"]

    def result_ending(client, run, name):
        """The result item of the run from a fresh outputs read, and then the run."""
        observed = client[0]
        base = "/v1/runs/" + run
        outputs, _, raw = observed(base + "/outputs", "OutputPage")
        (work / (name + "-outputs.json")).write_bytes(raw)
        result = next(item for item in outputs["items"] if item["kind"] == "result")
        value, _, raw = observed(base, "Run")
        (work / (name + "-run.json")).write_bytes(raw)
        return value, result

    # Case 1. At the command-ledger ceiling, an ordinary command is refused
    # with storage-quota while a run waits at its person question.
    first = serve(0)
    try:
        capabilities, client, workflow, create = setup()
        observed, wait_for, _, _ = client
        assert ledger() == 0, ("the command ledger is not empty before the first command", ledger())
        _, ceiling_run = approve_mixed(created_request(capabilities, create), workflow, client)
        head, _, _ = drive_mixed(ceiling_run, client, stop_at_question=True, overview=False)
        run_charge = ledger()
        assert run_charge == 4 * capacity, ("the commands of one run", run_charge)
        accepted = []
        for _ in range(8):
            used = ledger()
            status, value, key = create_attempt(capabilities, create)
            if used <= ordinary_ceiling:
                assert status == 201, ("ordinary command below the ledger ceiling", used, status, value.get("code"))
                accepted.append(value["id"])
                continue
            assert status == 429 and value["code"] == "storage-quota", ("ordinary command at the ledger ceiling", used, status, value.get("code"))
            assert unknown_key(key), "the refused command left a command row"
            break
        else:
            raise AssertionError("no ordinary command reached the command-ledger ceiling")
        print("PASS storage case 1: with globalMutationLedgerBytes", STORAGE_LEDGER, "the four commands of run", ceiling_run,
              "charge", run_charge, "bytes, run", ceiling_run, "waits at question", head, "and the next ordinary command after",
              len(accepted), "more is refused with 429 storage-quota at charge", used, "above", ordinary_ceiling, "with no command row", flush=True)

        # Case 2. A cancel uses the reserve and still ends the run cancelled.
        receipt, command = cancel(capabilities, client, ceiling_run, "ceiling")
        after_cancel = ledger()
        assert after_cancel == run_charge + (len(accepted) + 1) * capacity, ("the charge of the cancel", after_cancel)
        print("PASS storage case 2: cancel", receipt["id"], "was accepted at the ceiling and", command["state"], "and run", ceiling_run,
              "ended cancelled; the command ledger charge is", after_cancel, "of", STORAGE_LEDGER, flush=True)
    finally:
        stop(first, 0)

    # Case 3. After an ordinary restart, ordinary commands are still refused,
    # because the command ledger is not pruned.
    restarted = serve(1)
    try:
        capabilities, client, workflow, create = setup()
        status, value, key = create_attempt(capabilities, create)
        assert status == 429 and value["code"] == "storage-quota", ("ordinary command after the restart", status, value.get("code"))
        assert unknown_key(key), "the refused command left a command row after the restart"
        assert ledger() == after_cancel, ("the command ledger changed across the restart", ledger(), after_cancel)
        snapshot, _, _ = client[0]("/v1/runs/" + ceiling_run + "/snapshot", "RunSnapshot")
        assert snapshot["runtime"]["status"] == "cancelled", ("the cancelled run after the restart", snapshot["runtime"]["status"])
        print("PASS storage case 3: after an ordinary restart an ordinary command is still refused with 429 storage-quota, the command",
              "ledger keeps its charge", after_cancel, "and run", ceiling_run, "stays cancelled", flush=True)
    finally:
        stop(restarted, 1)

    # Case 4. The manager-log positions continue across the restart, and the
    # flow verb reports the floor.
    sealed = sorted((flow_dir / "sealed").glob("*/*.ndjson"))
    expected_floor = int(sealed[0].name[:20]) if sealed else 0
    stores = sorted(work.glob("manager/runs/runs/*/runtime"))
    flow_status, flowed, summary = read_flow("storage-ledger-flow", [flow_dir] + stores, runner)
    manager_summary = next(item for item in summary["logs"] if item["kind"] == "manager")
    lifetimes = summary["joins"]["lifetimes"]
    assert summary["verified"] and not summary["problems"], ("the flow verb does not verify the ledger lifetimes", flow_status, summary["problems"])
    assert manager_summary["floor"] == expected_floor, ("manager log floor", manager_summary["floor"], expected_floor)
    assert len(lifetimes) == 2 and all(item["shutdown"] is not None for item in lifetimes), ("lifetimes", lifetimes)
    assert lifetimes[1]["lifetime"]["position"] == lifetimes[0]["shutdown"] + 1, ("the positions do not continue", lifetimes)
    print("PASS storage case 4: the flow verb exits", flow_status, "and verifies both lifetimes; the second lifetime notice at",
          lifetimes[1]["lifetime"]["position"], "follows the shutdown notice at", lifetimes[0]["shutdown"], "and the floor is",
          manager_summary["floor"], "with", len(sealed), "sealed segments", flush=True)

    # Case 5. The operator raises the ceiling. While a run waits at its
    # question, the active manager log is renamed away, so that every append
    # fails, and an ordinary command is refused with storage-unavailable.
    configuration["limits"]["globalMutationLedgerBytes"] = STORAGE_RAISED_LEDGER
    config.write_text(json.dumps(configuration))
    archive = work / "storage-fault-flow"
    faulted = serve(2)
    try:
        capabilities, client, workflow, create = setup()
        _, fault_run = approve_mixed(created_request(capabilities, create), workflow, client)
        head, _, _ = drive_mixed(fault_run, client, stop_at_question=True, overview=False)
        actives = sorted(flow_dir.glob("*.ndjson"))
        assert len(actives) == 1, ("manager logs before the fault", actives)
        stream = actives[0].name[:-len(".ndjson")]
        archive.mkdir(mode=0o700)
        archived = archive / actives[0].name
        os.rename(actives[0], archived)
        rows = commands()
        status, value, key = create_attempt(capabilities, create)
        assert status == 503 and value["code"] == "storage-unavailable", ("ordinary command with every append failing", status, value.get("code"))
        assert commands() == rows and unknown_key(key), ("the refused command left a command row", rows, commands())
        print("PASS storage case 5: with the active manager log renamed away while run", fault_run, "waits at question", head,
              "an ordinary command is refused with 503 storage-unavailable and the ledger keeps its", rows, "command rows", flush=True)

        # Case 6. A cancel still ends the running run cancelled, and the
        # writer creates no new log at the renamed path.
        receipt, command = cancel(capabilities, client, fault_run, "fault")
        assert commands() == rows + 1, ("the cancel row", rows, commands())
        assert not sorted(flow_dir.glob("*.ndjson")), "the broken writer created a new manager log"
        print("PASS storage case 6: cancel", receipt["id"], "was accepted and", command["state"], "and run", fault_run,
              "ended cancelled while every manager-log append failed; the writer created no new log", flush=True)
    finally:
        stop(faulted, 2)
    assert not sorted(flow_dir.glob("*.ndjson")), "the broken writer created a new manager log at shutdown"

    # Case 7. The archived log ends without the cancel and without the
    # shutdown notice of the faulted lifetime. After the operator moves the
    # rest of the log out, the next lifetime begins a new log at position 0
    # with its lifetime notice and no gap notice.
    for part in ("sealed", "claims"):
        if (flow_dir / part / stream).exists():
            (archive / part).mkdir(mode=0o700)
            os.rename(flow_dir / part / stream, archive / part / stream)
    fault_stores = sorted(work.glob("manager/runs/runs/*/runtime"))
    flow_status, flowed, summary = read_flow("storage-fault-flow", [archived] + fault_stores, runner)
    lifetimes = summary["joins"]["lifetimes"]
    assert summary["verified"] and not summary["problems"], ("the flow verb does not verify the archived log", flow_status, summary["problems"])
    assert len(lifetimes) == 3 and lifetimes[2]["shutdown"] is None, ("archived lifetimes", lifetimes)
    assert summary["states"]["lifetimeWithoutShutdown"] == [lifetimes[2]["lifetime"]], ("archived lost lifetimes", summary["states"]["lifetimeWithoutShutdown"])
    assert not [record for record in flowed if record["schema"] == "command" and record["body"].get("operation") == "cancel"
                and record["position"] > lifetimes[2]["lifetime"]["position"]], "the archived log holds the cancel of the faulted lifetime"
    assert not [record for record in flowed if record["schema"] == "notice" and record["body"].get("notice") == "gap"], "the archived log holds a gap notice"
    recovered = serve(3)
    try:
        actives = sorted(flow_dir.glob("*.ndjson"))
        assert actives == [flow_dir / (stream + ".ndjson")], ("manager logs after the recovery", actives)
        opening = [json.loads(line) for line in actives[0].read_bytes().splitlines()]
        assert opening and opening[0]["schema"] == "notice" and opening[0]["body"]["inline"]["notice"] == "lifetime", ("first record of the new log", opening[:1])
        assert not [record for record in opening if record["schema"] == "notice" and record["body"]["inline"]["notice"] == "gap"], "the new log holds a gap notice"
        print("PASS storage case 7: the flow verb verifies the archived log with", len(lifetimes), "lifetimes, the last without its shutdown notice, and no cancel",
              "command and no gap notice of the faulted lifetime; the new log begins with lifetime notice",
              opening[0]["body"]["inline"]["processGeneration"], "and reconciliation counts", opening[0]["body"]["inline"]["reconciliation"],
              "and holds no gap notice", flush=True)

        # Case 8. A removed result keeps the run succeeded, and the result
        # and its download become unavailable.
        capabilities, client, workflow, create = setup()
        observed = client[0]
        result_stores = []
        for name, damage in (("removed", "missing"), ("corrupted", "corrupt")):
            before = set(work.glob("manager/runs/runs/*/runtime"))
            _, run = approve_mixed(created_request(capabilities, create), workflow, client)
            _, answered, retried = drive_mixed(run, client, overview=False)
            assert answered and retried, ("result run decisions", answered, retried)
            artifact = verified_download(run, client, authorized)
            store = sorted(set(work.glob("manager/runs/runs/*/runtime")) - before)
            assert len(store) == 1, ("run store of the result run", store)
            result_stores += store
            result_file = store[0] / "result.json"
            original = result_file.read_bytes()
            assert len(original) == int(artifact["bytes"]), ("result file length", len(original), artifact["bytes"])
            if damage == "missing":
                result_file.unlink()
            else:
                # One changed byte keeps the length and breaks the digest.
                mode = stat.S_IMODE(result_file.stat().st_mode)
                result_file.chmod(mode | stat.S_IWUSR)
                middle = len(original) // 2
                result_file.write_bytes(original[:middle] + bytes([original[middle] ^ 0x01]) + original[middle + 1:])
                result_file.chmod(mode)
            status, code = refused_download(artifact, name)
            assert (status, code) == (404, "unavailable-resource"), (name + " download", status, code)
            value, _, _ = observed("/v1/runs/" + run, "Run")
            assert value["runtime"]["status"] == "succeeded" and value["verification"]["state"] == "verified", (
                name + " run after the refused download", value["runtime"], value["verification"])
            value, result = result_ending(client, run, name)
            assert value["runtime"]["status"] == "succeeded", (name + " run runtime", value["runtime"])
            assert result["verification"] == {"state": "unavailable", "artifactId": artifact["id"], "reason": damage} and result["artifact"] is None, (
                name + " result item", result)
            assert value["verification"]["state"] == "unavailable", (name + " run verification", value["verification"])
            status, code = refused_download(artifact, name + "-again")
            assert (status, code) == (404, "unavailable-resource"), (name + " second download", status, code)
            print(f"PASS storage case {8 if damage == 'missing' else 9}: the", name, "result of run", run, "keeps runtime succeeded",
                  "with verification unavailable and reason", damage, "and GET", artifact["download"], "refuses with", status, code,
                  "and serves no bytes", flush=True)
    finally:
        stop(recovered, 3)

    # Case 10. The flow verb reads the new log from position 0 with one
    # lifetime and its shutdown notice.
    flow_status, flowed, summary = read_flow("storage-new-flow", [flow_dir] + result_stores, runner)
    lifetimes = summary["joins"]["lifetimes"]
    assert flow_status == 0 and summary["verified"] and not summary["problems"], ("the flow verb does not verify the new log", flow_status, summary["problems"])
    assert flowed and flowed[0]["position"] == 0 and flowed[0]["schema"] == "notice" and flowed[0]["body"].get("notice") == "lifetime", (
        "the new log does not begin with its lifetime notice at 0", flowed[:1])
    assert len(lifetimes) == 1 and lifetimes[0]["shutdown"] is not None, ("new log lifetimes", lifetimes)
    assert not [record for record in flowed if record["schema"] == "notice" and record["body"].get("notice") == "gap"], "the new log holds a gap notice"
    print("PASS storage case 10: the flow verb exits", flow_status, "and reads the new log from position 0 with one lifetime and its",
          "shutdown notice at", lifetimes[0]["shutdown"], "and no gap notice", flush=True)
    print("PASS storage: every storage-error ending held across four lifetimes of the TLS 1.3 manager", flush=True)


def capacity_admission_checks():
    """The workloads of the sections "Execution reservations at one",
    "Execution reservations at sixteen", "Queue at one hundred" and "Safety
    path" of manager/CAPACITY.md, in three lifetimes of the real HTTPS
    manager. Each numbered step prints one PASS line. The mode writes
    CAPACITY_RECORD with a measured value for each ceiling key of these
    sections, and it writes the record again after each workload, so that a
    later failure keeps the earlier values."""
    sys.path.insert(0, str(source / "manager/test"))
    import capacity_summary
    fixture = tui_fixture
    terminal = ("succeeded", "failed", "cancelled")
    reviewing = ("review", "start-pending", "associated")
    ceilings = capacity_summary.load_ceilings(str(source / "manager/test/capacity-ceilings.json"))
    part = sorted(key for key in ceilings if key.split(".")[0] in ("reservations", "queue", "safety"))
    measured, latencies, state = {}, {}, {}

    def save():
        (work / CAPACITY_RECORD).write_text(json.dumps(measured, indent=1, sort_keys=True) + "\n")

    def percentile(samples, fraction):
        """The nearest-rank percentile: the sample at position ceil(q n) of
        the sorted samples, counted from 1."""
        ordered = sorted(samples)
        assert ordered, "no latency samples"
        return round(ordered[max(1, math.ceil(fraction * len(ordered))) - 1], 1)

    def latency_keys(prefix, label):
        """The p50 and p95 keys of the latency samples of label."""
        measured[f"{prefix}.{label}-p50-ms"] = percentile(latencies[prefix + "." + label], 0.50)
        measured[f"{prefix}.{label}-p95-ms"] = percentile(latencies[prefix + "." + label], 0.95)

    def sample(label, value):
        latencies.setdefault(label, []).append(value)

    class Credential:
        """One issued credential with its persistent connection and the
        count of its ordinary mutations in each UTC minute. read_ms holds
        the milliseconds of its last read, from before its first attempt to
        the end of the body of its answer."""

        def __init__(self, name):
            self.name = name
            self.headers = {"Authorization": "Bearer " + (work / ("credential-" + name)).read_bytes().decode("ascii")}
            self.connection = PersistentConnection()
            self.minutes = {}
            self.read_ms = None

    class TaskInfo(ctypes.Structure):
        """struct proc_taskinfo of <sys/proc_info.h>, the PROC_PIDTASKINFO
        flavor of proc_pidinfo."""
        _fields_ = [("virtual_size", ctypes.c_uint64), ("resident_size", ctypes.c_uint64),
                    ("times", ctypes.c_uint64 * 4), ("counts", ctypes.c_int32 * 12)]

    proc_pidinfo = ctypes.CDLL(None).proc_pidinfo

    class Resident(threading.Thread):
        """The resident memory of the manager process every 250
        milliseconds, in bytes, from the start of the lifetime until stop().
        Each sample is the resident size of proc_pidinfo with
        PROC_PIDTASKINFO, which needs no entitlement for a process of the
        same user. A ps without the task-port entitlement refuses its rss
        keyword. The sampler stops before the manager is stopped, so every
        attempt is of a live manager, and peak() refuses a peak when more
        than one attempt in a hundred failed."""

        def __init__(self, pid):
            super().__init__(daemon=True)
            self.pid, self.samples, self.failed, self.stopped = pid, [], 0, threading.Event()
            self.start()

        def run(self):
            while not self.stopped.is_set():
                info = TaskInfo()
                if proc_pidinfo(self.pid, 4, ctypes.c_uint64(0), ctypes.byref(info), ctypes.sizeof(info)) == ctypes.sizeof(info):
                    self.samples.append(info.resident_size)
                else:
                    self.failed += 1
                self.stopped.wait(0.25)

        def peak(self):
            assert self.samples, "no resident memory sample of the manager"
            assert self.failed * 100 <= len(self.samples) + self.failed, (
                "resident memory samples failed", self.failed, len(self.samples))
            return max(self.samples)

        def stop(self):
            self.stopped.set()
            self.join(timeout=15)

    def begin(name, root, profiles, limits, names):
        """Start one lifetime with its configuration and issue its
        credentials. Returns the process, its resident sampler and the
        credentials by name."""
        fixture.begin(root, profiles, limits)
        with (work / f"server-{name}.stdout").open("wb") as output, (work / f"server-{name}.stderr").open("wb") as errors:
            process = subprocess.Popen([str(runner), "--manager", "serve", "--config", str(config), "+RTS", "-N" + native, "-RTS"],
                                       stdout=output, stderr=errors)
        resident = Resident(process.pid)
        wait_ready(process)
        fixture.issue_all(names)
        credentials = {credential: Credential(credential) for credential in names}
        capabilities, _, _ = read(credentials[names[0]], "/v1/capabilities", "Capabilities")
        configured = configuration["limits"]
        assert all(capabilities["limits"][key] == configured[key] for key in configured), (
            "the capabilities do not report the configured limits", name, capabilities["limits"])
        assert capabilities["limits"]["queuedRequests"] == 100 and capabilities["limits"]["ordinaryMutationsPerMinute"] == 30, (
            "the capabilities do not advertise the queue and the rate", capabilities["limits"])
        state.update(epoch=capabilities["authorityEpoch"], workflows={})
        return process, resident, credentials

    def end(name, process, resident, credentials):
        """End one lifetime as the operator stops it and keep its exit status."""
        for credential in credentials.values():
            credential.connection.close()
        resident.stop()
        if process.poll() is None:
            process.terminate()
        process.wait(timeout=25)
        (work / f"server-{name}.exit").write_text(str(process.returncode) + "\n")

    def read(credential, path, schema):
        """One schema-valid read on the connection of the credential. A
        read that meets the five-second Store allowance or the page-set
        capacity is a new bounded read, as in fetch. credential.read_ms
        times the read from before its first attempt."""
        started = time.monotonic()
        deadline = started + 5
        while True:
            status, value, raw, received = exchange(path, credential.headers, persistent=credential.connection)
            if status == 200:
                break
            assert time.monotonic() < deadline and (status == 503 or (status == 429 and value["code"] == "storage-quota")), (
                "capacity read", path, status, value.get("code"))
            time.sleep(0.05)
        credential.read_ms = (time.monotonic() - started) * 1000
        validate(schema, value, raw)
        return value, received.get("etag"), raw

    def post(credential, path, body, tag, ordinary=True):
        """One command on the connection of the credential. Returns the
        status, the decoded body and the latency in milliseconds. An
        ordinary command counts in the UTC minute of its send."""
        key = state["epoch"] + "." + secrets.token_urlsafe(16)
        payload = json.dumps(body, ensure_ascii=False, separators=(",", ":")).encode()
        headers = credential.headers | {"Content-Type": "application/json", "Idempotency-Key": key} | ({"If-Match": tag} if tag else {})
        if ordinary:
            minute = int(time.time() // 60)
            credential.minutes[minute] = credential.minutes.get(minute, 0) + 1
        status, value, raw, _ = exchange(path, headers, method="POST", payload=payload, persistent=credential.connection)
        if status in (201, 202):
            validate("Request" if status == 201 else "CommandReceipt", value, raw)
        return status, value, credential.connection.elapsed

    def effected(credential, receipt, what):
        """Wait until the command of the receipt has its effect."""
        deadline = time.monotonic() + 30
        while True:
            value, _, _ = read(credential, receipt["links"]["self"], "CommandReceipt")
            if value["state"] in ("effect-observed", "refused", "unresolved"):
                break
            assert time.monotonic() < deadline, ("command effect deadline", what)
            time.sleep(0.02)
        assert value["state"] == "effect-observed", ("command not effected", what, value["state"])

    def workflow(credential, profile):
        if profile not in state["workflows"]:
            catalogue, _, _ = read(credential, "/v1/workflows?profileId=" + profile, "WorkflowPage")
            state["workflows"][profile] = next(item for item in catalogue["items"] if item["name"] == "delayed-person")
        return state["workflows"][profile]

    def create(credential, profile):
        """Create one delayed-person draft. Returns the status, the body and
        the latency."""
        item = workflow(credential, profile)
        return post(credential, "/v1/requests", {"workflowId": item["id"], "descriptorRevision": item["revision"],
                                                 "profileId": item["profileId"], "profileRevision": item["profileRevision"]}, None)

    def submit(credential, profile):
        """Create one delayed-person request, supply the literal of each
        input and send its enqueue. Returns the created request, the status
        and body of the enqueue and its latency. An accepted enqueue has
        its effect before the return."""
        status, created, _ = create(credential, profile)
        assert status == 201, ("request creation", credential.name, status, created.get("code"))
        uri = created["links"]["self"]
        for declaration in workflow(credential, profile)["inputs"]:
            _, tag, _ = read(credential, uri, "Request")
            status, receipt, _ = post(credential, uri, {"operation": "set-input", "input": {
                "name": declaration["name"], "source": "literal", "value": CAPACITY_LITERAL}}, tag)
            assert status == 202, ("set-input", credential.name, status, receipt.get("code"))
            effected(credential, receipt, "set-input")
        current, tag, _ = read(credential, uri, "Request")
        assert not current["readiness"]["missing"] and not current["readiness"]["errors"], ("request readiness", current["readiness"])
        status, receipt, elapsed = post(credential, uri, {"operation": "enqueue"}, tag)
        if status == 202:
            effected(credential, receipt, "enqueue")
        return created, status, receipt, elapsed

    def approve(credential, preparation_id, request_id):
        """Approve the exact live review of the request. Returns the latency."""
        preparation, tag, _ = read(credential, "/v1/preparations/" + preparation_id, "Preparation")
        assert preparation["requestId"] == request_id and preparation["state"] == "live", ("review", request_id, preparation["state"])
        selectors = ("reviewDigest", "requestRevision", "profileRevision", "descriptorRevision", "processGeneration")
        status, receipt, elapsed = post(credential, "/v1/preparations/" + preparation_id,
                                        {"operation": "approve", **{key: preparation[key] for key in selectors}}, tag)
        assert status == 202, ("approval", request_id, status, receipt.get("code"))
        return elapsed

    def answer(credential, decision_id):
        """Answer the pending person question with true. Returns the latency."""
        decision, tag, _ = read(credential, "/v1/decisions/" + decision_id, "Decision")
        assert decision["state"] == "pending" and decision["kind"] == "question" and decision["position"] == 0, (
            "person question", decision_id, decision["state"], decision["kind"])
        status, receipt, elapsed = post(credential, "/v1/decisions/" + decision_id, {
            "operation": "answer", "occurrenceId": decision["address"]["occurrenceId"], "generation": decision["generation"], "value": True}, tag)
        assert status == 202, ("answer", decision_id, status, receipt.get("code"))
        effected(credential, receipt, "answer")
        return elapsed

    def one_page(credential, path, schema):
        value, _, _ = read(credential, path, schema)
        assert value["page"]["next"] is None, ("collection beyond one page", path)
        return value

    def capabilities_probe(credential, label):
        """One GET /v1/capabilities during saturation, with no further
        attempt. It must answer 200 within CAPACITY_PROBE_MS, timed from
        before the request, which includes the opening of a connection, to
        the end of its body."""
        started = time.monotonic()
        status, value, raw, _ = exchange("/v1/capabilities", credential.headers, persistent=credential.connection)
        elapsed = (time.monotonic() - started) * 1000
        assert status == 200, ("GET /v1/capabilities during saturation", label, status, value.get("code"))
        validate("Capabilities", value, raw)
        sample(label, elapsed)
        assert elapsed <= CAPACITY_PROBE_MS, ("GET /v1/capabilities during saturation", label, elapsed)
        return elapsed

    def settle(credential, uri, ready, what):
        """Read the request until ready holds, within 60 seconds."""
        deadline = time.monotonic() + 60
        while True:
            value, tag, _ = read(credential, uri, "Request")
            if ready(value):
                return value, tag
            assert time.monotonic() < deadline, (what, value["phase"], value["admission"]["reasons"])
            time.sleep(0.05)

    def discard(credential, preparation_id):
        """Discard the live review of one preparation and wait for its effect."""
        _, tag, _ = read(credential, "/v1/preparations/" + preparation_id, "Preparation")
        status, receipt, _ = post(credential, "/v1/preparations/" + preparation_id, {"operation": "discard"}, tag)
        assert status == 202, ("discard", preparation_id, status, receipt.get("code"))
        effected(credential, receipt, "discard")

    def cohort_checks(credential):
        """Step 3, in its own lifetime with sixteen reservations. For
        each pair of CAPACITY_COHORTS, the request of the first profile
        reaches review, and the request of the second waits queued with
        exactly the reason profile-busy. The manager names capacity first
        when no reservation is free, so the reason also shows a free
        reservation. The discard of the first review then admits
        the second request without a client command that names it. Its
        review is discarded in turn, so that the lifetime ends with no live
        review. Returns the four requests."""
        in_review = lambda value: value["phase"] == "review" and value["preparationId"] is not None
        busy = lambda value: value["phase"] == "queued" and value["admission"]["reasons"] == ["profile-busy"]
        held, waiting = [], []
        for holder, waiter in (("cap_shared_a", "cap_shared_b"), ("cap_plain_a", "cap_plain_b")):
            first, status, receipt, _ = submit(credential, holder)
            assert status == 202, ("cohort enqueue", holder, status, receipt.get("code"))
            held.append(settle(credential, first["links"]["self"], in_review, holder + " did not reach review")[0])
            second, status, receipt, _ = submit(credential, waiter)
            assert status == 202, ("cohort enqueue", waiter, status, receipt.get("code"))
            waiting.append(second)
        for second, waiter in zip(waiting, ("cap_shared_b", "cap_plain_b")):
            settle(credential, second["links"]["self"], busy, waiter + " did not wait with exactly profile-busy")
        for first, second in zip(held, waiting):
            discard(credential, first["preparationId"])
            admitted, _ = settle(credential, second["links"]["self"], in_review, second["profileId"] + " was not admitted after the discard")
            discard(credential, admitted["preparationId"])
        return [first["id"] for first in held] + [second["id"] for second in waiting]

    def reservations_workload(prefix, reservations, root, names):
        """Steps 1 and 2: 20 requests of four credentials with the given
        execution reservations. The loop reads the request, run and decision
        collections, approves each review, answers each person question and
        records the first observation of each review and each terminal run."""
        process, resident, credentials = begin(prefix, root, CAPACITY_PROFILES, {"executionReservations": reservations}, names)
        try:
            harness, clients = credentials[names[0]], [credentials[name] for name in names[1:]]
            order, owner = [], {}
            for index, profile in enumerate(CAPACITY_PROFILES):
                credential = clients[index % len(clients)]
                created, status, receipt, _ = submit(credential, profile)
                assert status == 202, (prefix + " enqueue", index + 1, status, receipt.get("code"))
                order.append(created["id"])
                owner[created["id"]] = credential
            position = {ident: index for index, ident in enumerate(order)}
            waiting = order[reservations:]
            reviewed, terminal_at, run_of, approved, answered = {}, {}, {}, set(), []
            peak, fifo, capacity_reason, saturated_ms, last_answer = 0, True, None, None, 0.0
            deadline = time.monotonic() + 360
            while True:
                requests_page = one_page(harness, "/v1/requests", "RequestPage")
                runs_page = one_page(harness, "/v1/runs", "RunPage")
                decisions_page = one_page(harness, "/v1/decisions", "DecisionPage")
                seen = time.monotonic()
                items = {item["id"]: item for item in requests_page["items"]}
                assert set(order) <= set(items), ("requests missing from the collection", prefix)
                for ident in order:
                    if items[ident]["phase"] in reviewing and ident not in reviewed:
                        reviewed[ident] = seen
                    if items[ident]["runId"] is not None:
                        run_of[ident] = items[ident]["runId"]
                # FIFO eligibility: the requests that have reached review are
                # always a prefix of the queue order.
                fifo = fifo and sorted(position[ident] for ident in reviewed) == list(range(len(reviewed)))
                active = [run for run in runs_page["items"] if run["runtime"] is None or run["runtime"]["status"] not in terminal]
                peak = max(peak, len(active))
                for run in runs_page["items"]:
                    if run["runtime"] is not None and run["runtime"]["status"] in terminal and run["id"] not in terminal_at:
                        assert run["runtime"]["status"] == "succeeded", (prefix + " run status", run["id"], run["runtime"]["status"])
                        terminal_at[run["id"]] = seen
                if len(terminal_at) == len(order):
                    break
                assert time.monotonic() < deadline, (prefix + " workload deadline", len(reviewed), len(terminal_at))
                for ident in order:
                    if items[ident]["phase"] == "review" and items[ident]["preparationId"] is not None and ident not in approved:
                        sample(prefix + ".approve", approve(owner[ident], items[ident]["preparationId"], ident))
                        approved.add(ident)
                questions = {decision["runId"]: decision for decision in decisions_page["items"]
                             if decision["state"] == "pending" and decision["kind"] == "question" and decision["position"] == 0}
                first = [run_of.get(ident) for ident in order[:reservations]]
                if reservations > 1 and capacity_reason is None and all(run in questions for run in first):
                    # The reservations are saturated: every run waits at its
                    # question, and each later request names capacity.
                    peak_at_saturation = sum(1 for run in active if run["id"] in first)
                    reads = [read(harness, "/v1/requests/" + ident, "Request") for ident in waiting]
                    capacity_reason = all(item["phase"] == "queued" and "capacity" in item["admission"]["reasons"] for item, _, _ in reads)
                    (work / f"{prefix}-saturated-requests.json").write_bytes(b"[" + b",".join(raw for _, _, raw in reads) + b"]\n")
                    saturated_ms = capabilities_probe(harness, prefix + ".capabilities-saturated")
                    assert peak_at_saturation == reservations, (prefix + " runs at saturation", peak_at_saturation)
                pending = next((ident for ident in order if ident not in answered), None)
                if (pending is not None and run_of.get(pending) in questions
                        and (reservations == 1 or (capacity_reason is not None and seen - last_answer >= 1.0))):
                    sample(prefix + ".answer", answer(owner[pending], questions[run_of[pending]]["id"]))
                    answered.append(pending)
                    last_answer = time.monotonic()
                time.sleep(0.05)
            assert answered == order and approved == set(order), (prefix + " answered and approved", len(answered), len(approved))
            # The k-th terminal run released the reservation that the k-th
            # waiting request took, and no client command named that request
            # between its enqueue and its review.
            terminals = sorted(terminal_at.values())
            releases = [(reviewed[ident] - terminals[index]) * 1000 for index, ident in enumerate(waiting)]
            assert all(value >= 0 for value in releases), (prefix + " a waiting request reached review before a release", releases)
            latencies[prefix + ".release-to-review"] = releases
        finally:
            end(prefix, process, resident, credentials)
        measured[prefix + ".peak-concurrent-runs"] = peak
        measured[prefix + ".fifo-order"] = fifo and len(reviewed) == len(order)
        for label in ("approve", "answer", "release-to-review"):
            latency_keys(prefix, label)
        measured[prefix + ".manager-rss-peak-bytes"] = resident.peak()
        if reservations > 1:
            measured[prefix + ".queued-capacity-reason"] = bool(capacity_reason)
        save()
        assert measured[prefix + ".fifo-order"], (prefix + " requests reached review out of queue order", sorted(reviewed, key=reviewed.get))
        assert reservations == 1 or capacity_reason, (prefix + " a waiting request did not name capacity")
        assert peak == reservations, (prefix + " peak concurrent runs", peak, reservations)
        return len(order), peak, releases, saturated_ms, resident.peak()

    # Step 1. One execution reservation.
    count, peak, releases, _, rss = reservations_workload("reservations.r1", 1, work / "manager",
                                                          ["harness", "r1-1", "r1-2", "r1-3", "r1-4"])
    print("PASS capacity-admission step 1: with executionReservations 1 four credentials ran", count, "delayed-person requests with at most",
          peak, "active run; the requests reached review in queue order, and each of the", len(releases), "releases through cleanup",
          "admitted the next queued request without a client command, after", f"{min(releases):.0f} to {max(releases):.0f} ms;",
          "resident peak", rss, "bytes", flush=True)

    # Step 2. Sixteen execution reservations.
    count, peak, releases, saturated_ms, rss = reservations_workload(
        "reservations.r16", 16, work / "capacity-r16", ["r16-harness", "r16-1", "r16-2", "r16-3", "r16-4"])
    print("PASS capacity-admission step 2: with executionReservations 16,", peak, "runs waited at their questions at once while requests",
          "17 to 20 waited queued with the reason capacity and GET /v1/capabilities answered in", f"{saturated_ms:.0f} ms;",
          "answered one each second, the releases admitted requests 17 to 20 in queue order through cleanup alone after",
          f"{min(releases):.0f} to {max(releases):.0f} ms; resident peak", rss, "bytes", flush=True)

    # Step 3. The shared-key and unclassified cohorts.
    process, resident, credentials = begin("cohorts", work / "capacity-cohorts", list(CAPACITY_COHORTS),
                                           {"executionReservations": 16}, ["cohort-harness"])
    try:
        cohort = cohort_checks(credentials["cohort-harness"])
    finally:
        end("cohorts", process, resident, credentials)
    print("PASS capacity-admission step 3: request", cohort[2], "of cap_shared_b waited with exactly profile-busy behind the review",
          "of request", cohort[0], "of cap_shared_a, which shares its key cap_key_shared, and request", cohort[3],
          "of cap_plain_b waited with exactly profile-busy behind the review of request", cohort[1], "of cap_plain_a in the",
          "unclassified resource;",
          "the discard of each holding review admitted the waiting request without a client command", flush=True)

    # Step 4. The queue at one hundred.
    queue_names = ["queue-harness", "safety"] + ["queue-%02d" % index for index in range(1, 13)]
    process, resident, credentials = begin("queue", work / "capacity-queue", ["cap_01"], {"globalMutationLedgerBytes": 67108864}, queue_names)
    try:
        harness, safety = credentials["queue-harness"], credentials["safety"]
        queuers = [credentials[name] for name in queue_names[2:]]
        first, status, receipt, _ = submit(queuers[0], "cap_01")
        assert status == 202, ("first enqueue", status, receipt.get("code"))
        deadline = time.monotonic() + 60
        while True:
            current, _, _ = read(harness, first["links"]["self"], "Request")
            if current["phase"] == "review" and current["preparationId"] is not None:
                break
            assert time.monotonic() < deadline, ("the first request did not reach review", current["phase"])
            time.sleep(0.05)
        approve(queuers[0], current["preparationId"], first["id"])
        while True:
            current, _, _ = read(harness, first["links"]["self"], "Request")
            run = current["runId"]
            control = read(harness, "/v1/runs/" + run + "/control", "RunControl")[0] if run else None
            if control is not None and control["decisionHeadId"] is not None:
                head = read(harness, "/v1/decisions/" + control["decisionHeadId"], "Decision")[0]
                assert head["kind"] == "question", ("the first run head", head["kind"])
                break
            assert time.monotonic() < deadline, "the first run did not reach its person question"
            time.sleep(0.05)
        # Twelve credentials queue 101 requests, 25 to 27 ordinary commands
        # each, with the four commands of the first request.
        plan = [7] + [9] * 6 + [8] * 5
        assert sum(plan) == 101
        queued, refusal = 0, None
        for credential, count in zip(queuers, plan):
            for _ in range(count):
                created, status, receipt, elapsed = submit(credential, "cap_01")
                if queued < 100:
                    assert status == 202, ("enqueue below the queue bound", queued, status, receipt.get("code"))
                    sample("queue.enqueue", elapsed)
                    queued += 1
                    if queued % 10 == 0:
                        read(harness, "/v1/requests", "RequestPage")
                        sample("queue.requests-first-page", harness.read_ms)
                else:
                    refusal = (status, receipt.get("code"), elapsed, created["id"])
            credential.connection.close()
        assert refusal is not None
        listing = one_page(harness, "/v1/requests", "RequestPage")
        accepted = sum(1 for item in listing["items"] if item["phase"] == "queued")
        refused_request = next(item for item in listing["items"] if item["id"] == refusal[3])
        saturated_ms = capabilities_probe(harness, "queue.capabilities-saturated")
        rate = max(max(credential.minutes.values()) for credential in queuers)
        measured.update({"queue.accepted-queued": accepted, "queue.refusal-status": refusal[0], "queue.refusal-code": refusal[1],
                         "queue.refusal-ms": round(refusal[2], 1), "queue.mutations-per-credential-minute": rate,
                         "queue.manager-rss-peak-bytes": resident.peak()})
        latency_keys("queue", "enqueue")
        latency_keys("queue", "requests-first-page")
        save()
        assert (refusal[0], refusal[1]) == (409, "state-conflict"), ("the 101st enqueue", refusal[:2])
        assert accepted == 100 and refused_request["phase"] == "draft", ("the queue after the refusal", accepted, refused_request["phase"])
        print("PASS capacity-admission step 4: while run", run, "held the reservation at its question, twelve credentials queued", accepted,
              "requests with at most", rate, "ordinary commands of one credential in one UTC minute; the enqueue of the 101st request",
              refusal[3], "was refused with", refusal[0], refusal[1], "in", f"{refusal[2]:.0f} ms", "and it stayed a draft, and",
              "GET /v1/capabilities answered in", f"{saturated_ms:.0f} ms", flush=True)

        # Step 5. The safety path in one UTC minute.
        assert not safety.minutes, "the safety credential sent a command before its minute"
        boundary = (time.time() // 60 + 1) * 60
        time.sleep(boundary - time.time() + 0.2)
        minute = int(time.time() // 60)
        for index in range(31):
            status, value, elapsed = create(safety, "cap_01")
            if index < 30:
                assert status == 201, ("safety create below the rate", index + 1, status, value.get("code"))
        rate_refusal = (status, value.get("code"), elapsed)
        saturated_ms = capabilities_probe(harness, "safety.capabilities-saturated")
        before_cancel = one_page(harness, "/v1/requests", "RequestPage")
        still_queued = sum(1 for item in before_cancel["items"] if item["phase"] == "queued")
        assert still_queued == 100, ("the queue before the cancel", still_queued)
        control, tag, _ = read(safety, "/v1/runs/" + run + "/control", "RunControl")
        assert control["cancelAllowed"], "the first run does not allow cancel"
        status, receipt, cancel_ms = post(safety, "/v1/runs/" + run + "/control", {"operation": "cancel"}, tag, ordinary=False)
        replied = time.monotonic()
        assert int(time.time() // 60) == minute, "the safety path left its UTC minute"
        cancel_accepted = status == 202
        if cancel_accepted:
            deadline = time.monotonic() + 30
            while True:
                snapshot, _, _ = read(harness, "/v1/runs/" + run + "/snapshot", "RunSnapshot")
                if snapshot["runtime"] is not None and snapshot["runtime"]["status"] in terminal:
                    cancelled_ms = (time.monotonic() - replied) * 1000
                    break
                assert time.monotonic() < deadline, "the cancelled run did not end"
                time.sleep(0.05)
        measured.update({"safety.rate-refusal-status": rate_refusal[0], "safety.rate-refusal-code": rate_refusal[1],
                         "safety.rate-refusal-ms": round(rate_refusal[2], 1), "safety.cancel-accepted": cancel_accepted,
                         "safety.cancel-ms": round(cancel_ms, 1)})
        if cancel_accepted:
            measured["safety.cancel-to-cancelled-ms"] = round(cancelled_ms, 1)
        save()
        assert (rate_refusal[0], rate_refusal[1]) == (429, "rate-limit"), ("the 31st create of one minute", rate_refusal[:2])
        assert cancel_accepted, ("the cancel at the rate", status, receipt.get("code"))
        command, _, _ = read(safety, receipt["links"]["self"], "CommandReceipt")
        assert command["state"] in ("acknowledged", "effect-observed"), ("the cancel command", command["state"])
        assert snapshot["runtime"]["status"] == "cancelled", ("the cancelled run status", snapshot["runtime"]["status"])
        print("PASS capacity-admission step 5: in one UTC minute the credential safety created 30 drafts and its 31st create was refused",
              "with", rate_refusal[0], rate_refusal[1], "in", f"{rate_refusal[2]:.0f} ms;", "with", still_queued, "requests queued and GET /v1/capabilities",
              "answering in", f"{saturated_ms:.0f} ms,", "its cancel", receipt["id"], "was accepted in", f"{cancel_ms:.0f} ms",
              "and reached", command["state"] + ",", "and run", run, "ended cancelled", f"{cancelled_ms:.0f} ms", "after the reply", flush=True)
    finally:
        end("queue", process, resident, credentials)
    measured["safety.manager-rss-peak-bytes"] = resident.peak()

    # Step 6. The record holds a measured value for each key of the part.
    # The latencies of GET /v1/capabilities during saturation name no
    # ceiling, and the summary lists them as UNCHECKED.
    for label in ("reservations.r16.capabilities-saturated", "queue.capabilities-saturated", "safety.capabilities-saturated"):
        measured[label + "-ms"] = round(max(latencies[label]), 1)
    save()
    missing = [key for key in part if key not in measured]
    assert not missing, ("the record lacks keys of the part", missing)
    above = [key for key in part if not capacity_summary.holds(ceilings[key], measured[key])]
    elapsed = time.monotonic() - mode_started
    assert elapsed <= CAPACITY_SECONDS, ("the capacity-admission mode took longer than its bound", round(elapsed), CAPACITY_SECONDS)
    print("PASS capacity-admission step 6:", CAPACITY_RECORD, "holds a measured value for each of the", len(part), "ceiling keys of",
          "the reservation, queue and safety workloads;", len(above), "of them above their ceilings", above, flush=True)
    print("PASS capacity-admission: the reservation, queue and safety workloads ran to their bounds in", f"{elapsed:.0f} seconds", flush=True)


if storage_mode:
    storage_checks()
    raise SystemExit(0)


